class MergeScenario(str, Enum):
    """The SVN launch semantics inferred from the *raw* TortoiseSVN inputs."""

    TWO_WAY = "two-way"
    UPDATE_CONFLICT = "update-conflict"
    CROSS_BRANCH_MERGE = "cross-branch-merge"
    UNKNOWN_THREE_WAY = "unknown-three-way"


