def _workbook_ext(path: str | None, default: str = ".xlsx") -> str:
    """Infer workbook extension even for SVN sidecar/temp filenames."""
    base = os.path.basename(str(path or ""))
    ext = os.path.splitext(base)[1].lower()
    if ext in _SUPPORTED_WORKBOOK_EXTS:
        return ext
    m = re.search(r"\.(xlsx|xlsm)", base, flags=re.IGNORECASE)
    if m:
        return "." + m.group(1).lower()
    return default


def _is_macro_enabled_workbook(path: str | None) -> bool:
    return _workbook_ext(path) == ".xlsm"


def _dlog(msg: str):
    if not _DEBUG_ENABLED:
        return
    try:
        ts = datetime.now().strftime("%H:%M:%S.%f")[:-3]
        with open(_DEBUG_LOG_PATH, "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {msg}\n")
    except Exception:
        pass


_WORKBOOK_REPAIR_CACHE: dict[tuple[str, int, int], str] = {}


def _cleanup_repair_cache():
    """Remove all temporary repaired workbook copies on process exit."""
    for path in list(_WORKBOOK_REPAIR_CACHE.values()):
        try:
            if os.path.exists(path):
                os.remove(path)
        except Exception:
            pass
    _WORKBOOK_REPAIR_CACHE.clear()


atexit.register(_cleanup_repair_cache)


def _workbook_sig(path: str) -> tuple[str, int, int]:
    p = os.path.abspath(path)
    try:
        st = os.stat(p)
        return p, int(getattr(st, "st_mtime_ns", 0)), int(st.st_size)
    except Exception:
        return p, 0, 0


def _repair_missing_shared_strings_part(xlsx_path: str) -> str | None:
    """Create a temporary repaired copy when sharedStrings.xml is referenced but missing.

    Some third-party exports leave the sharedStrings part declared in [Content_Types].xml
    but omit xl/sharedStrings.xml entirely. openpyxl raises KeyError on open in that case.
    We inject an empty sharedStrings.xml into a temp copy and retry the load.
    """
    if not xlsx_path or (not os.path.isfile(xlsx_path)):
        return None
    key = _workbook_sig(xlsx_path)
    cached = _WORKBOOK_REPAIR_CACHE.get(key)
    if cached and os.path.isfile(cached):
        return cached
    try:
        with zipfile.ZipFile(xlsx_path, "r") as zf:
            names = zf.namelist()
            if "xl/sharedStrings.xml" in names:
                return xlsx_path
            original_infos = {n: zf.getinfo(n) for n in names}
            all_bytes = {n: zf.read(n) for n in names}
    except Exception as e:
        _dlog(f"repair sharedStrings open failed: path={xlsx_path} err={e}")
        return None

    all_bytes["xl/sharedStrings.xml"] = (
        b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        b'<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="0" uniqueCount="0"/>'
    )

    ct_name = "[Content_Types].xml"
    ct_bytes = all_bytes.get(ct_name)
    if ct_bytes is not None:
        try:
            ct_root = ET.fromstring(ct_bytes)
            if ct_root.tag.startswith("{"):
                ns_uri = ct_root.tag[1:].split("}", 1)[0]
                q = lambda tag: f"{{{ns_uri}}}{tag}"
            else:
                q = lambda tag: tag
            has_override = False
            for node in ct_root.findall(q("Override")):
                if node.get("PartName") == "/xl/sharedStrings.xml":
                    has_override = True
                    break
            if not has_override:
                ET.SubElement(
                    ct_root,
                    q("Override"),
                    {
                        "PartName": "/xl/sharedStrings.xml",
                        "ContentType": "application/vnd.openxmlformats-officedocument.spreadsheetml.sharedStrings+xml",
                    },
                )
                all_bytes[ct_name] = ET.tostring(ct_root, encoding="utf-8", xml_declaration=True)
        except Exception as e:
            _dlog(f"repair sharedStrings content-types failed: path={xlsx_path} err={e}")

    base = os.path.basename(xlsx_path)
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    repaired = os.path.join(tempfile.gettempdir(), f"{APP_NAME}_repair_sst_{os.getpid()}_{ts}_{base}")
    ext = _workbook_ext(xlsx_path)
    if not repaired.lower().endswith(ext):
        repaired += ext
    try:
        with zipfile.ZipFile(repaired, "w") as zf:
            for name, payload in all_bytes.items():
                info = original_infos.get(name)
                comp = info.compress_type if info else zipfile.ZIP_DEFLATED
                zf.writestr(name, payload, compress_type=comp)
        _WORKBOOK_REPAIR_CACHE[key] = repaired
        _dlog(f"repair sharedStrings created: src={xlsx_path} repaired={repaired}")
        return repaired
    except Exception as e:
        _dlog(f"repair sharedStrings write failed: path={xlsx_path} err={e}")
        try:
            if os.path.exists(repaired):
                os.remove(repaired)
        except Exception:
            pass
        return None


def load_workbook(filename, *args, **kwargs):
    if "keep_vba" not in kwargs and _is_macro_enabled_workbook(str(filename)):
        kwargs["keep_vba"] = True
    try:
        return _openpyxl_load_workbook(filename, *args, **kwargs)
    except KeyError as e:
        if "sharedStrings.xml" not in str(e):
            raise
        path = str(filename)
        repaired = _repair_missing_shared_strings_part(path)
        if not repaired:
            raise
        _dlog(f"load_workbook retry with repaired sharedStrings: src={path} repaired={repaired}")
        return _openpyxl_load_workbook(repaired, *args, **kwargs)


def _worksheet_scan_bounds(ws) -> tuple[int, int]:
    """Return safe worksheet dimensions, recovering absent OOXML dimensions.

    Some valid XLSX writers omit ``<dimension>`` from worksheet XML.  Excel
    scans the sheet data when opening those files, but openpyxl's read-only
    mode leaves ``max_row`` and ``max_column`` as ``None``.  Treating that as
    a 1x1 sheet makes every later column look deleted.  Ask openpyxl to scan
    only in that incomplete-metadata case; normal workbooks keep their cheap
    declared dimensions.
    """
    try:
        max_r = getattr(ws, "max_row", None)
        max_c = getattr(ws, "max_column", None)
    except Exception:
        return 1, 1
    if max_r is None or max_c is None:
        try:
            ws.calculate_dimension(force=True)
            max_r = getattr(ws, "max_row", None)
            max_c = getattr(ws, "max_column", None)
            _dlog(
                f"worksheet dimension recovered: sheet={getattr(ws, 'title', '?')} "
                f"rows={max_r} cols={max_c}"
            )
        except Exception as e:
            _dlog(
                f"worksheet dimension recovery failed: sheet={getattr(ws, 'title', '?')} "
                f"err={e}"
            )
    try:
        return max(1, int(max_r or 1)), max(1, int(max_c or 1))
    except (TypeError, ValueError):
        return 1, 1


def _blank_worksheet(title: str = "Sheet"):
    wb = Workbook()
    ws = wb.active
    ws.title = title
    return wb, ws


def _row_sig_list_for_ws(ws, max_row_local: int, max_col: int):
    try:
        all_rows = ws.iter_rows(
            min_row=1,
            max_row=max_row_local,
            min_col=1,
            max_col=max_col,
            values_only=True,
        )
    except Exception:
        return []
    sigs = []
    for row in all_rows:
        sigs.append(_row_signature(row or ()))
    return sigs


def _row_signature(row_values) -> str:
    return "\x1f".join(
        _merge_cmp_value(value).replace("\x1f", "\x1e")
        for value in (row_values or ())
    )


def _row_alignment_cell_token(value, edit_value=None) -> str:
    """Stable row-identity token that does not depend on formula caches.

    ``data_only`` workbooks legitimately expose ``None`` for formulas whose
    cached result was discarded by an external editor (notably openpyxl after
    inserting/deleting columns).  Treating that ``None`` as the row identity
    makes every formula-bearing row appear inserted/deleted.  Formula text is
    the durable identity; cached values remain part of the later cell-diff
    classification, not row alignment.
    """
    literal_formula_text = (
        isinstance(edit_value, str)
        and edit_value.startswith("=")
        and value == edit_value
    )
    if not literal_formula_text:
        special = _special_formula_signature(edit_value)
        if special is not None:
            return "FORMULA:SPECIAL:" + repr(special)
        formula = _norm_formula_text(edit_value)
        if formula:
            return "FORMULA:TEXT:" + formula
    effective = value
    if effective is None and edit_value is not None:
        effective = edit_value
    return _merge_cmp_value(effective)


_BLANK_ROW_ALIGNMENT_SIGNATURE = "\x00SOW_BLANK_ROW\x00"
_UNIQUE_ROW_KEY_SIGNATURE_PREFIX = "\x00SOW_UNIQUE_KEY\x00"
_DUPLICATE_ROW_KEY_SIGNATURE_PREFIX = "\x00SOW_DUPLICATE_KEY\x00"
_UNSTABLE_ROW_KEY_SIGNATURE_PREFIX = "\x00SOW_UNSTABLE_KEY\x00"


def _row_alignment_signature(row_values, row_edit_values, width: int, offsets=None) -> str:
    values = _pad_row_values(row_values, width)
    edits = _pad_row_values(row_edit_values, width) if row_edit_values is not None else (None,) * width
    selected = offsets if offsets is not None else range(width)
    tokens = tuple(
        _row_alignment_cell_token(values[offset], edits[offset])
        for offset in selected
    )
    # A blank row needs a width-independent sentinel so it can later receive
    # a logical-context identity.  Leaving every blank row as the same raw
    # SequenceMatcher token lets an unrelated blank separator steal alignment
    # from identical nonblank records after a row deletion.
    if not tokens or all(token == "BLANK:" for token in tokens):
        return _BLANK_ROW_ALIGNMENT_SIGNATURE
    # repr(tuple(...)) is an unambiguous length-framed serialization for Python
    # strings.  A delimiter replacement would collapse native control
    # characters (for example U+001E versus U+001F) into the same signature.
    return repr(tokens)


def _contextualize_blank_row_signatures(signatures) -> list[str]:
    """Distinguish blank runs by their surrounding logical records.

    Physical row numbers are deliberately excluded: a blank separator that
    moves because of an earlier insertion must still align.  The nearest
    nonblank signatures on both sides identify the logical gap.  Ordinals keep
    multiple blanks within the same gap stable while still allowing a shorter
    run to surface as a structural insertion/deletion.
    """
    contextual = list(signatures or ())
    row_count = len(contextual)
    run_start = 0
    while run_start < row_count:
        if contextual[run_start] != _BLANK_ROW_ALIGNMENT_SIGNATURE:
            run_start += 1
            continue
        run_end = run_start + 1
        while (
            run_end < row_count
            and contextual[run_end] == _BLANK_ROW_ALIGNMENT_SIGNATURE
        ):
            run_end += 1
        previous = contextual[run_start - 1] if run_start > 0 else "\x00BOF\x00"
        following = contextual[run_end] if run_end < row_count else "\x00EOF\x00"
        context_digest = hashlib.sha256(
            (previous + "\x00" + following).encode("utf-8", errors="surrogatepass")
        ).hexdigest()[:24]
        for ordinal, row_offset in enumerate(
            range(run_start, run_end),
            start=1,
        ):
            contextual[row_offset] = (
                f"\x00SOW_BLANK_CONTEXT\x00{context_digest}:{ordinal}"
            )
        run_start = run_end
    return contextual


def _shared_physical_row_horizon(
    ws_left,
    ws_right,
    effective_left: int,
    effective_right: int,
    ws_left_edit=None,
    ws_right_edit=None,
) -> tuple[int, int]:
    """Retain a common styled row domain across pure column edits.

    Column fixture/edit tools often populate a newly inserted column through
    the worksheet's styled ``max_row``.  The opposite side still owns those
    row coordinates even though every value cell is blank.  If both workbooks
    expose the exact same physical row horizon, aligning only their different
    *effective* value bounds incorrectly reports the blank coordinates as
    inserted rows.  Unequal physical horizons remain conservative and keep the
    effective bounds so genuine row inserts are not hidden.
    """
    try:
        left_rows, _left_cols = _worksheet_scan_bounds(ws_left)
        right_rows, _right_cols = _worksheet_scan_bounds(ws_right)
        left_edit_rows = (
            _worksheet_scan_bounds(ws_left_edit)[0]
            if ws_left_edit is not None else 1
        )
        right_edit_rows = (
            _worksheet_scan_bounds(ws_right_edit)[0]
            if ws_right_edit is not None else 1
        )
        physical_left = max(
            left_rows,
            left_edit_rows,
        )
        physical_right = max(
            right_rows,
            right_edit_rows,
        )
    except Exception:
        return max(1, int(effective_left or 1)), max(1, int(effective_right or 1))
    if physical_left == physical_right:
        return physical_left, physical_right
    return max(1, int(effective_left or 1)), max(1, int(effective_right or 1))


def _row_signatures_from_unique_column_anchors(
    left_rows,
    right_rows,
    left_width: int,
    right_width: int,
    left_edit_rows=None,
    right_edit_rows=None,
) -> tuple[list[str], list[str]]:
    """Build row identities resilient to inserted/deleted physical columns.

    Unique non-empty values from the best shared row near the top are
    conservative column anchors.  Scanning a small prefix supports workbooks
    whose real header follows a blank title/comment row.  When one shared
    column also behaves as a high-confidence unique record key, row alignment
    uses that key alone; otherwise all shared anchors remain the fallback.
    """
    left_rows = list(left_rows or ())
    right_rows = list(right_rows or ())
    left_edit_rows = list(left_edit_rows or ())
    right_edit_rows = list(right_edit_rows or ())
    left_width = max(0, int(left_width or 0))
    right_width = max(0, int(right_width or 0))
    if not left_rows or not right_rows or left_width <= 0 or right_width <= 0:
        return (
            [
                _row_alignment_signature(
                    row,
                    left_edit_rows[idx] if idx < len(left_edit_rows) else None,
                    left_width,
                )
                for idx, row in enumerate(left_rows)
            ],
            [
                _row_alignment_signature(
                    row,
                    right_edit_rows[idx] if idx < len(right_edit_rows) else None,
                    right_width,
                )
                for idx, row in enumerate(right_rows)
            ],
        )

    def _unique_positions(row_values, row_edit_values):
        positions = {}
        duplicates = set()
        for offset, value in enumerate(row_values):
            token = _row_alignment_cell_token(value, row_edit_values[offset])
            if token == "BLANK:":
                continue
            if token in positions:
                duplicates.add(token)
            else:
                positions[token] = offset
        for token in duplicates:
            positions.pop(token, None)
        return positions

    anchors = []
    anchor_score = (-1, -1)
    shared_prefix_rows = min(8, len(left_rows), len(right_rows))
    for header_idx in range(shared_prefix_rows):
        left_header = _pad_row_values(left_rows[header_idx], left_width)
        right_header = _pad_row_values(right_rows[header_idx], right_width)
        left_edit_header = (
            _pad_row_values(left_edit_rows[header_idx], left_width)
            if header_idx < len(left_edit_rows) else (None,) * left_width
        )
        right_edit_header = (
            _pad_row_values(right_edit_rows[header_idx], right_width)
            if header_idx < len(right_edit_rows) else (None,) * right_width
        )
        left_positions = _unique_positions(left_header, left_edit_header)
        right_positions = _unique_positions(right_header, right_edit_header)
        candidate_anchors = sorted(
            (
                (left_positions[token], right_offset)
                for token, right_offset in right_positions.items()
                if token in left_positions
            ),
            key=lambda item: item[1],
        )
        candidate_score = (
            len(candidate_anchors),
            len(left_positions) + len(right_positions),
        )
        if candidate_score > anchor_score:
            anchors = candidate_anchors
            anchor_score = candidate_score
    if not anchors:
        return (
            [
                _row_alignment_signature(
                    row,
                    left_edit_rows[idx] if idx < len(left_edit_rows) else None,
                    left_width,
                )
                for idx, row in enumerate(left_rows)
            ],
            [
                _row_alignment_signature(
                    row,
                    right_edit_rows[idx] if idx < len(right_edit_rows) else None,
                    right_width,
                )
                for idx, row in enumerate(right_rows)
            ],
        )

    def _literal_identity_token(row, edit_row, width: int, offsets):
        if isinstance(offsets, int):
            offsets = (offsets,)
        else:
            offsets = tuple(int(offset) for offset in offsets)
        values = _pad_row_values(row, width)
        edits = (
            _pad_row_values(edit_row, width)
            if edit_row is not None else (None,) * width
        )
        tokens = []
        for offset in offsets:
            value = values[offset]
            edit_value = edits[offset]
            if isinstance(edit_value, str) and edit_value.startswith("="):
                return None
            effective = value if value is not None else edit_value
            token = _merge_cmp_value(effective)
            if token == "BLANK:":
                return None
            tokens.append(token)
        return tokens[0] if len(tokens) == 1 else repr(tuple(tokens))

    identity_token_cache = {}

    def _literal_identity_tokens(rows, edit_rows, width: int, offsets):
        offsets = (offsets,) if isinstance(offsets, int) else tuple(offsets)
        cache_key = (id(rows), id(edit_rows), int(width), offsets)
        cached = identity_token_cache.get(cache_key)
        if cached is not None:
            return cached
        if len(offsets) > 1:
            component_columns = [
                _literal_identity_tokens(
                    rows,
                    edit_rows,
                    width,
                    (offset,),
                )
                for offset in offsets
            ]
            tokens = []
            for row_idx in range(len(rows)):
                components = [
                    column[row_idx] for column in component_columns
                ]
                tokens.append(
                    None
                    if any(component is None for component in components)
                    else repr(tuple(components))
                )
        else:
            tokens = [
                _literal_identity_token(
                    row,
                    edit_rows[row_idx] if row_idx < len(edit_rows) else None,
                    width,
                    offsets,
                )
                for row_idx, row in enumerate(rows)
            ]
        identity_token_cache[cache_key] = tokens
        return tokens

    def _unique_literal_counts(rows, edit_rows, width: int, offsets):
        counts: dict[str, int] = {}
        for token in _literal_identity_tokens(
            rows,
            edit_rows,
            width,
            offsets,
        )[1:]:
            if token is not None:
                counts[token] = counts.get(token, 0) + 1
        return counts

    def _identity_candidate(
        left_offsets,
        right_offsets,
        *,
        position_priority: int,
    ):
        left_offsets = tuple(int(offset) for offset in left_offsets)
        right_offsets = tuple(int(offset) for offset in right_offsets)

        def _looks_like_physical_ordinal(rows, edit_rows, width, offsets):
            if len(offsets) != 1:
                return False
            offset = offsets[0]
            samples = []
            text_ordinal_samples = []
            header_values = _pad_row_values(rows[0], width) if rows else ()
            header_edits = (
                _pad_row_values(edit_rows[0], width)
                if edit_rows
                else (None,) * width
            )
            header_value = (
                header_values[offset]
                if offset < len(header_values)
                else None
            )
            if header_value is None and offset < len(header_edits):
                header_value = header_edits[offset]
            header_text = str(header_value or "").strip().casefold()
            text_ordinal_header = any(
                token in header_text
                for token in (
                    "序号",
                    "序列",
                    "行号",
                    "槽位",
                    "位置",
                    "索引",
                    "order",
                    "ordinal",
                    "slot",
                    "index",
                    "position",
                )
            )
            for row_idx in range(1, len(rows)):
                values = _pad_row_values(rows[row_idx], width)
                edits = (
                    _pad_row_values(edit_rows[row_idx], width)
                    if row_idx < len(edit_rows) else (None,) * width
                )
                value = values[offset]
                if value is None:
                    value = edits[offset]
                if isinstance(value, bool):
                    continue
                if text_ordinal_header and isinstance(value, str):
                    text_match = re.fullmatch(
                        r"\s*(.*?)([0-9]+)\s*",
                        value,
                    )
                    if text_match is not None:
                        text_ordinal_samples.append(
                            (
                                row_idx,
                                text_match.group(1).casefold(),
                                int(text_match.group(2)),
                            )
                        )
                try:
                    numeric = float(value)
                except (TypeError, ValueError):
                    continue
                if not numeric.is_integer():
                    continue
                samples.append((row_idx, int(numeric)))
            if len(text_ordinal_samples) >= 4:
                prefixes = [prefix for _row, prefix, _number in text_ordinal_samples]
                dominant_prefix = max(set(prefixes), key=prefixes.count)
                prefix_samples = [
                    (row_idx, number)
                    for row_idx, prefix, number in text_ordinal_samples
                    if prefix == dominant_prefix
                ]
                if len(prefix_samples) / len(text_ordinal_samples) >= 0.90:
                    text_offsets = [
                        number - row_idx
                        for row_idx, number in prefix_samples
                    ]
                    dominant_offset = max(
                        set(text_offsets),
                        key=text_offsets.count,
                    )
                    if (
                        text_offsets.count(dominant_offset)
                        / len(text_offsets)
                    ) >= 0.90:
                        return True
            # Without a semantic header, a sequential numeric column may be
            # the table's real stable ID (many compact data sheets have no
            # header row at all). Do not discard that evidence merely because
            # its values happen to track physical row order.
            if not text_ordinal_header:
                return False
            if len(samples) < 4:
                return False
            offsets_from_physical = [
                numeric - row_idx for row_idx, numeric in samples
            ]
            dominant = max(
                set(offsets_from_physical),
                key=offsets_from_physical.count,
            )
            return (
                offsets_from_physical.count(dominant) / len(samples)
            ) >= 0.90

        # A physical ordinal remains unsuitable when combined with another
        # column: the ordinal would make an otherwise duplicated payload look
        # artificially unique and can still displace the real composite key.
        for left_offset, right_offset in zip(left_offsets, right_offsets):
            if (
                _looks_like_physical_ordinal(
                    left_rows,
                    left_edit_rows,
                    left_width,
                    (left_offset,),
                )
                and _looks_like_physical_ordinal(
                    right_rows,
                    right_edit_rows,
                    right_width,
                    (right_offset,),
                )
            ):
                return None

        left_tokens = _literal_identity_tokens(
            left_rows,
            left_edit_rows,
            left_width,
            left_offsets,
        )
        right_tokens = _literal_identity_tokens(
            right_rows,
            right_edit_rows,
            right_width,
            right_offsets,
        )
        left_counts: dict[str, int] = {}
        right_counts: dict[str, int] = {}
        for token in left_tokens[1:]:
            if token is not None:
                left_counts[token] = left_counts.get(token, 0) + 1
        for token in right_tokens[1:]:
            if token is not None:
                right_counts[token] = right_counts.get(token, 0) + 1
        populated_left = sum(left_counts.values())
        populated_right = sum(right_counts.values())
        smaller_population = min(populated_left, populated_right)
        # One observed record cannot distinguish an identity column from an
        # ordinary payload column. Treat that tiny sample conservatively and
        # fall back to the complete anchored row.
        if smaller_population < 2:
            return None
        unique_left = sum(1 for count in left_counts.values() if count == 1)
        unique_right = sum(1 for count in right_counts.values() if count == 1)
        shared_tokens = {
            token
            for token, count in left_counts.items()
            if count == 1 and right_counts.get(token) == 1
        }
        shared_unique = len(shared_tokens)
        if shared_unique < 1:
            return None
        overlap = shared_unique / smaller_population
        uniqueness_left = unique_left / populated_left if populated_left else 0.0
        uniqueness_right = unique_right / populated_right if populated_right else 0.0
        if (
            overlap < 0.65
            or uniqueness_left < 0.60
            or uniqueness_right < 0.60
        ):
            return None

        right_positions = {
            token: row_idx
            for row_idx, token in enumerate(right_tokens[1:], start=1)
            if token in shared_tokens
        }
        ordered_right_positions = [
            right_positions[token]
            for token in left_tokens[1:]
            if token in shared_tokens
        ]
        lis_tails: list[int] = []
        for row_idx in ordered_right_positions:
            insert_at = bisect.bisect_left(lis_tails, row_idx)
            if insert_at == len(lis_tails):
                lis_tails.append(row_idx)
            else:
                lis_tails[insert_at] = row_idx
        order_stability = (
            len(lis_tails) / shared_unique if shared_unique else 0.0
        )
        if order_stability < 0.80:
            return None
        # Ordering and population coverage are evidence; physical column
        # priority deliberately precedes raw shared-count.  Otherwise a
        # position/order column with one extra shared value can displace the
        # actual leading ID column and hide an insertion+deletion.
        return (
            order_stability,
            -int(position_priority),
            -len(left_offsets),
            overlap,
            shared_unique,
            left_offsets,
            right_offsets,
        )

    # Prefer a single, mutually unique literal key only when it explains most
    # populated records on both sides.  Item-like tables commonly have a stable
    # ID in column A while formula columns legitimately change text after a row
    # insertion/deletion.  Requiring uniqueness and overlap avoids mistaking a
    # descriptive/value column for a row key.
    identity_candidates = []
    # A one-column sheet provides no evidence that its only value is a stable
    # identity rather than editable payload. Similarity alignment is safer
    # there (for example C -> C2 must remain an ordinary cell modification).
    if len(anchors) > 1:
        for left_offset, right_offset in anchors:
            candidate = _identity_candidate(
                (left_offset,),
                (right_offset,),
                position_priority=right_offset,
            )
            if candidate is not None:
                identity_candidates.append(candidate)
    # Configuration tables frequently use two- or three-column composite keys.
    # Search them when no reliable key starts at the leading shared column. A
    # strong leading single ID is the common large-sheet path and avoids the
    # combinatorial scan; a later S001/S002 slot candidate cannot suppress an
    # earlier composite key.
    leading_anchor = min(right for _left, right in anchors)
    has_leading_candidate = any(
        -int(candidate[1]) == leading_anchor
        for candidate in identity_candidates
    )
    if not has_leading_candidate:
        composite_pool = anchors[:16]
        found_leading_composite = False
        for first_idx in range(len(composite_pool)):
            for second_idx in range(first_idx + 1, len(composite_pool)):
                left_first, right_first = composite_pool[first_idx]
                left_second, right_second = composite_pool[second_idx]
                candidate = _identity_candidate(
                    (left_first, left_second),
                    (right_first, right_second),
                    position_priority=min(right_first, right_second),
                )
                if candidate is not None:
                    identity_candidates.append(candidate)
                    if -int(candidate[1]) == leading_anchor:
                        found_leading_composite = True
                        break
            if found_leading_composite:
                break
        has_leading_candidate = any(
            -int(candidate[1]) == leading_anchor
            for candidate in identity_candidates
        )
    if not has_leading_candidate:
        triple_pool = anchors[:10]
        found_leading_composite = False
        for first_idx in range(len(triple_pool)):
            for second_idx in range(first_idx + 1, len(triple_pool)):
                for third_idx in range(second_idx + 1, len(triple_pool)):
                    left_first, right_first = triple_pool[first_idx]
                    left_second, right_second = triple_pool[second_idx]
                    left_third, right_third = triple_pool[third_idx]
                    candidate = _identity_candidate(
                        (left_first, left_second, left_third),
                        (right_first, right_second, right_third),
                        position_priority=min(
                            right_first,
                            right_second,
                            right_third,
                        ),
                    )
                    if candidate is not None:
                        identity_candidates.append(candidate)
                        if -int(candidate[1]) == leading_anchor:
                            found_leading_composite = True
                            break
                if found_leading_composite:
                    break
            if found_leading_composite:
                break
    def _project(rows, edit_rows, width: int, offsets):
        signatures = []
        for idx, row in enumerate(rows):
            signatures.append(_row_alignment_signature(
                row,
                edit_rows[idx] if idx < len(edit_rows) else None,
                width,
                offsets,
            ))
        return signatures

    if identity_candidates:
        (
            _order_stability,
            _position,
            _key_width_priority,
            _overlap,
            _shared,
            left_key_offsets,
            right_key_offsets,
        ) = max(
            identity_candidates
        )
        fallback_left_offsets = [left for left, _right in anchors]
        fallback_right_offsets = [right for _left, right in anchors]
        selected_left_counts = _unique_literal_counts(
            left_rows,
            left_edit_rows,
            left_width,
            left_key_offsets,
        )
        selected_right_counts = _unique_literal_counts(
            right_rows,
            right_edit_rows,
            right_width,
            right_key_offsets,
        )
        duplicate_identity_tokens = {
            token
            for token in set(selected_left_counts) | set(selected_right_counts)
            if (
                selected_left_counts.get(token, 0) > 1
                or selected_right_counts.get(token, 0) > 1
            )
        }

        def _identity_projection(
            rows,
            edit_rows,
            width: int,
            key_offsets,
            fallback_offsets,
        ):
            key_signatures = []
            literal_tokens = []
            fallback_signatures = _project(
                rows,
                edit_rows,
                width,
                fallback_offsets,
            )
            for row_idx, row in enumerate(rows):
                edit_row = (
                    edit_rows[row_idx] if row_idx < len(edit_rows) else None
                )
                key_signatures.append(_row_alignment_signature(
                    row,
                    edit_row,
                    width,
                    key_offsets,
                ))
                literal_tokens.append(_literal_identity_token(
                    row,
                    edit_row,
                    width,
                    key_offsets,
                ))

            projected = []
            for key_signature, literal_token, fallback_signature in zip(
                key_signatures,
                literal_tokens,
                fallback_signatures,
            ):
                if (
                    key_signature == _BLANK_ROW_ALIGNMENT_SIGNATURE
                    and fallback_signature == _BLANK_ROW_ALIGNMENT_SIGNATURE
                ):
                    projected.append(_BLANK_ROW_ALIGNMENT_SIGNATURE)
                elif literal_token is None:
                    # Empty and formula-derived keys are not stable row
                    # identities.  Preserve the other anchored columns so a
                    # meaningful keyless row does not collapse into a blank
                    # separator and a moved formula key cannot claim a row by
                    # its physical-reference text alone.
                    projected.append(
                        _UNSTABLE_ROW_KEY_SIGNATURE_PREFIX + fallback_signature
                    )
                elif literal_token in duplicate_identity_tokens:
                    # A generally unique ID column may still contain a small
                    # repeated group.  Include the full anchored row only for
                    # those duplicates; otherwise SequenceMatcher can retain
                    # the wrong duplicate and structural adoption deletes the
                    # neighboring record.
                    projected.append(
                        _DUPLICATE_ROW_KEY_SIGNATURE_PREFIX
                        + key_signature
                        + "\x00"
                        + fallback_signature
                    )
                else:
                    projected.append(
                        _UNIQUE_ROW_KEY_SIGNATURE_PREFIX + key_signature
                    )
            return projected

        return (
            _identity_projection(
                left_rows,
                left_edit_rows,
                left_width,
                left_key_offsets,
                fallback_left_offsets,
            ),
            _identity_projection(
                right_rows,
                right_edit_rows,
                right_width,
                right_key_offsets,
                fallback_right_offsets,
            ),
        )

    return (
        _project(left_rows, left_edit_rows, left_width, [left for left, _right in anchors]),
        _project(right_rows, right_edit_rows, right_width, [right for _left, right in anchors]),
    )


@dataclass(frozen=True, slots=True)
class ColumnModelCacheKey:
    """Version identity for a cached logical-column model."""

    sheet_name: str
    row_model_version: int
    column_model_version: int
    mine_edit_version: int = 0
    base_edit_version: int = 0
    theirs_edit_version: int = 0

    def __post_init__(self):
        if not isinstance(self.sheet_name, str):
            raise TypeError("sheet_name must be an immutable string")
        for field_name in (
            "row_model_version",
            "column_model_version",
            "mine_edit_version",
            "base_edit_version",
            "theirs_edit_version",
        ):
            value = getattr(self, field_name)
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{field_name} must be an integer")
            if value < 0:
                raise ValueError(f"{field_name} must be non-negative")


COLUMN_MAPPING_CAUSE_BLANK_COLUMN = "blank-column"
COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE = "duplicate-intrinsic-signature"
COLUMN_MAPPING_CAUSE_FORMULA_MISMATCH = "formula-identity-mismatch"
COLUMN_MAPPING_CAUSE_INCOMPATIBLE_CACHE = "incompatible-signature-cache"
COLUMN_MAPPING_CAUSE_IMPLICIT_BOUNDARY = "implicit-column-boundary"
COLUMN_MAPPING_CAUSE_COLUMN_LIMIT = "column-limit-exceeded"
COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE = "low-confidence"
_COLUMN_MAPPING_CAUSE_CODES = frozenset((
    COLUMN_MAPPING_CAUSE_BLANK_COLUMN,
    COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE,
    COLUMN_MAPPING_CAUSE_FORMULA_MISMATCH,
    COLUMN_MAPPING_CAUSE_INCOMPATIBLE_CACHE,
    COLUMN_MAPPING_CAUSE_IMPLICIT_BOUNDARY,
    COLUMN_MAPPING_CAUSE_COLUMN_LIMIT,
    COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE,
))


@dataclass(frozen=True, slots=True)
class ColumnMappingConfidence:
    """Conservative confidence with stable leaf causes for UI diagnostics."""

    score: float = 1.0
    ambiguous: bool = False
    reason: str = ""
    evidence: tuple[str, ...] = ()
    cause_codes: tuple[str, ...] = ()

    def __post_init__(self):
        if isinstance(self.score, bool) or not isinstance(self.score, (int, float)):
            raise TypeError("column confidence score must be numeric")
        if not isinstance(self.ambiguous, bool):
            raise TypeError("column confidence ambiguous flag must be bool")
        if not isinstance(self.reason, str):
            raise TypeError("column confidence reason must be a string")
        cause_codes = tuple(self.cause_codes)
        if any(not isinstance(code, str) for code in cause_codes):
            raise TypeError("column confidence cause codes must be strings")
        unknown_codes = set(cause_codes) - _COLUMN_MAPPING_CAUSE_CODES
        if unknown_codes:
            raise ValueError(
                "unknown column confidence cause code: "
                + ", ".join(sorted(unknown_codes))
            )
        score = float(self.score)
        if not 0.0 <= score <= 1.0:
            raise ValueError("column confidence score must be between 0 and 1")
        object.__setattr__(self, "score", score)
        object.__setattr__(self, "evidence", tuple(str(item) for item in self.evidence))
        object.__setattr__(self, "cause_codes", tuple(dict.fromkeys(cause_codes)))


@dataclass(frozen=True, slots=True)
class ColumnSlot:
    """One immutable logical column with optional physical columns per side.

    ``base_boundary`` is the number of Base columns preceding a 3-way
    insertion; ``origin_side`` identifies whether Mine, Theirs, or both sides
    own the inserted logical column.
    """

    logical_idx: int
    mine_col: int | None = None
    base_col: int | None = None
    theirs_col: int | None = None
    state: str = "retained"
    confidence: ColumnMappingConfidence = ColumnMappingConfidence()
    base_boundary: int | None = None
    origin_side: str | None = None

    def __post_init__(self):
        if isinstance(self.logical_idx, bool) or not isinstance(self.logical_idx, int):
            raise TypeError("logical_idx must be an integer")
        if self.logical_idx < 0:
            raise ValueError("logical_idx must be non-negative")
        if self.mine_col is None and self.base_col is None and self.theirs_col is None:
            raise ValueError("a column slot must own at least one physical column")
        for field_name in ("mine_col", "base_col", "theirs_col"):
            value = getattr(self, field_name)
            if value is None:
                continue
            if isinstance(value, bool) or not isinstance(value, int):
                raise TypeError(f"{field_name} must be an integer")
            if value <= 0:
                raise ValueError(f"{field_name} must be a positive Excel column")
        if not isinstance(self.state, str):
            raise TypeError("column slot state must be a string")
        if not isinstance(self.confidence, ColumnMappingConfidence):
            raise TypeError("column slot confidence must be ColumnMappingConfidence")
        if self.base_boundary is not None:
            if (
                isinstance(self.base_boundary, bool)
                or not isinstance(self.base_boundary, int)
                or self.base_boundary < 0
            ):
                raise TypeError("base_boundary must be a non-negative integer")
            if self.base_col is not None:
                raise ValueError("a Base-relative insertion cannot own a Base column")
        if self.origin_side not in (None, "mine", "theirs", "both"):
            raise ValueError(
                "origin_side must be 'mine', 'theirs', 'both', or None"
            )
        if (self.base_boundary is None) != (self.origin_side is None):
            raise ValueError(
                "base_boundary and origin_side must be set together for insertions"
            )


@dataclass(frozen=True, slots=True)
class ColumnBlock:
    """Immutable consecutive logical-column range and its structural state."""

    ordinal: int
    slot_indices: tuple[int, ...]
    state: str
    confidence: ColumnMappingConfidence = ColumnMappingConfidence()

    def __post_init__(self):
        if isinstance(self.ordinal, bool) or not isinstance(self.ordinal, int):
            raise TypeError("column block ordinal must be an integer")
        indices = tuple(self.slot_indices)
        if any(isinstance(idx, bool) or not isinstance(idx, int) for idx in indices):
            raise TypeError("column block slot indices must be integers")
        if self.ordinal < 0 or not indices:
            raise ValueError("column block requires a non-negative ordinal and slots")
        if any(idx < 0 for idx in indices):
            raise ValueError("column block slot indices must be non-negative")
        if any(right != left + 1 for left, right in zip(indices, indices[1:])):
            raise ValueError("column block slot indices must be consecutive")
        if not isinstance(self.state, str):
            raise TypeError("column block state must be a string")
        if not isinstance(self.confidence, ColumnMappingConfidence):
            raise TypeError("column block confidence must be ColumnMappingConfidence")
        object.__setattr__(self, "slot_indices", indices)

    @property
    def start_slot_idx(self) -> int:
        return self.slot_indices[0]

    @property
    def end_slot_idx(self) -> int:
        return self.slot_indices[-1]


@dataclass(frozen=True, slots=True)
class FrozenIntLookup:
    """Small immutable integer lookup used by cached column models."""

    entries: tuple[tuple[int, int], ...] = ()
    _keys: tuple[int, ...] = field(init=False, repr=False, compare=False, default=())

    def __post_init__(self):
        normalized_items = []
        for key, value in self.entries:
            if (
                isinstance(key, bool) or not isinstance(key, int)
                or isinstance(value, bool) or not isinstance(value, int)
            ):
                raise TypeError("immutable column lookup keys and values must be integers")
            normalized_items.append((key, value))
        normalized = tuple(sorted(normalized_items))
        keys = tuple(key for key, _value in normalized)
        if len(keys) != len(set(keys)):
            raise ValueError("duplicate key in immutable column lookup")
        object.__setattr__(self, "entries", normalized)
        object.__setattr__(self, "_keys", keys)

    def get(self, key: int, default=None):
        key = int(key)
        idx = bisect.bisect_left(self._keys, key)
        if idx < len(self.entries) and self.entries[idx][0] == key:
            return self.entries[idx][1]
        return default

    def __getitem__(self, key: int) -> int:
        marker = object()
        value = self.get(key, marker)
        if value is marker:
            raise KeyError(key)
        return value

    def __len__(self) -> int:
        return len(self.entries)


@dataclass(frozen=True, slots=True)
class ColumnModel:
    """Immutable logical slots plus both physical/logical lookup directions."""

    cache_key: ColumnModelCacheKey
    slots: tuple[ColumnSlot, ...]
    blocks: tuple[ColumnBlock, ...]
    mine_physical_to_logical: FrozenIntLookup
    base_physical_to_logical: FrozenIntLookup
    theirs_physical_to_logical: FrozenIntLookup
    mine_logical_to_physical: FrozenIntLookup
    base_logical_to_physical: FrozenIntLookup
    theirs_logical_to_physical: FrozenIntLookup
    confidence: ColumnMappingConfidence = ColumnMappingConfidence()

    def __post_init__(self):
        if not isinstance(self.cache_key, ColumnModelCacheKey):
            raise TypeError("column model cache_key must be ColumnModelCacheKey")
        for field_name in (
            "mine_physical_to_logical",
            "base_physical_to_logical",
            "theirs_physical_to_logical",
            "mine_logical_to_physical",
            "base_logical_to_physical",
            "theirs_logical_to_physical",
        ):
            if not isinstance(getattr(self, field_name), FrozenIntLookup):
                raise TypeError(f"{field_name} must be FrozenIntLookup")
        if not isinstance(self.confidence, ColumnMappingConfidence):
            raise TypeError("column model confidence must be ColumnMappingConfidence")
        slots = tuple(self.slots)
        blocks = tuple(self.blocks)
        if any(not isinstance(slot, ColumnSlot) for slot in slots):
            raise TypeError("column model slots must be immutable ColumnSlot records")
        if any(not isinstance(block, ColumnBlock) for block in blocks):
            raise TypeError("column model blocks must be immutable ColumnBlock records")
        logical_indices = {slot.logical_idx for slot in slots}
        if len(logical_indices) != len(slots):
            raise ValueError("logical column indices must be unique")
        for block in blocks:
            if any(idx not in logical_indices for idx in block.slot_indices):
                raise ValueError("column block refers to a missing logical slot")
        object.__setattr__(self, "slots", slots)
        object.__setattr__(self, "blocks", blocks)

    @classmethod
    def from_slots(
        cls,
        cache_key: ColumnModelCacheKey,
        slots,
        *,
        blocks=(),
        confidence: ColumnMappingConfidence | None = None,
    ):
        input_slots = tuple(slots)
        input_blocks = tuple(blocks)
        if any(not isinstance(slot, ColumnSlot) for slot in input_slots):
            raise TypeError("from_slots requires immutable ColumnSlot records")
        if any(not isinstance(block, ColumnBlock) for block in input_blocks):
            raise TypeError("from_slots requires immutable ColumnBlock records")
        ordered_slots = tuple(sorted(input_slots, key=lambda slot: slot.logical_idx))
        logical_indices = tuple(slot.logical_idx for slot in ordered_slots)
        if len(logical_indices) != len(set(logical_indices)):
            raise ValueError("logical column indices must be unique")
        ordered_blocks = input_blocks

        def _maps(field_name: str):
            physical_to_logical = []
            logical_to_physical = []
            for slot in ordered_slots:
                physical = getattr(slot, field_name)
                if physical is None:
                    continue
                physical_to_logical.append((physical, slot.logical_idx))
                logical_to_physical.append((slot.logical_idx, physical))
            return FrozenIntLookup(tuple(physical_to_logical)), FrozenIntLookup(tuple(logical_to_physical))

        mine_p2l, mine_l2p = _maps("mine_col")
        base_p2l, base_l2p = _maps("base_col")
        theirs_p2l, theirs_l2p = _maps("theirs_col")
        return cls(
            cache_key=cache_key,
            slots=ordered_slots,
            blocks=ordered_blocks,
            mine_physical_to_logical=mine_p2l,
            base_physical_to_logical=base_p2l,
            theirs_physical_to_logical=theirs_p2l,
            mine_logical_to_physical=mine_l2p,
            base_logical_to_physical=base_l2p,
            theirs_logical_to_physical=theirs_l2p,
            confidence=confidence or ColumnMappingConfidence(),
        )

    def logical_for_physical(self, side: str, physical_col: int) -> int | None:
        side = str(side or "").upper()
        lookup = {
            "A": self.mine_physical_to_logical,
            "MINE": self.mine_physical_to_logical,
            "BASE": self.base_physical_to_logical,
            "B": self.theirs_physical_to_logical,
            "THEIRS": self.theirs_physical_to_logical,
        }.get(side)
        return lookup.get(physical_col) if lookup is not None else None

    def physical_for_logical(self, side: str, logical_idx: int) -> int | None:
        side = str(side or "").upper()
        lookup = {
            "A": self.mine_logical_to_physical,
            "MINE": self.mine_logical_to_physical,
            "BASE": self.base_logical_to_physical,
            "B": self.theirs_logical_to_physical,
            "THEIRS": self.theirs_logical_to_physical,
        }.get(side)
        return lookup.get(logical_idx) if lookup is not None else None


@dataclass(frozen=True, slots=True)
class ColumnSignature:
    """Bounded multi-signal identity derived only from sequential row caches."""

    physical_col: int
    row_count: int
    non_empty_count: int
    first_non_empty_row: int | None
    last_non_empty_row: int | None
    header_signals: tuple[str, ...]
    representative_signals: tuple[tuple[int, str], ...]
    non_empty_pattern: tuple[int, ...]
    formula_signals: tuple[tuple[int, str], ...]
    intrinsic_key: str
    left_context_key: str | None = None
    right_context_key: str | None = None
    ambiguous: bool = False
    ambiguity_reason: str = ""
    exact_content_key: str | None = None

    def __post_init__(self):
        object.__setattr__(self, "header_signals", tuple(self.header_signals))
        object.__setattr__(
            self, "representative_signals", tuple(tuple(item) for item in self.representative_signals)
        )
        object.__setattr__(self, "non_empty_pattern", tuple(self.non_empty_pattern))
        object.__setattr__(
            self, "formula_signals", tuple(tuple(item) for item in self.formula_signals)
        )
        if self.exact_content_key is not None:
            object.__setattr__(self, "exact_content_key", str(self.exact_content_key))

    @property
    def is_blank(self) -> bool:
        return self.non_empty_count == 0

    @property
    def context_key(self) -> tuple[str | None, str, str | None]:
        return self.left_context_key, self.intrinsic_key, self.right_context_key


@dataclass(frozen=True, slots=True)
class ColumnSignatureSnapshot:
    cache_key: ColumnModelCacheKey
    signatures: tuple[ColumnSignature, ...]
    header_row_limit: int
    representative_row_limit: int
    max_col: int
    width_is_explicit: bool

    def __post_init__(self):
        signatures = tuple(self.signatures)
        if not isinstance(self.cache_key, ColumnModelCacheKey):
            raise TypeError("signature snapshot cache_key must be ColumnModelCacheKey")
        if any(not isinstance(signature, ColumnSignature) for signature in signatures):
            raise TypeError("signature snapshot requires immutable ColumnSignature records")
        if isinstance(self.max_col, bool) or not isinstance(self.max_col, int) or self.max_col < 0:
            raise TypeError("signature snapshot max_col must be a non-negative integer")
        if len(signatures) != self.max_col:
            raise ValueError("signature snapshot max_col must match its signature count")
        if not isinstance(self.width_is_explicit, bool):
            raise TypeError("signature snapshot width_is_explicit must be bool")
        object.__setattr__(self, "signatures", signatures)


def _stable_column_signal_digest(value) -> str:
    return hashlib.sha256(repr(value).encode("utf-8", errors="replace")).hexdigest()[:24]


def _column_cell_signal(value, edit_value) -> tuple[str, str | None, bool]:
    """Return deterministic value/formula tokens without Worksheet access.

    The complete column stream is already hashed by one SHA-256 accumulator in
    ``build_column_signatures_from_row_cache``.  Hashing every individual cell
    before feeding that accumulator performed hundreds of thousands of tiny
    cryptographic calls on dense sheets without adding collision resistance to
    the final exact-column digest.  ``repr`` of the tagged immutable payload is
    unambiguous here and keeps the single, final column-level SHA-256 proof.
    """
    literal_formula_text = (
        isinstance(edit_value, str)
        and edit_value.startswith("=")
        and value == edit_value
    )
    formula_identity = None
    if not literal_formula_text:
        special = _special_formula_signature(edit_value)
        if special is not None:
            formula_identity = ("SPECIAL", special)
        else:
            formula = _norm_formula_text(edit_value)
            if formula:
                formula_identity = ("FORMULA", formula)

    if formula_identity is not None:
        formula_digest = repr(formula_identity)
        return (
            # Formula text/special-formula structure is the column identity.
            # Cached results are deliberately excluded: editors may discard
            # them after inserting/deleting a column while leaving the formula
            # itself unchanged. Cell comparison still evaluates available
            # cached values after logical columns have been aligned.
            repr(("FORMULA_CELL", formula_identity)),
            formula_digest,
            True,
        )

    chosen = value if value is not None else edit_value
    if chosen in (None, ""):
        return "", None, False
    return repr(("VALUE", _merge_cmp_value(chosen))), None, True


def _append_bounded_signal(accumulator: dict, prefix: str, item, limit: int):
    if limit <= 0:
        return
    head_limit = (limit + 1) // 2
    tail_limit = limit - head_limit
    head = accumulator[prefix + "_head"]
    tail = accumulator[prefix + "_tail"]
    if len(head) < head_limit:
        head.append(item)
        return
    if tail_limit <= 0:
        return
    tail.append(item)
    if len(tail) > tail_limit:
        del tail[0]


def build_column_signatures_from_row_cache(
    value_rows,
    edit_rows=None,
    *,
    max_col: int | None = None,
    header_row_limit: int = 8,
    representative_row_limit: int = 24,
) -> tuple[ColumnSignature, ...]:
    """Build bounded column signals in one sequential pass over cached rows.

    Inputs are row iterables already captured in memory.  The function never
    receives a worksheet and therefore cannot perform ``Worksheet.cell`` or
    high-row random reads.  Callers that need structural trailing blank columns
    must pass ``max_col`` explicitly; otherwise width is inferred from row tuple
    lengths and is intentionally treated as an unbounded observation.
    """
    header_limit = max(0, int(header_row_limit))
    representative_limit = max(0, int(representative_row_limit))
    width_is_explicit = max_col is not None
    configured_width = max(0, int(max_col or 0))
    accumulators: list[dict] = []
    row_count = 0
    physical_row_count = 0

    def _ensure_width(width: int, prior_rows: int):
        while len(accumulators) < width:
            accumulator = {
                "header": [""] * min(prior_rows, header_limit),
                "non_empty_count": 0,
                "first_non_empty": None,
                "last_non_empty": None,
                "rep_head": [],
                "rep_tail": [],
                "pattern_head": [],
                "pattern_tail": [],
                "formula_head": [],
                "formula_tail": [],
                "exact_digest": hashlib.sha256(),
            }
            for physical_ordinal in range(1, physical_row_count + 1):
                accumulator["exact_digest"].update(
                    f"{physical_ordinal}:0:".encode("utf-8")
                )
            accumulators.append(accumulator)

    _ensure_width(configured_width, 0)
    edit_iterable = edit_rows if edit_rows is not None else ()
    for row_idx, (value_row, edit_row) in enumerate(
        zip_longest(value_rows or (), edit_iterable, fillvalue=()),
        start=1,
    ):
        row_count = row_idx
        value_row = tuple(value_row or ())
        edit_row = tuple(edit_row or ())
        width = (
            configured_width
            if width_is_explicit
            else max(len(value_row), len(edit_row))
        )
        _ensure_width(width, row_idx - 1)
        row_signals = []
        for offset in range(width):
            value = value_row[offset] if offset < len(value_row) else None
            edit_value = edit_row[offset] if offset < len(edit_row) else None
            row_signals.append(_column_cell_signal(value, edit_value))
        # Aligned row caches contain all-None placeholders for rows missing on
        # one side.  Excluding those placeholders reconstructs the side's
        # physical row stream, so a full-column copy remains exactly provable
        # even when Mine and Theirs have independent row insertions/deletions.
        row_is_present = any(non_empty for _signal, _formula, non_empty in row_signals)
        if row_is_present:
            physical_row_count += 1
        for offset, (signal, formula_signal, non_empty) in enumerate(row_signals):
            accumulator = accumulators[offset]
            if row_is_present:
                # Length framing makes adjacent records unambiguous even when a
                # text/error value contains separators or NUL characters.
                accumulator["exact_digest"].update(
                    f"{physical_row_count}:{len(signal)}:{signal}".encode(
                        "utf-8", errors="replace"
                    )
                )
            if row_idx <= header_limit:
                accumulator["header"].append(signal)
            if not non_empty:
                continue
            accumulator["non_empty_count"] += 1
            if accumulator["first_non_empty"] is None:
                accumulator["first_non_empty"] = row_idx
            accumulator["last_non_empty"] = row_idx
            _append_bounded_signal(
                accumulator, "rep", (row_idx, signal), representative_limit
            )
            _append_bounded_signal(
                accumulator, "pattern", row_idx, representative_limit
            )
            if formula_signal is not None:
                _append_bounded_signal(
                    accumulator,
                    "formula",
                    (row_idx, formula_signal),
                    representative_limit,
                )

    provisional = []
    for offset, accumulator in enumerate(accumulators):
        representative = tuple(accumulator["rep_head"] + accumulator["rep_tail"])
        pattern = tuple(accumulator["pattern_head"] + accumulator["pattern_tail"])
        formulas = tuple(accumulator["formula_head"] + accumulator["formula_tail"])
        intrinsic_payload = (
            row_count,
            accumulator["non_empty_count"],
            accumulator["first_non_empty"],
            accumulator["last_non_empty"],
            tuple(accumulator["header"]),
            representative,
            pattern,
            formulas,
        )
        provisional.append(ColumnSignature(
            physical_col=offset + 1,
            row_count=row_count,
            non_empty_count=accumulator["non_empty_count"],
            first_non_empty_row=accumulator["first_non_empty"],
            last_non_empty_row=accumulator["last_non_empty"],
            header_signals=tuple(accumulator["header"]),
            representative_signals=representative,
            non_empty_pattern=pattern,
            formula_signals=formulas,
            intrinsic_key=_stable_column_signal_digest(intrinsic_payload),
            exact_content_key=(
                f"{physical_row_count}:"
                f"{accumulator['exact_digest'].hexdigest()}"
            ),
        ))

    counts: dict[str, int] = {}
    for signature in provisional:
        counts[signature.intrinsic_key] = counts.get(signature.intrinsic_key, 0) + 1

    signatures = []
    for idx, signature in enumerate(provisional):
        is_duplicate = counts.get(signature.intrinsic_key, 0) > 1
        ambiguous = signature.is_blank or is_duplicate
        reason = "blank-column" if signature.is_blank else "duplicate-intrinsic-signature" if is_duplicate else ""
        signatures.append(ColumnSignature(
            physical_col=signature.physical_col,
            row_count=signature.row_count,
            non_empty_count=signature.non_empty_count,
            first_non_empty_row=signature.first_non_empty_row,
            last_non_empty_row=signature.last_non_empty_row,
            header_signals=signature.header_signals,
            representative_signals=signature.representative_signals,
            non_empty_pattern=signature.non_empty_pattern,
            formula_signals=signature.formula_signals,
            intrinsic_key=signature.intrinsic_key,
            left_context_key=provisional[idx - 1].intrinsic_key if idx > 0 else None,
            right_context_key=provisional[idx + 1].intrinsic_key if idx + 1 < len(provisional) else None,
            ambiguous=ambiguous,
            ambiguity_reason=reason,
            exact_content_key=signature.exact_content_key,
        ))
    return tuple(signatures)


def build_column_signature_snapshot(
    cache_key: ColumnModelCacheKey,
    value_rows,
    edit_rows=None,
    *,
    max_col: int | None = None,
    header_row_limit: int = 8,
    representative_row_limit: int = 24,
) -> ColumnSignatureSnapshot:
    width_is_explicit = max_col is not None
    signatures = build_column_signatures_from_row_cache(
        value_rows,
        edit_rows,
        max_col=max_col,
        header_row_limit=header_row_limit,
        representative_row_limit=representative_row_limit,
    )
    return ColumnSignatureSnapshot(
        cache_key=cache_key,
        signatures=signatures,
        header_row_limit=max(0, int(header_row_limit)),
        representative_row_limit=max(0, int(representative_row_limit)),
        max_col=len(signatures),
        width_is_explicit=width_is_explicit,
    )


@dataclass(frozen=True, slots=True)
class ColumnAlignmentResult:
    """Deterministic 2-way logical-column model and fallback diagnostics."""

    model: ColumnModel
    anchor_pairs: tuple[tuple[int, int], ...]
    fallback_slot_indices: tuple[int, ...]
    used_physical_fallback: bool
    fallback_reason: str = ""

    def __post_init__(self):
        object.__setattr__(
            self, "anchor_pairs", tuple((int(left), int(right)) for left, right in self.anchor_pairs)
        )
        object.__setattr__(
            self, "fallback_slot_indices", tuple(int(idx) for idx in self.fallback_slot_indices)
        )

    @property
    def ranges(self) -> tuple[ColumnBlock, ...]:
        return self.model.blocks

    @property
    def has_unresolved(self) -> bool:
        return self.used_physical_fallback or bool(self.fallback_slot_indices)


@dataclass(frozen=True, slots=True)
class ColumnAlignment3WayResult:
    """Base-anchored 3-way model plus both independent side alignments."""

    model: ColumnModel
    mine_to_base: ColumnAlignmentResult
    theirs_to_base: ColumnAlignmentResult
    fallback_slot_indices: tuple[int, ...]
    used_physical_fallback: bool
    fallback_reason: str = ""

    def __post_init__(self):
        if not isinstance(self.model, ColumnModel):
            raise TypeError("3-way column alignment requires an immutable ColumnModel")
        if not isinstance(self.mine_to_base, ColumnAlignmentResult):
            raise TypeError("mine_to_base must be ColumnAlignmentResult")
        if not isinstance(self.theirs_to_base, ColumnAlignmentResult):
            raise TypeError("theirs_to_base must be ColumnAlignmentResult")
        object.__setattr__(
            self,
            "fallback_slot_indices",
            tuple(int(idx) for idx in self.fallback_slot_indices),
        )

    @property
    def ranges(self) -> tuple[ColumnBlock, ...]:
        return self.model.blocks

    @property
    def has_unresolved(self) -> bool:
        return self.used_physical_fallback or bool(self.fallback_slot_indices)


_COLUMN_ALIGNMENT_MAX_COLUMNS = 256
_COLUMN_ALIGNMENT_MIN_SCORE = 0.80
_COLUMN_ALIGNMENT_MIN_MARGIN = 0.08


def _column_positional_signal_similarity(left_values, right_values) -> float:
    left_values = tuple(left_values or ())
    right_values = tuple(right_values or ())
    if left_values == right_values:
        return 1.0
    if len(left_values) == 1 and len(right_values) == 1:
        return float(
            left_values[0] in (None, "") and right_values[0] in (None, "")
        )
    width = max(len(left_values), len(right_values))
    if width <= 0:
        return 1.0
    relevant = 0
    equal = 0
    for idx in range(width):
        left = left_values[idx] if idx < len(left_values) else ""
        right = right_values[idx] if idx < len(right_values) else ""
        if left in (None, "") and right in (None, ""):
            continue
        relevant += 1
        equal += int(left == right)
    return (equal / relevant) if relevant else 1.0


def _column_indexed_signal_similarity(left_values, right_values) -> float:
    left_map = {int(row): signal for row, signal in (left_values or ())}
    right_map = {int(row): signal for row, signal in (right_values or ())}
    rows = set(left_map) | set(right_map)
    if not rows:
        return 1.0
    return sum(left_map.get(row) == right_map.get(row) for row in rows) / len(rows)


def _prepare_column_similarity_profile(signature: ColumnSignature):
    representative_map = {
        int(row): signal for row, signal in signature.representative_signals
    }
    formula_map = {
        int(row): signal for row, signal in signature.formula_signals
    }
    return (
        frozenset(representative_map.items()),
        frozenset(representative_map),
        frozenset(signature.non_empty_pattern),
        frozenset(formula_map.items()),
        frozenset(formula_map),
    )


def _prepared_indexed_signal_similarity(
    left_items,
    left_rows,
    right_items,
    right_rows,
) -> float:
    if left_items == right_items:
        return 1.0
    if not left_rows and not right_rows:
        return 1.0
    if left_rows == right_rows:
        return len(left_items & right_items) / len(left_rows)
    shared_row_count = len(left_rows & right_rows)
    row_count = len(left_rows) + len(right_rows) - shared_row_count
    return len(left_items & right_items) / row_count


def _column_signature_similarity_prepared(
    left: ColumnSignature,
    right: ColumnSignature,
    left_profile,
    right_profile,
) -> float:
    if left.ambiguous or right.ambiguous:
        return 0.0
    if left.intrinsic_key == right.intrinsic_key:
        return 1.0

    if left.header_signals == right.header_signals:
        header_score = 1.0
    elif len(left.header_signals) == 1 and len(right.header_signals) == 1:
        header_score = float(
            left.header_signals[0] in (None, "")
            and right.header_signals[0] in (None, "")
        )
    else:
        header_score = _column_positional_signal_similarity(
            left.header_signals, right.header_signals
        )
    if left_profile[0] == right_profile[0]:
        representative_score = 1.0
    else:
        representative_score = _prepared_indexed_signal_similarity(
            left_profile[0], left_profile[1], right_profile[0], right_profile[1]
        )
    left_pattern = left_profile[2]
    right_pattern = right_profile[2]
    if left_pattern == right_pattern:
        pattern_score = 1.0
    else:
        pattern_intersection_count = len(left_pattern & right_pattern)
        pattern_union_count = (
            len(left_pattern) + len(right_pattern) - pattern_intersection_count
        )
        pattern_score = (
            pattern_intersection_count / pattern_union_count
            if pattern_union_count else 1.0
        )
    max_non_empty = (
        left.non_empty_count
        if left.non_empty_count >= right.non_empty_count
        else right.non_empty_count
    )
    count_score = (
        (
            right.non_empty_count
            if left.non_empty_count >= right.non_empty_count
            else left.non_empty_count
        ) / max_non_empty
        if max_non_empty else 1.0
    )
    if left_profile[3] == right_profile[3]:
        formula_score = 1.0
    else:
        formula_score = _prepared_indexed_signal_similarity(
            left_profile[3], left_profile[4], right_profile[3], right_profile[4]
        )
    left_context = (left.left_context_key, left.right_context_key)
    right_context = (right.left_context_key, right.right_context_key)
    if left_context == right_context:
        context_score = 1.0
    else:
        context_matches = 0
        context_known = 0
        for left_value, right_value in zip(left_context, right_context):
            if left_value is None and right_value is None:
                continue
            context_known += 1
            context_matches += int(
                left_value is not None and left_value == right_value
            )
        context_score = (context_matches / context_known) if context_known else 1.0
    score = (
        0.35 * header_score
        + 0.30 * representative_score
        + 0.15 * pattern_score
        + 0.10 * count_score
        + 0.05 * formula_score
        + 0.05 * context_score
    )
    # Formula references can change text solely because a preceding physical
    # column was inserted.  Until logical-coordinate formula translation is
    # available, never promote differing formula identities to an automatic
    # high-confidence structural match.
    if (
        (left.formula_signals or right.formula_signals)
        and left.formula_signals != right.formula_signals
    ):
        score = min(score, _COLUMN_ALIGNMENT_MIN_SCORE - 0.01)
    return score


def _column_signature_similarity(left: ColumnSignature, right: ColumnSignature) -> float:
    """Bounded deterministic score; ambiguous identities never auto-match."""
    return _column_signature_similarity_prepared(
        left,
        right,
        _prepare_column_similarity_profile(left),
        _prepare_column_similarity_profile(right),
    )


def _column_unique_header_prefix_identity(
    signature: ColumnSignature,
) -> tuple[str, str] | None:
    """Return a strong schema identity from physical header rows 1 and 2.

    Configuration workbooks normally place the field name and type in rows 1
    and 2.  Payload and formula edits can make the complete column signature
    intentionally dissimilar even though those two schema tokens still prove
    that a shifted column retained its identity.  Requiring both tokens, and
    later requiring the pair to be unique on each side, avoids treating a lone
    first-row data value or a repeated generic type as a structural anchor.
    """
    signals = tuple(signature.header_signals or ())
    if len(signals) < 2 or signals[0] in (None, "") or signals[1] in (None, ""):
        return None
    type_signal = str(signals[1])
    text_prefix = "('VALUE', 'TEXT:"
    if not (type_signal.startswith(text_prefix) and type_signal.endswith("')")):
        return None
    type_name = type_signal[len(text_prefix):-2].strip().lower().replace(" ", "")
    primitive_types = {
        "any",
        "bool",
        "boolean",
        "byte",
        "bytes",
        "date",
        "datetime",
        "decimal",
        "double",
        "duration",
        "fixed32",
        "fixed64",
        "float",
        "int",
        "int8",
        "int16",
        "int32",
        "int64",
        "long",
        "object",
        "sfixed32",
        "sfixed64",
        "short",
        "sint32",
        "sint64",
        "string",
        "time",
        "uint",
        "uint8",
        "uint16",
        "uint32",
        "uint64",
    }
    is_container_type = (
        type_name.endswith("[]")
        or any(
            type_name.startswith(prefix) and type_name.endswith(">")
            for prefix in ("array<", "list<", "map<", "repeated<", "set<")
        )
    )
    if type_name not in primitive_types and not is_container_type:
        return None
    return str(signals[0]), str(signals[1])


def _column_alignment_input(value):
    if isinstance(value, ColumnSignatureSnapshot):
        return tuple(value.signatures), value
    return tuple(value or ()), None


def _derive_column_alignment_cache_key(
    left_snapshot: ColumnSignatureSnapshot | None,
    right_snapshot: ColumnSignatureSnapshot | None,
    explicit_key: ColumnModelCacheKey | None,
) -> ColumnModelCacheKey:
    if explicit_key is not None:
        return explicit_key
    if left_snapshot is None and right_snapshot is None:
        return ColumnModelCacheKey("", 0, 0)
    left_key = left_snapshot.cache_key if left_snapshot is not None else None
    right_key = right_snapshot.cache_key if right_snapshot is not None else None
    sheet_name = (
        left_key.sheet_name if left_key is not None else right_key.sheet_name
    )
    return ColumnModelCacheKey(
        sheet_name=sheet_name,
        row_model_version=max(
            left_key.row_model_version if left_key is not None else 0,
            right_key.row_model_version if right_key is not None else 0,
        ),
        column_model_version=max(
            left_key.column_model_version if left_key is not None else 0,
            right_key.column_model_version if right_key is not None else 0,
        ),
        mine_edit_version=left_key.mine_edit_version if left_key is not None else 0,
        base_edit_version=0,
        theirs_edit_version=(
            right_key.theirs_edit_version
            if right_key is not None else 0
        ),
    )


def _derive_column_alignment_cache_key_3way(
    mine_snapshot: ColumnSignatureSnapshot | None,
    base_snapshot: ColumnSignatureSnapshot | None,
    theirs_snapshot: ColumnSignatureSnapshot | None,
    explicit_key: ColumnModelCacheKey | None,
) -> ColumnModelCacheKey:
    if explicit_key is not None:
        return explicit_key
    snapshots = tuple(
        snapshot
        for snapshot in (mine_snapshot, base_snapshot, theirs_snapshot)
        if snapshot is not None
    )
    if not snapshots:
        return ColumnModelCacheKey("", 0, 0)
    keys = tuple(snapshot.cache_key for snapshot in snapshots)
    reference_key = (
        base_snapshot.cache_key if base_snapshot is not None else keys[0]
    )
    return ColumnModelCacheKey(
        sheet_name=reference_key.sheet_name,
        row_model_version=max(key.row_model_version for key in keys),
        column_model_version=max(key.column_model_version for key in keys),
        mine_edit_version=(
            mine_snapshot.cache_key.mine_edit_version
            if mine_snapshot is not None else 0
        ),
        base_edit_version=(
            base_snapshot.cache_key.base_edit_version
            if base_snapshot is not None else 0
        ),
        theirs_edit_version=(
            theirs_snapshot.cache_key.theirs_edit_version
            if theirs_snapshot is not None else 0
        ),
    )


def _column_alignment_snapshot_incompatibility_reason(
    left_snapshot: ColumnSignatureSnapshot | None,
    right_snapshot: ColumnSignatureSnapshot | None,
) -> str:
    if left_snapshot is None or right_snapshot is None:
        return ""
    if (
        left_snapshot.cache_key.sheet_name != right_snapshot.cache_key.sheet_name
        or left_snapshot.cache_key.row_model_version
        != right_snapshot.cache_key.row_model_version
        or left_snapshot.header_row_limit != right_snapshot.header_row_limit
        or left_snapshot.representative_row_limit
        != right_snapshot.representative_row_limit
    ):
        return "incompatible-signature-cache"
    if (
        left_snapshot.max_col != right_snapshot.max_col
        and (
            not left_snapshot.width_is_explicit
            or not right_snapshot.width_is_explicit
        )
    ):
        return "implicit-column-boundary"
    return ""


def _column_alignment_gap_cause_codes(
    left,
    right,
    left_gap,
    right_gap,
    fallback_reason: str = "",
) -> tuple[str, ...]:
    causes = []
    if fallback_reason in _COLUMN_MAPPING_CAUSE_CODES:
        causes.append(fallback_reason)
    gap_signatures = tuple(left[idx] for idx in left_gap) + tuple(
        right[idx] for idx in right_gap
    )
    for signature in gap_signatures:
        if signature.ambiguity_reason in (
            COLUMN_MAPPING_CAUSE_BLANK_COLUMN,
            COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE,
        ):
            causes.append(signature.ambiguity_reason)

    left_formulas = tuple(
        left[idx].formula_signals
        for idx in left_gap
        if left[idx].formula_signals
    )
    right_formulas = tuple(
        right[idx].formula_signals
        for idx in right_gap
        if right[idx].formula_signals
    )
    if (
        left_gap
        and right_gap
        and (left_formulas or right_formulas)
        and left_formulas != right_formulas
    ):
        causes.append(COLUMN_MAPPING_CAUSE_FORMULA_MISMATCH)
    if not causes and (
        (left_gap and right_gap)
        or any(signature.ambiguous for signature in gap_signatures)
    ):
        causes.append(COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE)
    return tuple(dict.fromkeys(causes))


def _ordered_column_anchor_pairs(candidates):
    """Maximum-weight ordered candidate chain with deterministic tie breaks."""
    candidates = sorted(
        ((int(left), int(right), float(score), str(kind)) for left, right, score, kind in candidates),
        key=lambda item: (item[0], item[1], -item[2], item[3]),
    )
    if not candidates:
        return ()
    best: list[tuple[float, int, tuple[tuple[int, int], ...]]] = []
    for idx, (left, right, score, _kind) in enumerate(candidates):
        best_score = score
        best_path = ((left, right),)
        for prev_idx in range(idx):
            prev_left, prev_right, _prev_score, _prev_kind = candidates[prev_idx]
            if prev_left >= left or prev_right >= right:
                continue
            prev_total, _prev_len, prev_path = best[prev_idx]
            candidate_total = prev_total + score
            candidate_path = prev_path + ((left, right),)
            if (
                candidate_total > best_score + 1e-12
                or (
                    abs(candidate_total - best_score) <= 1e-12
                    and (len(candidate_path), tuple(candidate_path))
                    > (len(best_path), tuple(best_path))
                )
            ):
                best_score = candidate_total
                best_path = candidate_path
        best.append((best_score, len(best_path), best_path))
    _score, _length, path = max(
        best,
        key=lambda item: (item[0], item[1], tuple((-a, -b) for a, b in item[2])),
    )
    return tuple(path)


def _build_column_blocks(slots: tuple[ColumnSlot, ...]) -> tuple[ColumnBlock, ...]:
    if not slots:
        return ()

    def _structural_block_key(slot: ColumnSlot):
        # A two-sided unresolved column and an adjacent proven one-sided
        # insertion/deletion are not one actionable range even when their
        # confidence reason happens to match.  Preserve that boundary so the
        # pure structural subset can be accepted without touching the
        # unresolved neighbour.
        return (
            slot.state,
            slot.confidence.ambiguous,
            slot.confidence.reason,
            slot.mine_col is not None,
            slot.base_col is not None,
            slot.theirs_col is not None,
            slot.base_boundary,
            slot.origin_side,
        )

    blocks = []
    start = 0
    for idx in range(1, len(slots) + 1):
        boundary = idx == len(slots)
        if not boundary:
            previous = slots[idx - 1]
            current = slots[idx]
            boundary = _structural_block_key(current) != _structural_block_key(previous)
        if not boundary:
            continue
        group = slots[start:idx]
        confidence = ColumnMappingConfidence(
            score=min(slot.confidence.score for slot in group),
            ambiguous=any(slot.confidence.ambiguous for slot in group),
            reason=next(
                (slot.confidence.reason for slot in group if slot.confidence.reason),
                "",
            ),
            evidence=tuple(dict.fromkeys(
                evidence
                for slot in group
                for evidence in slot.confidence.evidence
            )),
            cause_codes=tuple(dict.fromkeys(
                cause
                for slot in group
                for cause in slot.confidence.cause_codes
            )),
        )
        blocks.append(ColumnBlock(
            ordinal=len(blocks),
            slot_indices=tuple(slot.logical_idx for slot in group),
            state=group[0].state,
            confidence=confidence,
        ))
        start = idx
    return tuple(blocks)


def align_column_signatures_2way(
    left_signatures,
    right_signatures,
    *,
    cache_key: ColumnModelCacheKey | None = None,
    min_score: float = _COLUMN_ALIGNMENT_MIN_SCORE,
    min_margin: float = _COLUMN_ALIGNMENT_MIN_MARGIN,
    max_columns: int = _COLUMN_ALIGNMENT_MAX_COLUMNS,
) -> ColumnAlignmentResult:
    """Align cached 2-way column signatures without any worksheet access.

    Only unique exact identities and mutually unique high-confidence candidates
    become retained anchors.  Every ambiguous or low-confidence two-sided gap
    is kept as an explicit unresolved range using deterministic physical-order
    fallback slots.
    """
    left, left_snapshot = _column_alignment_input(left_signatures)
    right, right_snapshot = _column_alignment_input(right_signatures)
    model_key = _derive_column_alignment_cache_key(
        left_snapshot, right_snapshot, cache_key
    )
    fallback_reason = ""
    force_fallback = False
    incompatibility_reason = _column_alignment_snapshot_incompatibility_reason(
        left_snapshot, right_snapshot
    )
    if incompatibility_reason:
        fallback_reason = incompatibility_reason
        force_fallback = True
    if len(left) > int(max_columns) or len(right) > int(max_columns):
        fallback_reason = "column-limit-exceeded"
        force_fallback = True

    candidates = []
    if not force_fallback:
        left_counts: dict[str, int] = {}
        right_counts: dict[str, int] = {}
        for signature in left:
            left_counts[signature.intrinsic_key] = left_counts.get(signature.intrinsic_key, 0) + 1
        for signature in right:
            right_counts[signature.intrinsic_key] = right_counts.get(signature.intrinsic_key, 0) + 1

        exact_pairs = set()
        right_by_key = {signature.intrinsic_key: idx for idx, signature in enumerate(right)}
        for left_idx, signature in enumerate(left):
            right_idx = right_by_key.get(signature.intrinsic_key)
            if (
                right_idx is not None
                and not signature.ambiguous
                and not right[right_idx].ambiguous
                and left_counts.get(signature.intrinsic_key) == 1
                and right_counts.get(signature.intrinsic_key) == 1
            ):
                exact_pairs.add((left_idx, right_idx))
                candidates.append((left_idx, right_idx, 1.0, "exact"))

        # A branch can replace most payload values or formulas in a column
        # while retaining its field-name/type schema.  The bounded similarity
        # score then drops below the automatic threshold and a real deletion
        # immediately before that column is misread as a physical-order
        # fallback.  Add unique two-row schema identities as ordered anchors;
        # duplicate/blank identities remain conservative.
        left_header_counts: dict[tuple[str, str], int] = {}
        right_header_counts: dict[tuple[str, str], int] = {}
        right_by_header: dict[tuple[str, str], int] = {}
        for signature in left:
            identity = _column_unique_header_prefix_identity(signature)
            if identity is not None:
                left_header_counts[identity] = (
                    left_header_counts.get(identity, 0) + 1
                )
        for right_idx, signature in enumerate(right):
            identity = _column_unique_header_prefix_identity(signature)
            if identity is not None:
                right_header_counts[identity] = (
                    right_header_counts.get(identity, 0) + 1
                )
                right_by_header[identity] = right_idx
        unique_header_pairs = set()
        for left_idx, signature in enumerate(left):
            identity = _column_unique_header_prefix_identity(signature)
            if (
                identity is None
                or signature.ambiguous
                or left_header_counts.get(identity) != 1
                or right_header_counts.get(identity) != 1
            ):
                continue
            right_idx = right_by_header[identity]
            if right[right_idx].ambiguous or (left_idx, right_idx) in exact_pairs:
                continue
            unique_header_pairs.add((left_idx, right_idx))
            candidates.append(
                (left_idx, right_idx, 0.995, "unique-header-prefix")
            )

        proven_pairs = exact_pairs | unique_header_pairs
        proven_left_indices = {left_idx for left_idx, _right_idx in proven_pairs}
        proven_right_indices = {right_idx for _left_idx, right_idx in proven_pairs}
        left_profiles = tuple(
            _prepare_column_similarity_profile(signature) for signature in left
        )
        right_profiles = tuple(
            _prepare_column_similarity_profile(signature) for signature in right
        )
        left_best: list[tuple[float, int] | None] = [None] * len(left)
        left_second: list[tuple[float, int] | None] = [None] * len(left)
        right_best: list[tuple[float, int] | None] = [None] * len(right)
        right_second: list[tuple[float, int] | None] = [None] * len(right)

        for left_idx, left_signature in enumerate(left):
            if left_signature.ambiguous or left_idx in proven_left_indices:
                continue
            for right_idx, right_signature in enumerate(right):
                if (
                    right_signature.ambiguous
                    or right_idx in proven_right_indices
                ):
                    continue
                if (
                    (left_signature.formula_signals or right_signature.formula_signals)
                    and left_signature.formula_signals != right_signature.formula_signals
                ):
                    continue
                score = _column_signature_similarity_prepared(
                    left_signature,
                    right_signature,
                    left_profiles[left_idx],
                    right_profiles[right_idx],
                )
                item = (score, right_idx)
                first = left_best[left_idx]
                if first is None or score > first[0] or (
                    score == first[0] and right_idx < first[1]
                ):
                    left_second[left_idx] = first
                    left_best[left_idx] = item
                else:
                    second = left_second[left_idx]
                    if second is None or score > second[0] or (
                        score == second[0] and right_idx < second[1]
                    ):
                        left_second[left_idx] = item

                item = (score, left_idx)
                first = right_best[right_idx]
                if first is None or score > first[0] or (
                    score == first[0] and left_idx < first[1]
                ):
                    right_second[right_idx] = first
                    right_best[right_idx] = item
                else:
                    second = right_second[right_idx]
                    if second is None or score > second[0] or (
                        score == second[0] and left_idx < second[1]
                    ):
                        right_second[right_idx] = item

        for left_idx, best in enumerate(left_best):
            if best is None:
                continue
            best_score, right_idx = best
            if best_score < float(min_score):
                continue
            left_second_score = (
                left_second[left_idx][0] if left_second[left_idx] is not None else 0.0
            )
            right_best_candidate = right_best[right_idx]
            if right_best_candidate is None or right_best_candidate[1] != left_idx:
                continue
            right_second_score = (
                right_second[right_idx][0]
                if right_second[right_idx] is not None
                else 0.0
            )
            if (
                best_score < 0.999999
                and (
                    best_score - left_second_score < float(min_margin)
                    or best_score - right_second_score < float(min_margin)
                )
            ):
                continue
            candidates.append((left_idx, right_idx, best_score, "approximate"))

    anchors = _ordered_column_anchor_pairs(candidates) if not force_fallback else ()
    anchor_scores = {
        (left_idx, right_idx): max(
            score
            for candidate_left, candidate_right, score, _kind in candidates
            if candidate_left == left_idx and candidate_right == right_idx
        )
        for left_idx, right_idx in anchors
    }
    anchor_kinds = {
        (left_idx, right_idx): next(
            kind
            for preferred_kind in ("exact", "unique-header-prefix", "approximate")
            for candidate_left, candidate_right, _score, kind in candidates
            if (
                candidate_left == left_idx
                and candidate_right == right_idx
                and kind == preferred_kind
            )
        )
        for left_idx, right_idx in anchors
    }

    slots: list[ColumnSlot] = []
    fallback_slot_indices: list[int] = []

    def _append_slot(
        left_idx: int | None,
        right_idx: int | None,
        state: str,
        confidence: ColumnMappingConfidence,
    ):
        logical_idx = len(slots)
        slots.append(ColumnSlot(
            logical_idx=logical_idx,
            mine_col=left[left_idx].physical_col if left_idx is not None else None,
            theirs_col=right[right_idx].physical_col if right_idx is not None else None,
            state=state,
            confidence=confidence,
        ))
        if state == "unresolved":
            fallback_slot_indices.append(logical_idx)

    def _append_gap(left_start: int, left_end: int, right_start: int, right_end: int):
        left_gap = list(range(left_start, left_end))
        right_gap = list(range(right_start, right_end))
        if not left_gap and not right_gap:
            return
        cause_codes = _column_alignment_gap_cause_codes(
            left,
            right,
            left_gap,
            right_gap,
            fallback_reason,
        )
        if force_fallback:
            confidence = ColumnMappingConfidence(
                0.0,
                True,
                fallback_reason or "low-confidence-physical-fallback",
                ("physical-order",),
                cause_codes or (COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE,),
            )
            common = min(len(left_gap), len(right_gap))
            for offset in range(common):
                _append_slot(
                    left_gap[offset], right_gap[offset], "unresolved", confidence
                )
            for left_idx in left_gap[common:]:
                _append_slot(left_idx, None, "unresolved", confidence)
            for right_idx in right_gap[common:]:
                _append_slot(None, right_idx, "unresolved", confidence)
            return
        if not left_gap:
            ambiguous = any(right[idx].ambiguous for idx in right_gap)
            state = "unresolved" if ambiguous else "inserted"
            confidence = ColumnMappingConfidence(
                0.0 if ambiguous else 0.95,
                ambiguous,
                "ambiguous-inserted-columns" if ambiguous else "side-only-insertion",
                cause_codes=cause_codes,
            )
            for right_idx in right_gap:
                _append_slot(None, right_idx, state, confidence)
            return
        if not right_gap:
            ambiguous = any(left[idx].ambiguous for idx in left_gap)
            state = "unresolved" if ambiguous else "deleted"
            confidence = ColumnMappingConfidence(
                0.0 if ambiguous else 0.95,
                ambiguous,
                "ambiguous-deleted-columns" if ambiguous else "side-only-deletion",
                cause_codes=cause_codes,
            )
            for left_idx in left_gap:
                _append_slot(left_idx, None, state, confidence)
            return

        confidence = ColumnMappingConfidence(
            0.0,
            True,
            fallback_reason or "low-confidence-physical-fallback",
            ("physical-order",),
            cause_codes or (COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE,),
        )
        common = min(len(left_gap), len(right_gap))
        for offset in range(common):
            _append_slot(left_gap[offset], right_gap[offset], "unresolved", confidence)
        for left_idx in left_gap[common:]:
            _append_slot(left_idx, None, "unresolved", confidence)
        for right_idx in right_gap[common:]:
            _append_slot(None, right_idx, "unresolved", confidence)

    previous_left = 0
    previous_right = 0
    for left_idx, right_idx in anchors:
        _append_gap(previous_left, left_idx, previous_right, right_idx)
        score = anchor_scores[(left_idx, right_idx)]
        exact = left[left_idx].intrinsic_key == right[right_idx].intrinsic_key
        anchor_kind = anchor_kinds[(left_idx, right_idx)]
        if exact:
            confidence_reason = "exact-anchor"
            confidence_evidence = ("intrinsic",)
        elif anchor_kind == "unique-header-prefix":
            confidence_reason = "unique-header-prefix-anchor"
            confidence_evidence = ("schema-header",)
        else:
            confidence_reason = "high-confidence-anchor"
            confidence_evidence = ("multi-signal",)
        _append_slot(
            left_idx,
            right_idx,
            "retained",
            ColumnMappingConfidence(
                score,
                False,
                confidence_reason,
                confidence_evidence,
            ),
        )
        previous_left = left_idx + 1
        previous_right = right_idx + 1
    _append_gap(previous_left, len(left), previous_right, len(right))

    frozen_slots = tuple(slots)
    blocks = _build_column_blocks(frozen_slots)
    unresolved = force_fallback or bool(fallback_slot_indices)
    overall_score = min(
        (slot.confidence.score for slot in frozen_slots),
        default=0.0 if force_fallback else 1.0,
    )
    model_cause_codes = [
        cause
        for slot in frozen_slots
        for cause in slot.confidence.cause_codes
    ]
    if fallback_reason in _COLUMN_MAPPING_CAUSE_CODES:
        model_cause_codes.append(fallback_reason)
    model = ColumnModel.from_slots(
        model_key,
        frozen_slots,
        blocks=blocks,
        confidence=ColumnMappingConfidence(
            overall_score,
            unresolved,
            "unresolved-column-range" if unresolved else "deterministic-two-way-alignment",
            cause_codes=tuple(dict.fromkeys(model_cause_codes)),
        ),
    )
    return ColumnAlignmentResult(
        model=model,
        anchor_pairs=tuple(
            (left[left_idx].physical_col, right[right_idx].physical_col)
            for left_idx, right_idx in anchors
        ),
        fallback_slot_indices=tuple(fallback_slot_indices),
        used_physical_fallback=unresolved,
        fallback_reason=(fallback_reason or "unresolved-column-range") if unresolved else "",
    )


def _project_side_alignment_to_base(
    alignment: ColumnAlignmentResult,
    base_count: int,
):
    """Return Base-column mappings and side insertions grouped by Base boundary."""
    base_mapping = {}
    insertions: list[list[tuple[int, ColumnMappingConfidence]]] = [
        [] for _idx in range(base_count + 1)
    ]
    base_seen = 0
    for slot in alignment.model.slots:
        side_col = slot.mine_col
        base_col = slot.theirs_col
        if base_col is None:
            if side_col is not None:
                insertions[min(base_seen, base_count)].append(
                    (side_col, slot.confidence)
                )
            continue
        base_mapping[base_col] = (side_col, slot.confidence)
        base_seen += 1
    return base_mapping, tuple(tuple(group) for group in insertions)


def align_column_signatures_3way(
    mine_signatures,
    base_signatures,
    theirs_signatures,
    *,
    cache_key: ColumnModelCacheKey | None = None,
    min_score: float = _COLUMN_ALIGNMENT_MIN_SCORE,
    min_margin: float = _COLUMN_ALIGNMENT_MIN_MARGIN,
    max_columns: int = _COLUMN_ALIGNMENT_MAX_COLUMNS,
) -> ColumnAlignment3WayResult:
    """Map Mine and Theirs to Base independently, then compose logical slots.

    Every Base column owns exactly one slot.  Side-only columns are placed at
    their Base-relative boundary.  Insertions on both sides are paired only
    when a unique full-column value/formula digest proves their equivalence;
    all unproved or incompatible remainder stays separate and unresolved.
    """
    mine, mine_snapshot = _column_alignment_input(mine_signatures)
    base, base_snapshot = _column_alignment_input(base_signatures)
    theirs, theirs_snapshot = _column_alignment_input(theirs_signatures)
    model_key = _derive_column_alignment_cache_key_3way(
        mine_snapshot,
        base_snapshot,
        theirs_snapshot,
        cache_key,
    )

    mine_input = mine_snapshot if mine_snapshot is not None else mine
    base_input = base_snapshot if base_snapshot is not None else base
    theirs_input = theirs_snapshot if theirs_snapshot is not None else theirs
    mine_to_base = align_column_signatures_2way(
        mine_input,
        base_input,
        min_score=min_score,
        min_margin=min_margin,
        max_columns=max_columns,
    )
    theirs_to_base = align_column_signatures_2way(
        theirs_input,
        base_input,
        min_score=min_score,
        min_margin=min_margin,
        max_columns=max_columns,
    )

    mine_by_base, mine_insertions = _project_side_alignment_to_base(
        mine_to_base, len(base)
    )
    theirs_by_base, theirs_insertions = _project_side_alignment_to_base(
        theirs_to_base, len(base)
    )
    mine_signature_by_col = {item.physical_col: item for item in mine}
    theirs_signature_by_col = {item.physical_col: item for item in theirs}

    def _exact_key_counts(signatures):
        counts = {}
        for signature in signatures:
            key = signature.exact_content_key
            if key:
                counts[key] = counts.get(key, 0) + 1
        return counts

    mine_exact_counts = _exact_key_counts(mine)
    theirs_exact_counts = _exact_key_counts(theirs)
    slots: list[ColumnSlot] = []
    fallback_slot_indices: list[int] = []

    def _append_slot(
        mine_col: int | None,
        base_col: int | None,
        theirs_col: int | None,
        state: str,
        confidence: ColumnMappingConfidence,
        base_boundary: int | None = None,
        origin_side: str | None = None,
    ):
        logical_idx = len(slots)
        slots.append(ColumnSlot(
            logical_idx=logical_idx,
            mine_col=mine_col,
            base_col=base_col,
            theirs_col=theirs_col,
            state=state,
            confidence=confidence,
            base_boundary=base_boundary,
            origin_side=origin_side,
        ))
        if state == "unresolved" or confidence.ambiguous:
            fallback_slot_indices.append(logical_idx)

    def _insertion_confidence(
        original: ColumnMappingConfidence,
        side: str,
        boundary: int,
    ) -> tuple[str, ColumnMappingConfidence]:
        ambiguous = original.ambiguous
        return (
            "unresolved" if ambiguous else "inserted",
            ColumnMappingConfidence(
                original.score,
                ambiguous,
                "ambiguous-side-insertion" if ambiguous else "side-only-insertion",
                tuple(dict.fromkeys(
                    original.evidence
                    + (f"base-boundary:{boundary}", f"side:{side}")
                )),
                original.cause_codes or (
                    (COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE,) if ambiguous else ()
                ),
            ),
        )

    def _append_insertion_gap(
        mine_group,
        theirs_group,
        boundary: int,
    ):
        def _append_competing_gap(mine_gap, theirs_gap):
            if not mine_gap and not theirs_gap:
                return
            if not mine_gap or not theirs_gap:
                side = "mine" if mine_gap else "theirs"
                for physical_col, original in mine_gap or theirs_gap:
                    state, confidence = _insertion_confidence(
                        original, side, boundary
                    )
                    _append_slot(
                        physical_col if side == "mine" else None,
                        None,
                        physical_col if side == "theirs" else None,
                        state,
                        confidence,
                        boundary,
                        side,
                    )
                return
            cause_codes = tuple(dict.fromkeys(
                cause
                for _physical_col, original in mine_gap + theirs_gap
                for cause in original.cause_codes
            ))
            confidence = ColumnMappingConfidence(
                0.0,
                True,
                "ambiguous-competing-insertions",
                (f"base-boundary:{boundary}", "separate-side-columns"),
                cause_codes or (COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE,),
            )
            for physical_col, _original in mine_gap:
                _append_slot(
                    physical_col,
                    None,
                    None,
                    "unresolved",
                    confidence,
                    boundary,
                    "mine",
                )
            for physical_col, _original in theirs_gap:
                _append_slot(
                    None,
                    None,
                    physical_col,
                    "unresolved",
                    confidence,
                    boundary,
                    "theirs",
                )

        # Build an ordered exact-match chain.  Requiring a non-blank digest to
        # be unique on each complete side prevents duplicate/blank columns from
        # being paired speculatively.  Gaps on both sides remain competing, so
        # a two-column block with only its first column equal converges to one
        # common slot plus a conservative two-slot conflict for the remainder.
        candidates = []
        for mine_pos, (mine_col, _mine_confidence) in enumerate(mine_group):
            mine_signature = mine_signature_by_col.get(mine_col)
            if mine_signature is None or mine_signature.is_blank:
                continue
            key = mine_signature.exact_content_key
            if not key or mine_exact_counts.get(key) != 1:
                continue
            for theirs_pos, (theirs_col, _theirs_confidence) in enumerate(
                theirs_group
            ):
                theirs_signature = theirs_signature_by_col.get(theirs_col)
                if (
                    theirs_signature is None
                    or theirs_signature.is_blank
                    or theirs_signature.exact_content_key != key
                    or theirs_exact_counts.get(key) != 1
                ):
                    continue
                candidates.append((mine_pos, theirs_pos))

        matches = ()
        if candidates:
            best_paths = []
            for mine_pos, theirs_pos in candidates:
                best_path = ((mine_pos, theirs_pos),)
                for previous_pos, (prev_mine, prev_theirs) in enumerate(candidates):
                    if previous_pos >= len(best_paths):
                        break
                    if prev_mine >= mine_pos or prev_theirs >= theirs_pos:
                        continue
                    candidate_path = best_paths[previous_pos] + (
                        (mine_pos, theirs_pos),
                    )
                    if (
                        len(candidate_path) > len(best_path)
                        or (
                            len(candidate_path) == len(best_path)
                            and candidate_path < best_path
                        )
                    ):
                        best_path = candidate_path
                best_paths.append(best_path)
            matches = max(
                best_paths,
                key=lambda path: (len(path), tuple((-a, -b) for a, b in path)),
            )

        mine_cursor = 0
        theirs_cursor = 0
        for mine_pos, theirs_pos in matches:
            _append_competing_gap(
                mine_group[mine_cursor:mine_pos],
                theirs_group[theirs_cursor:theirs_pos],
            )
            mine_col, _mine_confidence = mine_group[mine_pos]
            theirs_col, _theirs_confidence = theirs_group[theirs_pos]
            _append_slot(
                mine_col,
                None,
                theirs_col,
                "inserted",
                ColumnMappingConfidence(
                    1.0,
                    False,
                    "common-side-insertion",
                    (
                        f"base-boundary:{boundary}",
                        "exact-full-column-content",
                        "unique-on-both-sides",
                    ),
                ),
                boundary,
                "both",
            )
            mine_cursor = mine_pos + 1
            theirs_cursor = theirs_pos + 1
        _append_competing_gap(
            mine_group[mine_cursor:],
            theirs_group[theirs_cursor:],
        )

    def _append_insertions(boundary: int):
        mine_group = mine_insertions[boundary]
        theirs_group = theirs_insertions[boundary]
        if not mine_group and not theirs_group:
            return
        _append_insertion_gap(
            mine_group,
            theirs_group,
            boundary,
        )

    missing_mapping_confidence = ColumnMappingConfidence(
        0.0,
        True,
        "missing-base-projection",
        ("internal-safe-fallback",),
        (COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE,),
    )
    for base_idx, base_signature in enumerate(base):
        _append_insertions(base_idx)
        base_col = base_signature.physical_col
        mine_col, mine_confidence = mine_by_base.get(
            base_col, (None, missing_mapping_confidence)
        )
        theirs_col, theirs_confidence = theirs_by_base.get(
            base_col, (None, missing_mapping_confidence)
        )
        ambiguous = mine_confidence.ambiguous or theirs_confidence.ambiguous
        evidence = list(mine_confidence.evidence + theirs_confidence.evidence)
        cause_codes = tuple(dict.fromkeys(
            mine_confidence.cause_codes + theirs_confidence.cause_codes
        ))
        if mine_col is None:
            evidence.append("mine-missing")
        if theirs_col is None:
            evidence.append("theirs-missing")
        if ambiguous:
            state = "unresolved"
            reason = "unresolved-base-mapping"
        elif mine_col is None and theirs_col is None:
            state = "both-deleted"
            reason = "base-column-missing-on-both-sides"
        elif mine_col is None:
            state = "mine-deleted"
            reason = "base-column-missing-on-mine"
        elif theirs_col is None:
            state = "theirs-deleted"
            reason = "base-column-missing-on-theirs"
        else:
            state = "retained"
            reason = "base-anchored"
        _append_slot(
            mine_col,
            base_col,
            theirs_col,
            state,
            ColumnMappingConfidence(
                min(mine_confidence.score, theirs_confidence.score),
                ambiguous,
                reason,
                tuple(dict.fromkeys(evidence + ["base-identity"])),
                cause_codes,
            ),
        )
    _append_insertions(len(base))

    frozen_slots = tuple(slots)
    used_physical_fallback = (
        mine_to_base.used_physical_fallback
        or theirs_to_base.used_physical_fallback
    )
    unresolved = bool(fallback_slot_indices) or used_physical_fallback
    fallback_reasons = []
    if mine_to_base.fallback_reason:
        fallback_reasons.append(f"mine-to-base:{mine_to_base.fallback_reason}")
    if theirs_to_base.fallback_reason:
        fallback_reasons.append(f"theirs-to-base:{theirs_to_base.fallback_reason}")
    model = ColumnModel.from_slots(
        model_key,
        frozen_slots,
        blocks=_build_column_blocks(frozen_slots),
        confidence=ColumnMappingConfidence(
            min(
                (slot.confidence.score for slot in frozen_slots),
                default=0.0 if used_physical_fallback else 1.0,
            ),
            unresolved,
            (
                "unresolved-three-way-column-range"
                if unresolved else "deterministic-base-anchored-alignment"
            ),
            cause_codes=tuple(dict.fromkeys(
                mine_to_base.model.confidence.cause_codes
                + theirs_to_base.model.confidence.cause_codes
                + tuple(
                    cause
                    for slot in frozen_slots
                    for cause in slot.confidence.cause_codes
                )
            )),
        ),
    )
    return ColumnAlignment3WayResult(
        model=model,
        mine_to_base=mine_to_base,
        theirs_to_base=theirs_to_base,
        fallback_slot_indices=tuple(fallback_slot_indices),
        used_physical_fallback=used_physical_fallback,
        fallback_reason=(
            ";".join(fallback_reasons)
            if fallback_reasons
            else "unresolved-three-way-column-range" if unresolved else ""
        ),
    )


def _compute_row_pairs_from_signatures(sig_a: list[str], sig_b: list[str]):
    """Align precomputed row signatures without rescanning worksheets.

    Trimming the exact common prefix/suffix first avoids SequenceMatcher's
    quadratic behavior on large sheets containing many repeated rows while
    preserving exact alignment inside the changed middle section.
    """
    sig_a = _contextualize_blank_row_signatures(sig_a)
    sig_b = _contextualize_blank_row_signatures(sig_b)
    len_a = len(sig_a)
    len_b = len(sig_b)
    prefix = 0
    common_len = min(len_a, len_b)
    while prefix < common_len and sig_a[prefix] == sig_b[prefix]:
        prefix += 1

    suffix = 0
    while (
        suffix < (common_len - prefix)
        and sig_a[len_a - suffix - 1] == sig_b[len_b - suffix - 1]
    ):
        suffix += 1

    pairs: list[tuple[int | None, int | None]] = [
        (idx + 1, idx + 1) for idx in range(prefix)
    ]

    end_a = len_a - suffix
    end_b = len_b - suffix
    mid_a = sig_a[prefix:end_a]
    mid_b = sig_b[prefix:end_b]

    def _sim_score(sa: str, sb: str) -> float:
        if sa == sb:
            return 2.0
        if (not sa) or (not sb):
            return 0.0
        # Different high-confidence keys are different logical records.  A
        # substitution here would turn independent insert/delete operations
        # into a misleading cell conflict and could delete the wrong row.
        if (
            sa.startswith(_UNIQUE_ROW_KEY_SIGNATURE_PREFIX)
            and sb.startswith(_UNIQUE_ROW_KEY_SIGNATURE_PREFIX)
        ):
            return float("-inf")
        try:
            return difflib.SequenceMatcher(a=sa, b=sb, autojunk=False).ratio()
        except Exception:
            return 0.0

    def _align_bounded_replace(
        ai1: int,
        ai2: int,
        bj1: int,
        bj2: int,
    ) -> list[tuple[int | None, int | None]] | None:
        """Globally align a bounded replacement block with two-sided gaps.

        Exact anchors have already been removed by SequenceMatcher.  Allowing
        both delete and insert steps is essential even when total row counts
        are equal: one side may insert a record and delete a different record.
        Different high-confidence keys are prohibited from matching.
        """
        count_a = ai2 - ai1
        count_b = bj2 - bj1
        if count_a <= 0 or count_b <= 0:
            return None
        all_high_confidence_keys = all(
            signature.startswith(_UNIQUE_ROW_KEY_SIGNATURE_PREFIX)
            for signature in sig_a[ai1:ai2] + sig_b[bj1:bj2]
        )
        product_limit = 262144 if all_high_confidence_keys else 16384
        side_limit = 1024 if all_high_confidence_keys else 256
        if (
            count_a * count_b > product_limit
            or max(count_a, count_b) > side_limit
        ):
            return None

        negative = float("-inf")
        gap_penalty = -0.55
        scores = [
            [negative] * (count_b + 1)
            for _ in range(count_a + 1)
        ]
        decisions = [
            [""] * (count_b + 1)
            for _ in range(count_a + 1)
        ]
        scores[0][0] = 0.0
        for idx_a in range(1, count_a + 1):
            scores[idx_a][0] = idx_a * gap_penalty
            decisions[idx_a][0] = "A"
        for idx_b in range(1, count_b + 1):
            scores[0][idx_b] = idx_b * gap_penalty
            decisions[0][idx_b] = "B"

        for idx_a in range(1, count_a + 1):
            for idx_b in range(1, count_b + 1):
                row_similarity = _sim_score(
                    sig_a[ai1 + idx_a - 1],
                    sig_b[bj1 + idx_b - 1],
                )
                match_score = (
                    scores[idx_a - 1][idx_b - 1] + row_similarity
                    if row_similarity != negative else negative
                )
                delete_score = scores[idx_a - 1][idx_b] + gap_penalty
                insert_score = scores[idx_a][idx_b - 1] + gap_penalty
                best = max(match_score, delete_score, insert_score)
                scores[idx_a][idx_b] = best
                # A real row match wins ties; otherwise emit the right-side
                # insertion before the left-side deletion for deterministic
                # independent-row ordering.
                if match_score == best:
                    decisions[idx_a][idx_b] = "M"
                elif insert_score == best:
                    decisions[idx_a][idx_b] = "B"
                else:
                    decisions[idx_a][idx_b] = "A"

        operations: list[tuple[int | None, int | None]] = []
        idx_a = count_a
        idx_b = count_b
        while idx_a > 0 or idx_b > 0:
            decision = decisions[idx_a][idx_b]
            if decision == "M":
                operations.append((ai1 + idx_a, bj1 + idx_b))
                idx_a -= 1
                idx_b -= 1
            elif decision == "A":
                operations.append((ai1 + idx_a, None))
                idx_a -= 1
            elif decision == "B":
                operations.append((None, bj1 + idx_b))
                idx_b -= 1
            else:
                return None
        operations.reverse()
        return operations

    sm = difflib.SequenceMatcher(a=mid_a, b=mid_b, autojunk=False)
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        ai1 = prefix + i1
        ai2 = prefix + i2
        bj1 = prefix + j1
        bj2 = prefix + j2
        if tag == "equal":
            for i, j in zip(range(ai1, ai2), range(bj1, bj2)):
                pairs.append((i + 1, j + 1))
        elif tag == "replace":
            block_len_a = ai2 - ai1
            block_len_b = bj2 - bj1
            common = min(block_len_a, block_len_b)
            bounded_alignment = _align_bounded_replace(
                ai1,
                ai2,
                bj1,
                bj2,
            )
            if bounded_alignment is not None:
                pairs.extend(bounded_alignment)
                continue
            # Large equal-length replacement blocks are retained 1:1 unless a
            # bounded evidence-based alignment above proved structural gaps.
            # This avoids quadratic fuzzy matching on formula-heavy sheets.
            if block_len_a == block_len_b:
                for k in range(common):
                    pairs.append((ai1 + k + 1, bj1 + k + 1))
                continue
            head_score = 0.0
            tail_score = 0.0
            # For very large unequal replace blocks the choice is still only
            # head-vs-tail. A bounded, evenly distributed sample preserves that
            # decision without quadratic character matching across every row.
            if common <= 128:
                sample_offsets = range(common)
            else:
                sample_count = 64
                sample_offsets = sorted({
                    int(round(idx * (common - 1) / (sample_count - 1)))
                    for idx in range(sample_count)
                })
            for k in sample_offsets:
                head_score += _sim_score(sig_a[ai1 + k], sig_b[bj1 + k])
                tail_score += _sim_score(sig_a[ai2 - common + k], sig_b[bj2 - common + k])
            use_tail = tail_score >= head_score
            if use_tail:
                extra_a = block_len_a - common
                extra_b = block_len_b - common
                for k in range(extra_a):
                    pairs.append((ai1 + k + 1, None))
                for k in range(extra_b):
                    pairs.append((None, bj1 + k + 1))
                a_start = ai2 - common
                b_start = bj2 - common
                for k in range(common):
                    pairs.append((a_start + k + 1, b_start + k + 1))
            else:
                for k in range(common):
                    pairs.append((ai1 + k + 1, bj1 + k + 1))
                for k in range(common, block_len_a):
                    pairs.append((ai1 + k + 1, None))
                for k in range(common, block_len_b):
                    pairs.append((None, bj1 + k + 1))
        elif tag == "delete":
            for i in range(ai1, ai2):
                pairs.append((i + 1, None))
        elif tag == "insert":
            for j in range(bj1, bj2):
                pairs.append((None, j + 1))

    if suffix:
        start_a = len_a - suffix
        start_b = len_b - suffix
        for k in range(suffix):
            pairs.append((start_a + k + 1, start_b + k + 1))
    return pairs


def _compute_row_pairs_generic(
    ws_a,
    ws_b,
    max_col: int,
    force: bool = False,
    *,
    max_row_a: int | None = None,
    max_row_b: int | None = None,
    ws_a_edit=None,
    ws_b_edit=None,
):
    """Compute row alignment pairs between two worksheets."""
    ws_a_rows, ws_a_cols = _worksheet_scan_bounds(ws_a)
    ws_b_rows, ws_b_cols = _worksheet_scan_bounds(ws_b)
    max_row_a = max(1, int(max_row_a if max_row_a is not None else ws_a_rows))
    max_row_b = max(1, int(max_row_b if max_row_b is not None else ws_b_rows))
    max_row_a, max_row_b = _shared_physical_row_horizon(
        ws_a,
        ws_b,
        max_row_a,
        max_row_b,
        ws_a_edit,
        ws_b_edit,
    )
    max_row = max(max_row_a, max_row_b)
    if max_row <= 0:
        return []
    if not _should_auto_row_align(max_row_a, max_row_b, force=force):
        return [(r if r <= max_row_a else None, r if r <= max_row_b else None) for r in range(1, max_row + 1)]

    source_width_a = max(ws_a_cols, _worksheet_scan_bounds(ws_a_edit)[1] if ws_a_edit is not None else 1)
    source_width_b = max(ws_b_cols, _worksheet_scan_bounds(ws_b_edit)[1] if ws_b_edit is not None else 1)
    width_a = max(1, min(int(max_col or 1), source_width_a))
    width_b = max(1, min(int(max_col or 1), source_width_b))
    rows_a_cache = _read_rows_into_cache(
        ws_a, range(1, max_row_a + 1), width_a
    )
    rows_b_cache = _read_rows_into_cache(
        ws_b, range(1, max_row_b + 1), width_b
    )
    edit_rows_a_cache = (
        _read_rows_into_cache(ws_a_edit, range(1, max_row_a + 1), width_a)
        if ws_a_edit is not None else {}
    )
    edit_rows_b_cache = (
        _read_rows_into_cache(ws_b_edit, range(1, max_row_b + 1), width_b)
        if ws_b_edit is not None else {}
    )
    rows_a = [_row_from_cache(rows_a_cache, row_idx, width_a) for row_idx in range(1, max_row_a + 1)]
    rows_b = [_row_from_cache(rows_b_cache, row_idx, width_b) for row_idx in range(1, max_row_b + 1)]
    edit_rows_a = (
        [_row_from_cache(edit_rows_a_cache, row_idx, width_a) for row_idx in range(1, max_row_a + 1)]
        if ws_a_edit is not None else None
    )
    edit_rows_b = (
        [_row_from_cache(edit_rows_b_cache, row_idx, width_b) for row_idx in range(1, max_row_b + 1)]
        if ws_b_edit is not None else None
    )
    sig_a, sig_b = _row_signatures_from_unique_column_anchors(
        rows_a,
        rows_b,
        width_a,
        width_b,
        edit_rows_a,
        edit_rows_b,
    )

    return _compute_row_pairs_from_signatures(sig_a, sig_b)


def _collapse_one_sided_blank_tail_padding(
    display_pairs: list[tuple[int | None, int | None]],
    ws_a_val,
    ws_b_val,
    ws_a_edit,
    ws_b_edit,
    effective_max_row_a: int,
    effective_max_row_b: int,
    max_col: int,
    *,
    cancel_check=None,
) -> list[tuple[int | None, int | None]]:
    """Drop value-empty coordinate padding before a real one-sided tail append.

    Effective-bound alignment can expose a dense run of empty coordinates on
    the longer side before its first real appended row.  Those coordinates are
    spreadsheet padding, not inserted row records.  Only an empty *prefix* of a
    consecutive one-sided tail run is folded; internal one-sided blank rows and
    the real non-empty append remain structural differences.

    Both the cached-value and edit/formula worksheets are required.  This keeps
    missing-cache formulas (including formulas returning ``""``) non-empty and
    makes the fallback conservative while edit data is still loading.
    """
    pairs = list(display_pairs or [])
    if not pairs or ws_a_edit is None or ws_b_edit is None:
        return pairs
    try:
        max_a = max(1, int(effective_max_row_a or 1))
        max_b = max(1, int(effective_max_row_b or 1))
        width = max(1, int(max_col or 1))
    except Exception:
        return pairs

    candidates: dict[int, tuple[str, int, bool]] = {}
    rows_a: list[int] = []
    rows_b: list[int] = []
    for idx, (ra, rb) in enumerate(pairs):
        if (
            ra is None
            and rb is not None
            and (int(rb) > max_a or int(rb) > max_b)
        ):
            candidates[idx] = ("B", int(rb), int(rb) > max_b)
            rows_b.append(int(rb))
        elif (
            rb is None
            and ra is not None
            and (int(ra) > max_b or int(ra) > max_a)
        ):
            candidates[idx] = ("A", int(ra), int(ra) > max_a)
            rows_a.append(int(ra))
    if not candidates:
        return pairs

    val_a = _read_rows_into_cache(
        ws_a_val, rows_a, width, require_complete=True, cancel_check=cancel_check
    )
    edit_a = _read_rows_into_cache(
        ws_a_edit, rows_a, width, require_complete=True, cancel_check=cancel_check
    )
    val_b = _read_rows_into_cache(
        ws_b_val, rows_b, width, require_complete=True, cancel_check=cancel_check
    )
    edit_b = _read_rows_into_cache(
        ws_b_edit, rows_b, width, require_complete=True, cancel_check=cancel_check
    )
    if (rows_a and (not val_a or not edit_a)) or (rows_b and (not val_b or not edit_b)):
        return pairs

    def _has_value_or_formula(side: str, row_idx: int) -> bool:
        if side == "A":
            value_row = _row_from_cache(val_a, row_idx, width)
            edit_row = _row_from_cache(edit_a, row_idx, width)
        else:
            value_row = _row_from_cache(val_b, row_idx, width)
            edit_row = _row_from_cache(edit_b, row_idx, width)
        return any(
            value not in (None, "") or edit_value not in (None, "")
            for value, edit_value in zip(value_row, edit_row)
        )

    remove_indices: set[int] = set()
    sorted_indices = sorted(candidates)
    cursor = 0
    while cursor < len(sorted_indices):
        start = cursor
        start_idx = sorted_indices[start]
        side, row_idx, _beyond_own = candidates[start_idx]
        cursor += 1
        while cursor < len(sorted_indices):
            next_idx = sorted_indices[cursor]
            next_side, next_row, _next_beyond_own = candidates[next_idx]
            prev_idx = sorted_indices[cursor - 1]
            _prev_side, prev_row, _prev_beyond_own = candidates[prev_idx]
            if next_idx != prev_idx + 1 or next_side != side or next_row != prev_row + 1:
                break
            cursor += 1

        group = sorted_indices[start:cursor]
        for pair_idx in group:
            candidate_side, candidate_row, beyond_own = candidates[pair_idx]
            if beyond_own and not _has_value_or_formula(
                candidate_side,
                candidate_row,
            ):
                remove_indices.add(pair_idx)
        first_content = None
        for pos, pair_idx in enumerate(group):
            candidate_side, candidate_row, _beyond_own = candidates[pair_idx]
            if _has_value_or_formula(candidate_side, candidate_row):
                first_content = pos
                break
        if first_content is not None and first_content > 0:
            remove_indices.update(group[:first_content])

    if not remove_indices:
        return pairs
    return [pair for idx, pair in enumerate(pairs) if idx not in remove_indices]


def _row_map_from_pairs(pairs: list[tuple[int | None, int | None]]) -> dict[int, int]:
    out = {}
    for left, right in pairs:
        if left is not None and right is not None:
            out[left] = right
    return out


def _augment_three_way_row_pairs_with_base_deletions(
    display_pairs: list[tuple[int | None, int | None]],
    mine_to_base: dict[int, int] | None,
    theirs_to_base: dict[int, int] | None,
    base_max_row: int | None,
) -> tuple[list[tuple[int | None, int | None]], dict[int, int | None]]:
    """Insert logical rows deleted from both Mine and Theirs.

    The normal display alignment is built from Mine/Theirs, so a row that is
    present only in Base has no pair at all.  That is a meaningful three-way
    deletion and must remain visible to the difference browser.  Return the
    updated pairs plus explicit Base-row overrides for the synthetic
    ``(None, None)`` entries.  Keeping this projection in the cache layer
    means loaded and not-yet-opened Sheet views expose exactly the same rows.

    ``mine_to_base``/``theirs_to_base`` intentionally contain only confident
    side-to-Base matches; unknown/independent append rows therefore do not
    consume a Base identity and are not mistaken for deletions.
    """
    pairs = list(display_pairs or ())
    limit = max(0, int(base_max_row or 0))
    if not pairs or limit <= 0:
        return pairs, {}
    mine_map = mine_to_base or {}
    theirs_map = theirs_to_base or {}
    used_base_rows = {
        int(value)
        for value in tuple(mine_map.values()) + tuple(theirs_map.values())
        if value is not None and int(value) > 0
    }
    missing = [row for row in range(1, limit + 1) if row not in used_base_rows]
    if not missing:
        return pairs, {}

    def pair_base_identity(pair: tuple[int | None, int | None]) -> int | None:
        left, right = pair
        if left is not None and left in mine_map:
            return int(mine_map[left])
        if right is not None and right in theirs_map:
            return int(theirs_map[right])
        return None

    synthetic: dict[int, int | None] = {}
    # Insert in ascending Base order.  Since every insertion is before a
    # larger Base identity, the recorded pair index remains correct after
    # subsequent insertions.
    for base_row in missing:
        insert_at = len(pairs)
        for idx, pair in enumerate(pairs):
            identity = pair_base_identity(pair)
            if identity is not None and identity >= base_row:
                insert_at = idx
                break
        pairs.insert(insert_at, (None, None))
        # Shift all existing synthetic indices at/after the insertion point.
        synthetic = {
            (idx + 1 if idx >= insert_at else idx): value
            for idx, value in synthetic.items()
        }
        synthetic[insert_at] = int(base_row)
    return pairs, synthetic


def _reconcile_three_way_row_pairs_by_base(
    display_pairs: list[tuple[int | None, int | None]],
    mine_to_base: dict[int, int] | None,
    theirs_to_base: dict[int, int] | None,
    ws_mine=None,
    ws_theirs=None,
    max_col: int | None = None,
) -> list[tuple[int | None, int | None]]:
    """Prevent Mine/Theirs rows with different Base identities from pairing.

    Pairwise Mine↔Theirs heuristics cannot express every three-way state.  The
    independently established Base maps are authoritative: rows mapped to
    different Base records, or a Base record paired with an independent
    insertion, must remain separate structural rows.  Independent insertions
    on both sides are merged only when exact row equality proves they are the
    same addition.
    """
    pairs = list(display_pairs or ())
    mine_map = mine_to_base or {}
    theirs_map = theirs_to_base or {}
    if not pairs or not mine_map or not theirs_map:
        return pairs

    independent_pairs = [
        (ra, rb)
        for ra, rb in pairs
        if (
            ra is not None
            and rb is not None
            and mine_map.get(ra) is None
            and theirs_map.get(rb) is None
        )
    ]
    width = max(1, int(max_col or 1))
    mine_rows = {}
    theirs_rows = {}
    if independent_pairs and ws_mine is not None and ws_theirs is not None:
        mine_rows = _read_rows_into_cache(
            ws_mine,
            [ra for ra, _rb in independent_pairs],
            width,
            require_complete=True,
        )
        theirs_rows = _read_rows_into_cache(
            ws_theirs,
            [rb for _ra, rb in independent_pairs],
            width,
            require_complete=True,
        )

    out: list[tuple[int | None, int | None]] = []
    for ra, rb in pairs:
        if ra is None or rb is None:
            out.append((ra, rb))
            continue
        base_mine = mine_map.get(ra)
        base_theirs = theirs_map.get(rb)
        if base_mine is not None and base_theirs is not None:
            if base_mine == base_theirs:
                out.append((ra, rb))
            elif int(base_mine) < int(base_theirs):
                out.extend(((ra, None), (None, rb)))
            else:
                out.extend(((None, rb), (ra, None)))
            continue
        if (base_mine is None) != (base_theirs is None):
            out.extend(((None, rb), (ra, None)))
            continue

        rows_proven_equal = False
        if mine_rows and theirs_rows:
            mine_signature = _row_signature(
                _row_from_cache(mine_rows, ra, width)
            )
            theirs_signature = _row_signature(
                _row_from_cache(theirs_rows, rb, width)
            )
            rows_proven_equal = mine_signature == theirs_signature
        if rows_proven_equal:
            out.append((ra, rb))
        else:
            out.extend(((None, rb), (ra, None)))
    return out


def _split_tail_independent_append_pairs(
    display_pairs: list[tuple[int | None, int | None]],
    mine_to_base: dict[int, int] | None,
    theirs_to_base: dict[int, int] | None,
    ws_mine=None,
    ws_theirs=None,
    max_col: int | None = None,
) -> list[tuple[int | None, int | None]]:
    """Split safe 3-way tail append pairs into independent theirs/mine blocks.

    Conservative rule:
    - only consider pairs where both mine/theirs rows exist
    - neither row maps to base
    - both rows are strictly after their respective last mapped base row
    - require each side to have at least one mapped base row first

    Output order is fixed as: theirs block first, mine block second.
    """
    pairs = list(display_pairs or [])
    if not pairs:
        return pairs
    mine_map = mine_to_base or {}
    theirs_map = theirs_to_base or {}
    if not mine_map or not theirs_map:
        return pairs
    try:
        last_mine_mapped = max(int(r) for r in mine_map.keys() if r is not None)
        last_theirs_mapped = max(int(r) for r in theirs_map.keys() if r is not None)
    except Exception:
        return pairs

    candidate_rows: list[tuple[int, int, int]] = []
    for idx, (ra, rb) in enumerate(pairs):
        if ra is None or rb is None:
            continue
        if ra in mine_map or rb in theirs_map:
            continue
        if int(ra) <= last_mine_mapped or int(rb) <= last_theirs_mapped:
            continue
        candidate_rows.append((idx, int(ra), int(rb)))

    split_indices: set[int] = set()
    if candidate_rows:
        mine_rows = {}
        theirs_rows = {}
        if ws_mine is not None and ws_theirs is not None and max_col:
            # A read_only worksheet may parse from the start of its XML stream for
            # every high-row iter_rows() call. Read all candidate rows once per
            # side so multiple tail appends stay linear rather than O(rows * XML).
            mine_rows = _read_rows_into_cache(
                ws_mine,
                [ra for _idx, ra, _rb in candidate_rows],
                int(max_col),
                require_complete=True,
            )
            theirs_rows = _read_rows_into_cache(
                ws_theirs,
                [rb for _idx, _ra, rb in candidate_rows],
                int(max_col),
                require_complete=True,
            )
        for idx, ra, rb in candidate_rows:
            # Identical independent appends are one logical row, not two
            # competing blocks. If equality cannot be proven, retain the
            # conservative split.
            if mine_rows and theirs_rows:
                mine_sig = _row_signature(_row_from_cache(mine_rows, ra, int(max_col)))
                theirs_sig = _row_signature(_row_from_cache(theirs_rows, rb, int(max_col)))
                if mine_sig == theirs_sig:
                    continue
            split_indices.add(idx)

    out: list[tuple[int | None, int | None]] = []
    if split_indices:
        idx = 0
        while idx < len(pairs):
            if idx not in split_indices:
                out.append(pairs[idx])
                idx += 1
                continue
            end = idx
            while end + 1 < len(pairs) and (end + 1) in split_indices:
                end += 1
            # Keep the agreed deterministic order for an independent tail block:
            # all theirs rows first, followed by all mine rows.
            out.extend((None, pairs[pos][1]) for pos in range(idx, end + 1))
            out.extend((pairs[pos][0], None) for pos in range(idx, end + 1))
            idx = end + 1
    else:
        out = list(pairs)

    # High-confidence row identities can already split independent additions
    # before this helper runs. Normalize a terminal one-sided independent run
    # as well, otherwise the result order depends on the pairwise DP tie-break.
    suffix_start = len(out)
    while suffix_start > 0:
        ra, rb = out[suffix_start - 1]
        if (ra is None) == (rb is None):
            break
        if ra is not None:
            if ra in mine_map or int(ra) <= last_mine_mapped:
                break
        else:
            if rb in theirs_map or int(rb) <= last_theirs_mapped:
                break
        suffix_start -= 1
    suffix = out[suffix_start:]
    if (
        suffix
        and any(ra is not None for ra, _rb in suffix)
        and any(rb is not None for _ra, rb in suffix)
    ):
        theirs_suffix = [(None, rb) for _ra, rb in suffix if rb is not None]
        mine_suffix = [(ra, None) for ra, _rb in suffix if ra is not None]
        out[suffix_start:] = theirs_suffix + mine_suffix
    return out


def _split_low_similarity_tail_pairs(
    display_pairs: list[tuple[int | None, int | None]],
    mine_to_base: dict[int, int] | None,
    theirs_to_base: dict[int, int] | None,
    ws_mine,
    ws_theirs,
    max_col: int,
    *,
    sim_threshold: float = 0.75,
) -> list[tuple[int | None, int | None]]:
    """Split misaligned tail pairs before a mapped one-sided tail block.

    Conservative rule:
    - only consider the very end of the sheet
    - require a trailing mapped one-sided block on one side
    - only split immediately preceding paired rows that map to the matching
      base rows but have low row similarity

    This preserves exact behavior for the body of the sheet while allowing
    "local tail append vs remote tail append" cases to stay visible as
    independent rows in 3-way mode.
    """
    pairs = list(display_pairs or [])
    mine_map = mine_to_base or {}
    theirs_map = theirs_to_base or {}
    if not pairs or not mine_map or not theirs_map:
        return pairs

    def _row_sim_cache(ws_a, rows_a, ws_b, rows_b):
        rows_a_cache = _read_rows_into_cache(ws_a, rows_a, max_col)
        rows_b_cache = _read_rows_into_cache(ws_b, rows_b, max_col)
        sim_cache: dict[tuple[int, int], float] = {}
        for ra, rb in zip(rows_a, rows_b):
            row_a = _row_from_cache(rows_a_cache, ra, max_col)
            row_b = _row_from_cache(rows_b_cache, rb, max_col)
            sig_a = _row_signature(row_a)
            sig_b = _row_signature(row_b)
            if sig_a == sig_b:
                sim_cache[(ra, rb)] = 2.0
                continue
            if (not sig_a) or (not sig_b):
                sim_cache[(ra, rb)] = 0.0
                continue
            try:
                sim_cache[(ra, rb)] = difflib.SequenceMatcher(a=sig_a, b=sig_b, autojunk=False).ratio()
            except Exception:
                sim_cache[(ra, rb)] = 0.0
        return sim_cache

    def _split_one_side(
        cur_pairs: list[tuple[int | None, int | None]],
        *,
        trailing_side: str,
    ) -> list[tuple[int | None, int | None]]:
        if trailing_side == "B":
            trailing_idx = 1
            lead_idx = 0
            trailing_map = theirs_map
            lead_map = mine_map
        else:
            trailing_idx = 0
            lead_idx = 1
            trailing_map = mine_map
            lead_map = theirs_map

        cursor = len(cur_pairs) - 1
        suffix_start = len(cur_pairs)
        found_one_sided = False
        candidate_rows_a: list[int] = []
        candidate_rows_b: list[int] = []
        candidate_idx_pairs: list[tuple[int, int, int]] = []
        while cursor >= 0:
            pair = cur_pairs[cursor]
            lead_row = pair[lead_idx]
            trail_row = pair[trailing_idx]
            if lead_row is None and trail_row is not None:
                base_row = trailing_map.get(trail_row)
                if base_row is None:
                    break
                found_one_sided = True
                suffix_start = cursor
                cursor -= 1
                continue
            ra, rb = pair
            if ra is None or rb is None:
                break
            base_a = mine_map.get(ra)
            base_b = theirs_map.get(rb)
            if base_a is None or base_b is None or base_a != base_b:
                break
            candidate_rows_a.append(ra)
            candidate_rows_b.append(rb)
            candidate_idx_pairs.append((cursor, ra, rb))
            suffix_start = cursor
            cursor -= 1
        if (not found_one_sided) or (not candidate_idx_pairs):
            return cur_pairs

        sim_cache = _row_sim_cache(ws_mine, candidate_rows_a, ws_theirs, candidate_rows_b)

        split_indices: set[int] = set()
        for global_idx, ra, rb in sorted(candidate_idx_pairs, key=lambda x: x[0], reverse=True):
            if sim_cache.get((ra, rb), 0.0) >= sim_threshold:
                break
            split_indices.add(global_idx)
        if not split_indices:
            return cur_pairs

        out: list[tuple[int | None, int | None]] = list(cur_pairs[:suffix_start])
        seen_one_sided = False
        for global_idx in range(suffix_start, len(cur_pairs)):
            ra, rb = cur_pairs[global_idx]
            lead_row = cur_pairs[global_idx][lead_idx]
            trail_row = cur_pairs[global_idx][trailing_idx]
            if lead_row is None and trail_row is not None:
                out.append(cur_pairs[global_idx])
                seen_one_sided = True
                continue
            if global_idx not in split_indices:
                out.append(cur_pairs[global_idx])
                continue
            if trailing_side == "B":
                if seen_one_sided:
                    out.append((ra, None))
                    out.append((None, rb))
                else:
                    out.append((None, rb))
                    out.append((ra, None))
            else:
                if seen_one_sided:
                    out.append((None, rb))
                    out.append((ra, None))
                else:
                    out.append((ra, None))
                    out.append((None, rb))
        return out

    pairs = _split_one_side(pairs, trailing_side="B")
    pairs = _split_one_side(pairs, trailing_side="A")
    return pairs


def _build_pair_base_row_overrides(
    row_pairs: list[tuple[int | None, int | None]],
    mine_to_base: dict[int, int] | None,
    theirs_to_base: dict[int, int] | None,
    ws_base,
    ws_mine,
    ws_theirs,
    max_col: int,
    *,
    sim_delta: float = 0.05,
) -> dict[int, int | None]:
    """Choose which side should own the base row for adjacent split pairs."""
    pairs = list(row_pairs or [])
    mine_map = mine_to_base or {}
    theirs_map = theirs_to_base or {}
    if (not pairs) or ws_base is None or (not mine_map and not theirs_map):
        return {}

    twin_specs: list[tuple[int, int, int, int, int]] = []
    base_rows_needed: set[int] = set()
    mine_rows_needed: set[int] = set()
    theirs_rows_needed: set[int] = set()

    for idx in range(len(pairs) - 1):
        p1 = pairs[idx]
        p2 = pairs[idx + 1]
        base_1 = mine_map.get(p1[0]) if p1[0] is not None else theirs_map.get(p1[1]) if p1[1] is not None else None
        base_2 = mine_map.get(p2[0]) if p2[0] is not None else theirs_map.get(p2[1]) if p2[1] is not None else None
        if base_1 is None or base_2 is None or base_1 != base_2:
            continue
        if p1[0] is None and p1[1] is not None and p2[0] is not None and p2[1] is None:
            theirs_pair_idx, mine_pair_idx = idx, idx + 1
            theirs_row, mine_row = p1[1], p2[0]
        elif p1[0] is not None and p1[1] is None and p2[0] is None and p2[1] is not None:
            mine_pair_idx, theirs_pair_idx = idx, idx + 1
            mine_row, theirs_row = p1[0], p2[1]
        else:
            continue
        twin_specs.append((mine_pair_idx, theirs_pair_idx, mine_row, theirs_row, base_1))
        base_rows_needed.add(base_1)
        mine_rows_needed.add(mine_row)
        theirs_rows_needed.add(theirs_row)

    if not twin_specs:
        return {}

    rows_base = _read_rows_into_cache(ws_base, sorted(base_rows_needed), max_col)
    rows_mine = _read_rows_into_cache(ws_mine, sorted(mine_rows_needed), max_col)
    rows_theirs = _read_rows_into_cache(ws_theirs, sorted(theirs_rows_needed), max_col)

    def _sim_against_base(side_cache, side_row: int, base_row: int) -> float:
        row_side = _row_from_cache(side_cache, side_row, max_col)
        row_base = _row_from_cache(rows_base, base_row, max_col)
        sig_side = "\x1f".join(_merge_cmp_value(v) for v in row_side)
        sig_base = "\x1f".join(_merge_cmp_value(v) for v in row_base)
        if sig_side == sig_base:
            return 2.0
        if (not sig_side) or (not sig_base):
            return 0.0
        try:
            return difflib.SequenceMatcher(a=sig_side, b=sig_base, autojunk=False).ratio()
        except Exception:
            return 0.0

    overrides: dict[int, int | None] = {}
    for mine_pair_idx, theirs_pair_idx, mine_row, theirs_row, base_row in twin_specs:
        sim_mine = _sim_against_base(rows_mine, mine_row, base_row)
        sim_theirs = _sim_against_base(rows_theirs, theirs_row, base_row)
        if abs(sim_mine - sim_theirs) < sim_delta:
            continue
        if sim_mine > sim_theirs:
            overrides[mine_pair_idx] = base_row
            overrides[theirs_pair_idx] = None
        else:
            overrides[mine_pair_idx] = None
            overrides[theirs_pair_idx] = base_row
    return overrides


def _copy_sheet_basic(src_ws, dst_ws):
    """Copy enough worksheet structure for merge/save fallback paths."""
    for row in src_ws.iter_rows():
        for src_cell in row:
            try:
                dst_cell = dst_ws.cell(row=src_cell.row, column=src_cell.column)
                src_value = src_cell.value
                if src_cell.data_type == "s" and isinstance(src_value, str) and src_value.startswith("="):
                    src_value = _LiteralText(src_value)
                _assign_edit_cell_value(dst_cell, src_value)
                if src_cell.has_style:
                    dst_cell._style = copy.copy(src_cell._style)
                if src_cell.number_format:
                    dst_cell.number_format = src_cell.number_format
                if src_cell.font:
                    dst_cell.font = copy.copy(src_cell.font)
                if src_cell.fill:
                    dst_cell.fill = copy.copy(src_cell.fill)
                if src_cell.border:
                    dst_cell.border = copy.copy(src_cell.border)
                if src_cell.alignment:
                    dst_cell.alignment = copy.copy(src_cell.alignment)
                if src_cell.protection:
                    dst_cell.protection = copy.copy(src_cell.protection)
                if src_cell.comment is not None:
                    dst_cell.comment = copy.copy(src_cell.comment)
                if src_cell.hyperlink is not None:
                    dst_cell._hyperlink = copy.copy(src_cell.hyperlink)
            except Exception as exc:
                raise RuntimeError(
                    f"复制 Sheet 单元格失败：{src_ws.title}!{src_cell.coordinate}: {exc}"
                ) from exc
    try:
        for key, dim in src_ws.row_dimensions.items():
            dst_ws.row_dimensions[key] = copy.copy(dim)
    except Exception:
        pass
    try:
        for key, dim in src_ws.column_dimensions.items():
            dst_ws.column_dimensions[key] = copy.copy(dim)
    except Exception:
        pass
    try:
        for merged in list(src_ws.merged_cells.ranges):
            dst_ws.merge_cells(str(merged))
    except Exception:
        pass
    for attr in (
        "sheet_format",
        "sheet_properties",
        "sheet_view",
        "views",
        "page_margins",
        "page_setup",
        "print_options",
        "sheet_state",
    ):
        try:
            setattr(dst_ws, attr, copy.copy(getattr(src_ws, attr)))
        except Exception:
            pass
    try:
        dst_ws.freeze_panes = src_ws.freeze_panes
    except Exception:
        pass
    try:
        dst_ws.auto_filter = copy.copy(src_ws.auto_filter)
    except Exception:
        pass
    try:
        dst_ws.data_validations = copy.deepcopy(src_ws.data_validations)
    except Exception:
        pass
    try:
        dst_ws.conditional_formatting._cf_rules = copy.deepcopy(
            src_ws.conditional_formatting._cf_rules
        )
    except Exception:
        pass


def _remove_sheet_if_exists(wb, sheet_name: str):
    if wb is None or (not sheet_name):
        return False
    if sheet_name not in wb.sheetnames:
        return False
    wb.remove(wb[sheet_name])
    return True


def _create_sheet_from_source(dst_wb, src_ws, title: str, index: int | None = None):
    if dst_wb is None or src_ws is None or not title:
        return None
    if title in dst_wb.sheetnames:
        _remove_sheet_if_exists(dst_wb, title)
    if index is None:
        dst_ws = dst_wb.create_sheet(title=title)
    else:
        dst_ws = dst_wb.create_sheet(title=title, index=max(0, int(index)))
    _copy_sheet_basic(src_ws, dst_ws)
    return dst_ws


def _copy_row_metadata(src_ws, dst_ws, src_row: int, dst_row: int, max_col: int):
    """Copy row/cell presentation metadata without changing cell values."""
    if src_ws is None or dst_ws is None:
        return
    src_row = int(src_row)
    dst_row = int(dst_row)
    for col in range(1, max(1, int(max_col)) + 1):
        src_cell = src_ws.cell(row=src_row, column=col)
        dst_cell = dst_ws.cell(row=dst_row, column=col)
        if src_cell.has_style:
            dst_cell._style = copy.copy(src_cell._style)
        if src_cell.comment is not None:
            dst_cell.comment = copy.copy(src_cell.comment)
        if src_cell.hyperlink is not None:
            dst_cell._hyperlink = copy.copy(src_cell.hyperlink)
    src_dim = src_ws.row_dimensions.get(src_row)
    if src_dim is not None:
        dst_dim = copy.copy(src_dim)
        try:
            dst_dim.index = dst_row
        except Exception:
            pass
        dst_ws.row_dimensions[dst_row] = dst_dim


def _capture_worksheet_rows(ws, start_row: int, count: int):
    """Capture values and presentation metadata for an in-memory row-delete undo."""
    start_row = max(1, int(start_row))
    count = max(1, int(count))
    max_col = max(1, int(getattr(ws, "max_column", 1) or 1))
    captured_rows = []
    for row_idx in range(start_row, start_row + count):
        cells = []
        for col_idx in range(1, max_col + 1):
            cell = ws.cell(row=row_idx, column=col_idx)
            cells.append({
                "value": cell.value,
                "style": copy.copy(cell._style),
                "comment": copy.copy(cell.comment) if cell.comment is not None else None,
                "hyperlink": copy.copy(cell.hyperlink) if cell.hyperlink is not None else None,
            })
        row_dim = ws.row_dimensions.get(row_idx)
        captured_rows.append({
            "cells": cells,
            "row_dimension": copy.copy(row_dim) if row_dim is not None else None,
        })
    return {
        "start_row": start_row,
        "count": count,
        "max_col": max_col,
        "rows": captured_rows,
    }


def _restore_captured_worksheet_rows(ws, snapshot):
    """Reinsert rows previously captured by :func:`_capture_worksheet_rows`."""
    snapshot = dict(snapshot or {})
    start_row = max(1, int(snapshot.get("start_row", 1) or 1))
    count = max(1, int(snapshot.get("count", 1) or 1))
    rows = list(snapshot.get("rows") or [])
    ws.insert_rows(idx=start_row, amount=count)
    for offset, row_state in enumerate(rows[:count]):
        row_idx = start_row + offset
        for col_idx, cell_state in enumerate(list(row_state.get("cells") or []), start=1):
            cell = ws.cell(row=row_idx, column=col_idx)
            _assign_edit_cell_value(cell, cell_state.get("value"))
            style = cell_state.get("style")
            if style is not None:
                cell._style = copy.copy(style)
            comment = cell_state.get("comment")
            cell.comment = copy.copy(comment) if comment is not None else None
            hyperlink = cell_state.get("hyperlink")
            cell._hyperlink = copy.copy(hyperlink) if hyperlink is not None else None
        row_dim = row_state.get("row_dimension")
        if row_dim is not None:
            restored_dim = copy.copy(row_dim)
            try:
                restored_dim.index = row_idx
            except Exception:
                pass
            ws.row_dimensions[row_idx] = restored_dim


def _val_to_str(v):
    """Render a cell value as single-line text for the Text widget.

    IMPORTANT: We must keep each Excel row rendered as exactly ONE line in tk.Text.
    So we sanitize embedded newlines/tabs that would otherwise break line alignment
    and cause diff highlights to drift.
    """
    if v is None:
        return ""
    s = str(v)
    # Normalize line breaks and tabs to keep one-row-per-line invariant
    s = s.replace("\r\n", " ").replace("\r", " ").replace("\n", " ")
    s = s.replace("\t", "    ")
    return s


def _format_cell(val_str: str, width: int) -> str:
    """Render one grid cell at exactly ``width`` display cells and Tk indices.

    Every two-cell glyph is followed by a zero-width placeholder.  Thus a CJK
    glyph occupies two display cells *and* two Tk character indices, preserving
    the fixed logical-column spans used by hit testing and highlights.  NFC
    resolves common base-plus-combining input before formatting.  Remaining
    combining marks and raw U+200B input become visible ASCII escapes: they
    retain the original code point without adding a zero-width Tk index to the
    grid.  The only actual U+200B characters in the output are generated by
    this formatter after a two-cell glyph.
    """
    try:
        width = max(0, int(width))
    except (TypeError, ValueError):
        width = 0
    if width == 0:
        return ""

    normalized = unicodedata.normalize("NFC", str(val_str or ""))
    tokens: list[tuple[str, int]] = []
    used = 0
    for char in normalized:
        # Input U+200B is user data, not one of our output placeholders.
        # Expose it rather than silently hiding a meaningful invisible diff.
        if char == _TK_INDEX_PLACEHOLDER:
            escaped = f"{chr(92)}u{ord(char):04X}"
            tokens.append((escaped, len(escaped)))
            used += len(escaped)
            continue
        char_width = _display_cell_width(char)
        if char_width == 0:
            if unicodedata.combining(char):
                # NFC cannot compose every possible mark sequence.  A literal
                # escape is visibly auditable and has one ASCII grid cell per
                # Tk index, unlike silently retaining a zero-width character.
                escaped = f"{chr(92)}u{ord(char):04X}"
                tokens.append((escaped, len(escaped)))
                used += len(escaped)
            continue
        token = char + (_TK_INDEX_PLACEHOLDER if char_width == 2 else "")
        tokens.append((token, char_width))
        used += char_width

    if used > width:
        # U+2026 is East-Asian ambiguous and therefore a two-cell glyph under
        # this grid model.  A one-cell field still gets a visible truncation
        # marker without violating its fixed Tk index length.
        ellipsis = "." if width == 1 else "…" + _TK_INDEX_PLACEHOLDER
        ellipsis_width = 1 if width == 1 else 2
        content_width = width - ellipsis_width
        parts: list[str] = []
        used = 0
        for token, token_width in tokens:
            if used + token_width > content_width:
                break
            parts.append(token)
            used += token_width
        return "".join(parts) + ellipsis + (" " * (content_width - used))

    return "".join(token for token, _ in tokens) + (" " * (width - used))


def _display_cell_width(char: str) -> int:
    """Return the fixed grid width for one Unicode code point."""
    if not char or unicodedata.combining(char):
        return 0
    east_asian_width = unicodedata.east_asian_width(char)
    if east_asian_width in ("F", "W"):
        return 2
    if east_asian_width != "A":
        return 1

    # 新宋体 11 renders accented Latin letters and these compact trademark
    # symbols at the one-cell ASCII advance even though Unicode marks them
    # ambiguous.  Keep all other A characters wide: in particular U+2026
    # remains two cells, matching the truncation marker below.
    name = unicodedata.name(char, "")
    if "LATIN" in name or char in ("™", "®"):
        return 1
    return 2


def _excel_column_display(logical_col: int) -> str:
    """Return a user-facing logical column as an Excel label (A, Z, AA...)."""
    try:
        return get_column_letter(max(1, int(logical_col)))
    except (TypeError, ValueError):
        return "?"


def _excel_column_range_display(start_col: int, end_col: int | None = None) -> str:
    """Return an inclusive user-facing logical column range in Excel notation."""
    start = _excel_column_display(start_col)
    end = _excel_column_display(start_col if end_col is None else end_col)
    return start if start == end else f"{start}:{end}"


def _should_auto_row_align(max_row_a: int, max_row_b: int, force: bool = False) -> bool:
    """Auto-enable row alignment when it prevents cascading false diffs.

    Row counts can remain equal when one side inserts a row and deletes another, so
    count equality is not evidence that raw row-number comparison is safe. Align all
    sheets under the soft limit and leave larger sheets to their dedicated block/tail
    paths.
    """
    max_row = max(max_row_a, max_row_b)
    if max_row <= 0:
        return False
    if force:
        return True
    return max_row <= _ROW_ALIGN_SOFT_MAX_ROWS


def _effective_bounds(ws):
    """Return (max_row, max_col) using the true last non-empty row.

    Empty strings are treated as empty, so formulas returning "" do not keep a sheet
    artificially large. On read-only worksheets we avoid shrinking max_col from a
    single tail row because that can truncate real columns seen earlier in the sheet.
    """
    max_r, max_c = _worksheet_scan_bounds(ws)
    last_r = 1
    last_c = 1
    found = False
    found_via_cells = False
    try:
        cells = getattr(ws, "_cells", None)
        if cells:
            for cell in cells.values():
                v = cell.value
                if v not in (None, ""):
                    found = True
                    found_via_cells = True
                    if cell.row > last_r:
                        last_r = cell.row
                    if cell.column > last_c:
                        last_c = cell.column
    except Exception:
        pass
    if not found:
        try:
            for r in range(max_r, max(0, max_r - 5000), -1):
                row = next(ws.iter_rows(min_row=r, max_row=r, min_col=1, max_col=max_c, values_only=True), ())
                if any(v not in (None, "") for v in row):
                    found = True
                    last_r = r
                    break
        except Exception:
            pass
    if not found:
        return 1, max(1, max_c)
    if found_via_cells:
        # data_only mode can read uncached formula cells as None, which would
        # under-estimate columns when relying only on non-empty _cells.
        if _USE_CACHED_VALUES_ONLY and max_c > last_c:
            return max(1, last_r), max(1, max_c)
        if last_c <= 1 and max_c > last_c:
            return max(1, last_r), max(1, max_c)
        return max(1, last_r), max(1, last_c)
    # ReadOnlyWorksheet has no populated _cells mapping. The tail scan above
    # locates the last non-empty row, but it does not establish the widest
    # populated column across earlier rows, so keep the worksheet max_column.
    return max(1, last_r), max(1, max_c)


def _effective_bounds_with_edit(ws_val, ws_edit=None):
    """Include formula/literal cells whose data-only cache is empty."""
    val_row, val_col = _effective_bounds(ws_val)
    if ws_edit is None or ws_edit is ws_val:
        return val_row, val_col
    # Both workbooks are normal in-memory Worksheets on the interactive path.
    # Their XML dimension can include a large style-only tail (Guide is a
    # representative case: 19 populated columns but 33 styled columns).  The
    # initial background cache trims that tail, so a foreground rescan must use
    # the same semantic horizon or an insert/undo cycle appears to grow the
    # logical model.  The edit workbook sees formulas whose data-only cache can
    # be empty; taking the union of non-empty cells from both normal worksheets
    # is therefore exact without losing uncached formulas.
    def _populated_bounds_from_cells(ws):
        try:
            cells = getattr(ws, "_cells", None)
            if cells is None:
                return None
            populated = [
                cell for cell in cells.values()
                if getattr(cell, "value", None) not in (None, "")
            ]
            if not populated:
                return (1, 1)
            return (
                max(int(cell.row) for cell in populated),
                max(int(cell.column) for cell in populated),
            )
        except Exception:
            return None

    exact_val = _populated_bounds_from_cells(ws_val)
    exact_edit = _populated_bounds_from_cells(ws_edit)
    if exact_val is not None and exact_edit is not None:
        return (
            max(1, int(exact_val[0]), int(exact_edit[0])),
            max(1, int(exact_val[1]), int(exact_edit[1])),
        )
    try:
        edit_row, edit_col = _effective_bounds(ws_edit)
        return max(val_row, edit_row), max(val_col, edit_col)
    except Exception:
        return val_row, val_col
    return max(1, last_r), max(1, max_c)


def _save_values_only_from_wb(src_wb, target_path: str):
    """Fast save: values only, no styles. Drops formatting."""
    def _trim_bounds_ws(ws):
        # Find the true last non-empty row. Empty strings count as empty so formulas
        # returning "" do not keep trailing blank regions alive. Keep max_c for
        # read-only fallback paths so earlier populated columns are not truncated.
        max_r = ws.max_row or 1
        max_c = ws.max_column or 1
        last_r = 1
        last_c = 1
        found = False
        found_via_cells = False
        try:
            cells = getattr(ws, "_cells", None)
            if cells:
                for cell in cells.values():
                    v = cell.value
                    if v not in (None, ""):
                        found = True
                        found_via_cells = True
                        if cell.row > last_r:
                            last_r = cell.row
                        if cell.column > last_c:
                            last_c = cell.column
        except Exception:
            pass
        if not found:
            for r in range(max_r, max(0, max_r - 5000), -1):
                row = next(ws.iter_rows(min_row=r, max_row=r, min_col=1, max_col=max_c, values_only=True), ())
                if any(v not in (None, "") for v in row):
                    found = True
                    last_r = r
                    break
        if not found:
            return 1, max(1, max_c)
        if found_via_cells:
            # Keep columns conservative in cached-values mode to avoid losing
            # uncached formula columns when _cells appears sparse.
            if _USE_CACHED_VALUES_ONLY and max_c > last_c:
                return max(1, last_r), max(1, max_c)
            if last_c <= 1 and max_c > last_c:
                return max(1, last_r), max(1, max_c)
            return max(1, last_r), max(1, last_c)
        return max(1, last_r), max(1, max_c)

    dst = Workbook(write_only=True)
    # Remove default sheet
    try:
        if dst.sheetnames:
            dst.remove(dst[dst.sheetnames[0]])
    except Exception:
        pass
    for name in src_wb.sheetnames:
        ws_src = src_wb[name]
        ws_dst = dst.create_sheet(title=name)
        max_row, max_col = _trim_bounds_ws(ws_src)
        if max_row <= 0 or max_col <= 0:
            continue
        for row in ws_src.iter_rows(min_row=1, max_row=max_row, min_col=1, max_col=max_col, values_only=True):
            ws_dst.append(list(row))
    try:
        dst.save(target_path)
    finally:
        try:
            dst.close()
        except Exception:
            pass


def _capture_external_link_parts(xlsx_path: str):
    """Capture fragile package parts to preserve them across saves.

    Only activate this path when the workbook actually contains externalLinks parts.
    Capturing workbook/content-types metadata for every normal workbook can overwrite
    openpyxl's newly written package metadata and produce invalid archives.
    """
    if not xlsx_path or (not os.path.isfile(xlsx_path)):
        return None
    try:
        with zipfile.ZipFile(xlsx_path, "r") as zf:
            names = zf.namelist()
            target_names = set(
                n for n in names
                if n.startswith("xl/externalLinks/")
            )
            if not target_names:
                return None
            # workbook rels may carry externalLink relationship targets
            if "xl/_rels/workbook.xml.rels" in names:
                target_names.add("xl/_rels/workbook.xml.rels")
            # Preserve workbook/content-types metadata only for real external-link workbooks.
            if "xl/workbook.xml" in names:
                target_names.add("xl/workbook.xml")
            if "[Content_Types].xml" in names:
                target_names.add("[Content_Types].xml")
            parts = {n: zf.read(n) for n in target_names}
            _dlog(f"capture fragile parts: path={xlsx_path} count={len(parts)}")
            return parts
    except Exception:
        return None


def _restore_external_link_parts(xlsx_path: str, parts) -> int:
    """Restore captured fragile package parts into saved workbook."""
    if not parts:
        return 0
    if not xlsx_path or (not os.path.isfile(xlsx_path)):
        return 0
    try:
        with zipfile.ZipFile(xlsx_path, "r") as zf:
            names = zf.namelist()
            original_infos = {n: zf.getinfo(n) for n in names}
            all_bytes = {n: zf.read(n) for n in names}
    except Exception:
        return 0

    # Merge: keep all saved parts, overwrite/add captured external-link parts.
    for n, b in parts.items():
        all_bytes[n] = b

    # Keep package metadata internally consistent. Some originals carry a sharedStrings
    # override while openpyxl rewrites strings inline and omits xl/sharedStrings.xml.
    # If we restore the old [Content_Types].xml, add an empty sharedStrings part back.
    try:
        ct_name = "[Content_Types].xml"
        ct_bytes = all_bytes.get(ct_name)
        if ct_bytes is not None and "xl/sharedStrings.xml" not in all_bytes:
            ct_root = ET.fromstring(ct_bytes)
            for node in ct_root.iter():
                if node.tag.endswith('Override') and node.get('PartName') == '/xl/sharedStrings.xml':
                    all_bytes['xl/sharedStrings.xml'] = (
                        b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
                        b'<sst xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" count="0" uniqueCount="0"/>'
                    )
                    break
    except Exception as e:
        _dlog(f"fragile parts sharedStrings reconcile failed: {xlsx_path} err={e}")

    changed = len(parts)

    tmp = f"{xlsx_path}.extlinkrestore.{os.getpid()}.tmp"
    try:
        with zipfile.ZipFile(tmp, "w") as zf:
            for name in all_bytes.keys():
                info = original_infos.get(name)
                comp = info.compress_type if info else zipfile.ZIP_DEFLATED
                zf.writestr(name, all_bytes[name], compress_type=comp)
        os.replace(tmp, xlsx_path)
        _dlog(f"fragile parts restored: {xlsx_path} changed={changed}")
        return changed
    except Exception as e:
        _dlog(f"fragile parts restore failed: {xlsx_path} err={e}")
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return 0


def _apply_external_link_parts_on_file(path: str, external_link_parts=None):
    try:
        if path:
            _restore_external_link_parts(path, external_link_parts)
    except Exception as e:
        _dlog(f"apply fragile parts failed: path={path} err={e}")


def _cell_display_and_equal(ws_a_val, ws_b_val, ws_a_edit, ws_b_edit, r: int, c: int):
    va_val = ws_a_val.cell(row=r, column=c).value
    vb_val = ws_b_val.cell(row=r, column=c).value

    va_edit = ws_a_edit.cell(row=r, column=c).value if ws_a_edit is not None else None
    vb_edit = ws_b_edit.cell(row=r, column=c).value if ws_b_edit is not None else None
    return _cell_display_and_equal_from_values(va_val, vb_val, va_edit, vb_edit)


def _cell_display_from_values(v_val, v_edit=None):
    """Return one side's display value without running equality semantics.

    Rendering previously compared every cell with itself, which normalized the
    same formula twice before the real two-sided comparison immediately did it
    again.  This helper intentionally mirrors only the display half of that
    contract; formula/cache equality remains exclusively in the comparator.
    """
    if not _USE_CACHED_VALUES_ONLY:
        return v_val
    literal_formula_text = (
        isinstance(v_edit, str)
        and v_edit.startswith("=")
        and v_val == v_edit
    )
    special = None if literal_formula_text else _special_formula_signature(v_edit)
    formula = None if literal_formula_text else _formula_text(v_edit)
    if v_val is not None:
        return v_val
    if formula:
        return formula
    if special is not None:
        # Preserve the existing self-comparison display behavior for special
        # formulas whose data-only cache is absent.
        return None
    return v_edit


def _cell_display_and_equal_from_values(va_val, vb_val, va_edit=None, vb_edit=None):
    """Compare already-fetched cell values while preserving the existing fallback rules."""
    if _USE_CACHED_VALUES_ONLY:
        def _formula_identity(v_val, v_edit):
            if isinstance(v_edit, str) and v_edit.startswith("=") and v_val == v_edit:
                return None
            special = _special_formula_signature(v_edit)
            if special is not None:
                return ("SPECIAL", special)
            formula = _norm_formula_text(v_edit)
            return ("TEXT", formula) if formula else None

        # If cache missing but edit has a literal value, use it for display/compare.
        identity_a = _formula_identity(va_val, va_edit)
        identity_b = _formula_identity(vb_val, vb_edit)
        if va_val is None and va_edit is not None and identity_a is None:
            va_val = va_edit
        if vb_val is None and vb_edit is not None and identity_b is None:
            vb_val = vb_edit

        formula_a = _formula_text(va_edit) if identity_a is not None else None
        formula_b = _formula_text(vb_edit) if identity_b is not None else None

        # Formula structure is part of the cell value. Equal cached results do
        # not make different formulas (or formula-vs-literal) equivalent.
        if identity_a != identity_b and (identity_a is not None or identity_b is not None):
            display_a = va_val if va_val is not None else formula_a
            display_b = vb_val if vb_val is not None else formula_b
            return display_a, display_b, False

        # If both caches are missing, formula structure is the only available
        # evidence. Never collapse different formulas (or formula-vs-blank) into
        # an apparently equal pair of None values.
        if va_val is None and vb_val is None and (formula_a or formula_b):
            if identity_a is not None and identity_a == identity_b:
                return formula_a, formula_b, True
            return formula_a, formula_b, False

        # If cache missing on one side but both formulas are the same, treat as equal
        # and display the available value.
        if (va_val is None) != (vb_val is None) and identity_a is not None and identity_a == identity_b:
            v = va_val if va_val is not None else vb_val
            return v, v, True

        if va_val is None and formula_a:
            va_val = formula_a
        if vb_val is None and formula_b:
            vb_val = formula_b

        eq = (_merge_cmp_value(va_val) == _merge_cmp_value(vb_val))
        return va_val, vb_val, eq

    eq = (_merge_cmp_value(va_val) == _merge_cmp_value(vb_val))
    return va_val, vb_val, eq


def _pad_row_values(row_vals, max_col: int):
    row = tuple(row_vals or ())
    if len(row) >= max_col:
        return row[:max_col]
    return row + (None,) * (max_col - len(row))


def _worksheet_cached_physical_max_column(ws) -> int:
    """Return a normal Worksheet's physical horizon without repeated O(cells) scans.

    ``Worksheet.max_column`` recomputes ``max(_cells)`` on every access.  Row
    rendering calls this reader thousands of times, so using it inside the
    hot path made a medium Sheet spend seconds rescanning the same cell map.
    The map identity and size form a cheap conservative cache token; column
    actions replace/change that map or explicitly invalidate it before the
    next read.
    """
    cells = getattr(ws, "_cells", None)
    if cells is None or ws.__class__.__name__ == "ReadOnlyWorksheet":
        return max(1, int(getattr(ws, "max_column", 1) or 1))
    token = (id(cells), len(cells))
    if getattr(ws, "_sow_read_max_col_token", None) == token:
        return max(1, int(getattr(ws, "_sow_read_max_col", 1) or 1))
    try:
        width = max((int(key[1]) for key in cells), default=1)
    except Exception:
        width = max(1, int(getattr(ws, "max_column", 1) or 1))
    try:
        ws._sow_read_max_col_token = token
        ws._sow_read_max_col = max(1, int(width))
    except Exception:
        pass
    return max(1, int(width))


def _invalidate_worksheet_read_horizon(ws):
    for name in ("_sow_read_max_col_token", "_sow_read_max_col"):
        try:
            delattr(ws, name)
        except Exception:
            pass


def _read_rows_into_cache(
    ws,
    row_indices,
    max_col: int,
    *,
    require_complete: bool = False,
    cancel_check=None,
):
    """Read a set of rows via one contiguous iter_rows pass."""
    rows = {}
    try:
        needed = sorted({int(r) for r in row_indices if r is not None and int(r) > 0})
    except Exception:
        needed = []
    if not needed:
        return rows

    min_r = needed[0]
    max_r = needed[-1]
    needed_set = set(needed)
    # Normal openpyxl worksheets materialize cells when iter_rows is asked to
    # extend beyond the current physical horizon.  Logical projection often
    # requests the wider peer width, so cap the actual read and pad in memory;
    # otherwise a refresh can silently create an empty tail column on the
    # untouched side and make column-action undo non-idempotent.
    try:
        read_max_col = min(
            max(1, int(max_col)),
            _worksheet_cached_physical_max_column(ws),
        )
    except Exception:
        read_max_col = max(1, int(max_col))

    # A normal editable openpyxl Worksheet stores its sparse cells in `_cells`.
    # Calling iter_rows() over it creates Cell objects for every empty position
    # in the requested rectangle; a projection rebuild could therefore turn a
    # sparse real sheet into tens of thousands of persistent blank cells after
    # an otherwise exact column-action undo.  Direct dictionary reads are
    # in-memory only, preserve sparsity, and still build the same contiguous row
    # cache consumed by signature/comparison code.  ReadOnlyWorksheet has no
    # compatible sparse store and continues through the streaming path below.
    sparse_cells = getattr(ws, "_cells", None)
    if (
        isinstance(sparse_cells, dict)
        and str(getattr(ws.__class__, "__module__", "")).startswith("openpyxl.")
    ):
        for row_offset, row_idx in enumerate(needed):
            if cancel_check is not None and (row_offset & 127) == 0:
                cancel_check()
            values = []
            for col_idx in range(1, read_max_col + 1):
                cell = sparse_cells.get((row_idx, col_idx))
                values.append(
                    getattr(cell, "value", cell) if cell is not None else None
                )
            rows[row_idx] = _pad_row_values(values, max_col)
        return rows
    try:
        for idx, row in enumerate(
            ws.iter_rows(
                min_row=min_r,
                max_row=max_r,
                min_col=1,
                max_col=read_max_col,
                values_only=True,
            ),
            start=min_r,
        ):
            if cancel_check is not None and (idx & 127) == 0:
                cancel_check()
            if idx in needed_set:
                rows[idx] = _pad_row_values(row, max_col)
    except InterruptedError:
        raise
    except Exception:
        if require_complete:
            return {}

    if require_complete and any(r not in rows for r in needed):
        return {}
    for r in needed:
        rows.setdefault(r, (None,) * max_col)
    return rows


def _read_rows_into_shared_cache(
    ws,
    row_indices,
    max_col: int,
    *,
    cache_bundle: dict | None = None,
    cache_key=None,
):
    """Reuse one sequential worksheet read within a foreground refresh.

    The bundle is deliberately caller-owned and short-lived.  Worksheet
    identity, physical width, and row coverage are checked before reuse so a
    cache can never cross sheets, edit/value workbooks, or structural widths.
    """
    if ws is None:
        return {}
    try:
        needed = frozenset(
            int(row_idx)
            for row_idx in row_indices
            if row_idx is not None and int(row_idx) > 0
        )
    except Exception:
        needed = frozenset()
    if not needed:
        return {}
    width = max(1, int(max_col or 1))
    if cache_bundle is not None and cache_key is not None:
        entry = cache_bundle.get(cache_key)
        if (
            isinstance(entry, tuple)
            and len(entry) == 4
            and entry[0] is ws
            and entry[1] == width
            and needed.issubset(entry[2])
        ):
            return entry[3]
    rows = _read_rows_into_cache(ws, needed, width)
    if cache_bundle is not None and cache_key is not None:
        cache_bundle[cache_key] = (ws, width, needed, rows)
    return rows


def _row_from_cache(rows_cache: dict[int, tuple], row_idx: int | None, max_col: int):
    if row_idx is None:
        return (None,) * max_col
    return rows_cache.get(int(row_idx), (None,) * max_col)


@dataclass(frozen=True, slots=True)
class LogicalColumnComparisonCache:
    """Reusable pure-data column mapping for foreground/background replay.

    The cache owns the expensive signature/alignment result.  Row comparison,
    only-diff filtering, navigation, and conflict classification consume this
    immutable object and never need to revisit a Worksheet.
    """

    model: ColumnModel
    two_way_alignment: ColumnAlignmentResult | None = None
    three_way_alignment: ColumnAlignment3WayResult | None = None
    structural_diff_cols: frozenset[int] = frozenset()
    unresolved_cols: frozenset[int] = frozenset()

    def __post_init__(self):
        if not isinstance(self.model, ColumnModel):
            raise TypeError("logical comparison cache requires a ColumnModel")
        if self.two_way_alignment is not None and not isinstance(
            self.two_way_alignment, ColumnAlignmentResult
        ):
            raise TypeError("two_way_alignment must be ColumnAlignmentResult")
        if self.three_way_alignment is not None and not isinstance(
            self.three_way_alignment, ColumnAlignment3WayResult
        ):
            raise TypeError("three_way_alignment must be ColumnAlignment3WayResult")
        object.__setattr__(
            self, "structural_diff_cols", frozenset(int(c) for c in self.structural_diff_cols)
        )
        object.__setattr__(
            self, "unresolved_cols", frozenset(int(c) for c in self.unresolved_cols)
        )


_LOGICAL_COLUMN_PLACEHOLDER = "∅"
_LOGICAL_COLUMN_STATE_MARKERS = {
    "inserted": "+",
    "deleted": "−",
    "mine-deleted": "−",
    "theirs-deleted": "−",
    "both-deleted": "×",
    "unresolved": "?",
}

_COLUMN_ACTION_METADATA_SCOPE = (
    "values",
    "formulas",
    "column_dimensions",
    "styles",
    "comments",
    "hyperlinks",
    "data_validations",
    "merged_cells",
    "conditional_formatting",
)


@dataclass(frozen=True, slots=True)
class ColumnBlockActionPlan:
    """Fully validated, immutable plan for one logical column-block action."""

    action_id: str
    sheet: str
    block_ordinal: int
    logical_start: int
    logical_end: int
    source_side: str
    target_side: str
    source_physical_cols: tuple[int, ...]
    target_physical_cols: tuple[int, ...]
    target_physical_anchor: int
    count: int
    action_kind: str
    unresolved: bool = False
    metadata_scope: tuple[str, ...] = _COLUMN_ACTION_METADATA_SCOPE

    def __post_init__(self):
        if self.action_kind not in ("insert_copy", "delete", "copy", "retain"):
            raise ValueError(f"unknown column action kind: {self.action_kind!r}")
        if self.source_side not in ("A", "BASE", "B"):
            raise ValueError("source_side must be A, BASE, or B")
        if self.target_side not in ("A", "B"):
            raise ValueError("target_side must be A or B")
        if int(self.logical_start) <= 0 or int(self.logical_end) < int(self.logical_start):
            raise ValueError("invalid logical column range")
        if int(self.count) != int(self.logical_end) - int(self.logical_start) + 1:
            raise ValueError("column action count must match the logical range")
        if int(self.target_physical_anchor) <= 0:
            raise ValueError("target_physical_anchor must be positive")
        object.__setattr__(self, "source_physical_cols", tuple(int(v) for v in self.source_physical_cols))
        object.__setattr__(self, "target_physical_cols", tuple(int(v) for v in self.target_physical_cols))
        object.__setattr__(self, "metadata_scope", tuple(str(v) for v in self.metadata_scope))

    def operation_records(self) -> tuple[dict[str, object], ...]:
        """Return ordered replay records; 4.x will consume these natively."""
        common = {
            "sheet": self.sheet,
            "target_side": self.target_side,
            "target_logical_slot": self.logical_start,
            "target_physical_anchor": self.target_physical_anchor,
            "count": self.count,
            "source_side": self.source_side,
            "source_physical_cols": list(self.source_physical_cols),
            "metadata_scope": list(self.metadata_scope),
            "batch_id": self.action_id,
            "action_id": self.action_id,
        }
        if self.action_kind == "insert_copy":
            return (
                {**common, "kind": "insert_cols"},
                {**common, "kind": "copy_cols"},
            )
        if self.action_kind == "delete":
            return ({**common, "kind": "delete_cols"},)
        if self.action_kind == "copy":
            return ({**common, "kind": "copy_cols"},)
        return ()


def _normalize_logical_column_side(side: str) -> str:
    normalized = str(side or "").strip().lower()
    if normalized in ("a", "left", "mine"):
        return "mine"
    if normalized in ("base", "mid", "middle"):
        return "base"
    if normalized in ("b", "right", "theirs"):
        return "theirs"
    if normalized in ("logical", "slot", "c"):
        return "logical"
    raise ValueError(f"unknown logical column side: {side!r}")


@dataclass(frozen=True, slots=True)
class LogicalColumnProjection:
    """Shared render/interaction projection whose geometry is ``model.slots``.

    The projection deliberately does not copy or reorder slots.  Rendering,
    hit-testing, C-area actions and minimaps therefore consume one immutable
    logical geometry and only resolve a physical worksheet column at the last
    possible moment.
    """

    model: ColumnModel
    block_ordinal_by_slot: tuple[int, ...]

    def __post_init__(self):
        if not isinstance(self.model, ColumnModel):
            raise TypeError("logical projection requires a ColumnModel")
        ordinals = tuple(int(value) for value in self.block_ordinal_by_slot)
        if len(ordinals) != len(self.model.slots):
            raise ValueError("projection block lookup must match model.slots")
        object.__setattr__(self, "block_ordinal_by_slot", ordinals)

    @classmethod
    def from_model(cls, model: ColumnModel):
        block_by_slot = [-1] * len(model.slots)
        for block in model.blocks:
            for slot_idx in block.slot_indices:
                if 0 <= int(slot_idx) < len(block_by_slot):
                    block_by_slot[int(slot_idx)] = int(block.ordinal)
        return cls(model=model, block_ordinal_by_slot=tuple(block_by_slot))

    @property
    def slots(self) -> tuple[ColumnSlot, ...]:
        return self.model.slots

    @property
    def slot_count(self) -> int:
        return len(self.model.slots)

    def slot(self, logical_col: int) -> ColumnSlot | None:
        try:
            offset = int(logical_col) - 1
        except Exception:
            return None
        if 0 <= offset < len(self.model.slots):
            return self.model.slots[offset]
        return None

    def physical_col(self, side: str, logical_col: int) -> int | None:
        slot = self.slot(logical_col)
        if slot is None:
            return None
        normalized = _normalize_logical_column_side(side)
        if normalized == "logical":
            return int(logical_col)
        return _logical_model_side_col(slot, normalized)

    def logical_col(self, side: str, physical_col: int) -> int | None:
        normalized = _normalize_logical_column_side(side)
        if normalized == "logical":
            try:
                logical_col = int(physical_col)
            except Exception:
                return None
            return logical_col if self.slot(logical_col) is not None else None
        lookup = {
            "mine": self.model.mine_physical_to_logical,
            "base": self.model.base_physical_to_logical,
            "theirs": self.model.theirs_physical_to_logical,
        }[normalized]
        logical_idx = lookup.get(int(physical_col))
        return int(logical_idx) + 1 if logical_idx is not None else None

    def is_missing(self, side: str, logical_col: int) -> bool:
        return self.physical_col(side, logical_col) is None

    def structural_marker(self, side: str, logical_col: int) -> str:
        slot = self.slot(logical_col)
        if slot is None:
            return "?"
        normalized = _normalize_logical_column_side(side)
        if slot.state == "retained" and not slot.confidence.ambiguous:
            return ""
        if slot.confidence.ambiguous or slot.state == "unresolved":
            return "?"
        if normalized != "logical" and self.physical_col(normalized, logical_col) is None:
            return "∅"
        if slot.base_col is None and normalized in ("mine", "theirs"):
            return "+"
        return _LOGICAL_COLUMN_STATE_MARKERS.get(slot.state, "!")

    def structural_reason(self, side: str, logical_col: int) -> str:
        slot = self.slot(logical_col)
        if slot is None:
            return "logical-slot-missing"
        normalized = _normalize_logical_column_side(side)
        reasons = []
        if normalized != "logical" and self.physical_col(normalized, logical_col) is None:
            reasons.append(f"{normalized}-column-missing")
        if slot.state != "retained":
            reasons.append(slot.state)
        if slot.confidence.reason:
            reasons.append(slot.confidence.reason)
        reasons.extend(slot.confidence.cause_codes)
        if not reasons:
            reasons.append("retained-column")
        return "; ".join(dict.fromkeys(str(reason) for reason in reasons if reason))

    def header_label(self, side: str, logical_col: int) -> str:
        normalized = _normalize_logical_column_side(side)
        marker = self.structural_marker(normalized, logical_col)
        if normalized == "logical":
            # Logical-pane headers follow Excel's A..Z/AA convention too.
            # ``L<n>`` remains an internal/action identifier only; structural
            # markers are retained so C still exposes uncertain geometry.
            label = get_column_letter(int(logical_col))
        else:
            physical = self.physical_col(normalized, logical_col)
            label = get_column_letter(physical) if physical is not None else _LOGICAL_COLUMN_PLACEHOLDER
        return f"{marker}{label}" if marker and marker != label else label


@dataclass(frozen=True, slots=True)
class LogicalRowComparison:
    """Pure-data result for one logical 2-way row comparison."""

    diff_cols: frozenset[int]
    needs_formula_check: bool = False

    def __post_init__(self):
        object.__setattr__(self, "diff_cols", frozenset(int(c) for c in self.diff_cols))

    @property
    def has_diff(self) -> bool:
        return bool(self.diff_cols)


@dataclass(frozen=True, slots=True)
class LogicalThreeWayRowComparison:
    """Base-relative value/formula changes for one aligned logical row."""

    mine_changed_cols: frozenset[int]
    theirs_changed_cols: frozenset[int]
    conflict_cols: frozenset[int]

    def __post_init__(self):
        object.__setattr__(
            self, "mine_changed_cols", frozenset(int(c) for c in self.mine_changed_cols)
        )
        object.__setattr__(
            self, "theirs_changed_cols", frozenset(int(c) for c in self.theirs_changed_cols)
        )
        object.__setattr__(self, "conflict_cols", frozenset(int(c) for c in self.conflict_cols))


@dataclass(frozen=True, slots=True)
class LogicalColumnState:
    logical_col: int
    state: str
    mine_changed: bool = False
    theirs_changed: bool = False
    automatically_resolvable: bool = True


