@dataclass(frozen=True, slots=True)
class LogicalThreeWayColumnAnalysis:
    states: tuple[LogicalColumnState, ...]
    structural_conflicts: tuple[LogicalColumnStructuralConflict, ...]

    def __post_init__(self):
        object.__setattr__(self, "states", tuple(self.states))
        object.__setattr__(self, "structural_conflicts", tuple(self.structural_conflicts))

    @property
    def has_unresolved(self) -> bool:
        return bool(self.structural_conflicts)


def _logical_model_side_col(slot: ColumnSlot, side: str) -> int | None:
    side = str(side or "").lower()
    if side in ("a", "left", "mine"):
        return slot.mine_col
    if side == "base":
        return slot.base_col
    if side in ("b", "right", "theirs"):
        return slot.theirs_col
    raise ValueError(f"unknown logical column side: {side!r}")


def _logical_row_value(row_values, physical_col: int | None):
    """Read one mapped value without ever substituting another side's column."""
    if physical_col is None:
        return None
    values = row_values or ()
    offset = int(physical_col) - 1
    if offset < 0 or offset >= len(values):
        return None
    return values[offset]


def _logical_cell_has_content(value_row, edit_row, physical_col: int | None) -> bool:
    if physical_col is None:
        return False
    value = _logical_row_value(value_row, physical_col)
    edit = _logical_row_value(edit_row, physical_col)
    if value not in (None, ""):
        return True
    if edit in (None, ""):
        return False
    return bool(_formula_text(edit) or edit not in (None, ""))


def _logical_cell_payload(
    row_values,
    edit_values,
    physical_col: int,
    *,
    source_row: int | None,
    compare_row: int | None,
    logical_col: int,
    physical_to_logical=None,
):
    value = _logical_row_value(row_values, physical_col)
    edit = _logical_row_value(edit_values, physical_col)
    if source_row is not None and compare_row is not None:
        edit = _translate_normal_formula_for_compare(
            value,
            edit,
            int(source_row),
            int(physical_col),
            int(compare_row),
            int(physical_col),
        )
    return value, edit


@lru_cache(maxsize=2048)
def _one_based_formula_mapping(
    zero_based_entries: tuple[tuple[int, int], ...],
) -> FrozenIntLookup:
    """Cache an immutable physical→1-based-logical formula projection."""
    return FrozenIntLookup(tuple(
        (int(physical), int(logical_idx) + 1)
        for physical, logical_idx in zero_based_entries
    ))


def _formula_mapping_for_model_side(model: ColumnModel, side: str) -> FrozenIntLookup:
    normalized = _normalize_logical_column_side(side)
    lookup = {
        "mine": model.mine_physical_to_logical,
        "base": model.base_physical_to_logical,
        "theirs": model.theirs_physical_to_logical,
    }[normalized]
    return _one_based_formula_mapping(tuple(lookup.entries))


def build_logical_column_comparison_cache_2way(
    cache_key: ColumnModelCacheKey,
    mine_value_rows,
    theirs_value_rows,
    mine_edit_rows=None,
    theirs_edit_rows=None,
    *,
    mine_max_col: int | None = None,
    theirs_max_col: int | None = None,
) -> LogicalColumnComparisonCache:
    """Build a reusable 2-way mapping only from sequential in-memory rows."""
    mine_snapshot = build_column_signature_snapshot(
        cache_key,
        mine_value_rows,
        mine_edit_rows,
        max_col=mine_max_col,
    )
    theirs_snapshot = build_column_signature_snapshot(
        cache_key,
        theirs_value_rows,
        theirs_edit_rows,
        max_col=theirs_max_col,
    )
    alignment = align_column_signatures_2way(
        mine_snapshot,
        theirs_snapshot,
        cache_key=cache_key,
    )
    mine_width = max(0, int(mine_max_col or 0))
    theirs_width = max(0, int(theirs_max_col or 0))
    if mine_width > 0 and mine_width == theirs_width:
        width = mine_width

        def _first_row(rows):
            try:
                return tuple(rows[0]) if rows else ()
            except Exception:
                return ()

        def _header_token(value_row, edit_row, physical_col):
            value = _logical_row_value(value_row, physical_col)
            edit = _logical_row_value(edit_row, physical_col)
            formula = _formula_text(edit) or _special_formula_signature(edit)
            if formula is not None:
                return ("formula", formula)
            effective = value
            if effective is None and edit is not None and not _formula_text(edit):
                effective = edit
            if effective in (None, ""):
                return None
            return ("value", _merge_cmp_value(effective))

        mine_header = _first_row(mine_value_rows)
        theirs_header = _first_row(theirs_value_rows)
        mine_header_edit = _first_row(mine_edit_rows)
        theirs_header_edit = _first_row(theirs_edit_rows)
        mine_tokens = tuple(
            _header_token(mine_header, mine_header_edit, physical_col)
            for physical_col in range(1, width + 1)
        )
        theirs_tokens = tuple(
            _header_token(theirs_header, theirs_header_edit, physical_col)
            for physical_col in range(1, width + 1)
        )
        mine_unique = {
            token for token in mine_tokens
            if token is not None and mine_tokens.count(token) == 1
        }
        theirs_unique = {
            token for token in theirs_tokens
            if token is not None and theirs_tokens.count(token) == 1
        }

        def _same_ordinal_content_evidence(physical_col: int) -> bool:
            """Prove a same-width fallback column still shares real content.

            A normal cell edit can change the first sampled/header value and
            weaken a tiny column's signature.  One identical non-blank payload
            at the same ordinal proves this is not a wholly unrelated column,
            while blank/duplicate/formula-conflict causes remain blocked below.
            """
            row_count = max(
                len(mine_value_rows or ()),
                len(theirs_value_rows or ()),
                len(mine_edit_rows or ()),
                len(theirs_edit_rows or ()),
            )

            def _row(rows, index):
                try:
                    return rows[index]
                except (IndexError, TypeError):
                    return ()

            equal_count = 0
            different_count = 0
            for row_index in range(row_count):
                mine_value_row = _row(mine_value_rows, row_index)
                theirs_value_row = _row(theirs_value_rows, row_index)
                mine_edit_row = _row(mine_edit_rows, row_index)
                theirs_edit_row = _row(theirs_edit_rows, row_index)
                if not (
                    _logical_cell_has_content(
                        mine_value_row, mine_edit_row, physical_col
                    )
                    and _logical_cell_has_content(
                        theirs_value_row, theirs_edit_row, physical_col
                    )
                ):
                    continue
                mine_key = _merge_cell_compare_key(
                    _logical_row_value(mine_value_row, physical_col),
                    _logical_row_value(mine_edit_row, physical_col),
                )
                theirs_key = _merge_cell_compare_key(
                    _logical_row_value(theirs_value_row, physical_col),
                    _logical_row_value(theirs_edit_row, physical_col),
                )
                if mine_key == theirs_key:
                    equal_count += 1
                else:
                    different_count += 1
            # A lone coincidental default in an otherwise replaced column is
            # not enough.  Stable same-ordinal payloads must be at least as
            # numerous as differing comparable payloads.
            return equal_count > 0 and equal_count >= different_count

        normalized_slots = []
        changed = False
        for slot in alignment.model.slots:
            physical_col = slot.logical_idx + 1
            token = mine_tokens[physical_col - 1] if physical_col <= width else None
            single_column_same_ordinal = bool(
                width == 1
                and slot.mine_col == slot.theirs_col == physical_col == 1
            )
            can_promote = bool(
                slot.state == "unresolved"
                and slot.mine_col == slot.theirs_col == physical_col
                and (
                    single_column_same_ordinal
                    or (
                        token is not None
                        and token == theirs_tokens[physical_col - 1]
                        and token in mine_unique
                        and token in theirs_unique
                    )
                )
            )
            content_same_ordinal = bool(
                slot.state == "unresolved"
                and slot.mine_col == slot.theirs_col == physical_col
                and physical_col <= width
                and not (
                    set(slot.confidence.cause_codes)
                    & {
                        COLUMN_MAPPING_CAUSE_BLANK_COLUMN,
                        COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE,
                        COLUMN_MAPPING_CAUSE_FORMULA_MISMATCH,
                        COLUMN_MAPPING_CAUSE_INCOMPATIBLE_CACHE,
                        COLUMN_MAPPING_CAUSE_IMPLICIT_BOUNDARY,
                        COLUMN_MAPPING_CAUSE_COLUMN_LIMIT,
                    }
                )
                and _same_ordinal_content_evidence(physical_col)
            )
            can_promote = can_promote or content_same_ordinal
            if can_promote:
                normalized_slots.append(ColumnSlot(
                    logical_idx=slot.logical_idx,
                    mine_col=slot.mine_col,
                    base_col=slot.base_col,
                    theirs_col=slot.theirs_col,
                    state="retained",
                    confidence=ColumnMappingConfidence(
                        1.0,
                        False,
                        "single-column-same-ordinal"
                        if single_column_same_ordinal
                        else "same-ordinal-content-evidence"
                        if content_same_ordinal
                        else "unique-header-same-ordinal",
                        (
                            "content" if content_same_ordinal else "header",
                            "same-ordinal",
                        ),
                    ),
                    base_boundary=slot.base_boundary,
                    origin_side=slot.origin_side,
                ))
                changed = True
            else:
                normalized_slots.append(slot)
        if changed:
            normalized_slots = tuple(normalized_slots)
            remaining_fallback = tuple(
                slot.logical_idx
                for slot in normalized_slots
                if slot.state == "unresolved" or slot.confidence.ambiguous
            )
            normalized_model = ColumnModel.from_slots(
                cache_key,
                normalized_slots,
                blocks=_build_column_blocks(normalized_slots),
                confidence=ColumnMappingConfidence(
                    min((slot.confidence.score for slot in normalized_slots), default=1.0),
                    bool(remaining_fallback),
                    "unresolved-column-range" if remaining_fallback else "unique-header-same-ordinal",
                ),
            )
            alignment = ColumnAlignmentResult(
                normalized_model,
                alignment.anchor_pairs,
                remaining_fallback,
                bool(remaining_fallback),
                "unresolved-column-range" if remaining_fallback else "",
            )
    structural = frozenset(
        slot.logical_idx + 1
        for slot in alignment.model.slots
        if slot.mine_col is None or slot.theirs_col is None
    )
    unresolved = frozenset(
        slot.logical_idx + 1
        for slot in alignment.model.slots
        if slot.state == "unresolved" or slot.confidence.ambiguous
    )
    return LogicalColumnComparisonCache(
        model=alignment.model,
        two_way_alignment=alignment,
        structural_diff_cols=structural,
        unresolved_cols=unresolved,
    )


def build_logical_column_comparison_cache_3way(
    cache_key: ColumnModelCacheKey,
    mine_value_rows,
    base_value_rows,
    theirs_value_rows,
    mine_edit_rows=None,
    base_edit_rows=None,
    theirs_edit_rows=None,
    *,
    mine_max_col: int | None = None,
    base_max_col: int | None = None,
    theirs_max_col: int | None = None,
) -> LogicalColumnComparisonCache:
    """Build a Base-anchored reusable mapping from sequential row caches."""
    mine_snapshot = build_column_signature_snapshot(
        cache_key, mine_value_rows, mine_edit_rows, max_col=mine_max_col
    )
    base_snapshot = build_column_signature_snapshot(
        cache_key, base_value_rows, base_edit_rows, max_col=base_max_col
    )
    theirs_snapshot = build_column_signature_snapshot(
        cache_key, theirs_value_rows, theirs_edit_rows, max_col=theirs_max_col
    )
    alignment = align_column_signatures_3way(
        mine_snapshot,
        base_snapshot,
        theirs_snapshot,
        cache_key=cache_key,
    )

    # Row insertions can weaken full-column signatures even when the physical
    # column structure is unchanged.  Promote only the strongest conservative
    # cases when all three sides have the same width/order: either the unique
    # header identity agrees, or the complete value/formula digest agrees at
    # that ordinal on all three sides.  The latter safely handles identical
    # blank/duplicate columns without accepting a content-different mapping.
    widths = (
        max(0, int(mine_max_col or 0)),
        max(0, int(base_max_col or 0)),
        max(0, int(theirs_max_col or 0)),
    )
    if widths[0] > 0 and widths[0] == widths[1] == widths[2]:
        width = widths[0]

        def _first_row(rows):
            try:
                return tuple(rows[0]) if rows else ()
            except Exception:
                return ()

        def _header_token(value_row, edit_row, physical_col):
            value = _logical_row_value(value_row, physical_col)
            edit = _logical_row_value(edit_row, physical_col)
            formula = _formula_text(edit) or _special_formula_signature(edit)
            if formula is not None:
                return ("formula", formula)
            effective = value
            if effective is None and edit is not None and not _formula_text(edit):
                effective = edit
            if effective in (None, ""):
                return None
            return ("value", _merge_cmp_value(effective))

        mine_header = _first_row(mine_value_rows)
        base_header = _first_row(base_value_rows)
        theirs_header = _first_row(theirs_value_rows)
        mine_header_edit = _first_row(mine_edit_rows)
        base_header_edit = _first_row(base_edit_rows)
        theirs_header_edit = _first_row(theirs_edit_rows)
        side_tokens = []
        for value_row, edit_row in (
            (mine_header, mine_header_edit),
            (base_header, base_header_edit),
            (theirs_header, theirs_header_edit),
        ):
            side_tokens.append(tuple(
                _header_token(value_row, edit_row, physical_col)
                for physical_col in range(1, width + 1)
            ))
        unique_tokens = [
            {
                token
                for token in tokens
                if token is not None and tokens.count(token) == 1
            }
            for tokens in side_tokens
        ]
        normalized_slots = []
        changed = False
        for slot in alignment.model.slots:
            physical_col = slot.logical_idx + 1
            exact_same_ordinal = False
            if (
                physical_col <= width
                and slot.mine_col == slot.base_col == slot.theirs_col == physical_col
            ):
                mine_signature = mine_snapshot.signatures[physical_col - 1]
                base_signature = base_snapshot.signatures[physical_col - 1]
                theirs_signature = theirs_snapshot.signatures[physical_col - 1]
                exact_same_ordinal = bool(
                    mine_signature.exact_content_key
                    and mine_signature.exact_content_key
                    == base_signature.exact_content_key
                    == theirs_signature.exact_content_key
                )
            single_column_same_ordinal = bool(
                width == 1
                and slot.mine_col == slot.base_col == slot.theirs_col == physical_col == 1
            )
            can_promote = bool(
                slot.state == "unresolved"
                and slot.mine_col == slot.base_col == slot.theirs_col == physical_col
                and physical_col <= width
            )
            if can_promote and not (
                single_column_same_ordinal or exact_same_ordinal
            ):
                token = side_tokens[0][physical_col - 1]
                can_promote = bool(
                    token is not None
                    and token == side_tokens[1][physical_col - 1]
                    and token == side_tokens[2][physical_col - 1]
                    and all(token in tokens for tokens in unique_tokens)
                )
            if can_promote:
                normalized_slots.append(ColumnSlot(
                    logical_idx=slot.logical_idx,
                    mine_col=slot.mine_col,
                    base_col=slot.base_col,
                    theirs_col=slot.theirs_col,
                    state="retained",
                    confidence=ColumnMappingConfidence(
                        1.0,
                        False,
                        "single-column-same-ordinal"
                        if single_column_same_ordinal
                        else "exact-content-same-ordinal"
                        if exact_same_ordinal
                        else "unique-header-same-ordinal",
                        (
                            "exact-full-column-content"
                            if exact_same_ordinal else "header",
                            "same-ordinal",
                        ),
                    ),
                    base_boundary=slot.base_boundary,
                    origin_side=slot.origin_side,
                ))
                changed = True
            else:
                normalized_slots.append(slot)
        if changed:
            normalized_slots = tuple(normalized_slots)
            remaining_fallback = tuple(
                slot.logical_idx
                for slot in normalized_slots
                if slot.state == "unresolved" or slot.confidence.ambiguous
            )
            normalized_model = ColumnModel.from_slots(
                cache_key,
                normalized_slots,
                blocks=_build_column_blocks(normalized_slots),
                confidence=ColumnMappingConfidence(
                    min((slot.confidence.score for slot in normalized_slots), default=1.0),
                    bool(remaining_fallback),
                    "unresolved-column-range" if remaining_fallback else "unique-header-same-ordinal",
                ),
            )
            alignment = ColumnAlignment3WayResult(
                normalized_model,
                alignment.mine_to_base,
                alignment.theirs_to_base,
                remaining_fallback,
                bool(remaining_fallback),
                "unresolved-column-range" if remaining_fallback else "",
            )
    structural = frozenset(
        slot.logical_idx + 1
        for slot in alignment.model.slots
        if slot.mine_col is None or slot.theirs_col is None
    )
    unresolved = frozenset(
        slot.logical_idx + 1
        for slot in alignment.model.slots
        if slot.state == "unresolved" or slot.confidence.ambiguous
    )
    return LogicalColumnComparisonCache(
        model=alignment.model,
        three_way_alignment=alignment,
        structural_diff_cols=structural,
        unresolved_cols=unresolved,
    )


def compare_logical_row_sides(
    column_cache: LogicalColumnComparisonCache,
    left_value_row,
    right_value_row,
    left_edit_row=None,
    right_edit_row=None,
    *,
    left_side: str = "mine",
    right_side: str = "theirs",
    left_row: int | None = None,
    right_row: int | None = None,
    left_present: bool = True,
    right_present: bool = True,
    values_only: bool = False,
) -> LogicalRowComparison:
    """Compare any two model sides with cached rows and zero Worksheet access."""
    if not left_present or not right_present:
        if left_present != right_present:
            return LogicalRowComparison(frozenset((-1,)), False)
        return LogicalRowComparison(frozenset(), False)

    diff_cols = set()
    needs_formula_check = False
    compare_row = left_row if left_row is not None else right_row
    left_physical_to_logical = _formula_mapping_for_model_side(
        column_cache.model, left_side
    )
    right_physical_to_logical = _formula_mapping_for_model_side(
        column_cache.model, right_side
    )
    for slot in column_cache.model.slots:
        logical_col = slot.logical_idx + 1
        left_col = _logical_model_side_col(slot, left_side)
        right_col = _logical_model_side_col(slot, right_side)
        if left_col is None and right_col is None:
            continue
        if left_col is None or right_col is None:
            existing_row = right_value_row if left_col is None else left_value_row
            existing_edit_row = right_edit_row if left_col is None else left_edit_row
            existing_col = right_col if left_col is None else left_col
            if _logical_cell_has_content(existing_row, existing_edit_row, existing_col):
                diff_cols.add(logical_col)
            continue
        left_value = _logical_row_value(left_value_row, left_col)
        right_value = _logical_row_value(right_value_row, right_col)
        if values_only:
            if _merge_cmp_value(left_value) != _merge_cmp_value(right_value):
                diff_cols.add(logical_col)
            if left_edit_row is None or right_edit_row is None:
                needs_formula_check = True
            continue
        left_value, left_edit = _logical_cell_payload(
            left_value_row,
            left_edit_row,
            left_col,
            source_row=left_row,
            compare_row=compare_row,
            logical_col=logical_col,
            physical_to_logical=left_physical_to_logical,
        )
        right_value, right_edit = _logical_cell_payload(
            right_value_row,
            right_edit_row,
            right_col,
            source_row=right_row,
            compare_row=compare_row,
            logical_col=logical_col,
            physical_to_logical=right_physical_to_logical,
        )
        left_edit = _canonicalize_formula_column_references(
            left_edit, left_physical_to_logical
        )
        right_edit = _canonicalize_formula_column_references(
            right_edit, right_physical_to_logical
        )
        _left_display, _right_display, equal = _cell_display_and_equal_from_values(
            left_value,
            right_value,
            left_edit,
            right_edit,
        )
        if not equal:
            diff_cols.add(logical_col)
    return LogicalRowComparison(frozenset(diff_cols), needs_formula_check)


def compare_logical_row_2way(
    column_cache: LogicalColumnComparisonCache,
    mine_value_row,
    theirs_value_row,
    mine_edit_row=None,
    theirs_edit_row=None,
    *,
    mine_row: int | None = None,
    theirs_row: int | None = None,
    mine_present: bool = True,
    theirs_present: bool = True,
    values_only: bool = False,
) -> LogicalRowComparison:
    """Compare Mine and Theirs through cached logical slots."""
    return compare_logical_row_sides(
        column_cache,
        mine_value_row,
        theirs_value_row,
        mine_edit_row,
        theirs_edit_row,
        left_side="mine",
        right_side="theirs",
        left_row=mine_row,
        right_row=theirs_row,
        left_present=mine_present,
        right_present=theirs_present,
        values_only=values_only,
    )


def compare_logical_row_3way(
    column_cache: LogicalColumnComparisonCache,
    mine_value_row,
    base_value_row,
    theirs_value_row,
    mine_edit_row=None,
    base_edit_row=None,
    theirs_edit_row=None,
    *,
    mine_row: int | None = None,
    base_row: int | None = None,
    theirs_row: int | None = None,
) -> LogicalThreeWayRowComparison:
    """Classify one aligned 3-way row through Base-anchored logical slots."""
    mine_changed = set()
    theirs_changed = set()
    conflicts = set()
    compare_row = (
        mine_row if mine_row is not None
        else theirs_row if theirs_row is not None
        else base_row
    )
    mine_physical_to_logical = _formula_mapping_for_model_side(
        column_cache.model, "mine"
    )
    base_physical_to_logical = _formula_mapping_for_model_side(
        column_cache.model, "base"
    )
    theirs_physical_to_logical = _formula_mapping_for_model_side(
        column_cache.model, "theirs"
    )
    for slot in column_cache.model.slots:
        if slot.base_col is None:
            continue
        logical_col = slot.logical_idx + 1

        base_value, base_edit = _logical_cell_payload(
            base_value_row,
            base_edit_row,
            slot.base_col,
            source_row=base_row,
            compare_row=compare_row,
            logical_col=logical_col,
            physical_to_logical=base_physical_to_logical,
        )

        if slot.mine_col is None:
            mine_value = None
            mine_edit = None
            mine_key = None
        else:
            mine_value, mine_edit = _logical_cell_payload(
                mine_value_row,
                mine_edit_row,
                slot.mine_col,
                source_row=mine_row,
                compare_row=compare_row,
                logical_col=logical_col,
                physical_to_logical=mine_physical_to_logical,
            )

        if slot.theirs_col is None:
            theirs_value = None
            theirs_edit = None
            theirs_key = None
        else:
            theirs_value, theirs_edit = _logical_cell_payload(
                theirs_value_row,
                theirs_edit_row,
                slot.theirs_col,
                source_row=theirs_row,
                compare_row=compare_row,
                logical_col=logical_col,
                physical_to_logical=theirs_physical_to_logical,
            )

        base_edit = _canonicalize_formula_column_references(
            base_edit, base_physical_to_logical
        )
        if slot.mine_col is not None:
            mine_edit = _canonicalize_formula_column_references(
                mine_edit, mine_physical_to_logical
            )
        if slot.theirs_col is not None:
            theirs_edit = _canonicalize_formula_column_references(
                theirs_edit, theirs_physical_to_logical
            )

        base_key = _merge_cell_compare_key(base_value, base_edit)
        if slot.mine_col is None:
            mine_changed.add(logical_col)
        else:
            mine_key = _merge_cell_compare_key(mine_value, mine_edit)
            if mine_key != base_key:
                mine_changed.add(logical_col)

        if slot.theirs_col is None:
            theirs_changed.add(logical_col)
        else:
            theirs_key = _merge_cell_compare_key(theirs_value, theirs_edit)
            if theirs_key != base_key:
                theirs_changed.add(logical_col)

        if (
            slot.mine_col is not None
            and slot.theirs_col is not None
            and logical_col in mine_changed
            and logical_col in theirs_changed
            and mine_key != theirs_key
        ):
            conflicts.add(logical_col)
    return LogicalThreeWayRowComparison(
        frozenset(mine_changed),
        frozenset(theirs_changed),
        frozenset(conflicts),
    )


def classify_logical_columns_3way(
    column_cache: LogicalColumnComparisonCache,
    *,
    mine_changed_cols=(),
    theirs_changed_cols=(),
    mine_metadata_changed_cols=(),
    theirs_metadata_changed_cols=(),
    trusted_same_ordinal_cols=(),
) -> LogicalThreeWayColumnAnalysis:
    """Classify Base identities and conservatively expose structural conflicts."""
    mine_changed = {int(c) for c in mine_changed_cols} | {
        int(c) for c in mine_metadata_changed_cols
    }
    theirs_changed = {int(c) for c in theirs_changed_cols} | {
        int(c) for c in theirs_metadata_changed_cols
    }
    trusted_same_ordinal = {int(c) for c in trusted_same_ordinal_cols}
    states = []
    conflicts = []
    competing_boundaries = {
        slot.base_boundary
        for slot in column_cache.model.slots
        if (
            slot.base_col is None
            and slot.base_boundary is not None
            and slot.origin_side in ("mine", "theirs")
        )
        for other in column_cache.model.slots
        if (
            other.base_col is None
            and other.base_boundary == slot.base_boundary
            and other.origin_side in ("mine", "theirs")
            and other.origin_side != slot.origin_side
        )
    }
    for slot in column_cache.model.slots:
        logical_col = slot.logical_idx + 1
        mine_modified = logical_col in mine_changed
        theirs_modified = logical_col in theirs_changed
        conflict_kind = ""
        ambiguous = slot.state == "unresolved" or slot.confidence.ambiguous
        benign_same_ordinal_fallback = bool(
            ambiguous
            and slot.base_col is not None
            and slot.mine_col == slot.base_col == slot.theirs_col
            and logical_col in trusted_same_ordinal
            and not (
                set(slot.confidence.cause_codes)
                & {
                    COLUMN_MAPPING_CAUSE_BLANK_COLUMN,
                    COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE,
                }
            )
        )
        if benign_same_ordinal_fallback:
            # A value edit can weaken the only available column signature on a
            # narrow sheet.  When every side still owns the same ordinal and no
            # blank/duplicate/formula ambiguity exists, preserve legacy cell
            # conflict behavior instead of inventing a structural conflict.
            ambiguous = False
        if slot.base_col is None:
            state = "inserted"
            if (
                slot.origin_side in ("mine", "theirs")
                and slot.base_boundary in competing_boundaries
            ):
                conflict_kind = "competing-insertion"
            elif ambiguous:
                conflict_kind = "unresolved-mapping"
        elif slot.mine_col is None and slot.theirs_col is None:
            state = "both-deleted"
            if ambiguous:
                conflict_kind = "unresolved-mapping"
        elif slot.mine_col is None:
            state = "mine-deleted"
            if theirs_modified:
                conflict_kind = "delete-versus-modify"
            elif ambiguous:
                conflict_kind = "unresolved-mapping"
        elif slot.theirs_col is None:
            state = "theirs-deleted"
            if mine_modified:
                conflict_kind = "delete-versus-modify"
            elif ambiguous:
                conflict_kind = "unresolved-mapping"
        elif ambiguous:
            state = "unresolved"
            conflict_kind = "unresolved-mapping"
        elif mine_modified or theirs_modified:
            state = "modified"
        else:
            state = "retained"
        automatically_resolvable = not conflict_kind and not slot.confidence.ambiguous
        states.append(LogicalColumnState(
            logical_col,
            state,
            mine_modified,
            theirs_modified,
            automatically_resolvable,
        ))
        if conflict_kind:
            conflicts.append(LogicalColumnStructuralConflict(
                logical_col,
                conflict_kind,
                state,
                slot.base_boundary,
                slot.confidence.cause_codes,
            ))
    return LogicalThreeWayColumnAnalysis(tuple(states), tuple(conflicts))


def _worksheet_column_metadata_fingerprints(ws, max_col: int) -> tuple[str, ...]:
    """Build bounded per-column metadata identities without Worksheet.cell reads."""
    max_col = max(0, int(max_col or 0))
    signals: list[list[object]] = [[] for _idx in range(max_col)]
    if ws is None:
        return tuple(_stable_column_signal_digest(()) for _idx in range(max_col))
    try:
        dimensions = getattr(ws, "column_dimensions", {})
        for physical_col in range(1, max_col + 1):
            dimension = dimensions.get(get_column_letter(physical_col))
            if dimension is None:
                continue
            signals[physical_col - 1].append((
                "dimension",
                getattr(dimension, "width", None),
                bool(getattr(dimension, "hidden", False)),
                int(getattr(dimension, "outlineLevel", 0) or 0),
                bool(getattr(dimension, "collapsed", False)),
                int(getattr(dimension, "style_id", 0) or 0),
            ))
    except Exception:
        pass
    try:
        cells = getattr(ws, "_cells", {}) or {}
        for (row_idx, physical_col), cell in cells.items():
            physical_col = int(physical_col)
            if physical_col < 1 or physical_col > max_col:
                continue
            comment = getattr(cell, "comment", None)
            hyperlink = getattr(cell, "hyperlink", None)
            style_id = int(getattr(cell, "style_id", 0) or 0)
            number_format = str(getattr(cell, "number_format", "") or "")
            if (
                style_id == 0
                and number_format in ("", "General")
                and comment is None
                and hyperlink is None
            ):
                continue
            signals[physical_col - 1].append((
                "cell",
                int(row_idx),
                style_id,
                number_format,
                (
                    str(getattr(comment, "author", "") or ""),
                    str(getattr(comment, "text", "") or ""),
                ) if comment is not None else None,
                (
                    str(getattr(hyperlink, "target", "") or ""),
                    str(getattr(hyperlink, "location", "") or ""),
                    str(getattr(hyperlink, "tooltip", "") or ""),
                ) if hyperlink is not None else None,
            ))
    except Exception:
        pass
    try:
        validations = getattr(getattr(ws, "data_validations", None), "dataValidation", ()) or ()
        for validation in validations:
            ref_text = str(getattr(validation, "sqref", "") or "")
            validation_signal = (
                "validation",
                ref_text,
                str(getattr(validation, "type", "") or ""),
                str(getattr(validation, "formula1", "") or ""),
                str(getattr(validation, "formula2", "") or ""),
            )
            for match in re.finditer(
                r"(?:^|\s)\$?([A-Z]+)\$?\d*(?::\$?([A-Z]+)\$?\d*)?",
                ref_text.upper(),
            ):
                start_col = _col_index_from_ref(match.group(1))
                end_col = _col_index_from_ref(match.group(2) or match.group(1))
                for physical_col in range(max(1, start_col), min(max_col, end_col) + 1):
                    signals[physical_col - 1].append(validation_signal)
    except Exception:
        pass
    return tuple(
        _stable_column_signal_digest(tuple(sorted(column_signals, key=repr)))
        for column_signals in signals
    )


def logical_metadata_changes_from_base(
    column_cache: LogicalColumnComparisonCache,
    mine_metadata,
    base_metadata,
    theirs_metadata,
) -> tuple[frozenset[int], frozenset[int]]:
    """Project metadata identities through Base slots and return changed columns."""
    mine_changed = set()
    theirs_changed = set()
    for slot in column_cache.model.slots:
        if slot.base_col is None:
            continue
        logical_col = slot.logical_idx + 1
        base_value = _logical_row_value(base_metadata, slot.base_col)
        if slot.mine_col is not None:
            if _logical_row_value(mine_metadata, slot.mine_col) != base_value:
                mine_changed.add(logical_col)
        if slot.theirs_col is not None:
            if _logical_row_value(theirs_metadata, slot.theirs_col) != base_value:
                theirs_changed.add(logical_col)
    return frozenset(mine_changed), frozenset(theirs_changed)


def _cell_display_and_equal_by_row(ws_a_val, ws_b_val, ws_a_edit, ws_b_edit, ra: int | None, rb: int | None, c: int):
    va_val = ws_a_val.cell(row=ra, column=c).value if ra is not None else None
    vb_val = ws_b_val.cell(row=rb, column=c).value if rb is not None else None
    va_edit = ws_a_edit.cell(row=ra, column=c).value if (ra is not None and ws_a_edit is not None) else None
    vb_edit = ws_b_edit.cell(row=rb, column=c).value if (rb is not None and ws_b_edit is not None) else None
    if ra is not None and rb is not None and ra != rb:
        vb_edit = _translate_normal_formula_for_compare(vb_val, vb_edit, rb, c, ra, c)
    return _cell_display_and_equal_from_values(va_val, vb_val, va_edit, vb_edit)


class _LiteralText(str):
    """String beginning with '=' that must remain text, not become a formula."""


def _formula_text(v):
    if isinstance(v, _LiteralText):
        return None
    if isinstance(v, str) and v.startswith("="):
        return v
    if isinstance(v, ArrayFormula):
        return getattr(v, "text", None)
    t = getattr(v, "text", None)
    if isinstance(t, str) and t.startswith("="):
        return t
    return None


def _special_formula_signature(value):
    """Return structural identity for formulas that cannot be copied as a cell string."""
    if isinstance(value, ArrayFormula):
        return (
            "array",
            str(getattr(value, "ref", "") or ""),
            _norm_formula_text(getattr(value, "text", None)),
        )
    if isinstance(value, DataTableFormula):
        try:
            attrs = tuple(sorted((str(key), str(val)) for key, val in value))
        except Exception:
            attrs = tuple(sorted((str(key), repr(val)) for key, val in vars(value).items()))
        return ("dataTable", attrs)
    return None


def _ensure_formula_copy_supported(src_edit, dst_edit=None):
    """Reject copying a special multi-cell formula unless the target already owns it."""
    src_sig = _special_formula_signature(src_edit)
    if src_sig is None:
        return
    if src_sig == _special_formula_signature(dst_edit):
        return
    raise RuntimeError(
        "检测到数组公式或数据表公式。该公式跨越多个单元格，不能按单元格/行直接覆盖；"
        "请改为合并其依赖数据，或在 Excel 中整体处理该公式区域。"
    )


def _normalize_formula_text_uncached(formula: str) -> str:
    s = str(formula).strip()
    if s.startswith("="):
        s = s[1:]
    # Excel identifiers/functions are case-insensitive, but string literals and
    # spaces are semantically significant (a space can be the intersection
    # operator). Normalize case only outside double-quoted string literals.
    out = []
    in_string = False
    idx = 0
    while idx < len(s):
        ch = s[idx]
        if ch == '"':
            out.append(ch)
            if in_string and idx + 1 < len(s) and s[idx + 1] == '"':
                out.append('"')
                idx += 2
                continue
            in_string = not in_string
        else:
            out.append(ch if in_string else ch.upper())
        idx += 1
    return "".join(out)


@lru_cache(maxsize=8192)
def _normalize_normal_formula_text_cached(formula: str) -> str:
    return _normalize_formula_text_uncached(formula)


def _norm_formula_text(v):
    f = _formula_text(v)
    if not f:
        return None
    if isinstance(v, str) and not isinstance(v, _LiteralText):
        return _normalize_normal_formula_text_cached(str(f))
    return _normalize_formula_text_uncached(str(f))


def _same_formula(a, b):
    special_a = _special_formula_signature(a)
    special_b = _special_formula_signature(b)
    if special_a is not None or special_b is not None:
        return special_a is not None and special_a == special_b
    na = _norm_formula_text(a)
    nb = _norm_formula_text(b)
    return bool(na and nb and na == nb)


def _choose_edit_value(v_val, v_edit):
    """Preserve formula semantics on overwrite, even in cached-value mode."""
    _ensure_formula_copy_supported(v_edit, None)
    if (
        isinstance(v_edit, str)
        and v_edit.startswith("=")
        and v_val == v_edit
    ):
        # A true formula's data-only value is its cached result (or None), never
        # the formula text itself. Matching edit/data-only values therefore mean
        # the source cell is literal text whose first character happens to be '='.
        return _LiteralText(v_edit)
    f = _formula_text(v_edit)
    if f:
        return f
    return v_val if _USE_CACHED_VALUES_ONLY else v_edit


def _assign_edit_cell_value(cell, value):
    """Assign an edit-workbook value without turning literal '=...' text into a formula."""
    if isinstance(value, _LiteralText):
        cell.value = str(value)
        cell.data_type = "s"
        return
    cell.value = value


def _translate_normal_formula_for_compare(
    v_val,
    v_edit,
    src_row: int,
    src_col: int,
    dst_row: int,
    dst_col: int,
):
    """Translate a normal formula to a common coordinate for aligned comparison."""
    if (
        isinstance(v_edit, str)
        and v_edit.startswith("=")
        and v_val == v_edit
    ):
        return v_edit
    if _special_formula_signature(v_edit) is not None:
        return v_edit
    formula = _formula_text(v_edit)
    if not formula or (int(src_row), int(src_col)) == (int(dst_row), int(dst_col)):
        return v_edit
    try:
        origin = f"{get_column_letter(int(src_col))}{int(src_row)}"
        target = f"{get_column_letter(int(dst_col))}{int(dst_row)}"
        return Translator(formula, origin=origin).translate_formula(target)
    except Exception:
        # If translation cannot be proven, retain the original formula so the
        # comparator reports a conservative difference instead of hiding one.
        return v_edit


_LOCAL_A1_REFERENCE_RE = re.compile(
    r"^(?P<col_abs>\$?)(?P<col>[A-Za-z]{1,3})(?P<row_abs>\$?)(?P<row>[1-9][0-9]*)$"
)
_LOCAL_COLUMN_REFERENCE_RE = re.compile(
    r"^(?P<col_abs>\$?)(?P<col>[A-Za-z]{1,3})$"
)
_LOCAL_ROW_REFERENCE_RE = re.compile(
    r"^(?P<row_abs>\$?)(?P<row>[1-9][0-9]*)$"
)


def _immutable_formula_mapping_entries(physical_to_logical) -> tuple[tuple[int, int], ...]:
    entries = getattr(physical_to_logical, "entries", None)
    if entries is not None:
        return tuple((int(key), int(value)) for key, value in entries)
    try:
        return tuple(sorted(
            (int(key), int(value))
            for key, value in physical_to_logical.items()
        ))
    except Exception:
        return ()


@lru_cache(maxsize=16384)
def _canonicalize_normal_formula_cached(
    formula: str,
    mapping_entries: tuple[tuple[int, int], ...],
) -> str:
    physical_to_logical = dict(mapping_entries)

    def _mapped_endpoint(raw: str, *, allow_column_only: bool) -> str | None:
        match = _LOCAL_A1_REFERENCE_RE.fullmatch(raw)
        if match is not None:
            try:
                physical = column_index_from_string(match.group("col"))
                logical = physical_to_logical.get(int(physical))
            except Exception:
                logical = None
            if logical is None:
                return None
            return (
                match.group("col_abs")
                + get_column_letter(int(logical))
                + match.group("row_abs")
                + match.group("row")
            )
        if allow_column_only:
            match = _LOCAL_COLUMN_REFERENCE_RE.fullmatch(raw)
            if match is not None:
                try:
                    physical = column_index_from_string(match.group("col"))
                    logical = physical_to_logical.get(int(physical))
                except Exception:
                    logical = None
                if logical is not None:
                    return match.group("col_abs") + get_column_letter(int(logical))
        return None

    try:
        tokenizer = Tokenizer(formula)
        for token in tokenizer.items:
            if token.type != "OPERAND" or token.subtype != "RANGE":
                continue
            raw = str(token.value or "")
            if not raw or "!" in raw or "[" in raw or "]" in raw:
                continue
            parts = raw.split(":")
            if len(parts) == 1:
                mapped = _mapped_endpoint(parts[0], allow_column_only=False)
                if mapped is not None:
                    token.value = mapped
                continue
            if len(parts) != 2:
                continue
            allow_column_only = bool(
                _LOCAL_COLUMN_REFERENCE_RE.fullmatch(parts[0])
                and _LOCAL_COLUMN_REFERENCE_RE.fullmatch(parts[1])
            )
            left = _mapped_endpoint(parts[0], allow_column_only=allow_column_only)
            right = _mapped_endpoint(parts[1], allow_column_only=allow_column_only)
            if left is not None and right is not None:
                token.value = left + ":" + right
        return tokenizer.render()
    except Exception:
        return formula


def _canonicalize_formula_column_references(edit_value, physical_to_logical) -> object:
    """Map provable local A1 references from physical to logical columns.

    Whole-formula translation is incorrect around an inserted column: a
    formula cell may move while references before the insertion stay fixed and
    references after it move. Tokenizing lets us canonicalize each unqualified
    local reference independently. Sheet-qualified/external/structured/name
    operands remain untouched when their meaning cannot be proved here.
    """
    if _special_formula_signature(edit_value) is not None:
        return edit_value
    formula = _formula_text(edit_value)
    mapping_entries = _immutable_formula_mapping_entries(physical_to_logical)
    if not formula or not mapping_entries:
        return edit_value
    # Identity geometry cannot change any provable local reference.  Avoid the
    # tokenizer entirely on the overwhelmingly common non-structural sheet.
    if all(physical == logical for physical, logical in mapping_entries):
        return edit_value
    return _canonicalize_normal_formula_cached(str(formula), mapping_entries)


def _formula_sheet_name_from_qualifier(raw_qualifier: str) -> str | None:
    qualifier = str(raw_qualifier or "")
    if not qualifier or "[" in qualifier or "]" in qualifier:
        return None
    if qualifier.startswith("'") and qualifier.endswith("'"):
        qualifier = qualifier[1:-1].replace("''", "'")
    return qualifier


def _transform_formula_for_column_structure(
    edit_value,
    *,
    formula_sheet: str,
    target_sheet: str,
    anchor: int,
    count: int,
    insert: bool,
):
    """Apply Excel-like whole-column reference movement to one formula.

    Only local A1/cell-range/whole-column RANGE tokens whose worksheet target
    can be proved are changed. Structured references, names, external links,
    and references to unrelated sheets remain byte-for-byte untouched.
    """
    if _special_formula_signature(edit_value) is not None:
        return edit_value
    formula = _formula_text(edit_value)
    if not formula:
        return edit_value
    anchor = max(1, int(anchor))
    count = max(1, int(count))
    deleted_end = anchor + count - 1

    def _parse_endpoint(raw: str, *, allow_column_only: bool):
        match = _LOCAL_A1_REFERENCE_RE.fullmatch(raw)
        if match is not None:
            try:
                physical_col = int(column_index_from_string(match.group("col")))
            except Exception:
                return None
            return (
                "cell",
                physical_col,
                match.group("col_abs"),
                match.group("row_abs"),
                match.group("row"),
            )
        if allow_column_only:
            match = _LOCAL_COLUMN_REFERENCE_RE.fullmatch(raw)
            if match is not None:
                try:
                    physical_col = int(column_index_from_string(match.group("col")))
                except Exception:
                    return None
                return ("column", physical_col, match.group("col_abs"), "", "")
        return None

    def _render_endpoint(parsed, new_col: int) -> str:
        kind, _old_col, col_abs, row_abs, row = parsed
        rendered = col_abs + get_column_letter(int(new_col))
        if kind == "cell":
            rendered += row_abs + row
        return rendered

    def _shift_single_col(old_col: int) -> int | None:
        if insert:
            return old_col + count if old_col >= anchor else old_col
        if old_col < anchor:
            return old_col
        if old_col > deleted_end:
            return old_col - count
        return None

    def _transform_reference(reference: str) -> str | None:
        parts = reference.split(":")
        if len(parts) == 1:
            parsed = _parse_endpoint(parts[0], allow_column_only=False)
            if parsed is None:
                return None
            new_col = _shift_single_col(parsed[1])
            return "#REF!" if new_col is None else _render_endpoint(parsed, new_col)
        if len(parts) != 2:
            return None
        allow_column_only = bool(
            _LOCAL_COLUMN_REFERENCE_RE.fullmatch(parts[0])
            and _LOCAL_COLUMN_REFERENCE_RE.fullmatch(parts[1])
        )
        left = _parse_endpoint(parts[0], allow_column_only=allow_column_only)
        right = _parse_endpoint(parts[1], allow_column_only=allow_column_only)
        if left is None or right is None or left[0] != right[0]:
            return None
        left_col = int(left[1])
        right_col = int(right[1])
        # Reversed Excel ranges are unusual and their deletion behavior is not
        # safe to infer; leave them conservative.
        if left_col > right_col:
            return None
        if insert:
            new_left = _shift_single_col(left_col)
            new_right = _shift_single_col(right_col)
        else:
            if left_col < anchor:
                new_left = left_col
            elif left_col > deleted_end:
                new_left = left_col - count
            elif right_col > deleted_end:
                new_left = anchor
            else:
                new_left = None

            if right_col > deleted_end:
                new_right = right_col - count
            elif right_col < anchor:
                new_right = right_col
            elif left_col < anchor:
                new_right = anchor - 1
            else:
                new_right = None
        if new_left is None or new_right is None or new_left > new_right:
            return "#REF!"
        return _render_endpoint(left, new_left) + ":" + _render_endpoint(right, new_right)

    try:
        tokenizer = Tokenizer(formula)
        for token in tokenizer.items:
            if token.type != "OPERAND" or token.subtype != "RANGE":
                continue
            raw = str(token.value or "")
            if not raw or "[" in raw or "]" in raw:
                continue
            qualifier = ""
            reference = raw
            if "!" in raw:
                qualifier, reference = raw.rsplit("!", 1)
                qualified_sheet = _formula_sheet_name_from_qualifier(qualifier)
                if (
                    qualified_sheet is None
                    or qualified_sheet.casefold() != str(target_sheet).casefold()
                ):
                    continue
            elif str(formula_sheet).casefold() != str(target_sheet).casefold():
                continue
            transformed = _transform_reference(reference)
            if transformed is None:
                continue
            token.value = (qualifier + "!" if qualifier else "") + transformed
        return tokenizer.render()
    except Exception:
        return edit_value


def _transform_formula_for_row_structure(
    edit_value,
    *,
    formula_sheet: str,
    target_sheet: str,
    anchor: int,
    count: int,
    insert: bool,
):
    """Apply Excel-like row insertion/deletion movement to A1 references."""
    if _special_formula_signature(edit_value) is not None:
        return edit_value
    formula = _formula_text(edit_value)
    if not formula:
        return edit_value
    anchor = max(1, int(anchor))
    count = max(1, int(count))
    deleted_end = anchor + count - 1

    def _shift_row(old_row: int) -> int | None:
        if insert:
            return old_row + count if old_row >= anchor else old_row
        if old_row < anchor:
            return old_row
        if old_row > deleted_end:
            return old_row - count
        return None

    def _parse_endpoint(raw: str, *, allow_row_only: bool):
        match = _LOCAL_A1_REFERENCE_RE.fullmatch(raw)
        if match is not None:
            return (
                "cell",
                match.group("col_abs"),
                match.group("col"),
                match.group("row_abs"),
                int(match.group("row")),
            )
        if allow_row_only:
            match = _LOCAL_ROW_REFERENCE_RE.fullmatch(raw)
            if match is not None:
                return (
                    "row",
                    "",
                    "",
                    match.group("row_abs"),
                    int(match.group("row")),
                )
        return None

    def _render_endpoint(parsed, new_row: int) -> str:
        kind, col_abs, col, row_abs, _old_row = parsed
        if kind == "row":
            return row_abs + str(int(new_row))
        return col_abs + col + row_abs + str(int(new_row))

    def _transform_reference(reference: str) -> str | None:
        parts = reference.split(":")
        if len(parts) == 1:
            parsed = _parse_endpoint(parts[0], allow_row_only=False)
            if parsed is None:
                return None
            new_row = _shift_row(parsed[4])
            return (
                "#REF!"
                if new_row is None
                else _render_endpoint(parsed, new_row)
            )
        if len(parts) != 2:
            return None
        allow_row_only = bool(
            _LOCAL_ROW_REFERENCE_RE.fullmatch(parts[0])
            and _LOCAL_ROW_REFERENCE_RE.fullmatch(parts[1])
        )
        left = _parse_endpoint(parts[0], allow_row_only=allow_row_only)
        right = _parse_endpoint(parts[1], allow_row_only=allow_row_only)
        if left is None or right is None or left[0] != right[0]:
            return None
        left_row = int(left[4])
        right_row = int(right[4])
        if left_row > right_row:
            return None
        if insert:
            new_left = _shift_row(left_row)
            new_right = _shift_row(right_row)
        else:
            if left_row < anchor:
                new_left = left_row
            elif left_row > deleted_end:
                new_left = left_row - count
            elif right_row > deleted_end:
                new_left = anchor
            else:
                new_left = None

            if right_row > deleted_end:
                new_right = right_row - count
            elif right_row < anchor:
                new_right = right_row
            elif left_row < anchor:
                new_right = anchor - 1
            else:
                new_right = None
        if new_left is None or new_right is None or new_left > new_right:
            return "#REF!"
        return (
            _render_endpoint(left, new_left)
            + ":"
            + _render_endpoint(right, new_right)
        )

    try:
        tokenizer = Tokenizer(formula)
        for token in tokenizer.items:
            if token.type != "OPERAND" or token.subtype != "RANGE":
                continue
            raw = str(token.value or "")
            if not raw or "[" in raw or "]" in raw:
                continue
            qualifier = ""
            reference = raw
            if "!" in raw:
                qualifier, reference = raw.rsplit("!", 1)
                qualified_sheet = _formula_sheet_name_from_qualifier(qualifier)
                if (
                    qualified_sheet is None
                    or qualified_sheet.casefold()
                    != str(target_sheet).casefold()
                ):
                    continue
            elif str(formula_sheet).casefold() != str(target_sheet).casefold():
                continue
            transformed = _transform_reference(reference)
            if transformed is not None:
                token.value = (
                    (qualifier + "!" if qualifier else "") + transformed
                )
        return tokenizer.render()
    except Exception:
        return edit_value


def _formula_edit_value_map(ws_edit) -> dict[tuple[int, int], object]:
    """Index only formula cells from a normal worksheet for hot 3-way scans."""
    result = {}
    if ws_edit is None:
        return result
    try:
        cells = getattr(ws_edit, "_cells", None)
        if cells is not None:
            for (row_idx, col_idx), cell in cells.items():
                value = cell.value
                if getattr(cell, "data_type", None) == "f" or _special_formula_signature(value) is not None:
                    result[(int(row_idx), int(col_idx))] = value
            return result
    except Exception:
        result = {}
    try:
        for row in ws_edit.iter_rows(values_only=False):
            for cell in row:
                value = cell.value
                if getattr(cell, "data_type", None) == "f" or _special_formula_signature(value) is not None:
                    result[(int(cell.row), int(cell.column))] = value
    except Exception:
        pass
    return result


class _FormulaIdentityKey:
    __slots__ = ("kind", "value")

    def __init__(self, kind: str, value):
        self.kind = kind
        self.value = value

    def __eq__(self, other):
        if not isinstance(other, _FormulaIdentityKey) or self.kind != other.kind:
            return False
        if self.value == other.value:
            return True
        if self.kind == "TEXT":
            return _same_formula(self.value, other.value)
        return False


def _merge_cell_compare_key(v_val, v_edit):
    """Type- and formula-aware key for 3-way change/conflict classification."""
    literal_equals = (
        isinstance(v_edit, str)
        and v_edit.startswith("=")
        and v_val == v_edit
    )
    special = _special_formula_signature(v_edit)
    formula = None if literal_equals else _formula_text(v_edit)
    if special is not None:
        return ("FORMULA", _FormulaIdentityKey("SPECIAL", special), _merge_cmp_value(v_val))
    if formula:
        return ("FORMULA", _FormulaIdentityKey("TEXT", formula), _merge_cmp_value(v_val))
    effective = v_val
    if effective is None and v_edit is not None:
        effective = v_edit
    return ("VALUE", _merge_cmp_value(effective))


def _copy_edit_value_for_destination(
    v_val,
    v_edit,
    dst_edit,
    *,
    src_row: int,
    src_col: int,
    dst_row: int,
    dst_col: int,
):
    """Choose an edit value and translate normal formulas like Excel copy/paste."""
    src_row = int(src_row)
    src_col = int(src_col)
    dst_row = int(dst_row)
    dst_col = int(dst_col)
    special = _special_formula_signature(v_edit)
    if special is not None:
        if (src_row, src_col) != (dst_row, dst_col):
            raise RuntimeError(
                "数组公式或数据表公式不能安全移动到不同坐标；"
                "请在 Excel 中处理该公式区域。"
            )
        _ensure_formula_copy_supported(v_edit, dst_edit)
        return v_edit

    chosen = _choose_edit_value(v_val, v_edit)
    formula = _formula_text(chosen)
    if not formula or (src_row, src_col) == (dst_row, dst_col):
        return chosen
    try:
        origin = f"{get_column_letter(src_col)}{src_row}"
        target = f"{get_column_letter(dst_col)}{dst_row}"
        return Translator(formula, origin=origin).translate_formula(target)
    except Exception as exc:
        raise RuntimeError(
            f"无法安全平移公式 {formula!r}："
            f"{get_column_letter(src_col)}{src_row} -> "
            f"{get_column_letter(dst_col)}{dst_row}"
        ) from exc


def _is_same_formula_copy_noop(src_edit, dst_edit) -> bool:
    """Return True when copying would only replace a formula with itself.

    Cached results can differ because precedent cells differ. Copying the same
    formula cannot adopt that result; Excel will recalculate it from the target
    workbook and make the apparent overwrite revert.
    """
    return _same_formula(src_edit, dst_edit)


def _col_index_from_ref(ref: str) -> int:
    if not ref:
        return 0
    m = re.match(r"([A-Za-z]+)", str(ref))
    if not m:
        return 0
    letters = m.group(1).upper()
    n = 0
    for ch in letters:
        n = n * 26 + (ord(ch) - ord("A") + 1)
    return n


def _extract_ns_map(xml_bytes: bytes) -> dict:
    """Extract XML namespace prefix→URI map from the opening bytes of an XML document.
    Used to register namespaces with ET before re-serialization to preserve original prefixes."""
    text = xml_bytes[:4096].decode("utf-8", errors="ignore")
    ns_map = {}
    for m in re.finditer(r'xmlns(?::(\w+))?="([^"]+)"', text):
        prefix = m.group(1) if m.group(1) is not None else ""
        uri = m.group(2)
        ns_map[prefix] = uri
    return ns_map


def _register_xml_namespaces(ns_map: dict):
    """Register serializable prefixes while tolerating ElementTree's ns* reserve."""
    for prefix, uri in ns_map.items():
        try:
            ET.register_namespace(prefix, uri)
        except ValueError:
            # Prefixes such as ns0 are generated by XML libraries and reserved
            # by ElementTree. It will assign an equivalent prefix on output.
            continue


_MISSING_VALUE = object()
_EXCEL_ERROR_VALUES = {
    "#NULL!", "#DIV/0!", "#VALUE!", "#REF!", "#NAME?", "#NUM!", "#N/A",
    "#GETTING_DATA", "#SPILL!", "#CALC!", "#CONNECT!", "#BLOCKED!",
    "#UNKNOWN!", "#FIELD!",
}


def _excel_cached_value_payload(value, excel_epoch=CALENDAR_WINDOWS_1900):
    """Return (cell_type, text) for an OOXML cached/scalar value."""
    if value is None:
        return None, None
    if isinstance(value, bool):
        return "b", "1" if value else "0"
    if isinstance(value, (datetime, date, datetime_time, timedelta)):
        return None, str(to_excel(value, epoch=excel_epoch))
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if isinstance(value, float) and not math.isfinite(value):
            raise RuntimeError(f"Excel cell cannot store non-finite numeric value: {value!r}")
        return None, str(value)
    text = str(value)
    return ("e" if text.upper() in _EXCEL_ERROR_VALUES else "str"), text


def _set_formula_cached_value(target_cell, q, cached_value, excel_epoch):
    for child in list(target_cell):
        if child.tag == q("v"):
            target_cell.remove(child)
    target_cell.attrib.pop("t", None)
    cell_type, cache_text = _excel_cached_value_payload(cached_value, excel_epoch)
    if cache_text is None:
        return
    if cell_type:
        target_cell.attrib["t"] = cell_type
    v = ET.SubElement(target_cell, q("v"))
    v.text = cache_text


def _expand_shared_formula_group(ws_root, shared_formula, q):
    """Expand one shared-formula group into ordinary per-cell formulas.

    This makes replacing or clearing one member safe without Excel COM. Cached
    values and all unrelated cell metadata stay untouched; Excel can recalculate
    the expanded formulas normally.
    """
    shared_index = str(shared_formula.attrib.get("si") or "")
    if not shared_index:
        raise RuntimeError("shared formula has no group index")

    members = []
    masters = []
    for cell in ws_root.iter(q("c")):
        formula_node = cell.find(q("f"))
        if (
            formula_node is None
            or formula_node.attrib.get("t") != "shared"
            or str(formula_node.attrib.get("si") or "") != shared_index
        ):
            continue
        cell_ref = str(cell.attrib.get("r") or "")
        if not cell_ref:
            raise RuntimeError(
                f"shared formula group si={shared_index!r} contains a cell without a reference"
            )
        members.append((cell_ref, formula_node))
        if (formula_node.text or "").strip():
            masters.append((cell_ref, formula_node))

    if len(masters) != 1:
        raise RuntimeError(
            f"shared formula group si={shared_index!r} has {len(masters)} masters"
        )
    master_ref, master_formula = masters[0]
    master_text = (master_formula.text or "").strip()
    if not master_text:
        raise RuntimeError(f"shared formula group si={shared_index!r} has an empty master")

    source_formula = "=" + master_text
    translated = {}
    for cell_ref, _formula_node in members:
        try:
            translated[cell_ref] = Translator(
                source_formula,
                origin=master_ref,
            ).translate_formula(cell_ref)
        except Exception as exc:
            raise RuntimeError(
                f"cannot safely expand shared formula group si={shared_index!r}: "
                f"{master_ref} -> {cell_ref}"
            ) from exc

    for cell_ref, formula_node in members:
        formula_node.attrib.clear()
        formula_node.text = translated[cell_ref][1:]


def _sheet_xml_set_cell(
    ws_root,
    row_idx: int,
    col_idx: int,
    value,
    cached_value=_MISSING_VALUE,
    preserve_existing_formula: bool = False,
    excel_epoch=CALENDAR_WINDOWS_1900,
):
    ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    q = lambda t: f"{{{ns}}}{t}"
    xml_space = "{http://www.w3.org/XML/1998/namespace}space"

    sheet_data = ws_root.find(q("sheetData"))
    if sheet_data is None:
        sheet_data = ET.SubElement(ws_root, q("sheetData"))

    target_row = None
    insert_row_at = None
    rows = list(sheet_data.findall(q("row")))
    for i, r in enumerate(rows):
        try:
            rr = int(r.attrib.get("r", "0") or 0)
        except (ValueError, TypeError):
            rr = 0
        if rr == row_idx:
            target_row = r
            break
        if rr > row_idx and insert_row_at is None:
            insert_row_at = i
    if target_row is None:
        target_row = ET.Element(q("row"), {"r": str(row_idx)})
        if insert_row_at is None:
            sheet_data.append(target_row)
        else:
            sheet_data.insert(insert_row_at, target_row)

    cell_ref = f"{get_column_letter(col_idx)}{row_idx}"
    target_cell = None
    insert_cell_at = None
    cells = list(target_row.findall(q("c")))
    for i, c in enumerate(cells):
        ref = c.attrib.get("r", "")
        cc = _col_index_from_ref(ref)
        if ref == cell_ref:
            target_cell = c
            break
        if cc > col_idx and insert_cell_at is None:
            insert_cell_at = i
    if target_cell is None:
        target_cell = ET.Element(q("c"), {"r": cell_ref})
        if insert_cell_at is None:
            target_row.append(target_cell)
        else:
            target_row.insert(insert_cell_at, target_cell)

    existing_formula = target_cell.find(q("f"))
    if preserve_existing_formula:
        if existing_formula is None:
            raise RuntimeError(f"Cache-only update target is not a formula cell: {cell_ref}")
        if cached_value is _MISSING_VALUE:
            raise RuntimeError(f"Cache-only update has no cached value: {cell_ref}")
        _set_formula_cached_value(target_cell, q, cached_value, excel_epoch)
        return

    formula = _formula_text(value)
    if existing_formula is not None:
        existing_text = existing_formula.text or ""
        existing_full = ("=" + existing_text) if existing_text else None
        if formula and existing_full and _norm_formula_text(existing_full) == _norm_formula_text(formula):
            # Preserve shared/array formula metadata while allowing an explicit
            # cached-result adoption for workbooks that use manual calculation.
            if cached_value is not _MISSING_VALUE:
                _set_formula_cached_value(target_cell, q, cached_value, excel_epoch)
            return
        existing_formula_type = existing_formula.attrib.get("t")
        if existing_formula_type == "shared":
            _expand_shared_formula_group(ws_root, existing_formula, q)
            existing_formula = target_cell.find(q("f"))
        elif existing_formula_type in ("array", "dataTable"):
            raise RuntimeError(
                f"ZIP fallback cannot safely replace special formula cell {cell_ref}; "
                "Excel native save is required"
            )

    # Keep row/cell attrs (like style index), replace only value payload.
    for child in list(target_cell):
        target_cell.remove(child)

    if formula:
        target_cell.attrib.pop("t", None)
        f = ET.SubElement(target_cell, q("f"))
        f.text = formula[1:] if str(formula).startswith("=") else str(formula)
        if cached_value is not _MISSING_VALUE:
            _set_formula_cached_value(target_cell, q, cached_value, excel_epoch)
        return

    if value is None:
        target_cell.attrib.pop("t", None)
        return

    if isinstance(value, bool):
        target_cell.attrib["t"] = "b"
        v = ET.SubElement(target_cell, q("v"))
        v.text = "1" if value else "0"
        return

    if isinstance(value, (int, float)) and not isinstance(value, bool):
        if isinstance(value, float) and not math.isfinite(value):
            raise RuntimeError(f"Excel cell cannot store non-finite numeric value: {value!r}")
        target_cell.attrib.pop("t", None)
        v = ET.SubElement(target_cell, q("v"))
        v.text = str(value)
        return

    if isinstance(value, (datetime, date, datetime_time, timedelta)):
        target_cell.attrib.pop("t", None)
        v = ET.SubElement(target_cell, q("v"))
        v.text = str(to_excel(value, epoch=excel_epoch))
        return

    # Keep text independent from sharedStrings to avoid global reindex churn.
    s = str(value)
    target_cell.attrib["t"] = "inlineStr"
    is_node = ET.SubElement(target_cell, q("is"))
    t_node = ET.SubElement(is_node, q("t"))
    if s and (s[0].isspace() or s[-1].isspace()):
        t_node.attrib[xml_space] = "preserve"
    t_node.text = s


def _filter_noop_manual_ops(src_xlsx: str, manual_ops: dict) -> dict:
    """Drop formula-to-identical-formula writes before any save backend runs."""
    if not manual_ops:
        return {}
    wb = None
    try:
        wb = load_workbook(src_xlsx, data_only=False, read_only=False)
        filtered = {}
        for key, value in manual_ops.items():
            sheet, row_idx, col_idx = key
            if sheet not in wb.sheetnames:
                filtered[key] = value
                continue
            original = wb[sheet].cell(row=int(row_idx), column=int(col_idx)).value
            if _same_formula(original, value):
                continue
            filtered[key] = value
        return filtered
    except Exception as e:
        _dlog(f"manual op no-op filter failed; keeping original ops: {e}")
        return dict(manual_ops)
    finally:
        _wbs_close(wb)


def _prepare_manual_ops_for_save(
    src_xlsx: str,
    manual_ops: dict,
    row_ops=None,
    sheet_ops=None,
    column_ops=None,
) -> dict:
    """Filter cell no-ops only when coordinates still match the source snapshot."""
    if row_ops or sheet_ops or column_ops:
        return dict(manual_ops or {})
    return _filter_noop_manual_ops(src_xlsx, manual_ops or {})


def _xlsx_contains_formulas(path: str) -> bool:
    try:
        with zipfile.ZipFile(path, "r") as zf:
            for name in zf.namelist():
                if name.startswith("xl/worksheets/") and name.endswith(".xml"):
                    if re.search(rb"<(?:[A-Za-z_][\w.-]*:)?f(?:\s|>)", zf.read(name)):
                        return True
    except Exception:
        return True
    return False


def _xlsx_sheet_part_fingerprints(path: str) -> dict[str, tuple[int, int]]:
    """Return cheap per-Sheet XML fingerprints from the ZIP central directory.

    A mismatch is only a provisional difference signal: worksheet XML also
    contains non-value metadata. Exact cell/formula comparison remains the
    authority and will confirm or clear the tab state later.
    """
    fingerprints: dict[str, tuple[int, int]] = {}
    try:
        with zipfile.ZipFile(path, "r") as zf:
            workbook_name = "xl/workbook.xml"
            rels_name = "xl/_rels/workbook.xml.rels"
            if workbook_name not in zf.namelist() or rels_name not in zf.namelist():
                return fingerprints
            workbook_root = ET.fromstring(zf.read(workbook_name))
            rels_root = ET.fromstring(zf.read(rels_name))
            rel_targets = {
                str(rel.attrib.get("Id") or ""): str(rel.attrib.get("Target") or "")
                for rel in rels_root.iter()
                if rel.tag.rsplit("}", 1)[-1] == "Relationship"
            }
            rel_id_attr = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"
            for sheet_node in workbook_root.iter():
                if sheet_node.tag.rsplit("}", 1)[-1] != "sheet":
                    continue
                sheet_name = str(sheet_node.attrib.get("name") or "")
                rel_id = str(sheet_node.attrib.get(rel_id_attr) or "")
                if not rel_id:
                    rel_id = str(next(
                        (
                            value for key, value in sheet_node.attrib.items()
                            if key == "id" or key.rsplit("}", 1)[-1] == "id"
                        ),
                        "",
                    ))
                target = rel_targets.get(rel_id, "").replace("\\", "/")
                if not sheet_name or not target:
                    continue
                if target.startswith("/"):
                    part_name = target.lstrip("/")
                else:
                    part_name = posixpath.normpath(posixpath.join("xl", target))
                try:
                    info = zf.getinfo(part_name)
                except KeyError:
                    continue
                fingerprints[sheet_name] = (int(info.CRC), int(info.file_size))
    except Exception as e:
        _dlog(f"sheet fingerprint premark failed: path={path} err={e}")
    return fingerprints


def _xlsx_requires_native_structural_replay(path: str) -> bool:
    """Return True when openpyxl row/sheet replay cannot prove package fidelity."""
    if _xlsx_contains_formulas(path):
        return True
    risky_prefixes = (
        "xl/drawings/", "xl/charts/", "xl/tables/", "xl/pivot",
        "xl/comments", "xl/threadedComments/", "xl/externalLinks/",
        "xl/ctrlProps/", "xl/embeddings/", "xl/activeX/", "xl/slicers/",
        "xl/timelines/", "xl/vbaProject.bin", "xl/macrosheets/",
        "xl/dialogsheets/",
    )
    risky_sheet_tags = re.compile(
        rb"<(?:[A-Za-z_][\w.-]*:)?(?:dataValidations?|conditionalFormatting|mergeCells|hyperlinks)(?:\s|>)"
    )
    try:
        with zipfile.ZipFile(path, "r") as zf:
            names = zf.namelist()
            if any(name.startswith(risky_prefixes) for name in names):
                return True
            for name in names:
                if name.startswith("xl/worksheets/") and name.endswith(".xml"):
                    if risky_sheet_tags.search(zf.read(name)):
                        return True
        return False
    except Exception:
        # Structural replay is destructive; unreadable package metadata must fail closed.
        return True


def _replay_formula_source_paths(
    src_xlsx: str,
    row_ops=None,
    sheet_ops=None,
    source_paths: dict[str, str] | None = None,
) -> list[str]:
    """Return workbook paths whose formulas can enter a row/sheet replay."""
    source_paths = source_paths or {}
    sides = {"A"}
    for op in list(row_ops or []) + list(sheet_ops or []):
        side = str(op.get("source_side") or "").upper()
        if side:
            sides.add(side)
    paths = [src_xlsx]
    if "A" in sides and source_paths.get("A"):
        paths.append(source_paths["A"])
    if sides & {"B", "THEIRS"}:
        path_b = source_paths.get("B") or source_paths.get("THEIRS")
        if path_b:
            paths.append(path_b)
    if "BASE" in sides and source_paths.get("BASE"):
        paths.append(source_paths["BASE"])
    unique = []
    seen = set()
    for path in paths:
        try:
            key = os.path.normcase(os.path.abspath(path))
        except Exception:
            key = str(path)
        if key in seen:
            continue
        seen.add(key)
        unique.append(path)
    return unique


def _validate_xlsx_package(path: str) -> tuple[bool, str]:
    """Validate ZIP/XML integrity and shared-formula master references."""
    try:
        with zipfile.ZipFile(path, "r") as zf:
            bad_part = zf.testzip()
            if bad_part:
                return False, f"ZIP CRC failed: {bad_part}"
            for name in zf.namelist():
                if not name.endswith((".xml", ".rels")):
                    continue
                root = ET.fromstring(zf.read(name))
                if not name.startswith("xl/worksheets/") or not name.endswith(".xml"):
                    continue
                shared: dict[str, dict[str, int]] = {}
                for node in root.iter():
                    if not str(node.tag).endswith("}f") and node.tag != "f":
                        continue
                    if node.attrib.get("t") != "shared":
                        continue
                    si = str(node.attrib.get("si") or "")
                    state = shared.setdefault(si, {"masters": 0, "members": 0})
                    state["members"] += 1
                    if node.attrib.get("ref") and (node.text or "").strip():
                        state["masters"] += 1
                for si, state in shared.items():
                    if state["members"] and state["masters"] != 1:
                        return False, (
                            f"invalid shared formula group in {name}: "
                            f"si={si!r} masters={state['masters']} members={state['members']}"
                        )
        return True, ""
    except Exception as e:
        return False, str(e)


def _build_manual_merge_xlsx_via_zip(
    src_xlsx: str,
    out_xlsx: str,
    manual_ops: dict,
    cached_values: dict | None = None,
    cache_only_keys: set[tuple[str, int, int]] | None = None,
):
    """Patch only selected cells at XML level; keep untouched parts byte-identical."""
    with zipfile.ZipFile(src_xlsx, "r") as zf:
        names = zf.namelist()
        infos = {n: zf.getinfo(n) for n in names}
        files = {n: zf.read(n) for n in names}

    wb_name = "xl/workbook.xml"
    rels_name = "xl/_rels/workbook.xml.rels"
    if wb_name not in files or rels_name not in files:
        shutil.copy2(src_xlsx, out_xlsx)
        return

    wb_ns = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
    rel_ns = "http://schemas.openxmlformats.org/package/2006/relationships"
    doc_rel_ns = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"

    wb_root = ET.fromstring(files[wb_name])
    wb_pr = wb_root.find(f"{{{wb_ns}}}workbookPr")
    date1904 = False
    if wb_pr is not None:
        date1904 = str(wb_pr.attrib.get("date1904", "0")).strip().lower() in ("1", "true")
    excel_epoch = CALENDAR_MAC_1904 if date1904 else CALENDAR_WINDOWS_1900
    rel_root = ET.fromstring(files[rels_name])
    rid_to_target = {}
    for rel in rel_root.findall(f"{{{rel_ns}}}Relationship"):
        rid = rel.attrib.get("Id")
        tgt = rel.attrib.get("Target")
        if not rid or not tgt:
            continue
        if tgt.startswith("/"):
            norm = tgt.lstrip("/")
        elif tgt.startswith("xl/"):
            norm = tgt
        else:
            norm = f"xl/{tgt}"
        rid_to_target[rid] = norm.replace("\\", "/")

    sheet_to_part = {}
    sheets = wb_root.find(f"{{{wb_ns}}}sheets")
    if sheets is not None:
        for sh in sheets.findall(f"{{{wb_ns}}}sheet"):
            name = sh.attrib.get("name")
            rid = sh.attrib.get(f"{{{doc_rel_ns}}}id")
            if not name or not rid:
                continue
            part = rid_to_target.get(rid)
            if part and part in files:
                sheet_to_part[name] = part

    ops_by_sheet = {}
    cached_values = cached_values or {}
    cache_only_keys = {
        (str(sheet), int(r), int(c))
        for sheet, r, c in (cache_only_keys or set())
    }
    for (sheet, r, c), v in manual_ops.items():
        key = (str(sheet), int(r), int(c))
        cached = cached_values.get((sheet, int(r), int(c)), _MISSING_VALUE)
        ops_by_sheet.setdefault(sheet, []).append((int(r), int(c), v, cached, key in cache_only_keys))

    for sheet, ops in ops_by_sheet.items():
        part = sheet_to_part.get(sheet)
        if not part:
            continue
        # Register original namespace prefixes before parsing to preserve them in output
        ns_map = _extract_ns_map(files[part])
        _register_xml_namespaces(ns_map)
        ws_root = ET.fromstring(files[part])
        for r, c, v, cached, cache_only in sorted(ops, key=lambda x: (x[0], x[1])):
            _sheet_xml_set_cell(
                ws_root,
                r,
                c,
                v,
                cached,
                preserve_existing_formula=cache_only,
                excel_epoch=excel_epoch,
            )
        xml_bytes = ET.tostring(ws_root, encoding="utf-8", xml_declaration=True)
        xml_bytes = re.sub(
            rb'<\?xml[^?]*\?>',
            b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
            xml_bytes, count=1
        )
        # ET silently drops namespace declarations for prefixes not used in any element
        # tag (e.g. x14ac/xr/xr2 referenced only as string tokens in mc:Ignorable).
        # Re-inject any such declarations so mc:Ignorable remains valid.
        missing_decls = [
            f'xmlns:{pfx}="{uri}"'
            for pfx, uri in ns_map.items()
            if pfx and pfx != "xml" and f'xmlns:{pfx}="'.encode() not in xml_bytes
        ]
        if missing_decls:
            inject = (" " + " ".join(missing_decls)).encode()
            xml_bytes = re.sub(
                rb'(<\?xml[^?]*\?>\s*)(<[A-Za-z][\w:.-]*)',
                lambda m: m.group(1) + m.group(2) + inject,
                xml_bytes, count=1
            )
        files[part] = xml_bytes

    # Remove calcChain.xml to avoid Excel repair caused by stale calculation chain
    calc_chain = "xl/calcChain.xml"
    if calc_chain in names:
        names = [n for n in names if n != calc_chain]
        files.pop(calc_chain, None)

        # Remove calcChain Override from [Content_Types].xml
        ct_name = "[Content_Types].xml"
        if ct_name in files:
            ct_ns_map = _extract_ns_map(files[ct_name])
            _register_xml_namespaces(ct_ns_map)
            ct_root = ET.fromstring(files[ct_name])
            ct_ns = "http://schemas.openxmlformats.org/package/2006/content-types"
            for override in ct_root.findall(f"{{{ct_ns}}}Override"):
                if "/calcChain" in override.attrib.get("PartName", ""):
                    ct_root.remove(override)
            ct_bytes = ET.tostring(ct_root, encoding="utf-8", xml_declaration=True)
            ct_bytes = re.sub(
                rb'<\?xml[^?]*\?>',
                b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
                ct_bytes, count=1
            )
            files[ct_name] = ct_bytes

        # Remove calcChain Relationship from xl/_rels/workbook.xml.rels
        if rels_name in files:
            wbr_ns_map = _extract_ns_map(files[rels_name])
            _register_xml_namespaces(wbr_ns_map)
            wbr_root = ET.fromstring(files[rels_name])
            for rel in wbr_root.findall(f"{{{rel_ns}}}Relationship"):
                if "calcChain" in rel.attrib.get("Target", ""):
                    wbr_root.remove(rel)
            wbr_bytes = ET.tostring(wbr_root, encoding="utf-8", xml_declaration=True)
            wbr_bytes = re.sub(
                rb'<\?xml[^?]*\?>',
                b'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>',
                wbr_bytes, count=1
            )
            files[rels_name] = wbr_bytes

    with zipfile.ZipFile(out_xlsx, "w") as zf:
        for n in names:
            info = infos.get(n)
            comp = info.compress_type if info else zipfile.ZIP_DEFLATED
            zf.writestr(n, files[n], compress_type=comp)
    valid, reason = _validate_xlsx_package(out_xlsx)
    if not valid:
        raise RuntimeError(f"unsafe XLSX output rejected: {reason}")


def _excel_com_cell_op(sheet: str, row: int, col: int, value) -> dict:
    """Return a JSON-safe, type-preserving Excel COM cell operation."""
    formula = _formula_text(value)
    if formula:
        return {"sheet": sheet, "r": int(row), "c": int(col), "formula": formula}
    if value is None:
        # ConvertFrom-Json maps JSON null to PowerShell $null. Assigning that
        # directly to Excel Range.Value2 can raise NullReferenceException;
        # clearing is also the correct Excel operation for a blank source cell.
        return {
            "sheet": sheet,
            "r": int(row),
            "c": int(col),
            "value_kind": "blank",
        }
    if isinstance(value, datetime):
        return {
            "sheet": sheet,
            "r": int(row),
            "c": int(col),
            "value": float(to_excel(value, epoch=CALENDAR_WINDOWS_1900)),
            "value_kind": "datetime_serial",
        }
    if isinstance(value, date):
        return {
            "sheet": sheet,
            "r": int(row),
            "c": int(col),
            "value": float(to_excel(value, epoch=CALENDAR_WINDOWS_1900)),
            "value_kind": "datetime_serial",
        }
    if isinstance(value, datetime_time):
        seconds = (
            value.hour * 3600
            + value.minute * 60
            + value.second
            + value.microsecond / 1_000_000.0
        )
        value = seconds / 86400.0
    elif isinstance(value, timedelta):
        value = value.total_seconds() / 86400.0
    return {
        "sheet": sheet,
        "r": int(row),
        "c": int(col),
        "value": str(value) if isinstance(value, _LiteralText) else value,
        "value_kind": "text" if isinstance(value, str) else "typed",
    }


def _validated_column_replay_operations(column_ops) -> list[dict[str, object]]:
    """Return a JSON-safe, strictly ordered native column replay plan."""
    normalized = []
    seen_orders = set()
    for raw in column_ops or ():
        op = dict(raw or {})
        kind = str(op.get("kind") or "")
        sheet = str(op.get("sheet") or "")
        target_side = str(op.get("target_side") or "").upper()
        source_side = str(op.get("source_side") or "").upper()
        order = int(op.get("order", 0) or 0)
        anchor = int(op.get("target_physical_anchor", 0) or 0)
        count = int(op.get("count", 0) or 0)
        source_cols = [int(value) for value in (op.get("source_physical_cols") or [])]
        if kind not in ("insert_cols", "delete_cols", "copy_cols"):
            raise ValueError(f"unsupported native column operation: {kind!r}")
        if not sheet or target_side not in ("A", "B"):
            raise ValueError("native column operation has no valid Sheet/target")
        if source_side not in ("A", "BASE", "B"):
            raise ValueError("native column operation has no valid source")
        if order <= 0 or order in seen_orders or anchor <= 0 or count <= 0:
            raise ValueError("native column operation order/range is invalid")
        if kind == "copy_cols":
            if len(source_cols) != count or any(
                right != left + 1 for left, right in zip(source_cols, source_cols[1:])
            ):
                raise ValueError("native column copy source must be one consecutive block")
        seen_orders.add(order)
        op.update({
            "kind": kind,
            "sheet": sheet,
            "target_side": target_side,
            "source_side": source_side,
            "order": order,
            "target_physical_anchor": anchor,
            "count": count,
            "source_physical_cols": source_cols,
            "metadata_scope": list(op.get("metadata_scope") or _COLUMN_ACTION_METADATA_SCOPE),
        })
        normalized.append(op)
    normalized.sort(key=lambda op: int(op["order"]))
    return normalized


def _validated_structural_replay_operations(row_ops, column_ops) -> list[dict[str, object]]:
    """Return row/column operations in the exact order applied in memory.

    Row and column adoption can overlap.  Replaying all rows before all columns
    (or the reverse) changes the winner at their intersection, so newly-recorded
    operations share one monotonic structural order.  Legacy row records without
    an order remain supported and are placed after every explicitly ordered
    operation, matching the save behavior that existed before shared ordering.
    """
    columns = _validated_column_replay_operations(column_ops)
    normalized = []
    seen_orders = {int(op["order"]) for op in columns}
    max_explicit_order = max(seen_orders, default=0)
    legacy_rows = []
    for raw in row_ops or ():
        op = dict(raw or {})
        kind = str(op.get("kind") or "")
        sheet = str(op.get("sheet") or "")
        row = int(op.get("row", 0) or 0)
        count = int(op.get("count", 0) or 0)
        source_side = str(op.get("source_side") or "").upper()
        source_rows = [int(value) for value in (op.get("source_rows") or [])]
        if kind not in ("insert_rows", "delete_rows") or not sheet or row <= 0 or count <= 0:
            raise ValueError("native row operation kind/range is invalid")
        if source_side not in ("", "A", "BASE", "B", "THEIRS"):
            raise ValueError("native row operation source is invalid")
        if kind == "delete_rows" and (source_side or source_rows):
            raise ValueError("delete_rows cannot declare a copy source")
        if kind == "insert_rows" and source_rows and len(source_rows) != count:
            raise ValueError("native row copy source must match inserted row count")
        order = int(op.get("order", 0) or 0)
        op.update({
            "kind": kind,
            "sheet": sheet,
            "row": row,
            "count": count,
            "source_side": source_side,
            "source_rows": source_rows,
            "structural_kind": "row",
        })
        if order > 0:
            if order in seen_orders:
                raise ValueError("native structural operation order is duplicated")
            seen_orders.add(order)
            max_explicit_order = max(max_explicit_order, order)
            op["order"] = order
            normalized.append(op)
        else:
            legacy_rows.append(op)
    for op in columns:
        item = dict(op)
        item["structural_kind"] = "column"
        normalized.append(item)
    for op in legacy_rows:
        max_explicit_order += 1
        while max_explicit_order in seen_orders:
            max_explicit_order += 1
        op["order"] = max_explicit_order
        seen_orders.add(max_explicit_order)
        normalized.append(op)
    normalized.sort(key=lambda op: int(op["order"]))
    return normalized


def _run_excel_powershell_with_transient_retry(script: str, *, timeout: int):
    """Run an Excel COM script, retrying only the transient logon-session fault."""
    result = None
    for attempt in range(4):
        result = subprocess.run(
            ["powershell", "-NoProfile", "-STA", "-ExecutionPolicy", "Bypass", "-Command", script],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=timeout,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
        error_text = str(getattr(result, "stderr", "") or "")
        if int(getattr(result, "returncode", 1) or 0) == 0:
            return result
        if "80070520" not in error_text or attempt >= 3:
            return result
        _dlog(f"Excel COM logon session unavailable; transient retry {attempt + 2}/4")
        time.sleep(float(attempt + 1))
    return result


def _excel_reopen_validate(path: str) -> bool:
    """Require Excel itself to reopen the final native-replay package."""
    if not _workbook_package_ready(path):
        return False
    try:
        ps = (
            "$ErrorActionPreference='Stop';"
            "$p='" + str(path).replace("'", "''") + "';"
            "$xl=$null;$wb=$null;"
            "try{"
            "$xl=New-Object -ComObject Excel.Application;"
            "$xl.Visible=$false;$xl.DisplayAlerts=$false;$xl.AskToUpdateLinks=$false;$xl.EnableEvents=$false;"
            "$wb=$xl.Workbooks.Open($p,0,$true);"
            "if($wb -eq $null){throw 'Excel reopen returned null'};"
            "}finally{"
            "if($wb -ne $null){try{$wb.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wb)}catch{}};"
            "if($xl -ne $null){try{$xl.Quit()}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($xl)}catch{}};"
            "[GC]::Collect();[GC]::WaitForPendingFinalizers();[GC]::Collect();[GC]::WaitForPendingFinalizers();"
            "};"
        )
        result = _run_excel_powershell_with_transient_retry(ps, timeout=120)
        if result.returncode != 0:
            _dlog(f"Excel reopen validation failed: {result.stderr.strip()}")
            return False
        return True
    except Exception as exc:
        _dlog(f"Excel reopen validation exception: {exc}")
        return False


def _build_manual_merge_output_with_excel(
    src_xlsx: str,
    out_xlsx: str,
    manual_ops: dict,
    row_ops: list[dict] | None = None,
    sheet_ops: list[dict] | None = None,
    source_paths: dict[str, str] | None = None,
    column_ops: list[dict] | None = None,
) -> bool:
    """Apply manual ops through Excel COM to preserve workbook fidelity."""
    if not manual_ops and not row_ops and not sheet_ops and not column_ops:
        try:
            shutil.copy2(src_xlsx, out_xlsx)
            return True
        except Exception:
            return False
    row_ops = list(row_ops or [])
    sheet_ops = list(sheet_ops or [])
    try:
        column_ops = _validated_column_replay_operations(column_ops)
        structural_ops = _validated_structural_replay_operations(row_ops, column_ops)
    except Exception as exc:
        _dlog(f"excel native save: invalid column replay plan: {exc}")
        return False
    ops = []
    for (sheet, r, c), v in manual_ops.items():
        ops.append(_excel_com_cell_op(sheet, r, c, v))
    try:
        ops_json = os.path.join(
            tempfile.gettempdir(),
            f"{APP_NAME}_merge_ops_{os.getpid()}_{time.time_ns()}.json",
        )
        with open(ops_json, "w", encoding="utf-8") as f:
            json.dump(
                {
                    "row_ops": row_ops,
                    "cell_ops": ops,
                    "sheet_ops": sheet_ops,
                    "column_ops": column_ops,
                    "structural_ops": structural_ops,
                },
                f,
                ensure_ascii=False,
                allow_nan=False,
            )
    except Exception as e:
        _dlog(f"excel native save: write ops json failed: {e}")
        return False
    source_stage_dir = None
    try:
        if os.path.exists(out_xlsx):
            os.remove(out_xlsx)
        source_paths = source_paths or {}
        # Excel refuses to keep two workbooks with the same basename open in a
        # single COM instance.  Real SVN three-way inputs intentionally share
        # that basename (for example Base/Guide.xlsx and Theirs/Guide.xlsx), so
        # stage read-only replay sources under unique names before opening them.
        # The destination workbook already uses a unique snapshot name.
        staged_source_paths = {}
        if any(path for path in source_paths.values()):
            source_stage_dir = tempfile.mkdtemp(
                prefix=f"{APP_NAME}_native_sources_{os.getpid()}_"
            )
            for index, (side, source_path) in enumerate(source_paths.items()):
                if not source_path:
                    continue
                staged_path = os.path.join(
                    source_stage_dir,
                    f"{index:02d}_{str(side).lower()}{_workbook_ext(source_path)}",
                )
                # Besides avoiding Excel's same-basename restriction, this is
                # the save transaction's immutable source snapshot.  A live
                # SVN/local file may otherwise change between replay steps.
                shutil.copy2(source_path, staged_path)
                staged_source_paths[str(side).upper()] = staged_path
        source_paths = staged_source_paths
        mine_src = str(source_paths.get("A") or "").replace("'", "''")
        base_src = str(source_paths.get("BASE") or "").replace("'", "''")
        theirs_src = str(source_paths.get("B") or source_paths.get("THEIRS") or "").replace("'", "''")
        ps = (
            "$ErrorActionPreference='Stop';"
            "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8;"
            "$OutputEncoding=[System.Text.Encoding]::UTF8;"
            "[Console]::OutputEncoding=[System.Text.Encoding]::UTF8;"
            "$OutputEncoding=[System.Text.Encoding]::UTF8;"
            "$src='" + src_xlsx.replace("'", "''") + "';"
            "$out='" + out_xlsx.replace("'", "''") + "';"
            "$opsPath='" + ops_json.replace("'", "''") + "';"
            "$mineSrc='" + mine_src + "';"
            "$baseSrc='" + base_src + "';"
            "$theirsSrc='" + theirs_src + "';"
            # The producer writes UTF-8 JSON without a locale-specific BOM.
            # Windows PowerShell's default Get-Content decoding follows the
            # active system code page and can turn Chinese payloads into
            # mojibake before Excel receives them.  Read the bytes explicitly.
            "$payload=ConvertFrom-Json -InputObject ([System.IO.File]::ReadAllText($opsPath,[System.Text.Encoding]::UTF8));"
            "$xl=$null;$wb=$null;$wbMine=$null;$wbBase=$null;$wbTheirs=$null;$wbCheck=$null;"
            "try{"
            "$xl=New-Object -ComObject Excel.Application;"
            "$xl.Visible=$false;"
            "$xl.ScreenUpdating=$false;"
            "$xl.DisplayAlerts=$false;"
            "$xl.AskToUpdateLinks=$false;"
            "$xl.EnableEvents=$false;"
            "try{$xl.Calculation=-4135}catch{};"
            "try{$xl.CalculateBeforeSave=$false}catch{};"
            "$wb=$xl.Workbooks.Open($src,0,$false);"
            "try{$xl.Calculation=-4135}catch{};"
            "if($mineSrc){$wbMine=$xl.Workbooks.Open($mineSrc,0,$true)};"
            "if($baseSrc){$wbBase=$xl.Workbooks.Open($baseSrc,0,$true)};"
            "if($theirsSrc){$wbTheirs=$xl.Workbooks.Open($theirsSrc,0,$true)};"
            "foreach($op in @($payload.sheet_ops)){"
            "  if($null -eq $op){continue};"
            "  if($op.kind -eq 'delete_sheet'){"
            "    try{"
            "      if($wb.Worksheets.Count -gt 1){$wb.Worksheets.Item($op.sheet).Delete()}"
            "    }catch{};"
            "    continue"
            "  };"
            "  if($op.kind -eq 'copy_sheet'){"
            "    $srcWs=$null;"
            "    if($op.source_side -eq 'BASE' -and $wbBase -ne $null){$srcWs=$wbBase.Worksheets.Item($op.sheet)}"
            "    elseif(($op.source_side -eq 'B' -or $op.source_side -eq 'THEIRS') -and $wbTheirs -ne $null){$srcWs=$wbTheirs.Worksheets.Item($op.sheet)}"
            "    elseif($op.source_side -eq 'A' -and $wbMine -ne $null){$srcWs=$wbMine.Worksheets.Item($op.sheet)}"
            "    elseif($op.source_side -eq 'A'){$srcWs=$wb.Worksheets.Item($op.sheet)};"
            "    if($srcWs -eq $null){continue};"
            "    try{$wb.Worksheets.Item($op.sheet).Delete()}catch{};"
            "    $targetIndex=$null;try{$targetIndex=[int]$op.target_index}catch{$targetIndex=$null};"
            "    if($null -eq $targetIndex){"
            "      $after=$wb.Worksheets.Item($wb.Worksheets.Count);"
            "      $srcWs.Copy($null, $after);"
            "    }elseif($targetIndex -le 0){"
            "      $before=$wb.Worksheets.Item(1);"
            "      $srcWs.Copy($before, $null);"
            "    }else{"
            "      $afterIndex=[Math]::Min($targetIndex,[int]$wb.Worksheets.Count);"
            "      $after=$wb.Worksheets.Item($afterIndex);"
            "      $srcWs.Copy($null, $after);"
            "    };"
            "    if($null -eq $targetIndex){$newWs=$wb.Worksheets.Item($wb.Worksheets.Count)}"
            "    elseif($targetIndex -le 0){$newWs=$wb.Worksheets.Item(1)}"
            "    else{$newWs=$wb.Worksheets.Item([Math]::Min($afterIndex + 1,[int]$wb.Worksheets.Count))};"
            "    try{$newWs.Name=$op.sheet}catch{};"
            "  }"
            "};"
            "foreach($op in @($payload.structural_ops | Sort-Object {[int]$_.order})){"
            "  if($null -eq $op){continue};"
            "  $ws=$wb.Worksheets.Item([string]$op.sheet);"
            "  if($op.structural_kind -eq 'row'){"
            "    if($op.kind -eq 'delete_rows'){"
            "      $first=[int]$op.row;$last=$first+[int]$op.count-1;"
            "      [void]$ws.Range($ws.Rows.Item($first),$ws.Rows.Item($last)).EntireRow.Delete();"
            "      continue"
            "    };"
            "    if($op.kind -ne 'insert_rows'){throw ('unsupported row operation: '+$op.kind)};"
            "    for($i=0;$i -lt [int]$op.count;$i++){[void]$ws.Rows.Item([int]$op.row).Insert()};"
            "    $srcWs=$null;"
            "    if(($op.source_side -eq 'B' -or $op.source_side -eq 'THEIRS') -and $wbTheirs -ne $null){$srcWs=$wbTheirs.Worksheets.Item($op.sheet)}"
            "    elseif($op.source_side -eq 'BASE' -and $wbBase -ne $null){$srcWs=$wbBase.Worksheets.Item($op.sheet)};"
            "    if($op.source_side -eq 'A' -and $wbMine -ne $null){$srcWs=$wbMine.Worksheets.Item($op.sheet)};"
            "    $srcRows=@($op.source_rows);"
            "    if($srcWs -ne $null -and $srcRows.Count -gt 0){"
            "      $lastCol=[Math]::Max(1,[int]($srcWs.UsedRange.Column+$srcWs.UsedRange.Columns.Count-1));"
            "      for($i=0;$i -lt $srcRows.Count;$i++){"
            "        $srcRow=[int]$srcRows[$i];$dstRow=[int]$op.row+$i;"
            "        $srcRange=$srcWs.Range($srcWs.Cells.Item($srcRow,1),$srcWs.Cells.Item($srcRow,$lastCol));"
            "        $dstRange=$ws.Range($ws.Cells.Item($dstRow,1),$ws.Cells.Item($dstRow,$lastCol));"
            "        [void]$srcRange.Copy();[void]$dstRange.PasteSpecial(-4104);"
            "        try{$ws.Rows.Item($dstRow).RowHeight=$srcWs.Rows.Item($srcRow).RowHeight}catch{}"
            "      }"
            "    };"
            "    continue"
            "  };"
            "  if($op.structural_kind -ne 'column'){throw ('unsupported structural operation: '+$op.structural_kind)};"
            "  $anchor=[int]$op.target_physical_anchor;$count=[int]$op.count;"
            "  if($anchor -lt 1 -or $count -lt 1){throw 'invalid column operation range'};"
            "  $last=$anchor+$count-1;"
            "  if($op.kind -eq 'insert_cols'){"
            "    $dstRange=$ws.Range($ws.Columns.Item($anchor),$ws.Columns.Item($last)).EntireColumn;"
            "    [void]$dstRange.Insert();continue"
            "  };"
            "  if($op.kind -eq 'delete_cols'){"
            "    $dstRange=$ws.Range($ws.Columns.Item($anchor),$ws.Columns.Item($last)).EntireColumn;"
            "    [void]$dstRange.Delete();continue"
            "  };"
            "  if($op.kind -ne 'copy_cols'){throw ('unsupported column operation: '+$op.kind)};"
            "  $srcWs=$null;"
            "  if($op.source_side -eq 'BASE' -and $wbBase -ne $null){$srcWs=$wbBase.Worksheets.Item([string]$op.sheet)}"
            "  elseif(($op.source_side -eq 'B' -or $op.source_side -eq 'THEIRS') -and $wbTheirs -ne $null){$srcWs=$wbTheirs.Worksheets.Item([string]$op.sheet)}"
            "  elseif($op.source_side -eq 'A' -and $wbMine -ne $null){$srcWs=$wbMine.Worksheets.Item([string]$op.sheet)}"
            "  elseif($op.source_side -eq $op.target_side){$srcWs=$ws};"
            "  if($srcWs -eq $null){throw ('column copy source unavailable: '+$op.source_side)};"
            "  $srcCols=@($op.source_physical_cols);"
            "  if($srcCols.Count -ne $count){throw 'column copy source count mismatch'};"
            "  $srcFirst=[int]$srcCols[0];$srcLast=[int]$srcCols[$srcCols.Count-1];"
            "  $srcRange=$srcWs.Range($srcWs.Columns.Item($srcFirst),$srcWs.Columns.Item($srcLast)).EntireColumn;"
            "  $dstRange=$ws.Range($ws.Columns.Item($anchor),$ws.Columns.Item($last)).EntireColumn;"
            # Passing Destination avoids the Windows clipboard/PasteSpecial
            # round-trip while retaining Excel's native formula translation
            # and full cell/column metadata copy semantics.
            "  [void]$srcRange.Copy($dstRange);"
            "  for($i=0;$i -lt $count;$i++){"
            "    $srcColumn=$srcWs.Columns.Item([int]$srcCols[$i]);$dstColumn=$ws.Columns.Item($anchor+$i);"
            "    try{$dstColumn.ColumnWidth=$srcColumn.ColumnWidth}catch{};"
            "    try{$dstColumn.Hidden=$srcColumn.Hidden}catch{};"
            "  };"
            "  try{$xl.CutCopyMode=0}catch{}"
            "};"
            # Replay sources are no longer needed once sheet/row/column copies
            # finish. Closing them before explicit cell edits and SaveCopyAs
            # reduces Excel's save working set without weakening immutable
            # source staging or the final same-instance reopen validation.
            "$srcRange=$null;$srcWs=$null;$srcColumn=$null;"
            "if($wbTheirs -ne $null){$wbTheirs.Close($false);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbTheirs);$wbTheirs=$null};"
            "if($wbBase -ne $null){$wbBase.Close($false);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbBase);$wbBase=$null};"
            "if($wbMine -ne $null){$wbMine.Close($false);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbMine);$wbMine=$null};"
            # xlPasteAll preserves comments, hyperlinks, validation and cell
            # metadata. Explicit cell_ops run afterwards and remain the source
            # of truth for translated formulas and cached-value decisions.
            "foreach($op in @($payload.cell_ops)){"
            "  if($null -eq $op){continue};"
            "  $ws=$wb.Worksheets.Item($op.sheet);"
            "  $cell=$ws.Cells.Item([int]$op.r,[int]$op.c);"
            "  if($null -ne $op.formula){$cell.Formula=$op.formula}"
            "  elseif($op.value_kind -eq 'blank'){$cell.ClearContents()}"
            "  elseif($op.value_kind -eq 'datetime_serial'){"
            "    $serial=[double]$op.value;if($wb.Date1904){$serial-=1462};$cell.Value2=$serial"
            "  }"
            "  elseif($op.value_kind -eq 'text'){"
            "    if($cell.NumberFormat -eq 'General'){$cell.NumberFormat='@'};"
            "    $textValue=[string]$op.value;"
            "    $cell.Value=$textValue"
            "  }"
            "  else{$cell.Value2=$op.value}"
            "};"
            "$wb.SaveCopyAs($out);"
            "if($wb -ne $null){$wb.Close($false);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wb);$wb=$null};"
            "$wbCheck=$xl.Workbooks.Open($out,0,$true);"
            "if($wbCheck -eq $null){throw 'Excel reopen validation failed'};"
            "$wbCheck.Close($false);"
            "[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbCheck);$wbCheck=$null;"
            "}finally{"
            "  $cell=$null;$ws=$null;$srcRange=$null;$dstRange=$null;$srcWs=$null;$srcColumn=$null;$dstColumn=$null;$newWs=$null;$after=$null;"
            "  if($wbCheck -ne $null){try{$wbCheck.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbCheck)}catch{}};"
            "  if($wbTheirs -ne $null){try{$wbTheirs.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbTheirs)}catch{}};"
            "  if($wbBase -ne $null){try{$wbBase.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbBase)}catch{}};"
            "  if($wbMine -ne $null){try{$wbMine.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wbMine)}catch{}};"
            "  if($wb -ne $null){try{$wb.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wb)}catch{}};"
            "  if($xl -ne $null){try{$xl.Quit()}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($xl)}catch{}};"
            "  [GC]::Collect();[GC]::WaitForPendingFinalizers();"
            "};"
        )
        r = _run_excel_powershell_with_transient_retry(ps, timeout=180)
        if r.returncode != 0:
            _dlog(f"excel native save failed rc={r.returncode} err={r.stderr.strip()}")
            try:
                if os.path.exists(out_xlsx):
                    os.remove(out_xlsx)
            except Exception:
                pass
            return False
        valid, reason = _validate_xlsx_package(out_xlsx)
        if not valid:
            _dlog(f"excel native save produced invalid package: {reason}")
            try:
                if os.path.exists(out_xlsx):
                    os.remove(out_xlsx)
            except Exception:
                pass
            return False
        _dlog(
            f"excel native save ok: {out_xlsx} sheet_ops={len(sheet_ops)} "
            f"row_ops={len(row_ops)} column_ops={len(column_ops)} cell_ops={len(ops)}"
        )
        return True
    except Exception as e:
        _dlog(f"excel native save exception: {e}")
        try:
            if os.path.exists(out_xlsx):
                os.remove(out_xlsx)
        except Exception:
            pass
        return False
    finally:
        try:
            if os.path.exists(ops_json):
                os.remove(ops_json)
        except Exception:
            pass
        if source_stage_dir:
            try:
                shutil.rmtree(source_stage_dir)
            except Exception:
                pass


def _build_manual_merge_output_with_openpyxl(
    src_xlsx: str,
    out_xlsx: str,
    manual_ops: dict,
    row_ops: list[dict] | None = None,
    sheet_ops: list[dict] | None = None,
    source_paths: dict[str, str] | None = None,
) -> bool:
    """Replay manual merge operations with openpyxl when Excel COM is unavailable."""
    wb = None
    wb_a = None
    wb_base = None
    wb_b = None
    ext_parts = _capture_external_link_parts(src_xlsx)
    try:
        wb = load_workbook(src_xlsx, data_only=False)
        source_paths = source_paths or {}
        if source_paths.get("A"):
            wb_a = load_workbook(source_paths["A"], data_only=False)
        if source_paths.get("BASE"):
            wb_base = load_workbook(source_paths["BASE"], data_only=False)
        if source_paths.get("B"):
            wb_b = load_workbook(source_paths["B"], data_only=False)
        for op in list(sheet_ops or []):
            kind = str(op.get("kind") or "")
            sheet = str(op.get("sheet") or "")
            if kind == "delete_sheet":
                _remove_sheet_if_exists(wb, sheet)
                continue
            if kind != "copy_sheet" or not sheet:
                continue
            side = str(op.get("source_side") or "").upper()
            src_ws = None
            if side == "A":
                source_wb = wb_a if wb_a is not None else wb
                src_ws = source_wb[sheet] if sheet in source_wb.sheetnames else None
            elif side == "BASE":
                src_ws = wb_base[sheet] if wb_base is not None and sheet in wb_base.sheetnames else None
            elif side in ("B", "THEIRS"):
                src_ws = wb_b[sheet] if wb_b is not None and sheet in wb_b.sheetnames else None
            if src_ws is None:
                continue
            target_index = op.get("target_index")
            _create_sheet_from_source(
                wb,
                src_ws,
                sheet,
                index=(int(target_index) if target_index is not None else None),
            )
        for op in list(row_ops or []):
            kind = str(op.get("kind") or "")
            if kind not in ("insert_rows", "delete_rows"):
                continue
            sheet = op.get("sheet")
            if not sheet or sheet not in wb.sheetnames:
                continue
            row = max(1, int(op.get("row", 1)))
            count = max(1, int(op.get("count", 1)))
            dst_ws = wb[sheet]
            if kind == "delete_rows":
                dst_ws.delete_rows(idx=row, amount=count)
                continue
            dst_ws.insert_rows(idx=row, amount=count)
            source_side = str(op.get("source_side") or "").upper()
            source_rows = [int(value) for value in (op.get("source_rows") or [])]
            src_ws = None
            if source_side in ("B", "THEIRS") and wb_b is not None and sheet in wb_b.sheetnames:
                src_ws = wb_b[sheet]
            elif source_side == "A" and wb_a is not None and sheet in wb_a.sheetnames:
                src_ws = wb_a[sheet]
            elif source_side == "BASE" and wb_base is not None and sheet in wb_base.sheetnames:
                src_ws = wb_base[sheet]
            if src_ws is not None:
                max_col = max(1, int(src_ws.max_column or 1))
                for offset, source_row in enumerate(source_rows[:count]):
                    _copy_row_metadata(src_ws, dst_ws, source_row, row + offset, max_col)
        for (sheet, r, c), v in manual_ops.items():
            if sheet not in wb.sheetnames:
                continue
            _assign_edit_cell_value(wb[sheet].cell(row=int(r), column=int(c)), v)
        wb.save(out_xlsx)
        if ext_parts:
            _apply_external_link_parts_on_file(out_xlsx, ext_parts)
        _dlog(f"openpyxl merge save ok: {out_xlsx} sheet_ops={len(list(sheet_ops or []))} row_ops={len(list(row_ops or []))} cell_ops={len(manual_ops)}")
        return True
    except Exception as e:
        _dlog(f"openpyxl merge save failed: {e}")
        return False
    finally:
        _wbs_close(wb, wb_a, wb_base, wb_b)


def _merge_cmp_value(v):
    """Build a type-aware comparison key without collapsing meaningful data."""
    try:
        # Excel/openpyxl can represent a visually empty cell either as an
        # absent value (None) or as an exact zero-length string.  They render
        # identically and must not create a value diff.  Formula identity is
        # checked before this helper by the formula-aware comparison paths, so
        # this does not hide formula-vs-literal or distinct-formula changes.
        if v is None or (isinstance(v, str) and v == ""):
            return "BLANK:"
        if isinstance(v, bool):
            return "BOOL:1" if v else "BOOL:0"
        if isinstance(v, int) and not isinstance(v, bool):
            return f"NUM:{v}"
        if isinstance(v, float):
            if v == 0:
                v = 0.0
            if v.is_integer():
                return f"NUM:{int(v)}"
            return f"NUM:{repr(v)}"
        if isinstance(v, (datetime, date, datetime_time, timedelta)):
            return f"DATE:{repr(v)}"
        if isinstance(v, str):
            return "TEXT:" + v.replace("\r\n", "\n").replace("\r", "\n")
        return f"{type(v).__name__}:{_val_to_str(v)}"
    except Exception:
        return f"FALLBACK:{repr(v)}"


def _scan_formula_cache(path: str):
    """Return (has_formula, missing_cache) based on a sample scan."""
    wb_val = None
    wb_edit = None
    try:
        wb_val = load_workbook(path, data_only=True, read_only=True)
        wb_edit = load_workbook(path, data_only=False, read_only=True)
    except Exception as e:
        _dlog(f"cache check open failed: {e}")
        _wbs_close(wb_val, wb_edit)
        return False, True

    checked = 0
    has_formula = False
    missing_cache = False
    try:
        for sheet in wb_edit.sheetnames:
            ws_e = wb_edit[sheet]
            if sheet not in wb_val.sheetnames:
                continue
            ws_v = wb_val[sheet]
            max_row = max(_worksheet_scan_bounds(ws_e)[0], _worksheet_scan_bounds(ws_v)[0])
            max_col = max(_worksheet_scan_bounds(ws_e)[1], _worksheet_scan_bounds(ws_v)[1])
            edit_rows = ws_e.iter_rows(
                min_row=1, max_row=max_row, min_col=1, max_col=max_col,
                values_only=False,
            )
            value_rows = ws_v.iter_rows(
                min_row=1, max_row=max_row, min_col=1, max_col=max_col,
                values_only=False,
            )
            for edit_row, value_row in zip(edit_rows, value_rows):
                for cell, value_cell in zip(edit_row, value_row):
                    if checked >= _CACHE_CHECK_MAX_CELLS:
                        return has_formula, missing_cache
                    f = _formula_text(cell.value)
                    if not f:
                        continue
                    has_formula = True
                    checked += 1
                    v = value_cell.value
                    if v is None:
                        missing_cache = True
                        return has_formula, missing_cache
    finally:
        _wbs_close(wb_val, wb_edit)
    return has_formula, missing_cache


def _recalc_with_excel(path: str) -> str | None:
    """Use Excel COM to recalc formulas and update cached values in a temp copy."""
    try:
        base = os.path.basename(path)
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        tmp = os.path.join(tempfile.gettempdir(), f"{APP_NAME}_recalc_{os.getpid()}_{ts}_{base}")
        ext = _workbook_ext(path)
        if not tmp.lower().endswith(ext):
            tmp += ext
        shutil.copy2(path, tmp)
    except Exception as e:
        _dlog(f"recalc copy failed: {e}")
        return None

    try:
        ps = (
            "$ErrorActionPreference='Stop';"
            "$p='" + tmp.replace("'", "''") + "';"
            "$xl=$null;$wb=$null;"
            "try{"
            "$xl=New-Object -ComObject Excel.Application;"
            "$xl.Visible=$false;"
            "$xl.DisplayAlerts=$false;"
            "$xl.AskToUpdateLinks=$false;"
            "$xl.EnableEvents=$false;"
            "$wb=$xl.Workbooks.Open($p,$false,$false);"
            "try{$xl.Calculation=-4105}catch{};"
            "try{$xl.CalculateFullRebuild()}catch{};"
            "try{$wb.RefreshAll();$xl.CalculateFullRebuild()}catch{};"
            "$wb.Save();"
            "}finally{"
            "  if($wb -ne $null){try{$wb.Close($false)}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($wb)}catch{}};"
            "  if($xl -ne $null){try{$xl.Quit()}catch{};try{[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($xl)}catch{}};"
            "  [GC]::Collect();[GC]::WaitForPendingFinalizers();[GC]::Collect();[GC]::WaitForPendingFinalizers();"
            "};"
        )
        no_window = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        r = subprocess.run(
            ["powershell", "-NoProfile", "-STA", "-Command", ps],
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="replace",
            timeout=120,
            creationflags=no_window,
        )
        if r.returncode != 0:
            _dlog(f"excel recalc ps failed: {r.stderr.strip()}")
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass
            return None
        return tmp
    except Exception as e:
        _dlog(f"excel recalc failed: {e}")
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return None


def _prepare_val_path(path: str) -> str:
    if not _USE_CACHED_VALUES_ONLY or not _AUTO_RECALC_MISSING_CACHE:
        return path
    try:
        has_formula, missing_cache = _scan_formula_cache(path)
        if has_formula and (_AUTO_RECALC_FORMULAS_ALWAYS or missing_cache):
            _dlog(f"formula cache recalc: has_formula={has_formula} missing_cache={missing_cache} path={path}")
            tmp = _recalc_with_excel(path)
            if tmp:
                _dlog(f"recalc cache OK: {tmp}")
                return tmp
    except Exception as e:
        _dlog(f"prepare val path failed: {e}")
    return path


def _recalc_and_prepare_val_path(path: str) -> str | None:
    """Force Excel recalc to refresh cached values and return temp path."""
    try:
        tmp = _recalc_with_excel(path)
        return tmp
    except Exception:
        return None


def _maybe_recalc_and_prepare_val_path(path: str, force: bool = False) -> str | None:
    """Recalc only when needed, unless forced by the caller."""
    if not path:
        return None
    try:
        if not force:
            if not (_AUTO_RECALC_FORMULAS_ALWAYS or _AUTO_RECALC_MISSING_CACHE):
                return None
            has_formula, missing_cache = _scan_formula_cache(path)
            if not has_formula:
                return None
            if not (_AUTO_RECALC_FORMULAS_ALWAYS or (_AUTO_RECALC_MISSING_CACHE and missing_cache)):
                return None
        return _recalc_and_prepare_val_path(path)
    except Exception as e:
        _dlog(f"maybe recalc path failed: path={path} err={e}")
        return None


def _launch_deferred_copy(src: str, dst: str, retries: int = 60, delay_ms: int = 500) -> bool:
    """Launch a background copy that retries for a while (to avoid lock issues).

    Returns True if the background process was successfully launched, False
    otherwise. A False result means the deferred copy did NOT start, so callers
    must NOT report success to the user.
    """
    try:
        ps = (
            "$src='" + src.replace("'", "''") + "';"
            "$dst='" + dst.replace("'", "''") + "';"
            f"for($i=0;$i -lt {retries};$i++){{"
            "try{Copy-Item -LiteralPath $src -Destination $dst -Force;"
            "Remove-Item -LiteralPath $src -Force;exit 0}catch{Start-Sleep -Milliseconds "
            f"{delay_ms}}};exit 1"
        )
        creationflags = 0
        try:
            creationflags = subprocess.CREATE_NO_WINDOW
        except Exception:
            creationflags = 0
        subprocess.Popen(["powershell", "-NoProfile", "-Command", ps], creationflags=creationflags)
        return True
    except Exception as e:
        _dlog(f"deferred copy launch failed: {e}")
        return False


def _find_tortoise_merge_exe():
    candidates = [
        os.path.join(os.environ.get("ProgramFiles", r"C:\Program Files"), "TortoiseSVN", "bin", "TortoiseMerge.exe"),
        os.path.join(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"), "TortoiseSVN", "bin", "TortoiseMerge.exe"),
    ]
    for p in candidates:
        if os.path.exists(p):
            return p
    return "TortoiseMerge.exe"


def _find_tortoise_proc_exe():
    candidates = [
        os.path.join(os.environ.get("ProgramFiles", r"C:\Program Files"), "TortoiseSVN", "bin", "TortoiseProc.exe"),
        os.path.join(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"), "TortoiseSVN", "bin", "TortoiseProc.exe"),
    ]
    for p in candidates:
        if os.path.exists(p):
            return p
    return "TortoiseProc.exe"


def _find_svn_cli_exe() -> str | None:
    """Resolve svn.exe from PATH first, then common TortoiseSVN install paths."""
    p = shutil.which("svn")
    if p:
        return p
    candidates = [
        os.path.join(os.environ.get("ProgramFiles", r"C:\Program Files"), "TortoiseSVN", "bin", "svn.exe"),
        os.path.join(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"), "TortoiseSVN", "bin", "svn.exe"),
    ]
    for c in candidates:
        try:
            if os.path.exists(c):
                return c
        except Exception:
            pass
    return None


def _query_svn_version(svn_exe: str) -> str:
    try:
        no_window = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        out = subprocess.run(
            [svn_exe, "--version", "--quiet"],
            capture_output=True,
            text=True,
            errors="replace",
            timeout=8,
            creationflags=no_window,
        )
        if out.returncode == 0:
            return (out.stdout or "").strip()
    except Exception:
        pass
    return ""


def _workbook_package_ready(path: str) -> bool:
    """Return True only for a complete, readable OOXML workbook package."""
    try:
        if not path or not os.path.isfile(path) or os.path.getsize(path) <= 0:
            return False
        with zipfile.ZipFile(path, "r") as zf:
            names = set(zf.namelist())
            if "[Content_Types].xml" not in names or "xl/workbook.xml" not in names:
                return False
            return zf.testzip() is None
    except (OSError, zipfile.BadZipFile, EOFError):
        return False


def _sha256_file(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as source:
        while True:
            block = source.read(1024 * 1024)
            if not block:
                break
            digest.update(block)
    return digest.hexdigest()


@dataclass
class _PackageFingerprint:
    path: str
    sha256: str | None
    members: dict[str, tuple[int, str]] = field(default_factory=dict)
    payloads: dict[str, bytes] = field(default_factory=dict)
    ready: bool = False
    reason: str = ""
    elapsed_seconds: float = 0.0


_PACKAGE_FINGERPRINT_CACHE: dict[tuple[str, int, int], _PackageFingerprint] = {}


def _ooxml_package_fingerprint(path: str | None) -> _PackageFingerprint:
    """Read a stable package once for all matrix pair comparisons.

    The manifest accelerates obvious inequality; retained uncompressed member
    bytes are compared directly in the equality decision, including VBA blobs.
    """
    started = time.perf_counter()
    if not path:
        return _PackageFingerprint("", None, reason="missing input path", elapsed_seconds=time.perf_counter() - started)
    signature = _workbook_sig(path)
    cached = _PACKAGE_FINGERPRINT_CACHE.get(signature)
    if cached is not None:
        return cached
    fingerprint = _PackageFingerprint(str(path), None)
    try:
        if not _workbook_package_ready(path):
            fingerprint.reason = "input is not a complete OOXML package"
            return fingerprint
        fingerprint.sha256 = _sha256_file(path)
        with zipfile.ZipFile(path, "r") as package:
            raw_names = [name for name in package.namelist() if not name.endswith("/")]
            if len(set(raw_names)) != len(raw_names):
                fingerprint.reason = "duplicate OOXML package member names"
                return fingerprint
            for name in sorted(raw_names):
                payload = package.read(name)
                fingerprint.payloads[name] = payload
                fingerprint.members[name] = (len(payload), hashlib.sha256(payload).hexdigest())
        fingerprint.ready = True
        fingerprint.reason = "complete package fingerprint"
        return fingerprint
    except (OSError, zipfile.BadZipFile, EOFError, RuntimeError) as exc:
        fingerprint.reason = f"package fingerprint failed: {exc}"
        return fingerprint
    except Exception as exc:
        fingerprint.reason = f"package fingerprint unexpected error: {exc}"
        return fingerprint
    finally:
        fingerprint.elapsed_seconds = time.perf_counter() - started
        _PACKAGE_FINGERPRINT_CACHE[signature] = fingerprint
        _dlog(
            f"PACKAGE_FINGERPRINT path={path} ready={fingerprint.ready} "
            f"members={len(fingerprint.members)} elapsed_ms={fingerprint.elapsed_seconds * 1000.0:.1f} "
            f"reason={fingerprint.reason}"
        )


def compare_ooxml_packages(
    left_path: str | None,
    right_path: str | None,
    *,
    left_role: str = "left",
    right_role: str = "right",
) -> PackageComparison:
    """Compare complete OOXML packages by uncompressed member bytes.

    ZIP entry timestamps, ordering, compression levels, and container comments
    are intentionally ignored.  Every non-directory member (including
    ``xl/vbaProject.bin``) must exist on both sides and have identical bytes.
    Any read/package failure is ``None`` (unknown), never equality.
    """
    started = time.perf_counter()
    left = _ooxml_package_fingerprint(left_path)
    right = _ooxml_package_fingerprint(right_path)
    if not left.ready or not right.ready:
        reason = f"left: {left.reason}; right: {right.reason}"
        return PackageComparison(
            left_role, right_role, left_path, right_path, left.sha256, right.sha256,
            None, False, time.perf_counter() - started, reason,
        )
    if tuple(left.members) != tuple(right.members):
        return PackageComparison(
            left_role, right_role, left_path, right_path, left.sha256, right.sha256,
            False, True, time.perf_counter() - started, "OOXML member set differs",
        )
    for member, manifest in left.members.items():
        if right.members.get(member) != manifest:
            return PackageComparison(
                left_role, right_role, left_path, right_path, left.sha256, right.sha256,
                False, True, time.perf_counter() - started, f"OOXML member bytes differ: {member}",
            )
        # A member digest never alone proves equality.  Compare the actual
        # uncompressed bytes retained by the one-pass package scan.
        if left.payloads.get(member) != right.payloads.get(member):
            return PackageComparison(
                left_role, right_role, left_path, right_path, left.sha256, right.sha256,
                False, True, time.perf_counter() - started, f"OOXML member bytes differ: {member}",
            )
    return PackageComparison(
        left_role, right_role, left_path, right_path, left.sha256, right.sha256,
        True, True, time.perf_counter() - started, "all OOXML member bytes are identical",
    )


_OOXML_MAIN_NS = "http://schemas.openxmlformats.org/spreadsheetml/2006/main"
_OOXML_REL_NS = "http://schemas.openxmlformats.org/officeDocument/2006/relationships"
_OOXML_PACKAGE_REL_NS = "http://schemas.openxmlformats.org/package/2006/relationships"


def _canonical_ooxml_xml(element: ET.Element):
    """Return a whitespace-insensitive, attribute-order-stable XML value."""
    text = (element.text or "").strip()
    return (
        element.tag,
        tuple(sorted((str(key), str(value)) for key, value in element.attrib.items())),
        text,
        tuple(_canonical_ooxml_xml(child) for child in list(element)),
    )


def _ooxml_sheet_part_map(payloads: dict[str, bytes]) -> dict[str, str]:
    """Resolve workbook sheet names to their worksheet package member paths."""
    try:
        workbook = ET.fromstring(payloads["xl/workbook.xml"])
        relationships = ET.fromstring(payloads["xl/_rels/workbook.xml.rels"])
        targets = {
            relation.attrib.get("Id"): relation.attrib.get("Target", "")
            for relation in relationships.findall(f"{{{_OOXML_PACKAGE_REL_NS}}}Relationship")
        }
        result = {}
        for sheet in workbook.findall(f".//{{{_OOXML_MAIN_NS}}}sheet"):
            name = sheet.attrib.get("name")
            relationship_id = sheet.attrib.get(f"{{{_OOXML_REL_NS}}}id")
            target = targets.get(relationship_id)
            if not name or not target:
                continue
            normalized = posixpath.normpath(posixpath.join("xl", target)).lstrip("/")
            if normalized in payloads:
                result[str(name)] = normalized
        return result
    except Exception:
        return {}


def _shared_string_semantic_tokens(payload: bytes | None) -> tuple[str, ...] | None:
    """Decode shared-string table entries into stable semantic tokens."""
    if payload is None:
        return ()
    try:
        root = ET.fromstring(payload)
        tokens = []
        for item in root.findall(f"{{{_OOXML_MAIN_NS}}}si"):
            canonical = repr(_canonical_ooxml_xml(item)).encode("utf-8", "surrogatepass")
            tokens.append(hashlib.sha256(canonical).hexdigest())
        return tuple(tokens)
    except Exception:
        return None


def _normalized_worksheet_payload(
    payload: bytes,
    allowed_cells: set[str],
    *,
    shared_string_tokens: tuple[str, ...] | None = None,
) -> object | None:
    """Ignore only value/formula payloads for explicitly changed cells.

    Cell style attributes, comments/metadata attributes, sheet properties,
    merged ranges, dimensions and every other worksheet node deliberately stay
    in the canonical representation.  A difference in any of them is not a
    value/formula merge and therefore cannot be silently projected.
    """
    try:
        root = ET.fromstring(payload)
        cell_tag = f"{{{_OOXML_MAIN_NS}}}c"
        row_tag = f"{{{_OOXML_MAIN_NS}}}row"
        value_tags = {
            f"{{{_OOXML_MAIN_NS}}}v",
            f"{{{_OOXML_MAIN_NS}}}f",
            f"{{{_OOXML_MAIN_NS}}}is",
        }
        # Excel persists the user's active selection and scroll origin in the
        # worksheet view.  They are not workbook content.  Preserve split and
        # frozen-pane structure while removing only selection/focus fields.
        for sheet_view in root.findall(f".//{{{_OOXML_MAIN_NS}}}sheetView"):
            sheet_view.attrib.pop("tabSelected", None)
            for child in list(sheet_view):
                local_name = child.tag.rsplit("}", 1)[-1]
                if local_name == "selection":
                    sheet_view.remove(child)
                elif local_name == "pane":
                    child.attrib.pop("topLeftCell", None)
                    child.attrib.pop("activePane", None)
        for row in root.findall(f".//{row_tag}"):
            for cell in list(row):
                if cell.tag != cell_tag:
                    continue
                reference = cell.attrib.get("r")
                is_allowed = reference in allowed_cells
                if cell.attrib.get("t") == "s" and not is_allowed:
                    shared_index = cell.find(f"{{{_OOXML_MAIN_NS}}}v")
                    try:
                        index = int((shared_index.text or "").strip()) if shared_index is not None else -1
                    except (TypeError, ValueError):
                        return None
                    if (
                        shared_string_tokens is None
                        or index < 0
                        or index >= len(shared_string_tokens)
                        or shared_index is None
                    ):
                        return None
                    # Shared-string indexes are package-local and Excel can
                    # reindex the entire table on one unrelated text edit.
                    # Compare the resolved string semantics at every unchanged
                    # coordinate, never the transient table index.
                    shared_index.text = f"sow-shared:{shared_string_tokens[index]}"
                has_formula = cell.find(f"{{{_OOXML_MAIN_NS}}}f") is not None
                # Formula cache values are recalc artifacts, not source edits;
                # retain and compare the formula itself unless it is an
                # explicitly changed formula coordinate.
                if has_formula and not is_allowed:
                    for child in list(cell):
                        if child.tag == f"{{{_OOXML_MAIN_NS}}}v":
                            cell.remove(child)
                    continue
                if not is_allowed:
                    continue
                # Cell type is payload.  A default-style blank cell that was
                # materialized only to hold a new value is semantically the
                # same as a missing cell once its payload is removed.  Keep
                # every non-default style/metadata attribute so it remains a
                # visible unsupported representation change.
                cell.attrib.pop("t", None)
                if cell.attrib.get("s") == "0":
                    cell.attrib.pop("s", None)
                for child in list(cell):
                    if child.tag in value_tags:
                        cell.remove(child)
                if set(cell.attrib) == {"r"} and not list(cell):
                    row.remove(cell)
            # A newly materialized default row for a blank-to-value change is
            # likewise equivalent to no row.  Row height/style/hidden/etc.
            # remain, and therefore still fail the representation audit.
            if not list(row) and set(row.attrib) == {"r"}:
                parent = next(
                    (node for node in root.iter() if row in list(node)),
                    None,
                )
                if parent is not None:
                    parent.remove(row)
        return _canonical_ooxml_xml(root)
    except Exception:
        return None


def _shared_string_references(
    worksheet_payloads: dict[str, bytes],
    allowed_cells_by_member: dict[str, set[str]],
) -> tuple[set[int], bool]:
    """Return shared-string entries referenced only by allowed changed cells."""
    allowed_indexes: set[int] = set()
    disallowed_indexes: set[int] = set()
    try:
        for member, payload in worksheet_payloads.items():
            root = ET.fromstring(payload)
            allowed_cells = allowed_cells_by_member.get(member, set())
            for cell in root.findall(f".//{{{_OOXML_MAIN_NS}}}c"):
                if cell.attrib.get("t") != "s":
                    continue
                value = cell.find(f"{{{_OOXML_MAIN_NS}}}v")
                try:
                    index = int((value.text or "").strip()) if value is not None else -1
                except (TypeError, ValueError):
                    return set(), False
                if index < 0:
                    return set(), False
                if cell.attrib.get("r") in allowed_cells:
                    allowed_indexes.add(index)
                else:
                    disallowed_indexes.add(index)
    except Exception:
        return set(), False
    return allowed_indexes - disallowed_indexes, True


def _normalized_shared_strings_payload(payload: bytes, allowed_indexes: set[int]) -> object | None:
    try:
        root = ET.fromstring(payload)
        root.attrib.pop("count", None)
        root.attrib.pop("uniqueCount", None)
        for index, item in enumerate(root.findall(f"{{{_OOXML_MAIN_NS}}}si")):
            if index not in allowed_indexes:
                continue
            for child in list(item):
                item.remove(child)
            item.text = None
        return _canonical_ooxml_xml(root)
    except Exception:
        return None


def _normalized_content_types_payload(payload: bytes, *, allow_shared_strings: bool, allow_calc_chain: bool) -> object | None:
    try:
        root = ET.fromstring(payload)
        for child in list(root):
            part_name = str(child.attrib.get("PartName") or "")
            if (
                (allow_shared_strings and part_name == "/xl/sharedStrings.xml")
                or (allow_calc_chain and part_name == "/xl/calcChain.xml")
            ):
                root.remove(child)
        return _canonical_ooxml_xml(root)
    except Exception:
        return None


def _normalized_workbook_relationships_payload(payload: bytes, *, allow_shared_strings: bool, allow_calc_chain: bool) -> object | None:
    try:
        root = ET.fromstring(payload)
        for child in list(root):
            target = str(child.attrib.get("Target") or "").replace("\\", "/")
            if (
                (allow_shared_strings and target.endswith("sharedStrings.xml"))
                or (allow_calc_chain and target.endswith("calcChain.xml"))
            ):
                root.remove(child)
        return _canonical_ooxml_xml(root)
    except Exception:
        return None


def _normalized_workbook_payload(payload: bytes, *, allow_formula_delta: bool) -> object | None:
    try:
        root = ET.fromstring(payload)
        if allow_formula_delta:
            for calc_properties in root.findall(f"{{{_OOXML_MAIN_NS}}}calcPr"):
                root.remove(calc_properties)
        # Excel rewrites window placement and its revision-pointer GUID on a
        # normal save.  They are UI/save-session metadata, unlike activeTab,
        # sheets, definedNames and other workbook semantics which remain in
        # the canonical comparison below.
        for parent in root.iter():
            for child in list(parent):
                if child.tag.rsplit("}", 1)[-1] == "revisionPtr":
                    parent.remove(child)
            if parent.tag.rsplit("}", 1)[-1] == "workbookView":
                parent.attrib.pop("xWindow", None)
                parent.attrib.pop("yWindow", None)
        return _canonical_ooxml_xml(root)
    except Exception:
        return None


def _normalized_core_properties_payload(payload: bytes) -> object | None:
    """Ignore only save-volatile core properties, never user metadata."""
    try:
        root = ET.fromstring(payload)
        volatile = {"{http://purl.org/dc/terms/}modified"}
        for child in list(root):
            if child.tag in volatile:
                root.remove(child)
        return _canonical_ooxml_xml(root)
    except Exception:
        return None


def _cross_branch_ooxml_representation_audit(
    source_before_path: str,
    source_after_path: str,
    changed_cells_by_sheet: dict[str, set[str]],
    *,
    has_formula_content: bool,
    has_string_delta: bool,
) -> str | None:
    """Reject source package changes that cannot be represented as cell edits.

    The cross-branch writer copies only values/formulas into Target Working.
    This audit proves that the source package changed *only* at those explicit
    cell payloads.  Any style, comment, sheet property, document property,
    drawing, relation or other OOXML member is an additional incoming change
    and must be shown as manual work instead of being silently discarded.
    """
    before = _ooxml_package_fingerprint(source_before_path)
    after = _ooxml_package_fingerprint(source_after_path)
    if not before.ready or not after.ready:
        return f"Source OOXML representation audit unavailable: before={before.reason}; after={after.reason}"
    if before.members == after.members and all(
        before.payloads.get(member) == after.payloads.get(member)
        for member in before.members
    ):
        return None

    before_sheet_parts = _ooxml_sheet_part_map(before.payloads)
    after_sheet_parts = _ooxml_sheet_part_map(after.payloads)
    if set(before_sheet_parts) != set(after_sheet_parts):
        return "Source workbook sheet-member mapping changed"
    allowed_cells_by_member: dict[str, set[str]] = {}
    for sheet, cells in changed_cells_by_sheet.items():
        before_member = before_sheet_parts.get(sheet)
        after_member = after_sheet_parts.get(sheet)
        if not before_member or before_member != after_member:
            return f"Source worksheet member is unavailable for {sheet}"
        allowed_cells_by_member.setdefault(before_member, set()).update(cells)

    before_shared_tokens = _shared_string_semantic_tokens(before.payloads.get("xl/sharedStrings.xml"))
    after_shared_tokens = _shared_string_semantic_tokens(after.payloads.get("xl/sharedStrings.xml"))
    if before_shared_tokens is None or after_shared_tokens is None:
        return "Source sharedStrings representation could not be decoded"

    # Shared strings are an encoding table, not a distinct workbook feature.
    # All unlisted worksheet coordinates are proven unchanged by the cell
    # classification above, so a string payload change may legitimately rebuild
    # or reindex the whole table (including indices shared by unchanged cells).
    # Once each worksheet is compared through its resolved string semantics,
    # sharedStrings is only an encoding table.  Its member can reorder even
    # when the source has no logical cell delta, so never treat its raw bytes
    # as a separate incoming change.
    allow_shared_strings = True

    member_names = set(before.payloads) | set(after.payloads)
    for member in sorted(member_names):
        before_payload = before.payloads.get(member)
        after_payload = after.payloads.get(member)
        if before_payload == after_payload:
            continue
        if member.startswith("xl/worksheets/") and member.endswith(".xml"):
            # A source text edit can rebuild sharedStrings and reindex cells
            # on worksheets with no direct source delta.  Normalize every
            # worksheet through resolved shared-string semantics; a real style
            # or other non-payload change still survives and fails below.
            allowed_cells = allowed_cells_by_member.get(member, set())
            normalized_before = _normalized_worksheet_payload(
                before_payload or b"",
                allowed_cells,
                shared_string_tokens=before_shared_tokens,
            )
            normalized_after = _normalized_worksheet_payload(
                after_payload or b"",
                allowed_cells,
                shared_string_tokens=after_shared_tokens,
            )
        elif member == "xl/sharedStrings.xml" and allow_shared_strings:
            continue
        elif member == "xl/calcChain.xml" and has_formula_content:
            # Formula recalculation bookkeeping is not a user-visible source
            # edit.  Formula cell XML remains covered by its worksheet audit.
            continue
        elif member == "xl/workbook.xml":
            normalized_before = _normalized_workbook_payload(
                before_payload or b"", allow_formula_delta=has_formula_content
            )
            normalized_after = _normalized_workbook_payload(
                after_payload or b"", allow_formula_delta=has_formula_content
            )
        elif member == "docProps/core.xml":
            normalized_before = _normalized_core_properties_payload(before_payload or b"")
            normalized_after = _normalized_core_properties_payload(after_payload or b"")
        elif member == "[Content_Types].xml" and (allow_shared_strings or has_formula_content):
            normalized_before = _normalized_content_types_payload(
                before_payload or b"",
                allow_shared_strings=allow_shared_strings,
                allow_calc_chain=has_formula_content,
            )
            normalized_after = _normalized_content_types_payload(
                after_payload or b"",
                allow_shared_strings=allow_shared_strings,
                allow_calc_chain=has_formula_content,
            )
        elif member == "xl/_rels/workbook.xml.rels" and (allow_shared_strings or has_formula_content):
            normalized_before = _normalized_workbook_relationships_payload(
                before_payload or b"",
                allow_shared_strings=allow_shared_strings,
                allow_calc_chain=has_formula_content,
            )
            normalized_after = _normalized_workbook_relationships_payload(
                after_payload or b"",
                allow_shared_strings=allow_shared_strings,
                allow_calc_chain=has_formula_content,
            )
        else:
            return f"Unsupported Source OOXML member change: {member}"
        if normalized_before is None or normalized_after is None or normalized_before != normalized_after:
            return f"Unsupported Source OOXML representation change: {member}"
    return None


def _available_identities(
    identities: dict[str, VersionIdentity] | MergeLaunchContext,
) -> dict[str, VersionIdentity]:
    if isinstance(identities, MergeLaunchContext):
        # A launch context has four declared semantic roles even when the
        # local WC pristine cannot be materialized.  Keep unavailable roles in
        # the matrix so all six pair decisions are logged as fail-closed
        # evidence instead of silently disappearing.
        return {
            str(role).lower(): identity
            for role, identity in (identities.identities or {}).items()
            if isinstance(identity, VersionIdentity)
        }
    return {
        str(role).lower(): identity
        for role, identity in (identities or {}).items()
        if isinstance(identity, VersionIdentity) and identity.available
    }


def build_equivalence_matrix(
    identities: dict[str, VersionIdentity] | MergeLaunchContext,
) -> EquivalenceMatrix:
    """Build and log every available identity pair before any automatic action."""
    available = _available_identities(identities)
    matrix = EquivalenceMatrix()
    roles = sorted(available)
    for left_idx, left_role in enumerate(roles):
        for right_role in roles[left_idx + 1:]:
            left = available[left_role]
            right = available[right_role]
            result = compare_ooxml_packages(
                left.effective_path,
                right.effective_path,
                left_role=left_role,
                right_role=right_role,
            )
            matrix.comparisons[(left_role, right_role)] = result
            _dlog(
                "EQUIVALENCE "
                f"{left_role}<->{right_role} ready={result.ready} raw_sha_equal={result.raw_hash_equal} "
                f"package_equal={result.package_equal} elapsed_ms={result.elapsed_seconds * 1000.0:.1f} "
                f"reason={result.reason}"
            )
    if not matrix.comparisons:
        _dlog("EQUIVALENCE matrix has no comparable input pairs")
    return matrix


def decide_startup_merge_outcome(
    context: MergeLaunchContext,
    matrix: EquivalenceMatrix,
) -> StartupMergeOutcome:
    """Select only a proven whole-workbook convergence action and fold target."""
    outcome = StartupMergeOutcome()
    is_three_way = bool(context.source_base_path and context.mine_path and context.theirs_path)
    if not is_three_way:
        return outcome

    mine_base = matrix.are_equal("mine", "base")
    theirs_base = matrix.are_equal("theirs", "base")
    mine_theirs = matrix.are_equal("mine", "theirs")
    if mine_base:
        outcome.equality_evidence.append("Mine ≡ Base")
    if theirs_base:
        outcome.equality_evidence.append("Theirs ≡ Base")
    if mine_theirs:
        outcome.equality_evidence.append("Mine ≡ Theirs")

    # A non-empty branch merge must always reach source-delta classification,
    # even when Target Working happens to equal Source Before or Source After.
    # Whole-package convergence can initialize a file, but it cannot supply the
    # required incoming/applied/already-present audit counters.  The only branch
    # fast path is the proven empty source delta.
    if context.scenario == MergeScenario.CROSS_BRANCH_MERGE:
        if theirs_base:
            outcome.automatic_action = "initialize-from-mine-empty-branch-delta"
            outcome.source_role = "mine"
            outcome.equality_evidence.append("source Base ≡ source-right/Theirs")
        else:
            outcome.fallback_reasons.append(
                "non-empty source delta requires Source Before-to-Source After classification"
            )
    elif mine_theirs:
        outcome.automatic_action = "initialize-from-common-mine-theirs"
        outcome.source_role = "mine"
        if "Mine ≡ Theirs" not in outcome.equality_evidence:
            outcome.equality_evidence.append("Mine ≡ Theirs")
    elif mine_base and not theirs_base:
        outcome.automatic_action = "initialize-from-theirs"
        outcome.source_role = "theirs"
    elif theirs_base and not mine_base:
        outcome.automatic_action = "initialize-from-mine"
        outcome.source_role = "mine"
    else:
        outcome.fallback_reasons.append("no complete package equality proves whole-workbook convergence")

    # The center pane shows the initialized Merged candidate, not a mutable
    # alias of raw Mine.  Fold the pane that is redundant to what remains
    # visible after candidate initialization.
    if context.scenario == MergeScenario.CROSS_BRANCH_MERGE:
        if theirs_base:
            outcome.folded_identity = "base"
    elif outcome.source_role == "theirs":
        outcome.folded_identity = "theirs"
    elif mine_theirs:
        outcome.folded_identity = "theirs"
    elif theirs_base:
        outcome.folded_identity = "base"
    elif mine_base:
        outcome.folded_identity = "base"
    _dlog(
        "STARTUP_OUTCOME decision "
        f"action={outcome.automatic_action} source={outcome.source_role} fold={outcome.folded_identity} "
        f"evidence={outcome.equality_evidence} fallback={outcome.fallback_reasons}"
    )
    return outcome


def _find_svn_wc_root_for_path(path: str | None) -> str | None:
    probe = os.path.dirname(os.path.abspath(path)) if path else ""
    while probe:
        if os.path.isfile(os.path.join(probe, ".svn", "wc.db")):
            return probe
        parent = os.path.dirname(probe)
        if not parent or parent == probe:
            break
        probe = parent
    return None


def _parse_svn_skel(conflict_data: bytes | str | None):
    """Parse the small, s-expression-like subset used by SVN conflict skels.

    Working-copy ``ACTUAL_NODE.conflict_data`` is a binary SVN *skel*, not a
    public XML or JSON format.  In practice the merge-source records are
    represented by nested lists and length-prefixed atoms.  We intentionally
    parse just those stable primitives here rather than guessing a target
    repository path from a sidecar filename.  Malformed input returns an empty
    list so callers can retain the supplied sidecar identity as a safe fallback.
    """
    if conflict_data is None:
        return []
    # SVN skel atom lengths count bytes, not Python Unicode code points.  Keep
    # the cursor on raw bytes and decode only complete atoms; a Chinese source
    # path therefore cannot shift the following source node boundary.
    raw_data = (
        bytes(conflict_data)
        if isinstance(conflict_data, bytes)
        else str(conflict_data).encode("utf-8", errors="surrogatepass")
    )
    length = len(raw_data)
    position = 0

    def _skip_space():
        nonlocal position
        while position < length and raw_data[position] in b" \t\r\n":
            position += 1

    def _decode_atom(value: bytes) -> str:
        return value.decode("utf-8", errors="replace")

    def _read_node():
        nonlocal position
        _skip_space()
        if position >= length:
            return None
        if raw_data[position] == ord("("):
            position += 1
            values = []
            while True:
                _skip_space()
                if position >= length:
                    # A truncated WC record is not evidence we can use.
                    return None
                if raw_data[position] == ord(")"):
                    position += 1
                    return values
                item = _read_node()
                if item is None:
                    return None
                values.append(item)
        if raw_data[position] == ord(")"):
            return None

        start = position
        while position < length and ord("0") <= raw_data[position] <= ord("9"):
            position += 1
        if position > start:
            atom_length = int(raw_data[start:position])
            delimiter = raw_data[position] if position < length else None
            if delimiter == ord(":"):
                position += 1
                if position + atom_length <= length:
                    atom = _decode_atom(raw_data[position:position + atom_length])
                    position += atom_length
                    return atom
            elif delimiter in b" \t\r\n":
                # SVN's canonical form is ``<length> <atom>``.  Only consume
                # it when the declared atom fits, otherwise this was simply a
                # numeric revision token such as ``37073``.
                payload_start = position + 1
                if payload_start + atom_length <= length:
                    atom = _decode_atom(raw_data[payload_start:payload_start + atom_length])
                    position = payload_start + atom_length
                    return atom
            position = start

        start = position
        while position < length and raw_data[position] not in b" \t\r\n()":
            position += 1
        return _decode_atom(raw_data[start:position]) if position > start else None

    parsed = _read_node()
    _skip_space()
    return parsed if parsed is not None and position >= length else []


def _svn_skel_atoms(node) -> list[str]:
    """Flatten a parsed skel while preserving the order SVN wrote its atoms."""
    if isinstance(node, str):
        return [node]
    if not isinstance(node, list):
        return []
    atoms: list[str] = []
    for child in node:
        atoms.extend(_svn_skel_atoms(child))
    return atoms


def _normalise_svn_repository_path(value: str) -> str | None:
    cleaned = str(value or "").strip().strip("\"'")
    match = re.search(r"((?:[^()\s/]+/)+[^()\s/]+\.(?:xlsx|xlsm))", cleaned, re.IGNORECASE)
    if not match:
        return None
    return match.group(1).replace("\\", "/").lstrip("/")


def _svn_source_node_from_atoms(atoms: list[str]) -> tuple[str, int] | None:
    """Return one ``repository-relative path, revision`` pair from a skel node."""
    for index, atom in enumerate(atoms):
        repository_path = _normalise_svn_repository_path(atom)
        if not repository_path:
            continue
        revision = None
        # SVN's merge source node stores ``peg-rev`` followed by operative
        # revision (for example ``... Building.xlsx 5 37073 file``).  Search
        # backwards through the trailing fields so the operative revision wins.
        for nearby in list(reversed(atoms[index + 1:])) + list(reversed(atoms[:index])):
            match = re.fullmatch(r"r?(\d+)", str(nearby or "").strip(), re.IGNORECASE)
            if match:
                revision = int(match.group(1))
                break
        if revision is not None:
            return repository_path, revision
    return None


def _extract_svn_conflict_source_nodes(conflict_data: bytes | str | None) -> list[tuple[str, int]]:
    """Extract ordered merge-source nodes from a WC conflict skel.

    Newer SVN clients store two ``subversion`` source nodes for a merge.  The
    order is meaningful: first is Source Before and second is Source After.
    Be deliberately strict about needing a workbook path and explicit revision;
    incomplete records are not promoted over raw sidecar evidence.
    """
    parsed = _parse_svn_skel(conflict_data)
    candidates: list[tuple[str, int]] = []

    def _walk(node):
        if not isinstance(node, list):
            return
        atoms = _svn_skel_atoms(node)
        # Do not treat a wrapper containing two source nodes as a source node
        # itself: flattening that wrapper would accidentally pair Source Before
        # with Source After's final revision.
        if node and isinstance(node[0], str) and node[0].strip().lower() == "subversion":
            source = _svn_source_node_from_atoms(atoms[1:])
            if source is not None:
                candidates.append(source)
        for child in node:
            _walk(child)

    _walk(parsed)
    if not candidates:
        # Some SVN builds wrap the same source information in an opaque atom.
        # Preserve list order by pairing each workbook path with the first
        # adjacent revision token after it, then before it if necessary.
        atoms = _svn_skel_atoms(parsed)
        candidates = [
            source for source in (_svn_source_node_from_atoms(atoms),)
            if source is not None
        ]
    return candidates


def _read_cross_branch_sources_from_wc(
    wc_root: str,
    local_relpath: str,
) -> tuple[list[tuple[str, int]], str]:
    """Read exact Source Before/After identity evidence from ``ACTUAL_NODE``."""
    db_path = os.path.join(wc_root, ".svn", "wc.db")
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as conn:
            rows = conn.execute(
                """
                select conflict_data
                from ACTUAL_NODE
                where local_relpath = ? and conflict_data is not null
                """,
                (local_relpath.replace("\\", "/"),),
            ).fetchall()
        if len(rows) != 1:
            return [], (
                "ACTUAL_NODE conflict-data lookup is ambiguous"
                if rows else "ACTUAL_NODE has no conflict-data row for target"
            )
        sources = _extract_svn_conflict_source_nodes(rows[0][0])
        if len(sources) != 2:
            return [], "ACTUAL_NODE has no exact two-node merge source record"
        before, after = sources
        if before[0] != after[0] or before[1] >= after[1]:
            return [], "ACTUAL_NODE source nodes do not prove one increasing revision path"
        return sources, "wc-conflict-data"
    except Exception as exc:
        return [], f"ACTUAL_NODE conflict-data lookup failed: {exc}"


def resolve_cross_branch_source_metadata(context: MergeLaunchContext) -> None:
    """Promote WC-recorded source paths/revisions over sidecar suffix guesses."""
    if context.scenario != MergeScenario.CROSS_BRANCH_MERGE:
        return
    _dlog(
        "MERGE_ROLE_SEMANTICS "
        "scenario=cross-branch-merge base=Source Before theirs=Source After "
        "mine=Target Working target_pristine=Target Pristine"
    )
    anchor = context.merged_path or context.mine_path
    wc_root = _find_svn_wc_root_for_path(anchor)
    if wc_root and anchor:
        relpath = os.path.relpath(os.path.abspath(anchor), wc_root).replace("\\", "/")
        sources, reason = _read_cross_branch_sources_from_wc(wc_root, relpath)
        if len(sources) == 2:
            for role, (repository_path, revision) in zip(("base", "theirs"), sources):
                identity = context.identity_for(role)
                if identity is None:
                    continue
                identity.repository_identity = repository_path
                identity.revision = revision
                _dlog(
                    "SVN_CONFLICT_SOURCE "
                    f"role={role} repository_path={repository_path} revision=r{revision} "
                    "source=wc-conflict-data"
                )
            return
    else:
        reason = "target working-copy root unavailable"

    for role in ("base", "theirs"):
        identity = context.identity_for(role)
        if identity is not None:
            _dlog(
                "SVN_CONFLICT_SOURCE_FALLBACK "
                f"role={role} sidecar_path={identity.path!r} revision={identity.revision!r} reason={reason}"
            )


def _wc_node_metadata(wc_root: str, local_relpath: str) -> tuple[int | None, str | None, str]:
    """Return current WC BASE last-change metadata, read-only and locally."""
    db_path = os.path.join(wc_root, ".svn", "wc.db")
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as conn:
            row = conn.execute(
                """
                select changed_revision, changed_author
                from NODES
                where local_relpath = ? and op_depth = 0 and kind = 'file'
                  and presence = 'normal'
                limit 1
                """,
                (local_relpath.replace("\\", "/"),),
            ).fetchone()
        if row:
            return (int(row[0]) if row[0] is not None else None, row[1], "wc-db-current-node")
        return None, None, "wc.db has no normal file node"
    except Exception as exc:
        return None, None, f"wc.db current-node lookup failed: {exc}"


def _wc_author_for_exact_sidecar_revision(
    wc_root: str,
    basename: str,
    revision: int,
    *,
    repository_identity: str | None = None,
) -> tuple[str | None, str]:
    """Find an exact WC author record; never infer it from a revision alone.

    Cross-branch conflict metadata supplies a repository-relative source path.
    Once present, that path is authoritative: a missing exact row must remain
    unknown rather than falling back to a same-basename file in Target Working
    or another branch.
    """
    db_path = os.path.join(wc_root, ".svn", "wc.db")
    source_path = str(repository_identity or "").replace("\\", "/").strip().lstrip("/")
    if source_path:
        try:
            with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as conn:
                rows = conn.execute(
                    """
                    select local_relpath, changed_author
                    from NODES
                    where local_relpath = ? and op_depth = 0 and kind = 'file'
                      and presence = 'normal' and changed_revision = ?
                    """,
                    (source_path, int(revision)),
                ).fetchall()
            if len(rows) == 1 and rows[0][1]:
                return str(rows[0][1]), f"wc-db-exact-source:{rows[0][0]}@r{revision}"
            if len(rows) > 1:
                return None, f"wc.db exact source author ambiguous for {source_path}@r{revision}"
            return None, f"wc.db has no exact source path {source_path}@r{revision}"
        except Exception as exc:
            return None, f"wc.db exact source lookup failed: {exc}"

    name = os.path.basename(str(basename or ""))
    # The WC database stores the working filename, not SVN's temporary sidecar
    # suffix (for example ``Book.xlsx``, not ``Book.xlsx.merge-right.r42``).
    name = re.sub(r"\.merge-(?:left|right)(?:\.r\d+)?$", "", name, flags=re.IGNORECASE)
    name = re.sub(r"\.r\d+$", "", name, flags=re.IGNORECASE)
    name = re.sub(r"-rev\d+\.svn\d+\.tmp\.(xlsx|xlsm)$", r".\1", name, flags=re.IGNORECASE)
    name = name.lower()
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as conn:
            rows = conn.execute(
                """
                select local_relpath, changed_author
                from NODES
                where op_depth = 0 and kind = 'file' and presence = 'normal'
                  and changed_revision = ?
                  and (lower(local_relpath) = ? or lower(local_relpath) like ?)
                order by local_relpath
                """,
                (int(revision), name, "%/" + name),
            ).fetchall()
        if len(rows) == 1 and rows[0][1]:
            return str(rows[0][1]), f"wc-db-exact-sidecar:{rows[0][0]}@r{revision}"
        if len(rows) > 1:
            return None, f"wc.db exact sidecar author ambiguous ({len(rows)} matching paths)"
        return None, f"wc.db has no exact changed_revision={revision} basename={name} match"
    except Exception as exc:
        return None, f"wc.db sidecar lookup failed: {exc}"


def _wc_repository_metadata_for_local_path(
    wc_root: str, local_relpath: str
) -> tuple[str | None, str | None, str]:
    """Read one target-WC path's proven repository root and UUID, read-only."""
    db_path = os.path.join(wc_root, ".svn", "wc.db")
    relpath = str(local_relpath or "").replace("\\", "/").lstrip("/")
    if not relpath:
        return None, None, "target working-copy relative path unavailable"
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as conn:
            row = conn.execute(
                """
                select r.root, r.uuid
                from NODES n
                join REPOSITORY r on r.id = n.repos_id
                where n.local_relpath = ? and n.op_depth = 0 and n.kind = 'file'
                  and n.presence = 'normal'
                limit 1
                """,
                (relpath,),
            ).fetchone()
        if row and row[0]:
            return str(row[0]).rstrip("/"), str(row[1] or ""), "wc-db-repository-root"
        return None, None, "wc.db has no repository root for target path"
    except Exception as exc:
        return None, None, f"wc.db repository-root lookup failed: {exc}"


def _wc_repository_root_for_local_path(
    wc_root: str, local_relpath: str
) -> tuple[str | None, str]:
    """Compatibility wrapper for callers that only require the repository root."""
    root, _uuid, reason = _wc_repository_metadata_for_local_path(wc_root, local_relpath)
    return root, reason


def _svn_info_url_for_input_path(path: str | None) -> tuple[str | None, str]:
    """Ask SVN for a local input file's canonical URL, with a short timeout."""
    if not path or not os.path.exists(path):
        return None, "input file unavailable for svn info"
    svn_exe = _find_svn_cli_exe()
    if not svn_exe:
        return None, "svn CLI unavailable for input URL lookup"
    try:
        result = subprocess.run(
            [svn_exe, "info", "--xml", "--non-interactive", path],
            capture_output=True,
            text=True,
            errors="replace",
            timeout=8,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except Exception as exc:
        return None, f"svn info input URL lookup failed: {exc}"
    if int(getattr(result, "returncode", 1) or 0) != 0:
        detail = str(getattr(result, "stderr", "") or getattr(result, "stdout", "") or "").strip()
        return None, f"svn info input URL lookup failed: {detail or 'non-zero exit'}"
    try:
        root = ET.fromstring(str(getattr(result, "stdout", "") or ""))
        url = str(root.findtext(".//url") or "").strip()
    except Exception as exc:
        return None, f"svn info input URL XML invalid: {exc}"
    if not url:
        return None, "svn info input URL missing"
    return url, "svn-info-input-url"


_SVN_AUTHOR_MEMORY_CACHE: dict[tuple[str, str, int], str] = {}


class _SvnOptRevisionValue(ctypes.Union):
    _fields_ = [("number", ctypes.c_longlong), ("date", ctypes.c_longlong)]


class _SvnOptRevision(ctypes.Structure):
    _fields_ = [("kind", ctypes.c_int), ("value", _SvnOptRevisionValue)]


class _SvnString(ctypes.Structure):
    _fields_ = [("data", ctypes.c_char_p), ("len", ctypes.c_size_t)]


def _find_tortoise_svn_bin_dir() -> str | None:
    """Find TortoiseSVN's bundled Subversion runtime without loading it here."""
    candidates = [
        os.path.join(os.environ.get("ProgramFiles", r"C:\Program Files"), "TortoiseSVN", "bin"),
        os.path.join(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)"), "TortoiseSVN", "bin"),
    ]
    proc = _find_tortoise_proc_exe()
    if os.path.isabs(proc):
        candidates.append(os.path.dirname(proc))
    for candidate in dict.fromkeys(candidates):
        if all(
            os.path.isfile(os.path.join(candidate, filename))
            for filename in ("libapr_tsvn.dll", "libsvn_tsvn.dll")
        ):
            return candidate
    return None


def _tortoise_probe_error(svn, error_ptr, operation: str) -> None:
    if not error_ptr:
        return
    svn.svn_err_best_message.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_size_t]
    svn.svn_err_best_message.restype = ctypes.c_char_p
    buffer = ctypes.create_string_buffer(2048)
    message = svn.svn_err_best_message(error_ptr, buffer, len(buffer))
    svn.svn_error_clear.argtypes = [ctypes.c_void_p]
    svn.svn_error_clear(error_ptr)
    # The probe protocol deliberately returns only the operation class.  SVN's
    # native diagnostic can include server/authentication details and is not
    # needed by the visible Author label.
    _ = message or buffer
    raise RuntimeError(operation)


def _query_tortoise_svn_author_in_child(repo_url: str, revision: int) -> str:
    """Load TortoiseSVN's client DLLs in a disposable process only.

    This reads exactly ``svn:author`` at one URL/revision.  It never supplies,
    reads, logs, or serializes credentials; TortoiseSVN's own non-interactive
    authentication baton decides whether its existing secure configuration can
    access the repository.
    """
    bin_dir = _find_tortoise_svn_bin_dir()
    if not bin_dir or not hasattr(os, "add_dll_directory") or not hasattr(ctypes, "WinDLL"):
        raise RuntimeError("tortoise-runtime-unavailable")
    dll_cookie = os.add_dll_directory(bin_dir)
    apr_ready = False
    pool = ctypes.c_void_p()
    try:
        apr = ctypes.WinDLL(os.path.join(bin_dir, "libapr_tsvn.dll"))
        svn = ctypes.WinDLL(os.path.join(bin_dir, "libsvn_tsvn.dll"))
        apr.apr_initialize.argtypes = []
        apr.apr_initialize.restype = ctypes.c_int
        if int(apr.apr_initialize()):
            raise RuntimeError("apr-initialize")
        apr_ready = True
        apr.apr_pool_create_ex.argtypes = [
            ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p
        ]
        apr.apr_pool_create_ex.restype = ctypes.c_int
        if int(apr.apr_pool_create_ex(ctypes.byref(pool), None, None, None)):
            raise RuntimeError("apr-pool-create")
        svn.svn_dso_initialize2.argtypes = []
        svn.svn_dso_initialize2.restype = ctypes.c_void_p
        _tortoise_probe_error(svn, svn.svn_dso_initialize2(), "svn-dso-initialize")
        svn.svn_ra_initialize.argtypes = [ctypes.c_void_p]
        svn.svn_ra_initialize.restype = ctypes.c_void_p
        _tortoise_probe_error(svn, svn.svn_ra_initialize(pool), "svn-ra-initialize")

        auth_baton = ctypes.c_void_p()
        svn.svn_cmdline_create_auth_baton2.argtypes = [
            ctypes.POINTER(ctypes.c_void_p), ctypes.c_int,
            ctypes.c_char_p, ctypes.c_char_p, ctypes.c_char_p,
            ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int, ctypes.c_int,
            ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p, ctypes.c_void_p,
        ]
        svn.svn_cmdline_create_auth_baton2.restype = ctypes.c_void_p
        _tortoise_probe_error(
            svn,
            svn.svn_cmdline_create_auth_baton2(
                ctypes.byref(auth_baton), 1, None, None, None,
                0, 0, 0, 0, 0, 0, None, None, None, pool,
            ),
            "svn-auth-create",
        )

        context = ctypes.c_void_p()
        svn.svn_client_create_context2.argtypes = [
            ctypes.POINTER(ctypes.c_void_p), ctypes.c_void_p, ctypes.c_void_p
        ]
        svn.svn_client_create_context2.restype = ctypes.c_void_p
        _tortoise_probe_error(
            svn,
            svn.svn_client_create_context2(ctypes.byref(context), None, pool),
            "svn-client-context-create",
        )
        # svn_client_ctx_t starts with auth_baton in the bundled ABI. This is
        # isolated in the child process so a third-party DLL/ABI fault cannot
        # take down the merge UI.
        ctypes.cast(context, ctypes.POINTER(ctypes.c_void_p))[0] = auth_baton

        source_revision = _SvnOptRevision()
        source_revision.kind = 1  # svn_opt_revision_number
        source_revision.value.number = int(revision)
        value = ctypes.POINTER(_SvnString)()
        actual_revision = ctypes.c_longlong(-1)
        svn.svn_client_revprop_get.argtypes = [
            ctypes.c_char_p, ctypes.POINTER(ctypes.POINTER(_SvnString)), ctypes.c_char_p,
            ctypes.POINTER(_SvnOptRevision), ctypes.POINTER(ctypes.c_longlong),
            ctypes.c_void_p, ctypes.c_void_p,
        ]
        svn.svn_client_revprop_get.restype = ctypes.c_void_p
        encoded_url = quote(repo_url, safe="/%:@").encode("utf-8")
        _tortoise_probe_error(
            svn,
            svn.svn_client_revprop_get(
                b"svn:author", ctypes.byref(value), encoded_url,
                ctypes.byref(source_revision), ctypes.byref(actual_revision), context, pool,
            ),
            "svn-author-read",
        )
        if not value:
            raise RuntimeError("svn-author-absent")
        author = ctypes.string_at(value.contents.data, value.contents.len).decode("utf-8", errors="replace").strip()
        if not author:
            raise RuntimeError("svn-author-empty")
        return author
    finally:
        if pool:
            try:
                apr.apr_pool_destroy.argtypes = [ctypes.c_void_p]
                apr.apr_pool_destroy(pool)
            except Exception:
                pass
        if apr_ready:
            try:
                apr.apr_terminate()
            except Exception:
                pass
        dll_cookie.close()


def _run_tortoise_svn_author_probe(repo_url: str, revision: int) -> tuple[str | None, str]:
    """Run the native-DLL author lookup out of process with a hard timeout."""
    if not _find_tortoise_svn_bin_dir():
        return None, "TortoiseSVN runtime unavailable for URL+revision author query"
    fd, result_path = tempfile.mkstemp(
        prefix=f"{APP_NAME}_svn_author_{os.getpid()}_", suffix=".json"
    )
    os.close(fd)
    command = [sys.executable]
    if not getattr(sys, "frozen", False):
        command.append(os.path.abspath(__file__))
    command.extend((
        "--internal-svn-author-query",
        str(int(revision)),
        str(repo_url),
        result_path,
    ))
    try:
        result = subprocess.run(
            command,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            timeout=8,
            creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
        )
    except subprocess.TimeoutExpired:
        try:
            os.unlink(result_path)
        except OSError:
            pass
        return None, "TortoiseSVN author probe timed out"
    except Exception as exc:
        try:
            os.unlink(result_path)
        except OSError:
            pass
        return None, f"TortoiseSVN author probe launch failed: {type(exc).__name__}"
    payload: dict | None = None
    try:
        if int(getattr(result, "returncode", 1) or 0) == 0:
            with open(result_path, "r", encoding="utf-8") as stream:
                candidate = json.load(stream)
            if isinstance(candidate, dict):
                payload = candidate
    except (OSError, ValueError, TypeError):
        payload = None
    finally:
        try:
            os.unlink(result_path)
        except OSError:
            pass
    if isinstance(payload, dict):
        author = str(payload.get("author") or "").strip()
        if author:
            return author, "tortoise-svn-revprop-author"
    return None, "TortoiseSVN author probe failed"


def _run_tortoise_svn_author_probe_entrypoint(argv: list[str]) -> int:
    """Minimal file-only child protocol; never emit native SVN diagnostics."""
    result_path = ""
    try:
        if len(argv) != 3:
            raise ValueError("invalid arguments")
        result_path = os.path.abspath(argv[2])
        temp_root = os.path.abspath(tempfile.gettempdir())
        if (
            os.path.commonpath((temp_root, result_path)) != temp_root
            or not os.path.basename(result_path).startswith(f"{APP_NAME}_svn_author_")
        ):
            raise ValueError("invalid result path")
        payload = {"author": _query_tortoise_svn_author_in_child(argv[1], int(argv[0]))}
    except Exception as exc:
        payload = {"error": type(exc).__name__}
    if result_path:
        try:
            temp_path = result_path + ".tmp"
            with open(temp_path, "w", encoding="utf-8") as stream:
                json.dump(payload, stream, ensure_ascii=False)
            os.replace(temp_path, result_path)
        except OSError:
            return 2
    return 0 if payload.get("author") else 2


def _svn_author_cache_key(
    repository_root: str | None, repository_uuid: str | None, revision: int
) -> tuple[str, str, int] | None:
    if not repository_root:
        return None
    return str(repository_root).rstrip("/"), str(repository_uuid or ""), int(revision)


def _svn_author_for_url_peg(
    repo_url: str,
    revision: int,
    *,
    trusted_repository_root: str | None = None,
    repository_uuid: str | None = None,
) -> tuple[str | None, str]:
    """Resolve an author from one exact repository URL and revision.

    CLI remains the fast normal path.  When a TortoiseSVN-only installation has
    no ``svn.exe``, a child process uses its bundled client runtime solely for
    ``svn:author``—but only for a URL assembled from this WC's proven root.
    """
    try:
        revision = int(revision)
    except (TypeError, ValueError):
        return None, "invalid source revision for URL+peg author query"
    request_url = f"{str(repo_url).rstrip('@')}@{revision}"
    cache_key = _svn_author_cache_key(trusted_repository_root, repository_uuid, revision)
    if cache_key and cache_key in _SVN_AUTHOR_MEMORY_CACHE:
        return _SVN_AUTHOR_MEMORY_CACHE[cache_key], f"svn-author-memory-cache:{request_url}"

    cli_reason = "svn CLI unavailable for URL+peg author query"
    svn_exe = _find_svn_cli_exe()
    if svn_exe:
        try:
            result = subprocess.run(
                [svn_exe, "log", "--xml", "--non-interactive", "-r", f"{revision}:{revision}", request_url],
                capture_output=True,
                text=True,
                errors="replace",
                timeout=12,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
            if int(getattr(result, "returncode", 1) or 0) == 0:
                root = ET.fromstring(str(getattr(result, "stdout", "") or ""))
                author = str(root.findtext(".//logentry/author") or "").strip()
                if author:
                    if cache_key:
                        _SVN_AUTHOR_MEMORY_CACHE[cache_key] = author
                    return author, f"svn-log-url-peg:{request_url}"
                cli_reason = f"svn log URL+peg author missing for {request_url}"
            else:
                cli_reason = "svn log URL+peg author query failed"
        except Exception as exc:
            cli_reason = f"svn log URL+peg author query failed: {type(exc).__name__}"

    trusted_prefix = str(trusted_repository_root or "").rstrip("/")
    if trusted_prefix and (repo_url == trusted_prefix or repo_url.startswith(trusted_prefix + "/")):
        author, reason = _run_tortoise_svn_author_probe(repo_url, revision)
        if author:
            if cache_key:
                _SVN_AUTHOR_MEMORY_CACHE[cache_key] = author
            return author, f"{reason}:{request_url}"
        return None, f"{cli_reason}; {reason}"
    return None, f"{cli_reason}; TortoiseSVN fallback requires WC-proven repository root"


def _svn_author_for_source_identity(
    wc_root: str | None,
    anchor: str | None,
    identity: VersionIdentity,
) -> tuple[str | None, str]:
    """Resolve Source Before/After author without requiring a current WC row.

    Cross-branch merge metadata supplies a repository-relative identity.  Pair
    it with the target input's repository root and ask SVN for exactly that
    URL at exactly the sidecar/merge revision.  Plain sidecars retain a local
    ``svn info`` fallback for their corresponding input path.
    """
    if identity.revision is None:
        return None, "sidecar revision unavailable"
    source_path = str(identity.repository_identity or "").replace("\\", "/").strip().lstrip("/")
    if source_path:
        if not wc_root or not anchor:
            return None, "target working-copy root unavailable for source URL"
        try:
            anchor_relpath = os.path.relpath(os.path.abspath(anchor), wc_root).replace("\\", "/")
        except Exception as exc:
            return None, f"target working-copy relative path failed: {exc}"
        repository_root, repository_uuid, root_reason = _wc_repository_metadata_for_local_path(
            wc_root, anchor_relpath
        )
        if not repository_root:
            return None, root_reason
        encoded_source_path = quote(source_path, safe="/%:@")
        return _svn_author_for_url_peg(
            f"{repository_root.rstrip('/')}/{encoded_source_path}",
            identity.revision,
            trusted_repository_root=repository_root,
            repository_uuid=repository_uuid,
        )

    candidates = []
    for candidate in (identity.path, identity.effective_path):
        if candidate and candidate not in candidates:
            candidates.append(candidate)
    for candidate in tuple(candidates):
        name = os.path.basename(candidate)
        normalized_name = re.sub(
            r"\.merge-(?:left|right)(?:\.r\d+)?$|\.r\d+$",
            "",
            name,
            flags=re.IGNORECASE,
        )
        normalized = os.path.join(os.path.dirname(candidate), normalized_name)
        if normalized != candidate and normalized not in candidates:
            candidates.append(normalized)
    reasons = []
    for candidate in candidates:
        repo_url, reason = _svn_info_url_for_input_path(candidate)
        if repo_url:
            return _svn_author_for_url_peg(repo_url, identity.revision)
        reasons.append(reason)
    return None, "; ".join(dict.fromkeys(reasons)) or "source input URL unavailable"


def _copy_wc_pristine_local(path: str | None) -> str | None:
    """Copy a WC pristine blob without requiring the working file to exist.

    A ``missing`` or scheduled-deleted file has no working-path file by
    definition, but its BASE checksum and pristine blob remain in ``wc.db``.
    Requiring ``os.path.isfile(path)`` therefore made every legitimate missing
    file impossible to preflight.
    """
    if not path:
        _dlog("wc pristine unavailable: empty path")
        return None
    absolute_path = os.path.abspath(path)
    wc_root = _find_svn_wc_root_for_path(absolute_path)
    if not wc_root:
        _dlog(f"wc pristine unavailable: wc.db not found for {absolute_path}")
        return None
    relpath = os.path.relpath(absolute_path, wc_root).replace("\\", "/")
    db_path = os.path.join(wc_root, ".svn", "wc.db")
    try:
        with sqlite3.connect(f"file:{db_path}?mode=ro", uri=True) as conn:
            row = conn.execute(
                """
                select n.checksum, p.size
                from NODES n left join PRISTINE p on p.checksum = n.checksum
                where n.local_relpath = ? and n.op_depth = 0 and n.kind = 'file'
                  and n.presence = 'normal'
                limit 1
                """,
                (relpath,),
            ).fetchone()
        checksum = row[0] if row else None
        expected_size = int(row[1]) if row and row[1] is not None else None
        match = re.match(r"^\$sha1\$([0-9a-fA-F]{40})$", str(checksum or ""))
        if not match:
            _dlog(f"wc pristine unavailable: no checksum for {relpath}")
            return None
        sha1 = match.group(1).lower()
        pristine = os.path.join(wc_root, ".svn", "pristine", sha1[:2], sha1 + ".svn-base")
        if not os.path.isfile(pristine):
            _dlog(f"wc pristine unavailable: pristine blob missing {pristine}")
            return None
        actual_size = os.path.getsize(pristine)
        if expected_size is not None and actual_size != expected_size:
            _dlog(
                f"wc pristine unavailable: size mismatch {pristine} "
                f"expected={expected_size} actual={actual_size}"
            )
            return None
        digest = hashlib.sha1()
        with open(pristine, "rb") as stream:
            for block in iter(lambda: stream.read(1024 * 1024), b""):
                digest.update(block)
        if digest.hexdigest().lower() != sha1:
            _dlog(f"wc pristine unavailable: checksum mismatch {pristine}")
            return None
        ts = f"{datetime.now():%Y%m%d_%H%M%S}_{time.time_ns()}"
        target = os.path.join(
            tempfile.gettempdir(),
            f"{APP_NAME}_target_pristine_{os.getpid()}_{ts}_{os.path.basename(absolute_path)}",
        )
        if not target.lower().endswith(_workbook_ext(absolute_path)):
            target += _workbook_ext(absolute_path)
        shutil.copyfile(pristine, target)
        if _workbook_package_ready(target):
            _dlog(f"wc pristine copied from wc.db: {absolute_path} -> {target}")
            return target
        _dlog(f"wc pristine copy invalid package: {target}")
    except Exception as exc:
        _dlog(f"target pristine copy failed: {exc}")
    return None


def resolve_svn_author_metadata(context: MergeLaunchContext) -> dict[str, VersionIdentity]:
    """Populate author labels with an exact URL+peg lookup when available."""
    anchor = context.merged_path or context.mine_path
    wc_root = _find_svn_wc_root_for_path(anchor)
    mine_revision = None
    mine_author = None
    mine_reason = "working-copy metadata unavailable"
    if wc_root and anchor:
        relpath = os.path.relpath(os.path.abspath(anchor), wc_root).replace("\\", "/")
        mine_revision, mine_author, mine_reason = _wc_node_metadata(wc_root, relpath)
    for role, identity in context.identities.items():
        if identity is None or not identity.path:
            continue
        if role in ("mine", "target_pristine"):
            identity.revision = mine_revision if mine_revision is not None else identity.revision
            if mine_author:
                identity.author = str(mine_author)
                identity.author_source = mine_reason
                identity.author_status = "resolved"
                identity.availability_reason = ""
                _dlog(f"AUTHOR role={role} resolved author={identity.author} source={mine_reason}")
            else:
                identity.author = "未知"
                identity.author_source = "local-wc-db"
                identity.author_status = "unavailable"
                identity.availability_reason = mine_reason
                _dlog(f"AUTHOR role={role} unavailable reason={mine_reason}")
            continue
        revision = identity.revision
        author = None
        reason = "sidecar revision unavailable"
        if revision is not None:
            author, reason = _svn_author_for_source_identity(wc_root, anchor, identity)
        # An offline WC retains the old precise database lookup as a fallback.
        # It must not become the primary cross-branch source because a merge
        # source revision commonly has no current NODES row in the target WC.
        if not author and wc_root and revision is not None:
            wc_author, wc_reason = _wc_author_for_exact_sidecar_revision(
                wc_root,
                identity.path,
                revision,
                repository_identity=identity.repository_identity,
            )
            if wc_author:
                author, reason = wc_author, wc_reason
            else:
                reason = f"{reason}; offline fallback: {wc_reason}"
        if author:
            identity.author = author
            identity.author_source = reason
            identity.author_status = "resolved"
            identity.availability_reason = ""
            _dlog(f"AUTHOR role={role} resolved author={author} source={reason}")
        else:
            identity.author = "未知"
            identity.author_source = "local-wc-db"
            identity.author_status = "unavailable"
            identity.availability_reason = reason
            _dlog(f"AUTHOR role={role} unavailable revision={revision} reason={reason}")
    return context.identities


def format_version_identity(identity: VersionIdentity | None, *, candidate: bool = False) -> str:
    if identity is None:
        return "-"
    path = identity.path or identity.effective_path or "-"
    name = os.path.basename(path)
    rev = f" @r{identity.revision}" if identity.revision is not None else ""
    local = "；本地未提交修改" if identity.locally_modified else ""
    candidate_note = " → 合并候选" if candidate else ""
    repository = f" · SVN路径 = {identity.repository_identity}" if identity.repository_identity else ""
    return f"{name}{rev}{candidate_note}{repository} · Author = {identity.author or '未知'}{local}"


def _compact_identity_basename(identity: VersionIdentity | None) -> str:
    """Return the workbook name without SVN conflict-sidecar noise."""
    if identity is None:
        return "-"
    path = identity.path or identity.effective_path or "-"
    name = os.path.basename(path)
    return re.sub(
        r"(?i)(\.(?:xlsx|xlsm|xltx|xltm))"
        r"(?:\.merge-(?:left|right)\.r\d+|\.r\d+)$",
        r"\1",
        name,
    )


def format_compact_version_identity(
    identity: VersionIdentity | None,
    *,
    candidate: bool = False,
) -> str:
    """Format a pane identity with Author first so it survives clipping.

    Repository and local paths intentionally stay out of this permanent label;
    ``format_version_identity`` remains the complete diagnostic/hover format.
    """
    if identity is None:
        return "-"
    name = _compact_identity_basename(identity)
    rev = f" @r{identity.revision}" if identity.revision is not None else ""
    candidate_note = " → Merged" if candidate else ""
    local = "；本地未提交修改" if identity.locally_modified else ""
    return (
        f"Author = {identity.author or '未知'}{local} · "
        f"{name}{rev}{candidate_note}"
    )


def format_visible_file_path(path_like, *, max_len: int = 150) -> str:
    """Return a single-line absolute path while keeping its useful tail visible."""
    raw = os.fspath(path_like) if path_like else ""
    raw = str(raw or "").replace("\r", " ").replace("\n", " ").strip()
    if not raw:
        return "-"
    try:
        visible = os.path.normpath(os.path.abspath(raw))
    except Exception:
        visible = raw
    if len(visible) <= max_len:
        return visible
    tail_len = max(24, max_len - 4)
    return "…\\" + visible[-tail_len:].lstrip("\\/")


def merge_role_label(context: MergeLaunchContext | None, role: str, *, candidate: bool = False) -> str:
    """Return the user-facing semantic role name without changing raw roles."""
    normalized = str(role or "").lower()
    if context and context.scenario == MergeScenario.CROSS_BRANCH_MERGE:
        labels = {
            "base": "Source Before",
            "theirs": "Source After",
            "mine": "Target Working",
            "target_pristine": "Target Pristine",
        }
        label = labels.get(normalized, normalized.title() or "Unknown")
        return f"Merged Candidate ({label})" if candidate and normalized == "mine" else label
    labels = {
        "base": "Base",
        "theirs": "Theirs",
        "mine": "Mine",
        "target_pristine": "Target Pristine",
    }
    label = labels.get(normalized, normalized.title() or "Unknown")
    return f"Merged Candidate ({label})" if candidate and normalized == "mine" else label


def merge_side_label(context: MergeLaunchContext | None, side: str, *, candidate: bool = False) -> str:
    """Translate raw workspace sides into the scenario's visible role name."""
    normalized = str(side or "").upper()
    role = {
        "A": "mine",
        "MINE": "mine",
        "BASE": "base",
        "B": "theirs",
        "THEIRS": "theirs",
    }.get(normalized)
    return merge_role_label(context, role or normalized.lower(), candidate=candidate)


@dataclass(frozen=True)
class RolePresentation:
    """Single source of truth for pane/path labels and write directions."""

    left: str
    middle: str
    right: str
    left_role: str
    middle_role: str
    right_role: str

    def label_for_side(self, side: str) -> str:
        """Return the visible semantic label for a physical pane side."""
        normalized = str(side or "").upper()
        return {
            "A": self.left,
            "BASE": self.middle,
            "B": self.right,
        }.get(normalized, "")

    def roles_for_direction(self, direction: str) -> tuple[str, str | None]:
        """Map a copy command to its source/target visible roles."""
        source_target = {
            "A2B": ("A", "B"),
            "B2A": ("B", "A"),
            "BASE2A": ("BASE", "A"),
            # MINE2A is a conflict-resolution acknowledgement, not a write.
            "MINE2A": ("A", None),
        }
        source, target = source_target.get(str(direction or "").upper(), ("A", "B"))
        return self.label_for_side(source), self.label_for_side(target) or None

    def action_label(self, direction: str, scope: str = "row") -> str:
        """Render a direction-labelled command in the current scenario."""
        source, target = self.roles_for_direction(direction)
        suffix = {
            "region": "区域",
            "global": "全局",
            "table": "表",
            "row": "行",
            "column": "列",
        }.get(str(scope or "").lower(), "")
        if str(direction or "").upper() == "MINE2A":
            return f"保留 {source}{(' ' + suffix) if suffix else ''}"
        return f"应用 {source} → {target}{(' ' + suffix) if suffix else ''}"

    @classmethod
    def for_app(cls, app) -> "RolePresentation":
        context = getattr(app, "launch_context", None)
        if getattr(app, "role_mode", "") == "source-target":
            return cls("Source", "Source", "Target", "source", "source", "target")
        if getattr(app, "merge_mode", False) and getattr(app, "has_base", False):
            return cls(
                merge_role_label(context, "mine"),
                merge_role_label(context, "base"),
                merge_role_label(context, "theirs"),
                "mine", "base", "theirs",
            )
        # In ordinary SVN comparison A is the pristine/base side and B is the
        # working/mine side.  No third card is shown in this mode.
        return cls(
            merge_role_label(context, "base"),
            merge_role_label(context, "base"),
            merge_role_label(context, "mine"),
            "base", "base", "mine",
        )


def _create_startup_candidate_copy(source_path: str, role: str) -> str:
    ext = _workbook_ext(source_path)
    stamp = f"{datetime.now():%Y%m%d_%H%M%S}_{time.time_ns()}"
    candidate = os.path.join(
        tempfile.gettempdir(),
        f"{APP_NAME}_startup_candidate_{role}_{os.getpid()}_{stamp}{ext}",
    )
    shutil.copy2(source_path, candidate)
    if not _workbook_package_ready(candidate):
        raise RuntimeError(f"candidate copy is not a complete workbook: {candidate}")
    return candidate


def _legacy_premerge_effective_width_mismatch(
    base_path: str,
    mine_path: str,
    theirs_path: str,
) -> tuple[str, int, int, int] | None:
    """Find a conclusive physical-column blocker without row alignment.

    Legacy pre-merge writes by physical column.  If a common worksheet has
    different populated widths in Base, Mine, and Theirs, its physical column
    coordinates cannot be proved interchangeable.  This is sufficient to
    decline that writer before the much more expensive row/conflict scan.  A
    failure to inspect the lightweight bounds deliberately returns ``None`` so
    the exact scanner remains the conservative fallback.
    """
    started = time.perf_counter()

    def _widths(path: str) -> dict[str, int] | None:
        workbook = None
        try:
            # Normal worksheets expose sparse populated cells, allowing
            # `_effective_bounds` to ignore style-only XML tails.  Process one
            # input at a time to keep this preflight's memory bounded.
            workbook = load_workbook(path, data_only=False, keep_links=False)
            return {
                str(sheet): int(_effective_bounds(workbook[sheet])[1])
                for sheet in workbook.sheetnames
            }
        except Exception as exc:
            _dlog(f"SEMANTIC_PREMERGE_WIDTH_PREFLIGHT unavailable path={path} error={exc}")
            return None
        finally:
            _wbs_close(workbook)

    base_widths = _widths(base_path)
    mine_widths = _widths(mine_path)
    theirs_widths = _widths(theirs_path)
    if not (base_widths is not None and mine_widths is not None and theirs_widths is not None):
        return None
    for sheet in sorted(set(base_widths) & set(mine_widths) & set(theirs_widths)):
        widths = (base_widths[sheet], mine_widths[sheet], theirs_widths[sheet])
        if len(set(widths)) != 1:
            _dlog(
                "SEMANTIC_PREMERGE_WIDTH_PREFLIGHT_BLOCK "
                f"sheet={sheet} base={widths[0]} mine={widths[1]} theirs={widths[2]} "
                f"elapsed_ms={(time.perf_counter() - started) * 1000.0:.1f}"
            )
            return (sheet, *widths)
    _dlog(
        "SEMANTIC_PREMERGE_WIDTH_PREFLIGHT_CLEAR "
        f"sheets={len(set(base_widths) & set(mine_widths) & set(theirs_widths))} "
        f"elapsed_ms={(time.perf_counter() - started) * 1000.0:.1f}"
    )
    return None


def run_startup_merge_analysis(context: MergeLaunchContext) -> StartupMergeAnalysis:
    """Run the complete conservative pre-UI analysis without changing SVN state.

    Raw roles remain in ``context``.  A separate candidate file is made only
    after the full equality matrix has been captured.  Unsupported structural
    changes leave a manual candidate and are reported as fallbacks.
    """
    for identity in context.identities.values():
        if identity is None or not identity.path:
            continue
        try:
            identity.stable_path = _ensure_xlsx_copy(identity.path)
        except Exception as exc:
            identity.stable_path = identity.path
            identity.availability_reason = f"stable copy unavailable: {exc}"
            _dlog(f"IDENTITY stable copy failed role={identity.role} path={identity.path}: {exc}")

    if context.merged_path and not context.target_pristine_path:
        # The helper is intentionally local-only; retaining this call seam also
        # lets host integrations supply an already-read WC pristine identity.
        pristine = _try_export_svn_base_from_working_copy(context.merged_path)
        context.target_pristine_path = pristine
        pristine_identity = context.identity_for("target_pristine")
        if pristine_identity is not None:
            pristine_identity.path = pristine
            pristine_identity.stable_path = pristine
    # Cross-branch sidecar names are only a fallback.  Resolve the merge's
    # actual source branch identities from the target WC before author lookup
    # and equality logging make those revisions visible to the user.
    resolve_cross_branch_source_metadata(context)
    resolve_svn_author_metadata(context)
    matrix = build_equivalence_matrix(context)
    mine_identity = context.identity_for("mine")
    pristine_identity = context.identity_for("target_pristine")
    if mine_identity is not None and pristine_identity is not None and pristine_identity.available:
        mine_identity.locally_modified = not matrix.are_equal("mine", "target_pristine")
        _dlog(
            f"MINE_LOCAL_STATE mine_equals_target_pristine={not mine_identity.locally_modified} "
            f"mine={mine_identity.path} pristine={pristine_identity.path}"
        )

    outcome = decide_startup_merge_outcome(context, matrix)
    conflicts: list[tuple] = []
    conflict_map: dict = {}
    source_identity = context.identity_for(outcome.source_role or "")
    if outcome.source_role and source_identity and source_identity.available:
        try:
            outcome.candidate_path = _create_startup_candidate_copy(
                str(source_identity.effective_path), outcome.source_role
            )
            _dlog(
                f"STARTUP_CONVERGENCE action={outcome.automatic_action} source={outcome.source_role} "
                f"candidate={outcome.candidate_path}"
            )
        except Exception as exc:
            outcome.automatic_action = "manual-review"
            outcome.source_role = None
            outcome.fallback_reasons.append(f"candidate initialization failed: {exc}")

    if not outcome.source_role and context.scenario == MergeScenario.CROSS_BRANCH_MERGE:
        base = context.identity_for("base")
        mine = context.identity_for("mine")
        theirs = context.identity_for("theirs")
        if not (base and mine and theirs and base.available and mine.available and theirs.available):
            outcome.automatic_action = "manual-review"
            outcome.fallback_reasons.append(
                "complete Source Before/Target Working/Source After packages are unavailable"
            )
        else:
            (
                conflicts,
                candidate,
                conflict_map,
                branch_summary,
                manual_reason,
            ) = _cross_branch_source_delta_premerge(
                str(base.effective_path),
                str(mine.effective_path),
                str(theirs.effective_path),
            )
            outcome.incoming_count = int(branch_summary.get("incoming_count", 0))
            outcome.applied_count = int(branch_summary.get("applied_count", 0))
            outcome.already_present_count = int(branch_summary.get("already_present_count", 0))
            outcome.target_retained_count = int(branch_summary.get("target_retained_count", 0))
            outcome.unresolved_count = int(branch_summary.get("unresolved_count", len(conflicts)))
            outcome.merged_count = int(branch_summary.get("merged_count", outcome.applied_count))
            if manual_reason:
                outcome.automatic_action = "manual-review"
                outcome.fallback_reasons.append(f"source-delta projection safely declined: {manual_reason}")
                try:
                    outcome.candidate_path = _create_startup_candidate_copy(
                        str(mine.effective_path), "mine"
                    )
                    outcome.source_role = "mine"
                except Exception as exc:
                    outcome.fallback_reasons.append(
                        f"manual Target Working candidate initialization failed: {exc}"
                    )
            else:
                outcome.candidate_path = candidate
                outcome.source_role = "mine"
                if outcome.unresolved_count:
                    outcome.automatic_action = "manual-review"
                    outcome.fallback_reasons.append(
                        "some Source Before-to-Source After changes require manual resolution"
                    )
                elif outcome.applied_count:
                    outcome.automatic_action = "cross-branch-source-delta"
                elif outcome.already_present_count:
                    outcome.automatic_action = "incoming-already-present"
                else:
                    outcome.automatic_action = "manual-review"
                    outcome.fallback_reasons.append(
                        "source delta contained no supported incoming logical cells"
                    )
            _dlog(
                "STARTUP_CROSS_BRANCH_SOURCE_DELTA "
                f"incoming={outcome.incoming_count} applied={outcome.applied_count} "
                f"already_present={outcome.already_present_count} "
                f"target_retained={outcome.target_retained_count} "
                f"unresolved={outcome.unresolved_count} candidate={outcome.candidate_path}"
            )

    if not outcome.source_role and context.scenario != MergeScenario.CROSS_BRANCH_MERGE:
        base = context.identity_for("base")
        mine = context.identity_for("mine")
        theirs = context.identity_for("theirs")
        if not (base and mine and theirs and base.available and mine.available and theirs.available):
            outcome.fallback_reasons.append("complete Base/Mine/Theirs packages are unavailable for semantic pre-merge")
        else:
            base_path = str(base.effective_path)
            mine_path = str(mine.effective_path)
            theirs_path = str(theirs.effective_path)
            width_mismatch = _legacy_premerge_effective_width_mismatch(
                base_path, mine_path, theirs_path
            )
            if width_mismatch is not None:
                sheet, base_width, mine_width, theirs_width = width_mismatch
                # A manual candidate is byte-identical to Mine.  Do not invoke
                # the exact startup scanner here: SheetView's normal background
                # pipeline will build its complete row/column conflict model
                # after the user opens the manual three-way workspace.
                try:
                    outcome.candidate_path = _create_startup_candidate_copy(mine_path, "mine")
                except Exception as exc:
                    outcome.fallback_reasons.append(f"manual Mine candidate initialization failed: {exc}")
                outcome.automatic_action = "manual-review"
                outcome.fallback_reasons.append(
                    "legacy physical-column pre-merge skipped before exact conflict scan: "
                    f"{sheet} has different effective populated widths "
                    f"(Base={base_width}, Mine={mine_width}, Theirs={theirs_width}); "
                    "manual three-way view will build the exact conflict model"
                )
            else:
                try:
                    # The existing logical engine refuses unsupported column structure
                    # before writing.  It is therefore safe to use only as a preview.
                    conflicts, preview, conflict_map = _merge_three_way(
                        base_path,
                        mine_path,
                        theirs_path,
                        context.merged_path or mine_path,
                        save_merged=False,
                    )
                    outcome.candidate_path = preview or _create_startup_candidate_copy(
                        mine_path, "mine"
                    )
                    merged_summary = globals().get("_LAST_SEMANTIC_PREMERGE_SUMMARY", {}) or {}
                    outcome.merged_count = int(merged_summary.get("merged_count", 0))
                    outcome.unresolved_count = len(conflicts)
                    if outcome.merged_count:
                        outcome.automatic_action = "semantic-premerge"
                        outcome.source_role = "mine"
                    else:
                        outcome.automatic_action = "manual-review"
                        outcome.fallback_reasons.append("no supported one-sided or identical logical changes were applied")
                    _dlog(
                        f"STARTUP_SEMANTIC_PREMERGE merged={outcome.merged_count} unresolved={outcome.unresolved_count} "
                        f"candidate={outcome.candidate_path}"
                    )
                except _SemanticPremergeDeclined as exc:
                    # `_merge_three_way` has already completed the exact logical
                    # scan that proved legacy physical-column replay is unsafe.
                    # The stable Base/Mine/Theirs inputs cannot change during this
                    # startup transaction, so reuse that map verbatim instead of
                    # paying for a second whole-workbook scan before manual review.
                    outcome.automatic_action = "manual-review"
                    outcome.fallback_reasons.append(f"semantic pre-merge safely declined: {exc}")
                    conflicts = list(exc.conflicts)
                    conflict_map = dict(exc.conflict_cells_by_sheet)
                    outcome.unresolved_count = len(conflicts)
                    _dlog(
                        "STARTUP_SEMANTIC_PREMERGE_DECLINED_REUSED_SCAN "
                        f"unresolved={outcome.unresolved_count}"
                    )
                except Exception as exc:
                    outcome.automatic_action = "manual-review"
                    outcome.fallback_reasons.append(f"semantic pre-merge safely declined: {exc}")
                    try:
                        conflicts, conflict_map = _scan_three_way_conflicts(
                            base_path, mine_path, theirs_path
                        )
                        outcome.unresolved_count = len(conflicts)
                    except Exception as scan_exc:
                        outcome.fallback_reasons.append(f"manual conflict scan failed: {scan_exc}")
    else:
        if context.scenario == MergeScenario.CROSS_BRANCH_MERGE:
            # Whole-workbook convergence and source-delta pre-merge both retain
            # source-specific counts.  ``merged_count`` remains compatibility
            # only and therefore equals actual writes, never retained content.
            outcome.merged_count = outcome.applied_count
        else:
            outcome.unresolved_count = 0
            outcome.merged_count = 1
    _dlog(
        "STARTUP_ANALYSIS_COMPLETE "
        f"scenario={context.scenario.value} action={outcome.automatic_action} source={outcome.source_role} "
        f"fold={outcome.folded_identity} merged={outcome.merged_count} "
        f"incoming={outcome.incoming_count} applied={outcome.applied_count} "
        f"already_present={outcome.already_present_count} target_retained={outcome.target_retained_count} "
        f"unresolved={outcome.unresolved_count} "
        f"fallback={outcome.fallback_reasons}"
    )
    return StartupMergeAnalysis(context, matrix, outcome, conflicts, conflict_map)


def _wait_for_complete_workbook(path: str, timeout_seconds: float | None = None) -> bool:
    """Wait for asynchronous SVN exports to finish writing a valid OOXML ZIP."""
    timeout = float(_SVN_EXPORT_TIMEOUT_SECS if timeout_seconds is None else timeout_seconds)
    deadline = time.monotonic() + max(0.1, timeout)
    previous_size = -1
    stable_polls = 0
    while time.monotonic() < deadline:
        try:
            size = os.path.getsize(path) if os.path.isfile(path) else -1
        except OSError:
            size = -1
        if size > 0 and size == previous_size:
            stable_polls += 1
        else:
            previous_size = size
            stable_polls = 0
        # A ZIP central directory is written at the end, so a successful full
        # package test is the definitive signal that TortoiseProc has finished.
        if stable_polls >= 2 and _workbook_package_ready(path):
            return True
        time.sleep(0.1)
    ready = _workbook_package_ready(path)
    if not ready:
        _dlog(f"workbook export incomplete: path={path} size={previous_size}")
    return ready


def _try_export_svn_revision_from_merge_temp(path: str) -> str:
    """Compatibility shim: SVN sidecar content is authoritative as supplied.

    The old implementation guessed a target-branch repository path from a
    ``.merge-left`` sidecar and re-exported it through TortoiseProc.  That is
    invalid for cross-branch merges and can silently replace the source-left
    delta.  Keep the raw sidecar instead.
    """
    if path and ".merge-" in os.path.basename(str(path)).lower():
        _dlog(f"svn revision re-export intentionally skipped; preserving raw sidecar: {path}")
    return path



def _try_export_svn_base_from_working_copy(path: str) -> str | None:
    """Return a local WC pristine copy without invoking SVN/Tortoise UI.

    Retained for callers outside the launch path.  WC pristine is diagnostic
    fourth input only; it is never a substitute for the raw source Base.
    """
    return _copy_wc_pristine_local(path)


def _find_handle_exe():
    candidates = []
    configured = os.environ.get("SOW_HANDLE_EXE", "").strip()
    if configured:
        candidates.append(configured)
    candidates.append(
        os.path.join(os.environ.get("SystemRoot", r"C:\Windows"), "System32", "handle.exe")
    )
    for p in candidates:
        if os.path.exists(p):
            return p
    return shutil.which("handle.exe")


def _log_lock_holders(path: str) -> bool:
    """Return True if Excel is detected holding the file."""
    excel_found = False
    try:
        handle_exe = _find_handle_exe()
        if not handle_exe:
            _dlog(f"lock holders: handle.exe not found for {path}")
            return False
        no_window = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        r = subprocess.run(
            [handle_exe, "-accepteula", path],
            capture_output=True,
            text=True,
            errors="replace",
            timeout=10,
            creationflags=no_window,
        )
        out = (r.stdout or "") + (r.stderr or "")
        if out.strip():
            for line in out.splitlines():
                if path.lower() in line.lower():
                    _dlog(f"lock holders: {line.strip()}")
                    if "excel.exe" in line.lower():
                        excel_found = True
            return excel_found
        _dlog(f"lock holders: no output for {path}")
    except Exception as e:
        _dlog(f"lock holders: failed {e}")
    return excel_found


def _try_svn_resolve(path: str) -> bool:
    """Attempt to mark conflict as resolved in SVN."""
    try:
        svn_exe = shutil.which("svn")
        if svn_exe:
            subprocess.run(
                [svn_exe, "resolve", "--accept", "working", path],
                check=False,
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
            )
            return True
    except Exception:
        pass
    # Fallback to TortoiseProc (may show UI)
    try:
        proc_exe = _find_tortoise_proc_exe()
        subprocess.Popen([proc_exe, "/command:resolve", f"/path:{path}", "/closeonend:1"])
        return True
    except Exception:
        return False


def open_tortoise_merge(left_txt: str, right_txt: str, title: str):
    exe = _find_tortoise_merge_exe()
    args = [exe, "/base", left_txt, "/mine", right_txt, "/title", title]
    subprocess.Popen(args)


def _run_startup_progress_task(title: str, message: str, fn):
    """Run startup work off the Tk thread while keeping a progress window alive.

    ``fn`` receives ``report(message, detail=None, percent=None)``.  The helper is
    intentionally independent from ``SowMergeApp`` because merge conflict scanning
    happens before the main application object exists.
    """
    global _STARTUP_PROGRESS_ROOT
    root = _STARTUP_PROGRESS_ROOT
    try:
        root_exists = root is not None and bool(root.winfo_exists())
    except Exception:
        root_exists = False
    if not root_exists:
        root = tk.Tk()
        _STARTUP_PROGRESS_ROOT = root
    else:
        for child in list(root.winfo_children()):
            try:
                child.destroy()
            except Exception:
                pass
    root.title(title)
    root.resizable(False, False)
    root.protocol("WM_DELETE_WINDOW", lambda: None)
    root.deiconify()

    fast_candidate = None
    try:
        root.configure(bg=THEME.window_bg)
    except Exception:
        pass
    frame = ttk.Frame(root, padding=18, style="App.TFrame")
    frame.pack(fill="both", expand=True)
    try:
        configure_ttk_style(root)
    except Exception:
        pass
    title_label = ttk.Label(frame, text=message, style="Title.App.TLabel")
    title_label.pack(anchor="w")
    detail_label = ttk.Label(frame, text="正在准备...", style="Muted.App.TLabel", wraplength=500)
    detail_label.pack(
        anchor="w", fill="x", pady=(8, 10)
    )
    progress = ttk.Progressbar(frame, mode="indeterminate", length=500)
    progress.pack(fill="x")
    elapsed_label = ttk.Label(frame, text="已用时 0.0 秒", style="Muted.App.TLabel")
    elapsed_label.pack(anchor="e", pady=(7, 0))
    progress.start(12)

    root.update_idletasks()
    width = 550
    height = 155
    x = max(0, (root.winfo_screenwidth() - width) // 2)
    y = max(0, (root.winfo_screenheight() - height) // 2)
    root.geometry(f"{width}x{height}+{x}+{y}")

    updates_lock = threading.Lock()
    updates: list[tuple[str | None, str | None, float | None]] = []
    state: dict[str, object] = {}
    done = threading.Event()
    started = time.monotonic()

    def report(text=None, detail=None, percent=None):
        pct = None
        if percent is not None:
            try:
                pct = max(0.0, min(100.0, float(percent)))
            except Exception:
                pct = None
        with updates_lock:
            updates.append((text, detail, pct))

    def worker():
        try:
            state["result"] = fn(report)
        except BaseException as exc:
            state["error"] = exc
            state["traceback"] = traceback.format_exc()
        finally:
            done.set()

    # Tk objects must be finalized on the UI thread. openpyxl's XML parsing can
    # trigger cyclic GC in the worker, so defer cyclic collection until the
    # temporary Tk interpreter has been destroyed on this thread.
    gc_was_enabled = gc.isenabled()
    if gc_was_enabled:
        gc.disable()
    thread = threading.Thread(target=worker, daemon=True, name="sow-startup-progress")
    thread.start()

    def poll():
        latest = None
        with updates_lock:
            if updates:
                latest = updates[-1]
                updates.clear()
        if latest is not None:
            text_value, detail_value, percent_value = latest
            if text_value:
                title_label.configure(text=str(text_value))
            if detail_value is not None:
                detail_label.configure(text=str(detail_value))
            if percent_value is not None:
                progress.stop()
                progress.configure(mode="determinate", maximum=100, value=percent_value)
        elapsed_label.configure(text=f"已用时 {time.monotonic() - started:.1f} 秒")
        if done.is_set():
            try:
                progress.stop()
                root.quit()
            except Exception:
                pass
            return
        root.after(80, poll)

    root.after(50, poll)
    try:
        root.mainloop()
    finally:
        try:
            root.withdraw()
        except Exception:
            pass
        if gc_was_enabled:
            gc.enable()
            gc.collect()
    if "error" in state:
        _dlog(f"startup task failed: {state.get('traceback', state['error'])}")
        raise state["error"]
    return state.get("result")


def _destroy_startup_progress_root():
    global _STARTUP_PROGRESS_ROOT
    root = _STARTUP_PROGRESS_ROOT
    _STARTUP_PROGRESS_ROOT = None
    if root is None:
        return
    try:
        for aid in list(root.tk.call("after", "info") or ()):
            try:
                root.after_cancel(aid)
            except Exception:
                pass
    except Exception:
        pass
    try:
        if root.winfo_exists():
            root.destroy()
    except Exception:
        pass


def _take_startup_progress_root():
    """Promote the startup Tk interpreter to the application's main window."""
    global _STARTUP_PROGRESS_ROOT
    root = _STARTUP_PROGRESS_ROOT
    _STARTUP_PROGRESS_ROOT = None
    try:
        root_exists = root is not None and bool(root.winfo_exists())
    except Exception:
        root_exists = False
    if not root_exists:
        root = tk.Tk()
        root.withdraw()
        return root
    try:
        for aid in list(root.tk.call("after", "info") or ()):
            try:
                root.after_cancel(aid)
            except Exception:
                pass
    except Exception:
        pass
    for child in list(root.winfo_children()):
        try:
            child.destroy()
        except Exception:
            pass
    try:
        # The progress window used a compact geometry. Keep it withdrawn until
        # the full application layout has settled so Windows never paints that
        # intermediate geometry as the main window.
        root.withdraw()
    except Exception:
        pass
    return root


def excel_to_text(path: str, out_path: str, thick_sep_char: str = "="):
    val_path = _prepare_val_path(path)
    wb = load_workbook(val_path, data_only=True)
    try:
        with open(out_path, "w", encoding="utf-8") as f:
            f.write(f"{APP_NAME} text export\n")
            f.write(f"Source: {path}\n")
            f.write(f"Time: {datetime.now().isoformat(sep=' ', timespec='seconds')}\n\n")

            for idx, name in enumerate(wb.sheetnames):
                ws = wb[name]
                max_row = ws.max_row or 1
                max_col = ws.max_column or 1

                if idx != 0:
                    f.write("\n" + (thick_sep_char * 120) + "\n")

                title = f"SHEET: {name}"
                pad = max(0, 120 - len(title) - 2)
                left = thick_sep_char * (pad // 2)
                right = thick_sep_char * (pad - (pad // 2))
                f.write(f"{left} {title} {right}\n")

                cols = [ws.cell(row=1, column=c).coordinate[:-1] for c in range(1, max_col + 1)]
                f.write("ROW\t" + "\t".join(cols) + "\n")

                for r in range(1, max_row + 1):
                    vals = []
                    for c in range(1, max_col + 1):
                        vals.append(_val_to_str(ws.cell(row=r, column=c).value))
                    f.write(str(r) + "\t" + "\t".join(vals) + "\n")
    finally:
        _wbs_close(wb)
        if val_path != path:
            try:
                os.remove(val_path)
            except Exception:
                pass


def pick_two_files_same_name():
    root = tk.Tk()
    root.withdraw()

    a = filedialog.askopenfilename(title="Select first Excel workbook", filetypes=[("Excel Workbook", "*.xlsx *.xlsm")])
    if not a:
        return None, None
    b = filedialog.askopenfilename(title="Select second Excel workbook (same filename)", filetypes=[("Excel Workbook", "*.xlsx *.xlsm")])
    if not b:
        return None, None

    if os.path.basename(a).lower() != os.path.basename(b).lower():
        messagebox.showerror(
            "Filename mismatch",
            f"The two files must have the same filename.\n\nA: {os.path.basename(a)}\nB: {os.path.basename(b)}",
        )
        return None, None

    return a, b


def _detect_svn_conflict_files(target_path: str):
    # If user selected a conflict artifact directly, map back to merged target first.
    try:
        p = os.path.abspath(target_path)
        m = re.match(r"^(?P<base>.+)\.merge-(left|right)\.r\d+$", p, flags=re.IGNORECASE)
        if m:
            target_path = m.group("base")
    except Exception:
        pass
    folder = os.path.dirname(target_path)
    base_name = os.path.basename(target_path)
    # SVN conflict artifacts:
    # - file.merge-left.r#### / file.merge-right.r#### (newer SVN)
    # - file.r<rev> (older SVN), possibly .mine
    merge_left = []
    merge_right = []
    for name in os.listdir(folder):
        if name.startswith(base_name + ".merge-left.r"):
            suffix = name[len(base_name) + len(".merge-left.r"):]
            if suffix.isdigit():
                merge_left.append((int(suffix), os.path.join(folder, name)))
        elif name.startswith(base_name + ".merge-right.r"):
            suffix = name[len(base_name) + len(".merge-right.r"):]
            if suffix.isdigit():
                merge_right.append((int(suffix), os.path.join(folder, name)))
        elif name == base_name + ".merge-left":
            merge_left.append((0, os.path.join(folder, name)))
        elif name == base_name + ".merge-right":
            merge_right.append((0, os.path.join(folder, name)))
    if merge_left and merge_right:
        merge_left.sort(key=lambda x: x[0])
        merge_right.sort(key=lambda x: x[0])
        base_path = merge_left[-1][1]
        theirs_path = merge_right[-1][1]
        mine_path = target_path
        merged_path = target_path
        return base_path, mine_path, theirs_path, merged_path

    # Older SVN conflict artifacts: file.r<rev> (numeric), possibly .mine
    r_files = []
    for name in os.listdir(folder):
        if not name.startswith(base_name + ".r"):
            continue
        suffix = name[len(base_name) + 2:]
        if suffix.isdigit():
            r_files.append((int(suffix), os.path.join(folder, name)))
    if len(r_files) >= 2:
        r_files.sort(key=lambda x: x[0])
        base_path = r_files[0][1]
        theirs_path = r_files[-1][1]
        mine_path = target_path
        merged_path = target_path
        return base_path, mine_path, theirs_path, merged_path
    # Fallback for rOLD/rNEW naming
    r_old = os.path.join(folder, base_name + ".rOLD")
    r_new = os.path.join(folder, base_name + ".rNEW")
    if os.path.exists(r_old) and os.path.exists(r_new):
        return r_old, target_path, r_new, target_path
    # Fallback: fuzzy match for temp-stable names that still contain "<base>.merge-left/right.r####"
    # e.g. sow_merge_tool_stable_..._<base>.merge-right.r27548_...
    try:
        merge_left_fuzzy = []
        merge_right_fuzzy = []
        key = (base_name + ".merge-").lower()
        for name in os.listdir(folder):
            low = name.lower()
            if key not in low:
                continue
            i_left = low.find((base_name + ".merge-left.r").lower())
            if i_left >= 0:
                j = i_left + len((base_name + ".merge-left.r").lower())
                rev = []
                while j < len(low) and low[j].isdigit():
                    rev.append(low[j])
                    j += 1
                if rev:
                    merge_left_fuzzy.append((int("".join(rev)), os.path.join(folder, name)))
            i_right = low.find((base_name + ".merge-right.r").lower())
            if i_right >= 0:
                j = i_right + len((base_name + ".merge-right.r").lower())
                rev = []
                while j < len(low) and low[j].isdigit():
                    rev.append(low[j])
                    j += 1
                if rev:
                    merge_right_fuzzy.append((int("".join(rev)), os.path.join(folder, name)))
        if merge_left_fuzzy and merge_right_fuzzy:
            merge_left_fuzzy.sort(key=lambda x: x[0])
            merge_right_fuzzy.sort(key=lambda x: x[0])
            return merge_left_fuzzy[-1][1], target_path, merge_right_fuzzy[-1][1], target_path
    except Exception:
        pass
    return None


def _trace_launch(msg: str):
    try:
        ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
        with open(_LAUNCH_TRACE_PATH, "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {msg}\n")
    except Exception:
        pass


def _has_svn_conflict_artifacts(target_path: str) -> bool:
    try:
        folder = os.path.dirname(target_path)
        base_name = os.path.basename(target_path)
        mine = os.path.join(folder, base_name + ".mine")
        if os.path.exists(mine):
            return True
        for name in os.listdir(folder):
            if name.startswith(base_name + ".merge-left") or name.startswith(base_name + ".merge-right"):
                return True
        r_old = os.path.join(folder, base_name + ".rOLD")
        r_new = os.path.join(folder, base_name + ".rNEW")
        if os.path.exists(r_old) or os.path.exists(r_new):
            return True
        for name in os.listdir(folder):
            if name.startswith(base_name + ".r"):
                suffix = name[len(base_name) + 2:]
                if suffix.isdigit():
                    return True
    except Exception:
        pass
    return False


def _find_conflict_in_dir(folder: str):
    try:
        # If there is exactly one conflicted file in folder, return it.
        base_names = set()
        for name in os.listdir(folder):
            if ".merge-left" in name:
                base = name.split(".merge-left")[0]
                base_names.add(base)
                continue
            if ".merge-right" in name:
                base = name.split(".merge-right")[0]
                base_names.add(base)
                continue
            if ".r" in name:
                base = name.split(".r")[0]
                base_names.add(base)
        candidates = []
        for base in base_names:
            target = os.path.join(folder, base)
            if os.path.exists(target) and _has_svn_conflict_artifacts(target):
                candidates.append(target)
        if len(candidates) == 1:
            return candidates[0]
    except Exception:
        pass
    return None


def _auto_pick_conflict_file():
    # Best-effort: try current working directory
    try:
        cwd = os.getcwd()
        p = _find_conflict_in_dir(cwd)
        if p:
            return p
        try:
            svn_exe = shutil.which("svn")
            if svn_exe:
                no_window = getattr(subprocess, "CREATE_NO_WINDOW", 0)
                r = subprocess.run(
                    [svn_exe, "status", cwd],
                    capture_output=True,
                    text=True,
                    errors="replace",
                    timeout=8,
                    creationflags=no_window,
                )
                if r.returncode == 0:
                    conflicted = []
                    for line in (r.stdout or "").splitlines():
                        if not line:
                            continue
                        if line[0] != "C":
                            continue
                        rel = line[8:].strip() if len(line) > 8 else ""
                        if not rel:
                            continue
                        cand = os.path.abspath(os.path.join(cwd, rel))
                        if os.path.exists(cand):
                            conflicted.append(cand)
                    if len(conflicted) == 1:
                        return conflicted[0]
        except Exception:
            pass
        # Walk up to find SVN working copy root (.svn)
        cur = cwd
        wc_root = None
        while True:
            if os.path.isdir(os.path.join(cur, ".svn")):
                wc_root = cur
                break
            parent = os.path.dirname(cur)
            if parent == cur:
                break
            cur = parent
        if wc_root:
            # If exactly one conflicted file exists in the working copy, auto-pick it
            candidates = []
            for root, _dirs, files in os.walk(wc_root):
                base_names = set()
                for name in files:
                    if ".r" in name:
                        base = name.split(".r")[0]
                        base_names.add(base)
                for base in base_names:
                    target = os.path.join(root, base)
                    if os.path.exists(target) and _has_svn_conflict_artifacts(target):
                        candidates.append(target)
                        if len(candidates) > 1:
                            return None
            if len(candidates) == 1:
                return candidates[0]
    except Exception:
        pass
    return None


def pick_files_or_conflict():
    root = tk.Tk()
    root.withdraw()

    auto = _auto_pick_conflict_file()
    if auto:
        conflict = _detect_svn_conflict_files(auto)
        if conflict:
            return ("merge",) + conflict + (True,)

    a = filedialog.askopenfilename(title="Select Excel workbook", filetypes=[("Excel Workbook", "*.xlsx *.xlsm")])
    if not a:
        return None

    conflict = _detect_svn_conflict_files(a)
    if conflict:
        return ("merge",) + conflict + (True,)

    b = filedialog.askopenfilename(title="Select second Excel workbook (same filename)", filetypes=[("Excel Workbook", "*.xlsx *.xlsm")])
    if not b:
        return None

    if os.path.basename(a).lower() != os.path.basename(b).lower():
        messagebox.showerror(
            "Filename mismatch",
            f"The two files must have the same filename.\n\nA: {os.path.basename(a)}\nB: {os.path.basename(b)}",
        )
        return None

    return ("diff", a, b)


_DEFAULT_PICKER_FUNCTION = pick_files_or_conflict


def _atomic_save_wb(wb, target_path: str):
    """Safely overwrite a workbook."""
    folder = os.path.dirname(target_path)
    if folder:
        os.makedirs(folder, exist_ok=True)
    base = os.path.basename(target_path)
    tmp_path = os.path.join(folder, f"~{base}.{os.getpid()}.tmp")
    try:
        if _FAST_SAVE_VALUES_ONLY and _USE_CACHED_VALUES_ONLY:
            _save_values_only_from_wb(wb, tmp_path)
        else:
            wb.save(tmp_path)
        os.replace(tmp_path, target_path)
    except Exception:
        try:
            os.remove(tmp_path)
        except Exception:
            pass
        raise


def _ensure_xlsx_copy(path: str) -> str:
    """If path is not a directly openable workbook path, copy it to a temp workbook path."""
    if not path:
        return path
    if os.path.splitext(path)[1].lower() in _SUPPORTED_WORKBOOK_EXTS:
        return _ensure_stable_copy(path)
    try:
        if not _wait_for_complete_workbook(path):
            raise RuntimeError(f"SVN 临时 Excel 文件尚未完整生成或已损坏：{path}")
        base = os.path.basename(path)
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        ext = _workbook_ext(path)
        tmp = os.path.join(tempfile.gettempdir(), f"{APP_NAME}_svn_{base}_{ts}")
        if not tmp.lower().endswith(ext):
            tmp += ext
        shutil.copy2(path, tmp)
        if not _workbook_package_ready(tmp):
            raise RuntimeError(f"SVN 临时 Excel 文件复制后校验失败：{path}")
        return tmp
    except RuntimeError:
        raise
    except Exception as e:
        raise RuntimeError(f"无法准备 SVN 临时 Excel 文件：{path}\n{e}") from e


def _ensure_stable_copy(path: str) -> str:
    """If path looks like a temp/svn artifact, copy to a stable temp file."""
    if not path:
        return path
    tmp = None
    try:
        temp_root = os.path.abspath(tempfile.gettempdir()).lower()
        p_abs = os.path.abspath(path)
        p_low = p_abs.lower()
        base = os.path.basename(path)
        looks_temp = p_low.startswith(temp_root)
        looks_svn = ".svn" in p_low or ".r" in base or "revbase" in base.lower() or "rev" in base.lower()
        if looks_temp or looks_svn:
            if not _wait_for_complete_workbook(p_abs):
                raise RuntimeError(f"SVN 临时 Excel 文件尚未完整生成或已损坏：{path}")
            if base.lower().startswith(f"{APP_NAME}_stable_"):
                return p_abs
            stable_prefix = (
                f"{APP_NAME}_stable_{os.getpid()}_{time.time_ns()}_"
            )
            fd, tmp = tempfile.mkstemp(
                prefix=stable_prefix,
                suffix=f"_{base}",
                dir=tempfile.gettempdir(),
            )
            os.close(fd)
            ext = _workbook_ext(path)
            if not tmp.lower().endswith(ext):
                renamed = tmp + ext
                os.replace(tmp, renamed)
                tmp = renamed
            shutil.copy2(path, tmp)
            if not _workbook_package_ready(tmp):
                raise RuntimeError(f"SVN 临时 Excel 文件稳定副本校验失败：{path}")
            return tmp
    except RuntimeError:
        if tmp:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass
        raise
    except Exception:
        if tmp:
            try:
                if os.path.exists(tmp):
                    os.remove(tmp)
            except Exception:
                pass
        pass
    return path


def _is_temp_base_path(path: str) -> bool:
    if not path:
        return False
    p = os.path.abspath(path).lower()
    base = os.path.basename(path).lower()
    if p.startswith(os.path.abspath(tempfile.gettempdir()).lower()):
        return True
    if "revbase" in base or ".svn" in p or base.endswith(".tmp.xlsx") or base.endswith(".tmp.xlsm") or ".r" in base:
        return True
    return False


def _wbs_close(*wbs):
    """Safely close one or more openpyxl workbooks, ignoring errors."""
    for wb in wbs:
        if wb is not None:
            try:
                wb.close()
            except Exception:
                pass
            try:
                vba_archive = getattr(wb, "vba_archive", None)
                if vba_archive is not None:
                    vba_archive.close()
                    try:
                        vba_archive.fp = None
                    except Exception:
                        pass
                    try:
                        wb.vba_archive = None
                    except Exception:
                        pass
            except Exception:
                pass


def _cross_branch_source_delta_premerge(
    source_before_path: str,
    target_working_path: str,
    source_after_path: str,
) -> tuple[list[tuple], str | None, dict, dict[str, int], str | None]:
    """Project only a source-branch delta onto a target-working candidate.

    This intentionally does *not* reuse the generic Base/Mine/Theirs writer.
    In a cross-branch merge Mine is the target branch, not a second change
    relative to Source Before.  Starting from Target Working makes unrelated
    target edits naturally persistent; a Source Before-to-After cell is the
    only thing eligible to become incoming.
    """
    global _LAST_SEMANTIC_PREMERGE_SUMMARY
    summary = {
        "incoming_count": 0,
        "applied_count": 0,
        "already_present_count": 0,
        "target_retained_count": 0,
        "unresolved_count": 0,
        # Backward-compatible generic count: only a value written to the
        # candidate is a merge, never an already-present or retained value.
        "merged_count": 0,
        "unresolved_structural_count": 0,
    }
    conflicts: list[tuple] = []
    conflict_cells_by_sheet: dict = {}
    workbooks = []
    prepared_paths: list[tuple[str, str]] = []

    # Large configuration workbooks spend most of the legacy path opening six
    # openpyxl models and repeatedly normalizing every cell.  The OOXML planner
    # can prove and materialize direct source deltas in one pass.  Keep the
    # mature legacy path as the conservative fallback for overlaps and unusual
    # structures, and use the fast path only where its startup win is material.
    try:
        large_xlsx = (
            all(_workbook_ext(str(path)) == ".xlsx" for path in (
                source_before_path, target_working_path, source_after_path
            ))
            and max(os.path.getsize(path) for path in (
                source_before_path, target_working_path, source_after_path
            )) >= 256 * 1024
        )
        if large_xlsx:
            from .fast_branch_merge import analyze_source as _fast_analyze_source
            from .fast_branch_merge import analyze_target as _fast_analyze_target
            from .fast_branch_merge import apply_source_change_plan as _fast_apply_source_change_plan

            fast_delta = _fast_analyze_source(source_before_path, source_after_path)
            fast_decision = _fast_analyze_target(fast_delta, target_working_path)
            if fast_decision.disposition in {"direct", "already_applied"}:
                candidate = _create_startup_candidate_copy(target_working_path, "mine")
                fast_candidate = candidate
                if fast_decision.disposition == "direct":
                    _fast_apply_source_change_plan(
                        source_before_path,
                        source_after_path,
                        target_working_path,
                        candidate,
                        fast_decision,
                    )
                direct_count = int(fast_decision.summary.get("direct", 0))
                already_count = int(fast_decision.summary.get("already", 0))
                summary.update({
                    "incoming_count": int(fast_delta.incoming_count),
                    "applied_count": direct_count,
                    "already_present_count": already_count,
                    "merged_count": direct_count,
                })
                classified = direct_count + already_count
                if classified != summary["incoming_count"]:
                    raise RuntimeError(
                        "fast source-delta accounting mismatch: "
                        f"incoming={summary['incoming_count']} classified={classified}"
                    )
                _LAST_SEMANTIC_PREMERGE_SUMMARY = dict(summary)
                _dlog(
                    "CROSS_BRANCH_SOURCE_DELTA_FAST "
                    f"incoming={summary['incoming_count']} applied={summary['applied_count']} "
                    f"already={summary['already_present_count']}"
                )
                return [], candidate, {}, dict(summary), None
    except Exception as exc:
        if fast_candidate:
            try:
                os.remove(fast_candidate)
            except OSError:
                pass
        _dlog(f"CROSS_BRANCH_SOURCE_DELTA_FAST_FALLBACK reason={exc}")

    def _record_conflict(sheet: str, row: int, col: int, target_value, source_value):
        conflicts.append((sheet, int(row), int(col), target_value, source_value))
        conflict_cells_by_sheet.setdefault(sheet, {}).setdefault(int(row), set()).add(int(col))
        summary["unresolved_count"] += 1

    def _decline(reason: str, sheet: str = "<workbook>"):
        # A declined source change is still one incoming change.  Keeping that
        # accounting explicit is important to the startup dialog invariant:
        # incoming == applied + already-present + unresolved.  In particular,
        # package-only/style and sheet-structure changes have no cell delta to
        # increment before reaching this conservative exit.
        summary["incoming_count"] += 1
        # Earlier sheets may already have contributed incoming source changes
        # during the bounded preflight.  Once the projection as a whole is
        # declined, classify every not-yet-classified incoming item as manual
        # rather than leaving the audit counters internally inconsistent.
        pending = max(
            1,
            summary["incoming_count"]
            - summary["applied_count"]
            - summary["already_present_count"]
            - summary["unresolved_count"],
        )
        summary["unresolved_structural_count"] += pending
        for index in range(pending):
            _record_conflict(
                sheet,
                1 + index,
                1,
                "未支持的源结构变化",
                reason,
            )
        summary["merged_count"] = summary["applied_count"]
        _LAST_SEMANTIC_PREMERGE_SUMMARY = dict(summary)
        _dlog(
            "CROSS_BRANCH_SOURCE_DELTA_DECLINED "
            f"reason={reason} incoming={summary['incoming_count']} "
            f"applied={summary['applied_count']} unresolved={summary['unresolved_count']}"
        )
        # Preserve Target Working byte-for-byte even when a source change is
        # unsupported; callers still need a safe candidate to inspect.
        candidate = _create_startup_candidate_copy(target_working_path, "mine")
        return conflicts, candidate, conflict_cells_by_sheet, dict(summary), reason

    def _cell_value_key(ws_val, ws_edit, row: int, col: int):
        value = ws_val.cell(row=row, column=col).value
        edit_value = ws_edit.cell(row=row, column=col).value
        # Cached formula results are recalculation artifacts.  A Source input
        # edit may refresh many unchanged formula <v> nodes; classify formula
        # identity from its edit text and let Target Working recalculate rather
        # than treating cache churn as additional incoming cells.
        special = _special_formula_signature(edit_value)
        formula = _formula_text(edit_value)
        if special is not None:
            return value, edit_value, ("FORMULA", "SPECIAL", repr(special))
        if formula is not None:
            return value, edit_value, ("FORMULA", "TEXT", formula)
        return value, edit_value, _merge_cell_compare_key(value, edit_value)

    def _row_values(ws, rows: int, width: int):
        if rows <= 0 or width <= 0:
            return []
        cache = _read_rows_into_cache(ws, range(1, rows + 1), width)
        return [_row_from_cache(cache, row, width) for row in range(1, rows + 1)]

    def _source_to_target_row_map(
        source_val,
        source_edit,
        target_val,
        target_edit,
        source_rows: int,
        target_rows: int,
        source_width: int,
        target_width: int,
        source_to_target_cols: dict[int, int] | None = None,
    ) -> dict[int, int]:
        column_map = {
            int(source_col): int(target_col)
            for source_col, target_col in (source_to_target_cols or {}).items()
            if int(source_col) > 0 and int(target_col) > 0
        }
        if not column_map and source_width == target_width:
            column_map = {column: column for column in range(1, source_width + 1)}
        if not column_map:
            return {}
        try:
            source_columns = sorted(column_map)
            target_columns = [column_map[column] for column in source_columns]

            # Use the leftmost provably unique common column as a record key
            # and map it in O(n).  We deliberately do not choose a later
            # coincidentally-unique numeric payload: in ``[id, value]``, a
            # replacement ``a -> x`` may keep the same value and must not
            # receive Source After's change.  Missing/nonmatching keys simply
            # remain unmapped and become manual incoming work.
            def _looks_like_physical_ordinal(ws_val, ws_edit, rows: int, col: int) -> bool:
                samples = []
                for row in range(2, rows + 1):
                    value = ws_val.cell(row=row, column=col).value
                    if value is None:
                        value = ws_edit.cell(row=row, column=col).value
                    if isinstance(value, bool):
                        continue
                    try:
                        numeric = float(value)
                    except (TypeError, ValueError):
                        continue
                    if numeric.is_integer():
                        samples.append((row, int(numeric)))
                if len(samples) < 4:
                    return False
                offsets = [numeric - row for row, numeric in samples]
                dominant = max(set(offsets), key=offsets.count)
                return offsets.count(dominant) / len(offsets) >= 0.90

            for source_col in source_columns:
                target_col = column_map[source_col]
                if (
                    _looks_like_physical_ordinal(source_val, source_edit, source_rows, source_col)
                    and _looks_like_physical_ordinal(target_val, target_edit, target_rows, target_col)
                ):
                    continue
                source_positions: dict[object, int] = {}
                target_positions: dict[object, int] = {}
                source_duplicates: set[object] = set()
                target_duplicates: set[object] = set()
                for row in range(2, source_rows + 1):
                    key = _cell_value_key(source_val, source_edit, row, source_col)[2]
                    if key == _merge_cell_compare_key(None, None):
                        continue
                    if key in source_positions:
                        source_duplicates.add(key)
                    else:
                        source_positions[key] = row
                for row in range(2, target_rows + 1):
                    key = _cell_value_key(target_val, target_edit, row, target_col)[2]
                    if key == _merge_cell_compare_key(None, None):
                        continue
                    if key in target_positions:
                        target_duplicates.add(key)
                    else:
                        target_positions[key] = row
                populated_source = len(source_positions) + len(source_duplicates)
                populated_target = len(target_positions) + len(target_duplicates)
                if min(populated_source, populated_target) < 2:
                    continue
                unique_source = len(source_positions) / populated_source if populated_source else 0.0
                unique_target = len(target_positions) / populated_target if populated_target else 0.0
                if unique_source < 0.80 or unique_target < 0.80:
                    continue
                mapping = {1: 1} if source_rows and target_rows else {}
                for key, source_row in source_positions.items():
                    target_row = target_positions.get(key)
                    if (
                        target_row is not None
                        and key not in source_duplicates
                        and key not in target_duplicates
                    ):
                        mapping[source_row] = target_row
                shared_coverage = (len(mapping) - (1 if 1 in mapping else 0)) / min(
                    populated_source, populated_target
                )
                # This is the leftmost plausible identity candidate.  If it
                # does not explain most source/target records, a later unique
                # amount/status column is not a safe substitute.  That
                # preserves the a->x replacement guard while allowing
                # high-coverage business IDs in real workbooks to retain O(n)
                # mapping.
                if shared_coverage >= 0.80:
                    return mapping
                # Low coverage is not permission to try a later payload
                # column.  The exact shared keys are nevertheless proved
                # records (for example Target already contains Source After's
                # ``id=a`` while another target record was renamed), so retain
                # only that partial map and leave every missing key manual.
                return mapping

            def _project_rows(ws, row_count: int, columns: list[int]):
                return [
                    tuple(ws.cell(row=row, column=column).value for column in columns)
                    for row in range(1, row_count + 1)
                ]

            target_values = _project_rows(target_val, target_rows, target_columns)
            source_values = _project_rows(source_val, source_rows, source_columns)
            target_edits = _project_rows(target_edit, target_rows, target_columns)
            source_edits = _project_rows(source_edit, source_rows, source_columns)
            target_sigs, source_sigs = _row_signatures_from_unique_column_anchors(
                target_values,
                source_values,
                len(target_columns),
                len(source_columns),
                target_edits,
                source_edits,
            )
            target_to_source = _row_map_from_pairs(
                _compute_row_pairs_from_signatures(target_sigs, source_sigs)
            )
            # Equal grid dimensions are not row identity evidence.  Without a
            # semantic unique key above, require every mapped payload cell to
            # remain exactly equal to Source Before.  That is conservative for
            # target edits, but prevents an in-place record replacement from
            # inheriting Source After's value at the same physical row.
            def _proven_same_record(target_row: int, source_row: int) -> bool:
                if not (target_sigs[target_row - 1] and source_sigs[source_row - 1]):
                    return False
                return all(
                    _cell_value_key(source_val, source_edit, source_row, source_col)[2]
                    == _cell_value_key(target_val, target_edit, target_row, column_map[source_col])[2]
                    for source_col in source_columns
                )

            return {
                int(source_row): int(target_row)
                for target_row, source_row in target_to_source.items()
                if target_row is not None and source_row is not None
                and _proven_same_record(int(target_row), int(source_row))
            }
        except Exception as exc:
            _dlog(f"CROSS_BRANCH_SOURCE_DELTA row mapping unavailable: {exc}")
            return {}

    def _source_to_target_column_map(
        sheet: str,
        source_val,
        source_edit,
        target_val,
        target_edit,
        source_rows: int,
        target_rows: int,
        source_width: int,
        target_width: int,
    ) -> tuple[dict[int, int], int]:
        """Map Source-Before columns to Target Working logical columns.

        Target-only inserted/deleted columns are retained branch structure, so
        they contribute one diagnostic count each but are never treated as
        incoming source changes.  Cells in an unmapped source column remain
        safely unresolved only when Source After actually changes them.
        """
        try:
            cache = build_logical_column_comparison_cache_2way(
                ColumnModelCacheKey(sheet, 11, 1),
                _row_values(source_val, source_rows, source_width),
                _row_values(target_val, target_rows, target_width),
                _row_values(source_edit, source_rows, source_width),
                _row_values(target_edit, target_rows, target_width),
                mine_max_col=source_width,
                theirs_max_col=target_width,
            )
            mapping = {
                int(slot.mine_col): int(slot.theirs_col)
                for slot in cache.model.slots
                if slot.mine_col is not None
                and slot.theirs_col is not None
                and slot.state != "unresolved"
                and not slot.confidence.ambiguous
            }
            # Same ordinal dimensions with a normal header row are an explicit
            # identity proof even when a target-only cell change alters a full
            # column digest and weakens the signature cache.
            if source_width == target_width:
                for column in range(1, source_width + 1):
                    if column in mapping:
                        continue
                    source_header = _cell_value_key(source_val, source_edit, 1, column)[2]
                    target_header = _cell_value_key(target_val, target_edit, 1, column)[2]
                    if source_header == target_header and source_header != _merge_cell_compare_key(None, None):
                        mapping[column] = column
            retained_structural = sum(
                1
                for slot in cache.model.slots
                if (slot.mine_col is None) != (slot.theirs_col is None)
            )
            return mapping, retained_structural
        except Exception as exc:
            _dlog(f"CROSS_BRANCH_SOURCE_DELTA column mapping unavailable sheet={sheet}: {exc}")
            return {}, max(0, abs(int(target_width) - int(source_width)))

    try:
        source_before_path = _ensure_xlsx_copy(source_before_path)
        target_working_path = _ensure_xlsx_copy(target_working_path)
        source_after_path = _ensure_xlsx_copy(source_after_path)
        before_val_path = _prepare_val_path(source_before_path)
        target_val_path = _prepare_val_path(target_working_path)
        after_val_path = _prepare_val_path(source_after_path)
        prepared_paths.extend(((source_before_path, before_val_path), (target_working_path, target_val_path), (source_after_path, after_val_path)))

        wb_before_val = load_workbook(before_val_path, data_only=True, keep_links=False)
        wb_target_val = load_workbook(target_val_path, data_only=True, keep_links=False)
        wb_after_val = load_workbook(after_val_path, data_only=True, keep_links=False)
        wb_before_edit = load_workbook(
            source_before_path, data_only=False, keep_links=False,
            keep_vba=_is_macro_enabled_workbook(source_before_path),
        )
        wb_target_edit = load_workbook(
            target_working_path, data_only=False, keep_links=False,
            keep_vba=_is_macro_enabled_workbook(target_working_path),
        )
        wb_after_edit = load_workbook(
            source_after_path, data_only=False, keep_links=False,
            keep_vba=_is_macro_enabled_workbook(source_after_path),
        )
        workbooks.extend((wb_before_val, wb_target_val, wb_after_val, wb_before_edit, wb_target_edit, wb_after_edit))

        before_sheets = list(wb_before_val.sheetnames)
        after_sheets = list(wb_after_val.sheetnames)
        if before_sheets != after_sheets:
            source_sheet_changes = sorted(set(before_sheets).symmetric_difference(after_sheets))
            changed_sheet = source_sheet_changes[0] if source_sheet_changes else "<workbook>"
            return _decline(
                "Source Before/Source After sheet structure differs",
                changed_sheet,
            )

        # A target-only sheet and a target-deleted source sheet are branch
        # structure that must survive untouched.  They are not incoming source
        # content, so record each only as target-retained.
        target_sheet_names = set(wb_target_val.sheetnames)
        source_sheet_names = set(before_sheets)
        summary["target_retained_count"] += len(target_sheet_names - source_sheet_names)

        sheet_state: dict[str, tuple[int, int, int, int, dict[int, int], dict[int, int]]] = {}
        structurally_blocked_sheets: set[str] = set()
        source_has_supported_delta = False
        source_changed_cells_by_sheet: dict[str, set[str]] = {}
        source_has_formula_content = False
        source_has_string_delta = False
        for sheet in before_sheets:
            before_val = wb_before_val[sheet]
            after_val = wb_after_val[sheet]
            before_edit = wb_before_edit[sheet]
            after_edit = wb_after_edit[sheet]
            before_rows, before_width = _effective_bounds_with_edit(before_val, before_edit)
            after_rows, after_width = _effective_bounds_with_edit(after_val, after_edit)
            target_val = wb_target_val[sheet] if sheet in wb_target_val.sheetnames else None
            target_edit = wb_target_edit[sheet] if sheet in wb_target_edit.sheetnames else None

            # Derive row identities before touching either source projection or
            # Target Working.  The helper is the same bounded, key-aware row
            # alignment used by the manual three-way workspace.
            row_pairs = _compute_row_pairs_generic(
                before_val,
                after_val,
                max(1, max(before_width, after_width)),
                force=True,
                max_row_a=before_rows,
                max_row_b=after_rows,
                ws_a_edit=before_edit,
                ws_b_edit=after_edit,
            )
            row_ops = [pair for pair in row_pairs if (pair[0] is None) != (pair[1] is None)]

            before_value_rows = _row_values(before_val, before_rows, before_width)
            after_value_rows = _row_values(after_val, after_rows, after_width)
            before_edit_rows = _row_values(before_edit, before_rows, before_width)
            after_edit_rows = _row_values(after_edit, after_rows, after_width)
            column_cache = build_logical_column_comparison_cache_2way(
                ColumnModelCacheKey(sheet, 1, 1),
                before_value_rows,
                after_value_rows,
                before_edit_rows,
                after_edit_rows,
                mine_max_col=before_width,
                theirs_max_col=after_width,
            )
            # Same-width source sheets retain a physical 1:1 column identity
            # only when their ordered first-row identity tokens match.  A cell
            # value change can weaken a full-column signature (notably on
            # small enum sheets), so ``unresolved_cols`` alone is never source
            # structure.  A header replacement/reorder is the conservative
            # same-width structural signal.
            if before_width == after_width:
                column_ops = set()
                for column in range(1, before_width + 1):
                    before_header = _cell_value_key(before_val, before_edit, 1, column)[2]
                    after_header = _cell_value_key(after_val, after_edit, 1, column)[2]
                    if before_header != after_header:
                        column_ops.add((column, column))
            else:
                if column_cache.unresolved_cols:
                    return _decline(
                        "Source Before/Source After column identity is ambiguous",
                        sheet,
                    )
                column_ops = {
                    (slot.mine_col, slot.theirs_col)
                    for slot in column_cache.model.slots
                    if (slot.mine_col is None) != (slot.theirs_col is None)
                }
            column_ops = sorted(
                column_ops,
                key=lambda pair: (int(pair[1] or pair[0] or 0), int(pair[0] or pair[1] or 0)),
            )
            if before_width != after_width and column_cache.structural_diff_cols and not column_ops:
                return _decline(
                    "Source Before/Source After column structure has no safe logical projection",
                    sheet,
                )

            structural_count = len(row_ops) + len(column_ops)
            if structural_count:
                source_has_supported_delta = True
                # Row/column replays can alter merged cells, named ranges,
                # drawing anchors, formula references and VBA-bearing sheets.
                # The startup writer cannot yet prove all of those transforms,
                # so retain the source structural delta for manual resolution
                # rather than performing a partial openpyxl rewrite.  This is
                # intentionally one unresolved incoming item per aligned source
                # row/column operation and leaves Target Working byte-for-byte
                # untouched when nothing else is safely applicable.
                for before_row, after_row in row_ops:
                    summary["incoming_count"] += 1
                    _record_conflict(
                        sheet,
                        int(after_row or before_row or 1),
                        1,
                        "Source 结构变化待人工处理",
                        "Source Before → Source After 行插入/删除",
                    )
                for before_col, after_col in column_ops:
                    summary["incoming_count"] += 1
                    _record_conflict(
                        sheet,
                        1,
                        int(after_col or before_col or 1),
                        "Source 结构变化待人工处理",
                        "Source Before → Source After 列插入/删除",
                    )
                structurally_blocked_sheets.add(sheet)
            # No automatic structural rewrite occurs above.  Keep the original
            # Source Before coordinates only for non-structural sheets.
            before_rows, before_width = _effective_bounds_with_edit(before_val, before_edit)
            if target_val is None or target_edit is None:
                target_rows, target_width, source_to_target, source_to_target_cols = 0, 0, {}, {}
                retained_target_structure = 0
                # The target intentionally deleted an otherwise source-stable
                # sheet.  Retain that target branch decision as one logical
                # structural item; any source delta below will still become
                # unresolved because no target sheet can receive it.
                summary["target_retained_count"] += 1
            else:
                target_rows, target_width = _effective_bounds_with_edit(target_val, target_edit)
                source_to_target_cols, retained_target_structure = _source_to_target_column_map(
                    sheet,
                    before_val,
                    before_edit,
                    target_val,
                    target_edit,
                    before_rows,
                    target_rows,
                    before_width,
                    target_width,
                )
                source_to_target = _source_to_target_row_map(
                    before_val, before_edit, target_val, target_edit,
                    before_rows, target_rows, before_width, target_width,
                    source_to_target_cols,
                )
            sheet_state[sheet] = (
                before_rows,
                before_width,
                target_rows,
                target_width,
                source_to_target,
                source_to_target_cols,
            )
            if not structural_count and target_val is not None and target_edit is not None:
                # Target-only inserted/deleted rows are retained diagnostics,
                # never incoming source changes.  Count only source-stable
                # physical cells on proven same-ordinal columns; unmapped rows
                # are a safety/write decision, not by themselves target branch
                # structure (they may be ordinary blank/style padding).
                summary["target_retained_count"] += retained_target_structure
                if before_rows != target_rows:
                    def _semantic_row_present(ws_val, ws_edit, row_number: int, width: int) -> bool:
                        return any(
                            _cell_value_key(ws_val, ws_edit, row_number, column_number)[2]
                            != _merge_cell_compare_key(None, None)
                            for column_number in range(1, max(1, int(width)) + 1)
                        )

                    mapped_source_rows = set(source_to_target)
                    mapped_target_rows = set(source_to_target.values())
                    summary["target_retained_count"] += sum(
                        1
                        for row_number in (set(range(1, before_rows + 1)) - mapped_source_rows)
                        if _semantic_row_present(before_val, before_edit, row_number, before_width)
                    )
                    summary["target_retained_count"] += sum(
                        1
                        for row_number in (set(range(1, target_rows + 1)) - mapped_target_rows)
                        if _semantic_row_present(target_val, target_edit, row_number, target_width)
                    )
                else:
                    for row_number in range(1, before_rows + 1):
                        for source_col, target_col in source_to_target_cols.items():
                            if int(source_col) != int(target_col):
                                continue
                            _bv, _be, before_key = _cell_value_key(
                                before_val, before_edit, row_number, source_col
                            )
                            _av, _ae, after_key = _cell_value_key(
                                after_val, after_edit, row_number, source_col
                            )
                            _tv, _te, target_key = _cell_value_key(
                                target_val, target_edit, row_number, target_col
                            )
                            if before_key == after_key and target_key != before_key:
                                summary["target_retained_count"] += 1
            if not structural_count:
                for row in range(1, before_rows + 1):
                    for col in range(1, before_width + 1):
                        _, before_edit_value, before_key = _cell_value_key(before_val, before_edit, row, col)
                        _, after_edit_value, after_key = _cell_value_key(after_val, after_edit, row, col)
                        before_formula = _formula_text(before_edit_value)
                        after_formula = _formula_text(after_edit_value)
                        if before_formula is not None or after_formula is not None:
                            source_has_formula_content = True
                        if before_key != after_key:
                            source_has_supported_delta = True
                            summary["incoming_count"] += 1
                            source_changed_cells_by_sheet.setdefault(sheet, set()).add(
                                f"{get_column_letter(col)}{row}"
                            )
                            if (
                                (before_formula is None and isinstance(before_edit_value, str))
                                or (after_formula is None and isinstance(after_edit_value, str))
                            ):
                                source_has_string_delta = True

        # A package-level audit is required even when we found supported cell
        # deltas.  Without it a Source After tab color, document property,
        # comment, drawing or VBA member could disappear while the value write
        # looked successful.  Source row/column structure is already a manual
        # unit and is intentionally not double-counted here.
        if not structurally_blocked_sheets:
            representation_problem = _cross_branch_ooxml_representation_audit(
                source_before_path,
                source_after_path,
                source_changed_cells_by_sheet,
                has_formula_content=source_has_formula_content,
                has_string_delta=source_has_string_delta,
            )
            if representation_problem:
                return _decline(representation_problem)

        for sheet in before_sheets:
            before_val = wb_before_val[sheet]
            after_val = wb_after_val[sheet]
            before_edit = wb_before_edit[sheet]
            after_edit = wb_after_edit[sheet]
            target_val = wb_target_val[sheet] if sheet in wb_target_val.sheetnames else None
            target_edit = wb_target_edit[sheet] if sheet in wb_target_edit.sheetnames else None
            before_rows, before_width, target_rows, target_width, source_to_target, source_to_target_cols = sheet_state[sheet]
            if sheet in structurally_blocked_sheets:
                # A source structural delta is one atomic manual unit.  Do not
                # continue physical-cell projection on the same sheet, because
                # its coordinates may already have shifted.
                continue
            for row in range(1, before_rows + 1):
                target_row = source_to_target.get(row)
                for col in range(1, before_width + 1):
                    before_value, before_edit_value, before_key = _cell_value_key(before_val, before_edit, row, col)
                    after_value, after_edit_value, after_key = _cell_value_key(after_val, after_edit, row, col)
                    source_changed = before_key != after_key
                    target_col = source_to_target_cols.get(col)
                    if target_val is None or target_edit is None or not target_row or not target_col:
                        if source_changed:
                            _record_conflict(sheet, target_row or row, target_col or col, "目标行/列无法安全映射", after_value)
                        continue
                    target_value, target_edit_value, target_key = _cell_value_key(
                        target_val, target_edit, target_row, target_col
                    )
                    if not source_changed:
                        continue
                    if target_key == before_key:
                        try:
                            copied = _copy_edit_value_for_destination(
                                after_value,
                                after_edit_value,
                                target_edit_value,
                                src_row=row,
                                src_col=col,
                                dst_row=target_row,
                                dst_col=target_col,
                            )
                            if not _is_same_formula_copy_noop(copied, target_edit_value):
                                _assign_edit_cell_value(
                                    wb_target_edit[sheet].cell(row=target_row, column=target_col), copied
                                )
                            summary["applied_count"] += 1
                        except RuntimeError as exc:
                            _record_conflict(sheet, target_row, col, target_value, str(exc))
                    elif target_key == after_key:
                        summary["already_present_count"] += 1
                    else:
                        _record_conflict(sheet, target_row, col, target_value, after_value)

        if not source_has_supported_delta:
            source_equivalence = compare_ooxml_packages(
                source_before_path,
                source_after_path,
                left_role="source-before",
                right_role="source-after",
            )
            if not source_equivalence.package_equal:
                return _decline("Source package changed without a supported logical cell delta")

        summary["merged_count"] = summary["applied_count"]
        candidate = None
        if summary["applied_count"]:
            stamp = f"{datetime.now():%Y%m%d_%H%M%S}_{time.time_ns()}"
            candidate = os.path.join(
                tempfile.gettempdir(),
                f"{APP_NAME}_cross_branch_candidate_{os.getpid()}_{stamp}{_workbook_ext(target_working_path)}",
            )
            _atomic_save_wb(wb_target_edit, candidate)
        else:
            # Crucial for an all-already-present merge: openpyxl must not touch
            # OOXML members just to make a preview.  A direct Target Working
            # copy preserves raw/package equality for Building and audits.
            candidate = _create_startup_candidate_copy(target_working_path, "mine")
        _LAST_SEMANTIC_PREMERGE_SUMMARY = dict(summary)
        _dlog(
            "CROSS_BRANCH_SOURCE_DELTA "
            f"incoming={summary['incoming_count']} applied={summary['applied_count']} "
            f"already_present={summary['already_present_count']} "
            f"target_retained={summary['target_retained_count']} "
            f"unresolved={summary['unresolved_count']} candidate={candidate}"
        )
        return conflicts, candidate, conflict_cells_by_sheet, dict(summary), None
    except Exception as exc:
        return _decline(f"source-delta pre-merge failed safely: {exc}")
    finally:
        _wbs_close(*workbooks)
        for original, prepared in prepared_paths:
            if prepared != original:
                try:
                    os.remove(prepared)
                except Exception:
                    pass


def _merge_three_way(base_path: str, mine_path: str, theirs_path: str, merged_path: str, save_merged: bool = True):
    """3-way merge using row-aligned diff (consistent with _scan_three_way_conflicts).

    Conflict: mine and theirs both changed an aligned cell differently vs base.
    Non-conflicting theirs changes are applied onto mine for 1:1 aligned rows.

    Row alignment (via mine_to_base / theirs_to_base / display_pairs) is used instead
    of comparing by physical row number, so inserted/deleted rows no longer cause
    cross-row mis-comparison or theirs being written to the wrong row. Structural rows
    that exist on only one side (inserts/deletes) are left for the manual 3-way UI
    rather than blindly written by physical position.

    Returns (conflicts, merged_preview_path, conflict_cells_by_sheet).
    """
    global _LAST_SEMANTIC_PREMERGE_SUMMARY
    auto_merged_count = 0
    unresolved_structural_count = 0
    _LAST_SEMANTIC_PREMERGE_SUMMARY = {
        "merged_count": 0,
        "unresolved_structural_count": 0,
    }
    # The legacy auto-merge loop below is intentionally physical-column based.
    # Reuse the authoritative logical scan first and refuse to auto-write any
    # sheet with column structure/unresolved mapping; this prevents row mapping
    # from diverging between conflict scan and automatic save until the logical
    # column write pipeline is implemented in the later merge phase.
    preflight_started = time.perf_counter()
    preflight_conflicts, preflight_conflict_map = _scan_three_way_conflicts(
        base_path, mine_path, theirs_path
    )
    _dlog(
        "SEMANTIC_PREMERGE_PREFLIGHT "
        f"elapsed_ms={(time.perf_counter() - preflight_started) * 1000.0:.1f} "
        f"conflicts={len(preflight_conflicts)}"
    )
    structural_sheets = []
    for sheet_name, analysis in _LAST_THREE_WAY_COLUMN_ANALYSIS.items():
        if analysis.structural_conflicts or any(
            state.state not in ("retained", "modified")
            for state in analysis.states
        ):
            structural_sheets.append(sheet_name)
    if structural_sheets:
        preview = "、".join(structural_sheets[:6])
        if len(structural_sheets) > 6:
            preview += f" 等{len(structural_sheets)}张Sheet"
        raise _SemanticPremergeDeclined(
            "检测到列插入、删除或待确认映射，已停止旧版自动合并，"
            f"避免按物理列写错数据。涉及：{preview}",
            conflicts=preflight_conflicts,
            conflict_cells_by_sheet=preflight_conflict_map,
        )

    base_path = _ensure_xlsx_copy(base_path)
    mine_path = _ensure_xlsx_copy(mine_path)
    theirs_path = _ensure_xlsx_copy(theirs_path)

    base_val_path = _prepare_val_path(base_path)
    mine_val_path = _prepare_val_path(mine_path)
    theirs_val_path = _prepare_val_path(theirs_path)

    wb_base_val = load_workbook(base_val_path, data_only=True)
    wb_mine_val = load_workbook(mine_val_path, data_only=True)
    wb_theirs_val = load_workbook(theirs_val_path, data_only=True)
    wb_mine = load_workbook(mine_path, data_only=False)
    wb_base_edit = load_workbook(base_path, data_only=False)
    wb_theirs_edit = load_workbook(theirs_path, data_only=False)

    # Start merged as mine (copy in-memory by reusing workbook; then save to merged_path)
    wb_merged = wb_mine

    set_base = set(wb_base_val.sheetnames)
    set_mine = set(wb_mine_val.sheetnames)
    set_theirs = set(wb_theirs_val.sheetnames)

    # If a sheet exists only in theirs, copy into merged preserving formulas.
    only_theirs = sorted(set_theirs - set_mine)
    for name in only_theirs:
        ws_t = wb_theirs_edit[name]  # data_only=False preserves formulas
        ws_m = wb_merged.create_sheet(title=name)
        _copy_sheet_basic(ws_t, ws_m)
        auto_merged_count += 1

    conflicts = []
    conflict_cells_by_sheet = {}

    def _cmp_cell(
        ws_val,
        ws_edit,
        formula_map,
        row_idx: int | None,
        col_idx: int,
        compare_row: int | None = None,
    ):
        if ws_val is None or row_idx is None or row_idx <= 0:
            return None, _merge_cell_compare_key(None, None)
        try:
            vv = ws_val.cell(row=row_idx, column=col_idx).value
        except Exception:
            vv = None
        missing_formula = object()
        ve = formula_map.get((int(row_idx), int(col_idx)), missing_formula)
        if ve is missing_formula:
            ve = None
            if vv is None:
                try:
                    if ws_edit is not None:
                        ve = ws_edit.cell(row=row_idx, column=col_idx).value
                except Exception:
                    ve = None
        if compare_row is not None and row_idx != compare_row:
            ve = _translate_normal_formula_for_compare(
                vv, ve, row_idx, col_idx, compare_row, col_idx
            )
        cmp_v = vv
        try:
            if cmp_v is None:
                if ve is not None and not _formula_text(ve):
                    cmp_v = ve
        except Exception:
            pass
        return cmp_v, _merge_cell_compare_key(vv, ve)

    common = sorted(set_mine & set_theirs)
    for name in common:
        ws_b = wb_base_val[name] if name in set_base else None
        ws_m_val = wb_mine_val[name]
        ws_t = wb_theirs_val[name]
        ws_m_edit = wb_mine[name]
        ws_b_edit = wb_base_edit[name] if name in wb_base_edit.sheetnames else None
        ws_t_edit = wb_theirs_edit[name] if name in wb_theirs_edit.sheetnames else None
        formula_map_m = _formula_edit_value_map(ws_m_edit)
        formula_map_b = _formula_edit_value_map(ws_b_edit)
        formula_map_t = _formula_edit_value_map(ws_t_edit)

        mine_row_count, mine_width = _effective_bounds_with_edit(ws_m_val, ws_m_edit)
        theirs_row_count, theirs_width = _effective_bounds_with_edit(ws_t, ws_t_edit)
        if ws_b is not None:
            base_row_count, base_width = _effective_bounds_with_edit(ws_b, ws_b_edit)
        else:
            base_row_count, base_width = 0, 0
        max_col = max(mine_width, theirs_width, base_width, 1)

        mine_display_count, theirs_display_count = _shared_physical_row_horizon(
            ws_m_val,
            ws_t,
            mine_row_count,
            theirs_row_count,
            ws_m_edit,
            ws_t_edit,
        )
        mine_base_count = mine_row_count
        theirs_base_count = theirs_row_count
        base_mine_count = base_row_count
        base_theirs_count = base_row_count
        if ws_b is not None:
            mine_base_count, base_mine_count = _shared_physical_row_horizon(
                ws_m_val,
                ws_b,
                mine_row_count,
                base_row_count,
                ws_m_edit,
                ws_b_edit,
            )
            theirs_base_count, base_theirs_count = _shared_physical_row_horizon(
                ws_t,
                ws_b,
                theirs_row_count,
                base_row_count,
                ws_t_edit,
                ws_b_edit,
            )
        mine_read_count = max(mine_display_count, mine_base_count)
        theirs_read_count = max(theirs_display_count, theirs_base_count)
        base_read_count = max(base_mine_count, base_theirs_count)

        def _cached_rows(ws, row_count: int, width: int):
            if ws is None or row_count <= 0 or width <= 0:
                return []
            cache = _read_rows_into_cache(ws, range(1, row_count + 1), width)
            return [
                _row_from_cache(cache, row_idx, width)
                for row_idx in range(1, row_count + 1)
            ]

        mine_value_rows = _cached_rows(ws_m_val, mine_read_count, max_col)
        theirs_value_rows = _cached_rows(ws_t, theirs_read_count, max_col)
        base_value_rows = _cached_rows(ws_b, base_read_count, max_col)
        mine_edit_rows = _cached_rows(ws_m_edit, mine_read_count, max_col)
        theirs_edit_rows = _cached_rows(ws_t_edit, theirs_read_count, max_col)
        base_edit_rows = _cached_rows(ws_b_edit, base_read_count, max_col)

        # Same typed, formula-aware row-alignment pipeline as
        # _scan_three_way_conflicts so auto-merge and the UI cannot diverge
        # when formula caches are absent after a structural column edit.
        mine_sigs, base_sigs_for_mine = _row_signatures_from_unique_column_anchors(
            mine_value_rows[:mine_base_count],
            base_value_rows[:base_mine_count],
            mine_width,
            base_width,
            mine_edit_rows[:mine_base_count],
            base_edit_rows[:base_mine_count],
        )
        theirs_sigs, base_sigs_for_theirs = _row_signatures_from_unique_column_anchors(
            theirs_value_rows[:theirs_base_count],
            base_value_rows[:base_theirs_count],
            theirs_width,
            base_width,
            theirs_edit_rows[:theirs_base_count],
            base_edit_rows[:base_theirs_count],
        )
        mine_to_base = _row_map_from_pairs(
            _compute_row_pairs_from_signatures(mine_sigs, base_sigs_for_mine)
        ) if ws_b is not None else {}
        theirs_to_base = _row_map_from_pairs(
            _compute_row_pairs_from_signatures(theirs_sigs, base_sigs_for_theirs)
        ) if ws_b is not None else {}
        mine_display_sigs, theirs_display_sigs = _row_signatures_from_unique_column_anchors(
            mine_value_rows[:mine_display_count],
            theirs_value_rows[:theirs_display_count],
            mine_width,
            theirs_width,
            mine_edit_rows[:mine_display_count],
            theirs_edit_rows[:theirs_display_count],
        )
        display_pairs = _compute_row_pairs_from_signatures(
            mine_display_sigs, theirs_display_sigs
        )
        if ws_b is not None:
            display_pairs = _reconcile_three_way_row_pairs_by_base(
                display_pairs,
                mine_to_base,
                theirs_to_base,
                ws_m_val,
                ws_t,
                max_col,
            )
            display_pairs = _split_tail_independent_append_pairs(
                display_pairs, mine_to_base, theirs_to_base,
                ws_m_val, ws_t, max_col,
            )
            display_pairs = _split_low_similarity_tail_pairs(
                display_pairs,
                mine_to_base,
                theirs_to_base,
                ws_m_val,
                ws_t,
                max_col,
            )

        for ra, rb in display_pairs:
            base_row_m = mine_to_base.get(ra) if ra is not None else None
            base_row_t = theirs_to_base.get(rb) if rb is not None else None
            for c in range(1, max_col + 1):
                compare_row = ra if ra is not None else rb
                vm_cmp, vm_key = _cmp_cell(ws_m_val, ws_m_edit, formula_map_m, ra, c, compare_row)
                vt_cmp, vt_key = _cmp_cell(ws_t, ws_t_edit, formula_map_t, rb, c, compare_row)
                conflict_row = ra if ra is not None else (rb if rb is not None else 0)

                # Aligned 1:1 row sharing a base row -> full 3-way cell logic.
                if ra is not None and rb is not None and base_row_m is not None and base_row_m == base_row_t:
                    vb_cmp, vb_key = _cmp_cell(ws_b, ws_b_edit, formula_map_b, base_row_m, c, compare_row)
                    if vb_cmp is None and vt_cmp is not None and ws_b_edit is not None and ws_t_edit is not None:
                        try:
                            if _same_formula(ws_b_edit.cell(row=base_row_m, column=c).value, ws_t_edit.cell(row=rb, column=c).value):
                                vb_cmp = vt_cmp
                                vb_key = vt_key
                        except Exception:
                            pass
                    mine_changed = (vm_key != vb_key)
                    theirs_changed = (vt_key != vb_key)
                    if mine_changed and theirs_changed:
                        if vm_key != vt_key:
                            conflicts.append((name, conflict_row, c, vm_cmp, vt_cmp))
                            conflict_cells_by_sheet.setdefault(name, {}).setdefault(conflict_row, set()).add(c)
                        else:
                            # Both changed identically relative to Base.  Mine
                            # already contains the result, but it is still an
                            # auditable automatic semantic merge decision.
                            auto_merged_count += 1
                    elif mine_changed and (not theirs_changed):
                        # Mine's one-sided change is already present in the
                        # candidate and is counted as an automatic keep.
                        auto_merged_count += 1
                    elif (not mine_changed) and theirs_changed:
                        # Safe to apply theirs onto mine's aligned row (preserve formulas).
                        _t_edit_v = ws_t_edit.cell(row=rb, column=c).value if ws_t_edit is not None else None
                        _m_edit_v = ws_m_edit.cell(row=ra, column=c).value
                        try:
                            _new_edit_v = _copy_edit_value_for_destination(
                                vt_cmp,
                                _t_edit_v,
                                _m_edit_v,
                                src_row=rb,
                                src_col=c,
                                dst_row=ra,
                                dst_col=c,
                            )
                        except RuntimeError:
                            conflicts.append((name, conflict_row, c, vm_cmp, vt_cmp))
                            conflict_cells_by_sheet.setdefault(name, {}).setdefault(conflict_row, set()).add(c)
                            continue
                        if not _is_same_formula_copy_noop(_new_edit_v, _m_edit_v):
                            _assign_edit_cell_value(
                                ws_m_edit.cell(row=ra, column=c),
                                _new_edit_v,
                            )
                            auto_merged_count += 1
                    continue

                # Both sides added the same logical row independently (no shared base):
                # differing values are a conflict for manual resolution.
                if ra is not None and rb is not None and base_row_m is None and base_row_t is None:
                    if vm_key != vt_key:
                        conflicts.append((name, conflict_row, c, vm_cmp, vt_cmp))
                        conflict_cells_by_sheet.setdefault(name, {}).setdefault(conflict_row, set()).add(c)
                elif ra is None or rb is None:
                    # A Mine-only inserted row has no Base identity and is
                    # already safely retained in the Mine candidate.  Do not
                    # turn that proven preservation into a false conflict: a
                    # later aligned Theirs change can still be applied through
                    # the normal Base mapping.  Theirs-only insertion or either
                    # deletion case still lacks a safe write mapping here.
                    safe_mine_only_insert = (
                        ra is not None and rb is None and base_row_m is None
                    )
                    if c == 1 and not safe_mine_only_insert:
                        conflicts.append((name, conflict_row, 1, "未支持的行结构变化", "未支持的行结构变化"))
                        conflict_cells_by_sheet.setdefault(name, {}).setdefault(conflict_row, set()).add(1)
                        unresolved_structural_count += 1

    _merge_result = None
    try:
        # Always save a preview for UI if needed
        if conflicts or (not save_merged):
            ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            preview = os.path.join(
                tempfile.gettempdir(),
                f"{APP_NAME}_merged_preview_{os.getpid()}_{ts}{_workbook_ext(merged_path or mine_path)}",
            )
            _atomic_save_wb(wb_merged, preview)
            _merge_result = (conflicts, preview, conflict_cells_by_sheet)
        else:
            # No conflicts: save directly to merged path
            _atomic_save_wb(wb_merged, merged_path)
            _merge_result = ([], None, {})
    finally:
        _wbs_close(wb_base_val, wb_mine_val, wb_theirs_val, wb_mine, wb_base_edit, wb_theirs_edit)
        for _orig, _vp in ((base_path, base_val_path), (mine_path, mine_val_path), (theirs_path, theirs_val_path)):
            if _vp != _orig:
                try:
                    os.remove(_vp)
                except Exception:
                    pass
    _LAST_SEMANTIC_PREMERGE_SUMMARY = {
        "merged_count": int(auto_merged_count),
        "unresolved_structural_count": int(unresolved_structural_count),
    }
    return _merge_result


_LAST_THREE_WAY_COLUMN_ANALYSIS: dict[str, LogicalThreeWayColumnAnalysis] = {}
_LAST_SEMANTIC_PREMERGE_SUMMARY: dict[str, int] = {
    "merged_count": 0,
    "unresolved_structural_count": 0,
}


def _scan_three_way_conflicts(base_path: str, mine_path: str, theirs_path: str):
    """Detect cell and structural conflicts through cached logical columns."""
    base_path = _ensure_xlsx_copy(base_path)
    mine_path = _ensure_xlsx_copy(mine_path)
    theirs_path = _ensure_xlsx_copy(theirs_path)

    base_val_path = _prepare_val_path(base_path)
    mine_val_path = _prepare_val_path(mine_path)
    theirs_val_path = _prepare_val_path(theirs_path)

    wb_base_val = None
    wb_mine_val = None
    wb_theirs_val = None
    wb_mine_edit = None
    wb_base_edit = None
    wb_theirs_edit = None
    try:
        wb_base_val = load_workbook(base_val_path, data_only=True)
        wb_mine_val = load_workbook(mine_val_path, data_only=True)
        wb_theirs_val = load_workbook(theirs_val_path, data_only=True)
        wb_mine_edit = load_workbook(mine_path, data_only=False)
        wb_base_edit = load_workbook(base_path, data_only=False)
        wb_theirs_edit = load_workbook(theirs_path, data_only=False)

        conflicts = []
        conflict_cells_by_sheet = {}
        seen_conflicts = set()
        analyses = {}

        set_base = set(wb_base_val.sheetnames)
        set_mine = set(wb_mine_val.sheetnames)
        set_theirs = set(wb_theirs_val.sheetnames)

        def _sequential_rows(ws, max_row: int, max_col: int):
            if ws is None or max_row <= 0 or max_col <= 0:
                return []
            rows = []
            for row in ws.iter_rows(
                min_row=1,
                max_row=max_row,
                min_col=1,
                max_col=max_col,
                values_only=True,
            ):
                rows.append(_pad_row_values(row, max_col))
            return rows

        def _row(rows, row_idx: int | None, width: int):
            if row_idx is None or row_idx <= 0 or row_idx > len(rows):
                return (None,) * width
            return _pad_row_values(rows[row_idx - 1], width)

        def _effective_display(value_row, edit_row, physical_col: int | None):
            if physical_col is None:
                return None
            value = _logical_row_value(value_row, physical_col)
            edit = _logical_row_value(edit_row, physical_col)
            if value is None and edit is not None and not _formula_text(edit):
                return edit
            return value if value is not None else _formula_text(edit)

        def _add_conflict(name, row_idx, logical_col, mine_value, theirs_value):
            row_idx = max(1, int(row_idx or 1))
            logical_col = max(1, int(logical_col))
            key = (name, row_idx, logical_col)
            if key in seen_conflicts:
                return
            seen_conflicts.add(key)
            conflicts.append((name, row_idx, logical_col, mine_value, theirs_value))
            conflict_cells_by_sheet.setdefault(name, {}).setdefault(row_idx, set()).add(logical_col)

        for name in sorted(set_mine & set_theirs):
            ws_base_val = wb_base_val[name] if name in set_base else None
            ws_mine_val = wb_mine_val[name]
            ws_theirs_val = wb_theirs_val[name]
            ws_mine_edit = wb_mine_edit[name]
            ws_base_edit = wb_base_edit[name] if name in wb_base_edit.sheetnames else None
            ws_theirs_edit = wb_theirs_edit[name] if name in wb_theirs_edit.sheetnames else None

            mine_row_count, mine_width = _effective_bounds_with_edit(
                ws_mine_val, ws_mine_edit
            )
            theirs_row_count, theirs_width = _effective_bounds_with_edit(
                ws_theirs_val, ws_theirs_edit
            )
            if ws_base_val is not None:
                base_row_count, base_width = _effective_bounds_with_edit(
                    ws_base_val, ws_base_edit
                )
            else:
                base_row_count, base_width = 0, 0
            scan_width = max(mine_width, base_width, theirs_width, 1)

            mine_display_count, theirs_display_count = _shared_physical_row_horizon(
                ws_mine_val,
                ws_theirs_val,
                mine_row_count,
                theirs_row_count,
                ws_mine_edit,
                ws_theirs_edit,
            )
            mine_base_count = mine_row_count
            theirs_base_count = theirs_row_count
            base_mine_count = base_row_count
            base_theirs_count = base_row_count
            if ws_base_val is not None:
                mine_base_count, base_mine_count = _shared_physical_row_horizon(
                    ws_mine_val,
                    ws_base_val,
                    mine_row_count,
                    base_row_count,
                    ws_mine_edit,
                    ws_base_edit,
                )
                theirs_base_count, base_theirs_count = _shared_physical_row_horizon(
                    ws_theirs_val,
                    ws_base_val,
                    theirs_row_count,
                    base_row_count,
                    ws_theirs_edit,
                    ws_base_edit,
                )
            mine_read_count = max(mine_display_count, mine_base_count)
            theirs_read_count = max(theirs_display_count, theirs_base_count)
            base_read_count = max(base_mine_count, base_theirs_count)

            mine_value_rows = _sequential_rows(ws_mine_val, mine_read_count, scan_width)
            theirs_value_rows = _sequential_rows(ws_theirs_val, theirs_read_count, scan_width)
            base_value_rows = _sequential_rows(ws_base_val, base_read_count, scan_width)
            mine_edit_rows = _sequential_rows(ws_mine_edit, mine_read_count, scan_width)
            theirs_edit_rows = _sequential_rows(ws_theirs_edit, theirs_read_count, scan_width)
            base_edit_rows = _sequential_rows(ws_base_edit, base_read_count, scan_width)

            mine_sigs, base_sigs_for_mine = _row_signatures_from_unique_column_anchors(
                mine_value_rows[:mine_base_count],
                base_value_rows[:base_mine_count],
                mine_width,
                base_width,
                mine_edit_rows[:mine_base_count],
                base_edit_rows[:base_mine_count],
            )
            theirs_sigs, base_sigs_for_theirs = _row_signatures_from_unique_column_anchors(
                theirs_value_rows[:theirs_base_count],
                base_value_rows[:base_theirs_count],
                theirs_width,
                base_width,
                theirs_edit_rows[:theirs_base_count],
                base_edit_rows[:base_theirs_count],
            )
            mine_to_base = (
                _row_map_from_pairs(
                    _compute_row_pairs_from_signatures(mine_sigs, base_sigs_for_mine)
                )
                if base_sigs_for_mine else {}
            )
            theirs_to_base = (
                _row_map_from_pairs(
                    _compute_row_pairs_from_signatures(theirs_sigs, base_sigs_for_theirs)
                )
                if base_sigs_for_theirs else {}
            )
            mine_display_sigs, theirs_display_sigs = _row_signatures_from_unique_column_anchors(
                mine_value_rows[:mine_display_count],
                theirs_value_rows[:theirs_display_count],
                mine_width,
                theirs_width,
                mine_edit_rows[:mine_display_count],
                theirs_edit_rows[:theirs_display_count],
            )
            display_pairs = _compute_row_pairs_from_signatures(
                mine_display_sigs, theirs_display_sigs
            )
            if ws_base_val is not None:
                display_pairs = _reconcile_three_way_row_pairs_by_base(
                    display_pairs,
                    mine_to_base,
                    theirs_to_base,
                    ws_mine_val,
                    ws_theirs_val,
                    scan_width,
                )
                display_pairs = _split_tail_independent_append_pairs(
                    display_pairs,
                    mine_to_base,
                    theirs_to_base,
                    ws_mine_val,
                    ws_theirs_val,
                    scan_width,
                )
                display_pairs = _split_low_similarity_tail_pairs(
                    display_pairs,
                    mine_to_base,
                    theirs_to_base,
                    ws_mine_val,
                    ws_theirs_val,
                    scan_width,
                )

            aligned_base_rows = []
            aligned_base_edit_rows = []
            for mine_row, theirs_row in display_pairs:
                base_mine_row = mine_to_base.get(mine_row) if mine_row is not None else None
                base_theirs_row = theirs_to_base.get(theirs_row) if theirs_row is not None else None
                common_base_row = (
                    base_mine_row
                    if base_mine_row is not None and base_mine_row == base_theirs_row
                    else base_mine_row if theirs_row is None
                    else base_theirs_row if mine_row is None
                    else None
                )
                aligned_base_rows.append(_row(base_value_rows, common_base_row, scan_width))
                aligned_base_edit_rows.append(_row(base_edit_rows, common_base_row, scan_width))
            aligned_mine_rows = [_row(mine_value_rows, ra, scan_width) for ra, _rb in display_pairs]
            aligned_theirs_rows = [_row(theirs_value_rows, rb, scan_width) for _ra, rb in display_pairs]
            aligned_mine_edit_rows = [_row(mine_edit_rows, ra, scan_width) for ra, _rb in display_pairs]
            aligned_theirs_edit_rows = [_row(theirs_edit_rows, rb, scan_width) for _ra, rb in display_pairs]

            column_cache = build_logical_column_comparison_cache_3way(
                ColumnModelCacheKey(name, 1, 1),
                aligned_mine_rows,
                aligned_base_rows,
                aligned_theirs_rows,
                aligned_mine_edit_rows,
                aligned_base_edit_rows,
                aligned_theirs_edit_rows,
                mine_max_col=mine_width,
                base_max_col=base_width,
                theirs_max_col=theirs_width,
            )
            mine_changed_cols = set()
            theirs_changed_cols = set()
            first_mine_change_row = {}
            first_theirs_change_row = {}

            for pair_idx, (mine_row, theirs_row) in enumerate(display_pairs):
                base_mine_row = mine_to_base.get(mine_row) if mine_row is not None else None
                base_theirs_row = theirs_to_base.get(theirs_row) if theirs_row is not None else None
                mine_value_row = aligned_mine_rows[pair_idx]
                theirs_value_row = aligned_theirs_rows[pair_idx]
                mine_edit_row = aligned_mine_edit_rows[pair_idx]
                theirs_edit_row = aligned_theirs_edit_rows[pair_idx]
                conflict_row = mine_row if mine_row is not None else theirs_row

                if (
                    mine_row is not None
                    and theirs_row is not None
                    and base_mine_row is not None
                    and base_mine_row == base_theirs_row
                ):
                    base_value_row = _row(base_value_rows, base_mine_row, scan_width)
                    base_edit_row = _row(base_edit_rows, base_mine_row, scan_width)
                    row_result = compare_logical_row_3way(
                        column_cache,
                        mine_value_row,
                        base_value_row,
                        theirs_value_row,
                        mine_edit_row,
                        base_edit_row,
                        theirs_edit_row,
                        mine_row=mine_row,
                        base_row=base_mine_row,
                        theirs_row=theirs_row,
                    )
                    mine_changed_cols.update(row_result.mine_changed_cols)
                    theirs_changed_cols.update(row_result.theirs_changed_cols)
                    for logical_col in row_result.mine_changed_cols:
                        first_mine_change_row.setdefault(logical_col, conflict_row or 1)
                    for logical_col in row_result.theirs_changed_cols:
                        first_theirs_change_row.setdefault(logical_col, conflict_row or 1)
                    for logical_col in row_result.conflict_cols:
                        slot = column_cache.model.slots[logical_col - 1]
                        _add_conflict(
                            name,
                            conflict_row,
                            logical_col,
                            _effective_display(mine_value_row, mine_edit_row, slot.mine_col),
                            _effective_display(theirs_value_row, theirs_edit_row, slot.theirs_col),
                        )
                    continue

                if (
                    mine_row is not None
                    and theirs_row is not None
                    and base_mine_row is None
                    and base_theirs_row is None
                ):
                    added_row_result = compare_logical_row_2way(
                        column_cache,
                        mine_value_row,
                        theirs_value_row,
                        mine_edit_row,
                        theirs_edit_row,
                        mine_row=mine_row,
                        theirs_row=theirs_row,
                    )
                    for logical_col in added_row_result.diff_cols:
                        if logical_col < 1:
                            continue
                        slot = column_cache.model.slots[logical_col - 1]
                        _add_conflict(
                            name,
                            conflict_row,
                            logical_col,
                            _effective_display(mine_value_row, mine_edit_row, slot.mine_col),
                            _effective_display(theirs_value_row, theirs_edit_row, slot.theirs_col),
                        )

            mine_metadata = _worksheet_column_metadata_fingerprints(ws_mine_edit, mine_width)
            base_metadata = _worksheet_column_metadata_fingerprints(ws_base_edit, base_width)
            theirs_metadata = _worksheet_column_metadata_fingerprints(ws_theirs_edit, theirs_width)
            mine_metadata_changed, theirs_metadata_changed = logical_metadata_changes_from_base(
                column_cache,
                mine_metadata,
                base_metadata,
                theirs_metadata,
            )
            trusted_same_ordinal_cols = set()
            mine_header_values = _row(mine_value_rows, 1, scan_width)
            base_header_values = _row(base_value_rows, 1, scan_width)
            theirs_header_values = _row(theirs_value_rows, 1, scan_width)
            mine_header_edits = _row(mine_edit_rows, 1, scan_width)
            base_header_edits = _row(base_edit_rows, 1, scan_width)
            theirs_header_edits = _row(theirs_edit_rows, 1, scan_width)
            for slot in column_cache.model.slots:
                if not (
                    slot.base_col is not None
                    and slot.mine_col == slot.base_col == slot.theirs_col
                ):
                    continue
                mine_header_key = _merge_cell_compare_key(
                    _logical_row_value(mine_header_values, slot.mine_col),
                    _logical_row_value(mine_header_edits, slot.mine_col),
                )
                base_header_key = _merge_cell_compare_key(
                    _logical_row_value(base_header_values, slot.base_col),
                    _logical_row_value(base_header_edits, slot.base_col),
                )
                theirs_header_key = _merge_cell_compare_key(
                    _logical_row_value(theirs_header_values, slot.theirs_col),
                    _logical_row_value(theirs_header_edits, slot.theirs_col),
                )
                if mine_header_key == base_header_key == theirs_header_key:
                    trusted_same_ordinal_cols.add(slot.logical_idx + 1)
            analysis = classify_logical_columns_3way(
                column_cache,
                mine_changed_cols=mine_changed_cols,
                theirs_changed_cols=theirs_changed_cols,
                mine_metadata_changed_cols=mine_metadata_changed,
                theirs_metadata_changed_cols=theirs_metadata_changed,
                trusted_same_ordinal_cols=trusted_same_ordinal_cols,
            )
            analyses[name] = analysis
            for structural_conflict in analysis.structural_conflicts:
                logical_col = structural_conflict.logical_col
                slot = column_cache.model.slots[logical_col - 1]
                if structural_conflict.kind == "delete-versus-modify":
                    if structural_conflict.state == "mine-deleted":
                        row_idx = first_theirs_change_row.get(logical_col, 1)
                    else:
                        row_idx = first_mine_change_row.get(logical_col, 1)
                else:
                    row_idx = 1
                mine_value_row = _row(mine_value_rows, row_idx, scan_width)
                theirs_value_row = _row(theirs_value_rows, row_idx, scan_width)
                mine_edit_row = _row(mine_edit_rows, row_idx, scan_width)
                theirs_edit_row = _row(theirs_edit_rows, row_idx, scan_width)
                _add_conflict(
                    name,
                    row_idx,
                    logical_col,
                    _effective_display(mine_value_row, mine_edit_row, slot.mine_col),
                    _effective_display(theirs_value_row, theirs_edit_row, slot.theirs_col),
                )

        _LAST_THREE_WAY_COLUMN_ANALYSIS.clear()
        _LAST_THREE_WAY_COLUMN_ANALYSIS.update(analyses)
        return conflicts, conflict_cells_by_sheet
    finally:
        _wbs_close(wb_base_val, wb_mine_val, wb_theirs_val, wb_mine_edit, wb_base_edit, wb_theirs_edit)
        for _orig, _vp in ((base_path, base_val_path), (mine_path, mine_val_path), (theirs_path, theirs_val_path)):
            if _vp != _orig:
                try:
                    os.remove(_vp)
                except Exception:
                    pass


@dataclass(frozen=True)
class _DiffBlock:
    ordinal: int
    pair_indices: tuple[int, ...]
    start_pair_idx: int
    end_pair_idx: int
    pending: bool


class SheetView:
    """TortoiseMerge-like side-by-side full-sheet viewer.

    Performance notes (optimized for responsiveness):
    - Avoids O(N) tag_remove across the whole document on every click.
    - Avoids per-cell ws.cell access loops during normal interactions.
    - Keeps per-row cached text and per-row diff columns; row merge refreshes only that row.
    """

    def __init__(self, parent, app, sheet_name: str):
        self.parent = parent
        self.app = app
        self.root = getattr(app, "root", None)
        self.sheet = sheet_name
        self.role_presentation = RolePresentation.for_app(app)
        # Support lazy tab containers: if parent is already a tab frame, reuse it.
        if isinstance(parent, ttk.Frame) and not parent.winfo_children():
            self.frame = parent
        else:
            self.frame = ttk.Frame(parent)

        self.max_row = 1
        self.max_col = 1
        self.col_max_a = 1  # column count of side A (may differ from B)
        self.col_max_b = 1  # column count of side B
        self.col_max_base = 1
        self._bounds_checked = False
        self._base_bounds_checked = False
        # Every logical column in a Sheet intentionally shares this bounded
        # display width.  Keeping the geometry independent from sampled cell
        # content makes A/Base/B/C panes stable while scrolling or loading.
        self._logical_column_display_width = _LOGICAL_COLUMN_DISPLAY_WIDTH_MIN
        self._logical_column_widths: tuple[int, ...] = ()
        self._logical_column_widths_key = None
        # Compatibility map consumed by the existing formatter/hit testing.
        self.col_char_widths: dict[int, int] = {}
        self._rownum_display_width: int = 3  # right-justified row number gutter width
        self._row_header_width: int = 4

        # Cached row text and diff cols
        self.row_text_a: dict[int, str] = {}
        self.row_text_b: dict[int, str] = {}
        self.diff_cols_by_row: dict[int, set[int]] = {}
        self._display_diff_row_count: int = 0
        self._sample_scan_started = False
        # Row alignment (pair-wise) caches
        self.row_pairs: list[tuple[int | None, int | None]] = []
        self.pair_text_a: dict[int, str] = {}
        self.pair_text_b: dict[int, str] = {}
        self.pair_text_base: dict[int, str] = {}
        self.pair_parts_a: dict[int, tuple[str, ...]] = {}
        self.pair_parts_b: dict[int, tuple[str, ...]] = {}
        self.pair_parts_base: dict[int, tuple[str, ...]] = {}
        self.pair_diff_cols: dict[int, set[int]] = {}
        self.pair_base_diff_cols: dict[int, set[int]] = {}
        self.row_a_to_pair_idx: dict[int, int] = {}
        self.row_b_to_pair_idx: dict[int, int] = {}
        self.mine_to_base_row: dict[int, int] = {}
        self.theirs_to_base_row: dict[int, int] = {}
        self.pair_base_row_override: dict[int, int | None] = {}
        self._missing_base_row_map: dict[int, int] = {}
        self.column_comparison_cache: LogicalColumnComparisonCache | None = None
        self.column_projection: LogicalColumnProjection | None = None
        self.column_alignment_2way: ColumnAlignmentResult | None = None
        self.column_alignment_3way: ColumnAlignment3WayResult | None = None
        self.logical_column_states: tuple[LogicalColumnState, ...] = ()
        self.logical_column_structural_conflicts: tuple[LogicalColumnStructuralConflict, ...] = ()
        self._row_model_version = 0
        self._column_model_version = 0
        self._mine_edit_version = 0
        self._base_edit_version = 0
        self._theirs_edit_version = 0
        self._column_projection_generation = 0
        self._column_mapping_stale_reason = ""
        # A column-only mapping rebuild must not rerun row alignment against
        # temporarily different physical column positions.  Callers that know
        # rows changed set ``row_structure=True`` and clear this request.
        self._row_alignment_reuse_requested = False

        # Render state
        # display_rows stores pair indices (into row_pairs)
        self.display_rows: list[int] = []
        self._full_display_rows: list[int] = []
        self._render_limit: int = _FAST_RENDER_ROW_LIMIT
        self.row_to_line: dict[int, int] = {}
        self._pending_yview: float | None = None
        self._render_cache = {}
        self._data_version = 0
        # Minimap (diff map) throttle: cache diff rows/cols keyed by data version,
        # debounce redraws triggered by scrolling.
        self._diff_map_cache_version = None
        self._diff_map_cache = None
        self._diff_map_debounce_id = None
        self._diff_map_debounce_ms = 40
        self.selected_excel_row: int | None = None
        self.selected_excel_row_a: int | None = None
        self.selected_excel_row_b: int | None = None
        self.selected_pair_idx: int | None = None
        self._last_selected_line: int | None = None
        self._main_sel_col: int | None = None
        self._main_sel_line: int | None = None
        self.selected_column_block_ordinal: int | None = None
        self.selected_column_logical_range: tuple[int, int] | None = None
        self.selected_column_source_side: str | None = None
        self._selected_column_projection_generation: int | None = None
        # Each column projection gets at most one automatic structural-block
        # selection. A user clear in the same projection remains respected,
        # while an accepted block may reveal the next pending block after the
        # projection is rebuilt.
        self._auto_structural_selection_generation: int | None = None
        self._retained_column_decisions: set[tuple[int, int, str]] = set()
        # Logical common insertions explicitly accepted from the opposite
        # current side.  Row alignment may pair different physical row
        # numbers, so a freshly copied column can otherwise look changed on
        # those shifted pairs.  The visual filter below suppresses that noise
        # only while the source and target cells at the copied physical row
        # remain formula/value equivalent.
        self._accepted_common_insert_sources: dict[int, str] = {}
        self._applied_main_sel_col: int | None = None
        self._applied_main_sel_line: int | None = None
        self._cursor_cmp_sel_col: int | None = None
        self._cursor_cmp_sel_line: int | None = None
        self.hover_pair_idx: int | None = None
        self.hover_col_idx: int | None = None
        self.hover_side: str | None = None
        self._last_cursor_cmp_pair_idx: int | None = None
        self._trace_click_until: float = 0.0
        self._click_trace_seq: int = 0
        self._is_large_sheet = False
        self._prefer_only_diff_when_ready = False
        self._pending_only_diff_value: int | None = None
        self._diff_partial = False
        # True only when ``pair_diff_cols`` represents an exact 2-way scan of
        # every aligned pair (equal rows may be omitted).  Column actions may
        # reuse that model only after proving the old/new slot mapping; every
        # other path falls back to the normal full scan.
        self._pair_diff_full_exact = False
        self._base_diff_full_exact = False
        self._cache_formula_aware = False
        self._row_model_exact = False
        self._only_diff_rows_exact = False
        self._lifecycle_generation = 0
        self._lifecycle_state = "LOADING"
        self._lifecycle_error: str | None = None
        self._lifecycle_canceled = False
        self._only_diff_preview_full = False
        self._mode_switch_pending = False
        self._mode_switch_seq = 0
        self._mode_switch_after_id = None
        self._pending_exact_render = False
        self._pending_pair_parts_cache = None
        self._pending_column_only_diff_seed = None
        self._column_diff_seed_last = {"used": False, "reason": "not-attempted"}
        self._align_rows_enabled = True
        self._force_sequence_align = False
        # After user-triggered rescan/toggle, ignore late background cache apply for this sheet
        # to avoid delayed stale overwrite (rows unexpectedly disappear a few seconds later).
        self._suppress_bg_apply = False
        self._formula_copy_skips_pending = 0
        # Set to True once initial diff data has been computed (background or manual).
        # Prevents refresh(rescan=False) from triggering a full rescan on empty initial state.
        self._data_ready = False

        # Rows that were modified via overwrite in this session.
        # In "只看差异" mode, we keep these rows visible even if diffs are resolved.
        self.touched_rows: set[int] = set()

        # Snapshot mode: build the diff row list once, then keep the row list stable.
        # Overwrites only update per-row highlight (to show "已处理") and keep the row visible.
        self.snapshot_only_diff = True
        self._only_diff_source_version = 0
        self._only_diff_rows_cache: list[int] | None = None
        self._only_diff_rows_cache_key: tuple | None = None
        self._only_diff_async_build_key: tuple | None = None
        self._only_diff_async_build_seq = 0
        self._only_diff_async_building = False
        self._only_diff_async_thread: threading.Thread | None = None
        self._only_diff_async_requested_value = int(
            getattr(self.app, "only_diff_default", 0)
        )
        self._only_diff_request_origin_value = int(
            getattr(self.app, "only_diff_default", 0)
        )
        self._mutation_widgets: list[object] = []

        # Toolbar
        bar = ttk.Frame(self.frame)
        bar.pack(fill="x", padx=8, pady=(8, 6))
        self._toolbar = bar
        # Difference navigation and structural-column decisions deliberately
        # share one compact row.  The navigation group is absolutely centered
        # until it would collide with the protected right-side action groups.
        self.column_action_bar = ttk.Frame(self.frame)
        self.column_action_bar.pack(fill="x", padx=8, pady=(0, 4))
        # Reserve one fixed right-hand group before any dynamic text.  This
        # keeps row/region, view-mode and diff-navigation controls visible on
        # narrow Gunships sheets even while status text changes.
        self.toolbar_action_group = ttk.Frame(bar)
        self.toolbar_action_group.pack(side="right")
        self.diff_nav_group = ttk.Frame(self.column_action_bar)
        self._action_row_layout_after_id = None

        ttk.Label(
            bar,
            text=f"工作表 · {sheet_name}",
            font=("Segoe UI", 11, "bold"),
        ).pack(side="left", padx=(2, 10))
        self.info = None
        self.loading_progress = ttk.Progressbar(bar, mode="indeterminate", length=120)

        # Dynamic counts must never reflow the view-mode controls in the
        # toolbar above; their navigation group is placed independently.
        self.next_diff_btn = tk.Button(
            self.diff_nav_group,
            text="下一差异",
            padx=5,
            pady=2,
            command=self._goto_next_diff_block,
        )
        self.prev_diff_btn = tk.Button(
            self.diff_nav_group,
            text="上一差异",
            padx=5,
            pady=2,
            command=self._goto_prev_diff_block,
        )
        self._diff_blocks_cache = None  # None = not yet computed; [] = computed, no diffs
        self._full_diff_blocks_cache_key = None
        self._full_diff_blocks: list[_DiffBlock] = []
        self._pair_to_full_diff_block: dict[int, int] = {}
        self.diff_block_status_var = tk.StringVar(value="差异块 -/- · 待处理 -")
        self.diff_block_status = tk.Label(
            self.diff_nav_group,
            textvariable=self.diff_block_status_var,
            width=18,
            anchor="center",
            fg="#174A7E",
        )
        self.prev_diff_btn.pack(side="left")
        self.diff_block_status.pack(side="left", padx=8)
        self.next_diff_btn.pack(side="left")

        # Some environments fail to toggle BooleanVar reliably; use IntVar with explicit on/off values.
        self.only_diff_var = tk.IntVar(value=int(getattr(self.app, "only_diff_default", 0)))
        self._last_only_diff_value = int(self.only_diff_var.get())

        self.only_diff_cb = tk.Checkbutton(
            self.toolbar_action_group,
            text="仅差异",
            variable=self.only_diff_var,
            onvalue=1,
            offvalue=0,
            command=self._toggle_only_diff,
            padx=6,
            bg=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
            activebackground=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
        )
        # Put on the right for a stable position
        self.only_diff_cb.pack(side="right", padx=(6, 0))
        self.force_align_var = tk.IntVar(value=0)
        self.force_align_cb = tk.Checkbutton(
            self.toolbar_action_group,
            text="行对齐",
            variable=self.force_align_var,
            onvalue=1,
            offvalue=0,
            command=self._toggle_force_align,
            padx=6,
            bg=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
            activebackground=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
        )
        self.force_align_cb.pack(side="right", padx=(6, 0))
        self.grid_overlay_var = tk.IntVar(value=1)
        self.grid_overlay_cb = tk.Checkbutton(
            self.toolbar_action_group,
            text="网格",
            variable=self.grid_overlay_var,
            onvalue=1,
            offvalue=0,
            command=self._toggle_grid_overlay,
            padx=6,
            bg=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
            activebackground=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
        )
        self.grid_overlay_cb.pack(side="right", padx=(6, 0))
        if getattr(self.app, "merge_conflict_mode", False):
            try:
                self.only_diff_var.set(1)
                self.only_diff_cb.select()
                self.only_diff_cb.configure(state="disabled")
                self.force_align_var.set(0)
                self.force_align_cb.configure(state="disabled")
            except Exception:
                pass
        self._folded_identity = getattr(getattr(self.app, "startup_outcome", None), "folded_identity", None)
        self.three_way_var = tk.IntVar(
            value=(
                0 if self._folded_identity else 1
            ) if getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False) else 0
        )
        self._last_three_way_value = int(self.three_way_var.get())
        self.three_way_cb = None
        if getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False):
            self.three_way_cb = tk.Checkbutton(
                self.toolbar_action_group,
                text="展开三方" if self._folded_identity else "三方",
                variable=self.three_way_var,
                onvalue=1,
                offvalue=0,
                command=self._toggle_three_way_view,
                padx=6,
                bg=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
                activebackground=getattr(self.app, "workspace_chrome_color", "#E9E9E9"),
            )
            self.three_way_cb.pack(side="right", padx=(6, 0))

        # Apply initial visual state from persisted setting
        try:
            if self.only_diff_var.get():
                self.only_diff_cb.select()
            else:
                self.only_diff_cb.deselect()
        except Exception:
            pass
        self._last_only_diff_value = int(self.only_diff_var.get())

        # Debug: provide a force-toggle button to prove the filtering path works even if UI toggling fails.
        if _DEBUG_ENABLED and bool(getattr(self.app, "show_debug_controls", False)):
            tk.Button(
                self.toolbar_action_group,
                text="调试切换",
                command=lambda: (self.only_diff_var.set(0 if self.only_diff_var.get() else 1), self._toggle_only_diff()),
                padx=6,
                pady=1,
            ).pack(side="right", padx=(6, 0))

        # Debug: log click + resulting value
        def _log_cb_click(_evt=None):
            _dlog(f"CHECKBOX_CLICK sheet={self.sheet} var={self.only_diff_var.get()}")
            try:
                self.frame.after_idle(lambda: _dlog(f"CHECKBOX_AFTER_IDLE sheet={self.sheet} var={self.only_diff_var.get()}"))
            except Exception:
                pass

        try:
            self.only_diff_cb.bind("<ButtonRelease-1>", _log_cb_click)
        except Exception:
            pass
        # Context merge controls (row-level + region-level)
        # 区域 = 连续的差异行块；以当前鼠标所在行为锚点定位该块。
        # Office-like split button:
        # - Main button executes current mode action.
        # - Arrow menu switches mode only (no overwrite on switch).
        left_row_dir = "BASE2A" if (getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False)) else "A2B"
        right_row_dir = "B2A"
        self._left_copy_direction = left_row_dir
        self._right_copy_direction = right_row_dir
        self._copy_scope_mode = "row"
        self._copy_scope_var = tk.StringVar(value="row")

        def _build_split_group(parent, main_text: str, bg: str, command):
            group = tk.Frame(parent, bg=bg, bd=1, relief="solid")
            main_btn = tk.Button(
                group,
                text=main_text,
                bg=bg,
                activebackground=bg,
                padx=10,
                pady=2,
                relief="flat",
                bd=0,
                command=command,
            )
            sep = tk.Frame(group, bg="#9aa7b0", width=1)
            menu_btn = tk.Menubutton(
                group,
                text="▾",
                bg=bg,
                activebackground=bg,
                padx=6,
                pady=2,
                relief="flat",
                bd=0,
                indicatoron=False,
                direction="below",
            )
            main_btn.pack(side="left")
            sep.pack(side="left", fill="y", pady=2)
            menu_btn.pack(side="left")
            return group, main_btn, menu_btn

        left_action_text = self._format_direction_action(left_row_dir, "row")
        right_action_text = self._format_direction_action(right_row_dir, "row")
        self.use_left_group, self.use_left_btn, self.use_left_menu_btn = _build_split_group(
            self.toolbar_action_group,
            left_action_text,
            "#eaf2ff",
            command=lambda: self._run_copy_action_by_mode(self._left_copy_direction),
        )
        self._use_left_menu = tk.Menu(self.use_left_menu_btn, tearoff=0)
        self._use_left_menu.add_radiobutton(
            label="行模式",
            variable=self._copy_scope_var,
            value="row",
            command=lambda: self._set_copy_scope_mode("row"),
        )
        self._use_left_menu.add_radiobutton(
            label="区域模式",
            variable=self._copy_scope_var,
            value="region",
            command=lambda: self._set_copy_scope_mode("region"),
        )
        self._use_left_menu.add_radiobutton(
            label="全局模式",
            variable=self._copy_scope_var,
            value="global",
            command=lambda: self._set_copy_scope_mode("global"),
        )
        self.use_left_menu_btn.configure(menu=self._use_left_menu)

        self.use_right_group, self.use_right_btn, self.use_right_menu_btn = _build_split_group(
            self.toolbar_action_group,
            right_action_text,
            "#ffecec",
            command=lambda: self._run_copy_action_by_mode(self._right_copy_direction),
        )
        self._use_right_menu = tk.Menu(self.use_right_menu_btn, tearoff=0)
        self._use_right_menu.add_radiobutton(
            label="行模式",
            variable=self._copy_scope_var,
            value="row",
            command=lambda: self._set_copy_scope_mode("row"),
        )
        self._use_right_menu.add_radiobutton(
            label="区域模式",
            variable=self._copy_scope_var,
            value="region",
            command=lambda: self._set_copy_scope_mode("region"),
        )
        self._use_right_menu.add_radiobutton(
            label="全局模式",
            variable=self._copy_scope_var,
            value="global",
            command=lambda: self._set_copy_scope_mode("global"),
        )
        self.use_right_menu_btn.configure(menu=self._use_right_menu)
        self._set_copy_scope_mode("row")

        self.use_base_btn = None
        if getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False):
            self.use_base_btn = tk.Button(
                self.toolbar_action_group,
                text=self.role_presentation.action_label("MINE2A"),
                bg="#f3f3ff",
                padx=10,
                pady=2,
                command=lambda: self._copy_selected_row("MINE2A"),
            )
        self.undo_btn = tk.Button(
            self.toolbar_action_group,
            text="撤销",
            bg="#f2f2f2",
            padx=8,
            pady=2,
            command=self._undo_last_action,
        )
        # Keep at top-right (avoid misclick)
        self.use_right_group.pack(side="right", padx=(6, 0))
        if self.use_base_btn is not None:
            self.use_base_btn.pack(side="right", padx=(6, 0))
        self.use_left_group.pack(side="right")
        self.undo_btn.pack(side="right", padx=(6, 0))

        self.manual_rescan_btn = ttk.Button(self.toolbar_action_group, text="刷新", command=self._manual_rescan)
        self.manual_rescan_btn.pack(side="right", padx=(6, 0))
        self._full_render = False
        self._load_all_btn = ttk.Button(self.toolbar_action_group, text="全量", command=self._load_all_rows)
        if _FAST_OPEN_ENABLED:
            self._load_all_btn.pack(side="right", padx=(6, 0))
        # Structural-column action bar.  Buttons stay disabled until a user
        # selects a highlighted logical block from a header or minimap marker.
        self.column_action_status_var = tk.StringVar(
            value="列块：点击 + / − / ? 标记选择"
        )
        self.column_action_status_label = ttk.Label(
            self.column_action_bar,
            textvariable=self.column_action_status_var,
            foreground="#6A4A00",
            anchor="w",
        )
        self.column_action_status_label._identity_detail_text = (
            "列块：点击带 + / − / ? 标记的表头或下方橙色列标记进行选择"
        )
        self._bind_identity_label_tooltip(self.column_action_status_label)
        self.column_action_selection_var = tk.StringVar(value="")
        self.column_action_status_prefix_var = tk.StringVar(value="")
        self.column_action_status_suffix_var = tk.StringVar(value="")
        self.column_action_status_group = tk.Frame(self.column_action_bar)
        self.column_action_status_prefix_label = tk.Label(
            self.column_action_status_group,
            textvariable=self.column_action_status_prefix_var,
            foreground="#6A4A00",
            font=("Segoe UI", 9),
            anchor="w",
        )
        self.column_action_selection_label = tk.Label(
            self.column_action_status_group,
            textvariable=self.column_action_selection_var,
            foreground="#C62828",
            font=("Segoe UI", 9, "bold"),
            anchor="w",
        )
        self.column_action_status_suffix_label = tk.Label(
            self.column_action_status_group,
            textvariable=self.column_action_status_suffix_var,
            foreground="#6A4A00",
            font=("Segoe UI", 9),
            anchor="w",
        )
        for widget in (
            self.column_action_status_prefix_label,
            self.column_action_selection_label,
            self.column_action_status_suffix_label,
        ):
            widget._identity_detail_text = ""
            self._bind_identity_label_tooltip(widget)
            widget.pack(side="left")
        # General transient sheet feedback lives beside (not inside) the
        # fixed toolbar actions. Its normal render text is deliberately short.
        self.info = ttk.Label(self.column_action_bar, text="", foreground="#444", anchor="w")
        # Pack the action group first so a long status never squeezes the
        # buttons out of the GunshipsModify header.
        self.column_action_button_group = ttk.Frame(self.column_action_bar)
        self.column_action_button_group.pack(side="right")
        self.use_theirs_col_btn = tk.Button(
            self.column_action_button_group,
            text=f"应用 {self.role_presentation.right} → {self.role_presentation.left} 列",
            padx=8,
            pady=1,
            state="disabled",
            command=lambda: self._on_column_action_button("B"),
        )
        self.use_base_col_btn = tk.Button(
            self.column_action_button_group,
            text=f"应用 {self.role_presentation.middle} → {self.role_presentation.left} 列",
            padx=8,
            pady=1,
            state="disabled",
            command=lambda: self._on_column_action_button("BASE"),
        )
        self.use_mine_col_btn = tk.Button(
            self.column_action_button_group,
            text=(f"保留 {self.role_presentation.left} 列" if getattr(self.app, "merge_mode", False) else self._format_direction_action("A2B", "column")),
            padx=8,
            pady=1,
            state="disabled",
            command=lambda: self._on_column_action_button("A"),
        )
        self.use_theirs_col_btn.pack(side="right", padx=(4, 0))
        if getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False):
            self.use_base_col_btn.pack(side="right", padx=(4, 0))
        self.use_mine_col_btn.pack(side="right", padx=(4, 0))
        # The complete structural summary is a tagged group immediately left
        # of the three buttons: the logical range alone is red/bold while its
        # surrounding decision text stays neutral.
        self.column_action_status_group.pack(side="right", padx=(0, 8))
        # Transient feedback occupies only the free left portion of this row.
        # It is placed (rather than packed) so it yields to the centered diff
        # navigation before any protected structural action is clipped.
        for widget in (
            self.column_action_bar,
            self.diff_nav_group,
            self.column_action_status_group,
            self.column_action_button_group,
        ):
            widget.bind("<Configure>", self._schedule_column_action_row_layout, add="+")
        self._refresh_column_action_buttons()
        self._schedule_column_action_row_layout()

        # Each visible workbook gets an aligned identity card.  The first line
        # carries semantic role/revision/Author, while the second line exposes
        # the actual file path used by this pane.  Two-way mode therefore has
        # two 50:50 cards instead of reserving a blank third column for Base.
        path_bar = ttk.Frame(self.frame)
        path_bar.pack(fill="x", padx=8, pady=(2, 5))
        self.path_bar = path_bar
        self._path_font = ("Segoe UI", 9, "bold")
        self._path_file_font = ("Segoe UI", 8)

        if getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False):
            mine_src = getattr(self.app, "raw_mine", None) or self.app.file_a
            base_src = getattr(self.app, "raw_base", None) or getattr(self.app, "base_path", "")
            theirs_src = getattr(self.app, "raw_theirs", None) or self.app.file_b
            label_a = f"mine={self._source_display_name(mine_src)}"
            label_base = f"base={self._source_display_name(base_src)}" if base_src else "base=-"
            label_b = f"theirs={self._source_display_name(theirs_src)}"
        else:
            base_src = getattr(self.app, "raw_base", None) or self.app.file_a
            mine_src = getattr(self.app, "raw_mine", None) or self.app.file_b
            if getattr(self.app, "role_mode", "") == "source-target":
                label_a = f"Source（只读）={self._source_display_name(base_src)}"
                label_b = f"Target（可保存）={self._source_display_name(mine_src)}"
                label_base = f"Source={self._source_display_name(base_src)}"
            else:
                # Diff mode: keep wording consistent with SVN semantics (left=base, right=mine).
                label_a = f"base={self._source_display_name(base_src)}"
                label_b = f"mine={self._source_display_name(mine_src)}"
                label_base = f"base={self._source_display_name(getattr(self.app, 'base_path', '') or '')}"
        is_merge_labels = bool(getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False))
        path_bg_a = _MINE_BG if is_merge_labels else _BASE_BG
        path_bg_b = _THEIRS_BG if is_merge_labels else _MINE_BG

        def _identity_card(background: str, identity_text: str):
            card = tk.Frame(
                path_bar,
                bg=background,
                bd=0,
                highlightthickness=1,
                highlightbackground="#D7DCE3",
            )
            identity = tk.Label(
                card,
                text=identity_text,
                font=self._path_font,
                bg=background,
                fg="#20242A",
                anchor="w",
                padx=9,
                pady=2,
                width=1,
            )
            identity.pack(fill="x")
            file_path = tk.Label(
                card,
                text="文件路径：-",
                font=self._path_file_font,
                bg=background,
                fg="#4F5965",
                anchor="w",
                padx=9,
                pady=2,
                width=1,
                cursor="hand2",
            )
            file_path.pack(fill="x")
            return card, identity, file_path

        self.path_card_a, self.path_label_a, self.path_file_label_a = _identity_card(path_bg_a, label_a)
        self.path_card_base, self.path_label_base, self.path_file_label_base = _identity_card(
            _BASE_BG,
            label_base if label_base else "基础(base): -",
        )
        self.path_card_b, self.path_label_b, self.path_file_label_b = _identity_card(path_bg_b, label_b)
        self._visible_pane_paths = {"a": "", "base": "", "b": ""}
        for side, identity_label, file_label in (
            ("a", self.path_label_a, self.path_file_label_a),
            ("base", self.path_label_base, self.path_file_label_base),
            ("b", self.path_label_b, self.path_file_label_b),
        ):
            identity_label._identity_detail_text = ""
            file_label._identity_detail_text = ""
            self._bind_identity_label_tooltip(identity_label)
            self._bind_identity_label_tooltip(file_label)
            file_label.bind(
                "<Button-1>",
                lambda _event, pane_side=side: self._copy_visible_pane_path(pane_side),
                add="+",
            )

        # Extra vertical scrollbar (left side) for convenience; controls both panes.
        # NOTE: must be packed BEFORE the paned window so it remains visible.
        self.vsb_left = ttk.Scrollbar(self.frame, orient="vertical", command=self._yview_both)
        self.vsb_left.pack(side="left", fill="y")
        # Diff minimap next to the left vertical scrollbar (more discoverable).
        self.vdiff_map = tk.Canvas(self.frame, width=10, highlightthickness=0, bg="#ebebeb")
        self.vdiff_map.pack(side="left", fill="y", padx=(0, 2))
        self.vdiff_map.bind("<Button-1>", self._on_vdiff_map_click)

        # Reserve the lower compare area before the main panes so C区 and hover
        # panel do not get squeezed to 1px on first layout.
        self.lower_area = ttk.Frame(self.frame)
        self.lower_area.pack(side="bottom", fill="x")
        self.lower_area.pack_propagate(False)
        self._main_vertical_grip = ttk.Separator(self.frame, orient="horizontal")
        self._main_vertical_grip.pack(
            side="bottom", fill="x", padx=8, before=self.lower_area
        )
        self._main_vertical_grip.configure(cursor="sb_v_double_arrow")
        self._main_vertical_grip.bind(
            "<Button-1>", self._on_main_vertical_grip_press
        )
        self._main_vertical_grip.bind(
            "<B1-Motion>", self._on_main_vertical_grip_motion
        )

        # Panes
        paned = ttk.PanedWindow(self.frame, orient="horizontal")
        paned.pack(fill="both", expand=True, padx=8, pady=(0, 2))
        self._main_paned = paned

        left_wrap = ttk.Frame(paned)
        mid_wrap = ttk.Frame(paned)
        right_wrap = ttk.Frame(paned)
        self._left_wrap = left_wrap
        self._mid_wrap = mid_wrap
        self._right_wrap = right_wrap
        paned.add(mid_wrap, weight=1)
        paned.add(left_wrap, weight=1)
        paned.add(right_wrap, weight=1)

        self._pane_layout_initialized = False
        self._pane_layout_initialized_key = None
        self._pane_settings_key = hashlib.sha1(
            "|".join(str(value or "") for value in (
                getattr(self.app, "raw_base", None) or getattr(self.app, "file_a", ""),
                getattr(self.app, "raw_mine", None) or getattr(self.app, "file_a", ""),
                getattr(self.app, "raw_theirs", None) or getattr(self.app, "file_b", ""),
            )).encode("utf-8", "ignore")
        ).hexdigest()[:16]
        vertical_saved = (
            getattr(self.app, "settings", {}).get("vertical_sashes", {})
            if isinstance(getattr(self.app, "settings", {}), dict)
            else {}
        )
        from .vertical_layout import VerticalLayout

        self._vertical_layout = VerticalLayout.from_mapping(
            vertical_saved.get(self._pane_settings_key)
            if isinstance(vertical_saved, dict)
            else None,
            three_way=self._is_three_way_enabled(),
        )
        self.frame.bind(
            "<Configure>", self._on_vertical_frame_configure, add="+"
        )
        def _keep_panes_equal(_evt=None):
            """Restore the user's pane proportions once, then remember drags."""
            try:
                total = self._main_paned.winfo_width()
                if not total or total <= 2:
                    return
                layout_key = f"{self._pane_settings_key}:{'three' if self._is_three_way_expanded() else 'two'}"
                if self._pane_layout_initialized_key != layout_key:
                    all_saved = getattr(self.app, "settings", {}).get("pane_sashes", {})
                    saved = all_saved.get(self._pane_settings_key, {}) if isinstance(all_saved, dict) else {}
                    key = "three" if self._is_three_way_expanded() else "two"
                    values = saved.get(key, ()) if isinstance(saved, dict) else ()
                    if len(values) >= (2 if self._is_three_way_expanded() else 1):
                        for idx, value in enumerate(values):
                            self._main_paned.sashpos(idx, int(value))
                    elif self._is_three_way_expanded():
                        self._main_paned.sashpos(0, total // 3)
                        self._main_paned.sashpos(1, (total * 2) // 3)
                    else:
                        self._main_paned.sashpos(0, total // 2)
                    self._pane_layout_initialized = True
                    self._pane_layout_initialized_key = layout_key
                    # Persist the initial/default positions as well as user
                    # drags so the first session establishes a stable mode
                    # key and subsequent sessions can restore it immediately.
                    current = [
                        self._main_paned.sashpos(i)
                        for i in range(2 if key == "three" else 1)
                    ]
                    settings = getattr(self.app, "settings", {})
                    settings.setdefault("pane_sashes", {}).setdefault(
                        self._pane_settings_key, {}
                    )[key] = current
                else:
                    key = "three" if self._is_three_way_expanded() else "two"
                    current = [self._main_paned.sashpos(i) for i in range(2 if key == "three" else 1)]
                    settings = getattr(self.app, "settings", {})
                    settings.setdefault("pane_sashes", {}).setdefault(self._pane_settings_key, {})[key] = current
            except Exception:
                pass

        self._keep_panes_equal = _keep_panes_equal
        self._main_paned.bind("<ButtonRelease-1>", self._keep_panes_equal)
        self.frame.after(0, self._keep_panes_equal)

        pane_title_font = ("Segoe UI", 9, "bold")
        self.left_title = tk.Label(
            left_wrap,
            text=self.role_presentation.left,
            bg=_MINE_BG,
            fg="#20242A",
            font=pane_title_font,
            anchor="w",
            padx=9,
            pady=4,
        )
        self.left_title.pack(fill="x")
        self.mid_title = tk.Label(
            mid_wrap,
            text=self.role_presentation.middle,
            bg=_BASE_BG,
            fg="#20242A",
            font=pane_title_font,
            anchor="w",
            padx=9,
            pady=4,
        )
        self.mid_title.pack(fill="x")
        self.right_title = tk.Label(
            right_wrap,
            text=self.role_presentation.right,
            bg=_THEIRS_BG,
            fg="#20242A",
            font=pane_title_font,
            anchor="w",
            padx=9,
            pady=4,
        )
        self.right_title.pack(fill="x")

        # Font size tuned closer to TortoiseMerge (+~20%)
        # 新宋体 has an actual 1:2 ASCII/CJK advance at 11pt on supported
        # Windows installs, matching the fixed display-cell formatter.
        self.editor_font = ("新宋体", 11, "normal")
        left_body = ttk.Frame(left_wrap)
        left_body.pack(fill="both", expand=True)
        mid_body = ttk.Frame(mid_wrap)
        mid_body.pack(fill="both", expand=True)
        right_body = ttk.Frame(right_wrap)
        right_body.pack(fill="both", expand=True)
        left_footer = ttk.Frame(left_wrap)
        left_footer.pack(side="bottom", fill="x", before=left_body)
        mid_footer = ttk.Frame(mid_wrap)
        mid_footer.pack(side="bottom", fill="x", before=mid_body)
        right_footer = ttk.Frame(right_wrap)
        right_footer.pack(side="bottom", fill="x", before=right_body)

        self.left_ln = tk.Text(left_body, width=self._row_header_width, wrap="none", undo=False, font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.base_ln = tk.Text(mid_body, width=self._row_header_width, wrap="none", undo=False, font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.right_ln = tk.Text(right_body, width=self._row_header_width, wrap="none", undo=False, font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.left = tk.Text(left_body, wrap="none", undo=False, font=self.editor_font, bg="white")
        self.base = tk.Text(mid_body, wrap="none", undo=False, font=self.editor_font, bg="white")
        self.right = tk.Text(right_body, wrap="none", undo=False, font=self.editor_font, bg="white")

        # Scrollbars
        # Per-pane vertical scrollbars (user requested visible scrollbars on both A and B)
        self.vsb_a = ttk.Scrollbar(left_body, orient="vertical", command=self._yview_both)
        self.vsb_m = ttk.Scrollbar(mid_body, orient="vertical", command=self._yview_both)
        self.vsb_b = ttk.Scrollbar(right_body, orient="vertical", command=self._yview_both)
        self.vsb_a.pack(side="right", fill="y")
        self.vsb_m.pack(side="right", fill="y")
        self.vsb_b.pack(side="right", fill="y")

        # Shared vertical scrollbar on far right removed (redundant / low usability).
        self.vsb = None

        # Horizontal scroll sync: keep A/B panes aligned when scrolling horizontally.
        self._xsyncing = False
        # Suppress C-pane -> main-pane x-sync during programmatic C text refresh.
        self._suppress_c_xsync = False

        def _sync_main_headers(first):
            try:
                frac = float(first)
            except Exception:
                return
            try:
                if getattr(self, "left_colhdr", None) is not None:
                    self.left_colhdr.xview_moveto(frac)
                if getattr(self, "right_colhdr", None) is not None:
                    self.right_colhdr.xview_moveto(frac)
                if self._is_three_way_enabled() and getattr(self, "base_colhdr", None) is not None:
                    self.base_colhdr.xview_moveto(frac)
            except Exception:
                pass

        def _xscroll_left(first, last):
            # called when left xview changes
            if self._is_click_trace_active():
                _dlog(f"xscroll_left first={first} last={last} xsyncing={self._xsyncing}")
            if self._xsyncing:
                self.hsb_left.set(first, last)
                return
            self._xsyncing = True
            try:
                self.hsb_left.set(first, last)
                self._sync_main_x_from_widget(self.left, first)
                self._sync_c_x_from_widget(self.left, first)
            finally:
                self._xsyncing = False
            try:
                self._schedule_diff_maps()
            except Exception:
                pass

        def _xscroll_right(first, last):
            if self._is_click_trace_active():
                _dlog(f"xscroll_right first={first} last={last} xsyncing={self._xsyncing}")
            if self._xsyncing:
                self.hsb_right.set(first, last)
                return
            self._xsyncing = True
            try:
                self.hsb_right.set(first, last)
                self._sync_main_x_from_widget(self.right, first)
                self._sync_c_x_from_widget(self.right, first)
            finally:
                self._xsyncing = False
            try:
                self._schedule_diff_maps()
            except Exception:
                pass

        def _xscroll_mid(first, last):
            if self._is_click_trace_active():
                _dlog(f"xscroll_mid first={first} last={last} xsyncing={self._xsyncing}")
            if self._xsyncing:
                self.hsb_mid.set(first, last)
                return
            self._xsyncing = True
            try:
                self.hsb_mid.set(first, last)
                self._sync_main_x_from_widget(self.base, first)
                self._sync_c_x_from_widget(self.base, first)
            finally:
                self._xsyncing = False
            try:
                self._schedule_diff_maps()
            except Exception:
                pass

        def _xview_left(*args):
            # scrollbar drag/click on left
            self._xsyncing = True
            try:
                self.left.xview(*args)
                first, last = self.left.xview()
                self.hsb_left.set(first, last)
                self._sync_main_x_from_widget(self.left, first)
                self._sync_c_x_from_widget(self.left, first)
            finally:
                self._xsyncing = False
            try:
                self._schedule_diff_maps()
            except Exception:
                pass

        def _xview_right(*args):
            self._xsyncing = True
            try:
                self.right.xview(*args)
                first, last = self.right.xview()
                self.hsb_right.set(first, last)
                self._sync_main_x_from_widget(self.right, first)
                self._sync_c_x_from_widget(self.right, first)
            finally:
                self._xsyncing = False
            try:
                self._schedule_diff_maps()
            except Exception:
                pass

        def _xview_mid(*args):
            self._xsyncing = True
            try:
                self.base.xview(*args)
                first, last = self.base.xview()
                self.hsb_mid.set(first, last)
                self._sync_main_x_from_widget(self.base, first)
                self._sync_c_x_from_widget(self.base, first)
            finally:
                self._xsyncing = False
            try:
                self._schedule_diff_maps()
            except Exception:
                pass

        self.hsb_left = ttk.Scrollbar(left_footer, orient="horizontal", command=_xview_left)
        self.hsb_mid = ttk.Scrollbar(mid_footer, orient="horizontal", command=_xview_mid)
        self.hsb_right = ttk.Scrollbar(right_footer, orient="horizontal", command=_xview_right)
        self.hdiff_left = tk.Canvas(left_footer, height=10, highlightthickness=0, bg="#ebebeb")
        self.hdiff_mid = tk.Canvas(mid_footer, height=10, highlightthickness=0, bg="#ebebeb")
        self.hdiff_right = tk.Canvas(right_footer, height=10, highlightthickness=0, bg="#ebebeb")
        self.hdiff_left.bind("<Button-1>", lambda e: self._on_hdiff_map_click(e, "left"))
        self.hdiff_mid.bind("<Button-1>", lambda e: self._on_hdiff_map_click(e, "mid"))
        self.hdiff_right.bind("<Button-1>", lambda e: self._on_hdiff_map_click(e, "right"))
        self.left.configure(xscrollcommand=_xscroll_left)
        self.base.configure(xscrollcommand=_xscroll_mid)
        self.right.configure(xscrollcommand=_xscroll_right)

        self.left.configure(yscrollcommand=self._yscroll_left)
        self.base.configure(yscrollcommand=self._yscroll_mid)
        self.right.configure(yscrollcommand=self._yscroll_right)
        self.vsb_left.configure(command=self._yview_both)
        self.vsb_a.configure(command=self._yview_both)
        self.vsb_m.configure(command=self._yview_both)
        self.vsb_b.configure(command=self._yview_both)

        # Excel-like column header row for A/Base/B panes.
        left_head = ttk.Frame(left_wrap)
        left_head.pack(fill="x", before=left_body)
        mid_head = ttk.Frame(mid_wrap)
        mid_head.pack(fill="x", before=mid_body)
        right_head = ttk.Frame(right_wrap)
        right_head.pack(fill="x", before=right_body)

        self.left_corner_hdr = tk.Text(left_head, width=self._row_header_width, height=1, wrap="none", undo=False,
                                       font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.base_corner_hdr = tk.Text(mid_head, width=self._row_header_width, height=1, wrap="none", undo=False,
                                       font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.right_corner_hdr = tk.Text(right_head, width=self._row_header_width, height=1, wrap="none", undo=False,
                                        font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.left_colhdr = tk.Text(left_head, height=1, wrap="none", undo=False,
                                   font=self.editor_font, bg="#efefef", fg="#555555", relief="flat", takefocus=0, cursor="arrow")
        self.base_colhdr = tk.Text(mid_head, height=1, wrap="none", undo=False,
                                   font=self.editor_font, bg="#efefef", fg="#555555", relief="flat", takefocus=0, cursor="arrow")
        self.right_colhdr = tk.Text(right_head, height=1, wrap="none", undo=False,
                                    font=self.editor_font, bg="#efefef", fg="#555555", relief="flat", takefocus=0, cursor="arrow")

        self.left_corner_hdr.pack(side="left", fill="y")
        ttk.Separator(left_head, orient="vertical").pack(side="left", fill="y")
        self._vsb_hdr_spc_a = tk.Frame(left_head, width=1, bg="#efefef")
        self._vsb_hdr_spc_a.pack(side="right", fill="y")
        self.left_colhdr.pack(side="left", fill="x", expand=True)
        self.base_corner_hdr.pack(side="left", fill="y")
        ttk.Separator(mid_head, orient="vertical").pack(side="left", fill="y")
        self._vsb_hdr_spc_m = tk.Frame(mid_head, width=1, bg="#efefef")
        self._vsb_hdr_spc_m.pack(side="right", fill="y")
        self.base_colhdr.pack(side="left", fill="x", expand=True)
        self.right_corner_hdr.pack(side="left", fill="y")
        ttk.Separator(right_head, orient="vertical").pack(side="left", fill="y")
        self._vsb_hdr_spc_b = tk.Frame(right_head, width=1, bg="#efefef")
        self._vsb_hdr_spc_b.pack(side="right", fill="y")
        self.right_colhdr.pack(side="left", fill="x", expand=True)
        for w in (self.left_corner_hdr, self.base_corner_hdr, self.right_corner_hdr,
                  self.left_colhdr, self.base_colhdr, self.right_colhdr):
            try:
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", "")
                w.configure(state="disabled")
            except Exception:
                pass
        # Keep colhdr spacers in sync with the actual scrollbar width so that column
        # headers align precisely with the data widgets at all times.
        def _sync_vsb_hdr_spacers(event=None):
            try:
                w = self.vsb_a.winfo_width()
                if w > 1:
                    self._vsb_hdr_spc_a.configure(width=w)
                    self._vsb_hdr_spc_b.configure(width=w)
                    self._vsb_hdr_spc_m.configure(width=w)
            except Exception:
                pass
        self.vsb_a.bind("<Configure>", _sync_vsb_hdr_spacers, "+")

        self.left_ln.pack(side="left", fill="y")
        ttk.Separator(left_body, orient="vertical").pack(side="left", fill="y")
        self.left.pack(fill="both", expand=True)
        self.hsb_left.pack(fill="x")
        self.hdiff_left.pack(fill="x")
        self.base_ln.pack(side="left", fill="y")
        ttk.Separator(mid_body, orient="vertical").pack(side="left", fill="y")
        self.base.pack(fill="both", expand=True)
        self.hsb_mid.pack(fill="x")
        self.hdiff_mid.pack(fill="x")

        # Save action row: keep a fixed height on both sides so horizontal
        # scrollbars stay aligned even when only one side has a button.
        # Also keep middle pane height identical to left/right to avoid row misalignment.
        save_row_height = 34

        # Save A button (bottom-right of A pane)
        save_a_row = ttk.Frame(left_footer, height=save_row_height)
        save_a_row.pack(fill="x", pady=(2, 0))
        save_a_row.pack_propagate(False)
        if getattr(self.app, "merge_mode", False):
            self.save_a_btn = tk.Button(
                save_a_row, text="保存Merged并退出", bg="#eaf2ff", padx=14, pady=4,
                command=self.app.save_merged_and_exit
            )
            self.save_a_btn.pack(side="right")
        else:
            if not getattr(self.app, "diff_base_mine_mode", False):
                if not _is_temp_base_path(getattr(self.app, "file_a", "")):
                    self.save_a_btn = tk.Button(
                        save_a_row, text="保存A", bg="#eaf2ff", padx=14, pady=4,
                        command=self.app.save_a_inplace
                    )
                    self.save_a_btn.pack(side="right")

        # Base pane spacer: maintain same bottom reserved height as A/B panes.
        save_mid_row = ttk.Frame(mid_footer, height=save_row_height)
        save_mid_row.pack(fill="x", pady=(2, 0))
        save_mid_row.pack_propagate(False)

        self.right_ln.pack(side="left", fill="y")
        ttk.Separator(right_body, orient="vertical").pack(side="left", fill="y")
        self.right.pack(fill="both", expand=True)
        self.hsb_right.pack(fill="x")
        self.hdiff_right.pack(fill="x")

        # Save B button (bottom-right of B pane)
        save_b_row = ttk.Frame(right_footer, height=save_row_height)
        save_b_row.pack(fill="x", pady=(2, 0))
        save_b_row.pack_propagate(False)
        if not getattr(self.app, "merge_mode", False):
            save_b_text = "保存修改后文件" if getattr(self.app, "diff_base_mine_mode", False) else "保存B"
            self.save_b_btn = tk.Button(
                save_b_row, text=save_b_text, bg="#ffecec", padx=14, pady=4,
                command=self.app.save_b_inplace
            )
            self.save_b_btn.pack(side="right")

        # Tags (order matters: diffcell should be applied after diffrow)
        # Closer to TortoiseMerge vibe: left diff block = orange, right diff block = yellow
        self.left.tag_configure("diffrow", background=_MINE_BG)
        self.base.tag_configure("diffrow", background=_BASE_BG)
        self.right.tag_configure("diffrow", background=_THEIRS_BG)

        # Cell-level highlight (red) for exact diffs
        self.left.tag_configure("diffcell", background=_DIFF_CELL_BG)
        self.base.tag_configure("diffcell", background=_DIFF_CELL_BG)
        self.right.tag_configure("diffcell", background=_DIFF_CELL_BG)
        self.left.tag_raise("diffcell")
        self.base.tag_raise("diffcell")
        self.right.tag_raise("diffcell")
        # Alignment padding: grey slot for rows that exist only on the other side.
        # tag_raise ensures paddingrow background overrides diffrow on the empty slot.
        self.left.tag_configure("paddingrow", background="#A0A0A0")
        self.base.tag_configure("paddingrow", background="#A0A0A0")
        self.right.tag_configure("paddingrow", background="#A0A0A0")
        self.left.tag_raise("paddingrow")
        self.base.tag_raise("paddingrow")
        self.right.tag_raise("paddingrow")
        # paddingcol: grey span for columns that exist only on the other side (新增列).
        self.left.tag_configure("paddingcol", background="#A0A0A0")
        self.base.tag_configure("paddingcol", background="#A0A0A0")
        self.right.tag_configure("paddingcol", background="#A0A0A0")
        self.left.tag_raise("paddingcol")
        self.base.tag_raise("paddingcol")
        self.right.tag_raise("paddingcol")

        # selection should not overwrite diff colors
        # Selection must not override the pane font: a font change would make
        # wide-cell pixel geometry diverge from headers and other panes.
        self.left.tag_configure("selrow", underline=1)
        self.base.tag_configure("selrow", underline=1)
        self.right.tag_configure("selrow", underline=1)
        # Selected-cell highlight (same blue as C区 cselcell), applied on A/B/(Base).
        self.left.tag_configure("selcell", background="#8EB9FF")
        self.base.tag_configure("selcell", background="#8EB9FF")
        self.right.tag_configure("selcell", background="#8EB9FF")
        self.left.tag_raise("selcell")
        self.base.tag_raise("selcell")
        self.right.tag_raise("selcell")
        self.left_ln.tag_configure("diffrow", background="#ffd9d9")
        self.base_ln.tag_configure("diffrow", background="#ffd9d9")
        self.right_ln.tag_configure("diffrow", background="#ffd9d9")
        for w in (self.left, self.base, self.right, self.left_ln, self.base_ln, self.right_ln):
            w.tag_configure("blockstart", spacing1=8)
        self.left_ln.tag_configure(
            "blockmarker",
            background="#D8E8F8",
            foreground="#174A7E",
            font=("Consolas", 10, "bold"),
        )
        self.left_ln.tag_raise("blockmarker")

        # Bindings
        self._syncing = False
        for w in (self.left, self.base, self.right):
            w.bind("<MouseWheel>", self._on_mousewheel)
            w.bind("<Button-4>", self._on_mousewheel)
            w.bind("<Button-5>", self._on_mousewheel)
            w.bind("<KeyRelease>", lambda e: self._update_cursor_lines())
            w.bind("<ButtonRelease-1>", lambda e: self._update_cursor_lines())
            # F4 remains reserved for hover-panel pin/unpin. Block navigation
            # applies to normal 2-way/3-way views as well as conflict-only mode.
            w.bind("<F4>", self._on_hover_compare_f4_toggle)
            w.bind("<Shift-F4>", self._on_prev_diff_block_shortcut)
            w.bind("<Control-n>", self._on_next_diff_block_shortcut)
            w.bind("<Control-p>", self._on_prev_diff_block_shortcut)

        # Click handling (selection + arrow action)
        left_click_dir = "MINE2A" if (
            getattr(self.app, "merge_mode", False)
            and getattr(self.app, "has_base", False)
            and getattr(self.app, "merge_conflict_mode", False)
        ) else "A2B"
        self.left.bind("<Button-1>", lambda e, d=left_click_dir: self._on_click_with_arrow(self.left, e, d))
        self.base.bind("<Button-1>", lambda e: self._on_click_with_arrow(self.base, e, "BASE2A"))
        self.right.bind("<Button-1>", lambda e: self._on_click_with_arrow(self.right, e, "B2A"))
        self.left.bind("<Button-3>", lambda e: self._on_main_pane_right_click(self.left, e, "A"))
        self.base.bind("<Button-3>", lambda e: self._on_main_pane_right_click(self.base, e, "BASE"))
        self.right.bind("<Button-3>", lambda e: self._on_main_pane_right_click(self.right, e, "B"))
        self.left.bind("<Motion>", lambda e: self._on_cell_hover_tooltip(self.left, e, "A"))
        self.base.bind("<Motion>", lambda e: self._on_cell_hover_tooltip(self.base, e, "BASE"))
        self.right.bind("<Motion>", lambda e: self._on_cell_hover_tooltip(self.right, e, "B"))
        self.left.bind("<Leave>", lambda e: self._on_hover_compare_leave())
        self.base.bind("<Leave>", lambda e: self._on_hover_compare_leave())
        self.right.bind("<Leave>", lambda e: self._on_hover_compare_leave())
        # Double-click is navigation/details only.  All writes require the
        # explicit direction-labelled command buttons or row/column actions.
        self.left.bind("<Double-Button-1>", lambda e: self._on_double_click_navigate(self.left, e, "A"))
        self.base.bind("<Double-Button-1>", lambda e: self._on_double_click_navigate(self.base, e, "BASE"))
        self.right.bind("<Double-Button-1>", lambda e: self._on_double_click_navigate(self.right, e, "B"))
        self.left_colhdr.bind("<Button-1>", lambda e: self._on_column_header_click(self.left_colhdr, e, "A"))
        self.base_colhdr.bind("<Button-1>", lambda e: self._on_column_header_click(self.base_colhdr, e, "BASE"))
        self.right_colhdr.bind("<Button-1>", lambda e: self._on_column_header_click(self.right_colhdr, e, "B"))
        self.left_ln.bind("<Button-1>", lambda e, d=left_click_dir: self._on_row_header_click(self.left_ln, e, d))
        self.base_ln.bind("<Button-1>", lambda e: self._on_row_header_click(self.base_ln, e, "BASE2A"))
        self.right_ln.bind("<Button-1>", lambda e: self._on_row_header_click(self.right_ln, e, "B2A"))
        # Keep old habit compatibility: right-click on row header also triggers row apply.
        self.left_ln.bind("<Button-3>", lambda e, d=left_click_dir: self._on_row_header_click(self.left_ln, e, d))
        self.base_ln.bind("<Button-3>", lambda e: self._on_row_header_click(self.base_ln, e, "BASE2A"))
        self.right_ln.bind("<Button-3>", lambda e: self._on_row_header_click(self.right_ln, e, "B2A"))
        self.left_ln.bind("<Motion>", lambda e, d=left_click_dir: self._on_row_header_hover(self.left_ln, e, d))
        self.base_ln.bind("<Motion>", lambda e: self._on_row_header_hover(self.base_ln, e, "BASE2A"))
        self.right_ln.bind("<Motion>", lambda e: self._on_row_header_hover(self.right_ln, e, "B2A"))
        self.left_ln.bind("<Leave>", lambda e: self._clear_row_header_hover(self.left_ln))
        self.base_ln.bind("<Leave>", lambda e: self._clear_row_header_hover(self.base_ln))
        self.right_ln.bind("<Leave>", lambda e: self._clear_row_header_hover(self.right_ln))

        # C区: compact cursor compare block + cell-aligned view
        self.c_area = ttk.Notebook(self.lower_area, style="CompactPanel.TNotebook")
        self.c_area.pack(fill="x", padx=8, pady=(0, 2))
        self.c_area.pack_propagate(False)

        # ---- C1: compact row compare (2 lines in 2-way, 3 lines in 3-way) ----
        c_text_frame = ttk.Frame(self.c_area)
        self.c_area.add(c_text_frame, text="C区-行对比")

        # C区 column header + row-header layout (Excel-like)
        c_head = ttk.Frame(c_text_frame)
        c_head.pack(side="top", fill="x")
        self.cursor_cmp_corner = tk.Text(c_head, width=self._row_header_width, height=1, wrap="none", undo=False,
                                         font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.cursor_cmp_colhdr = tk.Text(c_head, height=1, wrap="none", undo=False,
                                         font=self.editor_font, bg="#efefef", fg="#555555", relief="flat", takefocus=0, cursor="arrow")
        self.cursor_cmp_corner.pack(side="left", fill="y")
        ttk.Separator(c_head, orient="vertical").pack(side="left", fill="y")
        self.cursor_cmp_colhdr.pack(side="left", fill="x", expand=True)

        c_body = ttk.Frame(c_text_frame)
        c_body.pack(side="top", fill="x")
        self.cursor_cmp_ln = tk.Text(c_body, width=self._row_header_width, height=3 if self._is_three_way_enabled() else 2, wrap="none", undo=False,
                                     font=self.editor_font, bg="#efefef", fg="#666666", relief="flat", takefocus=0, cursor="arrow")
        self.cursor_cmp_ln.pack(side="left", fill="y")
        ttk.Separator(c_body, orient="vertical").pack(side="left", fill="y")

        self.cursor_cmp = tk.Text(
            c_body,
            height=3 if self._is_three_way_enabled() else 2,
            wrap="none",
            font=self.editor_font,
            bd=1,
            relief="solid",
        )
        # Make base colors stronger (user feedback: previous too light)
        self.cursor_cmp.tag_configure("a", background=_MINE_BG)
        self.cursor_cmp.tag_configure("base", background=_BASE_BG)
        self.cursor_cmp.tag_configure("b", background=_THEIRS_BG)
        self.cursor_cmp.tag_configure("missing", background="#a6a6a6")
        # Diff cell highlight (match main panes)
        self.cursor_cmp.tag_configure("diffcell", background=_DIFF_CELL_BG)
        # Explicit C-area click target highlight
        self.cursor_cmp.tag_configure("cselcell", background="#8EB9FF")
        self.cursor_cmp.pack(side="left", fill="x", expand=True)

        for w in (self.cursor_cmp_corner, self.cursor_cmp_colhdr, self.cursor_cmp_ln):
            try:
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", "")
                w.configure(state="disabled")
            except Exception:
                pass

        # Horizontal scrollbar for C区行对比（sync with main panes）
        self.cursor_hsb = ttk.Scrollbar(c_text_frame, orient="horizontal", command=self._xview_cursor_cmp)
        self.cursor_cmp.configure(xscrollcommand=self._xscroll_cursor_cmp)
        self.cursor_hsb.pack(side="top", fill="x")
        self.cursor_cmp.bind("<Button-1>", self._on_cursor_cmp_click)
        self.cursor_cmp.bind("<Double-Button-1>", self._on_cursor_cmp_double_click)
        self.cursor_cmp.bind("<Button-3>", self._on_cursor_cmp_right_click)
        self.cursor_cmp.bind("<Motion>", self._on_cursor_cmp_hover_tooltip)
        self.cursor_cmp.bind("<Leave>", lambda e: self._on_hover_compare_leave())
        self.cursor_cmp_colhdr.bind(
            "<Button-1>",
            lambda e: self._on_column_header_click(self.cursor_cmp_colhdr, e, "LOGICAL"),
        )

        # ---- C2: cell-aligned view (optional; can be hidden if not useful/performance) ----
        self._enable_c_cell = False  # user feedback: not useful; keep hidden by default
        c_cell_frame = ttk.Frame(self.c_area)
        self.c_area.add(c_cell_frame, text="C区-单元格对齐")
        if not self._enable_c_cell:
            try:
                # A merely "hidden" Notebook page still contributes its
                # six-line requested height on Tk/Windows, leaving a large
                # blank strip under C1. Detach it while retaining the widgets.
                self.c_area.forget(c_cell_frame)
            except Exception:
                pass

        top_row = ttk.Frame(c_cell_frame)
        top_row.pack(fill="x", pady=(2, 2))
        self.c_only_diff_cells = tk.IntVar(value=1)
        tk.Checkbutton(
            top_row,
            text="只显示差异单元格",
            variable=self.c_only_diff_cells,
            onvalue=1,
            offvalue=0,
            command=lambda: self._update_cursor_lines(),
        ).pack(side="left")

        self.cell_cmp_text = tk.Text(c_cell_frame, height=6, wrap="none", font=self.editor_font, bd=1, relief="solid")
        self.cell_cmp_text.tag_configure("a", background=_MINE_BG)
        self.cell_cmp_text.tag_configure("b", background=_THEIRS_BG)
        self.cell_cmp_text.tag_configure("diffcell", background=_DIFF_CELL_BG)

        self.cell_cmp_hsb = ttk.Scrollbar(c_cell_frame, orient="horizontal", command=self._xview_cell_cmp)
        self.cell_cmp_text.configure(xscrollcommand=self._xscroll_cell_cmp)

        self.cell_cmp_text.pack(side="top", fill="x", expand=True)
        self.cell_cmp_hsb.pack(side="top", fill="x")

        # Stable hover compare panel (primary path; independent from popup windows).
        self._enable_hover_popup = False
        self._hover_clear_after_id = None
        self._last_hover_compare_key = None
        self._hover_payload_cache = {}
        # Hover throttle: dedup identical targets and debounce heavy panel refresh.
        self._last_hover_target_key = None
        self._hover_debounce_id = None
        self._pending_hover_args = None
        self._hover_debounce_ms = 30
        self.hover_cmp_host = ttk.Frame(self.lower_area, height=self._hover_compare_reserved_height())
        self.hover_cmp_host.pack(fill="x", padx=8, pady=(0, 2))
        try:
            self.hover_cmp_host.pack_propagate(False)
        except Exception:
            pass
        self._hover_vertical_grip = ttk.Separator(self.lower_area, orient="horizontal")
        self._hover_vertical_grip.pack(
            side="bottom", fill="x", padx=8, before=self.hover_cmp_host
        )
        self._hover_vertical_grip.configure(cursor="sb_v_double_arrow")
        self._hover_vertical_grip.bind(
            "<Button-1>", self._on_hover_vertical_grip_press
        )
        self._hover_vertical_grip.bind(
            "<B1-Motion>", self._on_hover_vertical_grip_motion
        )
        # One heading line carries both the panel purpose and the current
        # Sheet/cell identity. A second LabelFrame title only consumed height.
        hover_cmp_frame = ttk.Frame(self.hover_cmp_host)
        hover_cmp_frame.pack(fill="both", expand=True)
        self.hover_cmp_title_var = tk.StringVar(value="悬停完整对比 | 当前单元格：-")
        self.hover_cmp_pin_var = tk.IntVar(value=0)
        hover_hdr = ttk.Frame(hover_cmp_frame)
        hover_hdr.pack(fill="x", padx=4, pady=(2, 2))
        ttk.Label(hover_hdr, textvariable=self.hover_cmp_title_var).pack(side="left", anchor="w")
        ttk.Button(hover_hdr, text="清空", command=self._on_hover_compare_clear_click).pack(side="right", padx=(6, 0))
        ttk.Checkbutton(
            hover_hdr,
            text="固定(F4)",
            variable=self.hover_cmp_pin_var,
            onvalue=1,
            offvalue=0,
            command=self._on_hover_compare_pin_toggle,
        ).pack(side="right")
        self.hover_cmp_text = tk.Text(
            hover_cmp_frame,
            # The host also contains the heading and horizontal scrollbar;
            # three source rows therefore need a fourth Text display line to
            # avoid clipping the bottom half of Theirs in 3-way mode.
            height=4 if self._is_three_way_enabled() else 2,
            wrap="none",
            font=self.editor_font,
            bd=1,
            relief="solid",
        )
        # Source row backgrounds align with main panes.
        self.hover_cmp_text.tag_configure("hover_side_base", background=_BASE_BG)
        self.hover_cmp_text.tag_configure("hover_side_mine", background=_MINE_BG)
        self.hover_cmp_text.tag_configure("hover_side_theirs", background=_THEIRS_BG)
        # Missing row (新增行对侧无数据): muted gray, no red highlights.
        self.hover_cmp_text.tag_configure("hover_side_missing", background="#C8C8C8", foreground="#666666")
        # Char-level diff highlight inside each source line.
        self.hover_cmp_text.tag_configure("hover_diffchar", background=_DIFF_CELL_BG, foreground="#ffffff")
        self.hover_cmp_hsb = ttk.Scrollbar(hover_cmp_frame, orient="horizontal", command=self.hover_cmp_text.xview)
        self.hover_cmp_text.configure(xscrollcommand=self.hover_cmp_hsb.set)
        self.hover_cmp_hsb.pack(side="bottom", fill="x")
        self.hover_cmp_text.pack(side="top", fill="both", expand=True)
        self.hover_cmp_text.bind("<Shift-MouseWheel>", self._on_hover_cmp_shift_wheel)
        self.hover_cmp_text.bind("<MouseWheel>", self._on_hover_cmp_mousewheel)
        self.hover_cmp_text.bind("<Shift-Button-4>", self._on_hover_cmp_shift_wheel)
        self.hover_cmp_text.bind("<Shift-Button-5>", self._on_hover_cmp_shift_wheel)
        try:
            self.hover_cmp_text.configure(state="disabled")
        except Exception:
            pass

        # initial render should respect the persisted only-diff setting
        # Defer heavy initial refresh; SowMergeApp will lazy-load the active sheet.
        # (Still create the UI widgets now.)
        # self.refresh(row_only=None, rescan=True)
        # self._update_cursor_lines()
        # Initial panel state (must run after C区 widgets are created)
        self._apply_vertical_layout(persist=False)
        self._toggle_three_way_view(init_only=True)
        self._refresh_interaction_gate()

    # ---------- Scrolling sync ----------
    def _is_three_way_enabled(self) -> bool:
        """Whether the underlying comparison model is three-way (never folded away)."""
        try:
            return bool(getattr(self.app, "merge_mode", False) and getattr(self.app, "has_base", False))
        except Exception:
            return False

    def _is_three_way_expanded(self) -> bool:
        try:
            return bool(self._is_three_way_enabled() and self.three_way_var.get())
        except Exception:
            return False

    def _vertical_layout_available_height(self) -> int:
        try:
            height = int(self.frame.winfo_height())
            if height > 1:
                return height
        except (tk.TclError, AttributeError, TypeError, ValueError):
            pass
        try:
            return int(self.root.winfo_height())
        except (tk.TclError, AttributeError, TypeError, ValueError):
            return 620

    def _persist_vertical_layout(self) -> None:
        settings = getattr(self.app, "settings", None)
        if not isinstance(settings, dict):
            return
        mapping = self._vertical_layout.to_mapping()
        # Sheet navigation is app-global; keep it out of the per-comparison
        # pane record so restoring one comparison cannot overwrite another.
        mapping.pop("nav_height", None)
        settings.setdefault("vertical_sashes", {})[self._pane_settings_key] = mapping
        schedule = getattr(self.app, "_schedule_layout_settings_save", None)
        if callable(schedule):
            schedule()

    def _apply_vertical_layout(self, *, persist: bool = True) -> None:
        from .vertical_layout import GRIP_HEIGHT

        self._vertical_layout = self._vertical_layout.normalized(
            self._vertical_layout_available_height(),
            three_way=self._is_three_way_enabled(),
        )
        try:
            self.lower_area.configure(height=self._vertical_layout.lower_height)
            c_height = max(
                64,
                self._vertical_layout.lower_height
                - self._vertical_layout.hover_height
                - GRIP_HEIGHT,
            )
            self.c_area.configure(height=c_height)
            self.hover_cmp_host.configure(height=self._vertical_layout.hover_height)
        except (AttributeError, tk.TclError):
            return
        if persist:
            self._persist_vertical_layout()

    def _on_vertical_frame_configure(self, _event=None):
        self._apply_vertical_layout(persist=False)

    def _on_main_vertical_grip_press(self, event):
        self._vertical_drag_origin = (
            int(event.y_root),
            int(self._vertical_layout.lower_height),
            "lower",
        )

    def _on_main_vertical_grip_motion(self, event):
        from .vertical_layout import VerticalLayout

        origin_y, origin_value, _kind = getattr(
            self, "_vertical_drag_origin", (int(event.y_root), self._vertical_layout.lower_height, "lower")
        )
        self._vertical_layout = VerticalLayout(
            lower_height=origin_value + origin_y - int(event.y_root),
            hover_height=self._vertical_layout.hover_height,
            nav_height=self._vertical_layout.nav_height,
        )
        self._apply_vertical_layout()

    def _on_hover_vertical_grip_press(self, event):
        self._vertical_drag_origin = (
            int(event.y_root),
            int(self._vertical_layout.hover_height),
            "hover",
        )

    def _on_hover_vertical_grip_motion(self, event):
        from .vertical_layout import VerticalLayout

        origin_y, origin_value, _kind = getattr(
            self, "_vertical_drag_origin", (int(event.y_root), self._vertical_layout.hover_height, "hover")
        )
        self._vertical_layout = VerticalLayout(
            lower_height=self._vertical_layout.lower_height,
            hover_height=origin_value + origin_y - int(event.y_root),
            nav_height=self._vertical_layout.nav_height,
        )
        self._apply_vertical_layout()

    def reset_vertical_layout(self) -> None:
        from .vertical_layout import VerticalLayout

        self._vertical_layout = VerticalLayout.default(
            three_way=self._is_three_way_enabled()
        )
        self._apply_vertical_layout()

    def _hover_compare_reserved_height(self, enabled: bool | None = None) -> int:
        enabled = self._is_three_way_enabled() if enabled is None else bool(enabled)
        line_count = 4 if enabled else 2
        line_px = 18
        try:
            from tkinter import font as tkfont
            line_px = max(16, int(tkfont.Font(font=self.editor_font).metrics("linespace")))
        except Exception:
            pass
        # One compact heading + exact source rows + x-scrollbar. The main grid
        # receives every remaining pixel instead of reserving two blank lines.
        baseline = 124 if enabled else 84
        return max(baseline, int(line_px * line_count + 48))

    def _sync_hover_compare_reserved_height(self, enabled: bool | None = None):
        enabled = self._is_three_way_enabled() if enabled is None else bool(enabled)
        host = getattr(self, "hover_cmp_host", None)
        if host is None:
            return
        try:
            host.configure(height=self._hover_compare_reserved_height(enabled))
        except Exception:
            pass

    @staticmethod
    def _source_display_name(path_like: str) -> str:
        """Prefer stable workbook names and keep SVN revision hints when available."""
        s = (path_like or "").strip().strip('"')
        if not s:
            return "-"

        # Synthetic marker produced by parser when BASE is exported from .svn.
        m = re.match(r"(.+?)@BASE\(\.svn\)$", s, re.IGNORECASE)
        if m:
            return f"{os.path.basename(m.group(1))}@BASE"

        bn = os.path.basename(s)
        ext_pat = r"(?:xlsx|xlsm)"

        # Exported revision snapshots created by this tool.
        m = re.match(rf"{re.escape(APP_NAME)}_svncat_r(\d+)_\d{{8}}_\d{{6}}_(.+?\.{ext_pat})$", bn, re.IGNORECASE)
        if m:
            return f"{m.group(2)}@r{m.group(1)}"
        m = re.match(rf"{re.escape(APP_NAME)}_svncat_BASE_\d{{8}}_\d{{6}}_(.+?\.{ext_pat})$", bn, re.IGNORECASE)
        if m:
            return f"{m.group(1)}@BASE"

        # Temp wrapper pattern: xxx.xlsx-rev123.svn456.tmp.xlsx -> xxx.xlsx@r123
        m = re.match(rf"(.+?\.{ext_pat})-rev(\d+)\.svn\d+\.tmp\.{ext_pat}$", bn, re.IGNORECASE)
        if m:
            return f"{m.group(1)}@r{m.group(2)}"

        # SVN conflict side files: file.merge-left.r123 -> file@r123
        m = re.match(rf"(.+?)\.merge-(?:left|right)\.r(\d+)$", bn, re.IGNORECASE)
        if m:
            return f"{m.group(1)}@r{m.group(2)}"

        # Generic prefixed temp: keep original workbook tail if present.
        m = re.match(rf".*?_(.+?\.{ext_pat})$", bn, re.IGNORECASE)
        if m and ".merge-" not in m.group(1).lower():
            return m.group(1)
        return bn

    def _sheet_meta(self) -> dict[str, object]:
        return self.app.get_sheet_meta(self.sheet)

    def _is_missing_sheet_view(self) -> bool:
        return str(self._sheet_meta().get("view_mode") or "") == "missing_sheet"

    def _side_has_sheet(self, side: str) -> bool:
        meta = self._sheet_meta()
        side = str(side or "").upper()
        if side == "A":
            return bool(meta.get("has_a"))
        if side in ("B", "THEIRS"):
            return bool(meta.get("has_b"))
        if side == "BASE":
            return bool(meta.get("has_base"))
        return False

    def _display_ws(self, side: str, edit: bool = False):
        side = str(side or "").upper()
        if edit:
            edit_ready = getattr(self.app, "_edit_workbooks_ready", None)
            if callable(edit_ready) and not edit_ready():
                # View-only rendering must not synchronously load editable
                # workbooks. Use the value sheet as a provisional display.
                return self._display_ws(side, edit=False)
        ws = self.app.ws_for_side(side, self.sheet, edit=edit, allow_missing=True)
        if ws is not None:
            return ws
        key = (side, bool(edit))
        cache = getattr(self, "_blank_ws_cache", None)
        if cache is None:
            self._blank_ws_cache = {}
            cache = self._blank_ws_cache
        if key not in cache:
            cache[key] = _blank_worksheet(self.sheet)
        return cache[key][1]

    def _base_row_for_pair(self, pair_idx: int, pair: tuple[int | None, int | None] | None = None) -> int | None:
        if not self._is_three_way_enabled():
            return None
        if not getattr(self.app, "has_base", False):
            return None
        overrides = getattr(self, "pair_base_row_override", {}) or {}
        if pair_idx in overrides:
            return overrides.get(pair_idx)
        if pair is None:
            if not (0 <= pair_idx < len(self.row_pairs)):
                return None
            pair = self.row_pairs[pair_idx]
        ra, rb = pair
        if self._is_missing_sheet_view():
            rows = getattr(self, "_missing_base_row_map", {}) or {}
            return rows.get(pair_idx)
        mine_map = getattr(self, "mine_to_base_row", {}) or {}
        theirs_map = getattr(self, "theirs_to_base_row", {}) or {}
        if ra is not None and ra in mine_map:
            return mine_map.get(ra)
        if rb is not None and rb in theirs_map:
            return theirs_map.get(rb)
        return None

    def _derive_lifecycle_state(self) -> str:
        """Return the current per-Sheet readiness state.

        Rendering and navigation remain available in every non-closing state.
        Workbook mutations are permitted only after the row model, the requested
        comparison mode, column projection, and editable workbooks are ready.
        """
        if bool(getattr(self.app, "_is_closing", False)):
            return "CLOSING"
        if getattr(self, "_lifecycle_error", None):
            return "FAILED"
        if bool(getattr(self, "_lifecycle_canceled", False)):
            return "CANCELED"
        interactive_event = getattr(self.app, "_interactive_action_event", None)
        try:
            if interactive_event is not None and interactive_event.is_set():
                return "BUSY"
        except Exception:
            pass
        if bool(getattr(self, "_mode_switch_pending", False)):
            return "DIFFING"
        if not bool(getattr(self, "_data_ready", False)):
            return "LOADING"
        if not bool(getattr(self, "_row_model_exact", False)):
            return "DIFFING"
        if not bool(getattr(self, "_cache_formula_aware", False)):
            return "DIFFING"
        if not bool(getattr(self, "_pair_diff_full_exact", False)):
            return "DIFFING"
        if (
            self._is_three_way_enabled()
            and getattr(self.app, "has_base", False)
            and not bool(getattr(self, "_base_diff_full_exact", False))
        ):
            return "DIFFING"
        requested_only_diff = bool(getattr(self, "only_diff_var", None) and self.only_diff_var.get())
        if requested_only_diff and (
            not bool(getattr(self, "_only_diff_rows_exact", False))
            or not self._has_valid_only_diff_snapshot_cache()
        ):
            return "DIFFING"
        try:
            if not self._column_mapping_is_current():
                return "DIFFING"
        except Exception:
            return "DIFFING"
        edit_ready = getattr(self.app, "_edit_workbooks_ready", None)
        if callable(edit_ready) and not edit_ready():
            return "EDIT_LOADING"
        return "READY"

    def _mutation_block_message(self, action: str = "此操作") -> str:
        state = self._derive_lifecycle_state()
        detail = {
            "LOADING": "当前 Sheet 正在加载行结构。",
            "DIFFING": "当前 Sheet 正在生成精确差异。",
            "EDIT_LOADING": "可编辑工作簿正在后台加载。",
            "BUSY": "当前有一项修改正在执行。",
            "FAILED": f"当前 Sheet 计算失败：{getattr(self, '_lifecycle_error', '')}",
            "CANCELED": "当前 Sheet 的后台计算已取消。",
            "CLOSING": "工具正在关闭。",
        }.get(state, "当前 Sheet 尚未准备完成。")
        return f"{action}暂不可用。{detail}加载完成后请再次操作；当前仍可查看和切换 Sheet。"

    def _guard_mutation_ready(self, action: str = "此操作", *, notify: bool = True) -> bool:
        self._refresh_interaction_gate()
        if getattr(self, "_lifecycle_state", "") == "READY":
            return True
        if getattr(self, "_lifecycle_state", "") == "EDIT_LOADING":
            # The first explicit mutation opts into the deferred editable
            # preload.  Never wait on the Tk thread; the current click is
            # rejected safely and the next click can proceed after READY.
            request = getattr(self.app, "_request_edit_preload", None)
            if callable(request):
                request()
        if notify:
            show_notice = getattr(self.app, "show_nonblocking_notice", None)
            if callable(show_notice):
                show_notice(self._mutation_block_message(action), warning=False, duration_ms=6000)
        _dlog(
            f"mutation blocked sheet={self.sheet} action={action} "
            f"state={getattr(self, '_lifecycle_state', 'unknown')}"
        )
        return False

    def _guard_copy_direction(self, direction: str, action: str = "此操作") -> bool:
        """Reject commands that would write a protected VCS Base side.

        In a TortoiseSVN two-way view A is a temporary Base projection and B
        is the real Mine working file.  Keep this guard at every public copy
        entry point so keyboard, context, stale callback and direct test
        paths share the same no-Base-write boundary.
        """
        normalized = str(direction or "").upper()
        try:
            vcs_two_way = bool(self.app._is_vcs_two_way_mode())
        except Exception:
            vcs_two_way = bool(
                not getattr(self.app, "merge_mode", False)
                and getattr(self.app, "diff_base_mine_mode", False)
            )
        target_is_base = normalized in {"B2A", "BASE2A", "MINE2A"}
        mine_keep_valid = bool(
            getattr(self.app, "merge_mode", False)
            and getattr(self.app, "has_base", False)
        )
        if vcs_two_way and target_is_base:
            message = f"{action}已阻止：VCS 两方模式的 Base 是只读临时副本，只能修改并保存 Mine。"
        elif normalized == "MINE2A" and not mine_keep_valid:
            message = f"{action}已阻止：‘保留 Mine’仅适用于有效的三方合并视图。"
        else:
            return True
        try:
            show_notice = getattr(self.app, "show_nonblocking_notice", None)
            if callable(show_notice):
                show_notice(message, warning=True, duration_ms=6000)
            else:
                self.info.configure(text=message)
        except tk.TclError:
            pass
        except Exception:
            pass
        _dlog(
            f"COPY_DIRECTION_BLOCKED sheet={self.sheet} direction={normalized} "
            f"vcs_two_way={vcs_two_way} mine_keep_valid={mine_keep_valid}"
        )
        return False

    def _column_undo_model_ready(self) -> bool:
        """Allow a column transaction while only-diff presentation finishes.

        Column actions have a complete workbook snapshot, and both applying and
        restoring them rely only on the exact row, Base, formula, and column
        models.  They therefore remain safe while the optional only-diff row
        list is still being rebuilt.
        """
        try:
            if bool(getattr(self.app, "_is_closing", False)):
                return False
            if getattr(self, "_lifecycle_error", None) or bool(getattr(self, "_lifecycle_canceled", False)):
                return False
            event = getattr(self.app, "_interactive_action_event", None)
            if event is not None and event.is_set():
                return False
            if not all((
                bool(getattr(self, "_data_ready", False)),
                bool(getattr(self, "_row_model_exact", False)),
                bool(getattr(self, "_cache_formula_aware", False)),
                bool(getattr(self, "_pair_diff_full_exact", False)),
                bool(getattr(self, "_column_mapping_is_current", lambda: False)()),
            )):
                return False
            if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
                if not bool(getattr(self, "_base_diff_full_exact", False)):
                    return False
            edit_ready = getattr(self.app, "_edit_workbooks_ready", None)
            return not callable(edit_ready) or bool(edit_ready())
        except Exception:
            return False

    def _refresh_interaction_gate(self):
        """Atomically project lifecycle readiness onto every mutation control."""
        previous = getattr(self, "_lifecycle_state", None)
        current = self._derive_lifecycle_state()
        self._lifecycle_state = current
        try:
            self._command_state = self.app.command_state()
            if self._command_state.busy:
                current = "BUSY"
        except Exception:
            self._command_state = None
        if previous != current:
            self._lifecycle_generation += 1
            _dlog(
                f"SHEET_STATE sheet={self.sheet} generation={self._lifecycle_generation} "
                f"{previous}->{current}"
            )
        ready = current == "READY" and not bool(getattr(self._command_state, "busy", False))
        mutation_state = "normal" if ready else "disabled"
        try:
            checkbox_state = mutation_state
            if getattr(self.app, "merge_conflict_mode", False):
                checkbox_state = "disabled"
            self.only_diff_cb.configure(text="仅差异", state=checkbox_state)
        except Exception:
            pass
        try:
            force_state = mutation_state
            if getattr(self.app, "merge_conflict_mode", False):
                force_state = "disabled"
            self.force_align_cb.configure(state=force_state)
        except Exception:
            pass
        for name in (
            "use_left_btn",
            "use_right_btn",
            "use_left_menu_btn",
            "use_right_menu_btn",
            "use_base_btn",
            "undo_btn",
            "save_a_btn",
            "save_b_btn",
            "three_way_cb",
        ):
            widget = getattr(self, name, None)
            if widget is not None:
                try:
                    widget.configure(state=mutation_state)
                except Exception:
                    pass
        try:
            self.manual_rescan_btn.configure(
                state=("normal" if current in ("READY", "FAILED", "CANCELED") else "disabled")
            )
        except Exception:
            pass
        try:
            if getattr(self.app, "selected_sheet", None) == self.sheet:
                self.app.recalc_btn.configure(state=mutation_state)
        except Exception:
            pass
        self._update_sheet_role_labels()
        self._refresh_column_action_buttons()
        try:
            vcs_two_way = bool(self.app._is_vcs_two_way_mode())
        except Exception:
            vcs_two_way = bool(
                not getattr(self.app, "merge_mode", False)
                and getattr(self.app, "diff_base_mine_mode", False)
            )
        if vcs_two_way:
            # Reverse-direction and Base-save controls target the temporary
            # A-side projection and are never usable in an SVN two-way view.
            for widget in (
                getattr(self, "use_right_btn", None),
                getattr(self, "use_right_menu_btn", None),
                getattr(self, "save_a_btn", None),
            ):
                if widget is not None:
                    try:
                        widget.configure(state="disabled")
                    except Exception:
                        pass
        try:
            self.app._refresh_command_widgets()
        except Exception:
            pass

    def _hide_identity_label_tooltip(self):
        after_id = getattr(self, "_identity_tooltip_after_id", None)
        if after_id is not None and self.root is not None:
            try:
                self.root.after_cancel(after_id)
            except Exception:
                pass
        self._identity_tooltip_after_id = None
        tooltip = getattr(self, "_identity_tooltip_window", None)
        if tooltip is not None:
            try:
                tooltip.destroy()
            except Exception:
                pass
        self._identity_tooltip_window = None

    def _show_identity_label_tooltip(self, label):
        self._identity_tooltip_after_id = None
        detail = str(getattr(label, "_identity_detail_text", "") or "").strip()
        if not detail or self.root is None:
            return
        self._hide_identity_label_tooltip()
        try:
            tooltip = tk.Toplevel(self.root)
            tooltip.wm_overrideredirect(True)
            tooltip.attributes("-topmost", True)
            tk.Label(
                tooltip,
                text=detail,
                justify="left",
                anchor="w",
                bg="#FFFDE7",
                fg="#263238",
                bd=1,
                relief="solid",
                padx=8,
                pady=6,
                wraplength=900,
            ).pack(fill="both", expand=True)
            x = max(0, int(label.winfo_rootx()))
            y = max(0, int(label.winfo_rooty() + label.winfo_height() + 2))
            tooltip.geometry(f"+{x}+{y}")
            self._identity_tooltip_window = tooltip
        except Exception:
            self._identity_tooltip_window = None

    def _bind_identity_label_tooltip(self, label):
        def _enter(_event=None):
            self._hide_identity_label_tooltip()
            if self.root is None:
                return
            try:
                self._identity_tooltip_after_id = self.root.after(
                    350,
                    lambda: self._show_identity_label_tooltip(label),
                )
            except Exception:
                self._identity_tooltip_after_id = None

        label.bind("<Enter>", _enter, add="+")
        label.bind("<Leave>", lambda _event=None: self._hide_identity_label_tooltip(), add="+")

    def _pane_source_paths(self) -> dict[str, str]:
        """Map visible pane roles to the concrete files currently rendered."""
        if self._is_three_way_enabled():
            outcome = getattr(self.app, "startup_outcome", None)
            candidate = (
                getattr(outcome, "candidate_path", None)
                or getattr(self.app, "merge_candidate_path", None)
            )
            return {
                "a": str(candidate or getattr(self.app, "raw_mine", None) or self.app.file_a or ""),
                "base": str(
                    getattr(self.app, "raw_base", None)
                    or getattr(self.app, "base_path", None)
                    or ""
                ),
                "b": str(getattr(self.app, "raw_theirs", None) or self.app.file_b or ""),
            }
        return {
            "a": str(getattr(self.app, "raw_base", None) or self.app.file_a or ""),
            "base": "",
            "b": str(getattr(self.app, "raw_mine", None) or self.app.file_b or ""),
        }

    def _copy_visible_pane_path(self, side: str):
        full_path = str(getattr(self, "_visible_pane_paths", {}).get(side, "") or "").strip()
        if not full_path or self.root is None:
            return
        try:
            self.root.clipboard_clear()
            self.root.clipboard_append(full_path)
            self.root.update_idletasks()
            self.info.configure(text="已复制文件路径")
            self.root.after(1800, lambda: self.info.configure(text=""))
        except Exception:
            pass

    @staticmethod
    def _set_identity_card_background(card, identity_label, file_label, background: str):
        for widget in (card, identity_label, file_label):
            try:
                widget.configure(bg=background)
            except Exception:
                pass

    def _update_visible_path_labels(self):
        paths = self._pane_source_paths()
        self._visible_pane_paths = paths
        for side, label in (
            ("a", self.path_file_label_a),
            ("base", self.path_file_label_base),
            ("b", self.path_file_label_b),
        ):
            full_path = paths.get(side, "")
            label.configure(text=f"文件路径：{format_visible_file_path(full_path)}")
            label._identity_detail_text = f"完整路径：{format_visible_file_path(full_path, max_len=4096)}\n单击复制路径"

    def _layout_identity_cards(self, expanded: bool | None = None):
        expanded = self._is_three_way_expanded() if expanded is None else bool(expanded)
        for card in (self.path_card_a, self.path_card_base, self.path_card_b):
            card.grid_remove()
        for column in range(3):
            self.path_bar.grid_columnconfigure(column, weight=0, uniform="")

        if not self._is_three_way_enabled():
            visible = (self.path_card_a, self.path_card_b)
        elif expanded:
            visible = (self.path_card_base, self.path_card_a, self.path_card_b)
        elif str(self._folded_identity or "base").lower() == "theirs":
            visible = (self.path_card_base, self.path_card_a)
        else:
            visible = (self.path_card_a, self.path_card_b)

        uniform = "visible_workbook_identity"
        for column, card in enumerate(visible):
            self.path_bar.grid_columnconfigure(column, weight=1, uniform=uniform)
            card.grid(row=0, column=column, sticky="nsew", padx=(0, 4 if column < len(visible) - 1 else 0))

    @staticmethod
    def _identity_detail_text(
        role_label: str,
        identity: VersionIdentity | None,
        *,
        candidate: bool = False,
    ) -> str:
        if identity is None:
            return f"{role_label}：-"
        full_path = identity.path or identity.effective_path or "-"
        lines = [
            f"{role_label}：{format_version_identity(identity, candidate=candidate)}",
            f"完整路径：{full_path}",
        ]
        if identity.availability_reason:
            lines.append(f"Author/版本说明：{identity.availability_reason}")
        return "\n".join(lines)

    def _update_sheet_role_labels(self):
        enabled = self._is_three_way_enabled()
        meta = self._sheet_meta()
        presentation = self.role_presentation
        try:
            # Pane headers are updated alongside identity cards; this is the
            # path that also runs after a two-way/three-way toggle.
            self.left_title.configure(text=presentation.left)
            self.mid_title.configure(text=presentation.middle)
            self.right_title.configure(text=presentation.right)
        except Exception:
            pass
        try:
            if enabled:
                context = getattr(self.app, "launch_context", None)
                outcome = getattr(self.app, "startup_outcome", None)
                mine_identity = context.identity_for("mine") if context else None
                base_identity = context.identity_for("base") if context else None
                theirs_identity = context.identity_for("theirs") if context else None
                mine_label = merge_role_label(context, "mine")
                base_label = merge_role_label(context, "base")
                theirs_label = merge_role_label(context, "theirs")
                if meta.get("has_a") and getattr(outcome, "candidate_path", None):
                    source_role = str(getattr(outcome, "source_role", "") or "mine").lower()
                    source_identity = context.identity_for(source_role) if context else mine_identity
                    mine_text = (
                        "Merged="
                        f"{format_compact_version_identity(source_identity)}"
                    )
                    mine_detail = self._identity_detail_text(
                        f"{merge_role_label(context, 'mine', candidate=True)}"
                        f"（初始化自 {merge_role_label(context, source_role)}）",
                        source_identity,
                        candidate=True,
                    )
                else:
                    mine_text = (
                        mine_label + "=" + format_compact_version_identity(mine_identity)
                        if meta.get("has_a") and mine_identity else
                        (f"{mine_label}={self._source_display_name(getattr(self.app, 'raw_mine', None) or self.app.file_a)}" if meta.get("has_a") else f"{mine_label}=空白(该侧无此Sheet)")
                    )
                    mine_detail = (
                        self._identity_detail_text(mine_label, mine_identity)
                        if meta.get("has_a") and mine_identity
                        else mine_text
                    )
                base_text = (
                    base_label + "=" + format_compact_version_identity(base_identity)
                    if meta.get("has_base") and base_identity else
                    (f"{base_label}={self._source_display_name(getattr(self.app, 'raw_base', None) or getattr(self.app, 'base_path', ''))}" if meta.get("has_base") else f"{base_label}=空白(该侧无此Sheet)")
                )
                theirs_text = (
                    theirs_label + "=" + format_compact_version_identity(theirs_identity)
                    if meta.get("has_b") and theirs_identity else
                    (f"{theirs_label}={self._source_display_name(getattr(self.app, 'raw_theirs', None) or self.app.file_b)}" if meta.get("has_b") else f"{theirs_label}=空白(该侧无此Sheet)")
                )
                base_detail = (
                    self._identity_detail_text(base_label, base_identity)
                    if meta.get("has_base") and base_identity
                    else base_text
                )
                theirs_detail = (
                    self._identity_detail_text(theirs_label, theirs_identity)
                    if meta.get("has_b") and theirs_identity
                    else theirs_text
                )
                self.path_label_a.configure(text=mine_text, bg=_MINE_BG)
                self.path_label_base.configure(text=base_text, bg=_BASE_BG)
                self.path_label_b.configure(text=theirs_text, bg=_THEIRS_BG)
                self._set_identity_card_background(
                    self.path_card_a,
                    self.path_label_a,
                    self.path_file_label_a,
                    _MINE_BG,
                )
                self._set_identity_card_background(
                    self.path_card_base,
                    self.path_label_base,
                    self.path_file_label_base,
                    _BASE_BG,
                )
                self._set_identity_card_background(
                    self.path_card_b,
                    self.path_label_b,
                    self.path_file_label_b,
                    _THEIRS_BG,
                )
                self.path_label_a._identity_detail_text = mine_detail
                self.path_label_base._identity_detail_text = base_detail
                self.path_label_b._identity_detail_text = theirs_detail
            else:
                context = getattr(self.app, "launch_context", None)
                base_identity = context.identity_for("base") if context else None
                mine_identity = context.identity_for("mine") if context else None
                if getattr(self.app, "role_mode", "") == "source-target":
                    base_label, mine_label = "Source（只读）", "Target（可保存）"
                else:
                    base_label = merge_role_label(context, "base")
                    mine_label = merge_role_label(context, "mine")
                base_src = getattr(self.app, "raw_base", None) or self.app.file_a
                mine_src = getattr(self.app, "raw_mine", None) or self.app.file_b
                left_text = (
                    base_label + "=" + format_compact_version_identity(base_identity)
                    if meta.get("has_a") and base_identity
                    else (f"{base_label}={self._source_display_name(base_src)}" if meta.get("has_a") else f"{base_label}=空白(该侧无此Sheet)")
                )
                right_text = (
                    mine_label + "=" + format_compact_version_identity(mine_identity)
                    if meta.get("has_b") and mine_identity
                    else (f"{mine_label}={self._source_display_name(mine_src)}" if meta.get("has_b") else f"{mine_label}=空白(该侧无此Sheet)")
                )
                self.path_label_a.configure(text=left_text, bg=_BASE_BG)
                self.path_label_b.configure(text=right_text, bg=_MINE_BG)
                self._set_identity_card_background(
                    self.path_card_a,
                    self.path_label_a,
                    self.path_file_label_a,
                    _BASE_BG,
                )
                self._set_identity_card_background(
                    self.path_card_b,
                    self.path_label_b,
                    self.path_file_label_b,
                    _MINE_BG,
                )
                self.path_label_a._identity_detail_text = (
                    self._identity_detail_text(base_label, base_identity)
                    if meta.get("has_a") and base_identity
                    else f"{base_label}\n完整路径：{base_src}"
                )
                self.path_label_b._identity_detail_text = (
                    self._identity_detail_text(mine_label, mine_identity)
                    if meta.get("has_b") and mine_identity
                    else f"{mine_label}\n完整路径：{mine_src}"
                )
            self._update_visible_path_labels()
        except Exception:
            pass
        try:
            gate_ready = getattr(self, "_lifecycle_state", "") == "READY"
            if self._is_missing_sheet_view():
                if enabled:
                    left_state = "normal" if gate_ready and (meta.get("has_base") or meta.get("has_a")) else "disabled"
                else:
                    left_state = "normal" if gate_ready and meta.get("has_a") else "disabled"
                right_state = "normal" if gate_ready and meta.get("has_b") else "disabled"
                mine_state = "normal" if gate_ready and meta.get("has_a") else "disabled"
            else:
                left_state = "normal" if gate_ready else "disabled"
                right_state = "normal" if gate_ready else "disabled"
                mine_state = "normal" if gate_ready else "disabled"
            self.use_left_btn.configure(state=left_state)
            self.use_right_btn.configure(state=right_state)
            if self.use_base_btn is not None:
                self.use_base_btn.configure(
                    state=(
                        mine_state
                        if getattr(self.app, "merge_mode", False)
                        and getattr(self.app, "has_base", False)
                        else "disabled"
                    )
                )
        except Exception:
            pass
        try:
            self._refresh_copy_scope_buttons()
        except Exception:
            pass

    def _toggle_three_way_view(self, init_only: bool = False):
        if not init_only and self._derive_lifecycle_state() != "READY":
            try:
                self.three_way_var.set(int(self._last_three_way_value))
            except Exception:
                pass
            self._guard_mutation_ready("切换三方视图")
            return
        model_enabled = self._is_three_way_enabled()
        expanded = self._is_three_way_expanded()
        context = getattr(self.app, "launch_context", None)
        outcome = getattr(self.app, "startup_outcome", None)
        branch_candidate = bool(
            context
            and context.scenario == MergeScenario.CROSS_BRANCH_MERGE
            and getattr(outcome, "candidate_path", None)
        )
        mine_pane_label = merge_role_label(context, "mine", candidate=branch_candidate)
        base_pane_label = self.role_presentation.middle
        theirs_pane_label = self.role_presentation.right
        if not getattr(self.app, "merge_mode", False):
            mine_pane_label = self.role_presentation.right
            base_pane_label = self.role_presentation.left
        try:
            panes = list(self._main_paned.panes())
            mid_id = str(self._mid_wrap)
            right_id = str(self._right_wrap)
            has_mid = mid_id in panes
            has_right = right_id in panes
            folded_role = str(self._folded_identity or "base").lower()
            if expanded:
                if not has_mid:
                    self._main_paned.insert(0, self._mid_wrap, weight=1)
                if not has_right:
                    self._main_paned.add(self._right_wrap, weight=1)
            elif folded_role == "theirs":
                if not has_mid:
                    self._main_paned.insert(0, self._mid_wrap, weight=1)
                if has_right:
                    self._main_paned.forget(self._right_wrap)
            else:
                if not has_right:
                    self._main_paned.add(self._right_wrap, weight=1)
                if has_mid:
                    self._main_paned.forget(self._mid_wrap)
        except Exception:
            pass
        try:
            self._layout_identity_cards(expanded)
            if expanded:
                self.left_title.configure(text=mine_pane_label, background=_MINE_BG)
                self.mid_title.configure(text=base_pane_label, background=_BASE_BG)
                self.right_title.configure(text=theirs_pane_label, background=_THEIRS_BG)
            else:
                if str(self._folded_identity or "base").lower() == "theirs":
                    # Mine ≡ Theirs: keep Base plus the initialized candidate
                    # visible and fold only the proven-redundant Theirs pane.
                    self.mid_title.configure(text=base_pane_label, background=_BASE_BG)
                    self.left_title.configure(text=mine_pane_label, background=_MINE_BG)
                else:
                    # Base is redundant to one working side; keep the candidate
                    # and Theirs visible while retaining Base in memory.
                    self.left_title.configure(text=mine_pane_label, background=_MINE_BG)
                    self.right_title.configure(text=theirs_pane_label, background=_THEIRS_BG)
                    self.mid_title.configure(text=base_pane_label, background=_BASE_BG)
            self._update_sheet_role_labels()
            if self.three_way_cb is not None:
                self.three_way_cb.configure(text="折叠三方" if expanded else "展开三方")
        except Exception:
            pass
        try:
            self.cursor_cmp.configure(height=3 if model_enabled else 2)
        except Exception:
            pass
        try:
            self.cursor_cmp_ln.configure(height=3 if model_enabled else 2)
        except Exception:
            pass
        try:
            if hasattr(self, "hover_cmp_text"):
                self.hover_cmp_text.configure(height=4 if model_enabled else 2)
        except Exception:
            pass
        try:
            self._sync_hover_compare_reserved_height(model_enabled)
        except Exception:
            pass
        self._apply_vertical_layout(persist=False)
        if not init_only:
            try:
                self._last_three_way_value = int(self.three_way_var.get())
                # Folding only changes pane geometry.  Do not invalidate/rebuild
                # the three-way model: that preserves sheet, scroll position,
                # cursor/selection, pending operations, and candidate state.
                self._refresh_interaction_gate()
            except Exception:
                pass
        try:
            self.frame.after(0, self._keep_panes_equal)
        except Exception:
            pass
        self._refresh_column_action_buttons()

    def _sync_main_x_to_frac(self, first):
        try:
            frac = float(first)
        except Exception:
            return

        prev_xsync = bool(getattr(self, "_xsyncing", False))
        self._xsyncing = True
        try:
            # Use left pane as anchor, then map by pixel position to peers.
            # This avoids drift when panes render different glyph widths.
            self.left.xview_moveto(frac)
            self._sync_main_x_from_widget(self.left, frac)
        except Exception:
            pass
        finally:
            self._xsyncing = prev_xsync

    def _sync_c_projection_viewport_width(self):
        """C uses the full lower-pane width assigned by the geometry manager."""
        return

    def _sync_c_x_to_frac(self, first):
        try:
            frac = float(first)
        except Exception:
            return

        # Programmatic C-pane sync must not feed back into main panes.
        prev_suppress = bool(getattr(self, "_suppress_c_xsync", False))
        self._suppress_c_xsync = True
        try:
            self._sync_c_projection_viewport_width()
            try:
                c_first = self._map_xfirst_between_widgets(self.left, self.cursor_cmp, frac)
                self.cursor_cmp.xview_moveto(c_first)
                if getattr(self, "cursor_cmp_colhdr", None) is not None:
                    self.cursor_cmp_colhdr.xview_moveto(c_first)
            except Exception:
                pass
            try:
                cell_first = self._map_xfirst_between_widgets(self.left, self.cell_cmp_text, frac)
                self.cell_cmp_text.xview_moveto(cell_first)
            except Exception:
                pass
            self._set_c_hscrollbars_from_main()
        finally:
            self._suppress_c_xsync = prev_suppress

    def _set_c_hscrollbars_from_main(self):
        try:
            first, last = self.left.xview()
        except Exception:
            try:
                first, last = self.right.xview()
            except Exception:
                first, last = (0.0, 1.0)
        try:
            if getattr(self, "cursor_hsb", None) is not None:
                c_first, c_last = self.cursor_cmp.xview()
                self.cursor_hsb.set(c_first, c_last)
        except Exception:
            pass
        try:
            if getattr(self, "cell_cmp_hsb", None) is not None:
                self.cell_cmp_hsb.set(first, last)
        except Exception:
            pass

    @staticmethod
    def _clamp(value: float, lo: float, hi: float) -> float:
        try:
            v = float(value)
        except Exception:
            return lo
        if v < lo:
            return lo
        if v > hi:
            return hi
        return v

    def _map_xfirst_between_widgets(self, src_widget: tk.Text, dst_widget: tk.Text, src_first) -> float:
        """Map horizontal scroll position by pixel offset, with end-point locking."""
        try:
            sf, sl = src_widget.xview()
            sf = float(sf)
            sl = float(sl)
            df, dl = dst_widget.xview()
            df = float(df)
            dl = float(dl)
            src_first_f = float(src_first)
            src_vis = max(1e-6, sl - sf)
            dst_vis = max(1e-6, dl - df)
            src_max = max(0.0, 1.0 - src_vis)
            dst_max = max(0.0, 1.0 - dst_vis)
            src_first_f = self._clamp(src_first_f, 0.0, src_max)

            # Lock endpoints: when source is at extreme left/right, target should also
            # reach its own extreme to avoid "not fully right" under different viewports.
            eps = 1e-4
            if src_first_f <= eps:
                return 0.0
            if src_max <= eps:
                return 0.0
            if src_first_f >= src_max - eps:
                return dst_max

            src_vp = max(1.0, float(src_widget.winfo_width()))
            dst_vp = max(1.0, float(dst_widget.winfo_width()))
            src_total = src_vp / src_vis
            dst_total = dst_vp / dst_vis
            if src_total <= 1e-6 or dst_total <= 1e-6:
                return self._clamp(src_first_f, 0.0, dst_max)

            # Convert to absolute left-pixel position in source, then map to destination ratio.
            left_px = src_first_f * src_total
            dst_first = left_px / dst_total
            return self._clamp(dst_first, 0.0, dst_max)
        except Exception:
            try:
                return float(src_first)
            except Exception:
                return 0.0

    def _sync_main_x_from_widget(self, src_widget: tk.Text, src_first):
        """Sync A/B(/BASE) in the shared logical-slot coordinate system."""
        try:
            # Every main pane now renders exactly the same slot widths and
            # separators.  Re-mapping through independently inferred pixel
            # totals introduces rounding drift (notably after a click), so the
            # canonical logical fraction is applied directly to all peers.
            canonical_first = max(0.0, float(src_first))
            left_first = canonical_first
            right_first = canonical_first
            self.left.xview_moveto(left_first)
            self.right.xview_moveto(right_first)
            if self._is_three_way_enabled():
                base_first = canonical_first
                self.base.xview_moveto(base_first)
            if getattr(self, "left_colhdr", None) is not None:
                self.left_colhdr.xview_moveto(left_first)
            if getattr(self, "right_colhdr", None) is not None:
                self.right_colhdr.xview_moveto(right_first)
            if self._is_three_way_enabled() and getattr(self, "base_colhdr", None) is not None:
                base_first = float((self.base.xview() or (0.0, 1.0))[0])
                self.base_colhdr.xview_moveto(base_first)
            lf, ll = self.left.xview()
            rf, rl = self.right.xview()
            self.hsb_left.set(lf, ll)
            self.hsb_right.set(rf, rl)
            if self._is_three_way_enabled():
                mf, ml = self.base.xview()
                self.hsb_mid.set(mf, ml)
        except Exception:
            pass

    def _sync_c_x_from_widget(self, src_widget: tk.Text, src_first):
        """Sync C panes using the canonical logical-slot x fraction."""
        prev_suppress = bool(getattr(self, "_suppress_c_xsync", False))
        self._suppress_c_xsync = True
        try:
            self._sync_c_projection_viewport_width()
            try:
                c_first = self._map_xfirst_between_widgets(
                    src_widget,
                    self.cursor_cmp,
                    src_first,
                )
                self.cursor_cmp.xview_moveto(c_first)
                if getattr(self, "cursor_cmp_colhdr", None) is not None:
                    self.cursor_cmp_colhdr.xview_moveto(c_first)
            except Exception:
                pass
            try:
                if hasattr(self, "cell_cmp_text"):
                    cell_first = self._map_xfirst_between_widgets(src_widget, self.cell_cmp_text, src_first)
                    self.cell_cmp_text.xview_moveto(cell_first)
            except Exception:
                pass
            self._set_c_hscrollbars_from_main()
        finally:
            self._suppress_c_xsync = prev_suppress

    def _is_click_trace_active(self) -> bool:
        try:
            return float(getattr(self, "_trace_click_until", 0.0) or 0.0) > time.time()
        except Exception:
            return False

    def _log_click_trace_state(self, stage: str):
        if not self._is_click_trace_active():
            return
        try:
            lx = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            lx = -1.0
        try:
            rx = float((self.right.xview() or (0.0, 1.0))[0])
        except Exception:
            rx = -1.0
        try:
            cx = float((self.cursor_cmp.xview() or (0.0, 1.0))[0])
        except Exception:
            cx = -1.0
        try:
            li = str(self.left.index("insert"))
        except Exception:
            li = "?"
        try:
            ri = str(self.right.index("insert"))
        except Exception:
            ri = "?"
        _dlog(f"click_trace {stage} x(left={lx:.6f},right={rx:.6f},c={cx:.6f}) insert(left={li},right={ri})")

    def _post_click_x_guard(self, saved_x: float, stage: str):
        try:
            now_x = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            now_x = saved_x
        drift = abs(now_x - saved_x)
        if drift > 1e-4:
            try:
                self._sync_main_x_to_frac(saved_x)
                self._sync_c_x_to_frac(saved_x)
            except Exception:
                pass
            _dlog(f"click_guard_restore stage={stage} saved={saved_x:.6f} now={now_x:.6f} drift={drift:.6f}")
        else:
            _dlog(f"click_guard_ok stage={stage} saved={saved_x:.6f} now={now_x:.6f}")
        self._log_click_trace_state(f"post_guard:{stage}")

    def _xview_cursor_cmp(self, *args):
        if self._xsyncing:
            return
        self._xsyncing = True
        try:
            # C has a wider viewport than each main pane. Its scrollbar therefore
            # controls C itself; main-pane scrolling still updates C's left edge.
            self.cursor_cmp.xview(*args)
            first, last = self.cursor_cmp.xview()
            if getattr(self, "cursor_cmp_colhdr", None) is not None:
                self.cursor_cmp_colhdr.xview_moveto(first)
            self._set_c_hscrollbars_from_main()
        finally:
            self._xsyncing = False
        try:
            self._schedule_diff_maps()
        except Exception:
            pass

    def _xscroll_cursor_cmp(self, first, last):
        if self._is_click_trace_active():
            _dlog(f"xscroll_cursor_cmp first={first} last={last} xsyncing={self._xsyncing} suppress={getattr(self, '_suppress_c_xsync', False)}")
        try:
            if getattr(self, "cursor_hsb", None) is not None:
                self.cursor_hsb.set(float(first), float(last))
        except Exception:
            pass

    def _xview_cell_cmp(self, *args):
        if self._xsyncing:
            return
        self._xsyncing = True
        try:
            # Keep the lower C-area scrollbar as a main-pane controller too.
            # The cell text itself is often narrower than the main sheet viewport,
            # so driving from its own xview would collapse the thumb to 0..1.
            self.left.xview(*args)
            first, last = self.left.xview()
            self._sync_main_x_to_frac(first)
            self._sync_c_x_from_widget(self.left, first)
            self._set_c_hscrollbars_from_main()
        finally:
            self._xsyncing = False
        try:
            self._schedule_diff_maps()
        except Exception:
            pass

    def _xscroll_cell_cmp(self, first, last):
        if self._is_click_trace_active():
            _dlog(f"xscroll_cell_cmp first={first} last={last} xsyncing={self._xsyncing} suppress={getattr(self, '_suppress_c_xsync', False)}")
        # Same rule as cursor_cmp: passive callback updates only its own scrollbar.
        self._set_c_hscrollbars_from_main()
        return

    def _is_grid_overlay_enabled(self) -> bool:
        try:
            return bool(getattr(self, "grid_overlay_var", None) and self.grid_overlay_var.get())
        except Exception:
            return False

    def _gridify_parts(self, parts: list[str]) -> list[str]:
        if not self._is_grid_overlay_enabled():
            return parts
        # Keep tab layout unchanged; prepend a visual splitter in each cell.
        return [f"|{p}" for p in parts]

    def _toggle_grid_overlay(self):
        try:
            self._invalidate_render_cache()
            # pair_text_a/b/base cache formatted line strings; must be cleared so
            # _build_row_and_diff_pair re-runs with the new grid-on/off separator.
            self.pair_text_a = {}
            self.pair_text_b = {}
            self.pair_text_base = {}
            # Rescan widths to avoid stale narrow columns when toggling grid mode.
            self.refresh(row_only=None, rescan=True)
            self._update_cursor_lines()
        except Exception:
            pass

    def _yscroll_all(self, first, last):
        for sb in (self.vsb_left, self.vsb_a, self.vsb_m, self.vsb_b):
            try:
                sb.set(first, last)
            except Exception:
                pass
        try:
            self._schedule_diff_maps()
        except Exception:
            pass

    def _yscroll_left(self, first, last):
        if self._syncing:
            return
        self._syncing = True
        try:
            self.left_ln.yview_moveto(first)
            if self._is_three_way_enabled():
                self.base.yview_moveto(first)
                self.base_ln.yview_moveto(first)
            self.right.yview_moveto(first)
            self.right_ln.yview_moveto(first)
            self._yscroll_all(first, last)
        finally:
            self._syncing = False
        self._maybe_load_more_rows(last)

    def _yscroll_mid(self, first, last):
        if self._syncing:
            return
        self._syncing = True
        try:
            self.left.yview_moveto(first)
            self.left_ln.yview_moveto(first)
            self.right.yview_moveto(first)
            self.right_ln.yview_moveto(first)
            self.base_ln.yview_moveto(first)
            self._yscroll_all(first, last)
        finally:
            self._syncing = False
        self._maybe_load_more_rows(last)

    def _yscroll_right(self, first, last):
        if self._syncing:
            return
        self._syncing = True
        try:
            if self._is_three_way_enabled():
                self.base.yview_moveto(first)
                self.base_ln.yview_moveto(first)
            self.left.yview_moveto(first)
            self.left_ln.yview_moveto(first)
            self.right_ln.yview_moveto(first)
            self._yscroll_all(first, last)
        finally:
            self._syncing = False
        self._maybe_load_more_rows(last)

    def _yview_both(self, *args):
        self._syncing = True
        try:
            self.left.yview(*args)
            self.left_ln.yview(*args)
            if self._is_three_way_enabled():
                self.base.yview(*args)
                self.base_ln.yview(*args)
            self.right.yview(*args)
            self.right_ln.yview(*args)
            try:
                first, last = self.left.yview()
                self._yscroll_all(first, last)
            except Exception:
                pass
        finally:
            self._syncing = False
        try:
            _first, last = self.left.yview()
            self._maybe_load_more_rows(last)
        except Exception:
            pass

    def _on_mousewheel(self, event):
        if getattr(event, "num", None) == 4:
            delta = 120
        elif getattr(event, "num", None) == 5:
            delta = -120
        else:
            delta = event.delta
        steps = int(-1 * (delta / 120))
        self._yview_both("scroll", steps, "units")
        return "break"

    def _on_vdiff_map_click(self, event):
        try:
            h = max(1, self.vdiff_map.winfo_height())
            frac = min(1.0, max(0.0, float(event.y) / float(h)))
            total_pairs = len(self.row_pairs) if getattr(self, "row_pairs", None) else 0
            if total_pairs > 0 and self.display_rows:
                target_pair = min(total_pairs - 1, max(0, int(frac * total_pairs)))
                pos = bisect.bisect_left(self.display_rows, target_pair)
                if pos >= len(self.display_rows):
                    pos = len(self.display_rows) - 1
                elif pos > 0:
                    prev_pair = self.display_rows[pos - 1]
                    next_pair = self.display_rows[pos]
                    if abs(prev_pair - target_pair) <= abs(next_pair - target_pair):
                        pos -= 1
                if pos >= 0:
                    target_frac = float(pos) / float(max(1, len(self.display_rows)))
                    self._yview_both("moveto", target_frac)
                    return
            self._yview_both("moveto", frac)
        except Exception:
            pass

    def _visible_pair_span(self):
        if not self.display_rows:
            return None
        top_line = 1
        bottom_line = len(self.display_rows)
        try:
            top_line = int(str(self.left.index("@0,0")).split(".")[0])
        except Exception:
            top_line = 1
        try:
            bottom_y = max(0, int(self.left.winfo_height()) - 1)
            bottom_line = int(str(self.left.index(f"@0,{bottom_y}")).split(".")[0])
        except Exception:
            bottom_line = len(self.display_rows)
        top_line = max(1, min(top_line, len(self.display_rows)))
        bottom_line = max(top_line, min(bottom_line, len(self.display_rows)))
        start_pair = self.display_rows[top_line - 1]
        end_pair = self.display_rows[bottom_line - 1]
        if end_pair < start_pair:
            start_pair, end_pair = end_pair, start_pair
        return start_pair, min(len(self.row_pairs), end_pair + 1)

    def _on_hdiff_map_click(self, event, pane: str):
        try:
            canvas = self.hdiff_left if pane == "left" else (self.hdiff_mid if pane == "mid" else self.hdiff_right)
            w = max(1, canvas.winfo_width())
            frac = min(1.0, max(0.0, float(event.x) / float(w)))
            logical_count = max(1, self._logical_slot_count())
            logical_col = min(logical_count, max(1, int(frac * logical_count) + 1))
            source_side = "A" if pane == "left" else ("BASE" if pane == "mid" else "B")
            self._select_column_block_by_logical_col(logical_col, source_side)
            self._sync_main_x_to_frac(frac)
            self._sync_c_x_to_frac(frac)
        except Exception:
            pass

    def _compute_diff_map_data(self):
        """Return (total_pairs, diff_rows, diff_cols) cached by data version.

        The expensive O(N) scan over all pairs (``_pair_has_visual_diff``) only
        runs when the underlying data changed (``_data_version`` bump), so plain
        scrolling no longer pays for it on every frame.
        """
        ver = self._data_version
        cached = getattr(self, "_diff_map_cache", None)
        if cached is not None and getattr(self, "_diff_map_cache_version", None) == ver:
            return cached
        total_pairs = len(self.row_pairs) if getattr(self, "row_pairs", None) else 0
        diff_rows = sorted(
            int(pidx)
            for pidx in range(total_pairs)
            if self._pair_has_visual_diff(pidx)
        )
        diff_cols = set()
        for cols in (self.pair_diff_cols or {}).values():
            if cols:
                diff_cols.update(c for c in cols if c > 0)
        try:
            diff_cols.update(self._active_column_comparison_cache().structural_diff_cols)
            diff_cols.update(self._active_column_comparison_cache().unresolved_cols)
        except Exception:
            pass
        data = (total_pairs, diff_rows, sorted(diff_cols))
        self._diff_map_cache = data
        self._diff_map_cache_version = ver
        return data

    def _install_exact_diff_map_cache(self, diff_rows):
        """Install worker-prepared exact marker data without an O(N) Tk scan."""
        diff_cols = set()
        for cols in (self.pair_diff_cols or {}).values():
            diff_cols.update(int(col) for col in cols if int(col) > 0)
        try:
            cache = self._active_column_comparison_cache()
            diff_cols.update(int(col) for col in cache.structural_diff_cols)
            diff_cols.update(int(col) for col in cache.unresolved_cols)
        except Exception:
            pass
        self._diff_map_cache = (
            len(self.row_pairs),
            sorted({int(idx) for idx in (diff_rows or [])}),
            sorted(diff_cols),
        )
        self._diff_map_cache_version = self._data_version

    def _redraw_diff_markers(self):
        """Redraw the data-dependent diff markers (tagged ``dmark``)."""
        try:
            total_pairs, diff_rows, diff_cols = self._compute_diff_map_data()
        except Exception:
            return
        # Vertical diff map (by logical pair index across the full sheet)
        try:
            self.vdiff_map.delete("dmark")
            h = max(1, self.vdiff_map.winfo_height())
            w = max(1, self.vdiff_map.winfo_width())
            n = max(1, total_pairs)
            diff_count = len(diff_rows)
            # Dynamic marker height:
            # - fewer diffs -> thicker marker for visibility
            # - many diffs -> thinner marker to reduce overlap
            marker_min_h = max(2, min(12, int(h / max(1, diff_count)))) if diff_count > 0 else 2

            # Draw contiguous diff blocks as filled segments for better discoverability.
            i = 0
            while i < diff_count:
                start_pair = diff_rows[i]
                end_pair = start_pair
                while i + 1 < diff_count and diff_rows[i + 1] == end_pair + 1:
                    i += 1
                    end_pair = diff_rows[i]
                y1 = int((start_pair / n) * h)
                y2 = int(((end_pair + 1) / n) * h)
                if y2 - y1 < marker_min_h:
                    y2 = min(h, y1 + marker_min_h)
                self.vdiff_map.create_rectangle(0, y1, w, y2, outline="", fill="#ff2d2d", tags="dmark")
                i += 1
            self.vdiff_map.tag_raise("vpbox")
        except Exception:
            pass

        # Horizontal diff maps (under each pane scrollbar; by diff columns)
        try:
            max_col = self._logical_slot_count()
            canvases = [self.hdiff_left, self.hdiff_right]
            if self._is_three_way_enabled():
                canvases.insert(1, self.hdiff_mid)
            for canvas in canvases:
                canvas.delete("dmark")
                cw = max(1, canvas.winfo_width())
                ch = max(1, canvas.winfo_height())
                if diff_cols:
                    marker_min_w = max(2, min(14, int(cw / max(1, len(diff_cols)))))
                    sorted_cols = sorted(diff_cols)
                    seg_start = sorted_cols[0]
                    seg_end = sorted_cols[0]
                    for c in sorted_cols[1:]:
                        if c == seg_end + 1:
                            seg_end = c
                        else:
                            x1 = int(((seg_start - 1) / max_col) * cw)
                            x2 = int((seg_end / max_col) * cw)
                            if x2 - x1 < marker_min_w:
                                x2 = min(cw, x1 + marker_min_w)
                            canvas.create_rectangle(x1, 0, x2, ch, outline="", fill="#c46a00", tags="dmark")
                            seg_start = c
                            seg_end = c
                    x1 = int(((seg_start - 1) / max_col) * cw)
                    x2 = int((seg_end / max_col) * cw)
                    if x2 - x1 < marker_min_w:
                        x2 = min(cw, x1 + marker_min_w)
                    canvas.create_rectangle(x1, 0, x2, ch, outline="", fill="#c46a00", tags="dmark")
                canvas.tag_raise("vpbox")
        except Exception:
            pass

    def _redraw_diff_viewport(self):
        """Redraw only the viewport indicator boxes (tagged ``vpbox``, O(1))."""
        # Vertical viewport box
        try:
            total_pairs = len(self.row_pairs) if getattr(self, "row_pairs", None) else 0
            n = max(1, total_pairs)
            self.vdiff_map.delete("vpbox")
            h = max(1, self.vdiff_map.winfo_height())
            w = max(1, self.vdiff_map.winfo_width())
            span = self._visible_pair_span()
            if span is not None:
                start_pair, end_pair = span
                y1 = int((start_pair / n) * h)
                y2 = max(y1 + 2, int((end_pair / n) * h))
                self.vdiff_map.create_rectangle(0, y1, w, y2, outline="#1e78ff", tags="vpbox")
        except Exception:
            pass

        # Horizontal viewport boxes
        try:
            canvases = [self.hdiff_left, self.hdiff_right]
            if self._is_three_way_enabled():
                canvases.insert(1, self.hdiff_mid)
            lf, ll = self.left.xview()
            for canvas in canvases:
                canvas.delete("vpbox")
                cw = max(1, canvas.winfo_width())
                ch = max(1, canvas.winfo_height())
                canvas.create_rectangle(int(lf * cw), 0, max(int(ll * cw), int(lf * cw) + 2), ch, outline="#1e78ff", tags="vpbox")
        except Exception:
            pass

    def _update_diff_maps(self):
        """Full diff-map redraw (markers + viewport). For data-change callers."""
        self._redraw_diff_markers()
        self._redraw_diff_viewport()

    def _run_diff_markers_debounced(self):
        self._diff_map_debounce_id = None
        try:
            if not self.frame.winfo_exists():
                return
        except Exception:
            return
        self._redraw_diff_markers()

    def _schedule_diff_maps(self):
        """Scroll-driven diff-map update.

        Redraws the cheap viewport box immediately for responsive feedback and
        debounces the (cached) marker redraw to coalesce rapid scroll frames.
        """
        self._redraw_diff_viewport()
        try:
            self._update_diff_block_indicator()
        except Exception:
            pass
        aid = getattr(self, "_diff_map_debounce_id", None)
        if aid is not None:
            try:
                self.frame.after_cancel(aid)
            except Exception:
                pass
        delay = int(getattr(self, "_diff_map_debounce_ms", 40) or 0)
        if delay <= 0:
            self._redraw_diff_markers()
            return
        try:
            self._diff_map_debounce_id = self.frame.after(delay, self._run_diff_markers_debounced)
        except Exception:
            self._diff_map_debounce_id = None
            self._redraw_diff_markers()

    # ---------- Selection + toolbar buttons ----------
    def _widget_line(self, w: tk.Text):
        try:
            idx = w.index("@%d,%d" % (w.winfo_pointerx() - w.winfo_rootx(), w.winfo_pointery() - w.winfo_rooty()))
        except Exception:
            idx = w.index("insert")
        return int(str(idx).split(".")[0])

    def _pair_idx_for_line(self, line: int) -> int | None:
        if not (1 <= line <= len(self.display_rows)):
            return None
        return self.display_rows[line - 1]

    def _pair_for_line(self, line: int):
        idx = self._pair_idx_for_line(line)
        if idx is None or idx >= len(self.row_pairs):
            return None
        return self.row_pairs[idx]

    def _side_for_widget(self, w: tk.Text) -> str:
        if w is self.left:
            return "A"
        if w is self.base:
            return "BASE"
        return "B"

    def _col_from_char(self, char_pos: int) -> int | None:
        """Resolve display column index by character offset in a rendered row line."""
        try:
            ch = int(char_pos)
        except Exception:
            return None
        spans = self._spans_for_line()
        for c, (s, e) in spans.items():
            if s <= ch < e:
                return c
        return None

    def _set_main_selected_cell(self, line: int | None, col: int | None):
        try:
            ln = int(line) if line is not None else None
            cc = int(col) if col is not None else None
        except Exception:
            ln = None
            cc = None
        if ln is None or cc is None or ln < 1 or cc < 1:
            self._main_sel_line = None
            self._main_sel_col = None
            return
        self._main_sel_line = ln
        self._main_sel_col = cc

    def has_explicit_cell_selection(self) -> bool:
        try:
            if self._main_sel_line is not None and self._main_sel_col is not None:
                return True
            if self._cursor_cmp_sel_line is not None and self._cursor_cmp_sel_col is not None:
                return True
        except Exception:
            return False
        return False

    def _clear_selected_line_highlight(self):
        prev = self._last_selected_line
        if prev is None:
            return
        try:
            for t in (self.left, self.base, self.right):
                t.tag_remove("selrow", f"{prev}.0", f"{prev}.end")
        except Exception:
            pass
        self._last_selected_line = None

    def clear_explicit_cell_selection(self):
        self._set_main_selected_cell(None, None)
        self._cursor_cmp_sel_col = None
        self._cursor_cmp_sel_line = None
        self.selected_pair_idx = None
        self.selected_excel_row = None
        self.selected_excel_row_a = None
        self.selected_excel_row_b = None
        self._clear_selected_line_highlight()

    def _clear_selection_visuals(self):
        try:
            for t in (self.left, self.base, self.right):
                t.tag_remove("selrow", "1.0", "end")
                t.tag_remove("selcell", "1.0", "end")
        except Exception:
            pass
        try:
            self.cursor_cmp.tag_remove("cselcell", "1.0", "end")
        except Exception:
            pass
        self._last_selected_line = None
        self._applied_main_sel_line = None
        self._applied_main_sel_col = None

    def _snapshot_explicit_selection_state(self):
        if not self.has_explicit_cell_selection():
            return None
        return {
            "pair_idx": self.selected_pair_idx,
            "row_a": self.selected_excel_row_a,
            "row_b": self.selected_excel_row_b,
            "main_col": self._main_sel_col,
            "cursor_cmp_sel_line": self._cursor_cmp_sel_line,
            "cursor_cmp_sel_col": self._cursor_cmp_sel_col,
        }

    def _pair_idx_from_selection_snapshot(self, snapshot) -> int | None:
        if not snapshot:
            return None
        try:
            row_a = snapshot.get("row_a")
            if row_a is not None:
                pair_idx = self.row_a_to_pair_idx.get(int(row_a))
                pair_idx = self._normalize_pair_idx(pair_idx)
                if pair_idx is not None:
                    return pair_idx
        except Exception:
            pass
        try:
            row_b = snapshot.get("row_b")
            if row_b is not None:
                pair_idx = self.row_b_to_pair_idx.get(int(row_b))
                pair_idx = self._normalize_pair_idx(pair_idx)
                if pair_idx is not None:
                    return pair_idx
        except Exception:
            pass
        return self._normalize_pair_idx(snapshot.get("pair_idx"))

    def _restore_explicit_selection_state(self, snapshot) -> bool:
        pair_idx = self._pair_idx_from_selection_snapshot(snapshot)
        if pair_idx is None or pair_idx not in self.row_to_line:
            return False
        try:
            line = int(self.row_to_line[pair_idx])
        except Exception:
            return False
        try:
            self._highlight_selected_line(line)
            self.selected_pair_idx = int(pair_idx)
            pair = self._pair_for_line(line)
            self.selected_excel_row_a = self._row_for_side(pair, "A")
            self.selected_excel_row_b = self._row_for_side(pair, "B")
            self.selected_excel_row = self.selected_excel_row_a or self.selected_excel_row_b
            main_col = snapshot.get("main_col")
            self._set_main_selected_cell(line, main_col)
            cursor_col = snapshot.get("cursor_cmp_sel_col")
            cursor_line = snapshot.get("cursor_cmp_sel_line")
            self._cursor_cmp_sel_col = int(cursor_col) if cursor_col is not None else None
            self._cursor_cmp_sel_line = int(cursor_line) if cursor_line is not None else None
            self._last_cursor_cmp_pair_idx = int(pair_idx)
            return True
        except Exception:
            return False

    def _clear_hover_state(self, *, clear_panel: bool = False):
        self.hover_pair_idx = None
        self.hover_col_idx = None
        self.hover_side = None
        self._last_cursor_cmp_pair_idx = None
        self._hide_hover_popup()
        if clear_panel and (not self._hover_compare_is_pinned()):
            self._clear_hover_compare_panel()
        self._cell_tip_key = None

    def _normalize_pair_idx(self, pair_idx) -> int | None:
        try:
            if pair_idx is None:
                return None
            pair_idx = int(pair_idx)
            if pair_idx < 0 or pair_idx >= len(self.row_pairs):
                return None
            return pair_idx
        except Exception:
            return None

    def resolved_pair_idx_for_c_area(self) -> int | None:
        candidates = []
        if self.has_explicit_cell_selection():
            candidates.append(self.selected_pair_idx)
        candidates.append(self.hover_pair_idx)
        candidates.append(self.selected_pair_idx)
        candidates.append(getattr(self, "_last_cursor_cmp_pair_idx", None))
        try:
            line_guess = int(str(self.left.index("insert")).split(".")[0])
        except Exception:
            line_guess = None
        if line_guess is not None:
            candidates.append(self._pair_idx_for_line(line_guess))
        for pair_idx in candidates:
            norm = self._normalize_pair_idx(pair_idx)
            if norm is not None:
                return norm
        return None

    def update_hover_driven_panels(
        self,
        pair_idx: int | None,
        col_idx: int | None,
        side: str,
        *,
        force_panel: bool = True,
        popup_force_show: bool = False,
        x_root: int | None = None,
        y_root: int | None = None,
        refresh_c_area: bool = True,
    ):
        pair_idx = self._normalize_pair_idx(pair_idx)
        try:
            col_idx = int(col_idx) if col_idx is not None else None
        except Exception:
            col_idx = None
        self.hover_pair_idx = pair_idx
        self.hover_col_idx = col_idx
        self.hover_side = str(side or "").upper() if side is not None else None

        if pair_idx is None or col_idx is None or col_idx <= 0:
            self._hide_cell_tooltip(clear_panel=False)
            if refresh_c_area and not self.has_explicit_cell_selection():
                self._update_cursor_lines()
            return

        if refresh_c_area and not self.has_explicit_cell_selection():
            self._update_cursor_lines()

        panel_payload = self._cmp_tooltip_payload_by_pair_col(
            pair_idx,
            col_idx,
            force_show=bool(popup_force_show),
            force_panel=bool(force_panel),
        )
        if panel_payload:
            panel_text, panel_key = panel_payload
            self._set_hover_compare_panel(panel_text, panel_key)
        popup_payload = self._cmp_tooltip_payload_by_pair_col(pair_idx, col_idx, force_show=bool(popup_force_show))
        if popup_payload and x_root is not None and y_root is not None:
            tip_text, key = popup_payload
            self._show_cell_tooltip(tip_text, int(x_root), int(y_root), key)
        else:
            self._hide_cell_tooltip(clear_panel=False)

    def _apply_main_selected_cell_highlight(self):
        # Remove previously applied selcell highlight in O(1).
        prev_line = self._applied_main_sel_line
        prev_col = self._applied_main_sel_col
        if prev_line and prev_col:
            try:
                spans_prev = self._spans_for_line()
                if prev_col in spans_prev:
                    s0, e0 = spans_prev[prev_col]
                    for t in (self.left, self.base, self.right):
                        t.tag_remove("selcell", f"{prev_line}.{s0}", f"{prev_line}.{e0}")
            except Exception:
                pass
        self._applied_main_sel_line = None
        self._applied_main_sel_col = None

        line = self._main_sel_line
        col = self._main_sel_col
        if not line or not col:
            return
        if not (1 <= int(line) <= max(1, len(self.display_rows))):
            return

        try:
            spans = self._spans_for_line()
            if col not in spans:
                return
            s, e = spans[col]
            pair_idx = self.display_rows[int(line) - 1]
            pair = self._pair_for_line(int(line))
            ra = self._row_for_side(pair, "A")
            rb = self._row_for_side(pair, "B")
            base_r = self._base_row_for_pair(pair_idx, pair) if self._is_three_way_enabled() else None
            if ra is not None and self._slot_exists_on_side("A", col):
                self.left.tag_add("selcell", f"{line}.{s}", f"{line}.{e}")
            if (
                self._is_three_way_enabled()
                and base_r is not None
                and self._slot_exists_on_side("BASE", col)
            ):
                self.base.tag_add("selcell", f"{line}.{s}", f"{line}.{e}")
            if rb is not None and self._slot_exists_on_side("B", col):
                self.right.tag_add("selcell", f"{line}.{s}", f"{line}.{e}")
            self._applied_main_sel_line = int(line)
            self._applied_main_sel_col = int(col)
        except Exception:
            pass

    @staticmethod
    def _row_for_side(pair, side: str) -> int | None:
        if not pair:
            return None
        if side == "A":
            return pair[0]
        if side == "BASE":
            # Base must map to its own aligned row identity (A-side index only).
            # Falling back to B causes duplicated base row numbers in gap regions.
            return pair[0]
        return pair[1]

    def _select_from_widget(self, w: tk.Text, event):
        # Set insert mark to the clicked position so follow-up actions can use it.
        x_before = 0.0
        try:
            x_before = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            x_before = 0.0
        try:
            idx = w.index(f"@{event.x},{event.y}")
            w.mark_set("insert", idx)
        except Exception:
            idx = None

        line = self._widget_line(w)
        col = 0
        try:
            if idx is not None:
                col = int(str(idx).split(".")[1])
        except Exception:
            col = 0

        # Resolve clicked character position to display column index.
        hit_col = self._col_from_char(col)
        self._set_main_selected_cell(line, hit_col)

        # Mirror main-pane cell selection into C区 selected-cell hint.
        # 2-way: A->line1, B->line2
        # 3-way: BASE->line1, A->line2, B->line3
        c_line = None
        if hit_col is not None and int(hit_col) > 0:
            side = self._side_for_widget(w)
            if self._is_three_way_enabled():
                if side == "BASE":
                    c_line = 1
                elif side == "A":
                    c_line = 2
                else:
                    c_line = 3
            else:
                c_line = 1 if side in ("A", "BASE") else 2
        self._cursor_cmp_sel_col = int(hit_col) if c_line is not None else None
        self._cursor_cmp_sel_line = int(c_line) if c_line is not None else None

        # Keep both panes aligned for the cursor compare block:
        # when user clicks either side, keep row+column insert marks consistent.
        for other in (self.left, self.base, self.right):
            if other is w:
                continue
            try:
                other.mark_set("insert", f"{line}.{max(0, col)}")
            except Exception:
                pass

        self._highlight_selected_line(line)
        pair = self._pair_for_line(line)
        self.selected_pair_idx = self._pair_idx_for_line(line)
        self.hover_pair_idx = self._normalize_pair_idx(self.selected_pair_idx)
        self.hover_col_idx = int(hit_col) if hit_col is not None else None
        self.hover_side = self._side_for_widget(w)
        self.selected_excel_row_a = self._row_for_side(pair, "A")
        self.selected_excel_row_b = self._row_for_side(pair, "B")
        self.selected_excel_row = self.selected_excel_row_a or self.selected_excel_row_b
        # No button state updates (performance): buttons are always visible and logic no-ops when no diff.

        self._update_cursor_lines()
        self._update_diff_nav_state()
        try:
            self.app._refresh_command_widgets()
        except Exception:
            pass

        try:
            x_after = float((self.left.xview() or (0.0, 1.0))[0])
            _dlog(f"select_from_widget xview before={x_before:.6f} after={x_after:.6f} line={line} col={col}")
        except Exception:
            pass

    def _select_line(self, line: int):
        if line < 1:
            return
        for w in (self.left, self.base, self.right):
            try:
                w.mark_set("insert", f"{line}.0")
            except Exception:
                pass
        self._highlight_selected_line(line)
        pair = self._pair_for_line(line)
        self.selected_pair_idx = self._pair_idx_for_line(line)
        self.hover_pair_idx = self._normalize_pair_idx(self.selected_pair_idx)
        self.hover_col_idx = None
        self.hover_side = None
        self.selected_excel_row_a = self._row_for_side(pair, "A")
        self.selected_excel_row_b = self._row_for_side(pair, "B")
        self.selected_excel_row = self.selected_excel_row_a or self.selected_excel_row_b
        self._set_main_selected_cell(line, None)
        self._update_cursor_lines()
        self._update_diff_nav_state()
        try:
            self.app._refresh_command_widgets()
        except Exception:
            pass

    def _on_row_header_click(self, w: tk.Text, event, direction: str):
        try:
            idx = w.index(f"@{event.x},{event.y}")
            line = int(str(idx).split(".")[0])
        except Exception:
            line = 1
        hover_line = (
            getattr(self, "_hover_ln_line_left", None)
            if w is self.left_ln
            else (
                getattr(self, "_hover_ln_line_mid", None)
                if w is self.base_ln
                else getattr(self, "_hover_ln_line_right", None)
            )
        )
        pair_idx = self._pair_idx_for_line(line)
        # Row-number/arrow regions are browsing surfaces.  They only select a
        # row; all row writes go through the explicit toolbar action.
        arrow_clicked = False
        self._clear_row_header_hover(w)
        self._select_line(line)
        try:
            self.info.configure(
                text="已选择该行；请使用上方带方向的整行/区域/全局按钮执行写入。"
            )
        except Exception:
            pass
        return "break"

    def _row_header_action_available(
        self,
        w: tk.Text,
        line: int,
        direction: str,
    ) -> bool:
        if not (1 <= int(line) <= len(self.display_rows)):
            return False
        # In three-way mode Mine is the editable destination. Its row header is
        # selection-only; Base/Theirs headers are the explicit source arrows.
        if self._is_three_way_enabled() and w is self.left_ln:
            return False
        pair = self._pair_for_line(int(line))
        pair_idx = self._pair_idx_for_line(int(line))
        if pair_idx is None:
            return False
        source_side = self._row_header_side(w)
        if self._row_for_side(pair, source_side) is None:
            return False
        if (
            self._is_three_way_enabled()
            and direction == "BASE2A"
            and w is self.base_ln
        ):
            cols = set(self.pair_base_diff_cols.get(pair_idx, set()))
        else:
            cols = set(self.pair_diff_cols.get(pair_idx, set()))
        return bool(cols)

    def _row_header_side(self, w: tk.Text) -> str:
        if w is self.left_ln:
            return "A"
        if w is self.base_ln:
            return "BASE"
        return "B"

    def _set_row_header_text(self, w: tk.Text, line: int, txt: str):
        try:
            # Preserve existing row-header visual tags (e.g. diffrow background)
            # when replacing text for hover arrow rendering.
            keep_tags = []
            try:
                keep_tags = list(w.tag_names(f"{line}.0"))
            except Exception:
                keep_tags = []

            w.configure(state="normal")
            w.delete(f"{line}.0", f"{line}.end")
            w.insert(f"{line}.0", txt)
            for tag in keep_tags:
                if tag == "blockmarker":
                    continue
                try:
                    w.tag_add(tag, f"{line}.0", f"{line}.end")
                except Exception:
                    pass
            if w is self.left_ln:
                pair_idx = self._pair_idx_for_line(line)
                block = self._full_diff_block_for_pair(pair_idx)
                marker_width = self._diff_block_marker_width()
                if block is not None and block.start_pair_idx == pair_idx and marker_width > 0:
                    w.tag_add("blockmarker", f"{line}.0", f"{line}.{marker_width}")
            w.configure(state="disabled")
        except Exception:
            pass

    def _clear_row_header_hover(self, w: tk.Text):
        line = getattr(self, "_hover_ln_line_left", None) if w is self.left_ln else (
            getattr(self, "_hover_ln_line_mid", None) if w is self.base_ln else getattr(self, "_hover_ln_line_right", None)
        )
        if line is None:
            return
        pair_idx = self._pair_idx_for_line(line)
        if pair_idx is None:
            return
        rn_w = self._sync_row_header_width_widgets()
        side = self._row_header_side(w)
        txt = self._format_main_row_header(pair_idx, side, rn_w)
        self._set_row_header_text(w, line, txt)
        try:
            w.configure(cursor="arrow")
        except Exception:
            pass
        if w is self.left_ln:
            self._hover_ln_line_left = None
        elif w is self.base_ln:
            self._hover_ln_line_mid = None
        else:
            self._hover_ln_line_right = None

    def _on_row_header_hover(self, w: tk.Text, event, direction: str):
        try:
            idx = w.index(f"@{event.x},{event.y}")
            line = int(str(idx).split(".")[0])
        except Exception:
            self._clear_row_header_hover(w)
            return
        if not (1 <= line <= len(self.display_rows)):
            self._clear_row_header_hover(w)
            return

        pair_idx = self._pair_idx_for_line(line)
        side = self._row_header_side(w)
        if not self._row_header_action_available(w, line, direction):
            self._clear_row_header_hover(w)
            try:
                w.configure(cursor="arrow")
            except Exception:
                pass
            return
        hover_line = getattr(self, "_hover_ln_line_left", None) if w is self.left_ln else (
            getattr(self, "_hover_ln_line_mid", None) if w is self.base_ln else getattr(self, "_hover_ln_line_right", None)
        )
        if hover_line == line:
            return
        self._clear_row_header_hover(w)
        rn_w = self._sync_row_header_width_widgets()
        arrow = _ROW_ARROW_RIGHT if direction in ("A2B", "MINE2A", "BASE2A") else _ROW_ARROW_LEFT
        self._set_row_header_text(w, line, self._format_main_row_header(pair_idx, side, rn_w, arrow=arrow))
        try:
            w.configure(cursor="hand2")
        except Exception:
            pass
        if w is self.left_ln:
            self._hover_ln_line_left = line
        elif w is self.base_ln:
            self._hover_ln_line_mid = line
        else:
            self._hover_ln_line_right = line

    def _hide_hover_popup(self):
        tip_lbl = getattr(self, "_cell_tip_label", None)
        if tip_lbl is not None:
            try:
                tip_lbl.place_forget()
            except Exception:
                pass
        tip = getattr(self, "_cell_tip_win", None)
        if tip is not None:
            try:
                tip.destroy()
            except Exception:
                pass
        self._cell_tip_win = None

    def _clear_hover_compare_panel(self):
        try:
            if hasattr(self, "hover_cmp_title_var"):
                self.hover_cmp_title_var.set("悬停完整对比 | 当前单元格：-")
            if hasattr(self, "hover_cmp_text"):
                self.hover_cmp_text.configure(state="normal")
                self.hover_cmp_text.delete("1.0", "end")
                self.hover_cmp_text.configure(state="disabled")
        except Exception:
            pass
        self._last_hover_compare_key = None

    def _hover_compare_is_pinned(self) -> bool:
        try:
            return bool(getattr(self, "hover_cmp_pin_var", None) and self.hover_cmp_pin_var.get())
        except Exception:
            return False

    def _on_hover_compare_pin_toggle(self):
        try:
            if self._hover_compare_is_pinned():
                if getattr(self, "_last_hover_compare_key", None) is None:
                    self.hover_cmp_title_var.set(
                        "悬停完整对比 | 当前单元格：- | 已固定（等待悬停内容）"
                    )
                elif hasattr(self, "hover_cmp_title_var"):
                    t = str(self.hover_cmp_title_var.get() or "")
                    if "已固定" not in t:
                        self.hover_cmp_title_var.set(f"{t} | 已固定")
            else:
                if hasattr(self, "hover_cmp_title_var"):
                    t = str(self.hover_cmp_title_var.get() or "")
                    self.hover_cmp_title_var.set(t.replace(" | 已固定", ""))
        except Exception:
            pass

    def _on_hover_compare_f4_toggle(self, event=None):
        # Quick keyboard toggle for pin/unpin while reviewing long content.
        # Multiple SheetView instances may register F4 on root; only the active
        # sheet view should consume the key event.
        try:
            nb = getattr(self.app, "nb", None)
            if nb is not None:
                tab_id = nb.select()
                if tab_id:
                    tab_text = str(nb.tab(tab_id, "text") or "")
                    if tab_text != str(self.sheet):
                        return None
        except Exception:
            pass
        try:
            cur = 1 if self._hover_compare_is_pinned() else 0
            self.hover_cmp_pin_var.set(0 if cur else 1)
            self._on_hover_compare_pin_toggle()
        except Exception:
            pass
        return "break"

    def _on_hover_compare_clear_click(self):
        self._hide_hover_popup()
        self._clear_hover_compare_panel()

    def _on_hover_cmp_mousewheel(self, event):
        # Keep default behavior unless Shift is held (then treat as horizontal scroll).
        try:
            if int(getattr(event, "state", 0)) & 0x1:
                return self._on_hover_cmp_shift_wheel(event)
        except Exception:
            pass
        return None

    def _on_hover_cmp_shift_wheel(self, event):
        try:
            delta = int(getattr(event, "delta", 0))
        except Exception:
            delta = 0
        step = 0
        if delta != 0:
            step = -1 if delta > 0 else 1
        else:
            num = getattr(event, "num", None)
            if num == 4:
                step = -1
            elif num == 5:
                step = 1
        if step != 0:
            try:
                self.hover_cmp_text.xview_scroll(step * 3, "units")
            except Exception:
                pass
        return "break"

    def _cancel_hover_compare_clear(self):
        aid = getattr(self, "_hover_clear_after_id", None)
        if aid is not None:
            try:
                self.root.after_cancel(aid)
            except Exception:
                pass
        self._hover_clear_after_id = None

    def _on_hover_compare_leave(self):
        self._hide_hover_popup()
        # Keep panel content visible for manual horizontal drag/inspection.
        self._cancel_hover_compare_clear()

    def _set_hover_compare_panel(self, text: str, key):
        if not text:
            return
        self._cancel_hover_compare_clear()
        if self._hover_compare_is_pinned() and getattr(self, "_last_hover_compare_key", None) is not None:
            return
        if getattr(self, "_last_hover_compare_key", None) == key:
            return
        col_text = "-"
        cell_text = "-"
        try:
            if isinstance(key, tuple) and len(key) >= 4 and int(key[3]) > 0:
                ci = int(key[3])
                col_text = f"{get_column_letter(ci)}({ci})"
                payload = (getattr(self, "_hover_payload_cache", {}) or {}).get(key) or {}
                sides = tuple(payload.get("sides") or ())
                rows = tuple(payload.get("rows") or ())
                preferred_row = None
                if "A" in sides:
                    a_idx = sides.index("A")
                    if a_idx < len(rows):
                        preferred_row = rows[a_idx]
                if preferred_row is None:
                    preferred_row = next((row for row in rows if row is not None), None)
                if preferred_row is not None:
                    cell_text = f"{_excel_column_display(ci)}{int(preferred_row)}"
                else:
                    cell_text = _excel_column_display(ci)
        except Exception:
            col_text = "-"
            cell_text = "-"
        try:
            if hasattr(self, "hover_cmp_title_var"):
                suffix = " | 已固定" if self._hover_compare_is_pinned() else ""
                self.hover_cmp_title_var.set(
                    f"悬停完整对比 | 当前单元格：{self.sheet}!{cell_text}"
                    f"（列 {col_text}）{suffix}"
                )
            self._render_hover_compare_panel(text, key)
        except Exception:
            pass
        self._last_hover_compare_key = key

    @staticmethod
    def _hover_diff_masks(values):
        """Mark non-equal chars for each source value via pairwise sequence compare."""
        vals = ["" if v is None else str(v) for v in (values or ())]
        masks = [set() for _ in vals]
        if len(vals) <= 1:
            return masks
        for i in range(len(vals)):
            for j in range(i + 1, len(vals)):
                a = vals[i]
                b = vals[j]
                sm = difflib.SequenceMatcher(None, a, b)
                for tag, a1, a2, b1, b2 in sm.get_opcodes():
                    if tag == "equal":
                        continue
                    masks[i].update(range(a1, a2))
                    masks[j].update(range(b1, b2))
        return masks

    @staticmethod
    def _side_tag_for_hover_line(side: str, has_base: bool) -> str:
        s = (side or "").upper()
        if s == "BASE":
            return "hover_side_base"
        if s == "A":
            return "hover_side_mine" if has_base else "hover_side_base"
        if s == "B":
            return "hover_side_theirs" if has_base else "hover_side_mine"
        return "hover_side_base"

    @staticmethod
    def _side_label_for_hover_line(side: str, has_base: bool) -> str:
        s = (side or "").upper()
        if s == "BASE":
            return "base"
        if s == "A":
            return "mine" if has_base else "base"
        if s == "B":
            return "theirs" if has_base else "mine"
        return "base"

    def _render_hover_compare_panel(self, text: str, key):
        if not hasattr(self, "hover_cmp_text"):
            return
        w = self.hover_cmp_text
        try:
            w.configure(state="normal")
            w.delete("1.0", "end")
            payload = (getattr(self, "_hover_payload_cache", {}) or {}).get(key)
            if not payload:
                w.insert("1.0", text)
                w.configure(state="disabled")
                return
            sides = list(payload.get("sides") or [])
            rows = list(payload.get("rows") or [])
            values = ["" if v is None else str(v) for v in (payload.get("values") or ())]
            has_base = any((str(s).upper() == "BASE") for s in sides)
            # 新增行对侧（row_no 为 None）用空串参与 diff 计算，
            # 避免 "<missing>" 字面量被当作内容误比较。
            diff_inputs = ["" if row_no is None else v for row_no, v in zip(rows, values)]
            masks = self._hover_diff_masks(diff_inputs)

            for i, (side, row_no, val) in enumerate(zip(sides, rows, values), start=1):
                row_label = "-" if row_no is None else str(row_no)
                side_label = self._side_label_for_hover_line(side, has_base)
                prefix = f"{side_label}[{row_label}]: "
                line_txt = f"{prefix}{val}"
                if i > 1:
                    w.insert("end", "\n")
                line_start = f"{i}.0"
                w.insert("end", line_txt)
                # 无数据侧（新增行对侧）：整行置灰，不显示字符级红色高亮。
                if row_no is None:
                    w.tag_add("hover_side_missing", line_start, f"{i}.end")
                    continue
                # Color the whole source line by provenance.
                side_tag = self._side_tag_for_hover_line(side, has_base)
                w.tag_add(side_tag, line_start, f"{i}.end")

                # Color changed chars in value body.
                mask = sorted(masks[i - 1]) if (i - 1) < len(masks) else []
                if mask:
                    seg_s = None
                    seg_e = None
                    for p in mask:
                        if p < 0 or p >= len(val):
                            continue
                        if seg_s is None:
                            seg_s = p
                            seg_e = p + 1
                            continue
                        if p == seg_e:
                            seg_e = p + 1
                            continue
                        b0 = len(prefix) + seg_s
                        b1 = len(prefix) + seg_e
                        w.tag_add("hover_diffchar", f"{i}.{b0}", f"{i}.{b1}")
                        seg_s = p
                        seg_e = p + 1
                    if seg_s is not None and seg_e is not None:
                        b0 = len(prefix) + seg_s
                        b1 = len(prefix) + seg_e
                        w.tag_add("hover_diffchar", f"{i}.{b0}", f"{i}.{b1}")
            w.configure(state="disabled")
        except Exception:
            try:
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", text)
                w.configure(state="disabled")
            except Exception:
                pass

    def _hide_cell_tooltip(self, clear_panel: bool = True):
        # Reset hover dedup so re-entering the same cell re-triggers a refresh.
        self._last_hover_target_key = None
        self._hide_hover_popup()
        if clear_panel:
            self._clear_hover_compare_panel()
        self._cell_tip_key = None

    def _schedule_hover_panels(self, pair_idx, target_col, side, *,
                               popup_force_show=False, x_root=None, y_root=None,
                               refresh_c_area=True):
        """Throttle hover-driven panel refreshes.

        - Dedup: skip work entirely when the hovered (pair, col, side) is unchanged.
        - Debounce: coalesce rapid cross-cell motion into a single refresh.
        """
        key = (pair_idx, target_col, str(side), bool(refresh_c_area))
        # Always remember the freshest request so the debounced call uses latest position.
        self._pending_hover_args = (
            pair_idx, target_col, side, bool(popup_force_show),
            x_root, y_root, bool(refresh_c_area),
        )
        if key == getattr(self, "_last_hover_target_key", None):
            return
        self._last_hover_target_key = key
        # Coalesce bursts of Motion events: run the heavy panel refresh once when
        # the event loop next goes idle, instead of on every pixel of movement.
        aid = getattr(self, "_hover_debounce_id", None)
        if aid is not None:
            try:
                self.frame.after_cancel(aid)
            except Exception:
                pass
        try:
            self._hover_debounce_id = self.frame.after_idle(self._run_pending_hover_panels)
        except Exception:
            self._hover_debounce_id = None
            self._run_pending_hover_panels()

    def _run_pending_hover_panels(self):
        self._hover_debounce_id = None
        args = getattr(self, "_pending_hover_args", None)
        if not args:
            return
        try:
            if not self.frame.winfo_exists():
                return
        except Exception:
            return
        pair_idx, target_col, side, popup_force_show, x_root, y_root, refresh_c_area = args
        self.update_hover_driven_panels(
            pair_idx,
            target_col,
            side,
            force_panel=True,
            popup_force_show=popup_force_show,
            x_root=x_root,
            y_root=y_root,
            refresh_c_area=refresh_c_area,
        )

    def _show_cell_tooltip(self, text: str, x_root: int, y_root: int, key):
        if not text:
            self._hide_cell_tooltip(clear_panel=False)
            return
        self._set_hover_compare_panel(text, key)
        self._cell_tip_key = key
        if not bool(getattr(self, "_enable_hover_popup", False)):
            return
        try:
            lbl = getattr(self, "_cell_tip_label", None)
            if lbl is None:
                lbl = tk.Label(
                    self.root,
                    justify="left",
                    relief="solid",
                    borderwidth=1,
                    bg="#fffbe6",
                    fg="#222",
                    font=("Consolas", 10),
                    anchor="w",
                )
                self._cell_tip_label = lbl
            lbl.configure(text=text)
            self._cell_tip_win = None

            rx = int(self.root.winfo_rootx())
            ry = int(self.root.winfo_rooty())
            rw = max(1, int(self.root.winfo_width()))
            rh = max(1, int(self.root.winfo_height()))
            x = int(x_root - rx + 16)
            y = int(y_root - ry + 20)
            self.root.update_idletasks()
            tw = max(1, int(lbl.winfo_reqwidth()))
            th = max(1, int(lbl.winfo_reqheight()))
            x = max(0, min(x, max(0, rw - tw - 4)))
            y = max(0, min(y, max(0, rh - th - 4)))
            lbl.place(x=x, y=y)
            lbl.lift()
        except Exception:
            try:
                tip = tk.Toplevel(self.root)
                tip.wm_overrideredirect(True)
                try:
                    tip.wm_attributes("-topmost", True)
                except Exception:
                    pass
                tip.wm_geometry(f"+{x_root + 14}+{y_root + 18}")
                lbl = tk.Label(tip, text=text, justify="left", relief="solid", borderwidth=1, bg="#fffbe6", fg="#222", font=("Consolas", 10))
                self._cell_tip_win = tip
                self._cell_tip_key = key
                lbl.pack(ipadx=4, ipady=2)
            except Exception:
                self._hide_cell_tooltip(clear_panel=False)

    def _cmp_tooltip_payload_by_pair_col(
        self,
        pair_idx: int,
        target_col: int,
        force_show: bool = False,
        force_panel: bool = False,
    ):
        try:
            if pair_idx is None or int(pair_idx) < 0 or int(pair_idx) >= len(self.row_pairs):
                return None
            target_col = int(target_col)
            if target_col <= 0:
                return None
        except Exception:
            return None

        pair = self.row_pairs[int(pair_idx)]
        is_three = self._is_three_way_enabled()
        sides = ["BASE", "A", "B"] if is_three else ["A", "B"]
        rows = []
        for side in sides:
            if side == "BASE" and is_three:
                rows.append(self._base_row_for_pair(int(pair_idx), pair))
            else:
                rows.append(self._row_for_side(pair, side))
        ws_edit_cache = {}

        values = []
        for side, row_no in zip(sides, rows):
            if row_no is None:
                values.append("<missing>")
                continue
            physical_col = self._physical_col_for_logical(side, target_col)
            if physical_col is None:
                reason = self._active_column_projection().structural_reason(side, target_col)
                values.append(f"<{_LOGICAL_COLUMN_PLACEHOLDER}: {reason}>")
                continue
            try:
                if side == "A":
                    ws_val = self.app.ws_a_val(self.sheet)
                elif side == "BASE":
                    ws_val = self.app.ws_base_val(self.sheet)
                else:
                    ws_val = self.app.ws_b_val(self.sheet)
                v_disp = ws_val.cell(row=row_no, column=physical_col).value
                # Keep tooltip value source aligned with row rendering:
                # when cached-values mode misses literals, rendering falls back to edit WB.
                if _USE_CACHED_VALUES_ONLY and v_disp is None:
                    ws_edit = ws_edit_cache.get(side)
                    if ws_edit is None:
                        try:
                            if side == "A":
                                ws_edit = self.app.ws_a_edit(self.sheet)
                            elif side == "BASE":
                                ws_edit = self.app.ws_base_edit(self.sheet)
                            else:
                                ws_edit = self.app.ws_b_edit(self.sheet)
                            ws_edit_cache[side] = ws_edit
                        except Exception:
                            ws_edit = None
                    if ws_edit is not None:
                        try:
                            v_edit = ws_edit.cell(row=row_no, column=physical_col).value
                            if v_edit is not None and not _formula_text(v_edit):
                                v_disp = v_edit
                        except Exception:
                            pass
                if v_disp is None:
                    v_str = ""
                else:
                    v_str = str(v_disp)
                    v_str = v_str.replace("\r\n", "⏎").replace("\r", "⏎").replace("\n", "⏎")
                values.append(v_str)
            except Exception:
                return None

        width = max(1, int(self.col_char_widths.get(target_col, 1)))
        # 新增行：只要有一侧 row_no 为 None（该侧无数据），面板必须显示
        need_tip = (
            bool(force_show)
            or any(row_no is None for row_no in rows)
            or any(self._physical_col_for_logical(side, target_col) is None for side in sides)
            or any((row_no is not None and len(v) > width) for row_no, v in zip(rows, values))
        )
        if not need_tip and not force_panel:
            return None

        lines = []
        for side, row_no, v in zip(sides, rows, values):
            row_label = "-" if row_no is None else str(row_no)
            side_label = self._side_label_for_hover_line(side, is_three)
            lines.append(f"{side_label}[{row_label}]: {v}")
        tip_text = "\n".join(lines)
        key = (self.sheet, "CMP", int(pair_idx), target_col, tuple(values))
        try:
            if not isinstance(getattr(self, "_hover_payload_cache", None), dict):
                self._hover_payload_cache = {}
            self._hover_payload_cache[key] = {
                "sides": tuple(sides),
                "rows": tuple(rows),
                "values": tuple(values),
            }
            # Keep cache bounded; only recent hover payloads are needed.
            if len(self._hover_payload_cache) > 128:
                for old_k in list(self._hover_payload_cache.keys())[:-64]:
                    self._hover_payload_cache.pop(old_k, None)
        except Exception:
            pass
        return tip_text, key

    def _should_force_hover_tip(self, target_col: int, rendered_fragment: str = "") -> bool:
        """Heuristics for truncated/likely-truncated cell hover in dense grid rendering."""
        try:
            frag = (rendered_fragment or "").rstrip()
            if frag.endswith("\u2026") or frag.endswith("..."):
                return True
        except Exception:
            pass
        try:
            # When a column has already hit the global display cap, rows near the
            # cap can still feel clipped in practice; force compare tooltip there.
            if int(self.col_char_widths.get(int(target_col), 0)) >= int(_COL_MAX_DISPLAY_WIDTH):
                return True
        except Exception:
            pass
        return False

    def _hit_col_from_char(self, char_no: int):
        """Map a text char position to column span; separator chars belong to the left column."""
        spans = self._spans_for_line()
        last_col = None
        last_span = None
        for c, (s, e) in spans.items():
            last_col = c
            last_span = (s, e)
            if s <= char_no < e:
                return c, s, e
            sep_end = e + _COL_SEP_LEN
            if e <= char_no < sep_end:
                return c, s, e
        if last_col is not None and last_span is not None and char_no >= last_span[1]:
            return last_col, last_span[0], last_span[1]
        return None, 0, 0

    def _on_cell_hover_tooltip(self, w: tk.Text, event, side: str):
        try:
            idx = w.index(f"@{event.x},{event.y}")
            line = int(idx.split(".")[0])
            col_char = int(idx.split(".")[1])
        except Exception:
            self._hide_cell_tooltip(clear_panel=False)
            return
        if not (1 <= line <= len(self.display_rows)):
            self._hide_cell_tooltip(clear_panel=False)
            return
        pair_idx = self._pair_idx_for_line(line)
        if pair_idx is None or pair_idx >= len(self.row_pairs):
            self._hide_cell_tooltip(clear_panel=False)
            return
        target_col, span_s, span_e = self._hit_col_from_char(col_char)
        if target_col is None:
            self._hide_cell_tooltip(clear_panel=False)
            return
        force_show = False
        try:
            line_text = w.get(f"{line}.0", f"{line}.end")
            frag = line_text[span_s:span_e]
            force_show = self._should_force_hover_tip(target_col, frag)
            try:
                tags_here = set(w.tag_names(f"{line}.{max(0, int(col_char))}"))
                if "diffcell" in tags_here:
                    force_show = True
            except Exception:
                pass
        except Exception:
            force_show = False
        self._schedule_hover_panels(
            pair_idx,
            target_col,
            side,
            popup_force_show=force_show,
            x_root=getattr(event, "x_root", None),
            y_root=getattr(event, "y_root", None),
            refresh_c_area=True,
        )

    def _active_pair_idx_for_c_area(self) -> int | None:
        return self.resolved_pair_idx_for_c_area()

    def _cursor_cmp_tooltip_payload(self, char_no: int, force_panel: bool = False):
        target_col, _s, _e = self._hit_col_from_char(char_no)
        if target_col is None:
            return None

        pair_idx = self._active_pair_idx_for_c_area()
        return self._cmp_tooltip_payload_by_pair_col(pair_idx, target_col, force_panel=force_panel)

    def _on_cursor_cmp_hover_tooltip(self, event):
        try:
            idx = self.cursor_cmp.index(f"@{event.x},{event.y}")
            idx_s = str(idx)
            line_no = int(idx_s.split(".")[0])
            char_no = int(idx_s.split(".")[1])
        except Exception:
            self._hide_cell_tooltip(clear_panel=False)
            return
        target_col, span_s, span_e = self._hit_col_from_char(char_no)
        if target_col is None:
            self._hide_cell_tooltip(clear_panel=False)
            return
        force_show = False
        try:
            line_text = self.cursor_cmp.get(f"{line_no}.0", f"{line_no}.end")
            frag = line_text[span_s:span_e]
            force_show = self._should_force_hover_tip(target_col, frag)
            try:
                tags_here = set(self.cursor_cmp.tag_names(f"{line_no}.{max(0, int(char_no))}"))
                if "diffcell" in tags_here:
                    force_show = True
            except Exception:
                pass
        except Exception:
            force_show = False
        pair_idx = self._active_pair_idx_for_c_area()
        self._schedule_hover_panels(
            pair_idx,
            target_col,
            "C",
            popup_force_show=force_show,
            x_root=getattr(event, "x_root", None),
            y_root=getattr(event, "y_root", None),
            refresh_c_area=False,
        )

    def _on_main_pane_right_click(self, w: tk.Text, event, side: str):
        self.clear_explicit_cell_selection()
        self._update_cursor_lines()
        self._update_diff_nav_state()
        self._on_cell_hover_tooltip(w, event, side)
        return "break"

    def _on_cursor_cmp_right_click(self, event):
        self.clear_explicit_cell_selection()
        self._update_cursor_lines()
        self._update_diff_nav_state()
        return "break"

    def _on_click_with_arrow(self, w: tk.Text, event, direction: str):
        # Keep horizontal position stable on click; Tk default Text binding may call see(insert).
        saved_x = 0.0
        try:
            saved_x = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            saved_x = 0.0

        try:
            self._click_trace_seq = int(getattr(self, "_click_trace_seq", 0)) + 1
        except Exception:
            self._click_trace_seq = 1
        seq = self._click_trace_seq
        self._trace_click_until = time.time() + 1.2
        self._log_click_trace_state(f"click_start#{seq}")

        # Select row/column first.
        self._select_from_widget(w, event)
        self._log_click_trace_state(f"after_select#{seq}")

        # Multi-stage guard: catch delayed xview writes from Tk/idle callbacks.
        try:
            self.left.after_idle(lambda sx=saved_x, st=f"idle#{seq}": self._post_click_x_guard(sx, st))
            self.left.after(30, lambda sx=saved_x, st=f"t30#{seq}": self._post_click_x_guard(sx, st))
            self.left.after(120, lambda sx=saved_x, st=f"t120#{seq}": self._post_click_x_guard(sx, st))
        except Exception:
            self._post_click_x_guard(saved_x, f"fallback#{seq}")

        try:
            idx = w.index(f"@{event.x},{event.y}")
            line = int(idx.split(".")[0])
        except Exception:
            return "break"

        if not (1 <= line <= len(self.display_rows)):
            return "break"

        pair = self._pair_for_line(line)
        r = self._row_for_side(pair, self._side_for_widget(w))
        pair_idx = self._pair_idx_for_line(line)
        cols = self.pair_diff_cols.get(pair_idx, set()) if pair_idx is not None else set()
        allow_base_row_action = (
            self._is_three_way_enabled()
            and direction == "BASE2A"
            and w is self.base
        )

        # Row overwrite entry is row-header/button driven; main data-area click should only select.
        # Return break to suppress Tk Text default click handler that can reset xview.
        if (not cols) and (not allow_base_row_action):
            return "break"
        if r is None:
            return "break"
        return "break"

    def _on_double_click_navigate(self, w: tk.Text, event, side: str):
        """Select and pin the current difference without mutating a workbook."""
        self._select_from_widget(w, event)
        try:
            self._on_cell_hover_tooltip(w, event, side, force_show=True)
        except TypeError:
            # Older helper signatures remain compatible with this navigation
            # contract; selection has already happened above.
            try:
                self._on_cell_hover_tooltip(w, event, side)
            except Exception:
                pass
        try:
            self._update_cursor_lines()
            self._update_diff_nav_state()
        except Exception:
            pass
        return "break"

    def _on_hover(self, w: tk.Text, event, direction: str):
        try:
            idx = w.index(f"@{event.x},{event.y}")
            line = int(idx.split(".")[0])
            col = int(idx.split(".")[1])
        except Exception:
            self._clear_hover(w)
            return
        if not (1 <= line <= len(self.display_rows)):
            self._clear_hover(w)
            return
        pair = self._pair_for_line(line)
        r = self._row_for_side(pair, self._side_for_widget(w))
        pair_idx = self._pair_idx_for_line(line)
        cols = self.pair_diff_cols.get(pair_idx, set()) if pair_idx is not None else set()
        allow_base_row_action = (
            self._is_three_way_enabled()
            and direction == "BASE2A"
            and w is self.base
        )
        if (not cols) and (not allow_base_row_action):
            self._clear_hover(w)
            return
        if r is None:
            self._clear_hover(w)
            return
        self._show_hover_arrow(w, line, r, direction)

    def _clear_hover(self, w: tk.Text):
        if w is self.left:
            line = self._hover_line_left
        elif w is self.base:
            line = self._hover_line_mid
        else:
            line = self._hover_line_right
        if line is None:
            return
        self._restore_rownum(w, line)
        try:
            if w is self.left:
                w.configure(cursor=self._left_cursor_default)
            elif w is self.base:
                w.configure(cursor=self._mid_cursor_default)
            else:
                w.configure(cursor=self._right_cursor_default)
        except Exception:
            pass
        if w is self.left:
            self._hover_line_left = None
        elif w is self.base:
            self._hover_line_mid = None
        else:
            self._hover_line_right = None

    def _show_hover_arrow(self, w: tk.Text, line: int, r: int, direction: str):
        if w is self.left:
            if self._hover_line_left == line:
                return
        elif w is self.base:
            if self._hover_line_mid == line:
                return
        else:
            if self._hover_line_right == line:
                return
        # restore previous
        self._clear_hover(w)
        self._replace_rownum_with_arrow(w, line, r, direction)
        try:
            w.configure(cursor="hand2")
        except Exception:
            pass
        if w is self.left:
            self._hover_line_left = line
        elif w is self.base:
            self._hover_line_mid = line
        else:
            self._hover_line_right = line

    def _replace_rownum_with_arrow(self, w: tk.Text, line: int, r: int, direction: str):
        if direction == "B2A":
            arrow = _ROW_ARROW_LEFT
        else:
            arrow = _ROW_ARROW_RIGHT
        rownum = str(r)
        new_label = arrow + (" " * max(0, len(rownum) - 1))
        start = f"{line}.0"
        end = f"{line}.{len(rownum)}"
        try:
            w.delete(start, end)
            w.insert(start, new_label)
        except Exception:
            pass

    def _restore_rownum(self, w: tk.Text, line: int):
        if not (1 <= line <= len(self.display_rows)):
            return
        pair = self._pair_for_line(line)
        r = self._row_for_side(pair, self._side_for_widget(w))
        if r is None:
            return
        rownum = str(r)
        start = f"{line}.0"
        end = f"{line}.{len(rownum)}"
        try:
            w.delete(start, end)
            w.insert(start, rownum)
        except Exception:
            pass

    def _highlight_selected_line(self, line: int):
        # Remove highlight only from the previously selected line (O(1))
        self._clear_selected_line_highlight()
        for t in (self.left, self.base, self.right):
            t.tag_add("selrow", f"{line}.0", f"{line}.end")
        self._last_selected_line = line

    def _capture_view_anchor(self):
        """Capture viewport and selection to restore after heavy refresh."""
        first = 0.0
        x_main = 0.0
        x_c = 0.0
        line = 1
        col = 0
        pair_idx = self.selected_pair_idx
        row_a = self.selected_excel_row_a
        row_b = self.selected_excel_row_b
        try:
            first = float((self.left.yview() or (0.0, 1.0))[0])
        except Exception:
            first = 0.0
        try:
            x_main = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            x_main = 0.0
        try:
            x_c = float((self.cursor_cmp.xview() or (0.0, 1.0))[0])
        except Exception:
            x_c = x_main
        try:
            parts = str(self.left.index("insert")).split(".")
            line = int(parts[0])
            col = int(parts[1])
        except Exception:
            line = 1
            col = 0
        return (first, x_main, x_c, line, col, pair_idx, row_a, row_b)

    def _restore_view_anchor(self, anchor):
        if not anchor:
            return
        # backward compatibility with older anchor tuple shape
        if len(anchor) >= 8:
            first, x_main, x_c, line, col, pair_idx, row_a, row_b = anchor
        else:
            first, line, pair_idx, row_a, row_b = anchor
            x_main = 0.0
            x_c = 0.0
            col = 0
        try:
            self.left.yview_moveto(first)
            if self._is_three_way_enabled():
                self.base.yview_moveto(first)
            self.right.yview_moveto(first)
        except Exception:
            pass
        try:
            self._sync_main_x_to_frac(x_main)
            self._sync_c_x_to_frac(x_main if x_c is None else x_c)
        except Exception:
            pass

        target_line = None
        # Prefer relocating by real excel row id; pair indices may shift after rescan.
        try:
            p = None
            if row_a is not None:
                p = self.row_a_to_pair_idx.get(row_a)
            if p is None and row_b is not None:
                p = self.row_b_to_pair_idx.get(row_b)
            if p is not None and p in self.row_to_line:
                target_line = self.row_to_line.get(p)
        except Exception:
            target_line = None
        try:
            if target_line is None and pair_idx is not None and pair_idx in self.row_to_line:
                target_line = self.row_to_line.get(pair_idx)
        except Exception:
            target_line = None

        if target_line is None:
            try:
                max_line = max(1, len(self.display_rows))
            except Exception:
                max_line = 1
            target_line = max(1, min(int(line or 1), max_line))

        idx = f"{target_line}.{max(0, int(col or 0))}"
        for w in (self.left, self.base, self.right):
            try:
                w.mark_set("insert", idx)
            except Exception:
                pass
        try:
            self._highlight_selected_line(target_line)
            self.selected_pair_idx = self._pair_idx_for_line(target_line)
            pair = self._pair_for_line(target_line)
            self.selected_excel_row_a = self._row_for_side(pair, "A")
            self.selected_excel_row_b = self._row_for_side(pair, "B")
            self.selected_excel_row = self.selected_excel_row_a or self.selected_excel_row_b
        except Exception:
            pass

    def _base_to_mine_diff_cols(self, row_a: int | None, row_b: int | None, max_col: int) -> set[int]:
        """Columns that differ between base and mine for the target row in 3-way mode."""
        cols: set[int] = set()
        if not self._is_three_way_enabled():
            return cols
        if not getattr(self.app, "has_base", False):
            return cols
        if self._is_missing_sheet_view():
            r = row_a if row_a is not None else row_b
        else:
            r = None
            mine_map = getattr(self, "mine_to_base_row", {}) or {}
            if row_a is not None:
                r = mine_map.get(row_a)
        if r is None:
            return cols
        try:
            ws_a = self.app.ws_a_val(self.sheet)
            ws_base = self.app.ws_base_val(self.sheet)
        except Exception:
            return cols
        rows_a = _read_rows_into_cache(ws_a, (r,), max_col)
        rows_base = _read_rows_into_cache(ws_base, (r,), max_col)
        row_a = _row_from_cache(rows_a, r, max_col)
        row_base = _row_from_cache(rows_base, r, max_col)
        for c in range(1, max_col + 1):
            va = row_a[c - 1]
            vb = row_base[c - 1]
            if _val_to_str(va) != _val_to_str(vb):
                cols.add(c)
        return cols

    def _update_cursor_lines(self):
        """Update compact row compare block.

        2-way: line1=mine(A), line2=theirs(B)
        3-way: line1=base, line2=mine, line3=theirs
        """
        prev_suppress_c_xsync = bool(getattr(self, "_suppress_c_xsync", False))
        self._suppress_c_xsync = True
        cursor_first = 0.0
        cell_first = 0.0
        try:
            try:
                # Keep C area aligned with main panes by default.
                cursor_first = float((self.left.xview() or (0.0, 1.0))[0])
            except Exception:
                cursor_first = 0.0
            if hasattr(self, "cell_cmp_text"):
                try:
                    cell_first = cursor_first
                except Exception:
                    cell_first = 0.0

            pair_idx = self.resolved_pair_idx_for_c_area()
            if pair_idx is not None:
                self._last_cursor_cmp_pair_idx = pair_idx
            else:
                pair_idx = self._normalize_pair_idx(getattr(self, "_last_cursor_cmp_pair_idx", None))
            pair = self.row_pairs[pair_idx] if pair_idx is not None and pair_idx < len(self.row_pairs) else None
            ra = self._row_for_side(pair, "A")
            rb = self._row_for_side(pair, "B")
            # C-area is an inspection surface: keep raw logical differences
            # visible even when an unresolved/structural slot is intentionally
            # excluded from the only-diff row predicate.
            diff_cols = self._all_logical_diff_cols_for_pair(pair_idx) if pair_idx is not None else set()
            a_text = self.pair_text_a.get(pair_idx, "") if pair_idx is not None else ""
            b_text = self.pair_text_b.get(pair_idx, "") if pair_idx is not None else ""
            base_text = ""
            if self._is_three_way_enabled() and pair_idx is not None:
                base_text = self._build_base_line(pair_idx)

            is_three = self._is_three_way_enabled()
            self._render_cursor_row_headers(pair, is_three)
            # Force strict rendering order:
            # 2-way: mine/theirs
            # 3-way: base/mine/theirs
            self.cursor_cmp.configure(state="normal")
            self.cursor_cmp.delete("1.0", "end")
            if is_three:
                self.cursor_cmp.insert("1.0", f"{base_text}\n{a_text}\n{b_text}")
            else:
                self.cursor_cmp.insert("1.0", f"{a_text}\n{b_text}")

            # Clear & apply base tags
            self.cursor_cmp.tag_remove("a", "1.0", "end")
            self.cursor_cmp.tag_remove("base", "1.0", "end")
            self.cursor_cmp.tag_remove("b", "1.0", "end")
            self.cursor_cmp.tag_remove("missing", "1.0", "end")
            self.cursor_cmp.tag_remove("diffcell", "1.0", "end")
            self.cursor_cmp.tag_remove("cselcell", "1.0", "end")
            if is_three:
                base_r = self._base_row_for_pair(pair_idx, pair)
                if base_r is None:
                    self.cursor_cmp.tag_add("missing", "1.0", "1.end")
                else:
                    self.cursor_cmp.tag_add("base", "1.0", "1.end")
                if ra is None:
                    self.cursor_cmp.tag_add("missing", "2.0", "2.end")
                else:
                    self.cursor_cmp.tag_add("a", "2.0", "2.end")
                if rb is None:
                    self.cursor_cmp.tag_add("missing", "3.0", "3.end")
                else:
                    self.cursor_cmp.tag_add("b", "3.0", "3.end")
            else:
                if ra is None:
                    self.cursor_cmp.tag_add("missing", "1.0", "1.end")
                else:
                    self.cursor_cmp.tag_add("a", "1.0", "1.end")
                if rb is None:
                    self.cursor_cmp.tag_add("missing", "2.0", "2.end")
                else:
                    self.cursor_cmp.tag_add("b", "2.0", "2.end")

            spans_a = self._spans_for_line(a_text)
            spans_b = self._spans_for_line(b_text)
            spans_base = self._spans_for_line(base_text) if is_three else {}

            # Cell-level diff highlight
            if diff_cols:
                for c in diff_cols:
                    if is_three and c in spans_base and self._slot_exists_on_side("BASE", c):
                        s, e = spans_base[c]
                        self.cursor_cmp.tag_add("diffcell", f"1.{s}", f"1.{e}")
                    if c in spans_a and self._slot_exists_on_side("A", c):
                        s, e = spans_a[c]
                        self.cursor_cmp.tag_add("diffcell", f"{2 if is_three else 1}.{s}", f"{2 if is_three else 1}.{e}")
                    if c in spans_b and self._slot_exists_on_side("B", c):
                        s, e = spans_b[c]
                        self.cursor_cmp.tag_add("diffcell", f"{3 if is_three else 2}.{s}", f"{3 if is_three else 2}.{e}")

            # Keep a visible clicked-cell hint in C区 after re-render.
            try:
                sel_col = int(getattr(self, "_cursor_cmp_sel_col", 0) or 0)
                sel_line = int(getattr(self, "_cursor_cmp_sel_line", 0) or 0)
            except Exception:
                sel_col = 0
                sel_line = 0
            if sel_col > 0:
                if is_three:
                    if sel_line == 1 and sel_col in spans_base:
                        s0, e0 = spans_base[sel_col]
                        self.cursor_cmp.tag_add("cselcell", f"1.{s0}", f"1.{e0}")
                    elif sel_line == 2 and sel_col in spans_a:
                        s0, e0 = spans_a[sel_col]
                        self.cursor_cmp.tag_add("cselcell", f"2.{s0}", f"2.{e0}")
                    elif sel_line == 3 and sel_col in spans_b:
                        s0, e0 = spans_b[sel_col]
                        self.cursor_cmp.tag_add("cselcell", f"3.{s0}", f"3.{e0}")
                else:
                    if sel_line == 1 and sel_col in spans_a:
                        s0, e0 = spans_a[sel_col]
                        self.cursor_cmp.tag_add("cselcell", f"1.{s0}", f"1.{e0}")
                    elif sel_line == 2 and sel_col in spans_b:
                        s0, e0 = spans_b[sel_col]
                        self.cursor_cmp.tag_add("cselcell", f"2.{s0}", f"2.{e0}")

            # Apply selected-cell highlight on main panes (A/B and Base in 3-way).
            self._apply_main_selected_cell_highlight()

            self.cursor_cmp.configure(state="disabled")

            # ---- Update C区单元格对齐（可选） ----
            if getattr(self, "_enable_c_cell", False) and hasattr(self, "cell_cmp_text"):
                try:
                    self.cell_cmp_text.configure(state="normal")
                    self.cell_cmp_text.delete("1.0", "end")
                    self.cell_cmp_text.tag_remove("a", "1.0", "end")
                    self.cell_cmp_text.tag_remove("b", "1.0", "end")
                    self.cell_cmp_text.tag_remove("diffcell", "1.0", "end")

                    if pair is not None:
                        ws_a_val = self.app.ws_a_val(self.sheet)
                        ws_b_val = self.app.ws_b_val(self.sheet)
                        show_only_diff = bool(self.c_only_diff_cells.get())
                        cols_to_show = (
                            sorted(c for c in diff_cols if c > 0)
                            if show_only_diff
                            else list(range(1, self._logical_slot_count() + 1))
                        )

                        if show_only_diff:
                            parts_a = []
                            parts_b = []
                            widths = []
                            for c in cols_to_show:
                                ca = self._physical_col_for_logical("A", c)
                                cb = self._physical_col_for_logical("B", c)
                                va = ws_a_val.cell(row=ra, column=ca).value if ra is not None and ca is not None else None
                                vb = ws_b_val.cell(row=rb, column=cb).value if rb is not None and cb is not None else None
                                a_s = _val_to_str(va) if ca is not None else _LOGICAL_COLUMN_PLACEHOLDER
                                b_s = _val_to_str(vb) if cb is not None else _LOGICAL_COLUMN_PLACEHOLDER
                                parts_a.append(a_s)
                                parts_b.append(b_s)
                                widths.append(max(4, min(max(len(a_s), len(b_s)), _COL_MAX_DISPLAY_WIDTH)))

                            sep = _COL_SEP
                            trail = " \u2502"
                            a_line = sep.join(_format_cell(parts_a[i], widths[i]) for i in range(len(parts_a))) + (trail if parts_a else "")
                            b_line = sep.join(_format_cell(parts_b[i], widths[i]) for i in range(len(parts_b))) + (trail if parts_b else "")
                            self.cell_cmp_text.insert("end", a_line + "\n" + b_line + "\n")

                            self.cell_cmp_text.tag_add("a", "1.0", "1.end")
                            self.cell_cmp_text.tag_add("b", "2.0", "2.end")

                            # All shown columns are diffs (show_only_diff path) — highlight whole lines.
                            if a_line:
                                self.cell_cmp_text.tag_add("diffcell", "1.0", "1.end")
                            if b_line:
                                self.cell_cmp_text.tag_add("diffcell", "2.0", "2.end")
                        else:
                            line_no = 1
                            for c in cols_to_show:
                                ca = self._physical_col_for_logical("A", c)
                                cb = self._physical_col_for_logical("B", c)
                                va = ws_a_val.cell(row=ra, column=ca).value if ra is not None and ca is not None else None
                                vb = ws_b_val.cell(row=rb, column=cb).value if rb is not None and cb is not None else None
                                a_s = _val_to_str(va) if ca is not None else _LOGICAL_COLUMN_PLACEHOLDER
                                b_s = _val_to_str(vb) if cb is not None else _LOGICAL_COLUMN_PLACEHOLDER

                                self.cell_cmp_text.insert("end", a_s + "\n")
                                self.cell_cmp_text.insert("end", b_s + "\n")

                                self.cell_cmp_text.tag_add("a", f"{line_no}.0", f"{line_no}.end")
                                self.cell_cmp_text.tag_add("b", f"{line_no+1}.0", f"{line_no+1}.end")

                                if va != vb:
                                    self.cell_cmp_text.tag_add("diffcell", f"{line_no}.0", f"{line_no}.end")
                                    self.cell_cmp_text.tag_add("diffcell", f"{line_no+1}.0", f"{line_no+1}.end")

                                line_no += 2

                    self.cell_cmp_text.configure(state="disabled")
                except Exception:
                    try:
                        self.cell_cmp_text.configure(state="disabled")
                    except Exception:
                        pass

            # Restore C pane horizontal viewport without driving main panes.
            try:
                self.cursor_cmp.xview_moveto(cursor_first)
                cf, cl = self.cursor_cmp.xview()
                self.cursor_hsb.set(cf, cl)
                # Also restore column header: delete+insert resets its xview to 0.
                if getattr(self, "cursor_cmp_colhdr", None) is not None:
                    self.cursor_cmp_colhdr.xview_moveto(cursor_first)
            except Exception:
                pass
            if hasattr(self, "cell_cmp_text"):
                try:
                    self.cell_cmp_text.xview_moveto(cell_first)
                    sf, sl = self.cell_cmp_text.xview()
                    self.cell_cmp_hsb.set(sf, sl)
                except Exception:
                    pass
            self._suppress_c_xsync = prev_suppress_c_xsync
        except Exception:
            try:
                self._suppress_c_xsync = prev_suppress_c_xsync
            except Exception:
                pass
            pass

    def _selected_column_block(self) -> ColumnBlock | None:
        ordinal = getattr(self, "selected_column_block_ordinal", None)
        if ordinal is None:
            return None
        if getattr(self, "_selected_column_projection_generation", None) != getattr(
            self, "_column_projection_generation", None
        ):
            return None
        for block in self._active_column_projection().model.blocks:
            if int(block.ordinal) == int(ordinal):
                return block
        return None

    def _column_block_is_structural(self, block: ColumnBlock) -> bool:
        special = set(self._active_column_comparison_cache().structural_diff_cols)
        special.update(self._active_column_comparison_cache().unresolved_cols)
        return any(int(slot_idx) + 1 in special for slot_idx in block.slot_indices)

    def _column_block_cause_text(self, block: ColumnBlock) -> str:
        cause_labels = {
            COLUMN_MAPPING_CAUSE_BLANK_COLUMN: "空白列无法唯一识别",
            COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE: "重复列特征",
            COLUMN_MAPPING_CAUSE_FORMULA_MISMATCH: "公式结构不一致",
            COLUMN_MAPPING_CAUSE_INCOMPATIBLE_CACHE: "缓存版本不兼容",
            COLUMN_MAPPING_CAUSE_IMPLICIT_BOUNDARY: "列边界不明确",
            COLUMN_MAPPING_CAUSE_COLUMN_LIMIT: "超过列对齐上限",
            COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE: "匹配置信度不足",
        }
        reason_labels = {
            "side-only-insertion": "单侧新增列",
            "ambiguous-side-insertion": "单侧新增列身份不明确",
            "ambiguous-inserted-columns": "新增列身份不明确",
            "ambiguous-deleted-columns": "删除列身份不明确",
            "ambiguous-competing-insertions": "双方在同一位置新增了不同列",
            "competing-insertion": "同一位置存在竞争性新增列",
            "bounded-ambiguity": "相邻可靠列之间存在待确认范围",
            "unresolved-column-range": "列范围匹配待确认",
            "unresolved-three-way-column-range": "三方列范围匹配待确认",
            "low-confidence-physical-fallback": "匹配置信度不足，当前仅按物理位置候选",
            "exact-anchor": "精确列锚点",
            "high-confidence-anchor": "高置信度列锚点",
            "base-anchored": "按Base列锚点定位",
            "deterministic-base-anchored-alignment": "按Base确定性对齐",
            "separate-side-columns": "两侧独立新增列",
            "unique-header-same-ordinal": "唯一表头且物理顺序一致",
            "single-column-same-ordinal": "单列工作表物理顺序一致",
            "internal-safe-fallback": "内部安全回退",
        }
        causes = []
        projection = self._active_column_projection()
        for slot_idx in block.slot_indices:
            slot = projection.slot(int(slot_idx) + 1)
            if slot is None:
                continue
            causes.extend(cause_labels.get(code, code) for code in slot.confidence.cause_codes)
            if slot.confidence.reason:
                causes.append(reason_labels.get(slot.confidence.reason, "结构列变化（内部判定）"))
        return "；".join(dict.fromkeys(str(value) for value in causes if value)) or "结构列变化"

    def _merge_side_label(self, side: str) -> str:
        return merge_side_label(getattr(self.app, "launch_context", None), side)

    def _format_direction_action(self, direction: str, scope: str = "row") -> str:
        """Render an action from its real source/target sides, never left/right."""
        if not hasattr(self, "role_presentation") and not hasattr(
            getattr(self, "app", None), "merge_mode"
        ):
            suffix = {"region": "区域", "global": "全局", "table": "表", "row": "行", "column": "列"}.get(
                str(scope or "").lower(), ""
            )
            source = {"A2B": "左侧", "B2A": "右侧", "BASE2A": "Base"}.get(
                str(direction or ""), "所选侧"
            )
            return f"{source}{suffix}"
        presentation = getattr(
            self,
            "role_presentation",
            RolePresentation.for_app(getattr(self, "app", None)),
        )
        return presentation.action_label(direction, scope)

    def _schedule_column_action_row_layout(self, _event=None):
        """Coalesce geometry updates for the compact nav/action row."""
        bar = getattr(self, "column_action_bar", None)
        if bar is None:
            return
        pending = getattr(self, "_action_row_layout_after_id", None)
        if pending is not None:
            try:
                bar.after_cancel(pending)
            except Exception:
                pass
        try:
            self._action_row_layout_after_id = bar.after_idle(self._layout_column_action_row)
        except Exception:
            self._action_row_layout_after_id = None
            self._layout_column_action_row()

    def _layout_column_action_row(self):
        """Center navigation, moving it only left when right actions need room."""
        self._action_row_layout_after_id = None
        bar = getattr(self, "column_action_bar", None)
        nav = getattr(self, "diff_nav_group", None)
        info = getattr(self, "info", None)
        if bar is None or nav is None:
            return
        try:
            bar_width = int(bar.winfo_width())
            nav_width = int(nav.winfo_reqwidth())
        except Exception:
            return
        if bar_width <= 0 or nav_width <= 0:
            return

        protected_lefts = []
        for widget in (
            getattr(self, "column_action_status_group", None),
            getattr(self, "column_action_button_group", None),
        ):
            try:
                if widget is not None and widget.winfo_ismapped():
                    protected_lefts.append(int(widget.winfo_x()))
            except Exception:
                pass
        gap = 10
        nav_x = (bar_width - nav_width) // 2
        if protected_lefts:
            protected_left = min(protected_lefts)
            if nav_x + nav_width + gap > protected_left:
                # Keep the navigation's right edge clear of structural status
                # and all three decision buttons.  Do not move those controls.
                nav_x = protected_left - gap - nav_width
        try:
            nav.place(x=nav_x, rely=0.5, anchor="w")
        except Exception:
            pass

        # The informational label is intentionally expendable: it cannot
        # compete with the centered navigation or protected right-hand actions.
        if info is not None:
            info_width = max(0, nav_x - gap)
            try:
                if info_width:
                    info.place(x=0, rely=0.5, anchor="w", width=info_width)
                else:
                    info.place_forget()
            except Exception:
                pass

    def _set_column_action_status(self, summary: str, detail: str | None = None):
        """Keep the action bar compact while preserving its audit detail on hover."""
        self._column_action_status_detail = detail or summary
        try:
            self.column_action_status_var.set(summary)
        except Exception:
            pass
        self._sync_column_structure_status_detail()
        self._refresh_column_action_selection_badge()
        self._schedule_column_action_row_layout()

    def _refresh_column_action_selection_badge(self):
        """Render the compact structural status beside the action buttons."""
        range_label = getattr(self, "column_action_selection_label", None)
        if range_label is None:
            return
        block = self._selected_column_block()
        if block is None:
            range_text = ""
            detail = ""
        else:
            start_col = int(block.start_slot_idx) + 1
            end_col = int(block.end_slot_idx) + 1
            range_text = _excel_column_range_display(start_col, end_col)
            detail = (
                f"已选择结构列块 {range_text}｜原因："
                f"{self._column_block_cause_text(block)}"
            )
        try:
            summary = str(self.column_action_status_var.get() or "")
        except Exception:
            summary = ""
        if range_text and range_text in summary:
            prefix, suffix = summary.split(range_text, 1)
        elif range_text:
            prefix, suffix = "已选 ", ""
        else:
            prefix, suffix = summary, ""
        try:
            self.column_action_status_prefix_var.set(prefix)
            self.column_action_selection_var.set(range_text)
            self.column_action_status_suffix_var.set(suffix)
            for widget in (
                getattr(self, "column_action_status_prefix_label", None),
                range_label,
                getattr(self, "column_action_status_suffix_label", None),
            ):
                if widget is not None:
                    widget._identity_detail_text = detail or summary
        except Exception:
            pass
        self._schedule_column_action_row_layout()

    def _sync_column_structure_status_detail(self, structure_summary: str | None = None):
        """Append full structural evidence to hover/log, never the top toolbar."""
        label = getattr(self, "column_action_status_label", None)
        if label is None:
            return
        if structure_summary is None:
            try:
                structure_summary = self._column_structure_summary()
            except Exception:
                structure_summary = ""
        base_detail = str(
            getattr(self, "_column_action_status_detail", "")
            or getattr(label, "_identity_detail_text", "")
            or ""
        ).strip()
        full_detail = base_detail
        if structure_summary:
            full_detail = f"{base_detail}\n完整结构列摘要：{structure_summary}".strip()
        try:
            label._identity_detail_text = full_detail
        except Exception:
            pass
        if structure_summary != getattr(self, "_last_logged_column_structure_summary", None):
            self._last_logged_column_structure_summary = structure_summary
            _dlog(
                f"COLUMN_STRUCTURE_SUMMARY sheet={self.sheet} "
                f"summary={structure_summary or '-'}"
            )

    def _auto_select_first_structural_column_block_if_ready(self) -> ColumnBlock | None:
        """Select one proven structural block per current projection.

        This is presentation state only.  The existing action path still
        revalidates the projection and retains all ambiguous-mapping and
        write-time safety gates. A user clear consumes the current projection's
        automatic selection, while a completed structural action may rebuild
        the projection and expose the next pending block.
        """
        if getattr(self, "_lifecycle_state", "") != "READY":
            return None
        try:
            projection = self._ensure_column_projection_current("自动选择结构列块")
            generation = int(getattr(self, "_column_projection_generation", 0))
            if getattr(self, "_auto_structural_selection_generation", None) == generation:
                return None
            if self._selected_column_block() is not None:
                self._auto_structural_selection_generation = generation
                return None
            # Mark before entering the ordinary selection path, which refreshes
            # the buttons recursively after it applies selection tags.
            self._auto_structural_selection_generation = generation
            cache = self._active_column_comparison_cache()
            if not (cache.structural_diff_cols or cache.unresolved_cols):
                return None
            block = next(
                (
                    candidate
                    for candidate in projection.model.blocks
                    if self._column_block_is_structural(candidate)
                ),
                None,
            )
            if block is None:
                return None
            selected = self._select_column_block_by_logical_col(
                int(block.start_slot_idx) + 1,
                "LOGICAL",
            )
            if selected is not None:
                start_col = int(selected.start_slot_idx) + 1
                end_col = int(selected.end_slot_idx) + 1
                range_text = _excel_column_range_display(start_col, end_col)
                cause_text = self._column_block_cause_text(selected)
                self._set_column_action_status(
                    f"待处理 {range_text} 已自动选｜可执行",
                    f"已自动选择待处理列块 {range_text}｜原因：{cause_text}",
                )
            return selected
        except Exception as exc:
            _dlog(
                f"COLUMN_AUTO_SELECT_SKIPPED sheet={self.sheet} "
                f"err={type(exc).__name__}:{exc}"
            )
            return None

    def _refresh_column_action_buttons(self):
        self._auto_select_first_structural_column_block_if_ready()
        self._refresh_column_action_selection_badge()
        selected = self._selected_column_block() is not None
        ready = (
            getattr(self, "_lifecycle_state", "") == "READY"
            or self._column_undo_model_ready()
        )
        state = "normal" if selected and ready else "disabled"
        for name in ("use_mine_col_btn", "use_theirs_col_btn"):
            widget = getattr(self, name, None)
            if widget is not None:
                try:
                    widget.configure(state=state)
                except Exception:
                    pass
        try:
            if self.app._is_vcs_two_way_mode():
                self.use_theirs_col_btn.configure(state="disabled")
        except Exception:
            pass
        base_button = getattr(self, "use_base_col_btn", None)
        if base_button is not None:
            try:
                base_button.configure(state=(state if self._is_three_way_enabled() else "disabled"))
            except Exception:
                pass
        try:
            self.use_mine_col_btn.configure(
                text=(f"保留 {self.role_presentation.left} 列" if getattr(self.app, "merge_mode", False) else self._format_direction_action("A2B", "column"))
            )
            self.use_theirs_col_btn.configure(
                text=f"应用 {self.role_presentation.right} → {self.role_presentation.left} 列"
            )
            self.use_base_col_btn.configure(
                text=f"应用 {self.role_presentation.middle} → {self.role_presentation.left} 列"
            )
        except Exception:
            pass

    def _apply_column_block_selection_tags(self):
        selection = getattr(self, "selected_column_logical_range", None)
        for widget in (
            getattr(self, "left_colhdr", None),
            getattr(self, "base_colhdr", None),
            getattr(self, "right_colhdr", None),
            getattr(self, "cursor_cmp_colhdr", None),
        ):
            if widget is None:
                continue
            try:
                widget.tag_configure("colblocksel", background="#8EB9FF", foreground="#153A66")
                widget.tag_remove("colblocksel", "1.0", "end")
                if not selection:
                    continue
                start_col, end_col = selection
                spans = self._spans_for_line(widget.get("1.0", "1.end"))
                args = []
                for logical_col in range(int(start_col), int(end_col) + 1):
                    if logical_col in spans:
                        start, end = spans[logical_col]
                        args.extend([f"1.{start}", f"1.{end}"])
                if args:
                    widget.tag_add("colblocksel", *args)
                    widget.tag_raise("colblocksel")
            except Exception:
                pass

    def _select_column_block_by_logical_col(self, logical_col: int, source_side: str = "LOGICAL") -> ColumnBlock | None:
        projection = self._ensure_column_projection_current("选择结构列块")
        logical_col = int(logical_col)
        block = next(
            (candidate for candidate in projection.model.blocks if logical_col - 1 in candidate.slot_indices),
            None,
        )
        if block is None or not self._column_block_is_structural(block):
            self.selected_column_block_ordinal = None
            self.selected_column_logical_range = None
            self.selected_column_source_side = None
            self._selected_column_projection_generation = None
            # Explicitly clearing the selection must not cause this projection
            # to reselect a block on the refresh immediately below.
            self._auto_structural_selection_generation = int(
                getattr(self, "_column_projection_generation", 0)
            )
            self._apply_column_block_selection_tags()
            self._refresh_column_action_buttons()
            self._set_column_action_status(
                f"{_excel_column_display(logical_col)} 不是结构差异列块"
            )
            return None
        start_col = int(block.start_slot_idx) + 1
        end_col = int(block.end_slot_idx) + 1
        normalized_source = str(source_side or "LOGICAL").upper()
        self.selected_column_block_ordinal = int(block.ordinal)
        self.selected_column_logical_range = (start_col, end_col)
        self.selected_column_source_side = normalized_source
        self._selected_column_projection_generation = int(self._column_projection_generation)
        range_text = _excel_column_range_display(start_col, end_col)
        source_text = {"A": self._merge_side_label("A"), "BASE": self._merge_side_label("BASE"), "B": self._merge_side_label("B"), "LOGICAL": "Excel列"}.get(
            normalized_source, normalized_source
        )
        unresolved = any(
            (projection.slot(idx + 1).state == "unresolved" or projection.slot(idx + 1).confidence.ambiguous)
            for idx in block.slot_indices
            if projection.slot(idx + 1) is not None
        )
        state_text = "待显式确认" if unresolved else "可执行"
        cause_text = self._column_block_cause_text(block)
        self._set_column_action_status(
            f"已选 {range_text}｜{source_text}｜{state_text}",
            f"已选择列块 {range_text}｜来源 {source_text}｜{state_text}｜原因：{cause_text}",
        )
        self._apply_column_block_selection_tags()
        self._refresh_column_action_buttons()
        return block

    def _on_column_header_click(self, widget: tk.Text, event, source_side: str):
        try:
            char_pos = int(str(widget.index(f"@{event.x},{event.y}")).split(".")[1])
            logical_col = self._col_from_char(char_pos)
            if logical_col is not None:
                self._select_column_block_by_logical_col(logical_col, source_side)
        except Exception:
            pass
        return "break"

    @staticmethod
    def _require_consecutive_columns(columns: tuple[int, ...], label: str):
        if not columns:
            return
        if any(right != left + 1 for left, right in zip(columns, columns[1:])):
            raise RuntimeError(f"{label}物理列不连续，已阻止结构操作。")

    def _plan_selected_column_block_action(
        self,
        source_side: str,
        target_side: str | None = None,
        *,
        confirm_unresolved: bool = False,
        action_id: str | None = None,
    ) -> ColumnBlockActionPlan:
        projection = self._ensure_column_projection_current("规划列结构操作")
        block = self._selected_column_block()
        if block is None:
            raise RuntimeError("请先点击结构列块表头或橙色列标记。")
        source_side = str(source_side or "").upper()
        if source_side not in ("A", "BASE", "B"):
            raise ValueError("source_side must be A, BASE, or B")
        if target_side is None:
            target_side = "A" if self._is_three_way_enabled() else ("B" if source_side == "A" else "A")
        target_side = str(target_side or "").upper()
        if target_side not in ("A", "B"):
            raise ValueError("target_side must be A or B")
        slots = [projection.slot(idx + 1) for idx in block.slot_indices]
        if any(slot is None for slot in slots):
            raise RuntimeError("列块模型已失效，请刷新后重试。")
        unresolved = any(slot.state == "unresolved" or slot.confidence.ambiguous for slot in slots)
        if unresolved and not confirm_unresolved:
            start_col = int(block.start_slot_idx) + 1
            end_col = int(block.end_slot_idx) + 1
            raise RuntimeError(
                f"Excel列块 {_excel_column_range_display(start_col, end_col)} 映射待确认：{self._column_block_cause_text(block)}。"
                "必须显式确认后才能执行列结构操作。"
            )
        source_values = tuple(projection.physical_col(source_side, idx + 1) for idx in block.slot_indices)
        target_values = tuple(projection.physical_col(target_side, idx + 1) for idx in block.slot_indices)
        source_present = tuple(value is not None for value in source_values)
        target_present = tuple(value is not None for value in target_values)
        if len(set(source_present)) > 1 or len(set(target_present)) > 1:
            raise RuntimeError("列块在源侧或目标侧存在混合缺列状态，已阻止部分修改相邻列。")
        source_cols = tuple(int(value) for value in source_values if value is not None)
        target_cols = tuple(int(value) for value in target_values if value is not None)
        self._require_consecutive_columns(source_cols, "源侧")
        self._require_consecutive_columns(target_cols, "目标侧")
        logical_start = int(block.start_slot_idx) + 1
        logical_end = int(block.end_slot_idx) + 1
        count = logical_end - logical_start + 1
        if source_side == target_side:
            action_kind = "retain"
            anchor = target_cols[0] if target_cols else 1
        elif source_cols and not target_cols:
            action_kind = "insert_copy"
            next_physical = None
            for logical_col in range(logical_end + 1, projection.slot_count + 1):
                next_physical = projection.physical_col(target_side, logical_col)
                if next_physical is not None:
                    break
            if next_physical is None:
                previous = [
                    projection.physical_col(target_side, logical_col)
                    for logical_col in range(1, logical_start)
                ]
                previous = [int(value) for value in previous if value is not None]
                anchor = (previous[-1] + 1) if previous else 1
            else:
                anchor = int(next_physical)
        elif not source_cols and target_cols:
            action_kind = "delete"
            anchor = target_cols[0]
        elif source_cols and target_cols:
            action_kind = "copy"
            anchor = target_cols[0]
        else:
            raise RuntimeError("源侧和目标侧都缺少所选列块，无法执行。")
        return ColumnBlockActionPlan(
            action_id=action_id or self.app.next_manual_column_action_id(),
            sheet=self.sheet,
            block_ordinal=int(block.ordinal),
            logical_start=logical_start,
            logical_end=logical_end,
            source_side=source_side,
            target_side=target_side,
            source_physical_cols=source_cols,
            target_physical_cols=target_cols,
            target_physical_anchor=int(anchor),
            count=count,
            action_kind=action_kind,
            unresolved=unresolved,
        )

    @staticmethod
    def _column_action_cell_key_snapshot(cells) -> dict[str, object]:
        """Capture exact materialized-cell membership compactly.

        Normal action sheets are dense enough that a bit per physical position
        is dramatically smaller than retaining a set of coordinate tuples.  A
        sparse fallback avoids allocating a huge bitmap for unusual far-away
        cells.
        """
        max_row = 0
        max_col = 0
        for row, col in cells:
            row = int(row)
            col = int(col)
            if row > max_row:
                max_row = row
            if col > max_col:
                max_col = col
        span = max_row * max_col
        if 0 < span <= 64_000_000:
            bitmap = bytearray((span + 7) // 8)
            for row, col in cells:
                offset = (int(row) - 1) * max_col + int(col) - 1
                bitmap[offset >> 3] |= 1 << (offset & 7)
            return {
                "kind": "bitmap",
                "max_row": max_row,
                "max_col": max_col,
                "bits": bytes(bitmap),
            }
        return {"kind": "set", "keys": frozenset(cells)}

    @staticmethod
    def _column_action_cell_key_was_present(key_snapshot, row: int, col: int) -> bool:
        if not key_snapshot:
            return False
        if key_snapshot.get("kind") == "bitmap":
            max_row = int(key_snapshot.get("max_row", 0) or 0)
            max_col = int(key_snapshot.get("max_col", 0) or 0)
            if not (1 <= int(row) <= max_row and 1 <= int(col) <= max_col):
                return False
            offset = (int(row) - 1) * max_col + int(col) - 1
            bits = key_snapshot.get("bits") or b""
            byte_index = offset >> 3
            return byte_index < len(bits) and bool(bits[byte_index] & (1 << (offset & 7)))
        return (int(row), int(col)) in (key_snapshot.get("keys") or ())

    @staticmethod
    def _shift_worksheet_columns_fast(ws, anchor: int, count: int, *, insert: bool):
        """Shift materialized cells in one O(cells) dictionary rebuild.

        openpyxl's structural helper first materializes an entire rectangular
        ``iter_cols`` result and then rekeys cells individually.  Column actions
        already manage dimensions and range metadata explicitly, so a direct
        rekey preserves the same Cell objects and avoids that temporary matrix.
        """
        anchor = max(1, int(anchor))
        count = max(1, int(count))
        deleted_end = anchor + count - 1
        old_cells = getattr(ws, "_cells", {}) or {}
        new_cells = {}
        for (row, col), cell in old_cells.items():
            row = int(row)
            col = int(col)
            if insert:
                new_col = col + count if col >= anchor else col
            else:
                if anchor <= col <= deleted_end:
                    continue
                new_col = col - count if col > deleted_end else col
            new_cells[(row, new_col)] = cell
            if new_col != col:
                cell.column = int(new_col)
        ws._cells = new_cells
        _invalidate_worksheet_read_horizon(ws)

    @staticmethod
    def _pack_exact_pair_diff_map(pair_diff_cols, pair_count: int, slot_count: int) -> dict:
        """Detach an exact diff map into a compact row-major bitmap."""
        pair_count = max(0, int(pair_count))
        slot_count = max(0, int(slot_count))
        stride = max(1, (slot_count + 1 + 7) // 8)  # bit 0 is sentinel -1
        bits = bytearray(pair_count * stride)
        for raw_pair_idx, raw_cols in (pair_diff_cols or {}).items():
            pair_idx = int(raw_pair_idx)
            if not (0 <= pair_idx < pair_count):
                raise ValueError("pair diff index is outside the exact row model")
            offset = pair_idx * stride
            for raw_col in raw_cols or ():
                logical_col = int(raw_col)
                bit = 0 if logical_col == -1 else logical_col
                if not (0 <= bit <= slot_count):
                    raise ValueError("pair diff column is outside the exact slot model")
                bits[offset + (bit >> 3)] |= 1 << (bit & 7)
        return {
            "pair_count": pair_count,
            "slot_count": slot_count,
            "stride": stride,
            "bits": bytes(bits),
        }

    @staticmethod
    def _unpack_exact_pair_diff_map(packed) -> dict[int, set[int]]:
        if not isinstance(packed, dict):
            raise ValueError("missing packed exact diff map")
        pair_count = max(0, int(packed.get("pair_count", 0)))
        slot_count = max(0, int(packed.get("slot_count", 0)))
        stride = max(1, int(packed.get("stride", 0)))
        bits = packed.get("bits") or b""
        if len(bits) != pair_count * stride:
            raise ValueError("packed exact diff map length mismatch")
        result: dict[int, set[int]] = {}
        for pair_idx in range(pair_count):
            offset = pair_idx * stride
            mask = int.from_bytes(bits[offset:offset + stride], "little")
            if not mask:
                continue
            cols = {-1} if (mask & 1) else set()
            mask >>= 1
            logical_col = 1
            while mask and logical_col <= slot_count:
                if mask & 1:
                    cols.add(logical_col)
                logical_col += 1
                mask >>= 1
            if cols:
                result[pair_idx] = cols
        return result

    def _capture_column_action_diff_seed(self, plan: ColumnBlockActionPlan):
        """Retain an exact pre-action 2-way diff model for a proved remap.

        This is deliberately a narrow optimization.  The exact map is detached
        into a compact bitmap so later only-diff/background activity cannot
        mutate an undo layer and dense workbooks do not retain one dict/set graph
        per action.
        """
        reason = "eligible"
        try:
            if not bool(getattr(self, "_is_large_sheet", False)):
                reason = "not-large"
            elif self._is_three_way_enabled() or bool(getattr(self.app, "has_base", False)):
                reason = "not-2way"
            elif bool(getattr(self.app, "merge_conflict_mode", False)):
                reason = "conflict-mode"
            elif not bool(getattr(self, "_pair_diff_full_exact", False)):
                reason = "no-exact-full-diff"
            elif not bool(getattr(self, "_data_ready", False)):
                reason = "data-not-ready"
            elif not self._column_mapping_is_current():
                reason = "mapping-stale"
            elif plan.action_kind not in ("insert_copy", "delete", "copy"):
                reason = "unsupported-action"
            elif str(plan.source_side).upper() not in ("A", "B"):
                reason = "unsupported-source"
            else:
                projection = self._active_column_projection()
                if not isinstance(projection, LogicalColumnProjection):
                    reason = "missing-old-projection"
                else:
                    return {
                        "projection": projection,
                        "comparison_cache": self._active_column_comparison_cache(),
                        "row_pairs": tuple(self.row_pairs),
                        "pair_diff_bitmap": self._pack_exact_pair_diff_map(
                            self.pair_diff_cols,
                            len(self.row_pairs),
                            projection.slot_count,
                        ),
                        "row_model_version": int(getattr(self, "_row_model_version", 0)),
                        "pair_diff_full_exact": True,
                        "column_projection_generation": int(
                            getattr(self, "_column_projection_generation", 0)
                        ),
                        # Undo restores the physically identical projection, so
                        # these already-proved display widths avoid rereading the
                        # first large-sheet render window a second time.
                        "col_char_widths": tuple(
                            sorted(
                                (int(col), int(width))
                                for col, width in getattr(
                                    self, "col_char_widths", {}
                                ).items()
                            )
                        ),
                        "rownum_display_width": int(
                            getattr(self, "_rownum_display_width", 0)
                        ),
                        "effective_bounds": (
                            int(getattr(self, "_effective_max_row_a", 1)),
                            int(getattr(self, "col_max_a", 1)),
                            int(getattr(self, "_effective_max_row_b", 1)),
                            int(getattr(self, "col_max_b", 1)),
                        ),
                    }
        except Exception as exc:
            reason = f"capture-error:{type(exc).__name__}"
        self._column_diff_seed_last = {"used": False, "reason": reason}
        return None

    @staticmethod
    def _pack_column_diff_map(diff_map) -> tuple[tuple[int, int], ...]:
        """Compact a logical diff map into pair-index/bitmask records."""
        packed = []
        for pair_idx, cols in sorted((diff_map or {}).items()):
            mask = 0
            for col in cols or ():
                col = int(col)
                bit = 0 if col == -1 else col
                if bit < 0:
                    raise ValueError(f"invalid logical diff column: {col}")
                mask |= 1 << bit
            packed.append((int(pair_idx), mask))
        return tuple(packed)

    @staticmethod
    def _unpack_column_diff_map(packed) -> dict[int, set[int]]:
        restored = {}
        for pair_idx, raw_mask in packed or ():
            mask = int(raw_mask)
            cols = set()
            bit = 0
            while mask:
                if mask & 1:
                    cols.add(-1 if bit == 0 else bit)
                mask >>= 1
                bit += 1
            restored[int(pair_idx)] = cols
        return restored

    def _capture_column_action_comparison_state(self, diff_seed=None):
        """Capture the exact pre-action comparison channels for atomic undo."""
        try:
            projection = self._active_column_projection()
            cache = self._active_column_comparison_cache()
            if not self._column_mapping_is_current():
                return None
            state = {
                "slots": tuple(projection.model.slots),
                "blocks": tuple(projection.model.blocks),
                "structural_diff_cols": frozenset(cache.structural_diff_cols),
                "unresolved_cols": frozenset(cache.unresolved_cols),
                # Column-only refresh is required to preserve row alignment.
                # Keep only that identity check plus compact exact diff maps;
                # full row text is rebuilt from the restored workbooks.
                "row_pairs": self.row_pairs,
                "pair_base_diff_cols": self._pack_column_diff_map(
                    self.pair_base_diff_cols
                ),
                "logical_column_states": tuple(
                    getattr(self, "logical_column_states", ()) or ()
                ),
                "logical_column_structural_conflicts": tuple(
                    getattr(self, "logical_column_structural_conflicts", ()) or ()
                ),
                "pair_diff_full_exact": bool(
                    getattr(self, "_pair_diff_full_exact", False)
                ),
                "diff_partial": bool(getattr(self, "_diff_partial", False)),
            }
            # Reuse the large-sheet seed's immutable bitmap when available;
            # do not retain a second dict/set graph or duplicate bitmap for the
            # same undo layer. Small/partial views use the compact bitmask tuple.
            if isinstance(diff_seed, dict) and isinstance(
                diff_seed.get("pair_diff_bitmap"), dict
            ):
                state["pair_diff_bitmap"] = diff_seed["pair_diff_bitmap"]
            else:
                state["pair_diff_cols"] = self._pack_column_diff_map(
                    self.pair_diff_cols
                )
            return state
        except Exception as exc:
            _dlog(
                f"COLUMN_COMPARISON_STATE_CAPTURE_SKIPPED sheet={self.sheet} "
                f"err={type(exc).__name__}:{exc}"
            )
            return None

    def _restore_column_action_comparison_state(self, state) -> bool:
        """Restore an exact diff state only after the rebuilt model proves equal."""
        if not isinstance(state, dict):
            return False
        try:
            projection = self._active_column_projection()
            cache = self._active_column_comparison_cache()
            if not self._column_mapping_is_current():
                return False
            if tuple(projection.model.slots) != tuple(state.get("slots") or ()):
                return False
            if tuple(projection.model.blocks) != tuple(state.get("blocks") or ()):
                return False
            if frozenset(cache.structural_diff_cols) != frozenset(
                state.get("structural_diff_cols") or ()
            ):
                return False
            if frozenset(cache.unresolved_cols) != frozenset(
                state.get("unresolved_cols") or ()
            ):
                return False
            if tuple(self.row_pairs) != tuple(state.get("row_pairs") or ()):
                return False

            if isinstance(state.get("pair_diff_bitmap"), dict):
                self.pair_diff_cols = self._unpack_exact_pair_diff_map(
                    state.get("pair_diff_bitmap")
                )
            else:
                self.pair_diff_cols = self._unpack_column_diff_map(
                    state.get("pair_diff_cols")
                )
            self.pair_base_diff_cols = self._unpack_column_diff_map(
                state.get("pair_base_diff_cols")
            )
            self.logical_column_states = tuple(
                state.get("logical_column_states") or ()
            )
            self.logical_column_structural_conflicts = tuple(
                state.get("logical_column_structural_conflicts") or ()
            )
            self._pair_diff_full_exact = bool(
                state.get("pair_diff_full_exact", False)
            )
            self._diff_partial = bool(state.get("diff_partial", False))
            self._invalidate_render_cache()
            _dlog(f"COLUMN_COMPARISON_STATE_RESTORED sheet={self.sheet}")
            return True
        except Exception as exc:
            _dlog(
                f"COLUMN_COMPARISON_STATE_RESTORE_SKIPPED sheet={self.sheet} "
                f"err={type(exc).__name__}:{exc}"
            )
            return False

    @staticmethod
    def _column_action_shifted_physical_col(
        physical_col: int | None,
        plan: ColumnBlockActionPlan,
    ) -> int | None:
        if physical_col is None:
            return None
        physical_col = int(physical_col)
        anchor = int(plan.target_physical_anchor)
        end = anchor + int(plan.count) - 1
        if plan.action_kind == "insert_copy":
            return physical_col + int(plan.count) if physical_col >= anchor else physical_col
        if plan.action_kind == "delete":
            if anchor <= physical_col <= end:
                return None
            return physical_col - int(plan.count) if physical_col > end else physical_col
        return physical_col

    @staticmethod
    def _sparse_row_values_for_columns(ws, row: int | None, columns, width: int) -> tuple:
        if row is None:
            return (None,) * max(1, int(width))
        values = [None] * max(1, int(width))
        cells = getattr(ws, "_cells", {}) or {}
        for physical_col in columns:
            physical_col = int(physical_col)
            if not (1 <= physical_col <= len(values)):
                continue
            cell = cells.get((int(row), physical_col))
            if cell is not None:
                values[physical_col - 1] = getattr(cell, "value", None)
        return tuple(values)

    def _try_apply_column_action_bounds_seed(self, request) -> bool:
        """Reuse exact semantic bounds for a proved 2-way insert/copy/restore."""
        if not isinstance(request, dict):
            return False
        state = request.get("state")
        plan = request.get("plan")
        mode = str(request.get("mode") or "apply")
        if (
            not isinstance(state, dict)
            or not isinstance(plan, ColumnBlockActionPlan)
            or self._is_three_way_enabled()
            or bool(getattr(self.app, "has_base", False))
            or bool(getattr(self.app, "merge_conflict_mode", False))
            or not bool(state.get("pair_diff_full_exact", False))
        ):
            return False
        try:
            a_row, a_col, b_row, b_col = (
                int(value) for value in state.get("effective_bounds")
            )
        except Exception:
            return False
        if mode == "restore":
            pass
        elif mode == "apply" and plan.action_kind in ("insert_copy", "copy"):
            if plan.target_side == "A":
                a_row = max(a_row, b_row)
                if plan.action_kind == "insert_copy":
                    a_col += int(plan.count)
            elif plan.target_side == "B":
                b_row = max(a_row, b_row)
                if plan.action_kind == "insert_copy":
                    b_col += int(plan.count)
            else:
                return False
        else:
            return False
        self._effective_max_row_a = max(1, a_row)
        self._effective_max_row_b = max(1, b_row)
        self.col_max_a = max(1, a_col)
        self.col_max_b = max(1, b_col)
        self.max_row = max(self._effective_max_row_a, self._effective_max_row_b)
        self.max_col = max(self.col_max_a, self.col_max_b)
        self._bounds_checked = True
        self._is_large_sheet = self.max_row >= _LARGE_SHEET_ROW_THRESHOLD
        if self._is_large_sheet:
            self._prefer_only_diff_when_ready = True
        return True

    def _try_install_column_action_projection_seed(self, request) -> bool:
        """Install a deterministic 2-way projection for one owned column action.

        The seed is intentionally narrower than ordinary alignment: it is only
        accepted after an exact full diff, with unchanged row identity, and when
        every source identity/target shift can be proved from the immutable old
        model and validated action plan.  Any missing proof leaves the normal
        full-signature rebuild in charge.
        """

        def _fallback(reason: str) -> bool:
            self._column_projection_seed_last = {
                "used": False,
                "reason": str(reason),
            }
            return False

        if not isinstance(request, dict):
            return _fallback("no-request")
        state = request.get("state")
        plan = request.get("plan")
        mode = str(request.get("mode") or "apply")
        if not isinstance(state, dict) or not isinstance(plan, ColumnBlockActionPlan):
            return _fallback("invalid-request")
        if self._is_three_way_enabled() or bool(getattr(self.app, "has_base", False)):
            return _fallback("not-2way")
        if bool(getattr(self.app, "merge_conflict_mode", False)):
            return _fallback("conflict-mode")
        if not bool(getattr(self, "_is_large_sheet", False)):
            return _fallback("not-large")
        if not bool(state.get("pair_diff_full_exact", False)):
            return _fallback("old-diff-not-exact")
        if int(state.get("row_model_version", -1)) != int(
            getattr(self, "_row_model_version", 0)
        ):
            return _fallback("row-model-changed")
        if tuple(self.row_pairs) != tuple(state.get("row_pairs") or ()):
            return _fallback("row-pairs-changed")
        if bool(plan.unresolved):
            return _fallback("unresolved-action")

        old_projection = state.get("projection")
        old_cache = state.get("comparison_cache")
        if not isinstance(old_projection, LogicalColumnProjection) or not isinstance(
            old_cache, LogicalColumnComparisonCache
        ):
            return _fallback("missing-old-model")
        if old_cache.model is not old_projection.model:
            return _fallback("old-model-identity-mismatch")
        if old_cache.three_way_alignment is not None:
            return _fallback("old-model-not-2way")

        old_slots = tuple(old_projection.model.slots)
        selected = set(range(int(plan.logical_start), int(plan.logical_end) + 1))
        if (
            not selected
            or len(selected) != int(plan.count)
            or max(selected) > len(old_slots)
        ):
            return _fallback("invalid-old-range")
        source_side = str(plan.source_side).upper()
        target_side = str(plan.target_side).upper()
        if source_side not in ("A", "B") or target_side not in ("A", "B"):
            return _fallback("invalid-sides")
        if source_side == target_side:
            return _fallback("same-side-action")

        old_source_selected = tuple(
            old_projection.physical_col(source_side, logical_col)
            for logical_col in sorted(selected)
        )
        old_target_selected = tuple(
            old_projection.physical_col(target_side, logical_col)
            for logical_col in sorted(selected)
        )
        if mode == "restore":
            transformed_slots = old_slots
            model_confidence = old_projection.model.confidence
        elif mode == "apply":
            if plan.action_kind == "insert_copy":
                if old_source_selected != tuple(plan.source_physical_cols) or any(
                    value is not None for value in old_target_selected
                ):
                    return _fallback("insert-precondition-mismatch")
            elif plan.action_kind == "delete":
                if any(value is not None for value in old_source_selected) or tuple(
                    value for value in old_target_selected if value is not None
                ) != tuple(plan.target_physical_cols):
                    return _fallback("delete-precondition-mismatch")
            elif plan.action_kind == "copy":
                if (
                    old_source_selected != tuple(plan.source_physical_cols)
                    or old_target_selected != tuple(plan.target_physical_cols)
                    or any(
                        old_slots[logical_col - 1].confidence.ambiguous
                        for logical_col in selected
                    )
                ):
                    return _fallback("copy-precondition-mismatch")
            else:
                return _fallback("unsupported-action")

            adopted_confidence = ColumnMappingConfidence(
                1.0,
                False,
                "exact-anchor",
                ("intrinsic",),
            )
            transformed = []
            for old_slot in old_slots:
                old_logical = int(old_slot.logical_idx) + 1
                if plan.action_kind == "delete" and old_logical in selected:
                    continue
                mine_col = old_slot.mine_col
                theirs_col = old_slot.theirs_col
                if target_side == "A":
                    mine_col = self._column_action_shifted_physical_col(mine_col, plan)
                else:
                    theirs_col = self._column_action_shifted_physical_col(theirs_col, plan)
                adopted = old_logical in selected and plan.action_kind in (
                    "insert_copy", "copy"
                )
                if adopted:
                    offset = old_logical - int(plan.logical_start)
                    adopted_target = int(plan.target_physical_anchor) + offset
                    if target_side == "A":
                        mine_col = adopted_target
                    else:
                        theirs_col = adopted_target
                transformed.append(ColumnSlot(
                    logical_idx=len(transformed),
                    mine_col=mine_col,
                    base_col=None,
                    theirs_col=theirs_col,
                    state="retained" if adopted else old_slot.state,
                    confidence=adopted_confidence if adopted else old_slot.confidence,
                ))
            transformed_slots = tuple(transformed)
            unresolved = any(
                slot.state == "unresolved" or slot.confidence.ambiguous
                for slot in transformed_slots
            )
            model_confidence = ColumnMappingConfidence(
                min((slot.confidence.score for slot in transformed_slots), default=1.0),
                unresolved,
                "unresolved-column-range" if unresolved else "deterministic-two-way-alignment",
                cause_codes=tuple(dict.fromkeys(
                    cause
                    for slot in transformed_slots
                    for cause in slot.confidence.cause_codes
                )),
            )
        else:
            return _fallback("unsupported-mode")

        mine_cols = sorted(
            int(slot.mine_col) for slot in transformed_slots if slot.mine_col is not None
        )
        theirs_cols = sorted(
            int(slot.theirs_col) for slot in transformed_slots if slot.theirs_col is not None
        )
        if mine_cols != list(range(1, int(getattr(self, "col_max_a", 0)) + 1)):
            return _fallback("mine-physical-coverage-mismatch")
        if theirs_cols != list(range(1, int(getattr(self, "col_max_b", 0)) + 1)):
            return _fallback("theirs-physical-coverage-mismatch")

        blocks = _build_column_blocks(transformed_slots)
        model = ColumnModel.from_slots(
            self._expected_column_model_cache_key(),
            transformed_slots,
            blocks=blocks,
            confidence=model_confidence,
        )
        fallback_slots = tuple(
            slot.logical_idx
            for slot in transformed_slots
            if slot.state == "unresolved" or slot.confidence.ambiguous
        )
        alignment = ColumnAlignmentResult(
            model=model,
            anchor_pairs=tuple(
                (int(slot.mine_col), int(slot.theirs_col))
                for slot in transformed_slots
                if slot.mine_col is not None and slot.theirs_col is not None
            ),
            fallback_slot_indices=fallback_slots,
            used_physical_fallback=bool(fallback_slots),
            fallback_reason="unresolved-column-range" if fallback_slots else "",
        )
        cache = LogicalColumnComparisonCache(
            model=model,
            two_way_alignment=alignment,
            structural_diff_cols=frozenset(
                slot.logical_idx + 1
                for slot in transformed_slots
                if slot.mine_col is None or slot.theirs_col is None
            ),
            unresolved_cols=frozenset(slot.logical_idx + 1 for slot in transformed_slots if (
                slot.state == "unresolved" or slot.confidence.ambiguous
            )),
        )
        self._install_column_projection(cache)
        self.column_alignment_2way = self.column_comparison_cache.two_way_alignment
        self.column_alignment_3way = None
        self._column_projection_seed_last = {
            "used": True,
            "reason": f"{mode}-{plan.action_kind}",
        }
        return True

    def _try_apply_column_action_diff_seed(
        self,
        request,
        *,
        ws_a_val,
        ws_b_val,
        ws_a_edit,
        ws_b_edit,
    ) -> bool:
        """Install a proved incremental diff map, else record a full-scan reason."""

        def _fallback(reason: str) -> bool:
            self._column_diff_seed_last = {"used": False, "reason": str(reason)}
            _dlog(f"COLUMN_DIFF_SEED_FALLBACK sheet={self.sheet} reason={reason}")
            return False

        if not isinstance(request, dict):
            return _fallback("no-request")
        state = request.get("state")
        plan = request.get("plan")
        mode = str(request.get("mode") or "apply")
        if not isinstance(state, dict) or not isinstance(plan, ColumnBlockActionPlan):
            return _fallback("invalid-request")
        if self._is_three_way_enabled() or bool(getattr(self.app, "has_base", False)):
            return _fallback("not-2way")
        if not bool(getattr(self, "_is_large_sheet", False)):
            return _fallback("not-large")
        if tuple(self.row_pairs) != tuple(state.get("row_pairs") or ()):
            return _fallback("row-pairs-changed")
        old_projection = state.get("projection")
        new_projection = self._active_column_projection()
        if not isinstance(old_projection, LogicalColumnProjection) or not isinstance(
            new_projection, LogicalColumnProjection
        ):
            return _fallback("missing-projection")
        try:
            old_diff_map = self._unpack_exact_pair_diff_map(state.get("pair_diff_bitmap"))
        except Exception:
            return _fallback("missing-exact-map")

        # Undo/rollback restores the exact old workbooks.  Reuse is allowed only
        # if the rebuilt projection is physically identical on both sides.
        if mode == "restore":
            if old_projection.slot_count != new_projection.slot_count:
                return _fallback("restore-slot-count-changed")
            for logical_col in range(1, old_projection.slot_count + 1):
                for side in ("A", "B"):
                    if old_projection.physical_col(side, logical_col) != new_projection.physical_col(
                        side, logical_col
                    ):
                        return _fallback("restore-projection-mismatch")
            self.pair_diff_cols = {
                int(pair_idx): set(cols)
                for pair_idx, cols in old_diff_map.items()
                if cols
            }
            widths_restored = False
            try:
                self._set_uniform_logical_column_widths(new_projection)
                widths_restored = True
            except Exception:
                widths_restored = False
            self._pair_diff_full_exact = True
            self._column_diff_seed_last = {
                "used": True,
                "reason": "restore-exact",
                "widths_restored": widths_restored,
            }
            _dlog(f"COLUMN_DIFF_SEED_USED sheet={self.sheet} mode=restore")
            return True

        if mode != "apply" or plan.action_kind not in ("insert_copy", "delete", "copy"):
            return _fallback("unsupported-mode")
        source_side = str(plan.source_side).upper()
        target_side = str(plan.target_side).upper()
        if source_side not in ("A", "B") or target_side not in ("A", "B") or source_side == target_side:
            return _fallback("invalid-sides")
        selected = set(range(int(plan.logical_start), int(plan.logical_end) + 1))
        if not selected or max(selected) > old_projection.slot_count:
            return _fallback("invalid-old-range")

        old_source_selected = tuple(
            old_projection.physical_col(source_side, logical_col)
            for logical_col in sorted(selected)
        )
        old_target_selected = tuple(
            old_projection.physical_col(target_side, logical_col)
            for logical_col in sorted(selected)
        )
        if plan.action_kind == "insert_copy":
            if old_source_selected != tuple(plan.source_physical_cols) or any(
                value is not None for value in old_target_selected
            ):
                return _fallback("insert-precondition-mismatch")
            expected_slot_count = old_projection.slot_count
        elif plan.action_kind == "delete":
            if any(value is not None for value in old_source_selected) or tuple(
                value for value in old_target_selected if value is not None
            ) != tuple(plan.target_physical_cols):
                return _fallback("delete-precondition-mismatch")
            expected_slot_count = old_projection.slot_count - int(plan.count)
        else:
            if old_source_selected != tuple(plan.source_physical_cols) or old_target_selected != tuple(
                plan.target_physical_cols
            ):
                return _fallback("copy-precondition-mismatch")
            expected_slot_count = old_projection.slot_count
        if new_projection.slot_count != expected_slot_count:
            return _fallback("new-slot-count-mismatch")

        old_to_new: dict[int, int] = {}
        used_new = set()
        for old_logical in range(1, old_projection.slot_count + 1):
            if old_logical in selected:
                continue
            source_physical = old_projection.physical_col(source_side, old_logical)
            old_target_physical = old_projection.physical_col(target_side, old_logical)
            expected_target = self._column_action_shifted_physical_col(
                old_target_physical, plan
            )
            if source_physical is not None:
                new_logical = new_projection.logical_col(source_side, source_physical)
            elif expected_target is not None:
                # The target side is structurally shifted but existing Cell
                # identities outside the action range move deterministically.
                new_logical = new_projection.logical_col(target_side, expected_target)
            else:
                return _fallback("untracked-unaffected-slot")
            if new_logical is None or new_logical in used_new:
                return _fallback("unproved-unaffected-slot-remap")
            if new_projection.physical_col(source_side, new_logical) != source_physical:
                return _fallback("source-slot-identity-mismatch")
            if new_projection.physical_col(target_side, new_logical) != expected_target:
                return _fallback("target-slot-shift-mismatch")
            old_to_new[old_logical] = new_logical
            used_new.add(new_logical)

        affected_new: tuple[int, ...]
        if plan.action_kind == "delete":
            affected_new = ()
        else:
            mapped = tuple(
                new_projection.logical_col(source_side, physical_col)
                for physical_col in plan.source_physical_cols
            )
            if any(value is None for value in mapped) or len(set(mapped)) != int(plan.count):
                return _fallback("unproved-affected-slot-remap")
            affected_new = tuple(int(value) for value in mapped)
            for offset, logical_col in enumerate(affected_new):
                if new_projection.physical_col(target_side, logical_col) != int(
                    plan.target_physical_anchor
                ) + offset:
                    return _fallback("affected-target-slot-mismatch")
        if used_new | set(affected_new) != set(range(1, new_projection.slot_count + 1)):
            return _fallback("new-slot-coverage-mismatch")

        seeded: dict[int, set[int]] = {}
        for pair_idx, old_cols in old_diff_map.items():
            pair_idx = int(pair_idx)
            if not (0 <= pair_idx < len(self.row_pairs)):
                return _fallback("invalid-pair-index")
            remapped = set()
            for old_col in set(old_cols or ()):
                old_col = int(old_col)
                if old_col == -1:
                    remapped.add(-1)
                elif old_col in selected:
                    continue
                elif old_col in old_to_new:
                    remapped.add(old_to_new[old_col])
                else:
                    return _fallback("invalid-old-diff-column")
            if remapped:
                seeded[pair_idx] = remapped

        # The action can only change the selected logical block.  Recompute that
        # block for every pair from sparse, non-materializing _cells lookups so
        # formulas, cached values, blanks, and one-sided tail rows keep the same
        # comparison semantics as a full scan.
        if affected_new:
            affected_slots = tuple(
                (
                    int(logical_col),
                    new_projection.physical_col("A", logical_col),
                    new_projection.physical_col("B", logical_col),
                )
                for logical_col in affected_new
            )
            a_val_cells = getattr(ws_a_val, "_cells", {}) or {}
            b_val_cells = getattr(ws_b_val, "_cells", {}) or {}
            a_edit_cells = getattr(ws_a_edit, "_cells", {}) or {} if ws_a_edit is not None else {}
            b_edit_cells = getattr(ws_b_edit, "_cells", {}) or {} if ws_b_edit is not None else {}

            def _raw(cells, row, physical_col):
                cell = cells.get((int(row), int(physical_col)))
                return getattr(cell, "value", None) if cell is not None else None

            for pair_idx, (ra, rb) in enumerate(self.row_pairs):
                if (ra is None) != (rb is None):
                    seeded.setdefault(pair_idx, set()).add(-1)
                    continue
                if ra is None and rb is None:
                    continue
                compare_row = int(ra)
                changed = set()
                for logical_col, a_col, b_col in affected_slots:
                    if a_col is None and b_col is None:
                        continue
                    if a_col is None or b_col is None:
                        existing_row = rb if a_col is None else ra
                        existing_col = b_col if a_col is None else a_col
                        value_cells = b_val_cells if a_col is None else a_val_cells
                        edit_cells = b_edit_cells if a_col is None else a_edit_cells
                        value = _raw(value_cells, existing_row, existing_col)
                        edit = _raw(edit_cells, existing_row, existing_col)
                        if value not in (None, "") or edit not in (None, ""):
                            changed.add(logical_col)
                        continue

                    a_value = _raw(a_val_cells, ra, a_col)
                    b_value = _raw(b_val_cells, rb, b_col)
                    a_edit = _raw(a_edit_cells, ra, a_col)
                    b_edit = _raw(b_edit_cells, rb, b_col)
                    a_edit = _translate_normal_formula_for_compare(
                        a_value,
                        a_edit,
                        int(ra),
                        int(a_col),
                        compare_row,
                        logical_col,
                    )
                    b_edit = _translate_normal_formula_for_compare(
                        b_value,
                        b_edit,
                        int(rb),
                        int(b_col),
                        compare_row,
                        logical_col,
                    )
                    _a_display, _b_display, equal = _cell_display_and_equal_from_values(
                        a_value,
                        b_value,
                        a_edit,
                        b_edit,
                    )
                    if not equal:
                        changed.add(logical_col)
                if changed:
                    seeded.setdefault(pair_idx, set()).update(changed)
        self.pair_diff_cols = seeded
        widths_restored = False
        if plan.action_kind == "insert_copy":
            try:
                self._set_uniform_logical_column_widths(new_projection)
                widths_restored = True
            except Exception:
                widths_restored = False
        self._pair_diff_full_exact = True
        self._column_diff_seed_last = {
            "used": True,
            "reason": f"apply-{plan.action_kind}",
            "affected_cols": len(affected_new),
            "widths_restored": widths_restored,
        }
        _dlog(
            f"COLUMN_DIFF_SEED_USED sheet={self.sheet} mode=apply "
            f"kind={plan.action_kind} affected={len(affected_new)}"
        )
        return True

    def _column_action_workbook_snapshot(
        self,
        target_side: str,
        plan: ColumnBlockActionPlan | None = None,
    ) -> dict[str, object]:
        """Capture a bounded inverse snapshot before a column mutation.

        Insert undo needs no Cell copies because the original Cell objects are
        shifted back.  Delete/copy retain only the affected block.  Exact sparse
        ``_cells`` membership is represented by a compact bitmap so foreground
        values-only reads can be cleaned up again during rollback/undo.
        """
        target_side = str(target_side or "").upper()
        self.app._ensure_edit_loaded()
        self.app._ensure_value_workbooks_regular()
        if target_side == "A":
            wb_edit = self.app._wb_a_edit
            wb_val = self.app._wb_a_val
            manual_ops = self.app.manual_a_column_ops
            manual_cell_ops = self.app.manual_a_cell_ops
            manual_formula_cache_ops = self.app.manual_a_formula_cache_ops
        elif target_side == "B":
            wb_edit = self.app._wb_b_edit
            wb_val = self.app._wb_b_val
            manual_ops = self.app.manual_b_column_ops
            manual_cell_ops = self.app.manual_b_cell_ops
            manual_formula_cache_ops = self.app.manual_b_formula_cache_ops
        else:
            raise ValueError("target_side must be A or B")
        if wb_edit is None or wb_val is None:
            raise RuntimeError("目标工作簿尚未加载，无法建立原子回滚点。")

        def _sheet_state(ws):
            cells = getattr(ws, "_cells", {}) or {}
            action_kind = plan.action_kind if isinstance(plan, ColumnBlockActionPlan) else "full"
            anchor = int(plan.target_physical_anchor) if isinstance(plan, ColumnBlockActionPlan) else 1
            count = int(plan.count) if isinstance(plan, ColumnBlockActionPlan) else 0
            affected_end = anchor + count - 1
            if action_kind == "full":
                saved_cells = {
                    key: copy.copy(cell)
                    for key, cell in cells.items()
                }
                key_snapshot = None
            else:
                saved_cells = {
                    key: copy.copy(cell)
                    for key, cell in cells.items()
                    if action_kind in ("delete", "copy")
                    and anchor <= int(key[1]) <= affected_end
                }
                key_snapshot = self._column_action_cell_key_snapshot(cells)
            return {
                "cells": saved_cells,
                "cell_snapshot_mode": action_kind,
                "cell_keys": key_snapshot,
                "anchor": anchor,
                "count": count,
                "structure_applied": False,
                "copy_started": False,
                "restored_once": False,
                "column_dimensions": self._column_action_dimension_snapshot(ws),
                "data_validations": copy.deepcopy(ws.data_validations),
                # Preserve ConditionalFormatting objects as grouped in the
                # original XML.  Flattening by individual range changed one
                # multi-range object into many objects after undo.
                "conditional_formatting_rules": copy.deepcopy(
                    getattr(ws.conditional_formatting, "_cf_rules", {})
                ),
                "merged_cells": self._column_action_merged_ranges(ws),
                "current_row": int(getattr(ws, "_current_row", 0) or 0),
            }

        diff_seed = self._capture_column_action_diff_seed(plan) if isinstance(
            plan, ColumnBlockActionPlan
        ) else None
        comparison_state = self._capture_column_action_comparison_state(diff_seed)
        formula_transformations = ()
        if (
            isinstance(plan, ColumnBlockActionPlan)
            and plan.action_kind in ("insert_copy", "delete")
        ):
            formula_transformations = self._capture_column_formula_transformations(
                wb_edit,
                plan,
            )
        return {
            "target_side": target_side,
            "sheet": self.sheet,
            "edit_sheet": _sheet_state(wb_edit[self.sheet]),
            "value_sheet": _sheet_state(wb_val[self.sheet]),
            "manual_column_ops": copy.deepcopy(list(manual_ops)),
            "manual_cell_ops": copy.deepcopy(dict(manual_cell_ops)),
            "manual_formula_cache_ops": copy.deepcopy(dict(manual_formula_cache_ops)),
            "modified_a": bool(getattr(self.app, "modified_a", False)),
            "modified_b": bool(getattr(self.app, "modified_b", False)),
            "modified_sheets_a": set(getattr(self.app, "modified_sheets_a", set()) or set()),
            "modified_sheets_b": set(getattr(self.app, "modified_sheets_b", set()) or set()),
            "selection": {
                "block_ordinal": self.selected_column_block_ordinal,
                "logical_range": self.selected_column_logical_range,
                "source_side": self.selected_column_source_side,
                "cell": self._snapshot_explicit_selection_state(),
            },
            "retained_decisions": set(self._retained_column_decisions),
            "column_diff_seed": diff_seed,
            "column_comparison_state": comparison_state,
            # Excel's inverse structural operation cannot reconstruct formulas
            # that became #REF! during a deletion.  Retain only formulas whose
            # text will actually change, across every sheet that references the
            # structurally edited worksheet, so rollback/undo is exact without
            # copying whole workbooks.
            "formula_transformations": formula_transformations,
        }

    @staticmethod
    def _capture_column_formula_transformations(
        wb_edit,
        plan: ColumnBlockActionPlan,
    ) -> tuple[tuple[str, int, int, object, str, object], ...]:
        """Return changed normal-formula values for one structural action.

        Formulas on the target sheet can contain unqualified references;
        formulas on any other sheet can contain a target-sheet-qualified
        reference.  Special multi-cell formula objects stay conservative.
        """
        records = []
        insert = plan.action_kind == "insert_copy"
        target_sheet = str(plan.sheet)
        target_sheet_folded = target_sheet.casefold()
        unquoted_target = target_sheet_folded + "!"
        quoted_target = "'" + target_sheet.replace("'", "''").casefold() + "'!"
        for worksheet in getattr(wb_edit, "worksheets", ()) or ():
            formula_sheet = str(getattr(worksheet, "title", "") or "")
            for (row_idx, col_idx), cell in (
                (getattr(worksheet, "_cells", {}) or {}).items()
            ):
                if getattr(cell, "data_type", None) != "f":
                    continue
                old_value = cell.value
                if _special_formula_signature(old_value) is not None:
                    continue
                # An unqualified reference belongs to the formula's own sheet.
                # Other sheets can be affected only through an explicit target
                # sheet qualifier.  This lexical guard is deliberately only a
                # negative filter; possible matches still go through Tokenizer,
                # which rejects strings, names, external links and structured
                # references conservatively.  Large production workbooks often
                # contain tens of thousands of unrelated-sheet formulas.
                if formula_sheet.casefold() != target_sheet_folded:
                    formula_folded = str(_formula_text(old_value) or "").casefold()
                    if (
                        unquoted_target not in formula_folded
                        and quoted_target not in formula_folded
                    ):
                        continue
                new_value = _transform_formula_for_column_structure(
                    old_value,
                    formula_sheet=formula_sheet,
                    target_sheet=target_sheet,
                    anchor=int(plan.target_physical_anchor),
                    count=int(plan.count),
                    insert=insert,
                )
                if new_value == old_value:
                    continue
                records.append((
                    formula_sheet,
                    int(row_idx),
                    int(col_idx),
                    copy.deepcopy(old_value),
                    str(getattr(cell, "data_type", "f") or "f"),
                    new_value,
                ))
        return tuple(records)

    @staticmethod
    def _apply_column_formula_transformations(wb_edit, records) -> None:
        """Apply captured formula text before target-sheet cells are shifted."""
        for sheet, row_idx, col_idx, _old_value, _old_type, new_value in records or ():
            if sheet not in wb_edit.sheetnames:
                raise RuntimeError(f"公式所在工作表已不可用：{sheet}")
            cell = (getattr(wb_edit[sheet], "_cells", {}) or {}).get(
                (int(row_idx), int(col_idx))
            )
            if cell is None:
                raise RuntimeError(
                    f"公式单元格已不可用：{sheet}!{get_column_letter(int(col_idx))}{int(row_idx)}"
                )
            _assign_edit_cell_value(cell, new_value)

    @staticmethod
    def _restore_column_formula_transformations(wb_edit, records) -> None:
        """Restore exact pre-action formula text after inverse structure."""
        for sheet, row_idx, col_idx, old_value, old_type, _new_value in records or ():
            if sheet not in wb_edit.sheetnames:
                raise RuntimeError(f"公式所在工作表已不可用：{sheet}")
            worksheet = wb_edit[sheet]
            cell = (getattr(worksheet, "_cells", {}) or {}).get(
                (int(row_idx), int(col_idx))
            )
            if cell is None:
                cell = worksheet.cell(row=int(row_idx), column=int(col_idx))
            _assign_edit_cell_value(cell, copy.deepcopy(old_value))
            cell.data_type = str(old_type or "f")

    def _restore_column_action_workbook_snapshot(
        self,
        snapshot: dict[str, object],
        *,
        post_refresh_cleanup: bool = False,
    ):
        target_side = str(snapshot.get("target_side") or "").upper()
        sheet = str(snapshot.get("sheet") or self.sheet)
        if target_side == "A":
            wb_edit = self.app._wb_a_edit
            wb_value = self.app._wb_a_val
            self.app.manual_a_column_ops[:] = copy.deepcopy(snapshot.get("manual_column_ops") or [])
            manual_cell_ops = self.app.manual_a_cell_ops
            manual_formula_cache_ops = self.app.manual_a_formula_cache_ops
        elif target_side == "B":
            wb_edit = self.app._wb_b_edit
            wb_value = self.app._wb_b_val
            self.app.manual_b_column_ops[:] = copy.deepcopy(snapshot.get("manual_column_ops") or [])
            manual_cell_ops = self.app.manual_b_cell_ops
            manual_formula_cache_ops = self.app.manual_b_formula_cache_ops
        else:
            raise ValueError("invalid rollback target")
        if wb_edit is None or wb_value is None or sheet not in wb_edit.sheetnames or sheet not in wb_value.sheetnames:
            raise RuntimeError("目标工作表已不可用，无法恢复列结构操作。")

        def _restore_sheet_state(ws, state):
            state = state or {}
            mode = str(state.get("cell_snapshot_mode") or "full")
            saved_cells = state.get("cells") or {}
            if mode == "full":
                ws._cells = {
                    key: copy.copy(cell)
                    for key, cell in saved_cells.items()
                }
            else:
                anchor = max(1, int(state.get("anchor", 1) or 1))
                count = max(1, int(state.get("count", 1) or 1))
                if not bool(state.get("restored_once", False)):
                    if mode == "insert_copy" and bool(state.get("structure_applied", False)):
                        self._shift_worksheet_columns_fast(
                            ws, anchor, count, insert=False
                        )
                    elif mode == "delete" and bool(state.get("structure_applied", False)):
                        self._shift_worksheet_columns_fast(
                            ws, anchor, count, insert=True
                        )
                    state["restored_once"] = True

                # Remove empty Cells materialized by mapping/prescan/render so
                # the exact original sparse-key contract survives refresh.
                key_snapshot = state.get("cell_keys")
                for row, col in list(getattr(ws, "_cells", {}).keys()):
                    if not self._column_action_cell_key_was_present(
                        key_snapshot, int(row), int(col)
                    ):
                        ws._cells.pop((row, col), None)

                if mode in ("delete", "copy") and (
                    bool(state.get("structure_applied", False))
                    or bool(state.get("copy_started", False))
                ):
                    affected_end = anchor + count - 1
                    for row, col in list(getattr(ws, "_cells", {}).keys()):
                        if anchor <= int(col) <= affected_end:
                            ws._cells.pop((row, col), None)
                    for key, cell in saved_cells.items():
                        restored_cell = copy.copy(cell)
                        restored_cell.row = int(key[0])
                        restored_cell.column = int(key[1])
                        ws._cells[key] = restored_cell
            _invalidate_worksheet_read_horizon(ws)
            ws._current_row = int(state.get("current_row", 0) or 0)
            if post_refresh_cleanup:
                # The first restore already reinstated workbook metadata and
                # operation history.  The post-refresh pass exists only to
                # remove Cells materialized by read/render code (and to put
                # affected delete/copy Cells back byte-exactly); repeating all
                # deep metadata copies here adds latency without changing state.
                return
            ws.column_dimensions.clear()
            for physical_col, dimension in sorted((state.get("column_dimensions") or {}).items()):
                key = get_column_letter(int(physical_col))
                ws.column_dimensions[key] = copy.copy(dimension)
            ws.data_validations = copy.deepcopy(state.get("data_validations"))
            ws.conditional_formatting._cf_rules = copy.deepcopy(
                state.get("conditional_formatting_rules") or {}
            )
            ws.merged_cells = MultiCellRange(
                [str(cell_range) for cell_range in (state.get("merged_cells") or ())]
            )

        _restore_sheet_state(wb_edit[sheet], snapshot.get("edit_sheet"))
        _restore_sheet_state(wb_value[sheet], snapshot.get("value_sheet"))
        if not post_refresh_cleanup:
            self._restore_column_formula_transformations(
                wb_edit,
                snapshot.get("formula_transformations") or (),
            )
        if post_refresh_cleanup:
            return
        manual_cell_ops.clear()
        manual_cell_ops.update(copy.deepcopy(snapshot.get("manual_cell_ops") or {}))
        manual_formula_cache_ops.clear()
        manual_formula_cache_ops.update(
            copy.deepcopy(snapshot.get("manual_formula_cache_ops") or {})
        )
        self.app.modified_a = bool(snapshot.get("modified_a", False))
        self.app.modified_b = bool(snapshot.get("modified_b", False))
        self.app.modified_sheets_a.clear()
        self.app.modified_sheets_a.update(snapshot.get("modified_sheets_a") or set())
        self.app.modified_sheets_b.clear()
        self.app.modified_sheets_b.update(snapshot.get("modified_sheets_b") or set())
        self._retained_column_decisions = set(snapshot.get("retained_decisions") or set())

    @staticmethod
    def _column_action_dimension_snapshot(ws) -> dict[int, object]:
        result = {}
        for key, dimension in list(getattr(ws, "column_dimensions", {}).items()):
            physical_col = _col_index_from_ref(str(key))
            if physical_col > 0:
                result[physical_col] = copy.copy(dimension)
        return result

    @staticmethod
    def _restore_shifted_column_dimensions(ws, dimensions, anchor: int, count: int, *, insert: bool):
        try:
            ws.column_dimensions.clear()
        except Exception:
            return
        deleted_end = int(anchor) + int(count) - 1
        for old_col, old_dimension in sorted((dimensions or {}).items()):
            if insert:
                new_col = old_col + count if old_col >= anchor else old_col
            else:
                if anchor <= old_col <= deleted_end:
                    continue
                new_col = old_col - count if old_col > deleted_end else old_col
            dimension = copy.copy(old_dimension)
            letter = get_column_letter(new_col)
            try:
                dimension.index = letter
                dimension.min = new_col
                dimension.max = new_col
            except Exception:
                pass
            ws.column_dimensions[letter] = dimension

    @staticmethod
    def _copy_one_column_dimension(src_ws, dst_ws, src_col: int, dst_col: int):
        src_key = get_column_letter(int(src_col))
        dst_key = get_column_letter(int(dst_col))
        try:
            dst_ws.column_dimensions.pop(dst_key, None)
        except Exception:
            pass
        src_dimension = getattr(src_ws, "column_dimensions", {}).get(src_key)
        if src_dimension is None:
            return
        dimension = copy.copy(src_dimension)
        try:
            dimension.index = dst_key
            dimension.min = int(dst_col)
            dimension.max = int(dst_col)
        except Exception:
            pass
        dst_ws.column_dimensions[dst_key] = dimension

    @staticmethod
    def _column_action_validation_ranges(ws):
        result = []
        validations = getattr(getattr(ws, "data_validations", None), "dataValidation", ()) or ()
        for validation in validations:
            for cell_range in getattr(getattr(validation, "ranges", None), "ranges", ()) or ():
                result.append((validation, copy.copy(cell_range)))
        return result

    @staticmethod
    def _replace_validation_ranges(ws, entries):
        validations = getattr(getattr(ws, "data_validations", None), "dataValidation", None)
        if validations is None:
            return
        grouped = {}
        for validation, cell_range in entries:
            grouped.setdefault(id(validation), [validation, []])[1].append(cell_range)
        ws.data_validations.dataValidation = []
        for validation, ranges in grouped.values():
            cloned = copy.copy(validation)
            cloned.sqref = MultiCellRange(ranges)
            ws.add_data_validation(cloned)

    @staticmethod
    def _shift_column_validation_ranges(entries, anchor: int, count: int, *, insert: bool):
        shifted = []
        deleted_end = anchor + count - 1
        for validation, cell_range in entries:
            rng = copy.copy(cell_range)
            if insert:
                if rng.min_col >= anchor:
                    rng.shift(col_shift=count)
                elif rng.max_col >= anchor:
                    rng.max_col += count
            else:
                if rng.max_col < anchor:
                    pass
                elif rng.min_col > deleted_end:
                    rng.shift(col_shift=-count)
                else:
                    left_count = max(0, anchor - rng.min_col)
                    right_count = max(0, rng.max_col - deleted_end)
                    if left_count + right_count <= 0:
                        continue
                    # When the range starts inside the deleted block and
                    # continues on its right, the surviving right fragment
                    # moves to the deletion anchor.  Keeping the old min_col
                    # would shift C:E / delete B:C to C:D instead of B:C.
                    if left_count <= 0:
                        rng.min_col = anchor
                    rng.max_col = rng.min_col + left_count + right_count - 1
            shifted.append((validation, rng))
        return shifted

    def _prepare_column_copy_payload(self, plan: ColumnBlockActionPlan, src_edit, src_val, dst_edit, dst_val):
        payload = []
        max_row = max(
            int(getattr(src_edit, "max_row", 1) or 1),
            int(getattr(src_val, "max_row", 1) or 1),
            int(getattr(dst_edit, "max_row", 1) or 1),
            int(getattr(dst_val, "max_row", 1) or 1),
        )
        for offset, src_col in enumerate(plan.source_physical_cols):
            dst_col = plan.target_physical_anchor + offset
            for row in range(1, max_row + 1):
                source_edit_cell = getattr(src_edit, "_cells", {}).get((row, src_col))
                source_value_cell = getattr(src_val, "_cells", {}).get((row, src_col))
                target_edit_cell = getattr(dst_edit, "_cells", {}).get((row, dst_col))
                source_edit_value = source_edit_cell.value if source_edit_cell is not None else None
                source_value = source_value_cell.value if source_value_cell is not None else None
                target_edit_value = target_edit_cell.value if target_edit_cell is not None else None
                edit_value = _copy_edit_value_for_destination(
                    source_value,
                    source_edit_value,
                    target_edit_value,
                    src_row=row,
                    src_col=src_col,
                    dst_row=row,
                    dst_col=dst_col,
                )
                payload.append((
                    row,
                    src_col,
                    dst_col,
                    edit_value,
                    copy.deepcopy(source_value),
                    copy.copy(source_edit_cell._style) if source_edit_cell is not None else None,
                    copy.copy(source_edit_cell.comment) if source_edit_cell is not None else None,
                    copy.copy(source_edit_cell.hyperlink) if source_edit_cell is not None else None,
                ))
        return payload

    def _apply_column_copy_payload(self, payload, src_edit, dst_edit, dst_val):
        for row, _src_col, dst_col, edit_value, value, style, comment, hyperlink in payload:
            edit_cell = dst_edit.cell(row=row, column=dst_col)
            value_cell = dst_val.cell(row=row, column=dst_col)
            _assign_edit_cell_value(edit_cell, edit_value)
            value_cell.value = value
            edit_cell._style = copy.copy(style)
            value_cell._style = copy.copy(style)
            edit_cell.comment = copy.copy(comment)
            value_cell.comment = copy.copy(comment)
            edit_cell._hyperlink = copy.copy(hyperlink)
            value_cell._hyperlink = copy.copy(hyperlink)

    def _copy_column_validations(self, src_ws, dst_ws, plan: ColumnBlockActionPlan):
        target_start = int(plan.target_physical_anchor)
        target_end = target_start + plan.count - 1
        kept = []
        for validation, rng in self._column_action_validation_ranges(dst_ws):
            if rng.max_col < target_start or rng.min_col > target_end:
                kept.append((validation, rng))
        source_entries = self._column_action_validation_ranges(src_ws)
        source_map = dict(zip(plan.source_physical_cols, range(target_start, target_end + 1)))
        for validation, rng in source_entries:
            for source_col, destination_col in source_map.items():
                if rng.min_col <= source_col <= rng.max_col:
                    cloned_range = copy.copy(rng)
                    cloned_range.min_col = destination_col
                    cloned_range.max_col = destination_col
                    kept.append((validation, cloned_range))
        self._replace_validation_ranges(dst_ws, kept)

    @staticmethod
    def _column_action_conditional_ranges(ws):
        result = []
        conditional = getattr(ws, "conditional_formatting", None)
        rules_map = getattr(conditional, "_cf_rules", {}) if conditional is not None else {}
        for conditional_range, rules in list(rules_map.items()):
            for cell_range in getattr(getattr(conditional_range, "sqref", None), "ranges", ()) or ():
                result.append((copy.deepcopy(list(rules)), copy.copy(cell_range)))
        return result

    @staticmethod
    def _replace_conditional_ranges(ws, entries):
        conditional = getattr(ws, "conditional_formatting", None)
        if conditional is None:
            return
        try:
            conditional._cf_rules.clear()
        except Exception:
            return
        for rules, cell_range in entries:
            for rule in rules:
                conditional.add(str(cell_range), copy.deepcopy(rule))

    def _copy_column_conditionals(self, src_ws, dst_ws, plan: ColumnBlockActionPlan):
        target_start = int(plan.target_physical_anchor)
        target_end = target_start + plan.count - 1
        kept = []
        for rules, rng in self._column_action_conditional_ranges(dst_ws):
            if rng.max_col < target_start or rng.min_col > target_end:
                kept.append((rules, rng))
        source_map = dict(zip(plan.source_physical_cols, range(target_start, target_end + 1)))
        for rules, rng in self._column_action_conditional_ranges(src_ws):
            for source_col, destination_col in source_map.items():
                if rng.min_col <= source_col <= rng.max_col:
                    cloned_range = copy.copy(rng)
                    cloned_range.min_col = destination_col
                    cloned_range.max_col = destination_col
                    kept.append((rules, cloned_range))
        self._replace_conditional_ranges(dst_ws, kept)

    @staticmethod
    def _column_action_merged_ranges(ws):
        return [CellRange(str(value)) for value in list(ws.merged_cells.ranges)]

    @staticmethod
    def _replace_merged_ranges(ws, ranges):
        for value in list(ws.merged_cells.ranges):
            try:
                ws.unmerge_cells(str(value))
            except Exception:
                pass
        for cell_range in ranges:
            try:
                ws.merge_cells(str(cell_range))
            except Exception:
                pass

    def _copy_column_merges(self, src_ws, dst_ws, plan: ColumnBlockActionPlan):
        target_start = int(plan.target_physical_anchor)
        target_end = target_start + plan.count - 1
        existing = []
        for rng in self._column_action_merged_ranges(dst_ws):
            intersects = not (rng.max_col < target_start or rng.min_col > target_end)
            if intersects and not (target_start <= rng.min_col and rng.max_col <= target_end):
                raise RuntimeError("目标侧存在跨出所选列块的合并单元格，已阻止修改相邻列。")
            if not intersects:
                existing.append(rng)
        source_start = plan.source_physical_cols[0]
        source_end = plan.source_physical_cols[-1]
        delta = target_start - source_start
        for rng in self._column_action_merged_ranges(src_ws):
            intersects = not (rng.max_col < source_start or rng.min_col > source_end)
            if intersects and not (source_start <= rng.min_col and rng.max_col <= source_end):
                raise RuntimeError("源侧存在跨出所选列块的合并单元格，已阻止部分复制。")
            if intersects:
                cloned = copy.copy(rng)
                cloned.shift(col_shift=delta)
                existing.append(cloned)
        self._replace_merged_ranges(dst_ws, existing)

    def _validate_column_merge_boundaries(self, src_ws, dst_ws, plan: ColumnBlockActionPlan):
        if plan.source_physical_cols:
            source_start = plan.source_physical_cols[0]
            source_end = plan.source_physical_cols[-1]
            for rng in self._column_action_merged_ranges(src_ws):
                intersects = not (rng.max_col < source_start or rng.min_col > source_end)
                if intersects and not (source_start <= rng.min_col and rng.max_col <= source_end):
                    raise RuntimeError("源侧存在跨出所选列块的合并单元格，已阻止部分复制。")
        if plan.action_kind == "copy":
            target_start = plan.target_physical_anchor
            target_end = target_start + plan.count - 1
            for rng in self._column_action_merged_ranges(dst_ws):
                intersects = not (rng.max_col < target_start or rng.min_col > target_end)
                if intersects and not (target_start <= rng.min_col and rng.max_col <= target_end):
                    raise RuntimeError("目标侧存在跨出所选列块的合并单元格，已阻止修改相邻列。")

    def _apply_selected_column_block(
        self,
        source_side: str,
        target_side: str | None = None,
        *,
        confirm_unresolved: bool = False,
        _failure_injector=None,
    ) -> ColumnBlockActionPlan:
        direction = {
            "A": "A2B",
            "B": "B2A",
            "BASE": "BASE2A",
        }.get(str(source_side or "").upper(), "")
        if not direction or not self._guard_copy_direction(direction, "列结构操作"):
            raise RuntimeError("当前列结构操作方向不允许写入目标侧")
        if (
            not self._guard_mutation_ready("列结构操作", notify=False)
            and not self._column_undo_model_ready()
        ):
            raise RuntimeError(self._mutation_block_message("列结构操作"))
        plan = self._plan_selected_column_block_action(
            source_side,
            target_side,
            confirm_unresolved=confirm_unresolved,
        )
        selection_before = {
            "block_ordinal": self.selected_column_block_ordinal,
            "logical_range": self.selected_column_logical_range,
            "source_side": self.selected_column_source_side,
            "cell": self._snapshot_explicit_selection_state(),
        }
        accepted_common_before = dict(
            getattr(self, "_accepted_common_insert_sources", {}) or {}
        )
        if plan.action_kind == "retain":
            previous = set(self._retained_column_decisions)
            self._retained_column_decisions.add((plan.logical_start, plan.logical_end, plan.source_side))
            self.app.push_undo({
                "kind": "column_action",
                "sheet": self.sheet,
                "target": "COLUMN_ACTION",
                "plan": plan,
                "snapshot": None,
                "retained_decisions": previous,
                "selection": selection_before,
            })
            self._set_column_action_status(
                f"已保留{self._merge_side_label(plan.source_side)}列块 "
                f"{_excel_column_range_display(plan.logical_start, plan.logical_end)}；工作簿未改动。"
            )
            return plan

        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        if callable(begin_interactive):
            begin_interactive(self)
        snapshot = None
        try:
            self.root.configure(cursor="watch")
            self._set_column_action_status(
                f"正在验证并采用列块 "
                f"{_excel_column_range_display(plan.logical_start, plan.logical_end)}..."
            )
            self.root.update_idletasks()
            source_edit = self._display_ws(plan.source_side, edit=True)
            source_value = self._display_ws(plan.source_side, edit=False)
            target_edit = self._display_ws(plan.target_side, edit=True)
            target_value = self._display_ws(plan.target_side, edit=False)
            # Establish rollback before payload inspection.  Even a read via
            # Worksheet.cell() can materialize an empty Cell, so the payload
            # builder also uses the non-mutating _cells lookup below.
            snapshot = self._column_action_workbook_snapshot(plan.target_side, plan)
            copy_payload = []
            if plan.action_kind in ("insert_copy", "copy"):
                self._validate_column_merge_boundaries(source_edit, target_edit, plan)
                copy_payload = self._prepare_column_copy_payload(
                    plan, source_edit, source_value, target_edit, target_value
                )
            if callable(_failure_injector):
                _failure_injector("after_snapshot", plan)

            if plan.action_kind in ("insert_copy", "delete"):
                # Update formula references while every formula still lives at
                # its pre-action coordinate.  The target worksheet's normal
                # cell shift below then moves formula cells themselves; other
                # worksheets remain stationary while their qualified
                # references track the edited sheet.
                self._apply_column_formula_transformations(
                    target_edit.parent,
                    snapshot.get("formula_transformations") or (),
                )

            for state_name, worksheet in (
                ("edit_sheet", target_edit),
                ("value_sheet", target_value),
            ):
                sheet_snapshot = snapshot[state_name]
                dimensions = self._column_action_dimension_snapshot(worksheet)
                validation_entries = self._column_action_validation_ranges(worksheet)
                conditional_entries = self._column_action_conditional_ranges(worksheet)
                merged_entries = self._column_action_merged_ranges(worksheet)
                if plan.action_kind in ("insert_copy", "delete"):
                    self._replace_merged_ranges(worksheet, ())
                if plan.action_kind == "insert_copy":
                    self._shift_worksheet_columns_fast(
                        worksheet,
                        plan.target_physical_anchor,
                        plan.count,
                        insert=True,
                    )
                    sheet_snapshot["structure_applied"] = True
                    self._restore_shifted_column_dimensions(
                        worksheet, dimensions, plan.target_physical_anchor, plan.count, insert=True
                    )
                    self._replace_validation_ranges(
                        worksheet,
                        self._shift_column_validation_ranges(
                            validation_entries, plan.target_physical_anchor, plan.count, insert=True
                        ),
                    )
                    self._replace_conditional_ranges(
                        worksheet,
                        self._shift_column_validation_ranges(
                            conditional_entries, plan.target_physical_anchor, plan.count, insert=True
                        ),
                    )
                    shifted_merges = self._shift_column_validation_ranges(
                        [(None, rng) for rng in merged_entries],
                        plan.target_physical_anchor,
                        plan.count,
                        insert=True,
                    )
                    self._replace_merged_ranges(worksheet, [rng for _none, rng in shifted_merges])
                elif plan.action_kind == "delete":
                    self._shift_worksheet_columns_fast(
                        worksheet,
                        plan.target_physical_anchor,
                        plan.count,
                        insert=False,
                    )
                    sheet_snapshot["structure_applied"] = True
                    self._restore_shifted_column_dimensions(
                        worksheet, dimensions, plan.target_physical_anchor, plan.count, insert=False
                    )
                    self._replace_validation_ranges(
                        worksheet,
                        self._shift_column_validation_ranges(
                            validation_entries, plan.target_physical_anchor, plan.count, insert=False
                        ),
                    )
                    self._replace_conditional_ranges(
                        worksheet,
                        self._shift_column_validation_ranges(
                            conditional_entries, plan.target_physical_anchor, plan.count, insert=False
                        ),
                    )
                    shifted_merges = self._shift_column_validation_ranges(
                        [(None, rng) for rng in merged_entries],
                        plan.target_physical_anchor,
                        plan.count,
                        insert=False,
                    )
                    self._replace_merged_ranges(worksheet, [rng for _none, rng in shifted_merges])
                if plan.action_kind in ("insert_copy", "delete"):
                    _invalidate_worksheet_read_horizon(worksheet)

            if callable(_failure_injector):
                _failure_injector("after_structure", plan)
            if plan.action_kind in ("insert_copy", "copy"):
                # Payload was validated before mutation, so the following loop
                # cannot discover a late formula/mapping failure halfway through.
                snapshot["edit_sheet"]["copy_started"] = True
                snapshot["value_sheet"]["copy_started"] = True
                self._apply_column_copy_payload(copy_payload, source_edit, target_edit, target_value)
                for offset, source_col in enumerate(plan.source_physical_cols):
                    destination_col = plan.target_physical_anchor + offset
                    self._copy_one_column_dimension(source_edit, target_edit, source_col, destination_col)
                    self._copy_one_column_dimension(source_value, target_value, source_col, destination_col)
                self._copy_column_validations(source_edit, target_edit, plan)
                self._copy_column_validations(source_value, target_value, plan)
                self._copy_column_conditionals(source_edit, target_edit, plan)
                self._copy_column_conditionals(source_value, target_value, plan)
                self._copy_column_merges(source_edit, target_edit, plan)
                self._copy_column_merges(source_value, target_value, plan)
            if callable(_failure_injector):
                _failure_injector("after_copy", plan)

            self.app.remap_manual_cell_operations_for_column_action(
                plan.target_side,
                plan,
            )
            records = plan.operation_records()
            self.app.record_manual_column_operations(plan.target_side, records)
            if plan.target_side == "A":
                self.app.modified_a = True
                self.app.modified_sheets_a.add(self.sheet)
            else:
                self.app.modified_b = True
                self.app.modified_sheets_b.add(self.sheet)
            # Any structural action can move previous logical positions, so
            # retain only the newly proven common insertion.  This state is
            # restored exactly by undo/rollback.
            self._accepted_common_insert_sources = {}
            if (
                plan.action_kind == "insert_copy"
                and {plan.source_side, plan.target_side} == {"A", "B"}
            ):
                self._accepted_common_insert_sources.update(
                    {
                        logical_col: plan.source_side
                        for logical_col in range(
                            int(plan.logical_start),
                            int(plan.logical_end) + 1,
                        )
                    }
                )
            self._mark_column_mapping_stale(
                "column-block-action",
                column_structure=True,
                edited_sides=(plan.target_side,),
            )
            self._invalidate_only_diff_snapshot_cache()
            self._invalidate_render_cache()
            self._pending_column_only_diff_seed = {
                "state": snapshot.get("column_diff_seed"),
                "comparison_state": snapshot.get("column_comparison_state"),
                "plan": plan,
                "mode": "apply",
            }
            self.refresh(row_only=None, rescan=True, column_only=True)
            if callable(_failure_injector):
                _failure_injector("after_refresh", plan)
            self.app.push_undo({
                "kind": "column_action",
                "sheet": self.sheet,
                "target": "COLUMN_ACTION",
                "plan": plan,
                "snapshot": snapshot,
                "selection": selection_before,
                "accepted_common_insert_sources_before": accepted_common_before,
            })
            for logical_col in range(int(plan.logical_start), int(plan.logical_end) + 1):
                marker = getattr(self.app, "mark_structure_difference_processed", None)
                if callable(marker):
                    marker(self.sheet, logical_col, True)
                else:
                    self.app.mark_difference_processed(
                        f"{self.sheet}:structure:{logical_col}", True
                    )
            self.selected_column_block_ordinal = None
            self.selected_column_logical_range = None
            self.selected_column_source_side = None
            self._selected_column_projection_generation = None
            self._apply_column_block_selection_tags()
            self._refresh_column_action_buttons()
            next_block = self._selected_column_block()
            next_text = ""
            if next_block is not None:
                next_start = int(next_block.start_slot_idx) + 1
                next_end = int(next_block.end_slot_idx) + 1
                next_range = _excel_column_range_display(next_start, next_end)
                next_text = f"｜下一项 {next_range} 已选"
            completed_range = _excel_column_range_display(
                plan.logical_start, plan.logical_end
            )
            if next_block is not None:
                summary = f"已处理 {completed_range}{next_text}"
                detail = (
                    f"已完成列块 {completed_range}，"
                    f"{plan.source_side} → {plan.target_side}；可单步撤销。{next_text}"
                )
            else:
                comparison_cache = self._active_column_comparison_cache()
                still_pending = bool(
                    comparison_cache.structural_diff_cols
                    or comparison_cache.unresolved_cols
                )
                if still_pending:
                    summary = f"已处理 {completed_range}｜仍有列差异待检查"
                    detail = (
                        f"已完成列块 {completed_range}，"
                        f"{plan.source_side} → {plan.target_side}；"
                        "仍存在无法自动选择的结构列差异，请检查列标记。"
                    )
                else:
                    summary = f"列结构处理完成｜已处理 {completed_range}"
                    detail = (
                        f"已完成列块 {completed_range}，"
                        f"{plan.source_side} → {plan.target_side}；"
                        "当前 Sheet 已无待处理结构列差异，可单步撤销。"
                    )
            self._set_column_action_status(summary, detail)
            return plan
        except Exception:
            self._accepted_common_insert_sources = accepted_common_before
            if snapshot is not None:
                self._restore_column_action_workbook_snapshot(snapshot)
                self._mark_column_mapping_stale(
                    "column-block-action-rollback",
                    column_structure=True,
                    edited_sides=(plan.target_side,),
                )
                self._pending_column_only_diff_seed = {
                    "state": snapshot.get("column_diff_seed"),
                    "comparison_state": snapshot.get("column_comparison_state"),
                    "plan": plan,
                    "mode": "restore",
                }
                self.refresh(row_only=None, rescan=True, column_only=True)
                # Rendering can intern a default StyleArray on previously
                # unstyled cells.  Reapply the immutable rollback point after
                # caches/UI have been rebuilt so failure rollback stays byte-
                # semantics exact as well as visually exact.
                self._restore_column_action_workbook_snapshot(
                    snapshot, post_refresh_cleanup=True
                )
                self._restore_column_block_selection(selection_before)
            raise
        finally:
            try:
                self.root.configure(cursor="")
            except Exception:
                pass
            if callable(end_interactive):
                end_interactive()

    def _restore_column_block_selection(self, selection):
        selection = selection or {}
        logical_range = selection.get("logical_range")
        source_side = selection.get("source_side") or "LOGICAL"
        if logical_range:
            try:
                self._select_column_block_by_logical_col(int(logical_range[0]), source_side)
            except Exception:
                pass
        else:
            self.selected_column_block_ordinal = None
            self.selected_column_logical_range = None
            self.selected_column_source_side = None
            self._selected_column_projection_generation = None
            self._apply_column_block_selection_tags()
            self._refresh_column_action_buttons()
        cell_selection = selection.get("cell")
        if cell_selection:
            self._restore_explicit_selection_state(cell_selection)
            self._update_cursor_lines()

    def _undo_column_action(self, action: dict) -> bool:
        plan = action.get("plan")
        if (
            not self._guard_mutation_ready("撤销列结构操作", notify=False)
            and not self._column_undo_model_ready()
        ):
            return False
        if plan is not None:
            for logical_col in range(int(plan.logical_start), int(plan.logical_end) + 1):
                marker = getattr(self.app, "mark_structure_difference_processed", None)
                if callable(marker):
                    marker(self.sheet, logical_col, False)
                else:
                    self.app.mark_difference_processed(
                        f"{self.sheet}:structure:{logical_col}", False
                    )
        snapshot = action.get("snapshot")
        if snapshot is None:
            self._retained_column_decisions = set(action.get("retained_decisions") or set())
            self._restore_column_block_selection(action.get("selection"))
            self._set_column_action_status("已撤销保留列块决定。")
            return True
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        if callable(begin_interactive):
            begin_interactive(self)
        try:
            self._restore_column_action_workbook_snapshot(snapshot)
            plan = action.get("plan")
            target_side = plan.target_side if isinstance(plan, ColumnBlockActionPlan) else snapshot.get("target_side")
            self._accepted_common_insert_sources = dict(
                action.get("accepted_common_insert_sources_before") or {}
            )
            self._mark_column_mapping_stale(
                "undo-column-block-action",
                column_structure=True,
                edited_sides=(target_side,),
            )
            self._invalidate_only_diff_snapshot_cache()
            self._invalidate_render_cache()
            self._pending_column_only_diff_seed = {
                "state": snapshot.get("column_diff_seed"),
                "comparison_state": snapshot.get("column_comparison_state"),
                "plan": plan,
                "mode": "restore",
            }
            self.refresh(row_only=None, rescan=True, column_only=True)
            # Keep the workbook state exact even when render-time style inspection
            # materializes a default style on cells that originally had no style.
            self._restore_column_action_workbook_snapshot(
                snapshot, post_refresh_cleanup=True
            )
            self._restore_column_block_selection(action.get("selection") or snapshot.get("selection"))
            self._update_cursor_lines()
            self._set_column_action_status("已完整撤销列结构操作并恢复列映射与选择。")
            return True
        finally:
            if callable(end_interactive):
                end_interactive()

    def _on_column_action_button(self, source_side: str):
        try:
            direction = {
                "A": "A2B",
                "B": "B2A",
                "BASE": "BASE2A",
            }.get(str(source_side or "").upper(), "")
            if not direction or not self._guard_copy_direction(direction, "列结构操作"):
                return
            if (
                not self._guard_mutation_ready("列结构操作", notify=False)
                and not self._column_undo_model_ready()
            ):
                return
            block = self._selected_column_block()
            if block is None:
                return
            projection = self._active_column_projection()
            unresolved = any(
                projection.slot(idx + 1).state == "unresolved"
                or projection.slot(idx + 1).confidence.ambiguous
                for idx in block.slot_indices
            )
            confirmed = False
            if unresolved:
                confirmed = bool(messagebox.askyesno(
                    "确认待定列映射",
                    "该列块映射置信度不足。继续会按当前可见映射执行整个列块，"
                    "普通单元格覆盖仍保持禁用。\n\n"
                    f"原因：{self._column_block_cause_text(block)}\n\n是否明确确认？",
                ))
                if not confirmed:
                    return
            self._apply_selected_column_block(
                source_side,
                confirm_unresolved=confirmed,
            )
        except Exception as exc:
            messagebox.showerror("列结构操作失败", str(exc))

    def _authoritative_revalidate_column_projection_for_action(
        self,
        operation: str,
    ) -> LogicalColumnProjection:
        """Recheck a pending mapping once against live editable workbooks.

        Background-open caches are normally authoritative, but a conservative
        provisional slot can occasionally survive until the first mutation.
        Region actions used to fix that slot only as a side effect of their
        post-edit refresh. Row/cell actions must receive the same revalidation
        before showing a false "mapping pending" error.
        """
        projection = self._ensure_column_projection_current(operation)
        expected_key = self._expected_column_model_cache_key()
        if getattr(self, "_action_column_revalidation_key", None) == expected_key:
            return projection
        edit_ready = getattr(self.app, "_edit_workbooks_ready", None)
        if not callable(edit_ready) or not edit_ready() or self._is_missing_sheet_view():
            return projection

        before_slots = tuple(
            (slot.mine_col, slot.base_col, slot.theirs_col)
            for slot in projection.model.slots
        )
        before_unresolved = tuple(sorted(
            int(col) for col in self._active_column_comparison_cache().unresolved_cols
        ))
        started = time.perf_counter()
        try:
            rebuilt = self._rebuild_column_comparison_cache_from_worksheets(
                self.app.ws_a_val(self.sheet),
                self.app.ws_b_val(self.sheet),
                self.app.ws_a_edit(self.sheet),
                self.app.ws_b_edit(self.sheet),
                ws_base_val=(
                    self.app.ws_base_val(self.sheet)
                    if self._is_three_way_enabled() and getattr(self.app, "has_base", False)
                    else None
                ),
                ws_base_edit=(
                    self.app.ws_base_edit(self.sheet)
                    if self._is_three_way_enabled() and getattr(self.app, "has_base", False)
                    else None
                ),
            )
        except Exception as exc:
            _dlog(
                f"COLUMN_ACTION_REVALIDATE_FAILED sheet={self.sheet} "
                f"operation={operation} err={type(exc).__name__}:{exc}"
            )
            raise RuntimeError(
                f"{operation}前无法复核待定列映射：{exc}"
            ) from exc

        self._action_column_revalidation_key = self._expected_column_model_cache_key()
        after_projection = self._active_column_projection()
        after_slots = tuple(
            (slot.mine_col, slot.base_col, slot.theirs_col)
            for slot in after_projection.model.slots
        )
        after_unresolved = tuple(sorted(int(col) for col in rebuilt.unresolved_cols))
        _dlog(
            f"COLUMN_ACTION_REVALIDATE sheet={self.sheet} operation={operation} "
            f"unresolved={before_unresolved}->{after_unresolved} "
            f"geometry_changed={before_slots != after_slots} "
            f"ms={(time.perf_counter() - started) * 1000.0:.1f}"
        )
        if before_slots != after_slots:
            self._invalidate_render_cache()
            raise RuntimeError(
                f"{operation}前列映射已更新。为确保可见列与写入列一致，"
                "请刷新当前 Sheet，检查列位置后再次执行。"
            )
        return after_projection

    def _action_physical_columns(
        self, direction: str, logical_col: int
    ) -> tuple[int, int] | None:
        projection = self._ensure_column_projection_current("执行覆盖操作")
        slot = projection.slot(logical_col)
        if slot is None:
            return None
        if slot.state == "unresolved" or slot.confidence.ambiguous:
            projection = self._authoritative_revalidate_column_projection_for_action(
                "执行覆盖操作"
            )
            slot = projection.slot(logical_col)
            if slot is None:
                return None
        if slot.state == "unresolved" or slot.confidence.ambiguous:
            raise RuntimeError(
                f"Excel列 {_excel_column_display(logical_col)} 的映射待确认，已阻止覆盖以避免写入错误物理列。"
            )
        side_pair = {
            "A2B": ("A", "B"),
            "B2A": ("B", "A"),
            "BASE2A": ("BASE", "A"),
        }.get(direction)
        if side_pair is None:
            return None
        source_col = projection.physical_col(side_pair[0], logical_col)
        destination_col = projection.physical_col(side_pair[1], logical_col)
        if source_col is None or destination_col is None:
            raise RuntimeError(
                f"Excel列 {_excel_column_display(logical_col)} 在源侧或目标侧不存在；请使用列结构操作，不能按单元格覆盖。"
            )
        return int(source_col), int(destination_col)

    def _filter_row_action_unresolved_blank_noops(
        self,
        direction: str,
        logical_cols,
        source_row: int,
        destination_row: int,
    ) -> set[int]:
        """Drop pending slots that provably perform no write for this row.

        A real column can follow a run of common blank columns (for example
        populated L18 after empty L14-L17).  Those blank signatures remain
        conservatively unresolved for structural column operations, but a row
        value copy must not be blocked when both mapped cells are truly empty:
        leaving an empty destination unchanged is mapping-independent.  Missing
        side mappings, formulas, literals, and blank-to-value/value-to-blank
        changes are retained and continue through the ordinary safety gate.
        """
        cols = {int(col) for col in logical_cols if int(col) > 0}
        side_pair = {
            "A2B": ("A", "B"),
            "B2A": ("B", "A"),
            "BASE2A": ("BASE", "A"),
        }.get(direction)
        if not cols or side_pair is None:
            return cols

        projection = self._ensure_column_projection_current("执行整行覆盖")
        source_side, destination_side = side_pair
        source_val_ws = self.app.ws_for_side(
            source_side, self.sheet, edit=False
        )
        source_edit_ws = self.app.ws_for_side(
            source_side, self.sheet, edit=True
        )
        destination_val_ws = self.app.ws_for_side(
            destination_side, self.sheet, edit=False
        )
        destination_edit_ws = self.app.ws_for_side(
            destination_side, self.sheet, edit=True
        )
        source_width = max(
            (
                int(projection.physical_col(source_side, logical_col) or 0)
                for logical_col in cols
            ),
            default=1,
        )
        destination_width = max(
            (
                int(
                    projection.physical_col(
                        destination_side, logical_col
                    ) or 0
                )
                for logical_col in cols
            ),
            default=1,
        )
        source_value_row = _row_from_cache(
            _read_rows_into_cache(
                source_val_ws, (source_row,), source_width
            ),
            source_row,
            source_width,
        )
        source_edit_row = _row_from_cache(
            _read_rows_into_cache(
                source_edit_ws, (source_row,), source_width
            ),
            source_row,
            source_width,
        )
        destination_value_row = _row_from_cache(
            _read_rows_into_cache(
                destination_val_ws,
                (destination_row,),
                destination_width,
            ),
            destination_row,
            destination_width,
        )
        destination_edit_row = _row_from_cache(
            _read_rows_into_cache(
                destination_edit_ws,
                (destination_row,),
                destination_width,
            ),
            destination_row,
            destination_width,
        )
        skipped = []
        for logical_col in sorted(cols):
            slot = projection.slot(logical_col)
            if (
                slot is None
                or not (
                    slot.state == "unresolved"
                    or slot.confidence.ambiguous
                )
            ):
                continue
            source_col = projection.physical_col(source_side, logical_col)
            destination_col = projection.physical_col(
                destination_side, logical_col
            )
            if source_col is None or destination_col is None:
                continue

            if (
                not _logical_cell_has_content(
                    source_value_row, source_edit_row, source_col
                )
                and not _logical_cell_has_content(
                    destination_value_row,
                    destination_edit_row,
                    destination_col,
                )
            ):
                skipped.append(logical_col)

        if skipped:
            cols.difference_update(skipped)
            _dlog(
                f"OVERWRITE_ROW_SKIP_UNRESOLVED_BLANK_NOOP "
                f"sheet={self.sheet} dir={direction} "
                f"cols={tuple(skipped)}"
            )
        return cols

    def _copy_single_cell_by_pair(
        self,
        pair_idx: int,
        direction: str,
        c: int,
        *,
        _guarded: bool = False,
    ):
        if not self._guard_copy_direction(direction, "单元格覆盖"):
            return False
        if not _guarded and not self._guard_mutation_ready("单元格覆盖"):
            return False
        if _guarded:
            if not self.app._has_active_mutation_owner(self):
                _dlog(
                    f"mutation lease rejected sheet={self.sheet} "
                    "action=单元格覆盖"
                )
                return False
            return self._copy_single_cell_by_pair_impl(pair_idx, direction, c)
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        if callable(begin_interactive):
            begin_interactive(self)
        try:
            return self._copy_single_cell_by_pair_impl(pair_idx, direction, c)
        finally:
            if callable(end_interactive):
                end_interactive()

    def _copy_single_cell_by_pair_impl(
        self,
        pair_idx: int,
        direction: str,
        c: int,
    ):
        if not self._guard_copy_direction(direction, "单元格覆盖"):
            return False
        try:
            if pair_idx is None or pair_idx >= len(self.row_pairs):
                return
            pair = self.row_pairs[pair_idx]
            ra = self._row_for_side(pair, "A")
            rb = self._row_for_side(pair, "B")
            if direction == "A2B":
                if ra is None or rb is None:
                    return
                src_r, dst_r = ra, rb
            elif direction == "BASE2A":
                if ra is None:
                    return
                src_r = self._base_row_for_pair(pair_idx, pair)
                dst_r = ra
            elif direction == "MINE2A":
                # Keep Mine is a conflict-resolution acknowledgement.  It
                # never copies Theirs (or any other side) into the target.
                if not (
                    getattr(self.app, "merge_mode", False)
                    and getattr(self.app, "has_base", False)
                ):
                    return False
                if getattr(self.app, "merge_conflict_mode", False):
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_row(ra or rb, {int(c)})
                marker = getattr(self.app, "mark_difference_pair_processed", None)
                if callable(marker):
                    marker(self.sheet, int(pair_idx), (int(c),), True)
                else:
                    selected_id = getattr(self, "_selected_difference_item_id", None)
                    if selected_id:
                        self.app.mark_difference_processed(selected_id, True)
                return True
            else:
                if rb is None:
                    return
                src_r = rb
                dst_r = ra if ra is not None else rb

            logical_col = int(c)
            physical_cols = self._action_physical_columns(direction, logical_col)
            if physical_cols is None:
                return
            src_col, dst_col = physical_cols

            anchor = self._capture_view_anchor()
            adopted_formula_cache = False
            if direction == "A2B":
                old_edit = self.app.ws_b_edit(self.sheet).cell(row=dst_r, column=dst_col).value
                old_val = self.app.ws_b_val(self.sheet).cell(row=dst_r, column=dst_col).value
                v_edit = self.app.ws_a_edit(self.sheet).cell(row=src_r, column=src_col).value
                v_val = self.app.ws_a_val(self.sheet).cell(row=src_r, column=src_col).value
                new_edit = _copy_edit_value_for_destination(
                    v_val, v_edit, old_edit,
                    src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                )
                formula_mode = self._same_formula_copy_mode(new_edit, old_edit, v_val, old_val)
                if formula_mode == "noop":
                    return
                if formula_mode == "cache":
                    self.app.record_manual_b_formula_cache(self.sheet, dst_r, dst_col, v_val)
                    adopted_formula_cache = True
                else:
                    self.app.clear_manual_b_formula_cache(self.sheet, dst_r, dst_col)
                    _assign_edit_cell_value(
                        self.app.ws_b_edit(self.sheet).cell(row=dst_r, column=dst_col),
                        new_edit,
                    )
                    self.app.record_manual_b_cell(self.sheet, dst_r, dst_col, new_edit)
                self.app.ws_b_val(self.sheet).cell(row=dst_r, column=dst_col).value = v_val
                self.app.modified_b = True
                self.app.modified_sheets_b.add(self.sheet)
                self.app.push_undo({"sheet": self.sheet, "target": "B", "cells": [(dst_r, dst_col, old_edit, old_val)]})
            elif direction == "BASE2A":
                old_edit = self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=dst_col).value
                old_val = self.app.ws_a_val(self.sheet).cell(row=dst_r, column=dst_col).value
                if src_r is None:
                    v_edit = None
                    v_val = None
                else:
                    v_edit = self.app.ws_base_edit(self.sheet).cell(row=src_r, column=src_col).value
                    v_val = self.app.ws_base_val(self.sheet).cell(row=src_r, column=src_col).value
                new_edit = (
                    _copy_edit_value_for_destination(
                        v_val, v_edit, old_edit,
                        src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                    )
                    if src_r is not None else None
                )
                formula_mode = self._same_formula_copy_mode(new_edit, old_edit, v_val, old_val)
                if formula_mode == "noop":
                    return
                if formula_mode == "cache":
                    new_edit = old_edit
                    self.app.record_manual_a_formula_cache(self.sheet, dst_r, dst_col, v_val)
                    adopted_formula_cache = True
                else:
                    _assign_edit_cell_value(self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=dst_col), new_edit)
                    self.app.record_manual_a_cell(self.sheet, dst_r, dst_col, new_edit)
                self.app.ws_a_val(self.sheet).cell(row=dst_r, column=dst_col).value = v_val
                self.app.modified_a = True
                self.app.modified_sheets_a.add(self.sheet)
                self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": [(dst_r, dst_col, old_edit, old_val)]})
            else:
                old_edit = self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=dst_col).value
                old_val = self.app.ws_a_val(self.sheet).cell(row=dst_r, column=dst_col).value
                v_edit = self.app.ws_b_edit(self.sheet).cell(row=src_r, column=src_col).value
                v_val = self.app.ws_b_val(self.sheet).cell(row=src_r, column=src_col).value
                new_edit = _copy_edit_value_for_destination(
                    v_val, v_edit, old_edit,
                    src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                )
                formula_mode = self._same_formula_copy_mode(new_edit, old_edit, v_val, old_val)
                if formula_mode == "noop":
                    return
                if formula_mode == "cache":
                    new_edit = old_edit
                    self.app.record_manual_a_formula_cache(self.sheet, dst_r, dst_col, v_val)
                    adopted_formula_cache = True
                else:
                    _assign_edit_cell_value(self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=dst_col), new_edit)
                    self.app.record_manual_a_cell(self.sheet, dst_r, dst_col, new_edit)
                self.app.ws_a_val(self.sheet).cell(row=dst_r, column=dst_col).value = v_val
                self.app.modified_a = True
                self.app.modified_sheets_a.add(self.sheet)
                self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": [(dst_r, dst_col, old_edit, old_val)]})

            if getattr(self.app, "merge_conflict_mode", False):
                self.app.user_touched_conflicts = True
                self._resolve_conflict_row(dst_r, {logical_col})

            touched_r = ra or rb
            if touched_r is not None:
                self.touched_rows.add(touched_r)
                try:
                    self.app.mark_difference_row_processed(self.sheet, touched_r)
                except Exception:
                    pass
            self._mark_nonstructural_cell_edit(
                "cell-overwrite",
                edited_sides=("B",) if direction == "A2B" else ("A",),
            )
            self._invalidate_render_cache()
            if bool(self.only_diff_var.get()) and self.snapshot_only_diff:
                self._recalc_row_diff_and_update(dst_r)
            self.refresh(row_only=dst_r, rescan=False)
            self._restore_view_anchor(anchor)
            self._update_cursor_lines()
            if adopted_formula_cache:
                self._show_formula_copy_skip_notice(1)
        except Exception as e:
            messagebox.showerror("Error", f"C区覆盖失败：\n{e}")

    def _on_cursor_cmp_click(self, event):
        """Single-click in C区: map clicked cell back to current pair/column selection."""
        try:
            idx = self.cursor_cmp.index(f"@{event.x},{event.y}")
            line_no = int(str(idx).split(".")[0])
            char_no = int(str(idx).split(".")[1])
        except Exception:
            return "break"

        try:
            line_text = self.cursor_cmp.get(f"{line_no}.0", f"{line_no}.end")
        except Exception:
            line_text = ""
        spans = self._spans_for_line(line_text)
        hit_col = None
        hit_char = 0
        for c, (s0, e0) in spans.items():
            if s0 <= char_no < e0:
                hit_col = c
                hit_char = s0
                break
        if hit_col is None:
            return "break"

        # Resolve current pair/line in the main panes.
        pair_idx = self.resolved_pair_idx_for_c_area()

        target_line = None
        try:
            if pair_idx is not None and pair_idx in self.row_to_line:
                target_line = int(self.row_to_line.get(pair_idx))
        except Exception:
            target_line = None
        if target_line is None:
            target_line = 1
        try:
            target_line = max(1, min(int(target_line), max(1, len(self.display_rows))))
        except Exception:
            target_line = 1

        saved_x = 0.0
        try:
            saved_x = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            saved_x = 0.0

        target_idx = f"{target_line}.{max(0, int(hit_char))}"
        for w in (self.left, self.base, self.right):
            try:
                w.mark_set("insert", target_idx)
            except Exception:
                pass

        try:
            self._highlight_selected_line(target_line)
            self.selected_pair_idx = self._pair_idx_for_line(target_line)
            pair = self._pair_for_line(target_line)
            self.hover_pair_idx = self._normalize_pair_idx(self.selected_pair_idx)
            self.hover_col_idx = int(hit_col)
            self.hover_side = "C"
            self.selected_excel_row_a = self._row_for_side(pair, "A")
            self.selected_excel_row_b = self._row_for_side(pair, "B")
            self.selected_excel_row = self.selected_excel_row_a or self.selected_excel_row_b
        except Exception:
            pass

        # Store C selection so _update_cursor_lines can render visible clicked-cell highlight.
        self._cursor_cmp_sel_col = int(hit_col)
        self._cursor_cmp_sel_line = int(line_no)
        self._set_main_selected_cell(target_line, hit_col)

        # Re-render C block and keep x aligned.
        self._update_cursor_lines()
        try:
            self._sync_main_x_to_frac(saved_x)
            self._sync_c_x_to_frac(saved_x)
        except Exception:
            pass
        self._update_diff_nav_state()
        return "break"

    def _on_cursor_cmp_double_click(self, event):
        try:
            idx = self.cursor_cmp.index(f"@{event.x},{event.y}")
            line_no = int(str(idx).split(".")[0])
            char_no = int(str(idx).split(".")[1])
        except Exception:
            return

        pair_idx = self.resolved_pair_idx_for_c_area()
        if pair_idx is None or pair_idx >= len(self.row_pairs):
            return

        is_three = self._is_three_way_enabled()
        if is_three:
            if line_no == 1:
                direction = "BASE2A"
                diff_cols = self._visual_diff_cols_for_pair(pair_idx)
            elif line_no == 3:
                direction = "B2A"
                diff_cols = set(self.pair_diff_cols.get(pair_idx, set()))
            else:
                return
        else:
            if line_no == 2:
                direction = "B2A"
                diff_cols = set(self.pair_diff_cols.get(pair_idx, set()))
            else:
                return
        if not diff_cols:
            return

        line_text = self.cursor_cmp.get(f"{line_no}.0", f"{line_no}.end")
        spans = self._spans_for_line(line_text)
        hit_col = None
        for c, (s, e) in spans.items():
            if s <= char_no < e:
                hit_col = c
                break
        if hit_col is None or hit_col not in diff_cols:
            return
        # C-area double-click is navigation/details only.  Mutating the
        # workbook is reserved for the explicit direction-labelled actions.
        self.selected_pair_idx = int(pair_idx)
        self._cursor_cmp_sel_col = int(hit_col)
        self._cursor_cmp_sel_line = int(line_no)
        try:
            display_line = self.row_to_line.get(int(pair_idx), int(pair_idx) + 1)
            self._set_main_selected_cell(display_line, hit_col)
            self._select_line(display_line)
            self._update_cursor_lines()
            self._update_diff_nav_state()
        except Exception:
            pass
        return "break"

    def _set_copy_scope_mode(self, mode: str):
        mode_norm = str(mode or "").strip().lower()
        mode_norm = mode_norm if mode_norm in ("row", "region", "global") else "row"
        self._copy_scope_mode = mode_norm
        try:
            self._copy_scope_var.set(mode_norm)
        except Exception:
            pass
        self._refresh_copy_scope_buttons()

    def _refresh_copy_scope_buttons(self):
        if self._is_missing_sheet_view():
            left_text = self._format_direction_action(self._left_copy_direction, "table")
            right_text = self._format_direction_action(self._right_copy_direction, "table")
            try:
                self.use_left_btn.configure(text=left_text)
            except Exception:
                pass
            try:
                self.use_right_btn.configure(text=right_text)
            except Exception:
                pass
            return
        mode = getattr(self, "_copy_scope_mode", "row")
        left_text = self._format_direction_action(self._left_copy_direction, mode)
        right_text = self._format_direction_action(self._right_copy_direction, mode)
        try:
            self.use_left_btn.configure(text=left_text)
        except Exception:
            pass
        try:
            self.use_right_btn.configure(text=right_text)
        except Exception:
            pass

    def _run_copy_action_by_mode(self, direction: str):
        if not self._guard_copy_direction(direction, "采用所选内容"):
            return False
        if not self._guard_mutation_ready("采用所选内容"):
            return
        if self._is_missing_sheet_view():
            self._copy_missing_sheet(direction, _guarded=True)
            return
        mode = getattr(self, "_copy_scope_mode", "row")
        if mode == "region":
            self._copy_selected_region(direction)
        elif mode == "global":
            self._copy_all_safe_sheet_differences(direction)
        else:
            self._copy_selected_row(direction)

    def _show_global_apply_feedback(self, text: str, *, reason: str):
        """Report a global-mode refusal without hiding the no-write guarantee."""
        message = f"全局模式未写入：{text}"
        try:
            self.info.configure(text=message)
        except Exception:
            pass
        _dlog(
            f"GLOBAL_APPLY_BLOCKED sheet={self.sheet} reason={reason} text={message}"
        )

    def _global_column_cause_text(self, logical_col: int) -> str:
        """Return the user-facing cause for one unresolved logical column."""
        slot_index = int(logical_col) - 1
        try:
            projection = self._active_column_projection()
            for block in projection.model.blocks:
                if slot_index in block.slot_indices:
                    return self._column_block_cause_text(block)
        except Exception:
            pass
        return "列映射待确认"

    def _collect_global_ambiguous_diff_details(
        self,
        direction: str,
        diff_map: dict[int, set[int]],
        projection: LogicalColumnProjection,
    ) -> tuple[dict[str, object], ...]:
        """Collect unresolved columns that actually contain exact differences.

        An unresolved slot with equal source/destination cells is harmless for
        value-level global replacement.  Only slots present in the exact diff
        map are blockers, and the returned records are deliberately small so
        they can be shown in a modal dialog without rendering the whole sheet.
        """
        cache = self._active_column_comparison_cache()
        unresolved = set(int(col) for col in cache.unresolved_cols)
        if not unresolved:
            return ()
        source_side, destination_side = {
            "A2B": ("A", "B"),
            "B2A": ("B", "A"),
            "BASE2A": ("BASE", "A"),
        }.get(str(direction or ""), (None, None))
        if source_side is None or destination_side is None:
            return ()
        details: dict[int, dict[str, object]] = {}
        for pair_idx, raw_cols in (diff_map or {}).items():
            ambiguous_cols = sorted(
                int(col)
                for col in (raw_cols or ())
                if int(col) > 0 and int(col) in unresolved
            )
            if not ambiguous_cols:
                continue
            try:
                pair = self.row_pairs[int(pair_idx)]
            except (IndexError, TypeError, ValueError):
                pair = None
            source_row = (
                self._base_row_for_pair(int(pair_idx), pair)
                if source_side == "BASE"
                else self._row_for_side(pair, source_side)
            )
            destination_row = self._row_for_side(pair, destination_side)
            for logical_col in ambiguous_cols:
                item = details.setdefault(
                    logical_col,
                    {
                        "logical_col": logical_col,
                        "cause": self._global_column_cause_text(logical_col),
                        "source_col": projection.physical_col(source_side, logical_col),
                        "destination_col": projection.physical_col(destination_side, logical_col),
                        "count": 0,
                        "samples": [],
                    },
                )
                item["count"] = int(item.get("count", 0)) + 1
                samples = item.setdefault("samples", [])
                if len(samples) >= 4:
                    continue
                source_col = projection.physical_col(source_side, logical_col)
                destination_col = projection.physical_col(destination_side, logical_col)
                if source_row is not None and destination_row is not None:
                    source_text = (
                        f"{source_side}!{_excel_column_display(source_col)}{int(source_row)}"
                        if source_col is not None
                        else f"{source_side}!缺列"
                    )
                    destination_text = (
                        f"{destination_side}!{_excel_column_display(destination_col)}{int(destination_row)}"
                        if destination_col is not None
                        else f"{destination_side}!缺列"
                    )
                    samples.append(f"{source_text} ↔ {destination_text}")
                else:
                    samples.append(
                        f"行映射 {pair_idx}（{source_side}行={source_row or '-'}，"
                        f"{destination_side}行={destination_row or '-'}）"
                    )
        return tuple(details[col] for col in sorted(details))

    def _confirm_global_sheet_overwrite(
        self,
        source_side: str,
        target_side: str,
    ) -> bool:
        source_label = self._merge_side_label(source_side)
        target_label = self._merge_side_label(target_side)
        return bool(
            messagebox.askyesno(
                "确认整 Sheet 覆盖",
                (
                    f"即将使用{source_label}整张 Sheet 覆盖{target_label}。\n\n"
                    "这是高风险操作，将替换目标 Sheet 的全部内容和结构，"
                    "包括目标侧独有的单元格、行列、公式、样式、合并区域、"
                    "批注、超链接、数据验证、隐藏状态和布局。\n\n"
                    "确认继续吗？"
                ),
                parent=self.root,
            )
        )

    def _ask_global_ambiguous_action(
        self,
        direction: str,
        details: tuple[dict[str, object], ...],
    ) -> str:
        """Ask how to proceed after a real ambiguous global difference.

        The return value is ``cancel``, ``A2B_SHEET`` or ``B2A_SHEET``.  A
        separate destructive confirmation is required for either Sheet copy.
        3-way callers are intentionally handled by the existing fail-closed
        feedback path and never reach this dialog.
        """
        if self._is_three_way_enabled() or not details:
            return "cancel"
        result = {"action": "cancel"}
        dialog = tk.Toplevel(self.root)
        dialog.title("全局替换遇到歧义列")
        dialog.transient(self.root)
        dialog.resizable(True, True)
        dialog.minsize(720, 420)

        body = ttk.Frame(dialog, padding=14)
        body.pack(fill="both", expand=True)
        ttk.Label(
            body,
            text=f"Sheet“{self.sheet}”无法安全执行单元格级全局替换",
            font=("Segoe UI", 10, "bold"),
        ).pack(anchor="w")
        ttk.Label(
            body,
            text=(
                "以下列既无法唯一确认左右对应关系，又存在真实差异。"
                "工具不会猜测目标物理列。请返回检查，或明确选择整 Sheet 覆盖。"
            ),
            justify="left",
            wraplength=680,
        ).pack(anchor="w", pady=(7, 8))

        text = tk.Text(body, height=13, width=88, wrap="word")
        text.pack(fill="both", expand=True)
        lines = []
        for item in details:
            logical_label = _excel_column_display(int(item["logical_col"]))
            source_col = item.get("source_col")
            destination_col = item.get("destination_col")
            physical = (
                f"左右物理列 {source_col or '-'} ↔ {destination_col or '-'}"
            )
            samples = "、".join(str(value) for value in item.get("samples") or ())
            if samples:
                samples = f"；示例：{samples}"
            lines.append(
                f"列 {logical_label}：{item.get('cause') or '列映射待确认'}；"
                f"{physical}；差异 {int(item.get('count', 0))} 个{samples}"
            )
        text.insert("1.0", "\n".join(lines))
        text.configure(state="disabled")

        ttk.Label(
            body,
            text="整 Sheet 覆盖会丢弃目标侧当前 Sheet 的独有内容，执行前还会再次确认。",
            foreground="#B3261E",
            justify="left",
            wraplength=680,
        ).pack(anchor="w", pady=(9, 0))

        buttons = ttk.Frame(body)
        buttons.pack(fill="x", pady=(12, 0))

        def _close():
            result["action"] = "cancel"
            try:
                dialog.destroy()
            except Exception:
                pass

        def _choose(action: str, source_side: str, target_side: str):
            if not self._confirm_global_sheet_overwrite(source_side, target_side):
                return
            result["action"] = action
            try:
                dialog.destroy()
            except Exception:
                pass

        ttk.Button(buttons, text="返回检查", command=_close).pack(side="right")
        ttk.Button(
            buttons,
            text="左侧整 Sheet 覆盖右侧",
            command=lambda: _choose("A2B_SHEET", "A", "B"),
        ).pack(side="right", padx=(0, 8))
        ttk.Button(
            buttons,
            text="右侧整 Sheet 覆盖左侧",
            command=lambda: _choose("B2A_SHEET", "B", "A"),
        ).pack(side="right", padx=(0, 8))
        dialog.protocol("WM_DELETE_WINDOW", _close)
        dialog.bind("<Escape>", lambda _event: _close())
        try:
            dialog.update_idletasks()
            rx = self.root.winfo_rootx()
            ry = self.root.winfo_rooty()
            rw = self.root.winfo_width()
            rh = self.root.winfo_height()
            dw = dialog.winfo_width()
            dh = dialog.winfo_height()
            dialog.geometry(f"+{max(0, rx + (rw - dw) // 2)}+{max(0, ry + (rh - dh) // 2)}")
        except Exception:
            pass
        dialog.grab_set()
        try:
            dialog.focus_force()
        except Exception:
            pass
        dialog.wait_window()
        return str(result.get("action") or "cancel")

    def _capture_global_sheet_copy_snapshot(self, target_side: str) -> dict[str, object]:
        """Capture target Sheet and operation bookkeeping for one-step undo."""
        target_side = str(target_side or "").upper()
        target_val_wb, target_edit_wb = self.app._workbooks_for_side(target_side)
        target_index = None
        edit_snapshot = None
        value_snapshot = None
        if target_edit_wb is not None and self.sheet in target_edit_wb.sheetnames:
            target_index = int(target_edit_wb.sheetnames.index(self.sheet))
            snapshot_wb = Workbook()
            snapshot_wb.remove(snapshot_wb.active)
            _create_sheet_from_source(snapshot_wb, target_edit_wb[self.sheet], self.sheet, index=0)
            edit_snapshot = snapshot_wb
        if target_val_wb is not None and self.sheet in target_val_wb.sheetnames:
            snapshot_wb = Workbook()
            snapshot_wb.remove(snapshot_wb.active)
            _create_sheet_from_source(snapshot_wb, target_val_wb[self.sheet], self.sheet, index=0)
            value_snapshot = snapshot_wb
        return {
            "sheet": self.sheet,
            "target_side": target_side,
            "target_index": target_index,
            "edit_snapshot": edit_snapshot,
            "value_snapshot": value_snapshot,
            "manual_sheet_ops": copy.deepcopy(list(self.app.manual_sheet_ops)),
            "modified_a": bool(self.app.modified_a),
            "modified_b": bool(self.app.modified_b),
            "modified_sheets_a": set(self.app.modified_sheets_a),
            "modified_sheets_b": set(self.app.modified_sheets_b),
            "manual_cell_ops": copy.deepcopy(
                dict(self.app.manual_a_cell_ops if target_side == "A" else self.app.manual_b_cell_ops)
            ),
            "manual_formula_cache_ops": copy.deepcopy(
                dict(
                    self.app.manual_a_formula_cache_ops
                    if target_side == "A"
                    else self.app.manual_b_formula_cache_ops
                )
            ),
            "manual_row_ops": copy.deepcopy(
                list(self.app.manual_a_row_ops if target_side == "A" else self.app.manual_b_row_ops)
            ),
            "manual_column_ops": copy.deepcopy(
                list(
                    self.app.manual_a_column_ops
                    if target_side == "A"
                    else self.app.manual_b_column_ops
                )
            ),
            "touched_rows": set(self.touched_rows),
        }

    def _discard_global_sheet_target_ops(self, target_side: str):
        """Make a confirmed Sheet replacement authoritative at save time."""
        target_side = str(target_side or "").upper()
        if target_side == "A":
            cell_ops = self.app.manual_a_cell_ops
            formula_cache_ops = self.app.manual_a_formula_cache_ops
            row_ops = self.app.manual_a_row_ops
            column_ops = self.app.manual_a_column_ops
        else:
            cell_ops = self.app.manual_b_cell_ops
            formula_cache_ops = self.app.manual_b_formula_cache_ops
            row_ops = self.app.manual_b_row_ops
            column_ops = self.app.manual_b_column_ops
        for op_map in (cell_ops, formula_cache_ops):
            for key in list(op_map):
                if key[0] == self.sheet:
                    op_map.pop(key, None)
        row_ops[:] = [op for op in row_ops if str(op.get("sheet") or "") != self.sheet]
        column_ops[:] = [op for op in column_ops if str(op.get("sheet") or "") != self.sheet]
        self.app.manual_sheet_ops[:] = [
            op
            for op in self.app.manual_sheet_ops
            if not (
                str(op.get("sheet") or "") == self.sheet
                and str(op.get("target_side") or "").upper() == target_side
            )
        ]

    def _restore_global_sheet_copy_snapshot(self, snapshot: dict[str, object]):
        """Restore a pre-overwrite Sheet and all target-side operation state."""
        if not isinstance(snapshot, dict) or snapshot.get("sheet") != self.sheet:
            raise RuntimeError("整 Sheet 覆盖撤销快照无效")
        target_side = str(snapshot.get("target_side") or "").upper()
        target_val_wb, target_edit_wb = self.app._workbooks_for_side(target_side)
        target_index = snapshot.get("target_index")

        def _restore_one(dst_wb, source_wb):
            if dst_wb is None:
                return
            _remove_sheet_if_exists(dst_wb, self.sheet)
            if source_wb is not None and self.sheet in source_wb.sheetnames:
                _create_sheet_from_source(
                    dst_wb,
                    source_wb[self.sheet],
                    self.sheet,
                    index=(int(target_index) if target_index is not None else None),
                )

        _restore_one(target_edit_wb, snapshot.get("edit_snapshot"))
        _restore_one(target_val_wb, snapshot.get("value_snapshot"))
        self.app.manual_sheet_ops[:] = copy.deepcopy(
            list(snapshot.get("manual_sheet_ops") or [])
        )
        if target_side == "A":
            self.app.manual_a_cell_ops.clear()
            self.app.manual_a_cell_ops.update(copy.deepcopy(dict(snapshot.get("manual_cell_ops") or {})))
            self.app.manual_a_formula_cache_ops.clear()
            self.app.manual_a_formula_cache_ops.update(
                copy.deepcopy(dict(snapshot.get("manual_formula_cache_ops") or {}))
            )
            self.app.manual_a_row_ops[:] = copy.deepcopy(list(snapshot.get("manual_row_ops") or []))
            self.app.manual_a_column_ops[:] = copy.deepcopy(list(snapshot.get("manual_column_ops") or []))
            self.app.modified_a = bool(snapshot.get("modified_a", False))
        else:
            self.app.manual_b_cell_ops.clear()
            self.app.manual_b_cell_ops.update(copy.deepcopy(dict(snapshot.get("manual_cell_ops") or {})))
            self.app.manual_b_formula_cache_ops.clear()
            self.app.manual_b_formula_cache_ops.update(
                copy.deepcopy(dict(snapshot.get("manual_formula_cache_ops") or {}))
            )
            self.app.manual_b_row_ops[:] = copy.deepcopy(list(snapshot.get("manual_row_ops") or []))
            self.app.manual_b_column_ops[:] = copy.deepcopy(list(snapshot.get("manual_column_ops") or []))
            self.app.modified_b = bool(snapshot.get("modified_b", False))
        self.app.modified_sheets_a.clear()
        self.app.modified_sheets_a.update(set(snapshot.get("modified_sheets_a") or set()))
        self.app.modified_sheets_b.clear()
        self.app.modified_sheets_b.update(set(snapshot.get("modified_sheets_b") or set()))
        self.touched_rows.clear()
        self.touched_rows.update(set(snapshot.get("touched_rows") or set()))
        self.app._refresh_sheet_catalog()
        self._mark_column_mapping_stale(
            "undo-sheet-copy",
            row_structure=True,
            column_structure=True,
            edited_sides=(target_side,),
        )
        self._data_ready = False
        self._bounds_checked = False
        self._invalidate_only_diff_snapshot_cache()
        self._invalidate_render_cache()
        self._update_sheet_role_labels()
        self.app.refresh_sheet_nav()
        self.refresh(row_only=None, rescan=True)
        self._update_cursor_lines()

    def _apply_global_sheet_overwrite(self, source_side: str, target_side: str) -> bool:
        """Replace the target Sheet after an explicit ambiguity decision."""
        if self._is_three_way_enabled():
            return False
        if not self._guard_mutation_ready("整 Sheet 覆盖"):
            return False
        source_side = str(source_side or "").upper()
        target_side = str(target_side or "").upper()
        if source_side not in ("A", "B") or target_side not in ("A", "B"):
            return False
        snapshot = self._capture_global_sheet_copy_snapshot(target_side)
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        interactive_started = False
        previous_bg_suppression = bool(getattr(self, "_suppress_bg_apply", False))
        started = time.perf_counter()
        try:
            if callable(begin_interactive):
                begin_interactive(self)
                interactive_started = True
            self._suppress_bg_apply = True
            self._discard_global_sheet_target_ops(target_side)
            self.info.configure(
                text=(
                    f"正在使用{self._merge_side_label(source_side)}整 Sheet 覆盖"
                    f"{self._merge_side_label(target_side)}..."
                )
            )
            self.root.configure(cursor="watch")
            self.root.update_idletasks()
            self.app._copy_sheet_between_sides(self.sheet, source_side, target_side)
            self._mark_column_mapping_stale(
                "global-sheet-overwrite",
                row_structure=True,
                column_structure=True,
                edited_sides=(target_side,),
            )
            self._data_ready = False
            self._bounds_checked = False
            self._invalidate_only_diff_snapshot_cache()
            self._invalidate_render_cache()
            self._update_sheet_role_labels()
            self.app.refresh_sheet_nav()
            self.refresh(row_only=None, rescan=True)
            self._update_cursor_lines()
            self.app.push_undo({
                "kind": "global_sheet_copy",
                "sheet": self.sheet,
                "target": target_side,
                "source": source_side,
                "snapshot": snapshot,
            })
            elapsed = time.perf_counter() - started
            self.info.configure(
                text=(
                    f"已使用{self._merge_side_label(source_side)}整 Sheet 覆盖"
                    f"{self._merge_side_label(target_side)}，耗时 {elapsed:.1f} 秒"
                )
            )
            _dlog(
                f"GLOBAL_SHEET_COPY_DONE sheet={self.sheet} source={source_side} "
                f"target={target_side} ms={elapsed * 1000.0:.1f}"
            )
            return True
        except Exception as exc:
            try:
                self._restore_global_sheet_copy_snapshot(snapshot)
            except Exception as rollback_error:
                _dlog(
                    f"CRITICAL global Sheet rollback failed sheet={self.sheet} "
                    f"err={rollback_error}"
                )
            _dlog(
                f"GLOBAL_SHEET_COPY_ERROR sheet={self.sheet} source={source_side} "
                f"target={target_side} err={type(exc).__name__}:{exc}"
            )
            messagebox.showerror(
                "整 Sheet 覆盖失败",
                f"整 Sheet 覆盖失败，已尝试完整还原：\n{exc}",
                parent=self.root,
            )
            return False
        finally:
            self._suppress_bg_apply = previous_bg_suppression
            if interactive_started and callable(end_interactive):
                end_interactive()
            try:
                self.root.configure(cursor="")
            except Exception:
                pass

    def _capture_global_safe_apply_snapshot(
        self,
        direction: str,
        candidates: list[tuple[int, tuple[int, ...]]],
        projection: LogicalColumnProjection,
    ) -> dict:
        """Capture every writable target before the first global write.

        This snapshot is intentionally broader than row-level undo cells: it
        records manual-edit maps, dirty flags, touched rows, and conflict state
        as well.  A failure after a row has partially written can therefore be
        restored without relying on that row's local exception path.
        """
        target = "B" if direction == "A2B" else "A"
        ws_edit = self.app.ws_b_edit(self.sheet) if target == "B" else self.app.ws_a_edit(self.sheet)
        ws_val = self.app.ws_b_val(self.sheet) if target == "B" else self.app.ws_a_val(self.sheet)
        seen = set()
        cells = []
        for pair_idx, cols in candidates:
            pair = self.row_pairs[int(pair_idx)]
            row = self._row_for_side(pair, target)
            if row is None:
                raise RuntimeError("全局覆盖预检发现目标行缺失")
            for logical_col in cols:
                physical_col = projection.physical_col(target, int(logical_col))
                if physical_col is None:
                    raise RuntimeError(
                        f"全局覆盖预检发现 {_excel_column_display(logical_col)} 目标列缺失"
                    )
                key = (int(row), int(physical_col))
                if key in seen:
                    continue
                seen.add(key)
                cells.append((
                    key[0],
                    key[1],
                    copy.deepcopy(ws_edit.cell(row=key[0], column=key[1]).value),
                    copy.deepcopy(ws_val.cell(row=key[0], column=key[1]).value),
                ))
        if target == "A":
            manual_cells = self.app.manual_a_cell_ops
            manual_cache = self.app.manual_a_formula_cache_ops
            manual_rows = self.app.manual_a_row_ops
            modified = bool(self.app.modified_a)
            modified_sheets = set(self.app.modified_sheets_a)
        else:
            manual_cells = self.app.manual_b_cell_ops
            manual_cache = self.app.manual_b_formula_cache_ops
            manual_rows = self.app.manual_b_row_ops
            modified = bool(self.app.modified_b)
            modified_sheets = set(self.app.modified_sheets_b)
        conflict_map = getattr(self.app, "merge_conflict_cells_by_sheet", None)
        conflict_present = bool(isinstance(conflict_map, dict) and self.sheet in conflict_map)
        return {
            "sheet": self.sheet,
            "target": target,
            "cells": cells,
            "manual_cells": copy.deepcopy(dict(manual_cells)),
            "manual_cache": copy.deepcopy(dict(manual_cache)),
            "manual_rows": copy.deepcopy(list(manual_rows)),
            "modified": modified,
            "modified_sheets": modified_sheets,
            "touched_rows": set(self.touched_rows),
            "formula_skips_pending": int(getattr(self, "_formula_copy_skips_pending", 0)),
            "conflict_sheet_present": conflict_present,
            "conflict_sheet_before": copy.deepcopy(
                conflict_map.get(self.sheet) if conflict_present else None
            ),
            "user_touched_conflicts_before": bool(
                getattr(self.app, "user_touched_conflicts", False)
            ),
        }

    def _restore_global_safe_apply_snapshot(
        self,
        snapshot: dict,
        *,
        restore_conflicts: bool = True,
    ) -> set[int]:
        """Restore a global snapshot for both undo and in-flight rollback."""
        if not isinstance(snapshot, dict) or snapshot.get("sheet") != self.sheet:
            raise RuntimeError("全局覆盖快照无效或不属于当前 Sheet")
        target = str(snapshot.get("target") or "")
        if target == "A":
            ws_edit = self.app.ws_a_edit(self.sheet)
            ws_val = self.app.ws_a_val(self.sheet)
            manual_cells = self.app.manual_a_cell_ops
            manual_cache = self.app.manual_a_formula_cache_ops
            manual_rows = self.app.manual_a_row_ops
            modified_sheets = self.app.modified_sheets_a
        elif target == "B":
            ws_edit = self.app.ws_b_edit(self.sheet)
            ws_val = self.app.ws_b_val(self.sheet)
            manual_cells = self.app.manual_b_cell_ops
            manual_cache = self.app.manual_b_formula_cache_ops
            manual_rows = self.app.manual_b_row_ops
            modified_sheets = self.app.modified_sheets_b
        else:
            raise RuntimeError("全局覆盖快照缺少目标侧")
        rows = set()
        for row, col, old_edit, old_val in snapshot.get("cells") or ():
            row, col = int(row), int(col)
            _assign_edit_cell_value(
                ws_edit.cell(row=row, column=col),
                _choose_edit_value(old_val, old_edit),
            )
            ws_val.cell(row=row, column=col).value = old_val
            rows.add(row)
        manual_cells.clear()
        manual_cells.update(copy.deepcopy(dict(snapshot.get("manual_cells") or {})))
        manual_cache.clear()
        manual_cache.update(copy.deepcopy(dict(snapshot.get("manual_cache") or {})))
        manual_rows[:] = copy.deepcopy(list(snapshot.get("manual_rows") or ()))
        if target == "A":
            self.app.modified_a = bool(snapshot.get("modified", False))
        else:
            self.app.modified_b = bool(snapshot.get("modified", False))
        modified_sheets.clear()
        modified_sheets.update(set(snapshot.get("modified_sheets") or ()))
        self.touched_rows.clear()
        self.touched_rows.update(set(snapshot.get("touched_rows") or ()))
        self._formula_copy_skips_pending = int(snapshot.get("formula_skips_pending", 0))
        if restore_conflicts:
            self._restore_global_conflict_snapshot(
                bool(snapshot.get("conflict_sheet_present", False)),
                snapshot.get("conflict_sheet_before"),
                bool(snapshot.get("user_touched_conflicts_before", False)),
            )
        return rows

    def _restore_global_conflict_snapshot(
        self,
        sheet_present: bool,
        sheet_before,
        user_touched_before: bool,
    ):
        """Restore only this Sheet's conflict bookkeeping without auto-save."""
        conflict_map = getattr(self.app, "merge_conflict_cells_by_sheet", None)
        if not isinstance(conflict_map, dict):
            return
        if sheet_present:
            conflict_map[self.sheet] = copy.deepcopy(sheet_before or {})
        else:
            conflict_map.pop(self.sheet, None)
        self.app.user_touched_conflicts = bool(user_touched_before)

    def _retain_all_difference_items(self) -> bool:
        """Mark every pending DifferenceItem in this Sheet as retained.

        Global retain is deliberately metadata-only: it does not touch either
        editable workbook, column projection generation or structural caches.
        One batch ``difference_state`` action makes the acknowledgement fully
        undoable while keeping the browser rows visible and marked.
        """
        if not (
            getattr(self.app, "merge_mode", False)
            and getattr(self.app, "has_base", False)
        ):
            self._show_global_apply_feedback(
                "‘保留 Mine’仅适用于有效的三方合并视图。",
                reason="retain-invalid-mode",
            )
            return False
        try:
            self.app.refresh_difference_browser()
        except Exception:
            pass
        ids = tuple(
            item.id
            for item in getattr(self.app, "difference_items", ())
            if item.sheet == self.sheet and not item.processed
        )
        if not ids:
            try:
                self.info.configure(text="当前 Sheet 没有待处理差异；未写入任何数据。")
            except Exception:
                pass
            return False
        marker = getattr(self.app, "mark_difference_items_processed", None)
        marked = marker(ids, True) if callable(marker) else ids
        if not marked:
            return False
        self.app.push_undo({
            "kind": "difference_state",
            "sheet": self.sheet,
            "item_ids": tuple(marked),
        })
        try:
            self.info.configure(
                text=(
                    f"已保留{self.role_presentation.left}，未写入任何数据；"
                    f"已标记 {len(marked)} 项为已处理。"
                )
            )
        except Exception:
            pass
        return True

    def _copy_all_safe_sheet_differences(self, direction: str) -> bool:
        """Atomically apply every proved cell diff in this Sheet.

        This mode deliberately consumes the complete exact diff maps rather
        than the rendered/only-diff list.  It owns ordinary mapped cells only:
        a stale projection, any structural row/column difference, or an
        ambiguous slot rejects the entire command before the first write.
        """
        if not self._guard_copy_direction(direction, "全局覆盖"):
            return False
        if not self._guard_mutation_ready("全局覆盖"):
            return False
        if str(direction or "").upper() == "MINE2A":
            return self._retain_all_difference_items()
        side_pair = {
            "A2B": ("A", "B"),
            "B2A": ("B", "A"),
            "BASE2A": ("BASE", "A"),
        }.get(str(direction or ""))
        if side_pair is None:
            self._show_global_apply_feedback("当前方向不支持全局模式。", reason="direction")
            return False
        if self._is_missing_sheet_view():
            self._show_global_apply_feedback("缺失 Sheet 必须使用整 Sheet 操作。", reason="missing-sheet")
            return False
        if self._is_three_way_enabled() and direction == "A2B":
            self._show_global_apply_feedback(
                "三方视图的左侧全局操作必须使用 Base→A 方向。",
                reason="invalid-three-way-direction",
            )
            return False
        if not self._is_three_way_enabled() and direction == "BASE2A":
            self._show_global_apply_feedback(
                "双向视图不支持 Base→A 全局方向。",
                reason="invalid-two-way-direction",
            )
            return False
        if not self._column_mapping_is_current():
            self._show_global_apply_feedback("列映射已过期（STALE），请刷新后重试。", reason="stale")
            return False
        if not bool(getattr(self, "_pair_diff_full_exact", False)):
            self._show_global_apply_feedback("完整 A/B 差异仍在计算。", reason="ab-diff-not-exact")
            return False
        if direction == "BASE2A" and not bool(getattr(self, "_base_diff_full_exact", False)):
            self._show_global_apply_feedback("完整 Base 差异仍在计算。", reason="base-diff-not-exact")
            return False

        cache = self._active_column_comparison_cache()
        if cache.structural_diff_cols:
            cols = ", ".join(
                _excel_column_display(int(col))
                for col in sorted(cache.structural_diff_cols)
            )
            self._show_global_apply_feedback(
                f"本 Sheet 含列结构差异（{cols}）；请先处理列结构。",
                reason="column-structure",
            )
            return False
        source_side, destination_side = side_pair
        diff_map = self.pair_base_diff_cols if direction == "BASE2A" else self.pair_diff_cols
        projection = self._active_column_projection()

        ambiguous_details = self._collect_global_ambiguous_diff_details(
            direction,
            diff_map,
            projection,
        )
        if ambiguous_details:
            if self._is_three_way_enabled():
                cols = ", ".join(
                    _excel_column_display(int(item["logical_col"]))
                    for item in ambiguous_details
                )
                self._show_global_apply_feedback(
                    f"真实差异落在歧义列（{cols}）；请先确认列结构。",
                    reason="column-ambiguous-diff",
                )
                return False
            action = self._ask_global_ambiguous_action(direction, ambiguous_details)
            if action == "A2B_SHEET":
                return self._apply_global_sheet_overwrite("A", "B")
            if action == "B2A_SHEET":
                return self._apply_global_sheet_overwrite("B", "A")
            self._show_global_apply_feedback(
                "真实差异落在歧义列；已取消写入。",
                reason="column-ambiguous-diff-canceled",
            )
            return False

        candidates: list[tuple[int, tuple[int, ...]]] = []
        blocker = None
        for pair_idx in range(len(self.row_pairs)):
            raw_cols = set(diff_map.get(pair_idx, set()))
            if not raw_cols:
                continue
            if any(int(col) <= 0 for col in raw_cols):
                blocker = "本 Sheet 含单侧/结构行差异"
                break
            pair = self.row_pairs[pair_idx]
            source_row = (
                self._base_row_for_pair(pair_idx, pair)
                if source_side == "BASE"
                else self._row_for_side(pair, source_side)
            )
            destination_row = self._row_for_side(pair, destination_side)
            if source_row is None or destination_row is None:
                blocker = "本 Sheet 含单侧/结构行差异"
                break
            cols = tuple(sorted(int(col) for col in raw_cols if int(col) > 0))
            for logical_col in cols:
                slot = projection.slot(logical_col)
                if (
                    slot is None
                    or slot.state != "retained"
                    or slot.confidence.ambiguous
                    or projection.physical_col(source_side, logical_col) is None
                    or projection.physical_col(destination_side, logical_col) is None
                ):
                    blocker = (
                        f"{_excel_column_display(logical_col)} 不是可安全映射的普通列"
                    )
                    break
            if blocker:
                break
            candidates.append((pair_idx, cols))

        if blocker:
            self._show_global_apply_feedback(
                f"{blocker}；全局模式不会新增/删除行列或猜测映射。",
                reason="structural-row-or-slot",
            )
            return False
        if not candidates:
            self._show_global_apply_feedback("没有可安全写入的完整差异。", reason="no-candidates")
            return False

        cell_count = sum(len(cols) for _pair_idx, cols in candidates)
        source_label, target_label = self.role_presentation.roles_for_direction(direction)
        source_label = source_label or "所选侧"
        target_label = target_label or "目标侧"
        confirmation = (
            f"确认在 Sheet“{self.sheet}”中，以{source_label}为准并写入{target_label}？\n\n"
            f"将原子应用 {cell_count} 个安全映射的差异单元格（{len(candidates)} 行）。\n"
            "列结构、歧义映射和单侧行均不会写入；可通过一次“撤销”整体还原。"
        )
        if not messagebox.askyesno("确认全局应用", confirmation, parent=self.root):
            try:
                self.info.configure(text="已取消全局模式；未写入任何内容。")
            except Exception:
                pass
            return False

        started = time.perf_counter()
        changed_any = False
        undo_group_active = False
        interactive_started = False
        row_undo_cells: list = []
        snapshot = None
        previous_bg_suppression = bool(getattr(self, "_suppress_bg_apply", False))
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        try:
            # Validate formulas and capture every destination cell before the
            # first mutation. A row primitive may fail after writing one cell;
            # the outer snapshot remains authoritative for rollback.
            self._preflight_region_formula_copy(
                direction, [pair_idx for pair_idx, _cols in candidates]
            )
            snapshot = self._capture_global_safe_apply_snapshot(
                direction, candidates, projection
            )
            if callable(begin_interactive):
                begin_interactive(self)
                interactive_started = True
            self._suppress_bg_apply = True
            self.app.begin_undo_group(
                self.sheet,
                f"全局采用{source_label}",
                direction=direction,
                row_count=len(candidates),
                cell_count=cell_count,
                global_conflict_sheet_present=bool(snapshot["conflict_sheet_present"]),
                global_conflict_sheet_before=copy.deepcopy(snapshot["conflict_sheet_before"]),
                global_user_touched_conflicts_before=bool(snapshot["user_touched_conflicts_before"]),
            )
            undo_group_active = True
            try:
                self.info.configure(text=f"正在全局采用{source_label}：0/{len(candidates)} 行...")
                self.root.configure(cursor="watch")
                self.root.update_idletasks()
            except Exception:
                pass
            for ordinal, (pair_idx, cols) in enumerate(candidates, start=1):
                changed_any = bool(
                    self._copy_selected_row(
                        direction,
                        row_header=False,
                        override_pair_idx=pair_idx,
                        override_cols=set(cols),
                        suppress_refresh=True,
                        _undo_out=row_undo_cells,
                        raise_on_error=True,
                    )
                ) or changed_any
                if ordinal % 200 == 0:
                    try:
                        self.info.configure(
                            text=f"正在全局采用{source_label}：{ordinal}/{len(candidates)} 行..."
                        )
                        self.root.update_idletasks()
                    except Exception:
                        pass

            if not changed_any:
                self.app.finish_undo_group(commit=False)
                undo_group_active = False
                self._show_global_apply_feedback("所有候选单元格已经一致。", reason="unchanged")
                return False

            # One child action plus the compound metadata creates exactly one
            # visible undo. The same snapshot powers ordinary undo and an
            # exception rollback, including manual ops and conflict state.
            self.app.push_undo({
                "kind": "global_safe_cells",
                "sheet": self.sheet,
                "target": snapshot["target"],
                "snapshot": snapshot,
            })
            self.app.finish_undo_group(commit=True)
            undo_group_active = False
            self._mark_nonstructural_cell_edit(
                "global-safe-overwrite",
                edited_sides=("B",) if direction == "A2B" else ("A",),
            )
            exact_rows = self._refresh_pair_indices_exact(
                [pair_idx for pair_idx, _cols in candidates]
            )
            if bool(self.only_diff_var.get()) and self.snapshot_only_diff:
                self._cache_only_diff_rows_from_exact_pair_maps()
            self._invalidate_render_cache()
            self.refresh(row_only=None, rescan=False)
            self._refresh_diff_block_ui()
            self._update_cursor_lines()
            elapsed = time.perf_counter() - started
            try:
                self.info.configure(
                    text=(
                        f"已全局采用{source_label}：{cell_count} 个安全单元格／"
                        f"{len(candidates)} 行，耗时 {elapsed:.1f} 秒"
                    )
                )
            except Exception:
                pass
            _dlog(
                f"GLOBAL_APPLY_DONE sheet={self.sheet} dir={direction} "
                f"cells={cell_count} pairs={exact_rows} "
                f"ms={elapsed * 1000.0:.1f}"
            )
            return True
        except Exception as exc:
            try:
                if snapshot is not None:
                    self._restore_global_safe_apply_snapshot(snapshot)
                if undo_group_active:
                    self.app.finish_undo_group(commit=False)
                    undo_group_active = False
                if snapshot is not None:
                    self._refresh_pair_indices_exact(
                        [pair_idx for pair_idx, _cols in candidates]
                    )
                    self._invalidate_render_cache()
                    self.refresh(row_only=None, rescan=False)
                    self._update_cursor_lines()
            except Exception as rollback_error:
                _dlog(
                    f"CRITICAL global snapshot rollback failed sheet={self.sheet} "
                    f"dir={direction} err={rollback_error}"
                )
            _dlog(
                f"GLOBAL_APPLY_ERROR sheet={self.sheet} dir={direction} "
                f"err={type(exc).__name__}:{exc}"
            )
            messagebox.showerror("全局覆盖失败", f"全局覆盖失败，已完整还原：\n{exc}", parent=self.root)
            return False
        finally:
            if undo_group_active:
                self.app.finish_undo_group(commit=False)
            self._suppress_bg_apply = previous_bg_suppression
            if interactive_started and callable(end_interactive):
                end_interactive()
            try:
                self.root.configure(cursor="")
            except Exception:
                pass

    def _copy_missing_sheet(self, direction: str, *, _guarded: bool = False):
        if not self._guard_copy_direction(direction, "整 Sheet 操作"):
            return False
        if not _guarded and not self._guard_mutation_ready("整 Sheet 操作"):
            return False
        if _guarded and not self.app._has_active_mutation_owner(self):
            _dlog(
                f"mutation lease rejected sheet={self.sheet} "
                "action=整 Sheet 操作"
            )
            return False
        meta = self._sheet_meta()
        action_text = {
            "A2B": f"正在{self._format_direction_action('A2B', 'table')}...",
            "B2A": f"正在{self._format_direction_action('B2A', 'table')}...",
            "BASE2A": f"正在{self._format_direction_action('BASE2A', 'table')}...",
        }.get(direction, "正在处理整张 Sheet...")
        try:
            self.info.configure(text=action_text)
            self.root.configure(cursor="watch")
            self.root.update_idletasks()
        except Exception:
            pass
        try:
            if direction == "A2B":
                if meta.get("has_a") and (not meta.get("has_b")):
                    self.app._copy_sheet_between_sides(self.sheet, "A", "B")
            elif direction == "B2A":
                if meta.get("has_b") and (not meta.get("has_a")):
                    self.app._copy_sheet_between_sides(self.sheet, "B", "A")
            elif direction == "BASE2A":
                if meta.get("has_base"):
                    self.app._copy_sheet_between_sides(self.sheet, "BASE", "A")
                elif meta.get("has_a"):
                    self.app._delete_sheet_on_side(self.sheet, "A")
            elif direction == "MINE2A":
                return
            else:
                return
            self._mark_column_mapping_stale(
                "sheet-structure-change",
                row_structure=True,
                column_structure=True,
                edited_sides=("B",) if direction == "A2B" else ("A",),
            )
            self._data_ready = False
            self._bounds_checked = False
            self._invalidate_only_diff_snapshot_cache()
            self._invalidate_render_cache()
            self._update_sheet_role_labels()
            self.app.refresh_sheet_nav()
            self.refresh(row_only=None, rescan=True)
            self._update_cursor_lines()
        except Exception as e:
            messagebox.showerror("Error", f"整Sheet操作失败：\n{e}")
        finally:
            try:
                self.root.configure(cursor="")
            except Exception:
                pass

    def _update_merge_buttons_for_row(self, excel_row: int):
        # Buttons are always visible; no UI updates needed.
        return

    # ---------- Diff block navigation ----------
    @staticmethod
    def _group_diff_pair_rows(rows, pending_predicate=None) -> list[_DiffBlock]:
        """Group cached only-diff pair indices without reading worksheet cells."""
        normalized = []
        seen = set()
        for raw_idx in rows or []:
            try:
                pair_idx = int(raw_idx)
            except Exception:
                continue
            if pair_idx < 0 or pair_idx in seen:
                continue
            normalized.append(pair_idx)
            seen.add(pair_idx)
        normalized.sort()

        blocks: list[_DiffBlock] = []
        current: list[int] = []

        def _flush():
            if not current:
                return
            pending = True
            if callable(pending_predicate):
                pending = any(bool(pending_predicate(pair_idx)) for pair_idx in current)
            blocks.append(
                _DiffBlock(
                    ordinal=len(blocks) + 1,
                    pair_indices=tuple(current),
                    start_pair_idx=current[0],
                    end_pair_idx=current[-1],
                    pending=bool(pending),
                )
            )

        previous = None
        for pair_idx in normalized:
            if previous is not None and pair_idx != previous + 1:
                _flush()
                current = []
            current.append(pair_idx)
            previous = pair_idx
        _flush()
        return blocks

    def _invalidate_diff_block_model(self):
        self._full_diff_blocks_cache_key = None
        self._full_diff_blocks = []
        self._pair_to_full_diff_block = {}

    def _diff_block_model_ready(self) -> bool:
        try:
            return bool(self.only_diff_var.get()) and bool(self._data_ready) and not bool(self._only_diff_async_building)
        except Exception:
            return False

    def _ensure_full_diff_blocks(self) -> list[_DiffBlock]:
        if not self._diff_block_model_ready():
            self._invalidate_diff_block_model()
            return []
        rows = self._full_display_rows
        key = (
            id(rows),
            len(rows),
            id(self.row_pairs),
            len(self.row_pairs),
            int(self._only_diff_source_version),
            int(self._data_version),
        )
        if self._full_diff_blocks_cache_key == key:
            return self._full_diff_blocks
        blocks = self._group_diff_pair_rows(
            (pair_idx for pair_idx in rows if 0 <= int(pair_idx) < len(self.row_pairs)),
            pending_predicate=self._pair_has_visual_diff,
        )
        pair_to_block = {}
        for block_idx, block in enumerate(blocks):
            for pair_idx in block.pair_indices:
                pair_to_block[pair_idx] = block_idx
        self._full_diff_blocks_cache_key = key
        self._full_diff_blocks = blocks
        self._pair_to_full_diff_block = pair_to_block
        return blocks

    def _full_diff_block_index_for_pair(self, pair_idx) -> int | None:
        pair_idx = self._normalize_pair_idx(pair_idx)
        if pair_idx is None:
            return None
        self._ensure_full_diff_blocks()
        return self._pair_to_full_diff_block.get(pair_idx)

    def _active_full_diff_block_index(self) -> int | None:
        blocks = self._ensure_full_diff_blocks()
        if not blocks:
            return None

        selected_pair = self._normalize_pair_idx(self.selected_pair_idx)
        if selected_pair is not None and (
            self.has_explicit_cell_selection() or getattr(self, "_last_selected_line", None) is not None
        ):
            block_idx = self._pair_to_full_diff_block.get(selected_pair)
            if block_idx is not None:
                return block_idx

        try:
            top_line = int(str(self.left.index("@0,0")).split(".")[0])
        except Exception:
            top_line = 1
        top_pair = self._pair_idx_for_line(max(1, top_line))
        block_idx = self._pair_to_full_diff_block.get(top_pair)
        if block_idx is not None:
            return block_idx

        if selected_pair is not None:
            block_idx = self._pair_to_full_diff_block.get(selected_pair)
            if block_idx is not None:
                return block_idx
        return 0

    def _full_diff_block_for_pair(self, pair_idx) -> _DiffBlock | None:
        block_idx = self._full_diff_block_index_for_pair(pair_idx)
        blocks = self._full_diff_blocks
        if block_idx is None or not (0 <= block_idx < len(blocks)):
            return None
        return blocks[block_idx]

    def _set_diff_block_indicator_visible(self, visible: bool):
        # The indicator owns reserved geometry in the dedicated navigation row.
        # Visibility changes only its content, never the toolbar layout.
        if not visible:
            try:
                self.diff_block_status_var.set("差异块 -/- · 待处理 -")
            except Exception:
                pass

    def _update_diff_block_indicator(self):
        try:
            only_diff = bool(self.only_diff_var.get())
        except Exception:
            only_diff = False
        self._set_diff_block_indicator_visible(only_diff)
        if not only_diff:
            return
        if not self._diff_block_model_ready():
            self.diff_block_status_var.set("差异块 计算中...")
            return
        blocks = self._ensure_full_diff_blocks()
        if not blocks:
            self.diff_block_status_var.set("差异块 -/0 · 待处理 0")
            return
        active_idx = self._active_full_diff_block_index()
        if active_idx is None or not (0 <= active_idx < len(blocks)):
            active_idx = 0
        pending_count = sum(1 for block in blocks if block.pending)
        active = blocks[active_idx]
        suffix = " · 已处理" if not active.pending else ""
        self.diff_block_status_var.set(
            f"差异块 {active.ordinal}/{len(blocks)} · 待处理 {pending_count}{suffix}"
        )

    def _diff_block_marker_width(self) -> int:
        try:
            if not bool(self.only_diff_var.get()):
                return 0
        except Exception:
            return 0
        blocks = self._ensure_full_diff_blocks()
        if not blocks:
            return 0
        return max(4, len(str(len(blocks))) + 3)

    def _diff_block_marker_prefix(self, pair_idx: int, side: str) -> str:
        marker_width = self._diff_block_marker_width()
        if marker_width <= 0:
            return ""
        marker = ""
        if side == "A":
            block = self._full_diff_block_for_pair(pair_idx)
            if block is not None and block.start_pair_idx == pair_idx:
                marker = f"[{block.ordinal}]"
        return marker.ljust(marker_width)

    def _apply_diff_block_presentation(self):
        widgets = (self.left, self.base, self.right, self.left_ln, self.base_ln, self.right_ln)
        for w in widgets:
            try:
                w.tag_remove("blockstart", "1.0", "end")
            except Exception:
                pass
        try:
            self.left_ln.tag_remove("blockmarker", "1.0", "end")
        except Exception:
            pass
        try:
            if not bool(self.only_diff_var.get()):
                return
        except Exception:
            return

        blocks = self._ensure_full_diff_blocks()
        marker_width = self._diff_block_marker_width()
        for block in blocks:
            line = self.row_to_line.get(block.start_pair_idx)
            if line is None:
                continue
            if block.ordinal > 1:
                start = f"{line}.0"
                end = f"{line + 1}.0"
                for w in widgets:
                    try:
                        w.tag_add("blockstart", start, end)
                    except Exception:
                        pass
            if marker_width > 0:
                try:
                    self.left_ln.tag_add("blockmarker", f"{line}.0", f"{line}.{marker_width}")
                except Exception:
                    pass
        try:
            self.left_ln.tag_raise("blockmarker")
        except Exception:
            pass

    def _refresh_diff_block_ui(self):
        self._apply_diff_block_presentation()
        self._update_diff_block_indicator()

    def _compute_diff_blocks(self):
        """Return list of (start_line, end_line) diff blocks in current view."""
        blocks = []
        start = None
        previous_diff_pair_idx = None
        for line_idx, pair_idx in enumerate(self.display_rows, start=1):
            has = self._pair_has_visual_diff(pair_idx)
            if has:
                # In only-diff mode, adjacent display lines can be thousands of
                # worksheet rows apart. They must remain separate regions.
                if start is None:
                    start = line_idx
                elif previous_diff_pair_idx is None or int(pair_idx) != int(previous_diff_pair_idx) + 1:
                    blocks.append((start, line_idx - 1))
                    start = line_idx
                previous_diff_pair_idx = pair_idx
            elif (not has) and start is not None:
                blocks.append((start, line_idx - 1))
                start = None
                previous_diff_pair_idx = None
        if start is not None:
            blocks.append((start, len(self.display_rows)))
        self._diff_blocks_cache = blocks
        return blocks

    def _current_line(self) -> int:
        try:
            return int(self.left.index("insert").split(".")[0])
        except Exception:
            return 1

    def _current_diff_block_for_line(self, line: int):
        blocks = self._diff_blocks_cache if self._diff_blocks_cache is not None else self._compute_diff_blocks()
        for start, end in blocks:
            if start <= line <= end:
                return (start, end)
        return None

    def _logical_diff_pair_block_for_line(self, line: int) -> list[int]:
        """Expand the selected diff to its full pair block, beyond render limits."""
        if not (1 <= int(line) <= len(self.display_rows)):
            return []
        anchor_pair_idx = int(self.display_rows[int(line) - 1])
        return self._logical_diff_pair_block_for_pair(anchor_pair_idx)

    def _logical_diff_pair_block_for_pair(self, anchor_pair_idx: int) -> list[int]:
        """Expand a pair anchor to its full contiguous visual-diff block."""
        anchor_pair_idx = self._normalize_pair_idx(anchor_pair_idx)
        if anchor_pair_idx is None:
            return []
        try:
            if bool(self.only_diff_var.get()):
                block = self._full_diff_block_for_pair(anchor_pair_idx)
                if block is not None:
                    return list(block.pair_indices)
        except Exception:
            pass
        if not self._pair_has_visual_diff(anchor_pair_idx):
            return []
        start_pair_idx = anchor_pair_idx
        end_pair_idx = anchor_pair_idx
        while start_pair_idx > 0 and self._pair_has_visual_diff(start_pair_idx - 1):
            start_pair_idx -= 1
        last_pair_idx = len(self.row_pairs) - 1
        while end_pair_idx < last_pair_idx and self._pair_has_visual_diff(end_pair_idx + 1):
            end_pair_idx += 1
        return list(range(start_pair_idx, end_pair_idx + 1))

    def _region_pair_has_applicable_diff(
        self,
        direction: str,
        pair_idx: int,
        writable_col_cache: dict[tuple[str, int], bool] | None = None,
    ) -> bool:
        """Return whether one cached pair contains a safe write for ``direction``.

        This is intentionally an in-memory geometry check.  Region-button
        fallback must stay responsive and must not discover candidates by
        rereading worksheet cells.
        """
        pair_idx = self._normalize_pair_idx(pair_idx)
        if pair_idx is None:
            return False
        direction = str(direction or "")
        pair = self.row_pairs[pair_idx]
        ra = self._row_for_side(pair, "A")
        rb = self._row_for_side(pair, "B")
        if direction == "MINE2A":
            # Retain acknowledges visual differences from either comparison
            # map and never needs a writable source/destination projection.
            cols = set(self.pair_diff_cols.get(pair_idx, set()))
            cols.update(self.pair_base_diff_cols.get(pair_idx, set()))
            return bool(cols)
        if direction == "A2B":
            source_side, destination_side = "A", "B"
            cols = set(self.pair_diff_cols.get(pair_idx, set()))
            # Adopting a missing left row means accepting the left-side
            # deletion and deleting the corresponding destination row.
            if ra is None:
                return bool(rb is not None and -1 in cols)
        elif direction == "B2A":
            source_side, destination_side = "B", "A"
            cols = set(self.pair_diff_cols.get(pair_idx, set()))
            # Symmetric structural case: theirs deleted a row that mine still
            # has, so "使用右侧" must delete it from mine.
            if rb is None:
                return bool(ra is not None and -1 in cols)
        elif direction == "BASE2A":
            if not getattr(self.app, "has_base", False):
                return False
            base_row = self._base_row_for_pair(pair_idx, pair)
            if (ra is None) != (base_row is None):
                return True
            if ra is None:
                return False
            source_side, destination_side = "BASE", "A"
            cols = set(self.pair_base_diff_cols.get(pair_idx, set()))
        else:
            return False
        if not cols:
            return False

        # A missing destination row can be created from the selected source.
        if -1 in cols:
            if direction == "A2B" and rb is None:
                return True
            if direction == "B2A" and ra is None:
                return True

        projection = None
        for logical_col in (int(col) for col in cols if int(col) > 0):
            cache_key = (direction, logical_col)
            if writable_col_cache is not None and cache_key in writable_col_cache:
                if writable_col_cache[cache_key]:
                    return True
                continue
            if projection is None:
                try:
                    projection = self._active_column_projection()
                except Exception:
                    return False
            slot = projection.slot(logical_col)
            writable = bool(
                slot is not None
                and slot.state != "unresolved"
                and not slot.confidence.ambiguous
                and projection.physical_col(source_side, logical_col) is not None
                and projection.physical_col(destination_side, logical_col) is not None
            )
            if writable_col_cache is not None:
                writable_col_cache[cache_key] = writable
            if writable:
                return True
        return False

    def _region_column_structure_blockers(
        self,
        direction: str,
        pair_indices,
        *,
        first_only: bool = False,
    ) -> tuple[int, ...]:
        """Return logical columns that require an explicit structure action.

        A region command owns rows and cells, not the whole worksheet column
        geometry.  Missing source/destination columns and unresolved mappings
        therefore have to be resolved through the column-structure buttons
        before a region is allowed to write anything.
        """
        side_pair = {
            "A2B": ("A", "B"),
            "B2A": ("B", "A"),
            "BASE2A": ("BASE", "A"),
        }.get(str(direction or ""))
        if side_pair is None:
            return ()
        diff_map = (
            self.pair_base_diff_cols
            if direction == "BASE2A"
            else self.pair_diff_cols
        )
        normalized_pairs = tuple(
            normalized
            for normalized in (
                self._normalize_pair_idx(pair_idx) for pair_idx in pair_indices
            )
            if normalized is not None
        )
        if not any(
            int(col) > 0
            for pair_idx in normalized_pairs
            for col in diff_map.get(pair_idx, set())
        ):
            return ()
        projection = self._ensure_column_projection_current("检查区域列结构")
        blockers: list[int] = []
        seen: set[int] = set()
        source_side, destination_side = side_pair
        for normalized_pair_idx in normalized_pairs:
            for logical_col in sorted(
                int(col)
                for col in diff_map.get(normalized_pair_idx, set())
                if int(col) > 0
            ):
                if logical_col in seen:
                    continue
                slot = projection.slot(logical_col)
                if (
                    slot is None
                    or slot.state == "unresolved"
                    or slot.confidence.ambiguous
                    or projection.physical_col(source_side, logical_col) is None
                    or projection.physical_col(destination_side, logical_col) is None
                ):
                    blockers.append(logical_col)
                    seen.add(logical_col)
                    if first_only:
                        return tuple(blockers)
        return tuple(blockers)

    def _logical_column_display_name(self, logical_col: int) -> str:
        """Best-effort schema name for one projected logical column."""
        try:
            projection = self._ensure_column_projection_current("显示区域列结构")
        except Exception:
            return ""
        side_order = ("BASE", "A", "B") if self._is_three_way_enabled() else ("A", "B")
        for side in side_order:
            physical_col = projection.physical_col(side, int(logical_col))
            if physical_col is None:
                continue
            try:
                ws = self.app.ws_for_side(side, self.sheet, edit=False)
                value = ws.cell(row=1, column=int(physical_col)).value if ws is not None else None
            except Exception:
                value = None
            text = str(value or "").strip()
            if text:
                return text
        return ""

    def _guide_region_column_structure(
        self,
        direction: str,
        blocker_cols: tuple[int, ...],
    ):
        """Select the first blocked column and explain the explicit next step."""
        if not blocker_cols:
            return
        source_side = {
            "A2B": "A",
            "B2A": "B",
            "BASE2A": "BASE",
        }.get(str(direction or ""), "LOGICAL")
        action_text = {
            "A2B": f"应用 {self.role_presentation.left} → {self.role_presentation.right} 列",
            "B2A": f"应用 {self.role_presentation.right} → {self.role_presentation.left} 列",
            "BASE2A": f"应用 {self.role_presentation.middle} → {self.role_presentation.left} 列",
        }.get(str(direction or ""), "对应列结构按钮")
        first_col = int(blocker_cols[0])
        block = self._select_column_block_by_logical_col(first_col, source_side)
        if block is not None:
            start_col = int(block.start_slot_idx) + 1
            end_col = int(block.end_slot_idx) + 1
        else:
            start_col = end_col = first_col
        range_text = _excel_column_range_display(start_col, end_col)
        column_name = self._logical_column_display_name(first_col)
        named_range = f"{range_text}（{column_name}）" if column_name else range_text
        extra_count = len(blocker_cols) - 1
        extra_text = f"，另有 {extra_count} 个结构列" if extra_count > 0 else ""
        text = (
            f"该区域包含列结构差异：{named_range}{extra_text}。\n\n"
            "“使用区域”只覆盖所选行中的单元格，不会自动新增或删除整张 Sheet 的列。"
            f"已为你选中对应列块，请先点击“{action_text}”，"
            "完成列结构处理后再使用区域。\n\n本次未写入任何内容。"
        )
        try:
            self.info.configure(
                text=f"区域包含列结构差异 {named_range}；请先点击“{action_text}”（本次未写入）"
            )
        except Exception:
            pass
        try:
            self._set_column_action_status(
                f"区域操作已暂停｜{named_range}｜请点击“{action_text}”｜本次未写入"
            )
        except Exception:
            pass
        _dlog(
            f"OVERWRITE_REGION_COLUMN_STRUCTURE_BLOCKED sheet={self.sheet} "
            f"dir={direction} cols={blocker_cols} first={named_range}"
        )
        messagebox.showwarning("请先处理列结构差异", text)

    def _region_action_visual_blocks(self) -> list[_DiffBlock]:
        """Return safe-to-navigate visual blocks for the current display mode."""
        if self._diff_block_model_ready():
            return list(self._ensure_full_diff_blocks())
        # Full mode may render only a prefix of a large sheet.  Its lazy loader
        # assumes that prefix remains stable; jumping to an unrendered remote
        # row via the only-diff bounded-preview path would violate that
        # invariant. Restrict fallback to currently materialized rows.
        return self._group_diff_pair_rows(
            pair_idx
            for pair_idx in self.display_rows
            if self._pair_has_visual_diff(pair_idx)
        )

    def _resolve_region_action_target(
        self,
        direction: str,
        preferred_pair_idx=None,
    ) -> tuple[_DiffBlock, bool] | None:
        """Resolve the selected, nearest, or first applicable region.

        The boolean result says whether the command had to leave the preferred
        pair.  Equal-distance ties choose the earlier block for deterministic
        keyboard/mouse behavior.
        """
        direction = str(direction or "")
        # Large only-diff snapshots intentionally keep these maps sparse.  An
        # empty direction map proves in O(1) that no block can be applied and
        # avoids walking a 100k+ row visual block on the Tk event thread.
        if direction == "MINE2A":
            direction_map = {
                pair_idx: set(self.pair_diff_cols.get(pair_idx, set()))
                | set(self.pair_base_diff_cols.get(pair_idx, set()))
                for pair_idx in range(len(self.row_pairs))
                if self.pair_diff_cols.get(pair_idx) or self.pair_base_diff_cols.get(pair_idx)
            }
        else:
            direction_map = (
                self.pair_base_diff_cols
                if direction == "BASE2A"
                else self.pair_diff_cols
            )
        if not direction_map:
            return None
        preferred = self._normalize_pair_idx(preferred_pair_idx)
        nearest = None
        nearest_key = None
        writable_col_cache: dict[tuple[str, int], bool] = {}
        # Resolve while iterating instead of first materializing every
        # direction-applicable block.  The common no-selection case stops at
        # the first safe block; a preferred pair still keeps deterministic
        # nearest/earlier tie-breaking.
        for block in self._region_action_visual_blocks():
            has_writable_diff = any(
                self._region_pair_has_applicable_diff(
                    direction,
                    pair_idx,
                    writable_col_cache,
                )
                for pair_idx in block.pair_indices
            )
            if (
                not has_writable_diff
                and not self._region_column_structure_blockers(
                    direction,
                    block.pair_indices,
                    first_only=True,
                )
            ):
                continue
            if preferred is None:
                return block, True
            if block.start_pair_idx <= preferred <= block.end_pair_idx:
                return block, False
            if preferred < block.start_pair_idx:
                distance = block.start_pair_idx - preferred
            else:
                distance = preferred - block.end_pair_idx
            key = (distance, block.start_pair_idx)
            if nearest_key is None or key < nearest_key:
                nearest = block
                nearest_key = key
        if nearest is None:
            return None
        return nearest, True

    def _locate_region_action_block(self, block: _DiffBlock) -> bool:
        """Materialize and select a region start through the existing navigator."""
        pair_idx = self._normalize_pair_idx(block.start_pair_idx)
        if pair_idx is None or not self._materialize_pair_for_navigation(pair_idx):
            return False
        line = self.row_to_line.get(pair_idx)
        if line is None:
            return False
        self._goto_block_start(int(line))
        return self._normalize_pair_idx(self.selected_pair_idx) == pair_idx

    def _show_region_action_feedback(self, direction: str, reason: str = "none"):
        presentation = getattr(
            self,
            "role_presentation",
            RolePresentation.for_app(getattr(self, "app", None)),
        )
        app = getattr(self, "app", None)
        # Legacy headless adapters do not expose semantic mode attributes;
        # retain their left/right feedback contract while real views always
        # use RolePresentation labels.
        if not hasattr(self, "role_presentation") and not hasattr(app, "merge_mode"):
            source_label = {"A2B": "左侧", "B2A": "右侧", "BASE2A": "Base"}.get(
                str(direction or ""), "所选侧"
            )
            action_label = f"使用{source_label}区域"
        else:
            source_label = presentation.roles_for_direction(direction)[0] or "所选侧"
            action_label = self._format_direction_action(direction, "region") or f"使用{source_label}区域"
        if reason == "calculating":
            text = "差异区域仍在计算，请稍后再试。"
        elif reason == "locate-failed":
            text = f"找到可使用的{source_label}差异区域，但暂时无法定位；请刷新当前 Sheet 后重试。"
        elif reason == "unchanged":
            text = f"已定位到{source_label}差异区域，但其中没有可写入的内容。"
        elif reason == "located":
            text = (
                f"已定位到可使用的{source_label}差异区域，"
                f"请再次点击“{action_label}”。"
            )
        elif reason == "direction-unavailable":
            text = f"当前差异区域不能使用{source_label}内容，请选择另一侧或其他差异区域。"
        elif reason == "not-visible":
            text = (
                f"当前已加载范围内没有可使用的{source_label}差异区域；"
                "可切换“只看差异”后重试。"
            )
        else:
            text = f"当前 Sheet 没有可使用的{source_label}差异区域。"
        try:
            self.info.configure(text=text)
        except Exception:
            pass
        _dlog(
            f"OVERWRITE_REGION_FEEDBACK sheet={self.sheet} dir={direction} "
            f"reason={reason} text={text}"
        )

    def _copy_selected_region(self, direction: str):
        """Copy contiguous diff block around current line using diff-cell columns only."""
        if not self._guard_copy_direction(direction, "区域覆盖"):
            return False
        if not self._guard_mutation_ready("区域覆盖"):
            return False
        started = time.perf_counter()
        processed_rows = 0
        changed_any = False
        structural_rows_changed = False
        undo_group_active = False
        undo_cells_region: list = []
        retain_difference_ids: list[str] = []
        previous_bg_suppression = bool(getattr(self, "_suppress_bg_apply", False))
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        if callable(begin_interactive):
            begin_interactive(self)
        self._suppress_bg_apply = True
        direction_text = self._format_direction_action(direction, "region") or str(direction)
        try:
            formula_skip_before = int(getattr(self, "_formula_copy_skips_pending", 0))
            line = self._current_line()
            # A toolbar click can leave Tk's insert mark on the synthetic line
            # after the last rendered row (for example line 801 when a large
            # sheet initially renders 800 rows). Single-row actions already use
            # the selected/hovered pair first; region actions must do the same.
            selected_pair_idx = self._normalize_pair_idx(self.selected_pair_idx)
            has_selected_row = getattr(self, "_last_selected_line", None) is not None
            has_explicit_selection = bool(
                selected_pair_idx is not None
                and (self.has_explicit_cell_selection() or has_selected_row)
            )
            if has_explicit_selection:
                # Region actions are commands, not hover previews. A deliberate
                # cell/row selection must win over stale hover state left behind
                # when the pointer moves from the grid to the toolbar button.
                anchor_pair_idx = selected_pair_idx
            else:
                anchor_pair_idx = self.resolved_pair_idx_for_c_area()

            selected_visual_block = None
            if has_explicit_selection:
                for block in self._region_action_visual_blocks():
                    if selected_pair_idx in block.pair_indices:
                        if any(
                            self._pair_has_visual_diff(pair_idx)
                            for pair_idx in block.pair_indices
                        ):
                            selected_visual_block = block
                        break
            if selected_visual_block is not None:
                writable_col_cache: dict[tuple[str, int], bool] = {}
                has_writable_diff = any(
                    self._region_pair_has_applicable_diff(
                        direction,
                        pair_idx,
                        writable_col_cache,
                    )
                    for pair_idx in selected_visual_block.pair_indices
                )
                has_structure_diff = bool(
                    self._region_column_structure_blockers(
                        direction,
                        selected_visual_block.pair_indices,
                        first_only=True,
                    )
                )
                if not has_writable_diff and not has_structure_diff:
                    self._show_region_action_feedback(direction, "direction-unavailable")
                    return
                target = (selected_visual_block, False)
                locate_only = False
            else:
                target = self._resolve_region_action_target(direction, anchor_pair_idx)
                # No explicit selection, or an explicit ordinary/non-diff row,
                # requires a second click before any data is changed.
                locate_only = True
            if target is None:
                _dlog(
                    f"OVERWRITE_REGION_NO_BLOCK sheet={self.sheet} dir={direction} "
                    f"line={line} pair={anchor_pair_idx}"
                )
                reason = (
                    "calculating"
                    if bool(getattr(self, "_only_diff_async_building", False))
                    else (
                        "not-visible"
                        if (
                            not bool(self.only_diff_var.get())
                            and len(self.display_rows) < len(self.row_pairs)
                        )
                        else "none"
                    )
                )
                self._show_region_action_feedback(direction, reason)
                return
            target_block, relocated = target
            if locate_only or relocated:
                if not self._locate_region_action_block(target_block):
                    self._show_region_action_feedback(direction, "locate-failed")
                    return
                anchor_pair_idx = target_block.start_pair_idx
                _dlog(
                    f"OVERWRITE_REGION_AUTO_LOCATE sheet={self.sheet} dir={direction} "
                    f"pair={anchor_pair_idx} block={target_block.ordinal}"
                )
            if locate_only:
                self._show_region_action_feedback(direction, "located")
                return
            region_pair_indices = list(target_block.pair_indices)
            total_region_rows = len(region_pair_indices)
            _dlog(
                f"OVERWRITE_REGION_START sheet={self.sheet} dir={direction} "
                f"anchor={anchor_pair_idx} pairs={region_pair_indices[0]}-"
                f"{region_pair_indices[-1]} rows={total_region_rows}"
            )
            structure_blockers = self._region_column_structure_blockers(
                direction,
                region_pair_indices,
            )
            if structure_blockers:
                self._guide_region_column_structure(direction, structure_blockers)
                return False
            try:
                self.info.configure(text=f"正在采用{direction_text}：0/{total_region_rows} 行...")
                self.root.configure(cursor="watch")
                self.root.update_idletasks()
            except Exception:
                pass
            # Validate the whole region before writing the first cell so a later
            # unsupported multi-cell formula cannot leave a half-applied region.
            self._preflight_region_formula_copy(direction, region_pair_indices)
            anchor = self._capture_view_anchor()
            self.app.begin_undo_group(
                self.sheet,
                f"采用{direction_text}",
                direction=direction,
                row_count=total_region_rows,
            )
            undo_group_active = True
            # Collect all undo cells into one list so the entire region is a
            # single undo entry regardless of how many rows it spans.
            undo_target = "A" if direction in ("B2A", "BASE2A") else "B"
            # The common large-formula case is thousands of already aligned
            # rows copied from theirs to mine. Resolve worksheet objects once
            # and bypass the full single-row command setup for every row.
            fast_b2a = direction == "B2A"
            ws_a_val_fast = None
            ws_b_val_fast = None
            ws_a_edit_fast = None
            ws_b_edit_fast = None
            if fast_b2a:
                ws_a_val_fast = self.app.ws_a_val(self.sheet)
                ws_b_val_fast = self.app.ws_b_val(self.sheet)
                ws_a_edit_fast = self.app.ws_a_edit(self.sheet)
                ws_b_edit_fast = self.app.ws_b_edit(self.sheet)
            region_pos = 0
            while region_pos < total_region_rows:
                pair_idx = region_pair_indices[region_pos]
                if direction == "BASE2A":
                    cols = set(self.pair_base_diff_cols.get(pair_idx, set()))
                elif direction == "MINE2A":
                    cols = set(self.pair_diff_cols.get(pair_idx, set()))
                    cols.update(self.pair_base_diff_cols.get(pair_idx, set()))
                else:
                    cols = set(self.pair_diff_cols.get(pair_idx, set()))
                pair = self.row_pairs[pair_idx] if pair_idx < len(self.row_pairs) else None
                ra = self._row_for_side(pair, "A")
                rb = self._row_for_side(pair, "B")
                base_row = (
                    self._base_row_for_pair(pair_idx, pair)
                    if direction == "BASE2A" else None
                )
                if direction == "BASE2A" and (
                    (ra is None) != (base_row is None)
                ):
                    cols = {-1}
                if not cols:
                    region_pos += 1
                    continue

                if (
                    direction == "BASE2A"
                    and base_row is None
                    and ra is not None
                    and cols == {-1}
                ):
                    run = [(pair_idx, ra)]
                    probe = region_pos + 1
                    prev_ra = ra
                    while probe < total_region_rows:
                        next_pair_idx = region_pair_indices[probe]
                        next_pair = (
                            self.row_pairs[next_pair_idx]
                            if next_pair_idx < len(self.row_pairs) else None
                        )
                        next_ra = self._row_for_side(next_pair, "A")
                        next_base = self._base_row_for_pair(
                            next_pair_idx,
                            next_pair,
                        )
                        if next_base is not None or next_ra is None:
                            break
                        if int(next_ra) != int(prev_ra) + 1:
                            break
                        run.append((next_pair_idx, next_ra))
                        prev_ra = next_ra
                        probe += 1
                    row_changed = self._batch_delete_rows_for_missing_source(
                        run,
                        direction="BASE2A",
                        suppress_refresh=True,
                        anchor=anchor,
                    )
                    if row_changed:
                        changed_any = True
                        structural_rows_changed = True
                    processed_rows += len(run)
                    region_pos = probe
                    continue

                if (
                    direction == "BASE2A"
                    and ra is None
                    and base_row is not None
                    and cols == {-1}
                ):
                    run = [(pair_idx, base_row)]
                    probe = region_pos + 1
                    prev_base = base_row
                    while probe < total_region_rows:
                        next_pair_idx = region_pair_indices[probe]
                        next_pair = (
                            self.row_pairs[next_pair_idx]
                            if next_pair_idx < len(self.row_pairs) else None
                        )
                        next_ra = self._row_for_side(next_pair, "A")
                        next_base = self._base_row_for_pair(
                            next_pair_idx,
                            next_pair,
                        )
                        if next_ra is not None or next_base is None:
                            break
                        if int(next_base) != int(prev_base) + 1:
                            break
                        run.append((next_pair_idx, next_base))
                        prev_base = next_base
                        probe += 1
                    row_changed = self._batch_insert_row_copy(
                        run,
                        direction="BASE2A",
                        suppress_refresh=True,
                        anchor=anchor,
                    )
                    if row_changed:
                        changed_any = True
                        structural_rows_changed = True
                    processed_rows += len(run)
                    region_pos = probe
                    continue

                if direction == "B2A" and rb is None and ra is not None and cols == {-1}:
                    run: list[tuple[int, int]] = [(pair_idx, ra)]
                    probe = region_pos + 1
                    prev_ra = ra
                    while probe < total_region_rows:
                        next_pair_idx = region_pair_indices[probe]
                        next_cols = set(self.pair_diff_cols.get(next_pair_idx, set()))
                        next_pair = self.row_pairs[next_pair_idx] if next_pair_idx < len(self.row_pairs) else None
                        next_ra = self._row_for_side(next_pair, "A")
                        next_rb = self._row_for_side(next_pair, "B")
                        if next_cols != {-1} or next_rb is not None or next_ra is None:
                            break
                        if int(next_ra) != int(prev_ra) + 1:
                            break
                        run.append((next_pair_idx, next_ra))
                        prev_ra = next_ra
                        probe += 1
                    row_changed = self._batch_delete_rows_for_missing_source(
                        run,
                        direction="B2A",
                        suppress_refresh=True,
                        anchor=anchor,
                    )
                    if row_changed:
                        changed_any = True
                        structural_rows_changed = True
                    processed_rows += len(run)
                    region_pos = probe
                    continue

                if direction == "A2B" and ra is None and rb is not None and cols == {-1}:
                    run = [(pair_idx, rb)]
                    probe = region_pos + 1
                    prev_rb = rb
                    while probe < total_region_rows:
                        next_pair_idx = region_pair_indices[probe]
                        next_cols = set(self.pair_diff_cols.get(next_pair_idx, set()))
                        next_pair = self.row_pairs[next_pair_idx] if next_pair_idx < len(self.row_pairs) else None
                        next_ra = self._row_for_side(next_pair, "A")
                        next_rb = self._row_for_side(next_pair, "B")
                        if next_cols != {-1} or next_ra is not None or next_rb is None:
                            break
                        if int(next_rb) != int(prev_rb) + 1:
                            break
                        run.append((next_pair_idx, next_rb))
                        prev_rb = next_rb
                        probe += 1
                    row_changed = self._batch_delete_rows_for_missing_source(
                        run,
                        direction="A2B",
                        suppress_refresh=True,
                        anchor=anchor,
                    )
                    if row_changed:
                        changed_any = True
                        structural_rows_changed = True
                    processed_rows += len(run)
                    region_pos = probe
                    continue

                if direction == "B2A" and ra is None and rb is not None and cols == {-1}:
                    run: list[tuple[int, int]] = [(pair_idx, rb)]
                    probe = region_pos + 1
                    prev_rb = rb
                    while probe < total_region_rows:
                        next_pair_idx = region_pair_indices[probe]
                        next_cols = set(self.pair_diff_cols.get(next_pair_idx, set()))
                        next_pair = self.row_pairs[next_pair_idx] if next_pair_idx < len(self.row_pairs) else None
                        next_ra = self._row_for_side(next_pair, "A")
                        next_rb = self._row_for_side(next_pair, "B")
                        if next_cols != {-1} or next_ra is not None or next_rb is None:
                            break
                        if int(next_rb) != int(prev_rb) + 1:
                            break
                        run.append((next_pair_idx, next_rb))
                        prev_rb = next_rb
                        probe += 1
                    row_changed = self._batch_insert_row_copy(
                        run,
                        direction="B2A",
                        suppress_refresh=True,
                        anchor=anchor,
                    )
                    if row_changed:
                        changed_any = True
                    processed_rows += len(run)
                    region_pos = probe
                    continue

                if direction == "A2B" and rb is None and ra is not None and cols == {-1}:
                    run = [(pair_idx, ra)]
                    probe = region_pos + 1
                    prev_ra = ra
                    while probe < total_region_rows:
                        next_pair_idx = region_pair_indices[probe]
                        next_cols = set(self.pair_diff_cols.get(next_pair_idx, set()))
                        next_pair = self.row_pairs[next_pair_idx] if next_pair_idx < len(self.row_pairs) else None
                        next_ra = self._row_for_side(next_pair, "A")
                        next_rb = self._row_for_side(next_pair, "B")
                        if next_cols != {-1} or next_rb is not None or next_ra is None:
                            break
                        if int(next_ra) != int(prev_ra) + 1:
                            break
                        run.append((next_pair_idx, next_ra))
                        prev_ra = next_ra
                        probe += 1
                    row_changed = self._batch_insert_row_copy(
                        run,
                        direction="A2B",
                        suppress_refresh=True,
                        anchor=anchor,
                    )
                    if row_changed:
                        changed_any = True
                    processed_rows += len(run)
                    region_pos = probe
                    continue

                if (
                    fast_b2a
                    and ra is not None
                    and rb is not None
                    and cols
                    and all(int(c) > 0 for c in cols)
                ):
                    applied_cols = set()
                    row_undo = []
                    for c in sorted(int(c) for c in cols):
                        physical_cols = self._action_physical_columns("B2A", c)
                        if physical_cols is None:
                            continue
                        src_col, dst_col = physical_cols
                        old_edit = ws_a_edit_fast.cell(row=ra, column=dst_col).value
                        old_val = ws_a_val_fast.cell(row=ra, column=dst_col).value
                        source_edit = ws_b_edit_fast.cell(row=rb, column=src_col).value
                        source_val = ws_b_val_fast.cell(row=rb, column=src_col).value
                        new_edit = _copy_edit_value_for_destination(
                            source_val, source_edit, old_edit,
                            src_row=rb, src_col=src_col, dst_row=ra, dst_col=dst_col,
                        )
                        formula_mode = self._same_formula_copy_mode(
                            new_edit, old_edit, source_val, old_val
                        )
                        if formula_mode == "noop":
                            continue
                        if formula_mode == "cache":
                            ws_a_val_fast.cell(row=ra, column=dst_col).value = source_val
                            self.app.record_manual_a_formula_cache(self.sheet, ra, dst_col, source_val)
                        else:
                            _assign_edit_cell_value(ws_a_edit_fast.cell(row=ra, column=dst_col), new_edit)
                            ws_a_val_fast.cell(row=ra, column=dst_col).value = source_val
                            self.app.record_manual_a_cell(self.sheet, ra, dst_col, new_edit)
                        row_undo.append((ra, dst_col, old_edit, old_val))
                        applied_cols.add(c)
                    if row_undo:
                        undo_cells_region.extend(row_undo)
                        self.app.modified_a = True
                        self.app.modified_sheets_a.add(self.sheet)
                        self.touched_rows.add(int(ra))
                        changed_any = True
                    if getattr(self.app, "merge_conflict_mode", False) and applied_cols:
                        self.app.user_touched_conflicts = True
                        self._resolve_conflict_row(ra, applied_cols, refresh=False)
                    processed_rows += 1
                    if processed_rows % 200 == 0:
                        try:
                            self.info.configure(
                                text=f"正在采用{direction_text}：{processed_rows}/{total_region_rows} 行..."
                            )
                            self.root.update_idletasks()
                        except Exception:
                            pass
                    region_pos += 1
                    continue
                # In 3-way mode, "采用Base" is kept as its own button.
                # Left/Right region actions follow left/right semantics only.
                row_changed = self._copy_selected_row(
                    direction,
                    row_header=False,
                    override_pair_idx=pair_idx,
                    override_cols=cols,
                    suppress_refresh=True,
                    _undo_out=undo_cells_region,
                    _difference_ids_out=retain_difference_ids,
                )
                if row_changed:
                    changed_any = True
                processed_rows += 1
                if processed_rows % 200 == 0:
                    try:
                        self.info.configure(
                            text=f"正在采用{direction_text}：{processed_rows}/{total_region_rows} 行..."
                        )
                        self.root.update_idletasks()
                    except Exception:
                        pass
                region_pos += 1
            if changed_any:
                if direction == "MINE2A":
                    # Retain is metadata-only.  Do not mark a cell edit or
                    # invalidate the logical column projection; one undo
                    # restores the exact DifferenceItem processed states.
                    self.app.finish_undo_group(commit=False)
                    undo_group_active = False
                    if retain_difference_ids:
                        self.app.push_undo({
                            "kind": "difference_state",
                            "sheet": self.sheet,
                            "item_ids": tuple(retain_difference_ids),
                        })
                    self._refresh_diff_block_ui()
                    self._update_cursor_lines()
                    try:
                        self.info.configure(
                            text=(
                                f"已保留{self.role_presentation.left}，未写入任何数据；"
                                f"已标记 {len(retain_difference_ids) or processed_rows} 项为已处理。"
                            )
                        )
                    except Exception:
                        pass
                else:
                    if undo_cells_region:
                        self.app.push_undo({"sheet": self.sheet, "target": undo_target, "cells": undo_cells_region})
                    self.app.finish_undo_group(commit=True)
                    undo_group_active = False
                    if not structural_rows_changed:
                        self._mark_nonstructural_cell_edit(
                            "region-overwrite",
                            edited_sides=("B",) if direction == "A2B" else ("A",),
                        )
                    self._invalidate_render_cache()
                    if structural_rows_changed:
                        self._invalidate_only_diff_snapshot_cache()
                        self.refresh(row_only=None, rescan=True)
                        exact_region_rows = 0
                    else:
                        exact_region_rows = self._refresh_pair_indices_exact(region_pair_indices)
                        if bool(self.only_diff_var.get()) and self.snapshot_only_diff:
                            self._cache_only_diff_rows_from_exact_pair_maps()
                        # Exact pair caches above already contain every changed row;
                        # one non-rescanning render is sufficient for any region size.
                        self.refresh(row_only=None, rescan=False)
                    self._invalidate_render_cache()
                    self._refresh_diff_block_ui()
                    _dlog(
                        f"OVERWRITE_REGION_EXACT_REFRESH sheet={self.sheet} "
                        f"pairs={exact_region_rows} visible={len(self.display_rows)}"
                    )
                    self._restore_view_anchor(anchor)
                    self._update_cursor_lines()
                    try:
                        elapsed = time.perf_counter() - started
                        self.info.configure(
                            text=f"已采用{direction_text}：{processed_rows} 行，耗时 {elapsed:.1f} 秒"
                        )
                    except Exception:
                        pass
            else:
                self.app.finish_undo_group(commit=False)
                undo_group_active = False
                self._show_region_action_feedback(direction, "unchanged")
            formula_skipped = int(getattr(self, "_formula_copy_skips_pending", 0)) - formula_skip_before
            if formula_skipped > 0:
                self._show_formula_copy_skip_notice(formula_skipped)
        except Exception as e:
            if undo_group_active:
                try:
                    if undo_cells_region:
                        undo_target = "A" if direction in ("B2A", "BASE2A") else "B"
                        self.app.push_undo({
                            "sheet": self.sheet,
                            "target": undo_target,
                            "cells": undo_cells_region,
                        })
                    rollback_action = self.app.finish_undo_group(commit=True)
                    undo_group_active = False
                    if rollback_action is not None:
                        self._undo_last_action(_internal_rollback=True)
                    _dlog(
                        f"OVERWRITE_REGION_ROLLBACK sheet={self.sheet} "
                        f"dir={direction} err={e}"
                    )
                except Exception as rollback_error:
                    _dlog(
                        f"CRITICAL region rollback failed sheet={self.sheet} "
                        f"dir={direction} err={rollback_error}"
                    )
            messagebox.showerror("Error", f"覆盖区域失败：\n{e}")
        finally:
            if undo_group_active:
                self.app.finish_undo_group(commit=False)
            self._suppress_bg_apply = previous_bg_suppression
            if callable(end_interactive):
                end_interactive()
            try:
                self.root.configure(cursor="")
            except Exception:
                pass
            _dlog(
                f"OVERWRITE_REGION_END sheet={self.sheet} dir={direction} "
                f"processed={processed_rows} changed={int(bool(changed_any))} "
                f"ms={(time.perf_counter() - started) * 1000.0:.1f}"
            )
        return bool(changed_any)

    def _update_diff_nav_state(self):
        try:
            only_diff = bool(self.only_diff_var.get())
        except Exception:
            only_diff = False
        if only_diff:
            self._update_diff_block_indicator()
            if not self._diff_block_model_ready():
                self.prev_diff_btn.configure(state="disabled")
                self.next_diff_btn.configure(state="disabled")
                return
            blocks = self._ensure_full_diff_blocks()
            active_idx = self._active_full_diff_block_index()
            if not blocks or active_idx is None:
                self.prev_diff_btn.configure(state="disabled")
                self.next_diff_btn.configure(state="disabled")
                return
            self.prev_diff_btn.configure(state=("normal" if active_idx > 0 else "disabled"))
            self.next_diff_btn.configure(state=("normal" if active_idx + 1 < len(blocks) else "disabled"))
            return

        blocks = self._compute_diff_blocks()
        if not blocks:
            self.prev_diff_btn.configure(state="disabled")
            self.next_diff_btn.configure(state="disabled")
            self._update_diff_block_indicator()
            return

        cur = self._current_line()
        has_prev = any(b[1] < cur for b in blocks)  # only enable when a block ends before cursor
        has_next = any(b[0] > cur for b in blocks)
        self.prev_diff_btn.configure(state=("normal" if has_prev else "disabled"))
        self.next_diff_btn.configure(state=("normal" if has_next else "disabled"))
        self._update_diff_block_indicator()

    def _replace_rendered_rows_for_navigation(self, rows: list[int]):
        """Replace the visible only-diff page with a bounded navigation preview."""
        rows = [int(pair_idx) for pair_idx in rows]
        saved_x = 0.0
        try:
            saved_x = float((self.left.xview() or (0.0, 1.0))[0])
        except Exception:
            pass
        for widget in (self.left, self.base, self.right):
            try:
                widget.delete("1.0", "end")
            except Exception:
                pass
        for widget in (self.left_ln, self.base_ln, self.right_ln):
            try:
                widget.configure(state="normal")
                widget.delete("1.0", "end")
                widget.configure(state="disabled")
            except Exception:
                pass
        self.display_rows = []
        self.row_to_line = {}
        self._display_diff_row_count = 0
        self._render_limit = len(rows)
        self._append_rows(rows, refresh_block_ui=False)
        # Apply boundary tags once. _goto_block_start() will update the indicator
        # after selecting the target, so doing the full refresh here duplicated
        # model/indicator work on every navigation click.
        self._apply_diff_block_presentation()
        try:
            # _goto_block_start reads the current main-pane fraction and then
            # restores all synchronized panes, so only the main pane is needed
            # here.
            self._sync_main_x_to_frac(saved_x)
        except Exception:
            pass

    def _materialize_pair_for_navigation(self, pair_idx: int) -> bool:
        pair_idx = self._normalize_pair_idx(pair_idx)
        if pair_idx is None:
            return False
        if pair_idx in self.row_to_line:
            return True
        try:
            target_pos = bisect.bisect_left(self._full_display_rows, pair_idx)
            if target_pos >= len(self._full_display_rows) or self._full_display_rows[target_pos] != pair_idx:
                return False
        except Exception:
            return False
        # Navigation targets a logical block.  On large sheets, materializing
        # every preceding diff row (or a 400+ row block) makes a button click
        # seconds long.  A bounded preview keeps the interaction synchronous and
        # the full logical block model remains available to region actions.
        target_end_pos = target_pos
        target_block = self._full_diff_block_for_pair(pair_idx)
        if target_block is not None:
            try:
                candidate = bisect.bisect_left(
                    self._full_display_rows,
                    target_block.end_pair_idx,
                    lo=target_pos,
                )
                if (
                    candidate < len(self._full_display_rows)
                    and self._full_display_rows[candidate] == target_block.end_pair_idx
                ):
                    target_end_pos = candidate
            except Exception:
                target_end_pos = target_pos
        old_limit = len(self.display_rows)
        new_limit = min(len(self._full_display_rows), target_end_pos + 1)
        rendered_is_prefix = self.display_rows == self._full_display_rows[:old_limit]
        if new_limit <= old_limit and rendered_is_prefix:
            return pair_idx in self.row_to_line
        if self._is_large_sheet and (
            (not rendered_is_prefix)
            or (new_limit - old_limit) > _LARGE_DIFF_NAV_PREVIEW_ROWS
        ):
            preview_end = min(
                target_end_pos + 1,
                target_pos + _LARGE_DIFF_NAV_PREVIEW_ROWS,
            )
            preview_rows = self._full_display_rows[target_pos:preview_end]
            try:
                self.info.configure(
                    text=f"正在定位差异块：显示 {len(preview_rows)} 条预览行..."
                )
                self.root.update_idletasks()
            except Exception:
                pass
            self._replace_rendered_rows_for_navigation(preview_rows)
            self._diff_navigation_last = {
                "mode": "bounded-preview",
                "rows": len(preview_rows),
                "pair": pair_idx,
            }
            _dlog(
                f"DIFF_BLOCK_NAV_PREVIEW sheet={self.sheet} pair={pair_idx} "
                f"rows={len(preview_rows)} cap={_LARGE_DIFF_NAV_PREVIEW_ROWS} rescan=0"
            )
            return pair_idx in self.row_to_line
        try:
            self.info.configure(text=f"正在定位差异块：加载到第 {new_limit} 条差异行...")
            self.root.update_idletasks()
        except Exception:
            pass
        self._render_limit = max(int(self._render_limit or 0), new_limit)
        self._append_rows(self._full_display_rows[old_limit:new_limit])
        self._diff_navigation_last = {
            "mode": "append",
            "rows": new_limit - old_limit,
            "pair": pair_idx,
        }
        _dlog(
            f"DIFF_BLOCK_MATERIALIZE sheet={self.sheet} pair={pair_idx} "
            f"rows={old_limit}->{new_limit} rescan=0"
        )
        return pair_idx in self.row_to_line

    def _goto_full_diff_block(self, block_idx: int):
        blocks = self._ensure_full_diff_blocks()
        if not (0 <= int(block_idx) < len(blocks)):
            self._update_diff_nav_state()
            return
        pair_idx = blocks[int(block_idx)].start_pair_idx
        if not self._materialize_pair_for_navigation(pair_idx):
            self._update_diff_nav_state()
            return
        line = self.row_to_line.get(pair_idx)
        if line is None:
            self._update_diff_nav_state()
            return
        self._goto_block_start(line)

    def _goto_block_start(self, start_line: int):
        # Scroll so the line is visible
        try:
            # Preserve horizontal position: see() would reset xview to column 0.
            saved_x = 0.0
            try:
                saved_x = float((self.left.xview() or (0.0, 1.0))[0])
            except Exception:
                pass
            nav_widgets = [self.left, self.right]
            if self._is_three_way_enabled():
                nav_widgets.insert(1, self.base)
            for w in nav_widgets:
                w.mark_set("insert", f"{start_line}.0")
                w.see(f"{start_line}.0")
            # Restore horizontal position after see() reset it.
            try:
                self._sync_main_x_to_frac(saved_x)
                self._sync_c_x_to_frac(saved_x)
            except Exception:
                pass
            self._highlight_selected_line(start_line)
            pair = self._pair_for_line(start_line)
            self.selected_pair_idx = self._pair_idx_for_line(start_line)
            self.hover_pair_idx = self._normalize_pair_idx(self.selected_pair_idx)
            self.hover_col_idx = None
            self.hover_side = None
            self.selected_excel_row_a = self._row_for_side(pair, "A")
            self.selected_excel_row_b = self._row_for_side(pair, "B")
            self.selected_excel_row = self.selected_excel_row_a or self.selected_excel_row_b
            self._set_main_selected_cell(start_line, None)
            self._update_cursor_lines()
        except Exception:
            pass
        self._update_diff_nav_state()

    def focus_logical_cell(self, excel_row: int, logical_col: int) -> bool:
        """Materialize and visibly select one logical cell by Excel row/column."""
        try:
            excel_row = max(1, int(excel_row))
            logical_col = max(1, int(logical_col))
        except Exception:
            return False

        pair_idx = self._normalize_pair_idx(
            self.row_a_to_pair_idx.get(excel_row)
        )
        if pair_idx is None:
            pair_idx = self._normalize_pair_idx(
                self.row_b_to_pair_idx.get(excel_row)
            )
        if pair_idx is None:
            pair_idx = next(
                (
                    idx
                    for idx, pair in enumerate(self.row_pairs)
                    if excel_row in tuple(value for value in pair if value is not None)
                ),
                None,
            )
            pair_idx = self._normalize_pair_idx(pair_idx)
        if pair_idx is None or not self._materialize_pair_for_navigation(pair_idx):
            return False
        line = self.row_to_line.get(pair_idx)
        if line is None:
            return False
        line = int(line)
        self._goto_block_start(line)
        self._set_main_selected_cell(line, logical_col)
        self.selected_pair_idx = pair_idx
        pair = self.row_pairs[pair_idx]
        row_a = self._row_for_side(pair, "A")
        row_b = self._row_for_side(pair, "B")
        self.selected_excel_row_a = row_a
        self.selected_excel_row_b = row_b
        self.selected_excel_row = row_a or row_b
        self.hover_pair_idx = pair_idx
        self.hover_col_idx = logical_col
        self.hover_side = "A" if row_a is not None else "B"

        if self._is_three_way_enabled():
            if row_a is not None and self._slot_exists_on_side("A", logical_col):
                cursor_line = 2
            elif row_b is not None and self._slot_exists_on_side("B", logical_col):
                cursor_line = 3
            else:
                cursor_line = 1
        else:
            cursor_line = (
                1
                if row_a is not None and self._slot_exists_on_side("A", logical_col)
                else 2
            )
        self._cursor_cmp_sel_col = logical_col
        self._cursor_cmp_sel_line = cursor_line
        self._last_cursor_cmp_pair_idx = pair_idx
        self._update_cursor_lines()

        try:
            spans = self._spans_for_line()
            start_char = int(spans.get(logical_col, (0, 0))[0])
            cell_index = f"{line}.{max(0, start_char)}"
            nav_widgets = [self.left, self.right]
            if self._is_three_way_enabled():
                nav_widgets.insert(1, self.base)
            for widget in nav_widgets:
                widget.mark_set("insert", cell_index)
                widget.see(cell_index)
            try:
                fraction = float((self.left.xview() or (0.0, 1.0))[0])
                self._sync_main_x_to_frac(fraction)
                self._sync_c_x_to_frac(fraction)
            except Exception:
                pass
        except Exception:
            pass

        focus_widget = self.left
        if row_a is None or not self._slot_exists_on_side("A", logical_col):
            focus_widget = self.right
        try:
            focus_widget.focus_set()
        except Exception:
            pass
        try:
            excel_coordinate = f"{get_column_letter(logical_col)}{excel_row}"
            self.info.configure(
                text=(
                    f"已定位首个冲突：{self.sheet}｜{excel_coordinate}｜"
                    f"第 {excel_row} 行，Excel 列 {_excel_column_display(logical_col)}"
                )
            )
        except Exception:
            pass
        _dlog(
            f"CONFLICT_CELL_FOCUSED sheet={self.sheet} row={excel_row} "
            f"logical_col={logical_col} pair={pair_idx} line={line}"
        )
        return True

    def _goto_next_diff_block(self):
        try:
            if bool(self.only_diff_var.get()):
                blocks = self._ensure_full_diff_blocks()
                active_idx = self._active_full_diff_block_index()
                if blocks:
                    target_idx = 0 if active_idx is None else active_idx + 1
                    if target_idx < len(blocks):
                        self._goto_full_diff_block(target_idx)
                        return
                self._update_diff_nav_state()
                return
        except Exception:
            pass
        blocks = self._compute_diff_blocks()
        cur = self._current_line()
        for start, _end in blocks:
            if start > cur:
                self._goto_block_start(start)
                return
        self._update_diff_nav_state()

    def _on_next_diff_block_shortcut(self, event=None):
        """Handle the keyboard shortcut for the next logical diff block."""
        self._goto_next_diff_block()
        return "break"

    def _goto_prev_diff_block(self):
        try:
            if bool(self.only_diff_var.get()):
                active_idx = self._active_full_diff_block_index()
                if active_idx is not None and active_idx > 0:
                    self._goto_full_diff_block(active_idx - 1)
                    return
                self._update_diff_nav_state()
                return
        except Exception:
            pass
        blocks = self._compute_diff_blocks()
        cur = self._current_line()
        prev = None
        for start, end in blocks:
            if end < cur:
                prev = start
            elif start >= cur:
                break
        if prev is not None:
            self._goto_block_start(prev)
        self._update_diff_nav_state()

    def _on_prev_diff_block_shortcut(self, event=None):
        """Handle the keyboard shortcuts for the previous logical diff block."""
        self._goto_prev_diff_block()
        return "break"

    # ---------- Diff calculation helpers ----------
    def _get_row_values(self, ws, r: int):
        # Fast row read using iter_rows(values_only=True)
        try:
            row = next(ws.iter_rows(min_row=r, max_row=r, min_col=1, max_col=self.max_col, values_only=True))
        except StopIteration:
            row = ()
        if row is None:
            row = ()
        # Ensure length == max_col
        if len(row) < self.max_col:
            row = tuple(row) + (None,) * (self.max_col - len(row))
        return row

    def _show_loading(self, message: str = "正在后台计算差异，请稍候..."):
        """Show a loading placeholder while background diff computation is in progress."""
        if bool(getattr(self, "only_diff_var", None) and self.only_diff_var.get()):
            message = "只看差异 | 正在后台生成精确差异；当前只读，可查看或切换 Sheet..."
        try:
            if not self.loading_progress.winfo_manager():
                self.loading_progress.pack(side="left", padx=(10, 0))
            self.loading_progress.start(12)
            for w in (self.left, self.right):
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", "正在加载并计算差异...\n")
            for w in (self.left_ln, self.base_ln, self.right_ln):
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", "\n")
                w.configure(state="disabled")
            self.info.configure(text=message)
        except Exception:
            pass
        self._refresh_interaction_gate()

    def _hide_loading(self):
        try:
            self.loading_progress.stop()
            self.loading_progress.pack_forget()
        except Exception:
            pass
        self._refresh_interaction_gate()

    @staticmethod
    def _row_label(r: int | None) -> str:
        return str(r) if r is not None else ""

    def _build_line_from_row_label(self, label: str, row_vals) -> str:
        parts = [_val_to_str(v) for v in row_vals]
        parts = self._gridify_parts(parts)
        return "\t".join(parts)

    def _build_row_and_diff_pair(self, ws_a_val, ws_b_val, ws_a_edit, ws_b_edit, ra: int | None, rb: int | None):
        """Build display lines and diff columns for a row pair.
        col_char_widths must be pre-populated before calling (see _prescan_col_widths)."""
        rows_a_val = _read_rows_into_cache(ws_a_val, (ra,), self.max_col)
        rows_b_val = _read_rows_into_cache(ws_b_val, (rb,), self.max_col)
        rows_a_edit = (
            _read_rows_into_cache(ws_a_edit, (ra,), self.max_col)
            if ws_a_edit is not None else {}
        )
        rows_b_edit = (
            _read_rows_into_cache(ws_b_edit, (rb,), self.max_col)
            if ws_b_edit is not None else {}
        )
        return self._build_row_and_diff_pair_from_values(
            _row_from_cache(rows_a_val, ra, self.max_col),
            _row_from_cache(rows_b_val, rb, self.max_col),
            ra=ra,
            rb=rb,
            row_a_edit_vals=_row_from_cache(rows_a_edit, ra, self.max_col),
            row_b_edit_vals=_row_from_cache(rows_b_edit, rb, self.max_col),
        )

    def _render_line_from_raw_parts(self, raw_parts: list[str], side: str | None = None) -> str:
        if side is not None:
            raw_parts = self._project_raw_parts(raw_parts, side)
        grid_on = self._is_grid_overlay_enabled()
        sep = _COL_SEP if grid_on else "   "
        trail = " \u2502" if grid_on else ""
        return sep.join(
            _format_cell(raw_parts[i], self.col_char_widths.get(i + 1, 1))
            for i in range(len(raw_parts))
        ) + trail

    def _raw_parts_from_row_values(self, row_vals, max_col: int | None = None) -> list[str]:
        row_vals = _pad_row_values(row_vals, int(max_col or self.max_col))
        return [_val_to_str(v) for v in row_vals]

    def _expected_column_model_cache_key(self) -> ColumnModelCacheKey:
        return ColumnModelCacheKey(
            self.sheet,
            max(0, int(getattr(self, "_row_model_version", 0))),
            max(0, int(getattr(self, "_column_model_version", 0))),
            max(0, int(getattr(self, "_mine_edit_version", 0))),
            max(0, int(getattr(self, "_base_edit_version", 0))),
            max(0, int(getattr(self, "_theirs_edit_version", 0))),
        )

    def _retag_column_comparison_cache(
        self,
        cache: LogicalColumnComparisonCache,
        cache_key: ColumnModelCacheKey,
    ) -> LogicalColumnComparisonCache:
        if cache.model.cache_key == cache_key:
            return cache
        # A value/formula edit advances edit versions but cannot change column
        # geometry. Retag the immutable model while preserving its slot/block
        # and lookup objects; rebuilding signatures/lookups here turned a
        # single-cell edit into a full-sheet structural scan.
        old_model = cache.model
        model = ColumnModel(
            cache_key=cache_key,
            slots=old_model.slots,
            blocks=old_model.blocks,
            mine_physical_to_logical=old_model.mine_physical_to_logical,
            base_physical_to_logical=old_model.base_physical_to_logical,
            theirs_physical_to_logical=old_model.theirs_physical_to_logical,
            mine_logical_to_physical=old_model.mine_logical_to_physical,
            base_logical_to_physical=old_model.base_logical_to_physical,
            theirs_logical_to_physical=old_model.theirs_logical_to_physical,
            confidence=old_model.confidence,
        )
        return LogicalColumnComparisonCache(
            model=model,
            two_way_alignment=cache.two_way_alignment,
            three_way_alignment=cache.three_way_alignment,
            structural_diff_cols=cache.structural_diff_cols,
            unresolved_cols=cache.unresolved_cols,
        )

    def _mark_column_mapping_stale(
        self,
        reason: str,
        *,
        row_structure: bool = False,
        column_structure: bool = False,
        edited_sides=(),
    ):
        if row_structure:
            self._row_model_version = int(getattr(self, "_row_model_version", 0)) + 1
            self._row_alignment_reuse_requested = False
        elif getattr(self, "row_pairs", None):
            self._row_alignment_reuse_requested = True
        if column_structure:
            self._column_model_version = int(getattr(self, "_column_model_version", 0)) + 1
        normalized_sides = set()
        for side in edited_sides or ():
            try:
                normalized_sides.add(_normalize_logical_column_side(side))
            except Exception:
                continue
        if "mine" in normalized_sides:
            self._mine_edit_version = int(getattr(self, "_mine_edit_version", 0)) + 1
        if "base" in normalized_sides:
            self._base_edit_version = int(getattr(self, "_base_edit_version", 0)) + 1
        if "theirs" in normalized_sides:
            self._theirs_edit_version = int(getattr(self, "_theirs_edit_version", 0)) + 1
        self._column_mapping_stale_reason = str(reason or "worksheet-edited")
        self._invalidate_only_diff_snapshot_cache()
        self._diff_map_cache = None
        self._diff_map_cache_version = None

    def _mark_nonstructural_cell_edit(self, reason: str, *, edited_sides=()):
        """Advance edit versions while keeping proven column geometry current."""
        cache = self._active_column_comparison_cache()
        self._mark_column_mapping_stale(reason, edited_sides=edited_sides)
        self._install_column_projection(
            self._retag_column_comparison_cache(
                cache,
                self._expected_column_model_cache_key(),
            )
        )

    def _column_mapping_is_current(self) -> bool:
        cache = getattr(self, "column_comparison_cache", None)
        projection = getattr(self, "column_projection", None)
        return bool(
            isinstance(cache, LogicalColumnComparisonCache)
            and isinstance(projection, LogicalColumnProjection)
            and projection.model is cache.model
            and cache.model.cache_key == self._expected_column_model_cache_key()
            and not getattr(self, "_column_mapping_stale_reason", "")
        )

    def _ensure_column_projection_current(
        self,
        operation: str,
        *,
        ws_a_val=None,
        ws_b_val=None,
        ws_a_edit=None,
        ws_b_edit=None,
        ws_base_val=None,
        ws_base_edit=None,
        allow_rebuild: bool = True,
    ) -> LogicalColumnProjection:
        if self._column_mapping_is_current():
            return self.column_projection
        stale_reason = getattr(self, "_column_mapping_stale_reason", "") or "版本不一致"
        if not allow_rebuild:
            raise RuntimeError(
                f"{operation}前的列映射已过期（{stale_reason}），已安全停止。"
            )
        if self._is_missing_sheet_view():
            # A sheet-level action can legitimately leave one comparison side
            # absent (for example BaseOnly copied to mine while theirs still has
            # no such sheet).  Saving that whole-sheet operation does not need a
            # signature rebuild, and must not call ws_* for the absent side.
            # Install a version-current physical-order projection whose absent
            # sides have no physical columns instead.
            return self._install_column_projection(
                self._identity_column_comparison_cache()
            )
        try:
            ws_a_val = ws_a_val or self.app.ws_a_val(self.sheet)
            ws_b_val = ws_b_val or self.app.ws_b_val(self.sheet)
            ws_a_edit = ws_a_edit or self.app.ws_a_edit(self.sheet)
            ws_b_edit = ws_b_edit or self.app.ws_b_edit(self.sheet)
            if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
                ws_base_val = ws_base_val or self.app.ws_base_val(self.sheet)
                ws_base_edit = ws_base_edit or self.app.ws_base_edit(self.sheet)
            self._rebuild_column_comparison_cache_from_worksheets(
                ws_a_val,
                ws_b_val,
                ws_a_edit,
                ws_b_edit,
                ws_base_val=ws_base_val,
                ws_base_edit=ws_base_edit,
            )
        except Exception as exc:
            raise RuntimeError(
                f"{operation}前无法重建过期列映射（{stale_reason}）：{exc}"
            ) from exc
        if not self._column_mapping_is_current():
            raise RuntimeError(f"{operation}前列映射版本校验失败，已安全停止。")
        return self.column_projection

    def _install_column_projection(
        self, cache: LogicalColumnComparisonCache
    ) -> LogicalColumnProjection:
        cache = self._retag_column_comparison_cache(
            cache, self._expected_column_model_cache_key()
        )
        projection = LogicalColumnProjection.from_model(cache.model)
        self.column_comparison_cache = cache
        self.column_projection = projection
        self._column_projection_generation = int(
            getattr(self, "_column_projection_generation", 0)
        ) + 1
        self._column_mapping_stale_reason = ""
        self._set_uniform_logical_column_widths(projection)
        self._base_spans_cache = None
        self._base_spans_cache_key = None
        return projection

    def _active_column_projection(self) -> LogicalColumnProjection:
        cache = self._active_column_comparison_cache()
        projection = getattr(self, "column_projection", None)
        if (
            isinstance(projection, LogicalColumnProjection)
            and projection.model is cache.model
        ):
            return projection
        return self._install_column_projection(cache)

    def _logical_slot_count(self) -> int:
        return max(1, int(self._active_column_projection().slot_count or 0))

    def _physical_col_for_logical(self, side: str, logical_col: int) -> int | None:
        return self._active_column_projection().physical_col(side, logical_col)

    def _logical_col_for_physical(self, side: str, physical_col: int) -> int | None:
        return self._active_column_projection().logical_col(side, physical_col)

    def _slot_exists_on_side(self, side: str, logical_col: int) -> bool:
        return self._physical_col_for_logical(side, logical_col) is not None

    def _project_raw_parts(self, raw_parts, side: str) -> list[str]:
        projection = self._active_column_projection()
        values = list(raw_parts or ())
        projected = []
        for logical_col in range(1, projection.slot_count + 1):
            physical_col = projection.physical_col(side, logical_col)
            if physical_col is None:
                projected.append(_LOGICAL_COLUMN_PLACEHOLDER)
                continue
            offset = int(physical_col) - 1
            projected.append(values[offset] if 0 <= offset < len(values) else "")
        return projected

    def _projected_widths_from_cached_parts(
        self,
        pair_parts_a=None,
        pair_parts_b=None,
        pair_parts_base=None,
        fallback_physical_widths=None,
    ):
        # Background caches still carry raw parts for text/diff rendering, but
        # never participate in display geometry.  A Sheet's logical columns
        # are fixed-width across every row and pane.
        return self._set_uniform_logical_column_widths()

    def _set_uniform_logical_column_widths(
        self,
        projection: LogicalColumnProjection | None = None,
    ) -> dict[int, int]:
        """Install the Sheet-wide bounded logical-column width model.

        The formatter historically accepts a ``{logical_column: width}`` map;
        retain that interface while recording the canonical equal-width tuple.
        Content and scrolling therefore cannot change any column's geometry.
        """
        projection = projection or self._active_column_projection()
        width = max(
            _LOGICAL_COLUMN_DISPLAY_WIDTH_MIN,
            min(
                _LOGICAL_COLUMN_DISPLAY_WIDTH_MAX,
                int(getattr(self, "_logical_column_display_width", _LOGICAL_COLUMN_DISPLAY_WIDTH_MIN)),
            ),
        )
        count = max(0, int(projection.slot_count))
        widths_tuple = tuple(width for _ in range(count))
        key = (
            int(getattr(self, "_column_projection_generation", 0)),
            count,
            width,
        )
        if (
            getattr(self, "_logical_column_widths_key", None) == key
            and getattr(self, "_logical_column_widths", ()) == widths_tuple
            and len(getattr(self, "col_char_widths", {})) == count
        ):
            return self.col_char_widths
        self._logical_column_widths = widths_tuple
        self._logical_column_widths_key = key
        self.col_char_widths = {
            logical_col: width
            for logical_col in range(1, count + 1)
        }
        self._col_widths_version = int(getattr(self, "_col_widths_version", 0)) + 1
        self._base_spans_cache = None
        self._base_spans_cache_key = None
        return self.col_char_widths

    def _stage_cached_pair_parts(
        self,
        pair_parts_a,
        pair_parts_b,
        pair_parts_base,
        physical_widths,
        *,
        replace: bool = True,
    ):
        incoming_a = dict(pair_parts_a or {})
        incoming_b = dict(pair_parts_b or {})
        incoming_base = dict(pair_parts_base or {})
        if not replace and self._pending_pair_parts_cache is not None:
            old_a, old_b, old_base, old_widths, old_replace = self._pending_pair_parts_cache
            incoming_a = {**old_a, **incoming_a}
            incoming_b = {**old_b, **incoming_b}
            incoming_base = {**old_base, **incoming_base}
            physical_widths = {**(old_widths or {}), **(physical_widths or {})}
            replace = bool(old_replace)
        self._pending_pair_parts_cache = (
            incoming_a,
            incoming_b,
            incoming_base,
            dict(physical_widths or {}),
            bool(replace),
        )

    def _materialize_staged_pair_parts(self):
        staged = self._pending_pair_parts_cache
        if staged is None:
            return
        pair_parts_a, pair_parts_b, pair_parts_base, physical_widths, replace = staged
        self._pending_pair_parts_cache = None

        def _parts_with_missing_marker(pair_idx, parts, side: str):
            if parts is None:
                raw = []
            elif isinstance(parts, (str, bytes, bytearray)) or not isinstance(parts, Sequence):
                # A lightweight cache may contain one already-resolved cell
                # value.  Keep it as one physical column instead of splitting
                # text into characters or calling ``list`` on a number.
                raw = [parts]
            else:
                raw = list(parts)
            try:
                pair = self.row_pairs[int(pair_idx)]
                if side == "BASE":
                    missing = self._base_row_for_pair(int(pair_idx), pair) is None
                else:
                    missing = self._row_for_side(pair, side) is None
            except Exception:
                missing = False
            if missing:
                if not raw:
                    raw = [""]
                raw[0] = "【此侧缺行】"
            return tuple(raw)

        pair_parts_a = {
            int(idx): _parts_with_missing_marker(idx, parts, "A")
            for idx, parts in dict(pair_parts_a or {}).items()
        }
        pair_parts_b = {
            int(idx): _parts_with_missing_marker(idx, parts, "B")
            for idx, parts in dict(pair_parts_b or {}).items()
        }
        pair_parts_base = {
            int(idx): _parts_with_missing_marker(idx, parts, "BASE")
            for idx, parts in dict(pair_parts_base or {}).items()
        }
        self.pair_parts_a = {int(idx): tuple(parts) for idx, parts in pair_parts_a.items()}
        self.pair_parts_b = {int(idx): tuple(parts) for idx, parts in pair_parts_b.items()}
        self.pair_parts_base = {int(idx): tuple(parts) for idx, parts in pair_parts_base.items()}
        self._projected_widths_from_cached_parts(
            pair_parts_a,
            pair_parts_b,
            pair_parts_base,
            physical_widths,
        )
        if pair_parts_a or pair_parts_b:
            rendered_a = {
                int(idx): self._render_line_from_raw_parts(list(parts), "A")
                for idx, parts in pair_parts_a.items()
            }
            rendered_b = {
                int(idx): self._render_line_from_raw_parts(list(parts), "B")
                for idx, parts in pair_parts_b.items()
            }
            if replace:
                self.pair_text_a = rendered_a
                self.pair_text_b = rendered_b
            else:
                self.pair_text_a.update(rendered_a)
                self.pair_text_b.update(rendered_b)
        rendered_base = {
            int(idx): (
                self._render_line_from_raw_parts(list(parts), "BASE")
                if parts else ""
            )
            for idx, parts in pair_parts_base.items()
        }
        if replace:
            self.pair_text_base = rendered_base
        else:
            self.pair_text_base.update(rendered_base)

    def _identity_column_comparison_cache(self) -> LogicalColumnComparisonCache:
        """Return an immutable physical-order model until a signature cache is ready."""
        missing_view = self._is_missing_sheet_view()
        mine_width = (
            max(0, int(getattr(self, "col_max_a", self.max_col) or 0))
            if (not missing_view or self._side_has_sheet("A")) else 0
        )
        theirs_width = (
            max(0, int(getattr(self, "col_max_b", self.max_col) or 0))
            if (not missing_view or self._side_has_sheet("B")) else 0
        )
        base_width = (
            max(0, int(getattr(self, "col_max_base", self.max_col) or 0))
            if (
                self._is_three_way_enabled()
                and (not missing_view or self._side_has_sheet("BASE"))
            ) else 0
        )
        logical_width = max(mine_width, base_width, theirs_width)
        slots = []
        for offset in range(logical_width):
            mine_col = offset + 1 if offset < mine_width else None
            base_col = offset + 1 if offset < base_width else None
            theirs_col = offset + 1 if offset < theirs_width else None
            state = (
                "retained"
                if mine_col is not None and theirs_col is not None
                and (not self._is_three_way_enabled() or base_col is not None)
                else "unresolved"
            )
            slots.append(ColumnSlot(
                logical_idx=offset,
                mine_col=mine_col,
                base_col=base_col,
                theirs_col=theirs_col,
                state=state,
            ))
        key = self._expected_column_model_cache_key()
        model = ColumnModel.from_slots(key, tuple(slots), blocks=_build_column_blocks(tuple(slots)))
        return LogicalColumnComparisonCache(
            model=model,
            structural_diff_cols=frozenset(
                slot.logical_idx + 1
                for slot in slots
                if slot.mine_col is None or slot.theirs_col is None
            ),
        )

    def _active_column_comparison_cache(self) -> LogicalColumnComparisonCache:
        cache = getattr(self, "column_comparison_cache", None)
        if isinstance(cache, LogicalColumnComparisonCache):
            return cache
        return self._identity_column_comparison_cache()

    def _rebuild_column_comparison_cache_from_worksheets(
        self,
        ws_a_val,
        ws_b_val,
        ws_a_edit,
        ws_b_edit,
        *,
        ws_base_val=None,
        ws_base_edit=None,
        row_cache_bundle: dict | None = None,
    ) -> LogicalColumnComparisonCache:
        """Build signatures once from contiguous row reads and cache their model."""
        # Base is immutable during an interactive merge.  Once the background
        # scan has established its value/formula-aware effective width, retain
        # that bound instead of expanding to formatted all-blank tail columns
        # reported by Worksheet.max_column during a later forced rebuild.
        if ws_base_val is not None and not bool(
            getattr(self, "_base_bounds_checked", False)
        ):
            _base_row, base_width = _effective_bounds_with_edit(
                ws_base_val, ws_base_edit
            )
            self._base_bounds_checked = True
        else:
            base_width = max(1, int(getattr(self, "col_max_base", 1) or 1))
        self.col_max_base = base_width
        max_col = max(1, int(self.max_col or 1), base_width)
        rows_a_needed = [ra for ra, _rb in self.row_pairs if ra is not None]
        rows_b_needed = [rb for _ra, rb in self.row_pairs if rb is not None]
        rows_a_val = _read_rows_into_shared_cache(
            ws_a_val, rows_a_needed, max_col,
            cache_bundle=row_cache_bundle, cache_key="a_val",
        )
        rows_b_val = _read_rows_into_shared_cache(
            ws_b_val, rows_b_needed, max_col,
            cache_bundle=row_cache_bundle, cache_key="b_val",
        )
        rows_a_edit = (
            _read_rows_into_shared_cache(
                ws_a_edit, rows_a_needed, max_col,
                cache_bundle=row_cache_bundle, cache_key="a_edit",
            )
            if ws_a_edit is not None else {}
        )
        rows_b_edit = (
            _read_rows_into_shared_cache(
                ws_b_edit, rows_b_needed, max_col,
                cache_bundle=row_cache_bundle, cache_key="b_edit",
            )
            if ws_b_edit is not None else {}
        )
        aligned_a_val = [_row_from_cache(rows_a_val, ra, max_col) for ra, _rb in self.row_pairs]
        aligned_b_val = [_row_from_cache(rows_b_val, rb, max_col) for _ra, rb in self.row_pairs]
        aligned_a_edit = [_row_from_cache(rows_a_edit, ra, max_col) for ra, _rb in self.row_pairs]
        aligned_b_edit = [_row_from_cache(rows_b_edit, rb, max_col) for _ra, rb in self.row_pairs]
        cache_key = self._expected_column_model_cache_key()

        if ws_base_val is not None:
            base_rows = [
                self._base_row_for_pair(idx, pair)
                for idx, pair in enumerate(self.row_pairs)
            ]
            rows_base_val = _read_rows_into_shared_cache(
                ws_base_val, base_rows, max_col,
                cache_bundle=row_cache_bundle, cache_key="base_val",
            )
            rows_base_edit = (
                _read_rows_into_shared_cache(
                    ws_base_edit, base_rows, max_col,
                    cache_bundle=row_cache_bundle, cache_key="base_edit",
                )
                if ws_base_edit is not None else {}
            )
            aligned_base_val = [
                _row_from_cache(rows_base_val, base_row, max_col)
                for base_row in base_rows
            ]
            aligned_base_edit = [
                _row_from_cache(rows_base_edit, base_row, max_col)
                for base_row in base_rows
            ]
            cache = build_logical_column_comparison_cache_3way(
                cache_key,
                aligned_a_val,
                aligned_base_val,
                aligned_b_val,
                aligned_a_edit,
                aligned_base_edit,
                aligned_b_edit,
                mine_max_col=max(1, int(self.col_max_a or 1)),
                base_max_col=base_width,
                theirs_max_col=max(1, int(self.col_max_b or 1)),
            )
            self.column_alignment_3way = cache.three_way_alignment
            self.column_alignment_2way = None
        else:
            cache = build_logical_column_comparison_cache_2way(
                cache_key,
                aligned_a_val,
                aligned_b_val,
                aligned_a_edit,
                aligned_b_edit,
                mine_max_col=max(1, int(self.col_max_a or 1)),
                theirs_max_col=max(1, int(self.col_max_b or 1)),
            )
            self.column_alignment_2way = cache.two_way_alignment
            self.column_alignment_3way = None
        self._install_column_projection(cache)
        return cache

    def _cache_base_line_from_row_values(self, pair_idx: int, row_vals) -> str:
        line = self._render_line_from_raw_parts(
            self._raw_parts_from_row_values(
                row_vals, max(self.max_col, int(getattr(self, "col_max_base", 1) or 1))
            ),
            "BASE",
        )
        self.pair_text_base[int(pair_idx)] = line
        return line

    def _quick_diff_cols_from_value_rows(
        self,
        row_left_vals,
        row_right_vals,
        *,
        right_side: str = "theirs",
    ) -> tuple[set[int], bool]:
        column_cache = self._active_column_comparison_cache()
        result = compare_logical_row_sides(
            column_cache,
            row_left_vals,
            row_right_vals,
            left_side="mine",
            right_side=right_side,
            values_only=True,
        )
        need_exact = False
        for slot in column_cache.model.slots:
            if slot.logical_idx + 1 not in result.diff_cols:
                continue
            vl = _logical_row_value(row_left_vals, slot.mine_col)
            right_col = _logical_model_side_col(slot, right_side)
            vr = _logical_row_value(row_right_vals, right_col)
            if slot.mine_col is not None and right_col is not None and ((vl is None) != (vr is None)):
                need_exact = True
                break
        return set(result.diff_cols), need_exact

    def _edit_row_values_cached(self, ws_edit, row_idx: int | None, cache: dict[int, tuple]) -> tuple:
        if row_idx is None or ws_edit is None:
            return (None,) * self.max_col
        row_idx = int(row_idx)
        cached = cache.get(row_idx)
        if cached is not None:
            return cached
        try:
            row = next(
                ws_edit.iter_rows(
                    min_row=row_idx,
                    max_row=row_idx,
                    min_col=1,
                    max_col=self.max_col,
                    values_only=True,
                ),
                (),
            )
        except Exception:
            row = ()
        cached = _pad_row_values(row, self.max_col)
        cache[row_idx] = cached
        return cached

    def _build_row_and_diff_pair_from_values(
        self,
        row_a_vals,
        row_b_vals,
        *,
        ra: int | None,
        rb: int | None,
        ws_a_edit=None,
        ws_b_edit=None,
        edit_cache_a=None,
        edit_cache_b=None,
        row_a_edit_vals=None,
        row_b_edit_vals=None,
    ):
        raw_a, raw_b, cols = self._build_row_parts_and_diff_pair_from_values(
            row_a_vals,
            row_b_vals,
            ra=ra,
            rb=rb,
            ws_a_edit=ws_a_edit,
            ws_b_edit=ws_b_edit,
            edit_cache_a=edit_cache_a,
            edit_cache_b=edit_cache_b,
            row_a_edit_vals=row_a_edit_vals,
            row_b_edit_vals=row_b_edit_vals,
        )
        return (
            self._render_line_from_raw_parts(raw_a, "A"),
            self._render_line_from_raw_parts(raw_b, "B"),
            cols,
        )

    def _build_row_parts_and_diff_pair_from_values(
        self,
        row_a_vals,
        row_b_vals,
        *,
        ra: int | None,
        rb: int | None,
        ws_a_edit=None,
        ws_b_edit=None,
        edit_cache_a=None,
        edit_cache_b=None,
        row_a_edit_vals=None,
        row_b_edit_vals=None,
    ):
        row_a_vals = _pad_row_values(row_a_vals, self.max_col)
        row_b_vals = _pad_row_values(row_b_vals, self.max_col)
        if row_a_edit_vals is None:
            row_a_edit_vals = self._edit_row_values_cached(ws_a_edit, ra, edit_cache_a if edit_cache_a is not None else {}) if ws_a_edit is not None else (None,) * self.max_col
        else:
            row_a_edit_vals = _pad_row_values(row_a_edit_vals, self.max_col)
        if row_b_edit_vals is None:
            row_b_edit_vals = self._edit_row_values_cached(ws_b_edit, rb, edit_cache_b if edit_cache_b is not None else {}) if ws_b_edit is not None else (None,) * self.max_col
        else:
            row_b_edit_vals = _pad_row_values(row_b_edit_vals, self.max_col)

        raw_a: list[str] = []
        raw_b: list[str] = []
        for offset in range(self.max_col):
            da = _cell_display_from_values(
                row_a_vals[offset], row_a_edit_vals[offset]
            )
            db = _cell_display_from_values(
                row_b_vals[offset], row_b_edit_vals[offset]
            )
            raw_a.append(_val_to_str(da))
            raw_b.append(_val_to_str(db))
        comparison = compare_logical_row_2way(
            self._active_column_comparison_cache(),
            row_a_vals,
            row_b_vals,
            row_a_edit_vals,
            row_b_edit_vals,
            mine_row=ra,
            theirs_row=rb,
            mine_present=ra is not None,
            theirs_present=rb is not None,
        )
        cols = set(comparison.diff_cols)
        # A structurally missing row can contain no values at all (for example,
        # deleting a blank separator row).  Grey padding alone then looks like
        # an unexplained gap, so render an explicit non-data placeholder while
        # keeping the comparison model and save payload untouched.
        if ra is None and raw_a:
            raw_a[0] = "【此侧缺行】"
        if rb is None and raw_b:
            raw_b[0] = "【此侧缺行】"
        return raw_a, raw_b, cols

    def _compute_base_diff_cols_from_values(
        self,
        row_a_vals,
        row_base_vals,
        *,
        ra: int | None,
        base_row: int | None,
        ws_a_edit=None,
        ws_base_edit=None,
        edit_cache_a=None,
        edit_cache_base=None,
        row_a_edit_vals=None,
        row_base_edit_vals=None,
    ) -> set[int]:
        if ra is None:
            return set()
        if base_row is None:
            return {-1}
        row_a_vals = _pad_row_values(row_a_vals, self.max_col)
        row_base_vals = _pad_row_values(row_base_vals, self.max_col)
        if row_a_edit_vals is None:
            row_a_edit_vals = self._edit_row_values_cached(ws_a_edit, ra, edit_cache_a if edit_cache_a is not None else {}) if ws_a_edit is not None else (None,) * self.max_col
        else:
            row_a_edit_vals = _pad_row_values(row_a_edit_vals, self.max_col)
        if row_base_edit_vals is None:
            row_base_edit_vals = self._edit_row_values_cached(ws_base_edit, base_row, edit_cache_base if edit_cache_base is not None else {}) if ws_base_edit is not None else (None,) * self.max_col
        else:
            row_base_edit_vals = _pad_row_values(row_base_edit_vals, self.max_col)
        comparison = compare_logical_row_sides(
            self._active_column_comparison_cache(),
            row_a_vals,
            row_base_vals,
            row_a_edit_vals,
            row_base_edit_vals,
            left_side="mine",
            right_side="base",
            left_row=ra,
            right_row=base_row,
        )
        return set(comparison.diff_cols)

    def _compute_base_diff_cols_for_pair(
        self,
        pair_idx: int,
        pair: tuple[int | None, int | None] | None = None,
        *,
        max_col: int | None = None,
        ws_a_val=None,
        ws_a_edit=None,
        ws_base_val=None,
        ws_base_edit=None,
    ) -> set[int]:
        if not self._is_three_way_enabled():
            return set()
        if not getattr(self.app, "has_base", False):
            return set()
        if self._is_missing_sheet_view():
            return set()
        if pair is None:
            if not (0 <= pair_idx < len(self.row_pairs)):
                return set()
            pair = self.row_pairs[pair_idx]
        ra, _rb = pair
        if ra is None:
            return set()
        base_row = self._base_row_for_pair(pair_idx, pair)
        if base_row is None:
            return {-1}
        if ws_a_val is None:
            ws_a_val = self.app.ws_a_val(self.sheet)
        if ws_a_edit is None:
            try:
                ws_a_edit = self.app.ws_a_edit(self.sheet)
            except Exception:
                ws_a_edit = ws_a_val
        if ws_base_val is None:
            ws_base_val = self.app.ws_base_val(self.sheet)
        if ws_base_edit is None:
            try:
                ws_base_edit = self.app.ws_base_edit(self.sheet)
            except Exception:
                ws_base_edit = ws_base_val
        full_max_col = max(
            int(max_col or 1),
            ws_a_val.max_column or 1,
            ws_base_val.max_column or 1,
            ws_a_edit.max_column or 1,
            ws_base_edit.max_column or 1,
        )
        rows_a_val = _read_rows_into_cache(ws_a_val, (ra,), full_max_col)
        rows_base_val = _read_rows_into_cache(ws_base_val, (base_row,), full_max_col)
        rows_a_edit = _read_rows_into_cache(ws_a_edit, (ra,), full_max_col)
        rows_base_edit = _read_rows_into_cache(ws_base_edit, (base_row,), full_max_col)
        return self._compute_base_diff_cols_from_values(
            _row_from_cache(rows_a_val, ra, full_max_col),
            _row_from_cache(rows_base_val, base_row, full_max_col),
            ra=ra,
            base_row=base_row,
            row_a_edit_vals=_row_from_cache(rows_a_edit, ra, full_max_col),
            row_base_edit_vals=_row_from_cache(rows_base_edit, base_row, full_max_col),
        )

    def _ensure_base_diff_cache(
        self,
        *,
        pair_indices=None,
        max_col: int | None = None,
        ws_a_val=None,
        ws_a_edit=None,
        ws_base_val=None,
        ws_base_edit=None,
        row_cache_bundle: dict | None = None,
    ):
        if not self._is_three_way_enabled():
            self.pair_base_diff_cols = {}
            return False
        if not getattr(self.app, "has_base", False):
            self.pair_base_diff_cols = {}
            return False
        if self._is_missing_sheet_view():
            self.pair_base_diff_cols = {}
            return False
        if ws_a_val is None:
            ws_a_val = self.app.ws_a_val(self.sheet)
        if ws_a_edit is None:
            try:
                ws_a_edit = self.app.ws_a_edit(self.sheet)
            except Exception:
                ws_a_edit = ws_a_val
        if ws_base_val is None:
            ws_base_val = self.app.ws_base_val(self.sheet)
        if ws_base_edit is None:
            try:
                ws_base_edit = self.app.ws_base_edit(self.sheet)
            except Exception:
                ws_base_edit = ws_base_val
        if pair_indices is None:
            targets = list(range(len(self.row_pairs)))
        else:
            targets = [int(idx) for idx in pair_indices if 0 <= int(idx) < len(self.row_pairs)]
        targets = [idx for idx in targets if idx not in self.pair_base_diff_cols]
        if not targets:
            return False
        full_max_col = max(
            int(max_col or 1),
            int(getattr(ws_a_val, "max_column", 1) or 1),
            int(getattr(ws_base_val, "max_column", 1) or 1),
            int(getattr(ws_a_edit, "max_column", 1) or 1),
            int(getattr(ws_base_edit, "max_column", 1) or 1),
        )
        rows_a_needed = [self.row_pairs[idx][0] for idx in targets]
        base_rows_needed = [
            self._base_row_for_pair(idx, self.row_pairs[idx])
            for idx in targets
        ]
        rows_a_val = _read_rows_into_shared_cache(
            ws_a_val, rows_a_needed, full_max_col,
            cache_bundle=row_cache_bundle, cache_key="a_val",
        )
        rows_a_edit = _read_rows_into_shared_cache(
            ws_a_edit, rows_a_needed, full_max_col,
            cache_bundle=row_cache_bundle, cache_key="a_edit",
        )
        rows_base_val = _read_rows_into_shared_cache(
            ws_base_val, base_rows_needed, full_max_col,
            cache_bundle=row_cache_bundle, cache_key="base_val",
        )
        rows_base_edit = _read_rows_into_shared_cache(
            ws_base_edit, base_rows_needed, full_max_col,
            cache_bundle=row_cache_bundle, cache_key="base_edit",
        )
        added_any = False
        for idx in targets:
            pair = self.row_pairs[idx]
            ra, _rb = pair
            base_row = self._base_row_for_pair(idx, pair)
            self.pair_base_diff_cols[idx] = self._compute_base_diff_cols_from_values(
                _row_from_cache(rows_a_val, ra, full_max_col),
                _row_from_cache(rows_base_val, base_row, full_max_col),
                ra=ra,
                base_row=base_row,
                row_a_edit_vals=_row_from_cache(rows_a_edit, ra, full_max_col),
                row_base_edit_vals=_row_from_cache(rows_base_edit, base_row, full_max_col),
            )
            added_any = True
        return added_any

    def _refresh_pair_indices_exact(self, pair_indices) -> int:
        """Batch-refresh exact row diff/text channels for selected aligned pairs.

        Region adoption suppresses per-row UI refresh.  The final lazy render may
        materialize only the first 200 rows of a large block, so its remaining
        pair entries must be updated explicitly without expanding the visible
        navigation window or rescanning unrelated rows.
        """
        targets = list(dict.fromkeys(
            int(idx)
            for idx in pair_indices
            if 0 <= int(idx) < len(self.row_pairs)
        ))
        if not targets:
            return 0
        ws_a_val = self.app.ws_a_val(self.sheet)
        ws_b_val = self.app.ws_b_val(self.sheet)
        try:
            ws_a_edit = self.app.ws_a_edit(self.sheet)
        except Exception:
            ws_a_edit = ws_a_val
        try:
            ws_b_edit = self.app.ws_b_edit(self.sheet)
        except Exception:
            ws_b_edit = ws_b_val
        rows_a_needed = [self.row_pairs[idx][0] for idx in targets]
        rows_b_needed = [self.row_pairs[idx][1] for idx in targets]
        row_cache_bundle: dict = {}
        rows_a_val = _read_rows_into_shared_cache(
            ws_a_val, rows_a_needed, self.max_col,
            cache_bundle=row_cache_bundle, cache_key="a_val",
        )
        rows_b_val = _read_rows_into_shared_cache(
            ws_b_val, rows_b_needed, self.max_col,
            cache_bundle=row_cache_bundle, cache_key="b_val",
        )
        rows_a_edit = _read_rows_into_shared_cache(
            ws_a_edit, rows_a_needed, self.max_col,
            cache_bundle=row_cache_bundle, cache_key="a_edit",
        )
        rows_b_edit = _read_rows_into_shared_cache(
            ws_b_edit, rows_b_needed, self.max_col,
            cache_bundle=row_cache_bundle, cache_key="b_edit",
        )
        for pair_idx in targets:
            ra, rb = self.row_pairs[pair_idx]
            line_a, line_b, cols = self._build_row_and_diff_pair_from_values(
                _row_from_cache(rows_a_val, ra, self.max_col),
                _row_from_cache(rows_b_val, rb, self.max_col),
                ra=ra,
                rb=rb,
                row_a_edit_vals=_row_from_cache(rows_a_edit, ra, self.max_col),
                row_b_edit_vals=_row_from_cache(rows_b_edit, rb, self.max_col),
            )
            self.pair_diff_cols[pair_idx] = cols
            self.pair_text_a[pair_idx] = line_a
            self.pair_text_b[pair_idx] = line_b

        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            for pair_idx in targets:
                self.pair_base_diff_cols.pop(pair_idx, None)
            ws_base_val = self.app.ws_base_val(self.sheet)
            try:
                ws_base_edit = self.app.ws_base_edit(self.sheet)
            except Exception:
                ws_base_edit = ws_base_val
            self._ensure_base_diff_cache(
                pair_indices=targets,
                max_col=self.max_col,
                ws_a_val=ws_a_val,
                ws_a_edit=ws_a_edit,
                ws_base_val=ws_base_val,
                ws_base_edit=ws_base_edit,
                row_cache_bundle=row_cache_bundle,
            )
            base_rows_needed = [
                self._base_row_for_pair(idx, self.row_pairs[idx])
                for idx in targets
            ]
            rows_base_val = _read_rows_into_shared_cache(
                ws_base_val, base_rows_needed, self.max_col,
                cache_bundle=row_cache_bundle, cache_key="base_val",
            )
            for pair_idx, base_row in zip(targets, base_rows_needed):
                if base_row is None:
                    self.pair_text_base[pair_idx] = ""
                else:
                    self._cache_base_line_from_row_values(
                        pair_idx,
                        _row_from_cache(rows_base_val, base_row, self.max_col),
                    )
        return len(targets)

    def _all_logical_diff_cols_for_pair(self, pair_idx: int) -> set[int]:
        """Return the raw logical diff channel, including structural slots."""
        cols = set(self.pair_diff_cols.get(pair_idx, set()))
        base_cols = set(self.pair_base_diff_cols.get(pair_idx, set()))
        if base_cols:
            if -1 in base_cols:
                cols.add(-1)
            cols.update(c for c in base_cols if c > 0)
        return cols

    def _visual_diff_cols_for_pair(self, pair_idx: int) -> set[int]:
        """Return row-content diffs only; column structure has its own markers.

        A missing logical slot can contain values on its owning side in every
        row.  Treating those values as row diffs floods only-diff with the whole
        sheet.  Only genuinely missing-side slots are removed here.  An
        unresolved slot that still maps a physical column on both sides can
        contain a real cell edit, so it remains in the row channel (merge
        actions can still reject that ambiguous mapping independently).
        """
        cols = self._all_logical_diff_cols_for_pair(pair_idx)
        try:
            cache = self._active_column_comparison_cache()
            structural = set(cache.structural_diff_cols)
            cols.difference_update(c for c in structural if c > 0)
            # A resolved insertion owned identically by Mine and Theirs has no
            # Base physical column by definition.  Base-relative comparison
            # therefore marks that logical slot on every populated row.  A
            # paired common insertion is structural, not a row-content diff:
            # physical row offsets can make its accepted copied payload differ
            # even when the logical insertion itself is proven and intentional.
            # Keep that evidence in the column marker/action bar instead of
            # flooding only-diff with every populated row.
            if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
                resolved_common_insertions = {
                    slot.logical_idx + 1
                    for slot in cache.model.slots
                    if (
                        slot.base_col is None
                        and slot.mine_col is not None
                        and slot.theirs_col is not None
                        and slot.state != "unresolved"
                        and not slot.confidence.ambiguous
                    )
                }
                pair_cols = set(self.pair_diff_cols.get(pair_idx, set()))
                accepted_sources = dict(
                    getattr(self, "_accepted_common_insert_sources", {}) or {}
                )
                cols.difference_update(
                    col
                    for col in resolved_common_insertions
                    if (
                        col not in pair_cols
                        or (
                            col in accepted_sources
                            and self._accepted_common_insertion_row_is_unchanged(
                                pair_idx,
                                col,
                                accepted_sources[col],
                            )
                        )
                    )
                )
        except Exception:
            pass
        return cols

    def _accepted_common_insertion_row_is_unchanged(
        self,
        pair_idx: int,
        logical_col: int,
        source_side: str,
    ) -> bool:
        """Prove an accepted common-insert cell still matches its copy source.

        The comparison deliberately uses the target side's physical row on
        both current workbooks.  That is the coordinate copied by the column
        transaction; comparing the normal Mine/Theirs row pair here would
        reproduce the row-alignment offset that this guard is meant to remove.
        Any subsequent edit on either side breaks equality and immediately
        restores the real visual difference.
        """
        source = str(source_side or "").upper()
        if source not in ("A", "B"):
            return False
        if not (0 <= int(pair_idx) < len(self.row_pairs)):
            return False
        row_a, row_b = self.row_pairs[int(pair_idx)]
        physical_row = row_b if source == "A" else row_a
        if physical_row is None:
            return False
        projection = self._active_column_projection()
        mine_col = projection.physical_col("A", int(logical_col))
        theirs_col = projection.physical_col("B", int(logical_col))
        if mine_col is None or theirs_col is None:
            return False

        def _raw_value(ws, row: int, col: int):
            cells = getattr(ws, "_cells", None)
            if isinstance(cells, dict):
                cell = cells.get((int(row), int(col)))
                return getattr(cell, "value", None) if cell is not None else None
            return ws.cell(row=int(row), column=int(col)).value

        ws_a_val = self.app.ws_a_val(self.sheet)
        ws_b_val = self.app.ws_b_val(self.sheet)
        ws_a_edit = self.app.ws_a_edit(self.sheet)
        ws_b_edit = self.app.ws_b_edit(self.sheet)
        row = int(physical_row)
        a_val = _raw_value(ws_a_val, row, mine_col)
        b_val = _raw_value(ws_b_val, row, theirs_col)
        a_edit = _raw_value(ws_a_edit, row, mine_col)
        b_edit = _raw_value(ws_b_edit, row, theirs_col)
        a_edit = _translate_normal_formula_for_compare(
            a_val,
            a_edit,
            row,
            int(mine_col),
            row,
            int(logical_col),
        )
        b_edit = _translate_normal_formula_for_compare(
            b_val,
            b_edit,
            row,
            int(theirs_col),
            row,
            int(logical_col),
        )
        _display_a, _display_b, equal = _cell_display_and_equal_from_values(
            a_val,
            b_val,
            a_edit,
            b_edit,
        )
        return bool(equal)

    def _pair_has_visual_diff(self, pair_idx: int) -> bool:
        return bool(self._visual_diff_cols_for_pair(pair_idx))

    def _prescan_col_widths(
        self,
        ws_a_val,
        ws_b_val,
        ws_base_val=None,
        max_pairs: int = 0,
        *,
        row_cache_bundle: dict | None = None,
    ):
        """Install fixed Sheet geometry; cell values never affect widths.

        Arguments remain for callers that previously supplied row caches. The
        width model intentionally does no cell scan: every logical column is
        the same bounded 18-character width in A/Base/B/C and all rows.
        """
        self._rownum_display_width = 0
        return self._set_uniform_logical_column_widths()

    def _build_row_pairs(
        self,
        ws_a_val,
        ws_b_val,
        force: bool = False,
        *,
        max_row_a: int | None = None,
        max_row_b: int | None = None,
        ws_a_edit=None,
        ws_b_edit=None,
    ):
        return _compute_row_pairs_generic(
            ws_a_val,
            ws_b_val,
            self.max_col,
            force=force,
            max_row_a=max_row_a,
            max_row_b=max_row_b,
            ws_a_edit=ws_a_edit,
            ws_b_edit=ws_b_edit,
        )

    @staticmethod
    def _build_row_pairs_direct(max_row_a: int, max_row_b: int):
        """Direct row pairing (1:1 by row number), used for very large sheets."""
        max_row = max(max_row_a, max_row_b)
        pairs: list[tuple[int | None, int | None]] = []
        for r in range(1, max_row + 1):
            ra = r if r <= max_row_a else None
            rb = r if r <= max_row_b else None
            pairs.append((ra, rb))
        return pairs

    def _precompute_large_diff_by_blocks(
        self,
        ws_a_val,
        ws_b_val,
        ws_a_edit,
        ws_b_edit,
        max_row_a: int,
        max_row_b: int,
        ws_base_val=None,
        ws_base_edit=None,
    ):
        """Large-sheet only-diff precompute using tail-first block scan."""
        edit_cache_a: dict[int, tuple] = {}
        edit_cache_b: dict[int, tuple] = {}
        edit_cache_base: dict[int, tuple] = {}
        has_base = bool(self._is_three_way_enabled() and getattr(self.app, "has_base", False) and ws_base_val is not None)

        def _cache_base_pair(pair_idx: int, base_row: int | None, rows_base: dict):
            if not has_base:
                return
            if base_row is None:
                self.pair_text_base[pair_idx] = ""
                return
            self._cache_base_line_from_row_values(
                pair_idx,
                _row_from_cache(rows_base, base_row, self.max_col),
            )

        if self._align_rows_enabled and self.row_pairs:
            pair_count = len(self.row_pairs)
            block = _LARGE_SHEET_BLOCK_ROWS
            for block_end in range(pair_count, 0, -block):
                block_start = max(0, block_end - block)
                block_pairs = self.row_pairs[block_start:block_end]

                rows_a = _read_rows_into_cache(ws_a_val, [ra for ra, _rb in block_pairs if ra is not None], self.max_col)
                rows_b = _read_rows_into_cache(ws_b_val, [rb for _ra, rb in block_pairs if rb is not None], self.max_col)
                rows_a_edit_block = _read_rows_into_cache(
                    ws_a_edit,
                    [ra for ra, _rb in block_pairs if ra is not None],
                    self.max_col,
                ) if ws_a_edit is not None else {}
                rows_b_edit_block = _read_rows_into_cache(
                    ws_b_edit,
                    [rb for _ra, rb in block_pairs if rb is not None],
                    self.max_col,
                ) if ws_b_edit is not None else {}
                base_rows_needed = []
                if has_base:
                    for off, pair in enumerate(block_pairs):
                        pair_idx = block_start + off
                        base_row = self._base_row_for_pair(pair_idx, pair)
                        if base_row is not None:
                            base_rows_needed.append(base_row)
                rows_base = _read_rows_into_cache(ws_base_val, base_rows_needed, self.max_col) if has_base else {}
                rows_base_edit_block = _read_rows_into_cache(
                    ws_base_edit, base_rows_needed, self.max_col
                ) if (has_base and ws_base_edit is not None) else {}
                exact_rows: list[tuple[int, int | None, int | None, int | None, set[int], bool, set[int], bool]] = []

                for off in range(len(block_pairs) - 1, -1, -1):
                    pair_idx = block_start + off
                    if not (0 <= pair_idx < len(self.row_pairs)):
                        continue
                    ra, rb = self.row_pairs[pair_idx]
                    row_a = _row_from_cache(rows_a, ra, self.max_col)
                    row_b = _row_from_cache(rows_b, rb, self.max_col)
                    row_a_edit_block = _row_from_cache(rows_a_edit_block, ra, self.max_col)
                    row_b_edit_block = _row_from_cache(rows_b_edit_block, rb, self.max_col)
                    comparison = compare_logical_row_2way(
                        self._active_column_comparison_cache(),
                        row_a,
                        row_b,
                        row_a_edit_block,
                        row_b_edit_block,
                        mine_row=ra,
                        theirs_row=rb,
                        mine_present=ra is not None,
                        theirs_present=rb is not None,
                    )
                    cols = set(comparison.diff_cols)
                    need_exact_ab = False
                    base_cols = set()
                    need_exact_base = False
                    base_row = None
                    if has_base:
                        base_row = self._base_row_for_pair(pair_idx, (ra, rb))
                        if base_row is None and ra is not None and rb is not None:
                            base_cols = {-1}
                        elif base_row is not None and ra is None:
                            base_cols = {-1}
                        elif base_row is not None:
                            row_base = _row_from_cache(rows_base, base_row, self.max_col)
                            base_comparison = compare_logical_row_sides(
                                self._active_column_comparison_cache(),
                                row_a,
                                row_base,
                                row_a_edit_block,
                                _row_from_cache(rows_base_edit_block, base_row, self.max_col),
                                left_side="mine",
                                right_side="base",
                                left_row=ra,
                                right_row=base_row,
                            )
                            base_cols = set(base_comparison.diff_cols)
                            need_exact_base = False
                    if (not cols) and (not base_cols):
                        continue
                    if need_exact_ab or need_exact_base:
                        exact_rows.append((pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base))
                        continue
                    self.pair_diff_cols[pair_idx] = cols
                    if has_base:
                        self.pair_base_diff_cols[pair_idx] = base_cols
                    self.pair_text_a[pair_idx] = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_a), "A")
                    self.pair_text_b[pair_idx] = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_b), "B")
                    _cache_base_pair(pair_idx, base_row, rows_base)

                if exact_rows:
                    exact_rows_a = [ra for _pair_idx, ra, _rb, _base_row, _cols, need_ab, _bcols, need_base in exact_rows if ra is not None and (need_ab or need_base)]
                    exact_rows_b = [rb for _pair_idx, _ra, rb, _base_row, _cols, need_ab, _bcols, _need_base in exact_rows if rb is not None and need_ab]
                    exact_rows_base = [base_row for _pair_idx, _ra, _rb, base_row, _cols, _need_ab, _bcols, need_base in exact_rows if base_row is not None and need_base]
                    rows_a_edit = _read_rows_into_cache(ws_a_edit, exact_rows_a, self.max_col) if ws_a_edit is not None else {}
                    rows_b_edit = _read_rows_into_cache(ws_b_edit, exact_rows_b, self.max_col) if ws_b_edit is not None else {}
                    rows_base_edit = _read_rows_into_cache(ws_base_edit, exact_rows_base, self.max_col) if (ws_base_edit is not None and has_base) else {}
                    for pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base in exact_rows:
                        row_a = _row_from_cache(rows_a, ra, self.max_col)
                        row_b = _row_from_cache(rows_b, rb, self.max_col)
                        row_a_edit = _row_from_cache(rows_a_edit, ra, self.max_col)
                        row_b_edit = _row_from_cache(rows_b_edit, rb, self.max_col)
                        if need_exact_ab:
                            line_a, line_b, cols = self._build_row_and_diff_pair_from_values(
                                row_a,
                                row_b,
                                ra=ra,
                                rb=rb,
                                ws_a_edit=ws_a_edit,
                                ws_b_edit=ws_b_edit,
                                edit_cache_a=edit_cache_a,
                                edit_cache_b=edit_cache_b,
                                row_a_edit_vals=row_a_edit,
                                row_b_edit_vals=row_b_edit,
                            )
                        else:
                            line_a = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_a), "A")
                            line_b = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_b), "B")
                        if need_exact_base and has_base and ra is not None:
                            row_base = _row_from_cache(rows_base, base_row, self.max_col)
                            row_base_edit = _row_from_cache(rows_base_edit, base_row, self.max_col)
                            base_cols = self._compute_base_diff_cols_from_values(
                                row_a,
                                row_base,
                                ra=ra,
                                base_row=base_row,
                                ws_a_edit=ws_a_edit,
                                ws_base_edit=ws_base_edit,
                                edit_cache_a=edit_cache_a,
                                edit_cache_base=edit_cache_base,
                                row_a_edit_vals=row_a_edit,
                                row_base_edit_vals=row_base_edit,
                            )
                        if (not cols) and (not base_cols):
                            continue
                        self.pair_diff_cols[pair_idx] = cols
                        if has_base:
                            self.pair_base_diff_cols[pair_idx] = base_cols
                        self.pair_text_a[pair_idx] = line_a
                        self.pair_text_b[pair_idx] = line_b
                        _cache_base_pair(pair_idx, base_row, rows_base)
            return

        max_row = max(max_row_a, max_row_b)
        block = _LARGE_SHEET_BLOCK_ROWS
        for block_end in range(max_row, 0, -block):
            block_start = max(1, block_end - block + 1)
            block_len = block_end - block_start + 1

            rows_a = _read_rows_into_cache(
                ws_a_val,
                range(block_start, min(block_end, max_row_a) + 1),
                self.max_col,
            )
            rows_b = _read_rows_into_cache(
                ws_b_val,
                range(block_start, min(block_end, max_row_b) + 1),
                self.max_col,
            )
            rows_a_edit_block = _read_rows_into_cache(
                ws_a_edit,
                range(block_start, min(block_end, max_row_a) + 1),
                self.max_col,
            ) if ws_a_edit is not None else {}
            rows_b_edit_block = _read_rows_into_cache(
                ws_b_edit,
                range(block_start, min(block_end, max_row_b) + 1),
                self.max_col,
            ) if ws_b_edit is not None else {}
            base_rows_needed = []
            if has_base:
                for r in range(block_start, block_end + 1):
                    pair_idx = self.row_a_to_pair_idx.get(r)
                    if pair_idx is None:
                        pair_idx = self.row_b_to_pair_idx.get(r)
                    if pair_idx is None or pair_idx >= len(self.row_pairs):
                        continue
                    base_row = self._base_row_for_pair(pair_idx, self.row_pairs[pair_idx])
                    if base_row is not None:
                        base_rows_needed.append(base_row)
            rows_base = _read_rows_into_cache(ws_base_val, base_rows_needed, self.max_col) if has_base else {}
            rows_base_edit_block = _read_rows_into_cache(
                ws_base_edit, base_rows_needed, self.max_col
            ) if (has_base and ws_base_edit is not None) else {}
            exact_rows: list[tuple[int, int | None, int | None, int | None, set[int], bool, set[int], bool]] = []

            # Tail-first within changed block (newer rows first).
            for off in range(block_len - 1, -1, -1):
                r = block_start + off
                pair_idx = self.row_a_to_pair_idx.get(r)
                if pair_idx is None:
                    pair_idx = self.row_b_to_pair_idx.get(r)
                if pair_idx is None:
                    continue
                if pair_idx >= len(self.row_pairs):
                    continue
                ra, rb = self.row_pairs[pair_idx]
                row_a = _row_from_cache(rows_a, ra, self.max_col)
                row_b = _row_from_cache(rows_b, rb, self.max_col)
                row_a_edit_block = _row_from_cache(rows_a_edit_block, ra, self.max_col)
                row_b_edit_block = _row_from_cache(rows_b_edit_block, rb, self.max_col)
                comparison = compare_logical_row_2way(
                    self._active_column_comparison_cache(),
                    row_a,
                    row_b,
                    row_a_edit_block,
                    row_b_edit_block,
                    mine_row=ra,
                    theirs_row=rb,
                    mine_present=ra is not None,
                    theirs_present=rb is not None,
                )
                cols = set(comparison.diff_cols)
                need_exact_ab = False
                base_cols = set()
                need_exact_base = False
                base_row = None
                if has_base:
                    base_row = self._base_row_for_pair(pair_idx, (ra, rb))
                    if base_row is None and ra is not None and rb is not None:
                        base_cols = {-1}
                    elif base_row is not None and ra is None:
                        base_cols = {-1}
                    elif base_row is not None:
                        row_base = _row_from_cache(rows_base, base_row, self.max_col)
                        base_comparison = compare_logical_row_sides(
                            self._active_column_comparison_cache(),
                            row_a,
                            row_base,
                            row_a_edit_block,
                            _row_from_cache(rows_base_edit_block, base_row, self.max_col),
                            left_side="mine",
                            right_side="base",
                            left_row=ra,
                            right_row=base_row,
                        )
                        base_cols = set(base_comparison.diff_cols)
                        need_exact_base = False
                if (not cols) and (not base_cols):
                    continue
                if need_exact_ab or need_exact_base:
                    exact_rows.append((pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base))
                    continue
                self.pair_diff_cols[pair_idx] = cols
                if has_base:
                    self.pair_base_diff_cols[pair_idx] = base_cols
                self.pair_text_a[pair_idx] = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_a), "A")
                self.pair_text_b[pair_idx] = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_b), "B")
                _cache_base_pair(pair_idx, base_row, rows_base)

            if exact_rows:
                exact_rows_a = [ra for _pair_idx, ra, _rb, _base_row, _cols, need_ab, _bcols, need_base in exact_rows if ra is not None and (need_ab or need_base)]
                exact_rows_b = [rb for _pair_idx, _ra, rb, _base_row, _cols, need_ab, _bcols, _need_base in exact_rows if rb is not None and need_ab]
                exact_rows_base = [base_row for _pair_idx, _ra, _rb, base_row, _cols, _need_ab, _bcols, need_base in exact_rows if base_row is not None and need_base]
                rows_a_edit = _read_rows_into_cache(ws_a_edit, exact_rows_a, self.max_col) if ws_a_edit is not None else {}
                rows_b_edit = _read_rows_into_cache(ws_b_edit, exact_rows_b, self.max_col) if ws_b_edit is not None else {}
                rows_base_edit = _read_rows_into_cache(ws_base_edit, exact_rows_base, self.max_col) if (has_base and ws_base_edit is not None) else {}
                for pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base in exact_rows:
                    row_a = _row_from_cache(rows_a, ra, self.max_col)
                    row_b = _row_from_cache(rows_b, rb, self.max_col)
                    row_a_edit = _row_from_cache(rows_a_edit, ra, self.max_col)
                    row_b_edit = _row_from_cache(rows_b_edit, rb, self.max_col)
                    if need_exact_ab:
                        line_a, line_b, cols = self._build_row_and_diff_pair_from_values(
                            row_a,
                            row_b,
                            ra=ra,
                            rb=rb,
                            ws_a_edit=ws_a_edit,
                            ws_b_edit=ws_b_edit,
                            edit_cache_a=edit_cache_a,
                            edit_cache_b=edit_cache_b,
                            row_a_edit_vals=row_a_edit,
                            row_b_edit_vals=row_b_edit,
                        )
                    else:
                        line_a = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_a), "A")
                        line_b = self._render_line_from_raw_parts(self._raw_parts_from_row_values(row_b), "B")
                    if need_exact_base and has_base and ra is not None:
                        row_base = _row_from_cache(rows_base, base_row, self.max_col)
                        row_base_edit = _row_from_cache(rows_base_edit, base_row, self.max_col)
                        base_cols = self._compute_base_diff_cols_from_values(
                            row_a,
                            row_base,
                            ra=ra,
                            base_row=base_row,
                            ws_a_edit=ws_a_edit,
                            ws_base_edit=ws_base_edit,
                            edit_cache_a=edit_cache_a,
                            edit_cache_base=edit_cache_base,
                            row_a_edit_vals=row_a_edit,
                            row_base_edit_vals=row_base_edit,
                        )
                    if (not cols) and (not base_cols):
                        continue
                    self.pair_diff_cols[pair_idx] = cols
                    if has_base:
                        self.pair_base_diff_cols[pair_idx] = base_cols
                    self.pair_text_a[pair_idx] = line_a
                    self.pair_text_b[pair_idx] = line_b
                    _cache_base_pair(pair_idx, base_row, rows_base)

    def _build_row_and_diff(self, ws_a_val, ws_b_val, ws_a_edit, ws_b_edit, r: int):
        parts_a = []
        parts_b = []
        cols = set()
        for c in range(1, self.max_col + 1):
            da, db, eq = _cell_display_and_equal(ws_a_val, ws_b_val, ws_a_edit, ws_b_edit, r, c)
            parts_a.append(_val_to_str(da))
            parts_b.append(_val_to_str(db))
            if not eq:
                cols.add(c)
        line_a = str(r) + "\t" + "\t".join(parts_a)
        line_b = str(r) + "\t" + "\t".join(parts_b)
        return line_a, line_b, cols

    def _compute_diff_cols_from_rows(self, row_a, row_b):
        cols = set()
        # row tuples are 0-indexed; cols are 1-indexed
        for i, (va, vb) in enumerate(zip(row_a, row_b), start=1):
            if va != vb:
                cols.add(i)
        return cols

    def _build_line_from_row(self, r: int, row_vals) -> str:
        return str(r) + "\t" + "\t".join(_val_to_str(v) for v in row_vals)

    def _base_spans(self) -> dict:
        """Unclamped {colIndex: (start, end)} char positions, cached per refresh.

        Depends only on max_col, grid-overlay state and the current column widths,
        so it is recomputed only when those change (``_col_widths_version`` bump),
        not once per rendered line in the tag phase."""
        grid = self._is_grid_overlay_enabled()
        slot_count = self._logical_slot_count()
        key = (
            int(slot_count),
            bool(grid),
            int(getattr(self, "_col_widths_version", 0)),
            int(getattr(self, "_column_projection_generation", 0)),
        )
        if getattr(self, "_base_spans_cache", None) is not None \
                and getattr(self, "_base_spans_cache_key", None) == key:
            return self._base_spans_cache
        sep_len = len(_COL_SEP) if grid else 3
        pos = 0
        spans = {}
        for c in range(1, slot_count + 1):
            w = max(1, self.col_char_widths.get(c, 1))
            spans[c] = (pos, pos + w)
            pos += w
            if c < slot_count:
                pos += sep_len
        self._base_spans_cache = spans
        self._base_spans_cache_key = key
        return spans

    def _spans_for_line(self, line: str = "") -> dict:
        """Return {colIndex: (start, end)} character positions in the rendered line.

        When a concrete line string is available, clamp spans to the actual text length so
        downstream tag ranges stay aligned with what Tk is really showing."""
        base = self._base_spans()
        text = str(line or "")
        if not text:
            # Copy so callers can't mutate the cached base spans.
            return dict(base)
        text_len = len(text)
        return {c: (min(s, text_len), min(e, text_len)) for c, (s, e) in base.items()}

    def _diffcell_tag_args_for_line(
        self,
        line_no: int,
        pair_idx: int,
        line_a: str = "",
        line_base: str = "",
        line_b: str = "",
    ) -> tuple[list[str], list[str], list[str], list[tuple[int, int]], list[tuple[int, int]], list[tuple[int, int]]]:
        left_args: list[str] = []
        base_args: list[str] = []
        right_args: list[str] = []
        left_ranges: list[tuple[int, int]] = []
        base_ranges: list[tuple[int, int]] = []
        right_ranges: list[tuple[int, int]] = []
        if not (0 <= int(pair_idx) < len(self.row_pairs)):
            return left_args, base_args, right_args, left_ranges, base_ranges, right_ranges
        pair = self.row_pairs[pair_idx]
        ra, rb = pair
        base_r = self._base_row_for_pair(pair_idx, pair) if self._is_three_way_enabled() else None
        cols = self._visual_diff_cols_for_pair(pair_idx)
        if not cols:
            return left_args, base_args, right_args, left_ranges, base_ranges, right_ranges
        spans_a = self._spans_for_line(line_a)
        spans_base = self._spans_for_line(line_base) if self._is_three_way_enabled() else {}
        spans_b = self._spans_for_line(line_b)
        for c in cols:
            if c <= 0:
                continue
            if ra is not None and c in spans_a and self._slot_exists_on_side("A", c):
                s, e = spans_a[c]
                if s < e:
                    left_args.extend([f"{line_no}.{s}", f"{line_no}.{e}"])
                    left_ranges.append((s, e))
            if base_r is not None and c in spans_base and self._slot_exists_on_side("BASE", c):
                s, e = spans_base[c]
                if s < e:
                    base_args.extend([f"{line_no}.{s}", f"{line_no}.{e}"])
                    base_ranges.append((s, e))
            if rb is not None and c in spans_b and self._slot_exists_on_side("B", c):
                s, e = spans_b[c]
                if s < e:
                    right_args.extend([f"{line_no}.{s}", f"{line_no}.{e}"])
                    right_ranges.append((s, e))
        return left_args, base_args, right_args, left_ranges, base_ranges, right_ranges

    def _padding_column_tag_args(self, side: str, line_count: int) -> list[str]:
        """Return exact placeholder ranges for a pane in shared slot geometry."""
        if line_count <= 0:
            return []
        projection = self._active_column_projection()
        spans = self._spans_for_line()
        args = []
        for logical_col in range(1, projection.slot_count + 1):
            if not projection.is_missing(side, logical_col) or logical_col not in spans:
                continue
            start, end = spans[logical_col]
            for line_no in range(1, int(line_count) + 1):
                args.extend([f"{line_no}.{start}", f"{line_no}.{end}"])
        return args

    def _clear_diffrow_under_diffcells(self, left_args=None, base_args=None, right_args=None):
        try:
            for widget, args in ((self.left, left_args), (self.base, base_args), (self.right, right_args)):
                if not args:
                    continue
                pairs = list(args)
                for i in range(0, len(pairs), 2):
                    if i + 1 >= len(pairs):
                        break
                    widget.tag_remove("diffrow", pairs[i], pairs[i + 1])
        except Exception:
            pass

    def _apply_rownum_diff_tag_line(self, line_idx: int, pair_idx: int):
        pass  # Row headers are rendered in dedicated widgets (left_ln/base_ln/right_ln).

    # ---------- Only-diff toggle ----------
    def _invalidate_only_diff_snapshot_cache(self):
        self._only_diff_source_version += 1
        self._only_diff_rows_cache = None
        self._only_diff_rows_cache_key = None
        self._only_diff_rows_exact = False
        self._only_diff_async_build_key = None
        self._only_diff_async_building = False
        self._only_diff_async_build_seq += 1
        self._invalidate_diff_block_model()

    def _has_user_edits_for_current_sheet(self) -> bool:
        if bool(self.touched_rows):
            return True
        modified_a = getattr(self.app, "modified_sheets_a", set())
        modified_b = getattr(self.app, "modified_sheets_b", set())
        return self.sheet in modified_a or self.sheet in modified_b

    def _current_only_diff_cache_key(self) -> tuple:
        return (
            self.sheet,
            int(self._only_diff_source_version),
            int(len(self.row_pairs)),
            int(self._logical_slot_count()),
            int(getattr(self, "_column_projection_generation", 0)),
            int(bool(self._align_rows_enabled)),
            int(bool(self._force_sequence_align)),
            int(bool(self._is_three_way_enabled() and getattr(self.app, "has_base", False))),
        )

    def _has_valid_only_diff_snapshot_cache(self) -> bool:
        rows = getattr(self, "_only_diff_rows_cache", None)
        if rows is None:
            return False
        return self._only_diff_rows_cache_key == self._current_only_diff_cache_key()

    def _cache_only_diff_rows_snapshot(self, rows, *, exact: bool = False):
        normalized = sorted({int(idx) for idx in (rows or []) if 0 <= int(idx) < len(self.row_pairs)})
        self._only_diff_rows_cache = normalized
        self._only_diff_rows_cache_key = self._current_only_diff_cache_key()
        if exact:
            self._only_diff_rows_exact = True
        return list(normalized)

    def _cache_only_diff_rows_from_exact_pair_maps(self) -> bool:
        """Publish a synchronous snapshot when current in-memory maps are exact.

        Disk-backed only-diff workers intentionally refuse to run after a user
        edit because their source files are stale.  Column actions already
        rebuild the full Mine/Theirs map and, on ordinary three-way sheets, the
        full Base-relative map in memory.  Reusing those proved maps prevents a
        toggle from waiting forever for an async result that must be rejected.
        """
        if not bool(getattr(self, "_data_ready", False)):
            return False
        if not bool(getattr(self, "_cache_formula_aware", False)):
            return False
        pair_diff_map = getattr(self, "pair_diff_cols", {}) or {}
        pair_map_complete = len(pair_diff_map) >= len(self.row_pairs) and all(
            pair_idx in pair_diff_map for pair_idx in range(len(self.row_pairs))
        )
        if not bool(getattr(self, "_pair_diff_full_exact", False)) and not pair_map_complete:
            return False
        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            if not bool(getattr(self, "_base_diff_full_exact", False)):
                return False
        self._cache_only_diff_rows_snapshot(
            (
                pair_idx
                for pair_idx in range(len(self.row_pairs))
                if self._pair_has_visual_diff(pair_idx)
            ),
            exact=True,
        )
        return True

    def _only_diff_rows_with_touched(self, rows):
        rows_set = set(int(idx) for idx in (rows or []) if 0 <= int(idx) < len(self.row_pairs))
        for r in self.touched_rows:
            idx = self.row_a_to_pair_idx.get(r)
            if idx is None:
                idx = self.row_b_to_pair_idx.get(r)
            if idx is not None:
                rows_set.add(int(idx))
        return sorted(rows_set)

    def _set_only_diff_pending_info(self):
        try:
            total_rows = len(self.row_pairs) if self.row_pairs else self.max_row
            prefix = (
                "只看差异 | 正在后台生成精确差异行..."
                if bool(self.only_diff_var.get())
                else "正在后台完成精确差异计算（当前只读）..."
            )
            self.info.configure(
                text=f"{prefix}   Rows: {total_rows}   {self._info_column_text()}"
            )
            self._set_diff_block_indicator_visible(True)
            self.diff_block_status_var.set("差异块 计算中...")
        except Exception:
            pass

    def _refresh_mode_switch_preserving_selection(self, *, rescan: bool):
        saved_selection = self._snapshot_explicit_selection_state()
        self._clear_selection_visuals()
        self._set_main_selected_cell(None, None)
        self._cursor_cmp_sel_col = None
        self._cursor_cmp_sel_line = None
        self.selected_pair_idx = None
        self.selected_excel_row = None
        self.selected_excel_row_a = None
        self.selected_excel_row_b = None
        self._clear_hover_state(clear_panel=True)
        self._suppress_bg_apply = True
        try:
            self.refresh(row_only=None, rescan=rescan)
        finally:
            self._suppress_bg_apply = False  # Fresh data rendered; allow bg applies again.
        if not self._restore_explicit_selection_state(saved_selection):
            self.clear_explicit_cell_selection()
        self._update_cursor_lines()
        self._update_diff_nav_state()

    def _start_async_large_only_diff_build(self, *, user_initiated: bool = False) -> bool:
        # This worker opens disk snapshots. Once the user has adopted any data,
        # those files are stale and must never be allowed to rebuild UI text.
        if self._has_user_edits_for_current_sheet():
            _dlog(f"only-diff async skipped after user edits: sheet={self.sheet}")
            return False
        if not getattr(self, "_data_ready", False):
            self._prefer_only_diff_when_ready = True
            return False
        if not self.row_pairs:
            return False
        cache_key = self._current_only_diff_cache_key()
        if self._has_valid_only_diff_snapshot_cache():
            return False
        if self._only_diff_async_building and self._only_diff_async_build_key == cache_key:
            self._set_only_diff_pending_info()
            return True

        self._only_diff_async_build_seq += 1
        build_seq = int(self._only_diff_async_build_seq)
        self._lifecycle_canceled = False
        self.app._claim_priority_exact(self, build_seq)
        self._only_diff_async_build_key = cache_key
        self._only_diff_async_building = True
        self._only_diff_async_requested_value = int(self.only_diff_var.get())
        self._only_diff_preview_full = True
        self._set_only_diff_pending_info()
        self._refresh_interaction_gate()
        if user_initiated and getattr(self.app, "selected_sheet", None) == self.sheet:
            self.app._begin_only_diff_progress(self, build_seq)

        sheet_name = self.sheet
        max_col = int(self.max_col or 1)
        row_pairs = list(self.row_pairs)
        row_a_to_pair_idx = dict(self.row_a_to_pair_idx)
        row_b_to_pair_idx = dict(self.row_b_to_pair_idx)
        mine_to_base_row = dict(self.mine_to_base_row)
        theirs_to_base_row = dict(self.theirs_to_base_row)
        pair_base_row_override = dict(getattr(self, "pair_base_row_override", {}) or {})
        missing_base_row_map = dict(getattr(self, "_missing_base_row_map", {}) or {})
        has_base = bool(self._is_three_way_enabled() and getattr(self.app, "has_base", False))
        align_enabled = bool(self._align_rows_enabled)
        structural_cols_snapshot = set(
            self._active_column_comparison_cache().structural_diff_cols
        )

        def _has_row_content_diff(cols) -> bool:
            return any(int(col) == -1 or int(col) not in structural_cols_snapshot for col in (cols or ()))

        def _base_row_for_snapshot(pair_idx: int, pair: tuple[int | None, int | None]) -> int | None:
            if not has_base:
                return None
            if pair_idx in pair_base_row_override:
                return pair_base_row_override.get(pair_idx)
            ra, rb = pair
            mapped = missing_base_row_map.get(pair_idx)
            if mapped is not None:
                return mapped
            if ra is not None and ra in mine_to_base_row:
                return mine_to_base_row.get(ra)
            if rb is not None and rb in theirs_to_base_row:
                return theirs_to_base_row.get(rb)
            return None

        def _worker_impl():
            wb_a_val = None
            wb_b_val = None
            wb_base_val = None
            wb_a_edit = None
            wb_b_edit = None
            wb_base_edit = None
            last_progress_emit = [0.0]

            def _cancelled():
                return bool(
                    getattr(self.app, "_is_closing", False)
                    or build_seq != self._only_diff_async_build_seq
                )

            def _report_progress(stage: str, current: int, total: int, *, force: bool = False):
                now = time.monotonic()
                if not force and now - last_progress_emit[0] < 0.12:
                    return
                last_progress_emit[0] = now
                try:
                    self.app._queue_ui_task(
                        lambda s=str(stage), c=int(current), t=max(1, int(total)): (
                            self.app._update_only_diff_progress(
                                self,
                                build_seq,
                                s,
                                c,
                                t,
                            )
                        )
                    )
                except Exception:
                    pass

            if _cancelled():
                return
            _report_progress("正在打开工作簿", 0, 1, force=True)
            try:
                wb_a_val = load_workbook(self.app._file_a_val_path, data_only=True, read_only=True)
                wb_b_val = load_workbook(self.app._file_b_val_path, data_only=True, read_only=True)
                if has_base and getattr(self.app, "_file_base_val_path", None):
                    wb_base_val = load_workbook(self.app._file_base_val_path, data_only=True, read_only=True)
                wb_a_edit = load_workbook(self.app.file_a, data_only=False, read_only=True)
                wb_b_edit = load_workbook(self.app.file_b, data_only=False, read_only=True)
                if has_base and getattr(self.app, "base_path", None):
                    wb_base_edit = load_workbook(self.app.base_path, data_only=False, read_only=True)
                if _cancelled():
                    _wbs_close(wb_a_val, wb_b_val, wb_base_val, wb_a_edit, wb_b_edit, wb_base_edit)
                    return
            except Exception as e:
                _dlog(f"only-diff async open failed sheet={sheet_name}: {e}")
                _wbs_close(wb_a_val, wb_b_val, wb_base_val, wb_a_edit, wb_b_edit, wb_base_edit)

                def _apply_open_fail():
                    if build_seq != self._only_diff_async_build_seq:
                        return
                    self._only_diff_async_building = False
                    self._only_diff_async_build_key = None
                    self._lifecycle_error = "精确差异生成失败"
                    self.app._finish_only_diff_progress(
                        self,
                        build_seq,
                        outcome="open-failed",
                    )
                    self._refresh_diff_block_ui()
                    self._refresh_interaction_gate()
                    show_notice = getattr(self.app, "show_nonblocking_notice", None)
                    if callable(show_notice):
                        show_notice(
                            f"{self.sheet} 精确差异生成失败，可稍后重试“只看差异”。",
                            warning=True,
                            duration_ms=8000,
                        )

                try:
                    self.app._queue_ui_task(_apply_open_fail)
                except Exception:
                    pass
                return

            result = {
                "build_key": cache_key,
                "build_seq": build_seq,
                "sheet": sheet_name,
                "diff_pair_indices": [],
                "pair_diff_cols": {},
                "pair_base_diff_cols": {},
                "pair_parts_a": {},
                "pair_parts_b": {},
                "pair_parts_base": {},
            }
            try:
                ws_a_val = wb_a_val[sheet_name]
                ws_b_val = wb_b_val[sheet_name]
                ws_a_edit = wb_a_edit[sheet_name]
                ws_b_edit = wb_b_edit[sheet_name]
                ws_base_val = wb_base_val[sheet_name] if wb_base_val is not None and sheet_name in wb_base_val.sheetnames else None
                ws_base_edit = wb_base_edit[sheet_name] if wb_base_edit is not None and sheet_name in wb_base_edit.sheetnames else ws_base_val
                edit_cache_a: dict[int, tuple] = {}
                edit_cache_b: dict[int, tuple] = {}
                edit_cache_base: dict[int, tuple] = {}

                def _store_base_parts(pair_idx: int, pair, rows_base: dict):
                    if not has_base:
                        return
                    base_row = _base_row_for_snapshot(pair_idx, pair)
                    if base_row is None or ws_base_val is None:
                        result["pair_parts_base"][pair_idx] = []
                        return
                    result["pair_parts_base"][pair_idx] = self._raw_parts_from_row_values(
                        _row_from_cache(rows_base, base_row, max_col)
                    )

                def _formula_rows(ws_edit, stage: str):
                    rows = {}
                    if ws_edit is None:
                        return rows
                    total = max(1, int(ws_edit.max_row or 1))
                    for row_idx, cells in enumerate(
                        ws_edit.iter_rows(min_col=1, max_col=max_col, values_only=False),
                        start=1,
                    ):
                        if (row_idx & 255) == 0:
                            _report_progress(stage, row_idx, total)
                        if (row_idx & 255) == 0 and _cancelled():
                            break
                        values = tuple(cell.value for cell in cells)
                        if any(
                            getattr(cell, "data_type", None) == "f"
                            or _special_formula_signature(cell.value) is not None
                            for cell in cells
                        ):
                            rows[row_idx] = _pad_row_values(values, max_col)
                    _report_progress(stage, total, total, force=True)
                    return rows

                formula_rows_a = _formula_rows(ws_a_edit, "正在扫描 Mine 公式")
                formula_rows_b = _formula_rows(ws_b_edit, "正在扫描 Theirs 公式")
                formula_rows_base = (
                    _formula_rows(ws_base_edit, "正在扫描 Base 公式")
                    if has_base
                    else {}
                )

                def _needs_formula_exact(row_left, row_right, edit_left, edit_right):
                    for offset in range(max_col):
                        if row_left[offset] is not None or row_right[offset] is not None:
                            continue
                        left_formula = _formula_text(edit_left[offset]) or _special_formula_signature(edit_left[offset])
                        right_formula = _formula_text(edit_right[offset]) or _special_formula_signature(edit_right[offset])
                        if left_formula or right_formula:
                            return True
                    return False

                def _edit_rows_for(needed_rows, preloaded, ws_edit):
                    needed = sorted({int(row) for row in needed_rows if row is not None})
                    result_rows = {row: preloaded[row] for row in needed if row in preloaded}
                    missing = [row for row in needed if row not in result_rows]
                    if missing and ws_edit is not None:
                        result_rows.update(_read_rows_into_cache(ws_edit, missing, max_col))
                    return result_rows

                if align_enabled and row_pairs:
                    pair_count = len(row_pairs)
                    processed_pairs = 0
                    block = _LARGE_SHEET_BLOCK_ROWS
                    for block_end in range(pair_count, 0, -block):
                        if _cancelled():
                            return
                        block_start = max(0, block_end - block)
                        block_pairs = row_pairs[block_start:block_end]
                        rows_a = _read_rows_into_cache(ws_a_val, [ra for ra, _rb in block_pairs if ra is not None], max_col)
                        rows_b = _read_rows_into_cache(ws_b_val, [rb for _ra, rb in block_pairs if rb is not None], max_col)
                        base_rows_needed = []
                        if has_base and ws_base_val is not None:
                            for off, pair in enumerate(block_pairs):
                                base_row = _base_row_for_snapshot(block_start + off, pair)
                                if base_row is not None:
                                    base_rows_needed.append(base_row)
                        rows_base = _read_rows_into_cache(ws_base_val, base_rows_needed, max_col) if (has_base and ws_base_val is not None) else {}
                        exact_rows: list[tuple[int, int | None, int | None, int | None, set[int], bool, set[int], bool]] = []

                        for off in range(len(block_pairs) - 1, -1, -1):
                            pair_idx = block_start + off
                            ra, rb = block_pairs[off]
                            row_a = _row_from_cache(rows_a, ra, max_col)
                            row_b = _row_from_cache(rows_b, rb, max_col)
                            if (ra is None) != (rb is None):
                                cols = {-1}
                                need_exact_ab = False
                            else:
                                cols, need_exact_ab = self._quick_diff_cols_from_value_rows(row_a, row_b)
                                if not need_exact_ab and (ra in formula_rows_a or rb in formula_rows_b):
                                    need_exact_ab = _needs_formula_exact(
                                        row_a,
                                        row_b,
                                        _row_from_cache(formula_rows_a, ra, max_col),
                                        _row_from_cache(formula_rows_b, rb, max_col),
                                    )
                            base_cols = set()
                            need_exact_base = False
                            base_row = None
                            if has_base and ws_base_val is not None:
                                base_row = _base_row_for_snapshot(pair_idx, (ra, rb))
                                if base_row is None and ra is not None and rb is not None:
                                    base_cols = {-1}
                                elif base_row is not None and ra is None:
                                    base_cols = {-1}
                                elif base_row is not None:
                                    row_base = _row_from_cache(rows_base, base_row, max_col)
                                    base_cols, need_exact_base = self._quick_diff_cols_from_value_rows(
                                        row_a, row_base, right_side="base"
                                    )
                                    if not need_exact_base and (ra in formula_rows_a or base_row in formula_rows_base):
                                        need_exact_base = _needs_formula_exact(
                                            row_a,
                                            row_base,
                                            _row_from_cache(formula_rows_a, ra, max_col),
                                            _row_from_cache(formula_rows_base, base_row, max_col),
                                        )
                            if (not cols) and (not base_cols) and (not need_exact_ab) and (not need_exact_base):
                                continue
                            if need_exact_ab or need_exact_base:
                                exact_rows.append((pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base))
                                continue
                            if not (_has_row_content_diff(cols) or _has_row_content_diff(base_cols)):
                                continue
                            result["diff_pair_indices"].append(pair_idx)
                            result["pair_diff_cols"][pair_idx] = cols
                            if has_base:
                                result["pair_base_diff_cols"][pair_idx] = base_cols
                            result["pair_parts_a"][pair_idx] = self._raw_parts_from_row_values(row_a)
                            result["pair_parts_b"][pair_idx] = self._raw_parts_from_row_values(row_b)
                            _store_base_parts(pair_idx, (ra, rb), rows_base)

                        if exact_rows:
                            exact_rows_a = [ra for _pair_idx, ra, _rb, _base_row, _cols, need_ab, _bcols, need_base in exact_rows if ra is not None and (need_ab or need_base)]
                            exact_rows_b = [rb for _pair_idx, _ra, rb, _base_row, _cols, need_ab, _bcols, _need_base in exact_rows if rb is not None and need_ab]
                            exact_rows_base = [base_row for _pair_idx, _ra, _rb, base_row, _cols, _need_ab, _bcols, need_base in exact_rows if base_row is not None and need_base]
                            rows_a_edit = _edit_rows_for(exact_rows_a, formula_rows_a, ws_a_edit)
                            rows_b_edit = _edit_rows_for(exact_rows_b, formula_rows_b, ws_b_edit)
                            rows_base_edit = _edit_rows_for(exact_rows_base, formula_rows_base, ws_base_edit) if has_base else {}
                            for pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base in exact_rows:
                                row_a = _row_from_cache(rows_a, ra, max_col)
                                row_b = _row_from_cache(rows_b, rb, max_col)
                                row_a_edit = _row_from_cache(rows_a_edit, ra, max_col)
                                row_b_edit = _row_from_cache(rows_b_edit, rb, max_col)
                                if need_exact_ab:
                                    raw_a, raw_b, cols = self._build_row_parts_and_diff_pair_from_values(
                                        row_a,
                                        row_b,
                                        ra=ra,
                                        rb=rb,
                                        ws_a_edit=ws_a_edit,
                                        ws_b_edit=ws_b_edit,
                                        edit_cache_a=edit_cache_a,
                                        edit_cache_b=edit_cache_b,
                                        row_a_edit_vals=row_a_edit,
                                        row_b_edit_vals=row_b_edit,
                                    )
                                else:
                                    raw_a = self._raw_parts_from_row_values(row_a)
                                    raw_b = self._raw_parts_from_row_values(row_b)
                                if need_exact_base and has_base and ws_base_val is not None and ra is not None:
                                    row_base = _row_from_cache(rows_base, base_row, max_col)
                                    row_base_edit = _row_from_cache(rows_base_edit, base_row, max_col)
                                    base_cols = self._compute_base_diff_cols_from_values(
                                        row_a,
                                        row_base,
                                        ra=ra,
                                        base_row=base_row,
                                        ws_a_edit=ws_a_edit,
                                        ws_base_edit=ws_base_edit,
                                        edit_cache_a=edit_cache_a,
                                        edit_cache_base=edit_cache_base,
                                        row_a_edit_vals=row_a_edit,
                                        row_base_edit_vals=row_base_edit,
                                    )
                                if (not cols) and (not base_cols):
                                    continue
                                if not (_has_row_content_diff(cols) or _has_row_content_diff(base_cols)):
                                    continue
                                result["diff_pair_indices"].append(pair_idx)
                                result["pair_diff_cols"][pair_idx] = cols
                                if has_base:
                                    result["pair_base_diff_cols"][pair_idx] = base_cols
                                result["pair_parts_a"][pair_idx] = raw_a
                                result["pair_parts_b"][pair_idx] = raw_b
                                _store_base_parts(pair_idx, (ra, rb), rows_base)
                        processed_pairs += len(block_pairs)
                        _report_progress(
                            "正在生成精确差异",
                            processed_pairs,
                            pair_count,
                            force=processed_pairs >= pair_count,
                        )
                else:
                    max_row_a = ws_a_val.max_row or 1
                    max_row_b = ws_b_val.max_row or 1
                    max_row = max(max_row_a, max_row_b)
                    processed_rows = 0
                    block = _LARGE_SHEET_BLOCK_ROWS
                    for block_end in range(max_row, 0, -block):
                        if _cancelled():
                            return
                        block_start = max(1, block_end - block + 1)
                        rows_a = _read_rows_into_cache(
                            ws_a_val,
                            range(block_start, min(block_end, max_row_a) + 1),
                            max_col,
                        )
                        rows_b = _read_rows_into_cache(
                            ws_b_val,
                            range(block_start, min(block_end, max_row_b) + 1),
                            max_col,
                        )
                        base_rows_needed = []
                        if has_base and ws_base_val is not None:
                            for r in range(block_start, block_end + 1):
                                pair_idx = row_a_to_pair_idx.get(r)
                                if pair_idx is None:
                                    pair_idx = row_b_to_pair_idx.get(r)
                                if pair_idx is None or pair_idx >= len(row_pairs):
                                    continue
                                base_row = _base_row_for_snapshot(pair_idx, row_pairs[pair_idx])
                                if base_row is not None:
                                    base_rows_needed.append(base_row)
                        rows_base = _read_rows_into_cache(ws_base_val, base_rows_needed, max_col) if (has_base and ws_base_val is not None) else {}
                        exact_rows: list[tuple[int, int | None, int | None, int | None, set[int], bool, set[int], bool]] = []

                        for r in range(block_end, block_start - 1, -1):
                            pair_idx = row_a_to_pair_idx.get(r)
                            if pair_idx is None:
                                pair_idx = row_b_to_pair_idx.get(r)
                            if pair_idx is None or pair_idx >= len(row_pairs):
                                continue
                            ra, rb = row_pairs[pair_idx]
                            row_a = _row_from_cache(rows_a, ra, max_col)
                            row_b = _row_from_cache(rows_b, rb, max_col)
                            if (ra is None) != (rb is None):
                                cols = {-1}
                                need_exact_ab = False
                            else:
                                cols, need_exact_ab = self._quick_diff_cols_from_value_rows(row_a, row_b)
                                if not need_exact_ab and (ra in formula_rows_a or rb in formula_rows_b):
                                    need_exact_ab = _needs_formula_exact(
                                        row_a,
                                        row_b,
                                        _row_from_cache(formula_rows_a, ra, max_col),
                                        _row_from_cache(formula_rows_b, rb, max_col),
                                    )
                            base_cols = set()
                            need_exact_base = False
                            base_row = None
                            if has_base and ws_base_val is not None:
                                base_row = _base_row_for_snapshot(pair_idx, (ra, rb))
                            if base_row is None and ra is not None and rb is not None:
                                base_cols = {-1}
                            elif base_row is not None and ra is None:
                                base_cols = {-1}
                            elif base_row is not None:
                                row_base = _row_from_cache(rows_base, base_row, max_col)
                                base_cols, need_exact_base = self._quick_diff_cols_from_value_rows(
                                    row_a, row_base, right_side="base"
                                )
                                if not need_exact_base and (ra in formula_rows_a or base_row in formula_rows_base):
                                    need_exact_base = _needs_formula_exact(
                                        row_a,
                                        row_base,
                                        _row_from_cache(formula_rows_a, ra, max_col),
                                        _row_from_cache(formula_rows_base, base_row, max_col),
                                    )
                            if (not cols) and (not base_cols) and (not need_exact_ab) and (not need_exact_base):
                                continue
                            if need_exact_ab or need_exact_base:
                                exact_rows.append((pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base))
                                continue
                            if not (_has_row_content_diff(cols) or _has_row_content_diff(base_cols)):
                                continue
                            result["diff_pair_indices"].append(pair_idx)
                            result["pair_diff_cols"][pair_idx] = cols
                            if has_base:
                                result["pair_base_diff_cols"][pair_idx] = base_cols
                            result["pair_parts_a"][pair_idx] = self._raw_parts_from_row_values(row_a)
                            result["pair_parts_b"][pair_idx] = self._raw_parts_from_row_values(row_b)
                            _store_base_parts(pair_idx, (ra, rb), rows_base)

                        if exact_rows:
                            exact_rows_a = [ra for _pair_idx, ra, _rb, _base_row, _cols, need_ab, _bcols, need_base in exact_rows if ra is not None and (need_ab or need_base)]
                            exact_rows_b = [rb for _pair_idx, _ra, rb, _base_row, _cols, need_ab, _bcols, _need_base in exact_rows if rb is not None and need_ab]
                            exact_rows_base = [base_row for _pair_idx, _ra, _rb, base_row, _cols, _need_ab, _bcols, need_base in exact_rows if base_row is not None and need_base]
                            rows_a_edit = _edit_rows_for(exact_rows_a, formula_rows_a, ws_a_edit)
                            rows_b_edit = _edit_rows_for(exact_rows_b, formula_rows_b, ws_b_edit)
                            rows_base_edit = _edit_rows_for(exact_rows_base, formula_rows_base, ws_base_edit) if has_base else {}
                            for pair_idx, ra, rb, base_row, cols, need_exact_ab, base_cols, need_exact_base in exact_rows:
                                row_a = _row_from_cache(rows_a, ra, max_col)
                                row_b = _row_from_cache(rows_b, rb, max_col)
                                row_a_edit = _row_from_cache(rows_a_edit, ra, max_col)
                                row_b_edit = _row_from_cache(rows_b_edit, rb, max_col)
                                if need_exact_ab:
                                    raw_a, raw_b, cols = self._build_row_parts_and_diff_pair_from_values(
                                        row_a,
                                        row_b,
                                        ra=ra,
                                        rb=rb,
                                        ws_a_edit=ws_a_edit,
                                        ws_b_edit=ws_b_edit,
                                        edit_cache_a=edit_cache_a,
                                        edit_cache_b=edit_cache_b,
                                        row_a_edit_vals=row_a_edit,
                                        row_b_edit_vals=row_b_edit,
                                    )
                                else:
                                    raw_a = self._raw_parts_from_row_values(row_a)
                                    raw_b = self._raw_parts_from_row_values(row_b)
                                if need_exact_base and has_base and ws_base_val is not None and ra is not None:
                                    row_base = _row_from_cache(rows_base, base_row, max_col)
                                    row_base_edit = _row_from_cache(rows_base_edit, base_row, max_col)
                                    base_cols = self._compute_base_diff_cols_from_values(
                                        row_a,
                                        row_base,
                                        ra=ra,
                                        base_row=base_row,
                                        ws_a_edit=ws_a_edit,
                                        ws_base_edit=ws_base_edit,
                                        edit_cache_a=edit_cache_a,
                                        edit_cache_base=edit_cache_base,
                                        row_a_edit_vals=row_a_edit,
                                        row_base_edit_vals=row_base_edit,
                                    )
                                if (not cols) and (not base_cols):
                                    continue
                                if not (_has_row_content_diff(cols) or _has_row_content_diff(base_cols)):
                                    continue
                                result["diff_pair_indices"].append(pair_idx)
                                result["pair_diff_cols"][pair_idx] = cols
                                if has_base:
                                    result["pair_base_diff_cols"][pair_idx] = base_cols
                                result["pair_parts_a"][pair_idx] = raw_a
                                result["pair_parts_b"][pair_idx] = raw_b
                                _store_base_parts(pair_idx, (ra, rb), rows_base)
                        processed_rows += block_end - block_start + 1
                        _report_progress(
                            "正在生成精确差异",
                            processed_rows,
                            max_row,
                            force=processed_rows >= max_row,
                        )

                result["diff_pair_indices"] = sorted(set(result["diff_pair_indices"]))
                _report_progress("正在准备显示结果", 1, 1, force=True)
            except Exception as e:
                _dlog(f"only-diff async build failed sheet={sheet_name}: {e}")
                result["error"] = str(e)
            finally:
                _wbs_close(wb_a_val, wb_b_val, wb_base_val, wb_a_edit, wb_b_edit, wb_base_edit)

            def _apply_result(res=result, _prepared=False):
                if res.get("build_seq") != self._only_diff_async_build_seq:
                    return
                visible_for_publish = (
                    getattr(self.app, "selected_sheet", None) == self.sheet
                    and not bool(getattr(self.app, "_is_closing", False))
                )
                if (
                    not _prepared
                    and not res.get("error")
                    and res.get("build_key") == self._current_only_diff_cache_key()
                    and not self._has_user_edits_for_current_sheet()
                    and visible_for_publish
                ):
                    # The broker may just have released lower-priority XML
                    # parsing. Reserve a quiet UI window before rebuilding
                    # Text widgets, then acknowledge the lease afterward.
                    release_transition = self.app._reserve_ui_transition_window(
                        1200
                    )

                    def _publish_after_quiet_window():
                        try:
                            _apply_result(res, True)
                        finally:
                            if callable(release_transition):
                                release_transition()

                    try:
                        self.frame.after(75, _publish_after_quiet_window)
                        return
                    except Exception:
                        if callable(release_transition):
                            release_transition()
                if res.get("build_key") != self._current_only_diff_cache_key():
                    self._only_diff_async_building = False
                    self._only_diff_async_build_key = None
                    if not self._has_valid_only_diff_snapshot_cache():
                        self._lifecycle_canceled = True
                    # A foreground rescan may already have produced the exact
                    # row set while this older worker was running.  Dropping
                    # the stale payload must still publish that now-ready
                    # block model to the widgets.
                    self._refresh_diff_block_ui()
                    self._refresh_interaction_gate()
                    self.app._finish_only_diff_progress(
                        self,
                        build_seq,
                        outcome="superseded",
                    )
                    return
                if self._has_user_edits_for_current_sheet():
                    self._only_diff_async_building = False
                    self._only_diff_async_build_key = None
                    self._lifecycle_canceled = True
                    _dlog(f"only-diff async result dropped after user edits: sheet={self.sheet}")
                    self._refresh_diff_block_ui()
                    self._refresh_interaction_gate()
                    self.app._finish_only_diff_progress(
                        self,
                        build_seq,
                        outcome="edited",
                    )
                    return
                self._only_diff_async_building = False
                self._only_diff_async_build_key = None
                if res.get("error"):
                    self._lifecycle_error = str(res.get("error") or "精确差异生成失败")
                    self.app._finish_only_diff_progress(
                        self,
                        build_seq,
                        outcome="failed",
                    )
                    self._refresh_diff_block_ui()
                    self._refresh_interaction_gate()
                    show_notice = getattr(self.app, "show_nonblocking_notice", None)
                    if callable(show_notice):
                        show_notice(
                            f"{self.sheet} 精确差异生成失败，可稍后重试“只看差异”。",
                            warning=True,
                            duration_ms=8000,
                        )
                    return
                self._lifecycle_error = None
                self._lifecycle_canceled = False
                self.pair_diff_cols = {
                    int(pair_idx): set(cols)
                    for pair_idx, cols in (res.get("pair_diff_cols") or {}).items()
                    if cols
                }
                self._pair_diff_full_exact = True
                self._base_diff_full_exact = bool(has_base)
                self._cache_formula_aware = True
                self._only_diff_rows_exact = True
                for pair_idx, cols in (res.get("pair_base_diff_cols") or {}).items():
                    self.pair_base_diff_cols[int(pair_idx)] = set(cols)
                visible = (
                    getattr(self.app, "selected_sheet", None) == self.sheet
                    and not bool(getattr(self.app, "_is_closing", False))
                )
                self._stage_cached_pair_parts(
                    res.get("pair_parts_a") or {},
                    res.get("pair_parts_b") or {},
                    res.get("pair_parts_base") or {},
                    {},
                    replace=False,
                )
                if visible:
                    self._materialize_staged_pair_parts()
                self._cache_only_diff_rows_snapshot(
                    res.get("diff_pair_indices") or [],
                    exact=True,
                )
                self._only_diff_preview_full = False
                self._invalidate_render_cache()
                self._install_exact_diff_map_cache(
                    res.get("diff_pair_indices") or []
                )
                if bool(self.only_diff_var.get()) and visible:
                    self._refresh_mode_switch_preserving_selection(rescan=False)
                    # The first presentation pass can run while the async model
                    # is still marked as building, in which case it correctly
                    # clears/omits block tags.  Re-apply after the result has
                    # been materialized and the ready flag is false so every
                    # pane receives the final block boundaries.
                    self._refresh_diff_block_ui()
                    self._pending_exact_render = False
                elif bool(self.only_diff_var.get()):
                    self._pending_exact_render = True
                    _dlog(f"EXACT_RESULT cached without render sheet={self.sheet}")
                else:
                    self._update_diff_nav_state()
                self._last_only_diff_value = int(self.only_diff_var.get())
                self._refresh_interaction_gate()
                self._persist_only_diff_setting_debounced()
                self.app._finish_only_diff_progress(
                    self,
                    build_seq,
                    outcome="success",
                )

            try:
                if not _cancelled():
                    self.app._queue_ui_task(_apply_result)
            except Exception as e:
                _dlog(f"only-diff async queue failed sheet={sheet_name}: {e}")

        def _handle_submit_failure():
            self.app._release_priority_exact(self, build_seq)
            self._only_diff_async_building = False
            self._only_diff_async_build_key = None
            self._only_diff_preview_full = False
            self._lifecycle_error = "无法启动精确差异后台任务"
            self.app._finish_only_diff_progress(
                self,
                build_seq,
                outcome="submit-failed",
            )
            self._refresh_diff_block_ui()
            self._refresh_interaction_gate()

        def _launch_exact_worker():
            if (
                build_seq != int(self._only_diff_async_build_seq)
                or bool(getattr(self.app, "_is_closing", False))
            ):
                return False
            self._only_diff_async_thread = self.app._submit_priority_exact(
                self,
                build_seq,
                _worker_impl,
            )
            if self._only_diff_async_thread is None:
                _handle_submit_failure()
                return False
            return True

        if user_initiated:
            # Let the modal dialog acquire its grab and paint before openpyxl
            # starts parsing XML. This keeps visible feedback inside the 100 ms
            # contract even on a cold WorldMonster run.
            self._only_diff_async_thread = True
            try:
                self.frame.after(60, _launch_exact_worker)
                return True
            except Exception:
                pass
        return _launch_exact_worker()

    def _cancel_only_diff_calculation(self, build_seq: int | None = None):
        """Cancel only the pending display-mode request, not the stable Sheet."""
        if build_seq is None:
            build_seq = int(self._only_diff_async_build_seq)
        token = (self, int(build_seq))
        if getattr(self.app, "_only_diff_progress_owner", None) != token:
            return
        try:
            button = getattr(self.app, "_only_diff_progress_cancel_btn", None)
            if button is not None:
                button.configure(text="正在取消…", state="disabled")
        except Exception:
            pass

        self._only_diff_async_build_seq += 1
        self._only_diff_async_building = False
        self._only_diff_async_build_key = None
        self._only_diff_preview_full = False
        self._pending_exact_render = False
        self._lifecycle_error = None
        self._lifecycle_canceled = False
        origin = int(getattr(self, "_only_diff_request_origin_value", 0))
        self.only_diff_var.set(origin)
        self._last_only_diff_value = origin
        self._prefer_only_diff_when_ready = bool(origin)
        self.app._release_priority_exact(self, int(build_seq))
        try:
            with self.app._exact_broker_lock:
                pending = self.app._exact_broker_pending
                if pending and pending[0] is self and int(pending[1]) == int(build_seq):
                    self.app._exact_broker_pending = None
        except Exception:
            pass
        self.app._finish_only_diff_progress(
            self,
            int(build_seq),
            outcome="canceled",
        )
        self._refresh_diff_block_ui()
        self._refresh_interaction_gate()
        self._persist_only_diff_setting_debounced()
        try:
            total_rows = len(self.row_pairs) if self.row_pairs else self.max_row
            self.info.configure(
                text=(
                    f"已取消只看差异计算，保留全量视图 | "
                    f"RowsShown: {len(self.display_rows)} / {total_rows}"
                )
            )
        except Exception:
            pass

    def _persist_only_diff_setting_debounced(self):
        try:
            self.app.only_diff_default = int(self.only_diff_var.get())
            if getattr(self, "_settings_save_id", None):
                try:
                    self.frame.after_cancel(self._settings_save_id)
                except Exception:
                    pass
            self._settings_save_id = self.frame.after(1000, self._flush_settings)
        except Exception as e:
            _dlog(f"settings debounce failed: {e}")

    def _schedule_cached_only_diff_mode_switch(self, requested_value: int) -> bool:
        """Publish a large cached mode switch after the Tk callback returns.

        A ready exact cache makes the comparison itself cheap, but rebuilding
        the visible Text panes can still contend with a background XML parser.
        The short reservation gives that parser time to reach a cooperative
        pause before the bounded visible publication runs.
        """
        if bool(getattr(self, "_mode_switch_pending", False)):
            return True
        self._mode_switch_seq += 1
        switch_seq = int(self._mode_switch_seq)
        self._mode_switch_pending = True
        self._last_only_diff_value = int(requested_value)
        self._only_diff_preview_full = False
        self._refresh_interaction_gate()
        try:
            self.info.configure(
                text=(
                    "正在切换为只看差异；当前暂只读..."
                    if requested_value
                    else "正在切换为显示全部；当前暂只读..."
                )
            )
        except Exception:
            pass

        release_transition = None
        reserve_transition = getattr(self.app, "_reserve_ui_transition_window", None)
        if callable(reserve_transition):
            release_transition = reserve_transition(700)

        def _apply_mode_switch():
            self._mode_switch_after_id = None
            if switch_seq != int(getattr(self, "_mode_switch_seq", 0)):
                if callable(release_transition):
                    release_transition()
                return
            if bool(getattr(self.app, "_is_closing", False)):
                self._mode_switch_pending = False
                if callable(release_transition):
                    release_transition()
                return
            if getattr(self.app, "selected_sheet", None) != self.sheet:
                self._pending_exact_render = True
                self._mode_switch_pending = False
                self._refresh_interaction_gate()
                if callable(release_transition):
                    release_transition()
                return
            started = time.perf_counter()
            try:
                self._refresh_mode_switch_preserving_selection(rescan=False)
                self._pending_exact_render = False
            except Exception as exc:
                self._lifecycle_error = f"显示模式切换失败：{exc}"
                _dlog(
                    f"only-diff deferred render failed sheet={self.sheet}: "
                    f"{type(exc).__name__}: {exc}"
                )
            finally:
                self._mode_switch_pending = False
                self._only_diff_preview_full = False
                self._refresh_interaction_gate()
                if callable(release_transition):
                    release_transition()
                _dlog(
                    f"ONLY_DIFF_PUBLISH sheet={self.sheet} "
                    f"requested={bool(requested_value)} "
                    f"render_ms={(time.perf_counter() - started) * 1000.0:.1f}"
                )

        try:
            # Let the checkbox callback return and give cooperative workbook
            # parsers several heartbeat slices to observe the pause event.
            self._mode_switch_after_id = self.frame.after(75, _apply_mode_switch)
            return True
        except Exception:
            if callable(release_transition):
                release_transition()
            self._mode_switch_pending = False
            return False

    def _toggle_only_diff(self):
        # Snapshot mode confirmed by user: diff rows list is generated once when opening (or manual refresh).
        # Toggling "只看差异" only switches display, without recomputing the diff map.
        try:
            _dlog(
                f"TOGGLE only_diff={bool(self.only_diff_var.get())} "
                f"raw={self.only_diff_var.get()} sheet={self.sheet} "
                f"window_state={self.root.state()} geometry={self.root.geometry()}"
            )
        except Exception:
            pass

        if bool(getattr(self, "_only_diff_async_building", False)):
            self.only_diff_var.set(
                int(getattr(self, "_only_diff_async_requested_value", 1))
            )
            self._refresh_interaction_gate()
            return

        cur = int(self.only_diff_var.get())
        previous = int(getattr(self, "_last_only_diff_value", 0))
        # Tk has already changed the IntVar before invoking this callback.
        # Validate the lifecycle that owned the click, not the newly requested
        # mode (which legitimately lacks an exact only-diff snapshot yet).
        self.only_diff_var.set(previous)
        try:
            entry_state = self._derive_lifecycle_state()
        finally:
            self.only_diff_var.set(cur)
        if entry_state != "READY":
            self.only_diff_var.set(previous)
            show_notice = getattr(self.app, "show_nonblocking_notice", None)
            if callable(show_notice):
                show_notice(
                    self._mutation_block_message("切换“只看差异”"),
                    duration_ms=6000,
                )
            self._refresh_interaction_gate()
            return

        # Performance optimization:
        # - For normal sheets with ready diff data, toggling only-diff only changes
        #   display mode and does not need a full rescan.
        # - For large sheets when enabling only-diff, build the exact diff snapshot
        #   in background and keep the current full view responsive until ready.
        if not getattr(self, "_data_ready", False):
            # Never perform a full rescan on the Tk callback. Preserve the
            # checkbox state, prioritize this Sheet's worker, and apply it when
            # the exact cache arrives.
            self._pending_only_diff_value = cur
            self._prefer_only_diff_when_ready = bool(cur)
            if cur:
                self._set_only_diff_pending_info()
            else:
                try:
                    self.info.configure(text="正在后台加载当前 Sheet；完成后显示全量数据...")
                except Exception:
                    pass
            try:
                self.app._enqueue_sheet(
                    self.sheet,
                    front=True,
                    exact_only_diff=bool(cur),
                )
                self.app._kick_worker()
            except Exception as e:
                _dlog(f"only-diff prioritize failed sheet={self.sheet}: {e}")
            self._update_diff_nav_state()
            self._persist_only_diff_setting_debounced()
            return
        if bool(cur) and not self._has_valid_only_diff_snapshot_cache():
            # Do not sweep a large pair map on the Tk callback. The exact worker
            # owns progress, cancellation, and publication for that path.
            cached_synchronously = False
            if (
                not bool(getattr(self, "_is_large_sheet", False))
                or self._has_user_edits_for_current_sheet()
            ):
                cached_synchronously = self._cache_only_diff_rows_from_exact_pair_maps()
            self._only_diff_request_origin_value = previous
            if (not cached_synchronously) and self._start_async_large_only_diff_build(
                user_initiated=True,
            ):
                return
        try:
            _dlog(
                "TOGGLE only_diff refresh: rescan=False "
                f"data_ready={getattr(self, '_data_ready', False)} "
                f"large={getattr(self, '_is_large_sheet', False)} "
                f"sheet={self.sheet}"
            )
        except Exception:
            pass

        if bool(getattr(self, "_is_large_sheet", False)) and not self._full_render:
            # Both directions can expose thousands of rows. Rendering 800 tagged
            # Text lines makes the checkbox callback feel stuck, so switch modes
            # with the same 200-row first window used by large-sheet initial load.
            self._render_limit = min(
                max(1, int(self._render_limit or _LARGE_SHEET_INITIAL_ROWS)),
                _LARGE_SHEET_INITIAL_ROWS,
            )

        if bool(getattr(self, "_is_large_sheet", False)):
            if self._schedule_cached_only_diff_mode_switch(cur):
                self._persist_only_diff_setting_debounced()
                return

        reserve_transition = getattr(self.app, "_reserve_ui_transition_window", None)
        if callable(reserve_transition):
            reserve_transition(300)
        self._refresh_mode_switch_preserving_selection(rescan=False)
        self._last_only_diff_value = cur
        self._only_diff_preview_full = False
        self._refresh_interaction_gate()

        # Persist setting (debounced: write 1 s after last toggle to avoid per-keypress I/O)
        self._persist_only_diff_setting_debounced()

    def _toggle_force_align(self):
        """Manual override for row pairing accuracy, rebuilt off the Tk thread."""
        if not self._guard_mutation_ready("重新行对齐"):
            try:
                self.force_align_var.set(int(bool(self._force_sequence_align)))
            except Exception:
                pass
            return
        try:
            self._force_sequence_align = bool(self.force_align_var.get())
            _dlog(f"TOGGLE force_align={self._force_sequence_align} sheet={self.sheet}")
        except Exception:
            self._force_sequence_align = bool(self.force_align_var.get())
        self._invalidate_only_diff_snapshot_cache()
        # Small sheets do not benefit from a worker round-trip and keeping the
        # synchronous path preserves the immediate editing semantics used by
        # the lightweight merge adapters.  Large sheets are the problematic
        # case (for example Language.xlsx), so only those are moved off Tk.
        if not bool(getattr(self, "_is_large_sheet", False)):
            self._suppress_bg_apply = True
            try:
                self.refresh(row_only=None, rescan=True)
            finally:
                self._suppress_bg_apply = False
            self._update_cursor_lines()
            self._update_diff_nav_state()
            if (
                not bool(getattr(self, "_pair_diff_full_exact", False))
                or (
                    self._is_three_way_enabled()
                    and getattr(self.app, "has_base", False)
                    and not bool(getattr(self, "_base_diff_full_exact", False))
                )
            ):
                self._start_async_large_only_diff_build()
            self._refresh_interaction_gate()
            return
        # A full force-alignment scan can take several seconds on Language.xlsx.
        # Reuse the existing background worker instead of calling refresh()
        # synchronously from the Tk callback (which freezes the window).
        self._data_ready = False
        self._row_model_exact = False
        self._pair_diff_full_exact = False
        self._base_diff_full_exact = False
        self._show_loading(
            "正在后台重新行对齐…当前内容仍可查看，完成后恢复操作"
        )
        self._refresh_interaction_gate()
        try:
            with self.app._compute_lock:
                self.app._sheet_compute_generation[self.sheet] = (
                    int(self.app._sheet_compute_generation.get(self.sheet, 0)) + 1
                )
            self.app._enqueue_sheet(
                self.sheet,
                front=True,
                exact_only_diff=bool(self.only_diff_var.get()),
                force_recompute=True,
                force_align=bool(self._force_sequence_align),
            )
            self.app._kick_worker()
        except Exception as exc:
            self._lifecycle_error = f"后台重新行对齐启动失败：{exc}"
            self._hide_loading()
            self._refresh_interaction_gate()
            _dlog(f"force-align enqueue failed sheet={self.sheet}: {exc}")
        self._refresh_interaction_gate()

    def _flush_settings(self):
        """Debounced settings write: called 1 s after the last only-diff toggle."""
        try:
            os.makedirs(os.path.dirname(_SETTINGS_PATH), exist_ok=True)
            settings = dict(getattr(self.app, "settings", {}) or {})
            settings["only_diff"] = int(self.only_diff_var.get())
            with open(_SETTINGS_PATH, "w", encoding="utf-8") as f:
                json.dump(settings, f, ensure_ascii=False, indent=2)
        except Exception as e:
            _dlog(f"settings save failed: {e}")

    def _manual_rescan(self):
        state = self._derive_lifecycle_state()
        if state not in ("READY", "FAILED", "CANCELED"):
            self._guard_mutation_ready("刷新当前 Sheet")
            return
        if state in ("FAILED", "CANCELED") or not self._has_user_edits_for_current_sheet():
            self._lifecycle_error = None
            self._lifecycle_canceled = False
            self._data_ready = False
            self._row_model_exact = False
            self._only_diff_rows_exact = False
            self._invalidate_only_diff_snapshot_cache()
            self._show_loading("正在后台重新计算当前 Sheet...")
            with self.app._compute_lock:
                self.app._sheet_compute_generation[self.sheet] = (
                    int(self.app._sheet_compute_generation.get(self.sheet, 0)) + 1
                )
            self.app._enqueue_sheet(
                self.sheet,
                front=True,
                exact_only_diff=bool(self.only_diff_var.get()),
                force_recompute=True,
            )
            self.app._kick_worker()
            return
        self._invalidate_only_diff_snapshot_cache()
        self._suppress_bg_apply = True
        try:
            self.refresh(row_only=None, rescan=True)
        finally:
            self._suppress_bg_apply = False  # Fresh data rendered; allow bg applies again.
        self._update_cursor_lines()
        self._update_diff_nav_state()

    # ---------- Merge operations ----------
    def _same_formula_copy_mode(self, src_edit, dst_edit, src_val, dst_val) -> str | None:
        """Return ``noop`` or ``cache`` for same-formula copies."""
        if not _is_same_formula_copy_noop(src_edit, dst_edit):
            return None
        if _merge_cmp_value(src_val) == _merge_cmp_value(dst_val):
            return "noop"
        self._formula_copy_skips_pending += 1
        return "cache"

    def _preflight_region_formula_copy(self, direction: str, pair_indices: list[int]):
        if direction not in ("A2B", "B2A", "BASE2A"):
            return
        if direction == "A2B" and getattr(self.app, "merge_conflict_mode", False):
            return
        ws_a_edit = self.app.ws_a_edit(self.sheet)
        ws_b_edit = self.app.ws_b_edit(self.sheet)
        ws_base_edit = self.app.ws_base_edit(self.sheet) if getattr(self.app, "has_base", False) else None
        ws_a_val = self.app.ws_a_val(self.sheet)
        ws_b_val = self.app.ws_b_val(self.sheet)
        ws_base_val = self.app.ws_base_val(self.sheet) if getattr(self.app, "has_base", False) else None
        for pair_idx in pair_indices:
            if not (0 <= int(pair_idx) < len(self.row_pairs)):
                continue
            pair = self.row_pairs[int(pair_idx)]
            ra, rb = pair
            if direction == "A2B":
                src_ws, src_val_ws, dst_ws, src_row, dst_row = ws_a_edit, ws_a_val, ws_b_edit, ra, rb
            elif direction == "B2A":
                src_ws, src_val_ws, dst_ws, src_row, dst_row = ws_b_edit, ws_b_val, ws_a_edit, rb, ra
            else:
                src_ws, src_val_ws, dst_ws = ws_base_edit, ws_base_val, ws_a_edit
                src_row = self._base_row_for_pair(int(pair_idx), pair)
                dst_row = ra
            if src_ws is None or src_row is None:
                continue
            cols = set(
                (
                    self.pair_base_diff_cols
                    if direction == "BASE2A"
                    else self.pair_diff_cols
                ).get(int(pair_idx), set())
            )
            if dst_row is None or cols == {-1}:
                physical_col_pairs = tuple(
                    (physical_col, physical_col)
                    for physical_col in range(
                        1,
                        max(1, int(src_ws.max_column or 1)) + 1,
                    )
                )
            else:
                physical_col_pairs = []
                for logical_col in sorted(int(col) for col in cols if int(col) > 0):
                    physical_cols = self._action_physical_columns(direction, logical_col)
                    if physical_cols is not None:
                        physical_col_pairs.append(physical_cols)
            for src_col, dst_col in physical_col_pairs:
                if int(src_col) <= 0 or int(dst_col) <= 0:
                    continue
                src_edit = src_ws.cell(row=int(src_row), column=int(src_col)).value
                dst_edit = (
                    dst_ws.cell(row=int(dst_row), column=int(dst_col)).value
                    if dst_ws is not None and dst_row is not None else None
                )
                src_val = (
                    src_val_ws.cell(row=int(src_row), column=int(src_col)).value
                    if src_val_ws is not None else None
                )
                _copy_edit_value_for_destination(
                    src_val,
                    src_edit,
                    dst_edit,
                    src_row=int(src_row),
                    src_col=int(src_col),
                    dst_row=int(dst_row) if dst_row is not None else int(src_row),
                    dst_col=int(dst_col),
                )

    def _show_formula_copy_skip_notice(self, count: int):
        if count <= 0:
            return
        msg = (
            f"已保留 {count} 个单元格的原公式，并采用 theirs 的当前计算结果。\n\n"
            "这些结果来自其他输入单元格。为保证以后重新计算仍一致，"
            "请同时在产生差异的依赖 Sheet/输入列中采用对应数据。"
        )
        _dlog(f"FORMULA_RESULT_CACHE_ADOPTED sheet={self.sheet} count={count}")
        try:
            self.info.configure(text=f"已采用 {count} 个公式缓存结果并保留公式；请同步合并依赖数据")
        except Exception:
            pass
        try:
            messagebox.showinfo("已保留公式并采用计算结果", msg)
        except Exception:
            pass

    def _copy_cell(self, direction: str, event):
        if not self._guard_copy_direction(direction, "单元格覆盖"):
            return "break"
        if not self._guard_mutation_ready("单元格覆盖"):
            return "break"
        # Upgrade the cached value workbooks only after the mutation gate has
        # succeeded.  Browsing and background comparison remain read-only.
        self.app._ensure_edit_loaded()
        self.app._ensure_value_workbooks_regular()
        previous_bg_suppression = bool(getattr(self, "_suppress_bg_apply", False))
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        if callable(begin_interactive):
            begin_interactive(self)
        self._suppress_bg_apply = True
        try:
            if self._is_missing_sheet_view():
                self._copy_missing_sheet(direction, _guarded=True)
                return
            anchor = self._capture_view_anchor()
            if direction == "A2B":
                src = self.left
            elif direction == "MINE2A":
                src = self.left
            elif direction == "BASE2A":
                src = self.base
            else:
                src = self.right
            idx = src.index(f"@{event.x},{event.y}")
            src.mark_set("insert", idx)
            line = int(idx.split(".")[0])
            col_char = int(idx.split(".")[1])

            if not (1 <= line <= len(self.display_rows)):
                return
            pair = self._pair_for_line(line)
            ra = self._row_for_side(pair, "A")
            rb = self._row_for_side(pair, "B")
            if direction == "A2B":
                if ra is None:
                    return
                if rb is None:
                    # A-only row: insert new row in B then return (full-row insert).
                    pair_idx = self.display_rows[line - 1]
                    self._insert_row_copy(pair_idx, "A2B", ra, False, None, anchor)
                    return
                src_r = ra
                dst_r = rb
            elif direction == "MINE2A":
                if ra is None and rb is None:
                    return
                src_r = ra if ra is not None else rb
                dst_r = ra if ra is not None else rb
            elif direction == "BASE2A":
                if ra is None:
                    return
                pair_idx = self.display_rows[line - 1]
                src_r = self._base_row_for_pair(pair_idx, pair)
                dst_r = ra
            else:
                if rb is None:
                    return
                if ra is None:
                    # B-only row: insert new row in A then return (full-row insert).
                    pair_idx = self.display_rows[line - 1]
                    self._insert_row_copy(pair_idx, "B2A", rb, False, None, anchor)
                    return
                src_r = rb
                dst_r = ra

            # Use strict character spans to resolve clicked column.
            # Separator clicks must not map to adjacent cells.
            spans = self._spans_for_line()
            c = None
            for col_num, (s0, e0) in spans.items():
                if s0 <= col_char < e0:
                    c = col_num
                    break
            if c is None:
                return
            if c > self._logical_slot_count():
                c = self._logical_slot_count()

            pair_idx = self.display_rows[line - 1]
            # The click column is a logical slot.  Keep-mine only resolves the
            # logical conflict; all write directions resolve distinct physical
            # source/destination columns through the shared projection.
            if direction == "MINE2A":
                if getattr(self.app, "merge_conflict_mode", False):
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_cell(dst_r, c)
                return
            if getattr(self.app, "merge_conflict_mode", False) and direction == "A2B":
                self.app.user_touched_conflicts = True
                self._resolve_conflict_cell(dst_r, c)
                return
            self._copy_single_cell_by_pair(
                pair_idx,
                direction,
                c,
                _guarded=True,
            )
            return

            # Merge conflict mode:
            # - "A2B" means keep mine, just mark resolved.
            # - "B2A" means apply theirs to mine, then mark resolved.
            if getattr(self.app, "merge_conflict_mode", False):
                if direction == "A2B":
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_cell(dst_r, c)
                    return

            if direction == "A2B":
                old_edit = self.app.ws_b_edit(self.sheet).cell(row=dst_r, column=c).value
                old_val = self.app.ws_b_val(self.sheet).cell(row=dst_r, column=c).value
                v_edit = self.app.ws_a_edit(self.sheet).cell(row=src_r, column=c).value
                v_val = self.app.ws_a_val(self.sheet).cell(row=src_r, column=c).value
                new_edit = _copy_edit_value_for_destination(
                    v_val, v_edit, old_edit,
                    src_row=src_r, src_col=c, dst_row=dst_r, dst_col=c,
                )
                formula_mode = self._same_formula_copy_mode(new_edit, old_edit, v_val, old_val)
                if formula_mode == "noop":
                    return
                if formula_mode == "cache":
                    self.app.ws_b_val(self.sheet).cell(row=dst_r, column=c).value = v_val
                    self.app.record_manual_b_formula_cache(self.sheet, dst_r, c, v_val)
                    self.app.modified_b = True
                    self.app.modified_sheets_b.add(self.sheet)
                    self.app.push_undo({"sheet": self.sheet, "target": "B", "cells": [(dst_r, c, old_edit, old_val)]})
                    self._show_formula_copy_skip_notice(1)
                else:
                    # Cached-value mode: always write the cached value
                    self.app.clear_manual_b_formula_cache(self.sheet, dst_r, c)
                    _assign_edit_cell_value(
                        self.app.ws_b_edit(self.sheet).cell(row=dst_r, column=c),
                        new_edit,
                    )
                    self.app.record_manual_b_cell(self.sheet, dst_r, c, new_edit)
                    self.app.ws_b_val(self.sheet).cell(row=dst_r, column=c).value = v_val
                    self.app.modified_b = True
                    self.app.modified_sheets_b.add(self.sheet)
                    self.app.push_undo({"sheet": self.sheet, "target": "B", "cells": [(dst_r, c, old_edit, old_val)]})
            elif direction == "MINE2A":
                # Keep Mine/Target Working without copying any cell.
                if getattr(self.app, "merge_conflict_mode", False):
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_cell(dst_r, c)
                marker = getattr(self.app, "mark_difference_pair_processed", None)
                if callable(marker):
                    marker(self.sheet, int(pair_idx), (int(c),), True)
                else:
                    selected_id = getattr(self, "_selected_difference_item_id", None)
                    if selected_id:
                        self.app.mark_difference_processed(selected_id, True)
                return
            elif direction == "B2A":
                old_edit = self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=c).value
                old_val = self.app.ws_a_val(self.sheet).cell(row=dst_r, column=c).value
                v_edit = self.app.ws_b_edit(self.sheet).cell(row=src_r, column=c).value
                v_val = self.app.ws_b_val(self.sheet).cell(row=src_r, column=c).value
                new_edit = _copy_edit_value_for_destination(
                    v_val, v_edit, old_edit,
                    src_row=src_r, src_col=c, dst_row=dst_r, dst_col=c,
                )
                formula_mode = self._same_formula_copy_mode(new_edit, old_edit, v_val, old_val)
                if formula_mode == "noop":
                    return
                if formula_mode == "cache":
                    self.app.ws_a_val(self.sheet).cell(row=dst_r, column=c).value = v_val
                    self.app.record_manual_a_formula_cache(self.sheet, dst_r, c, v_val)
                    self.app.modified_a = True
                    self.app.modified_sheets_a.add(self.sheet)
                    self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": [(dst_r, c, old_edit, old_val)]})
                    self._show_formula_copy_skip_notice(1)
                else:
                    _assign_edit_cell_value(self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=c), new_edit)
                    self.app.ws_a_val(self.sheet).cell(row=dst_r, column=c).value = v_val
                    self.app.record_manual_a_cell(self.sheet, dst_r, c, new_edit)
                    self.app.modified_a = True
                    self.app.modified_sheets_a.add(self.sheet)
                    self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": [(dst_r, c, old_edit, old_val)]})
                # In conflict mode, B2A applies theirs; mark conflict resolved.
                if getattr(self.app, "merge_conflict_mode", False):
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_cell(dst_r, c)
                    return
            else:
                old_edit = self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=c).value
                old_val = self.app.ws_a_val(self.sheet).cell(row=dst_r, column=c).value
                if src_r is None:
                    v_edit = None
                    v_val = None
                else:
                    v_edit = self.app.ws_base_edit(self.sheet).cell(row=src_r, column=c).value
                    v_val = self.app.ws_base_val(self.sheet).cell(row=src_r, column=c).value
                new_edit = (
                    _copy_edit_value_for_destination(
                        v_val, v_edit, old_edit,
                        src_row=src_r, src_col=c, dst_row=dst_r, dst_col=c,
                    )
                    if src_r is not None else None
                )
                formula_mode = self._same_formula_copy_mode(new_edit, old_edit, v_val, old_val)
                if formula_mode == "noop":
                    return
                if formula_mode == "cache":
                    self.app.ws_a_val(self.sheet).cell(row=dst_r, column=c).value = v_val
                    self.app.record_manual_a_formula_cache(self.sheet, dst_r, c, v_val)
                    self.app.modified_a = True
                    self.app.modified_sheets_a.add(self.sheet)
                    self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": [(dst_r, c, old_edit, old_val)]})
                    self._show_formula_copy_skip_notice(1)
                else:
                    _assign_edit_cell_value(self.app.ws_a_edit(self.sheet).cell(row=dst_r, column=c), new_edit)
                    self.app.ws_a_val(self.sheet).cell(row=dst_r, column=c).value = v_val
                    self.app.record_manual_a_cell(self.sheet, dst_r, c, new_edit)
                    self.app.modified_a = True
                    self.app.modified_sheets_a.add(self.sheet)
                    self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": [(dst_r, c, old_edit, old_val)]})

            # Mark as touched: keep row visible in "只看差异" even if diffs are resolved.
            pair = self._pair_for_line(line)
            touched_r = self._row_for_side(pair, "A") or self._row_for_side(pair, "B")
            if touched_r is not None:
                self.touched_rows.add(touched_r)
            self._invalidate_only_diff_snapshot_cache()
            self._invalidate_render_cache()

            # Minimize flicker: use row-only incremental refresh after overwrite.
            # Full-sheet rescan can be done manually by user when needed.
            if bool(self.only_diff_var.get()) and self.snapshot_only_diff:
                self._recalc_row_diff_and_update(dst_r)
            self.refresh(row_only=dst_r, rescan=False)
            self._restore_view_anchor(anchor)
            self._update_cursor_lines()
        except Exception as e:
            messagebox.showerror("Error", f"覆盖单元格失败：\n{e}")
        finally:
            self._suppress_bg_apply = previous_bg_suppression
            if callable(end_interactive):
                end_interactive()

    # ---------- Row-insert helpers ----------

    def _find_row_insert_position(self, pair_idx: int, side: str) -> int:
        """Return the worksheet row index at which to insert a new row.

        Scans row_pairs[0..pair_idx-1] to find the last non-None row on the
        given side ('A' or 'B').  Returns last_row + 1, or 1 if no prior rows
        exist on that side.
        """
        last_row = 0
        side_idx = 0 if side == "A" else 1
        for i in range(pair_idx):
            r = self.row_pairs[i][side_idx]
            if r is not None:
                last_row = r
        return last_row + 1

    def _find_base_row_insert_position(self, pair_idx: int) -> int:
        """Return the BASE worksheet row index at which to insert a new row.

        Uses the BASE row mapping (mine_to_base_row / theirs_to_base_row via
        _base_row_for_pair) instead of mine's row number, so that when mine and
        base are not identity-aligned (mine has prior inserts/deletes vs base)
        the blank base row lands at the correct BASE position. Returns
        last_base_row + 1, or 1 if no prior pair maps to a base row.
        """
        last_base = 0
        for i in range(pair_idx):
            try:
                br = self._base_row_for_pair(i, self.row_pairs[i])
            except Exception:
                br = None
            if br is not None:
                last_base = int(br)
        return last_base + 1

    @staticmethod
    def _shift_row_number_for_insert(row_num: int | None, insert_pos: int, amount: int = 1) -> int | None:
        if row_num is None:
            return None
        try:
            row_num = int(row_num)
        except Exception:
            return row_num
        amount = max(0, int(amount))
        return row_num + amount if row_num >= int(insert_pos) else row_num

    def _rebuild_row_pair_lookup_maps(self):
        self.row_a_to_pair_idx = {}
        self.row_b_to_pair_idx = {}
        for idx, (ra, rb) in enumerate(self.row_pairs):
            if ra is not None:
                self.row_a_to_pair_idx[int(ra)] = idx
            if rb is not None:
                self.row_b_to_pair_idx[int(rb)] = idx

    def _update_row_model_after_insert(
        self,
        *,
        pair_idx: int,
        direction: str,
        insert_pos: int,
        base_insert_pos: int | None = None,
        old_pair: tuple[int | None, int | None] | None,
        base_inserted: bool,
    ):
        if not (0 <= int(pair_idx) < len(self.row_pairs)):
            return

        pair_idx = int(pair_idx)
        insert_pos = int(insert_pos)
        # Base rows shift at the base-coordinate insert position (defaults to
        # insert_pos for backward compatibility / identity mine-base alignment).
        base_insert_pos = int(base_insert_pos) if base_insert_pos is not None else insert_pos
        old_pair = old_pair if old_pair is not None else self.row_pairs[pair_idx]
        old_base_row = None
        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            try:
                old_base_row = self._base_row_for_pair(pair_idx, old_pair)
            except Exception:
                old_base_row = None

        updated_pairs: list[tuple[int | None, int | None]] = []
        for idx, (ra, rb) in enumerate(self.row_pairs):
            if direction in ("B2A", "BASE2A"):
                ra = self._shift_row_number_for_insert(ra, insert_pos)
                if idx == pair_idx:
                    ra = insert_pos
            else:
                rb = self._shift_row_number_for_insert(rb, insert_pos)
                if idx == pair_idx:
                    rb = insert_pos
            updated_pairs.append((ra, rb))
        self.row_pairs = updated_pairs
        self._rebuild_row_pair_lookup_maps()

        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            def _shift_base_row(base_row: int | None) -> int | None:
                if not base_inserted:
                    return base_row
                return self._shift_row_number_for_insert(base_row, base_insert_pos)

            shifted_base_row = _shift_base_row(old_base_row)
            mine_map_old = dict(getattr(self, "mine_to_base_row", {}) or {})
            theirs_map_old = dict(getattr(self, "theirs_to_base_row", {}) or {})
            overrides_old = dict(getattr(self, "pair_base_row_override", {}) or {})

            if direction == "B2A":
                mine_map_new: dict[int, int] = {}
                for ra, base_row in mine_map_old.items():
                    new_ra = self._shift_row_number_for_insert(ra, insert_pos)
                    if new_ra is None:
                        continue
                    mine_map_new[int(new_ra)] = _shift_base_row(base_row)
                if shifted_base_row is not None:
                    mine_map_new[insert_pos] = int(shifted_base_row)
                self.mine_to_base_row = mine_map_new

                theirs_map_new: dict[int, int] = {}
                for rb, base_row in theirs_map_old.items():
                    if rb is None:
                        continue
                    theirs_map_new[int(rb)] = _shift_base_row(base_row)
                self.theirs_to_base_row = theirs_map_new
            else:
                mine_map_new = {}
                for ra, base_row in mine_map_old.items():
                    if ra is None:
                        continue
                    mine_map_new[int(ra)] = _shift_base_row(base_row)
                self.mine_to_base_row = mine_map_new

                theirs_map_new: dict[int, int] = {}
                for rb, base_row in theirs_map_old.items():
                    new_rb = self._shift_row_number_for_insert(rb, insert_pos)
                    if new_rb is None:
                        continue
                    theirs_map_new[int(new_rb)] = _shift_base_row(base_row)
                if shifted_base_row is not None:
                    theirs_map_new[insert_pos] = int(shifted_base_row)
                self.theirs_to_base_row = theirs_map_new

            overrides_new: dict[int, int | None] = {}
            for idx, base_row in overrides_old.items():
                overrides_new[int(idx)] = _shift_base_row(base_row)
            if shifted_base_row is not None:
                overrides_new[pair_idx] = int(shifted_base_row)
            else:
                overrides_new.pop(pair_idx, None)
            self.pair_base_row_override = overrides_new

        try:
            self.max_row = max(
                int(self.max_row or 1),
                int(getattr(self.app.ws_a_val(self.sheet), "max_row", 1) or 1),
                int(getattr(self.app.ws_b_val(self.sheet), "max_row", 1) or 1),
            )
        except Exception:
            pass

    def _prime_pair_cache_after_insert(
        self,
        *,
        pair_idx: int,
        ws_a_val,
        ws_b_val,
        ws_a_edit,
        ws_b_edit,
    ):
        if not (0 <= int(pair_idx) < len(self.row_pairs)):
            return
        pair_idx = int(pair_idx)
        ra, rb = self.row_pairs[pair_idx]
        line_a, line_b, cols = self._build_row_and_diff_pair(ws_a_val, ws_b_val, ws_a_edit, ws_b_edit, ra, rb)
        self.pair_text_a[pair_idx] = line_a
        self.pair_text_b[pair_idx] = line_b
        self.pair_diff_cols[pair_idx] = cols
        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            try:
                self.pair_base_diff_cols[pair_idx] = self._compute_base_diff_cols_for_pair(
                    pair_idx,
                    (ra, rb),
                    max_col=self.max_col,
                    ws_a_val=ws_a_val,
                    ws_a_edit=ws_a_edit,
                    ws_base_val=self.app.ws_base_val(self.sheet),
                    ws_base_edit=self.app.ws_base_edit(self.sheet),
                )
            except Exception:
                self.pair_base_diff_cols.pop(pair_idx, None)
        else:
            self.pair_base_diff_cols.pop(pair_idx, None)

    def _try_fast_refresh_after_row_insert(
        self,
        *,
        pair_idx: int,
        direction: str,
        insert_pos: int,
        base_insert_pos: int | None = None,
        old_pair: tuple[int | None, int | None] | None,
        base_inserted: bool,
        suppress_refresh: bool,
        anchor,
        ws_a_val,
        ws_b_val,
        ws_a_edit,
        ws_b_edit,
    ) -> bool:
        if suppress_refresh:
            return False
        if not getattr(self, "_is_large_sheet", False):
            return False
        if not getattr(self, "_data_ready", False):
            return False
        try:
            self._update_row_model_after_insert(
                pair_idx=pair_idx,
                direction=direction,
                insert_pos=insert_pos,
                base_insert_pos=base_insert_pos,
                old_pair=old_pair,
                base_inserted=base_inserted,
            )
            self._ensure_column_projection_current(
                "插入行后刷新",
                ws_a_val=ws_a_val,
                ws_b_val=ws_b_val,
                ws_a_edit=ws_a_edit,
                ws_b_edit=ws_b_edit,
                ws_base_val=(self.app.ws_base_val(self.sheet) if getattr(self.app, "has_base", False) else None),
                ws_base_edit=(self.app.ws_base_edit(self.sheet) if getattr(self.app, "has_base", False) else None),
            )
            self._prime_pair_cache_after_insert(
                pair_idx=pair_idx,
                ws_a_val=ws_a_val,
                ws_b_val=ws_b_val,
                ws_a_edit=ws_a_edit,
                ws_b_edit=ws_b_edit,
            )
            if direction == "B2A":
                touched_r = insert_pos
            else:
                touched_r = self.row_pairs[pair_idx][0] or self.row_pairs[pair_idx][1]
            if touched_r is not None:
                self.touched_rows.add(int(touched_r))
            self._invalidate_only_diff_snapshot_cache()
            self._invalidate_render_cache()
            self.refresh(row_only=None, rescan=False)
            if anchor is not None:
                self._restore_view_anchor(anchor)
            self._update_cursor_lines()
            return True
        except Exception as e:
            _dlog(f"FAST_INSERT_REFRESH_FAILED sheet={self.sheet} pair_idx={pair_idx} err={e}")
            return False

    def _batch_insert_row_copy(
        self,
        run: list[tuple[int, int]],
        direction: str,
        suppress_refresh: bool,
        anchor,
    ) -> bool:
        if not run:
            return False
        if not self.app._has_active_mutation_owner(self):
            _dlog(
                f"mutation lease rejected sheet={self.sheet} "
                "action=批量插入行"
            )
            return False
        committed = False
        dst_val_inserted = False
        dst_edit_inserted = False
        base_val_inserted = False
        base_edit_inserted = False
        ws_dst_val = None
        ws_dst_edit = None
        ws_bv = None
        ws_be = None
        insert_pos = None
        base_insert_pos = None
        count = len(run)
        manual_a_cells_before = dict(getattr(self.app, "manual_a_cell_ops", {}) or {})
        manual_a_cache_before = dict(getattr(self.app, "manual_a_formula_cache_ops", {}) or {})
        manual_b_cells_before = dict(getattr(self.app, "manual_b_cell_ops", {}) or {})
        manual_b_cache_before = dict(getattr(self.app, "manual_b_formula_cache_ops", {}) or {})
        manual_a_row_ops_before = copy.deepcopy(
            list(getattr(self.app, "manual_a_row_ops", []) or [])
        )
        manual_b_row_ops_before = copy.deepcopy(
            list(getattr(self.app, "manual_b_row_ops", []) or [])
        )
        undo_len = len(getattr(self.app, "undo_stack", []) or [])
        undo_capture = getattr(self.app, "_undo_group_capture", None)
        undo_capture_len = (
            len(undo_capture.get("actions") or [])
            if undo_capture is not None
            else None
        )
        modified_a_before = bool(getattr(self.app, "modified_a", False))
        modified_b_before = bool(getattr(self.app, "modified_b", False))
        modified_sheets_a_before = set(getattr(self.app, "modified_sheets_a", set()) or set())
        modified_sheets_b_before = set(getattr(self.app, "modified_sheets_b", set()) or set())
        row_pairs_before = list(getattr(self, "row_pairs", []) or [])
        mine_to_base_before = dict(getattr(self, "mine_to_base_row", {}) or {})
        theirs_to_base_before = dict(getattr(self, "theirs_to_base_row", {}) or {})
        overrides_before = dict(getattr(self, "pair_base_row_override", {}) or {})
        touched_before = set(getattr(self, "touched_rows", set()) or set())
        max_row_before = getattr(self, "max_row", 1)
        cache_maps = (
            self.pair_text_a,
            self.pair_text_b,
            self.pair_text_base,
            self.pair_diff_cols,
            self.pair_base_diff_cols,
        )
        affected_pair_indices = [int(pair_idx) for pair_idx, _src_row in run]
        pair_cache_before = [
            {
                idx: (idx in cache_map, cache_map.get(idx))
                for idx in affected_pair_indices
            }
            for cache_map in cache_maps
        ]
        try:
            run = [(int(pair_idx), int(src_row)) for pair_idx, src_row in run]
            ws_a_val = self.app.ws_a_val(self.sheet)
            ws_b_val = self.app.ws_b_val(self.sheet)
            ws_a_edit = self.app.ws_a_edit(self.sheet)
            ws_b_edit = self.app.ws_b_edit(self.sheet)

            first_pair_idx = run[0][0]
            old_pairs = {
                pair_idx: self.row_pairs[pair_idx]
                for pair_idx, _src_row in run
                if 0 <= pair_idx < len(self.row_pairs)
            }
            old_base_rows = {
                pair_idx: self._base_row_for_pair(pair_idx, old_pairs.get(pair_idx))
                for pair_idx, _src_row in run
                if pair_idx in old_pairs
            }

            if direction in ("B2A", "BASE2A"):
                ws_dst_val = ws_a_val
                ws_dst_edit = ws_a_edit
                if direction == "BASE2A":
                    ws_src_val = self.app.ws_base_val(self.sheet)
                    ws_src_edit = self.app.ws_base_edit(self.sheet)
                else:
                    ws_src_val = ws_b_val
                    ws_src_edit = ws_b_edit
                insert_pos = self._find_row_insert_position(first_pair_idx, "A")
            else:
                ws_dst_val = ws_b_val
                ws_dst_edit = ws_b_edit
                ws_src_val = ws_a_val
                ws_src_edit = ws_a_edit
                insert_pos = self._find_row_insert_position(first_pair_idx, "B")

            ws_dst_val.insert_rows(idx=insert_pos, amount=count)
            dst_val_inserted = True
            ws_dst_edit.insert_rows(idx=insert_pos, amount=count)
            dst_edit_inserted = True

            if direction in ("B2A", "BASE2A"):
                self.app.transform_manual_formulas_for_row_action(
                    "A", self.sheet, insert_pos, count, insert=True
                )
                for op_map in (
                    self.app.manual_a_cell_ops,
                    self.app.manual_a_formula_cache_ops,
                ):
                    to_shift = {
                        k: v for k, v in op_map.items()
                        if k[0] == self.sheet and k[1] >= insert_pos
                    }
                    for k in to_shift:
                        del op_map[k]
                    for (s, r, c), v in to_shift.items():
                        op_map[(s, r + count, c)] = v
                self.app.record_manual_a_row_insert(
                    self.sheet,
                    insert_pos,
                    count,
                    source_side=("BASE" if direction == "BASE2A" else "B"),
                    source_rows=[src_row for _pair_idx, src_row in run],
                )
            else:
                self.app.transform_manual_formulas_for_row_action(
                    "B", self.sheet, insert_pos, count, insert=True
                )
                for op_map in (
                    self.app.manual_b_cell_ops,
                    self.app.manual_b_formula_cache_ops,
                ):
                    to_shift = {
                        key: value for key, value in op_map.items()
                        if key[0] == self.sheet and key[1] >= insert_pos
                    }
                    for key in to_shift:
                        del op_map[key]
                    for (sheet_name, row_idx, col_idx), value in to_shift.items():
                        op_map[(sheet_name, row_idx + count, col_idx)] = value
                self.app.record_manual_b_row_insert(
                    self.sheet,
                    insert_pos,
                    count,
                    source_side="A",
                    source_rows=[src_row for _pair_idx, src_row in run],
                )

            base_inserted = False
            # BASE insert position is computed in BASE coordinates (not mine's
            # insert_pos) so that non-identity mine/base alignment inserts the
            # blank base row at the right place; the row-model base shifts below
            # use the same base_insert_pos to stay consistent.
            base_insert_pos = insert_pos
            if direction == "B2A" and self._is_three_way_enabled():
                try:
                    base_insert_pos = self._find_base_row_insert_position(first_pair_idx)
                    ws_bv = self.app.ws_base_val(self.sheet)
                    ws_be = self.app.ws_base_edit(self.sheet)
                    if ws_bv is None or ws_be is None:
                        raise RuntimeError("BASE worksheet is unavailable")
                    ws_bv.insert_rows(idx=base_insert_pos, amount=count)
                    base_val_inserted = True
                    ws_be.insert_rows(idx=base_insert_pos, amount=count)
                    base_edit_inserted = True
                    base_inserted = True
                except Exception as _e_base_ins:
                    _dlog(f"batch base insert failed: sheet={self.sheet} pos={base_insert_pos} err={_e_base_ins}")
                    raise RuntimeError(f"向 BASE 批量插入对齐行失败：{_e_base_ins}") from _e_base_ins

            src_rows = [src_row for _pair_idx, src_row in run]
            max_col = max(1, ws_src_val.max_column or 1, ws_src_edit.max_column or 1)
            src_val_cache = _read_rows_into_cache(ws_src_val, src_rows, max_col)
            src_edit_cache = _read_rows_into_cache(ws_src_edit, src_rows, max_col)
            for offset, (_pair_idx, src_row) in enumerate(run):
                dst_row = insert_pos + offset
                row_val = _row_from_cache(src_val_cache, src_row, max_col)
                row_edit = _row_from_cache(src_edit_cache, src_row, max_col)
                for c in range(1, max_col + 1):
                    v_val = row_val[c - 1]
                    v_edit = row_edit[c - 1]
                    dst_cell_edit = ws_dst_edit.cell(row=dst_row, column=c)
                    new_edit = _copy_edit_value_for_destination(
                        v_val,
                        v_edit,
                        dst_cell_edit.value,
                        src_row=src_row,
                        src_col=c,
                        dst_row=dst_row,
                        dst_col=c,
                    )
                    ws_dst_val.cell(row=dst_row, column=c).value = v_val
                    _assign_edit_cell_value(dst_cell_edit, new_edit)
                    if direction in ("B2A", "BASE2A"):
                        self.app.record_manual_a_cell(self.sheet, dst_row, c, new_edit)
                        if _formula_text(new_edit):
                            self.app.record_manual_a_formula_cache(self.sheet, dst_row, c, v_val)
                    else:
                        self.app.record_manual_b_cell(self.sheet, dst_row, c, new_edit)
                        if _formula_text(new_edit):
                            self.app.record_manual_b_formula_cache(self.sheet, dst_row, c, v_val)
                _copy_row_metadata(ws_src_edit, ws_dst_edit, src_row, dst_row, max_col)
                _copy_row_metadata(ws_src_val, ws_dst_val, src_row, dst_row, max_col)

            if direction in ("B2A", "BASE2A"):
                self.app.modified_a = True
                self.app.modified_sheets_a.add(self.sheet)
                self.app.push_undo({
                    "sheet": self.sheet,
                    "target": "A_INSERT_ROW",
                    "row": insert_pos,
                    "base_row": base_insert_pos,
                    "count": count,
                    "base_inserted": base_inserted,
                    "manual_cells_before": manual_a_cells_before,
                    "manual_cache_before": manual_a_cache_before,
                    "manual_row_ops_before": manual_a_row_ops_before,
                    "modified_before": modified_a_before,
                    "modified_sheets_before": modified_sheets_a_before,
                })
            else:
                self.app.modified_b = True
                self.app.modified_sheets_b.add(self.sheet)
                self.app.push_undo({
                    "sheet": self.sheet,
                    "target": "B_INSERT_ROW",
                    "row": insert_pos,
                    "count": count,
                    "base_inserted": False,
                    "manual_cells_before": manual_b_cells_before,
                    "manual_cache_before": manual_b_cache_before,
                    "manual_row_ops_before": manual_b_row_ops_before,
                    "modified_before": modified_b_before,
                    "modified_sheets_before": modified_sheets_b_before,
                })

            amount = count
            run_pair_to_dst = {pair_idx: insert_pos + offset for offset, (pair_idx, _src_row) in enumerate(run)}
            updated_pairs: list[tuple[int | None, int | None]] = []
            for idx, (ra, rb) in enumerate(self.row_pairs):
                if direction in ("B2A", "BASE2A"):
                    ra = self._shift_row_number_for_insert(ra, insert_pos, amount)
                    if idx in run_pair_to_dst:
                        ra = run_pair_to_dst[idx]
                else:
                    rb = self._shift_row_number_for_insert(rb, insert_pos, amount)
                    if idx in run_pair_to_dst:
                        rb = run_pair_to_dst[idx]
                updated_pairs.append((ra, rb))
            self.row_pairs = updated_pairs
            self._rebuild_row_pair_lookup_maps()

            if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
                def _shift_base_row(base_row: int | None) -> int | None:
                    if not base_inserted:
                        return base_row
                    return self._shift_row_number_for_insert(base_row, base_insert_pos, amount)

                mine_map_old = dict(getattr(self, "mine_to_base_row", {}) or {})
                theirs_map_old = dict(getattr(self, "theirs_to_base_row", {}) or {})
                overrides_old = dict(getattr(self, "pair_base_row_override", {}) or {})

                if direction in ("B2A", "BASE2A"):
                    mine_map_new: dict[int, int] = {}
                    for ra, base_row in mine_map_old.items():
                        new_ra = self._shift_row_number_for_insert(ra, insert_pos, amount)
                        if new_ra is None:
                            continue
                        mine_map_new[int(new_ra)] = _shift_base_row(base_row)
                    for pair_idx, dst_row in run_pair_to_dst.items():
                        base_row = _shift_base_row(old_base_rows.get(pair_idx))
                        if base_row is not None:
                            mine_map_new[int(dst_row)] = int(base_row)
                    self.mine_to_base_row = mine_map_new

                    theirs_map_new: dict[int, int] = {}
                    for rb, base_row in theirs_map_old.items():
                        if rb is None:
                            continue
                        theirs_map_new[int(rb)] = _shift_base_row(base_row)
                    self.theirs_to_base_row = theirs_map_new
                else:
                    mine_map_new: dict[int, int] = {}
                    for ra, base_row in mine_map_old.items():
                        if ra is None:
                            continue
                        mine_map_new[int(ra)] = _shift_base_row(base_row)
                    self.mine_to_base_row = mine_map_new

                    theirs_map_new: dict[int, int] = {}
                    for rb, base_row in theirs_map_old.items():
                        new_rb = self._shift_row_number_for_insert(rb, insert_pos, amount)
                        if new_rb is None:
                            continue
                        theirs_map_new[int(new_rb)] = _shift_base_row(base_row)
                    for pair_idx, dst_row in run_pair_to_dst.items():
                        base_row = _shift_base_row(old_base_rows.get(pair_idx))
                        if base_row is not None:
                            theirs_map_new[int(dst_row)] = int(base_row)
                    self.theirs_to_base_row = theirs_map_new

                overrides_new: dict[int, int | None] = {}
                for idx, base_row in overrides_old.items():
                    overrides_new[int(idx)] = _shift_base_row(base_row)
                for pair_idx in run_pair_to_dst:
                    base_row = _shift_base_row(old_base_rows.get(pair_idx))
                    if base_row is not None:
                        overrides_new[int(pair_idx)] = int(base_row)
                    else:
                        overrides_new.pop(int(pair_idx), None)
                self.pair_base_row_override = overrides_new

            try:
                self.max_row = max(
                    int(self.max_row or 1),
                    int(getattr(self.app.ws_a_val(self.sheet), "max_row", 1) or 1),
                    int(getattr(self.app.ws_b_val(self.sheet), "max_row", 1) or 1),
                )
            except Exception:
                pass

            for offset, (pair_idx, src_row) in enumerate(run):
                touched_row = (
                    insert_pos + offset
                    if direction in ("B2A", "BASE2A")
                    else src_row
                )
                self.touched_rows.add(int(touched_row))
                self._prime_pair_cache_after_insert(
                    pair_idx=pair_idx,
                    ws_a_val=ws_a_val,
                    ws_b_val=ws_b_val,
                    ws_a_edit=ws_a_edit,
                    ws_b_edit=ws_b_edit,
                )

            self._mark_column_mapping_stale(
                "batch-row-insert",
                row_structure=True,
                edited_sides=("A", "BASE") if direction == "B2A" and base_inserted
                else (
                    ("A",)
                    if direction in ("B2A", "BASE2A")
                    else ("B",)
                ),
            )
            committed = True
            try:
                self.app.mark_difference_row_processed(self.sheet, int(insert_pos), True)
            except Exception:
                pass

            if not suppress_refresh:
                try:
                    self._invalidate_only_diff_snapshot_cache()
                    self._invalidate_render_cache()
                    self.refresh(row_only=None, rescan=False)
                    if anchor is not None:
                        self._restore_view_anchor(anchor)
                    self._update_cursor_lines()
                except Exception as refresh_error:
                    _dlog(
                        f"batch row insert committed but refresh failed: sheet={self.sheet} "
                        f"row={insert_pos} count={count} err={refresh_error}"
                    )
                    try:
                        messagebox.showwarning(
                            "行已插入",
                            "数据已成功批量插入，但界面刷新失败。请点击“刷新本Sheet”查看最新结果。\n"
                            f"详情：{refresh_error}",
                        )
                    except Exception:
                        pass
            return True
        except Exception as e:
            if not committed:
                try:
                    if base_edit_inserted and ws_be is not None and base_insert_pos is not None:
                        ws_be.delete_rows(int(base_insert_pos), int(count))
                    if base_val_inserted and ws_bv is not None and base_insert_pos is not None:
                        ws_bv.delete_rows(int(base_insert_pos), int(count))
                    if dst_edit_inserted and ws_dst_edit is not None and insert_pos is not None:
                        ws_dst_edit.delete_rows(int(insert_pos), int(count))
                    if dst_val_inserted and ws_dst_val is not None and insert_pos is not None:
                        ws_dst_val.delete_rows(int(insert_pos), int(count))
                    self.app.manual_a_cell_ops.clear()
                    self.app.manual_a_cell_ops.update(manual_a_cells_before)
                    self.app.manual_a_formula_cache_ops.clear()
                    self.app.manual_a_formula_cache_ops.update(manual_a_cache_before)
                    self.app.manual_b_cell_ops.clear()
                    self.app.manual_b_cell_ops.update(manual_b_cells_before)
                    self.app.manual_b_formula_cache_ops.clear()
                    self.app.manual_b_formula_cache_ops.update(manual_b_cache_before)
                    self.app.manual_a_row_ops[:] = manual_a_row_ops_before
                    self.app.manual_b_row_ops[:] = manual_b_row_ops_before
                    del self.app.undo_stack[undo_len:]
                    current_capture = getattr(self.app, "_undo_group_capture", None)
                    if (
                        current_capture is undo_capture
                        and undo_capture_len is not None
                    ):
                        del current_capture["actions"][undo_capture_len:]
                    self.app.modified_a = modified_a_before
                    self.app.modified_b = modified_b_before
                    self.app.modified_sheets_a.clear()
                    self.app.modified_sheets_a.update(modified_sheets_a_before)
                    self.app.modified_sheets_b.clear()
                    self.app.modified_sheets_b.update(modified_sheets_b_before)
                    self.row_pairs = row_pairs_before
                    self.mine_to_base_row = mine_to_base_before
                    self.theirs_to_base_row = theirs_to_base_before
                    self.pair_base_row_override = overrides_before
                    self.touched_rows = touched_before
                    self.max_row = max_row_before
                    self._rebuild_row_pair_lookup_maps()
                    for cache_map, saved_entries in zip(cache_maps, pair_cache_before):
                        for idx, (existed, value) in saved_entries.items():
                            if existed:
                                cache_map[idx] = value
                            else:
                                cache_map.pop(idx, None)
                    _dlog(
                        f"batch row insert rolled back: sheet={self.sheet} "
                        f"row={insert_pos} count={count}"
                    )
                except Exception as rollback_error:
                    _dlog(
                        f"CRITICAL batch row insert rollback failed: sheet={self.sheet} "
                        f"row={insert_pos} count={count} err={rollback_error}"
                    )
            messagebox.showerror("Error", f"批量插入行失败：\n{e}")
            return False

    def _batch_delete_rows_for_missing_source(
        self,
        run: list[tuple[int, int]],
        direction: str,
        suppress_refresh: bool,
        anchor,
    ) -> bool:
        """Accept source-side row deletion by deleting paired destination rows.

        ``B2A`` handles mine-only rows (theirs deleted them), ``BASE2A``
        handles Mine rows absent from Base, and ``A2B`` handles theirs-only
        rows. Pair indices remain stable until the post-action rescan.
        """
        if not run:
            return False
        if direction not in ("B2A", "BASE2A", "A2B"):
            return False
        if not self.app._has_active_mutation_owner(self):
            _dlog(
                f"mutation lease rejected sheet={self.sheet} "
                "action=批量删除行"
            )
            return False

        normalized = sorted(
            {(int(pair_idx), int(row_idx)) for pair_idx, row_idx in run},
            key=lambda item: item[1],
        )
        rows = [row_idx for _pair_idx, row_idx in normalized]
        start_row = rows[0]
        count = len(rows)
        if rows != list(range(start_row, start_row + count)):
            raise RuntimeError("删除区域中的目标行不连续，已停止操作。")
        end_row = start_row + count - 1
        target_side = "A" if direction in ("B2A", "BASE2A") else "B"
        target_pair_indices = {pair_idx for pair_idx, _row_idx in normalized}

        ws_val = self.app.ws_a_val(self.sheet) if target_side == "A" else self.app.ws_b_val(self.sheet)
        ws_edit = self.app.ws_a_edit(self.sheet) if target_side == "A" else self.app.ws_b_edit(self.sheet)
        edit_snapshot = _capture_worksheet_rows(ws_edit, start_row, count)
        val_snapshot = _capture_worksheet_rows(ws_val, start_row, count)

        if target_side == "A":
            manual_cells = self.app.manual_a_cell_ops
            manual_cache = self.app.manual_a_formula_cache_ops
            manual_row_ops = self.app.manual_a_row_ops
            modified_before = bool(self.app.modified_a)
            modified_sheets_before = set(self.app.modified_sheets_a)
        else:
            manual_cells = self.app.manual_b_cell_ops
            manual_cache = self.app.manual_b_formula_cache_ops
            manual_row_ops = self.app.manual_b_row_ops
            modified_before = bool(self.app.modified_b)
            modified_sheets_before = set(self.app.modified_sheets_b)

        manual_cells_before = dict(manual_cells)
        manual_cache_before = dict(manual_cache)
        manual_row_ops_before = copy.deepcopy(list(manual_row_ops))
        undo_capture = getattr(self.app, "_undo_group_capture", None)
        undo_capture_len = (
            len(undo_capture.get("actions") or [])
            if undo_capture is not None
            else None
        )
        row_pairs_before = list(self.row_pairs)
        mine_to_base_before = dict(getattr(self, "mine_to_base_row", {}) or {})
        theirs_to_base_before = dict(getattr(self, "theirs_to_base_row", {}) or {})
        overrides_before = dict(getattr(self, "pair_base_row_override", {}) or {})
        touched_before = set(self.touched_rows)
        max_row_before = int(self.max_row or 1)
        val_deleted = False
        edit_deleted = False
        committed = False

        try:
            self.app.transform_manual_formulas_for_row_action(
                target_side,
                self.sheet,
                start_row,
                count,
                insert=False,
            )
            ws_val.delete_rows(idx=start_row, amount=count)
            val_deleted = True
            ws_edit.delete_rows(idx=start_row, amount=count)
            edit_deleted = True

            for op_map in (manual_cells, manual_cache):
                to_drop = [
                    key for key in op_map
                    if key[0] == self.sheet and start_row <= int(key[1]) <= end_row
                ]
                for key in to_drop:
                    op_map.pop(key, None)
                to_shift = {
                    key: value for key, value in op_map.items()
                    if key[0] == self.sheet and int(key[1]) > end_row
                }
                for key in to_shift:
                    op_map.pop(key, None)
                for (sheet_name, row_idx, col_idx), value in to_shift.items():
                    op_map[(sheet_name, int(row_idx) - count, col_idx)] = value

            if target_side == "A":
                self.app.record_manual_a_row_delete(self.sheet, start_row, count)
                self.app.modified_a = True
                self.app.modified_sheets_a.add(self.sheet)
            else:
                self.app.record_manual_b_row_delete(self.sheet, start_row, count)
                self.app.modified_b = True
                self.app.modified_sheets_b.add(self.sheet)

            updated_pairs: list[tuple[int | None, int | None]] = []
            for pair_idx, (ra, rb) in enumerate(self.row_pairs):
                if target_side == "A":
                    if pair_idx in target_pair_indices:
                        ra = None
                    elif ra is not None and int(ra) > end_row:
                        ra = int(ra) - count
                    elif ra is not None and start_row <= int(ra) <= end_row:
                        ra = None
                else:
                    if pair_idx in target_pair_indices:
                        rb = None
                    elif rb is not None and int(rb) > end_row:
                        rb = int(rb) - count
                    elif rb is not None and start_row <= int(rb) <= end_row:
                        rb = None
                updated_pairs.append((ra, rb))
            self.row_pairs = updated_pairs
            self._rebuild_row_pair_lookup_maps()

            if target_side == "A":
                self.mine_to_base_row = {
                    (int(row_idx) - count if int(row_idx) > end_row else int(row_idx)): base_row
                    for row_idx, base_row in mine_to_base_before.items()
                    if not (start_row <= int(row_idx) <= end_row)
                }
            else:
                self.theirs_to_base_row = {
                    (int(row_idx) - count if int(row_idx) > end_row else int(row_idx)): base_row
                    for row_idx, base_row in theirs_to_base_before.items()
                    if not (start_row <= int(row_idx) <= end_row)
                }

            self.touched_rows = {
                (int(row_idx) - count if int(row_idx) > end_row else int(row_idx))
                for row_idx in touched_before
                if not (start_row <= int(row_idx) <= end_row)
            }
            self.max_row = max(
                1,
                int(getattr(self.app.ws_a_val(self.sheet), "max_row", 1) or 1),
                int(getattr(self.app.ws_b_val(self.sheet), "max_row", 1) or 1),
            )
            self.app.push_undo({
                "sheet": self.sheet,
                "target": f"{target_side}_DELETE_ROW",
                "row": start_row,
                "count": count,
                "edit_snapshot": edit_snapshot,
                "val_snapshot": val_snapshot,
                "manual_cells_before": manual_cells_before,
                "manual_cache_before": manual_cache_before,
                "manual_row_ops_before": manual_row_ops_before,
                "modified_before": modified_before,
                "modified_sheets_before": modified_sheets_before,
            })
            self._mark_column_mapping_stale(
                "row-delete",
                row_structure=True,
                edited_sides=(target_side,),
            )
            committed = True
            _dlog(
                f"DELETE_MISSING_SOURCE_ROWS sheet={self.sheet} dir={direction} "
                f"row={start_row} count={count}"
            )

            if not suppress_refresh:
                self._invalidate_only_diff_snapshot_cache()
                self._invalidate_render_cache()
                self.refresh(row_only=None, rescan=True)
                if anchor is not None:
                    self._restore_view_anchor(anchor)
                self._update_cursor_lines()
            return True
        except Exception as exc:
            if not committed:
                try:
                    if edit_deleted:
                        _restore_captured_worksheet_rows(ws_edit, edit_snapshot)
                    if val_deleted:
                        _restore_captured_worksheet_rows(ws_val, val_snapshot)
                    manual_cells.clear()
                    manual_cells.update(manual_cells_before)
                    manual_cache.clear()
                    manual_cache.update(manual_cache_before)
                    manual_row_ops[:] = manual_row_ops_before
                    current_capture = getattr(self.app, "_undo_group_capture", None)
                    if (
                        current_capture is undo_capture
                        and undo_capture_len is not None
                    ):
                        del current_capture["actions"][undo_capture_len:]
                    self.row_pairs = row_pairs_before
                    self.mine_to_base_row = mine_to_base_before
                    self.theirs_to_base_row = theirs_to_base_before
                    self.pair_base_row_override = overrides_before
                    self.touched_rows = touched_before
                    self.max_row = max_row_before
                    self._rebuild_row_pair_lookup_maps()
                    if target_side == "A":
                        self.app.modified_a = modified_before
                        self.app.modified_sheets_a.clear()
                        self.app.modified_sheets_a.update(modified_sheets_before)
                    else:
                        self.app.modified_b = modified_before
                        self.app.modified_sheets_b.clear()
                        self.app.modified_sheets_b.update(modified_sheets_before)
                except Exception as rollback_error:
                    _dlog(
                        f"CRITICAL row delete rollback failed: sheet={self.sheet} "
                        f"row={start_row} count={count} err={rollback_error}"
                    )
            messagebox.showerror("Error", f"删除行失败：\n{exc}")
            return False

    def _insert_row_copy(
        self,
        pair_idx: int,
        direction: str,
        src_row: int,
        suppress_refresh: bool,
        _undo_out,
        anchor,
    ) -> bool:
        """Insert a new row in the destination worksheet and copy src_row data into it.

        Called by _copy_selected_row when the destination side has no paired row:
        - direction="B2A": rb exists, ra is None → insert new row in A.
        - direction="A2B": ra exists, rb is None → insert new row in B.

        In 3-way mode, B2A also inserts an empty row in Base at the same position
        to keep A-Base row-number alignment intact.
        """
        committed = False
        dst_val_inserted = False
        dst_edit_inserted = False
        base_val_inserted = False
        base_edit_inserted = False
        ws_dst_val = None
        ws_dst_edit = None
        ws_bv = None
        ws_be = None
        insert_pos = None
        base_insert_pos = None
        manual_a_cells_before = dict(getattr(self.app, "manual_a_cell_ops", {}) or {})
        manual_a_cache_before = dict(getattr(self.app, "manual_a_formula_cache_ops", {}) or {})
        manual_b_cells_before = dict(getattr(self.app, "manual_b_cell_ops", {}) or {})
        manual_b_cache_before = dict(getattr(self.app, "manual_b_formula_cache_ops", {}) or {})
        manual_a_row_ops_before = copy.deepcopy(
            list(getattr(self.app, "manual_a_row_ops", []) or [])
        )
        manual_b_row_ops_before = copy.deepcopy(
            list(getattr(self.app, "manual_b_row_ops", []) or [])
        )
        undo_len = len(getattr(self.app, "undo_stack", []) or [])
        undo_capture = getattr(self.app, "_undo_group_capture", None)
        undo_capture_len = (
            len(undo_capture.get("actions") or [])
            if undo_capture is not None
            else None
        )
        modified_a_before = bool(getattr(self.app, "modified_a", False))
        modified_b_before = bool(getattr(self.app, "modified_b", False))
        modified_sheets_a_before = set(getattr(self.app, "modified_sheets_a", set()) or set())
        modified_sheets_b_before = set(getattr(self.app, "modified_sheets_b", set()) or set())
        try:
            ws_a_val = self.app.ws_a_val(self.sheet)
            ws_b_val = self.app.ws_b_val(self.sheet)
            ws_a_edit = self.app.ws_a_edit(self.sheet)
            ws_b_edit = self.app.ws_b_edit(self.sheet)
            old_pair = self.row_pairs[pair_idx] if 0 <= int(pair_idx) < len(self.row_pairs) else None

            if direction in ("B2A", "BASE2A"):
                ws_dst_val = ws_a_val
                ws_dst_edit = ws_a_edit
                if direction == "BASE2A":
                    ws_src_val = self.app.ws_base_val(self.sheet)
                    ws_src_edit = self.app.ws_base_edit(self.sheet)
                else:
                    ws_src_val = ws_b_val
                    ws_src_edit = ws_b_edit
                insert_pos = self._find_row_insert_position(pair_idx, "A")
            else:  # A2B
                ws_dst_val = ws_b_val
                ws_dst_edit = ws_b_edit
                ws_src_val = ws_a_val
                ws_src_edit = ws_a_edit
                insert_pos = self._find_row_insert_position(pair_idx, "B")

            # Insert blank row in destination worksheet.
            ws_dst_val.insert_rows(idx=insert_pos)
            dst_val_inserted = True
            ws_dst_edit.insert_rows(idx=insert_pos)
            dst_edit_inserted = True

            # When inserting into A, shift any existing manual-edit records whose
            # row numbers are >= insert_pos (they moved up by one in the worksheet).
            if direction in ("B2A", "BASE2A"):
                self.app.transform_manual_formulas_for_row_action(
                    "A", self.sheet, insert_pos, 1, insert=True
                )
                for op_map in (
                    self.app.manual_a_cell_ops,
                    self.app.manual_a_formula_cache_ops,
                ):
                    to_shift = {k: v for k, v in op_map.items()
                                if k[0] == self.sheet and k[1] >= insert_pos}
                    for k in to_shift:
                        del op_map[k]
                    for (s, r, c), v in to_shift.items():
                        op_map[(s, r + 1, c)] = v
                self.app.record_manual_a_row_insert(
                    self.sheet,
                    insert_pos,
                    1,
                    source_side=("BASE" if direction == "BASE2A" else "B"),
                    source_rows=[src_row],
                )
            else:
                self.app.transform_manual_formulas_for_row_action(
                    "B", self.sheet, insert_pos, 1, insert=True
                )
                for op_map in (
                    self.app.manual_b_cell_ops,
                    self.app.manual_b_formula_cache_ops,
                ):
                    to_shift = {
                        key: value for key, value in op_map.items()
                        if key[0] == self.sheet and key[1] >= insert_pos
                    }
                    for key in to_shift:
                        del op_map[key]
                    for (sheet_name, row_idx, col_idx), value in to_shift.items():
                        op_map[(sheet_name, row_idx + 1, col_idx)] = value
                self.app.record_manual_b_row_insert(
                    self.sheet,
                    insert_pos,
                    1,
                    source_side="A",
                    source_rows=[src_row],
                )

            # In 3-way mode, inserting into A also inserts an empty row in Base.
            # The base position is mapped via base coordinates (not mine's
            # insert_pos) so non-identity mine/base alignment stays correct; the
            # row-model update shifts base rows using the same base_insert_pos.
            base_inserted = False
            base_insert_pos = insert_pos
            if direction == "B2A" and self._is_three_way_enabled():
                try:
                    base_insert_pos = self._find_base_row_insert_position(pair_idx)
                    ws_bv = self.app.ws_base_val(self.sheet)
                    ws_be = self.app.ws_base_edit(self.sheet)
                    if ws_bv is None or ws_be is None:
                        raise RuntimeError("BASE worksheet is unavailable")
                    ws_bv.insert_rows(idx=base_insert_pos)
                    base_val_inserted = True
                    ws_be.insert_rows(idx=base_insert_pos)
                    base_edit_inserted = True
                    base_inserted = True
                except Exception as _e_base_ins:
                    _dlog(f"base insert failed: sheet={self.sheet} pos={base_insert_pos} err={_e_base_ins}")
                    raise RuntimeError(f"向 BASE 插入对齐行失败：{_e_base_ins}") from _e_base_ins

            # Copy cell values from src_row into the newly inserted row.
            max_col = max(1, ws_src_val.max_column or 1, ws_src_edit.max_column or 1)
            for c in range(1, max_col + 1):
                v_val = ws_src_val.cell(row=src_row, column=c).value
                v_edit = ws_src_edit.cell(row=src_row, column=c).value
                dst_cell_edit = ws_dst_edit.cell(row=insert_pos, column=c)
                new_edit = _copy_edit_value_for_destination(
                    v_val,
                    v_edit,
                    dst_cell_edit.value,
                    src_row=src_row,
                    src_col=c,
                    dst_row=insert_pos,
                    dst_col=c,
                )
                ws_dst_val.cell(row=insert_pos, column=c).value = v_val
                _assign_edit_cell_value(dst_cell_edit, new_edit)
                if direction in ("B2A", "BASE2A"):
                    self.app.record_manual_a_cell(self.sheet, insert_pos, c, new_edit)
                    if _formula_text(new_edit):
                        self.app.record_manual_a_formula_cache(self.sheet, insert_pos, c, v_val)
                else:
                    self.app.record_manual_b_cell(self.sheet, insert_pos, c, new_edit)
                    if _formula_text(new_edit):
                        self.app.record_manual_b_formula_cache(self.sheet, insert_pos, c, v_val)

            _copy_row_metadata(ws_src_edit, ws_dst_edit, src_row, insert_pos, max_col)
            _copy_row_metadata(ws_src_val, ws_dst_val, src_row, insert_pos, max_col)

            if direction in ("B2A", "BASE2A"):
                self.app.modified_a = True
                self.app.modified_sheets_a.add(self.sheet)
            else:
                self.app.modified_b = True
                self.app.modified_sheets_b.add(self.sheet)

            target_tag = (
                "A_INSERT_ROW"
                if direction in ("B2A", "BASE2A")
                else "B_INSERT_ROW"
            )
            self.app.push_undo({
                "sheet": self.sheet,
                "target": target_tag,
                "row": insert_pos,
                "base_row": base_insert_pos,
                "count": 1,
                "base_inserted": base_inserted,
                "manual_cells_before": (
                    manual_a_cells_before
                    if direction in ("B2A", "BASE2A")
                    else manual_b_cells_before
                ),
                "manual_cache_before": (
                    manual_a_cache_before
                    if direction in ("B2A", "BASE2A")
                    else manual_b_cache_before
                ),
                "manual_row_ops_before": (
                    manual_a_row_ops_before
                    if direction in ("B2A", "BASE2A")
                    else manual_b_row_ops_before
                ),
                "modified_before": (
                    modified_a_before
                    if direction in ("B2A", "BASE2A")
                    else modified_b_before
                ),
                "modified_sheets_before": (
                    modified_sheets_a_before
                    if direction in ("B2A", "BASE2A")
                    else modified_sheets_b_before
                ),
            })
            self._mark_column_mapping_stale(
                "row-insert",
                row_structure=True,
                edited_sides=("A", "BASE") if direction == "B2A" and base_inserted
                else (
                    ("A",)
                    if direction in ("B2A", "BASE2A")
                    else ("B",)
                ),
            )
            committed = True

            if not suppress_refresh:
                try:
                    fast_done = self._try_fast_refresh_after_row_insert(
                        pair_idx=pair_idx,
                        direction=direction,
                        insert_pos=insert_pos,
                        base_insert_pos=base_insert_pos,
                        old_pair=old_pair,
                        base_inserted=base_inserted,
                        suppress_refresh=suppress_refresh,
                        anchor=anchor,
                        ws_a_val=ws_a_val,
                        ws_b_val=ws_b_val,
                        ws_a_edit=ws_a_edit,
                        ws_b_edit=ws_b_edit,
                    )
                    if not fast_done:
                        self._invalidate_only_diff_snapshot_cache()
                        self._invalidate_render_cache()
                        self.refresh(row_only=None, rescan=True)
                        if anchor is not None:
                            self._restore_view_anchor(anchor)
                        self._update_cursor_lines()
                except Exception as refresh_error:
                    _dlog(
                        f"row insert committed but refresh failed: sheet={self.sheet} "
                        f"row={insert_pos} err={refresh_error}"
                    )
                    try:
                        messagebox.showwarning(
                            "行已插入",
                            "数据已成功插入，但界面刷新失败。请点击“刷新本Sheet”查看最新结果。\n"
                            f"详情：{refresh_error}",
                        )
                    except Exception:
                        pass
            return True
        except Exception as e:
            if not committed:
                try:
                    if base_edit_inserted and ws_be is not None and base_insert_pos is not None:
                        ws_be.delete_rows(int(base_insert_pos), 1)
                    if base_val_inserted and ws_bv is not None and base_insert_pos is not None:
                        ws_bv.delete_rows(int(base_insert_pos), 1)
                    if dst_edit_inserted and ws_dst_edit is not None and insert_pos is not None:
                        ws_dst_edit.delete_rows(int(insert_pos), 1)
                    if dst_val_inserted and ws_dst_val is not None and insert_pos is not None:
                        ws_dst_val.delete_rows(int(insert_pos), 1)
                    self.app.manual_a_cell_ops.clear()
                    self.app.manual_a_cell_ops.update(manual_a_cells_before)
                    self.app.manual_a_formula_cache_ops.clear()
                    self.app.manual_a_formula_cache_ops.update(manual_a_cache_before)
                    self.app.manual_b_cell_ops.clear()
                    self.app.manual_b_cell_ops.update(manual_b_cells_before)
                    self.app.manual_b_formula_cache_ops.clear()
                    self.app.manual_b_formula_cache_ops.update(manual_b_cache_before)
                    self.app.manual_a_row_ops[:] = manual_a_row_ops_before
                    self.app.manual_b_row_ops[:] = manual_b_row_ops_before
                    del self.app.undo_stack[undo_len:]
                    current_capture = getattr(self.app, "_undo_group_capture", None)
                    if (
                        current_capture is undo_capture
                        and undo_capture_len is not None
                    ):
                        del current_capture["actions"][undo_capture_len:]
                    self.app.modified_a = modified_a_before
                    self.app.modified_b = modified_b_before
                    self.app.modified_sheets_a.clear()
                    self.app.modified_sheets_a.update(modified_sheets_a_before)
                    self.app.modified_sheets_b.clear()
                    self.app.modified_sheets_b.update(modified_sheets_b_before)
                    _dlog(f"row insert rolled back: sheet={self.sheet} row={insert_pos}")
                except Exception as rollback_error:
                    _dlog(
                        f"CRITICAL row insert rollback failed: sheet={self.sheet} "
                        f"row={insert_pos} err={rollback_error}"
                    )
            messagebox.showerror("Error", f"插入行失败：\n{e}")
            return False

    def _difference_item_matches_pair(
        self,
        item_id: str | None,
        pair_idx: int | None,
        columns: set[int] | None = None,
    ) -> bool:
        """Validate a browser selection before using it as a retain alias.

        The browser selection can outlive a main-grid row change while a
        cache refresh is still in flight.  Treat its ID as authoritative only
        when the current DifferenceIndex contains that exact item, its Sheet
        and aligned pair match, and a region's requested logical columns
        contain the item.  Otherwise callers must use the current pair/row
        fallback, which returns IDs suitable for undo.
        """
        try:
            pair_idx = self._normalize_pair_idx(pair_idx)
            item_key = str(item_id or "")
        except Exception:
            return False
        if pair_idx is None or not item_key:
            return False

        browser = getattr(self.app, "_diff_browser", None)
        index = getattr(browser, "index", None) if browser is not None else None
        if index is not None and callable(getattr(index, "all", None)):
            # A live index is the source of truth.  Do not fall back to a
            # stale app snapshot when it cannot confirm this ID.
            items = tuple(index.all())
        else:
            items = tuple(getattr(self.app, "difference_items", ()) or ())
        item = next(
            (candidate for candidate in items if str(getattr(candidate, "id", "")) == item_key),
            None,
        )
        if item is None or str(getattr(item, "sheet", "")) != str(self.sheet):
            return False

        pair_match = re.search(r":pair:(-?\d+):", item_key)
        if pair_match is not None:
            try:
                if int(pair_match.group(1)) != int(pair_idx):
                    return False
            except (TypeError, ValueError):
                return False
        else:
            # Legacy row IDs have no pair token.  Confirm their physical row
            # belongs to this aligned pair before accepting the alias.
            try:
                pair = self.row_pairs[int(pair_idx)]
                row_candidates = {
                    int(value)
                    for value in tuple(pair or ())
                    if value is not None
                }
                base_row = self._base_row_for_pair(int(pair_idx), pair)
                if base_row is not None:
                    row_candidates.add(int(base_row))
                if getattr(item, "row", None) is None or int(item.row) not in row_candidates:
                    return False
            except (AttributeError, IndexError, TypeError, ValueError):
                return False

        if columns is not None:
            try:
                allowed = {int(value) for value in columns}
                item_col = getattr(item, "column", None)
                if item_col is None:
                    if -1 not in allowed:
                        return False
                elif int(item_col) not in allowed:
                    return False
            except (TypeError, ValueError):
                return False
        return True

    def _copy_selected_row(
        self,
        direction: str,
        row_header: bool = False,
        override_pair_idx: int | None = None,
        override_cols: set[int] | None = None,
        suppress_refresh: bool = False,
        _undo_out: list | None = None,
        raise_on_error: bool = False,
        _difference_ids_out: list[str] | None = None,
    ) -> bool:
        if not self._guard_copy_direction(direction, "行覆盖"):
            return False
        # Region actions acquire readiness at their public entry and then reuse
        # this primitive while the app advertises BUSY.
        if suppress_refresh:
            if not self.app._has_active_mutation_owner(self):
                _dlog(
                    f"mutation lease rejected sheet={self.sheet} "
                    "action=批量行覆盖"
                )
                return False
        elif not self._guard_mutation_ready("行覆盖"):
            return False
        # Value workbooks are opened read-only for fast startup.  Upgrade them
        # before capturing any worksheet references because the upgrade swaps
        # the workbook objects; otherwise local ReadOnlyWorksheet references
        # would be closed when the editable gate runs below.
        self.app._ensure_edit_loaded()
        self.app._ensure_value_workbooks_regular()
        t0 = datetime.now()
        formula_skip_before = int(getattr(self, "_formula_copy_skips_pending", 0))
        interactive_busy = not suppress_refresh
        previous_bg_suppression = bool(getattr(self, "_suppress_bg_apply", False))
        begin_interactive = getattr(self.app, "_begin_interactive_action", None)
        end_interactive = getattr(self.app, "_end_interactive_action", None)
        if callable(begin_interactive):
            begin_interactive(self)
        self._suppress_bg_apply = True
        if interactive_busy:
            action_text = self._format_direction_action(direction, "row")
            if action_text:
                action_text = f"正在{action_text}..."
            else:
                action_text = "正在处理行操作..."
            try:
                self.info.configure(text=action_text)
                self.root.configure(cursor="watch")
                self.root.update_idletasks()
            except Exception:
                pass
        try:
            if self._is_missing_sheet_view():
                self._copy_missing_sheet(direction, _guarded=True)
                return True
            anchor = None if suppress_refresh else self._capture_view_anchor()
            resolved_only = False
            changed = False
            # use last selected excel row (set on click); fallback to cursor line
            pair_idx = override_pair_idx if override_pair_idx is not None else self.selected_pair_idx
            if pair_idx is None:
                widget = self.left
                try:
                    focus = self.root.focus_get()
                    if focus == self.right:
                        widget = self.right
                except Exception:
                    pass
                try:
                    line = int((widget.index("insert").split(".")[0]))
                except Exception:
                    line = 1
                if not (1 <= line <= len(self.display_rows)):
                    return False
                pair_idx = self.display_rows[line - 1]
            pair = self.row_pairs[pair_idx] if pair_idx is not None and pair_idx < len(self.row_pairs) else None
            ra = self._row_for_side(pair, "A")
            rb = self._row_for_side(pair, "B")
            if direction == "A2B":
                if ra is None:
                    if rb is None:
                        return False
                    return self._batch_delete_rows_for_missing_source(
                        [(pair_idx, rb)],
                        direction="A2B",
                        suppress_refresh=suppress_refresh,
                        anchor=anchor,
                    )
                src_r = ra
                dst_r = rb  # may be None if A-only row; insert path handled in second block
            elif direction == "MINE2A":
                if ra is None and rb is None:
                    return False
                src_r = ra if ra is not None else rb
                dst_r = ra if ra is not None else rb
            elif direction == "BASE2A":
                src_r = self._base_row_for_pair(pair_idx, pair)
                if ra is None and src_r is None:
                    return False
                dst_r = ra
            else:
                if rb is None:
                    if ra is None:
                        return False
                    return self._batch_delete_rows_for_missing_source(
                        [(pair_idx, ra)],
                        direction="B2A",
                        suppress_refresh=suppress_refresh,
                        anchor=anchor,
                    )
                src_r = rb
                dst_r = ra  # may be None if B-only row; insert path handled in second block
            ws_a_val = self.app.ws_a_val(self.sheet)
            ws_b_val = self.app.ws_b_val(self.sheet)
            ws_base_val = self.app.ws_base_val(self.sheet) if getattr(self.app, "has_base", False) else None
            ws_a_edit = self.app.ws_a_edit(self.sheet)
            ws_b_edit = self.app.ws_b_edit(self.sheet)
            ws_base_edit = self.app.ws_base_edit(self.sheet) if getattr(self.app, "has_base", False) else None

            # Default row action overwrites full row range.
            full_max_col = max(
                self.max_col,
                ws_a_val.max_column or 1,
                ws_b_val.max_column or 1,
                (ws_base_val.max_column or 1) if ws_base_val is not None else 1,
                ws_a_edit.max_column or 1,
                ws_b_edit.max_column or 1,
                (ws_base_edit.max_column or 1) if ws_base_edit is not None else 1,
            )
            action_direction = direction
            cols = (
                set(range(1, self._logical_slot_count() + 1))
                if override_cols is None else set(override_cols)
            )

            # 3-way row-header behavior:
            # - Base row number: apply only diff cells to mine
            # - Theirs row number: apply full row to mine
            if row_header and self._is_three_way_enabled() and direction == "BASE2A":
                # Use base-vs-mine diffs for base-row action (not mine-vs-theirs).
                cols = set(self.pair_base_diff_cols.get(pair_idx, set()))

            # Recompute src/dst based on final action direction.
            if action_direction == "A2B":
                if ra is None:
                    return False
                if rb is None:
                    # A-only row: insert a new row in B at the corresponding position.
                    return self._insert_row_copy(pair_idx, "A2B", ra, suppress_refresh, _undo_out, anchor)
                src_r = ra
                dst_r = rb
            elif action_direction == "MINE2A":
                if ra is None and rb is None:
                    return False
                src_r = ra if ra is not None else rb
                dst_r = ra if ra is not None else rb
            elif action_direction == "BASE2A":
                base_row = self._base_row_for_pair(pair_idx, pair)
                if ra is None and base_row is None:
                    return False
                if ra is None:
                    return self._batch_insert_row_copy(
                        [(pair_idx, base_row)],
                        direction="BASE2A",
                        suppress_refresh=suppress_refresh,
                        anchor=anchor,
                    )
                if base_row is None:
                    return self._batch_delete_rows_for_missing_source(
                        [(pair_idx, ra)],
                        direction="BASE2A",
                        suppress_refresh=suppress_refresh,
                        anchor=anchor,
                    )
                src_r = base_row
                dst_r = ra
            else:
                if rb is None:
                    return False
                if ra is None:
                    # B-only row: insert a new row in A at the corresponding position.
                    return self._insert_row_copy(pair_idx, "B2A", rb, suppress_refresh, _undo_out, anchor)
                src_r = rb
                dst_r = ra

            if action_direction in ("A2B", "B2A", "BASE2A"):
                cols = self._filter_row_action_unresolved_blank_noops(
                    action_direction,
                    cols,
                    int(src_r),
                    int(dst_r),
                )

            # Merge conflict mode:
            # - "A2B" means keep mine, just mark resolved.
            # - "B2A" means apply theirs to mine, then mark resolved.
            if getattr(self.app, "merge_conflict_mode", False):
                rows = self.app.merge_conflict_cells_by_sheet.get(self.sheet) if getattr(self.app, "merge_conflict_cells_by_sheet", None) else None
                conflict_row = ra or rb
                if rows and conflict_row in rows:
                    cols = set(rows.get(conflict_row, set())) if action_direction == "A2B" else cols
                if action_direction == "A2B":
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_row(
                        conflict_row,
                        cols,
                        refresh=not suppress_refresh,
                        raise_on_error=raise_on_error,
                    )
                    resolved_only = True
                    changed = True
                elif action_direction == "MINE2A":
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_row(
                        conflict_row,
                        cols,
                        refresh=not suppress_refresh,
                        raise_on_error=raise_on_error,
                    )
                    resolved_only = True
                    changed = True

            if not cols:
                return False

            if not resolved_only and action_direction in ("A2B", "B2A", "BASE2A"):
                if action_direction == "A2B":
                    src_edit_ws, src_val_ws, dst_edit_ws = ws_a_edit, ws_a_val, ws_b_edit
                elif action_direction == "B2A":
                    src_edit_ws, src_val_ws, dst_edit_ws = ws_b_edit, ws_b_val, ws_a_edit
                else:
                    src_edit_ws, src_val_ws, dst_edit_ws = ws_base_edit, ws_base_val, ws_a_edit
                if src_r is not None and src_edit_ws is not None:
                    for c in cols:
                        if int(c) <= 0:
                            continue
                        physical_cols = self._action_physical_columns(action_direction, c)
                        if physical_cols is None:
                            continue
                        src_col, dst_col = physical_cols
                        _copy_edit_value_for_destination(
                            src_val_ws.cell(row=src_r, column=src_col).value if src_val_ws is not None else None,
                            src_edit_ws.cell(row=src_r, column=src_col).value,
                            dst_edit_ws.cell(row=dst_r, column=dst_col).value,
                            src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                        )

            if action_direction == "A2B":
                if not resolved_only:
                    undo_cells = []
                    for c in cols:
                        if int(c) <= 0:
                            continue
                        physical_cols = self._action_physical_columns(action_direction, c)
                        if physical_cols is None:
                            continue
                        src_col, dst_col = physical_cols
                        old_edit = ws_b_edit.cell(row=dst_r, column=dst_col).value
                        old_val = ws_b_val.cell(row=dst_r, column=dst_col).value
                        v_edit = ws_a_edit.cell(row=src_r, column=src_col).value
                        v_val = ws_a_val.cell(row=src_r, column=src_col).value
                        new_edit = _copy_edit_value_for_destination(
                            v_val, v_edit, old_edit,
                            src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                        )
                        formula_mode = self._same_formula_copy_mode(
                            new_edit, old_edit, v_val, old_val
                        )
                        if formula_mode == "noop":
                            continue
                        if formula_mode == "cache":
                            ws_b_val.cell(row=dst_r, column=dst_col).value = v_val
                            self.app.record_manual_b_formula_cache(self.sheet, dst_r, dst_col, v_val)
                            undo_cells.append((dst_r, dst_col, old_edit, old_val))
                            continue
                        self.app.clear_manual_b_formula_cache(self.sheet, dst_r, dst_col)
                        _assign_edit_cell_value(
                            ws_b_edit.cell(row=dst_r, column=dst_col),
                            new_edit,
                        )
                        self.app.record_manual_b_cell(self.sheet, dst_r, dst_col, new_edit)
                        ws_b_val.cell(row=dst_r, column=dst_col).value = v_val
                        undo_cells.append((dst_r, dst_col, old_edit, old_val))
                    self.app.modified_b = True
                    self.app.modified_sheets_b.add(self.sheet)
                    if undo_cells:
                        changed = True
                        if _undo_out is not None:
                            _undo_out.extend(undo_cells)
                        else:
                            self.app.push_undo({"sheet": self.sheet, "target": "B", "cells": undo_cells})
            elif action_direction == "MINE2A":
                # Keep Mine/Target Working as-is.  This is an explicit,
                # no-write acknowledgement: retain the selected DifferenceItem
                # as processed (and resolve conflict metadata when the legacy
                # conflict mode is active).
                marked_ids = tuple()
                try:
                    marker = getattr(self.app, "mark_difference_pair_processed", None)
                    if callable(marker):
                        marked_ids = marker(
                            self.sheet,
                            int(pair_idx),
                            cols if override_cols is not None else None,
                            True,
                        )
                    selected_id = getattr(self, "_selected_difference_item_id", None)
                    selected_is_current = self._difference_item_matches_pair(
                        selected_id,
                        pair_idx,
                        cols if override_cols is not None else None,
                    )
                    if not marked_ids and selected_is_current:
                        self.app.mark_difference_processed(selected_id, True)
                        marked_ids = (str(selected_id),)
                    if not marked_ids and (ra is not None or rb is not None):
                        row_marked_ids = self.app.mark_difference_row_processed(
                            self.sheet, int(ra or rb), True
                        )
                        # Pair IDs may be unavailable for a legacy/cache
                        # snapshot.  The row fallback still marks real
                        # DifferenceItems; carry those IDs into the caller's
                        # undo record and region accumulator.
                        marked_ids = tuple(
                            dict.fromkeys(
                                str(item_id)
                                for item_id in (marked_ids or ())
                                + tuple(row_marked_ids or ())
                                if item_id
                            )
                        )
                    if _difference_ids_out is not None:
                        _difference_ids_out.extend(
                            item_id
                            for item_id in marked_ids
                            if item_id not in _difference_ids_out
                        )
                except Exception:
                    pass
                if marked_ids and not suppress_refresh:
                    self.app.push_undo({
                        "kind": "difference_state",
                        "sheet": self.sheet,
                        "item_ids": tuple(marked_ids),
                    })
                try:
                    self.info.configure(
                        text=(
                            f"已保留{self.role_presentation.left}，未写入任何数据；"
                            f"已标记 {len(marked_ids) or 1} 项为已处理。"
                        )
                    )
                except Exception:
                    pass
                if not suppress_refresh:
                    try:
                        self.app.refresh_difference_browser()
                    except Exception:
                        pass
                return bool(changed or marked_ids or ra is not None or rb is not None)
            elif action_direction == "B2A":
                undo_cells = []
                applied_cols = set()
                for c in cols:
                    if int(c) <= 0:
                        continue
                    physical_cols = self._action_physical_columns(action_direction, c)
                    if physical_cols is None:
                        continue
                    src_col, dst_col = physical_cols
                    old_edit = ws_a_edit.cell(row=dst_r, column=dst_col).value
                    old_val = ws_a_val.cell(row=dst_r, column=dst_col).value
                    v_edit = ws_b_edit.cell(row=src_r, column=src_col).value
                    v_val = ws_b_val.cell(row=src_r, column=src_col).value
                    new_edit = _copy_edit_value_for_destination(
                        v_val, v_edit, old_edit,
                        src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                    )
                    formula_mode = self._same_formula_copy_mode(
                        new_edit, old_edit, v_val, old_val
                    )
                    if formula_mode == "noop":
                        continue
                    if formula_mode == "cache":
                        ws_a_val.cell(row=dst_r, column=dst_col).value = v_val
                        self.app.record_manual_a_formula_cache(self.sheet, dst_r, dst_col, v_val)
                        undo_cells.append((dst_r, dst_col, old_edit, old_val))
                        applied_cols.add(c)
                        continue
                    _assign_edit_cell_value(ws_a_edit.cell(row=dst_r, column=dst_col), new_edit)
                    ws_a_val.cell(row=dst_r, column=dst_col).value = v_val
                    self.app.record_manual_a_cell(self.sheet, dst_r, dst_col, new_edit)
                    undo_cells.append((dst_r, dst_col, old_edit, old_val))
                    applied_cols.add(c)
                if undo_cells:
                    self.app.modified_a = True
                    self.app.modified_sheets_a.add(self.sheet)
                    changed = True
                    if _undo_out is not None:
                        _undo_out.extend(undo_cells)
                    else:
                        self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": undo_cells})
                # In conflict mode, B2A applies theirs; mark conflict resolved.
                if getattr(self.app, "merge_conflict_mode", False) and applied_cols:
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_row(
                        conflict_row,
                        applied_cols,
                        refresh=not suppress_refresh,
                        raise_on_error=raise_on_error,
                    )
                    resolved_only = True
                    changed = True
            else:
                undo_cells = []
                applied_cols = set()
                if ws_base_edit is None or ws_base_val is None:
                    return False
                for c in cols:
                    if int(c) <= 0:
                        continue
                    physical_cols = self._action_physical_columns(action_direction, c)
                    if physical_cols is None:
                        continue
                    src_col, dst_col = physical_cols
                    old_edit = ws_a_edit.cell(row=dst_r, column=dst_col).value
                    old_val = ws_a_val.cell(row=dst_r, column=dst_col).value
                    if src_r is None:
                        v_edit = None
                        v_val = None
                    else:
                        v_edit = ws_base_edit.cell(row=src_r, column=src_col).value
                        v_val = ws_base_val.cell(row=src_r, column=src_col).value
                    new_edit = (
                        _copy_edit_value_for_destination(
                            v_val, v_edit, old_edit,
                            src_row=src_r, src_col=src_col, dst_row=dst_r, dst_col=dst_col,
                        )
                        if src_r is not None else None
                    )
                    formula_mode = self._same_formula_copy_mode(
                        new_edit, old_edit, v_val, old_val
                    )
                    if formula_mode == "noop":
                        continue
                    if formula_mode == "cache":
                        ws_a_val.cell(row=dst_r, column=dst_col).value = v_val
                        self.app.record_manual_a_formula_cache(self.sheet, dst_r, dst_col, v_val)
                        undo_cells.append((dst_r, dst_col, old_edit, old_val))
                        applied_cols.add(c)
                        continue
                    _assign_edit_cell_value(ws_a_edit.cell(row=dst_r, column=dst_col), new_edit)
                    ws_a_val.cell(row=dst_r, column=dst_col).value = v_val
                    self.app.record_manual_a_cell(self.sheet, dst_r, dst_col, new_edit)
                    undo_cells.append((dst_r, dst_col, old_edit, old_val))
                    applied_cols.add(c)
                if undo_cells:
                    self.app.modified_a = True
                    self.app.modified_sheets_a.add(self.sheet)
                    changed = True
                    if _undo_out is not None:
                        _undo_out.extend(undo_cells)
                    else:
                        self.app.push_undo({"sheet": self.sheet, "target": "A", "cells": undo_cells})
                if getattr(self.app, "merge_conflict_mode", False) and applied_cols:
                    self.app.user_touched_conflicts = True
                    self._resolve_conflict_row(
                        dst_r,
                        applied_cols,
                        refresh=not suppress_refresh,
                        raise_on_error=raise_on_error,
                    )
                    resolved_only = True
                    changed = True

            if not changed:
                formula_skipped = int(getattr(self, "_formula_copy_skips_pending", 0)) - formula_skip_before
                if formula_skipped > 0 and not suppress_refresh:
                    self._show_formula_copy_skip_notice(formula_skipped)
                return False

            # Mark as touched: keep row visible in "只看差异" even if diffs are resolved.
            touched_r = ra or rb
            if touched_r is not None:
                self.touched_rows.add(touched_r)
            if not suppress_refresh:
                self._mark_column_mapping_stale(
                    "row-overwrite",
                    edited_sides=("B",) if action_direction == "A2B" else ("A",),
                )
                self._invalidate_only_diff_snapshot_cache()
                self._invalidate_render_cache()
                # Minimize flicker: use row-only incremental refresh after overwrite.
                if bool(self.only_diff_var.get()) and self.snapshot_only_diff:
                    self._recalc_row_diff_and_update(dst_r)
                self.refresh(row_only=dst_r, rescan=False)
                self._restore_view_anchor(anchor)
                self._update_cursor_lines()
                formula_skipped = int(getattr(self, "_formula_copy_skips_pending", 0)) - formula_skip_before
                if formula_skipped > 0:
                    self._show_formula_copy_skip_notice(formula_skipped)
            return True
        except Exception as e:
            _dlog(
                f"OVERWRITE_ROW_FAILED sheet={self.sheet} dir={direction} "
                f"err={type(e).__name__}:{e}"
            )
            if raise_on_error:
                raise
            messagebox.showerror("Error", f"覆盖整行失败：\n{e}")
            return False
        finally:
            self._suppress_bg_apply = previous_bg_suppression
            if callable(end_interactive):
                end_interactive()
            try:
                dt = (datetime.now() - t0).total_seconds() * 1000.0
                _dlog(f"OVERWRITE_ROW {self.sheet} dir={direction} ms={dt:.1f}")
            except Exception:
                pass
            if interactive_busy:
                try:
                    self.root.configure(cursor="")
                except Exception:
                    pass

    def _undo_last_action(self, *, _internal_rollback: bool = False):
        pending = self.app.undo_stack[-1] if getattr(self.app, "undo_stack", None) else None
        if not pending:
            return
        try:
            vcs_two_way = bool(self.app._is_vcs_two_way_mode())
        except Exception:
            vcs_two_way = False
        def _writes_protected_base(action) -> bool:
            if not isinstance(action, dict):
                return False
            if str(action.get("target") or "").upper() == "A":
                return True
            plan = action.get("plan")
            if str(getattr(plan, "target_side", "") or "").upper() == "A":
                return True
            return any(_writes_protected_base(child) for child in action.get("actions") or ())

        if vcs_two_way and _writes_protected_base(pending):
            notice = getattr(self.app, "show_nonblocking_notice", None)
            if callable(notice):
                notice(
                    "VCS 两方模式不会撤销或写入 Base 临时副本。",
                    warning=True,
                    duration_ms=6000,
                )
            return
        action_sheet = pending.get("sheet") or self.sheet
        undo_view = (
            self
            if action_sheet == self.sheet
            else getattr(self.app, "sheet_views", {}).get(action_sheet)
        )
        if undo_view is None:
            self.app.show_nonblocking_notice(
                f"撤销暂不可用：{action_sheet} 尚未加载。",
                duration_ms=6000,
            )
            return
        allow_column_undo_while_diffing = bool(
            pending
            and pending.get("kind") == "column_action"
            and undo_view._column_undo_model_ready()
        )
        if (
            not _internal_rollback
            and not undo_view._guard_mutation_ready("撤销", notify=False)
            and not allow_column_undo_while_diffing
        ):
            return
        try:
            if not _internal_rollback:
                undo_view._ensure_column_projection_current("撤销操作")
            column_undo_view = undo_view
            if pending and pending.get("kind") == "column_action":
                column_undo_view._ensure_column_projection_current("撤销列结构操作")
            action = self.app.pop_undo()
            if not action:
                return
            # Re-open the affected stable IDs while reversing an explicit
            # action; processed rows remain in the browser but become pending.
            try:
                undo_sheet = action.get("sheet") or undo_view.sheet
                affected_rows = {int(row) for row, *_rest in action.get("cells", [])}
                if action.get("row"):
                    affected_rows.add(int(action.get("row")))
                for row in affected_rows:
                    self.app.mark_difference_row_processed(undo_sheet, row, False)
            except Exception:
                pass
            if action.get("kind") == "compound":
                child_actions = list(action.get("actions") or ())
                if not child_actions:
                    return
                # Children are chronological. Appending them directly makes
                # the newest child pop first, so one visible undo command
                # reverses the complete region transaction.
                self.app.undo_stack.extend(child_actions)
                undone = 0
                for _child in child_actions:
                    stack_size = len(self.app.undo_stack)
                    self._undo_last_action(
                        _internal_rollback=_internal_rollback
                    )
                    if len(self.app.undo_stack) >= stack_size:
                        raise RuntimeError("复合操作中的子操作未能撤销")
                    undone += 1
                if "global_conflict_sheet_present" in action:
                    undo_view._restore_global_conflict_snapshot(
                        bool(action.get("global_conflict_sheet_present", False)),
                        action.get("global_conflict_sheet_before"),
                        bool(action.get("global_user_touched_conflicts_before", False)),
                    )
                    try:
                        undo_view.refresh(row_only=None, rescan=False)
                        undo_view._update_cursor_lines()
                    except Exception:
                        pass
                try:
                    undo_view.info.configure(
                        text=(
                            f"已撤销{action.get('label', '复合操作')}"
                            f"（{undone} 个步骤）。"
                        )
                    )
                except Exception:
                    pass
                _dlog(
                    f"UNDO_COMPOUND sheet={action.get('sheet')} "
                    f"label={action.get('label')} actions={undone}"
                )
                return
            if action.get("kind") == "column_action":
                column_undo_view._undo_column_action(action)
                return
            if action.get("kind") == "difference_state":
                for item_id in tuple(action.get("item_ids") or ()):
                    self.app.mark_difference_processed(item_id, False)
                try:
                    self.app.refresh_difference_browser()
                    undo_view.info.configure(text="已撤销保留 Mine 的处理标记；未写入工作簿数据。")
                except Exception:
                    pass
                return
            if action.get("kind") == "global_safe_cells":
                snapshot = action.get("snapshot")
                rows = undo_view._restore_global_safe_apply_snapshot(
                    snapshot,
                    # The enclosing compound restores the conflict map only
                    # after all chronological child actions have completed.
                    restore_conflicts=False,
                )
                undo_view._invalidate_only_diff_snapshot_cache()
                undo_view._invalidate_render_cache()
                side_lookup = (
                    undo_view.row_a_to_pair_idx
                    if action.get("target") == "A"
                    else undo_view.row_b_to_pair_idx
                )
                affected_pair_indices = list(dict.fromkeys(
                    int(side_lookup[row])
                    for row in sorted(rows)
                    if row in side_lookup
                ))
                undo_view._refresh_pair_indices_exact(affected_pair_indices)
                if bool(undo_view.only_diff_var.get()) and undo_view.snapshot_only_diff:
                    undo_view._cache_only_diff_rows_from_exact_pair_maps()
                undo_view.refresh(row_only=None, rescan=False)
                undo_view._update_cursor_lines()
                return
            if action.get("kind") == "global_sheet_copy":
                undo_view._restore_global_sheet_copy_snapshot(
                    action.get("snapshot") or {}
                )
                try:
                    undo_view.info.configure(text="已撤销整 Sheet 覆盖。")
                except Exception:
                    pass
                _dlog(
                    f"UNDO_GLOBAL_SHEET_COPY sheet={action.get('sheet')} "
                    f"source={action.get('source')} target={action.get('target')}"
                )
                return
            sheet = action.get("sheet")
            target = action.get("target")
            if sheet == undo_view.sheet:
                row_structure = target in (
                    "A_APPEND",
                    "A_INSERT_ROW",
                    "B_INSERT_ROW",
                    "A_DELETE_ROW",
                    "B_DELETE_ROW",
                )
                if str(target or "").startswith("A"):
                    edited_sides = ("A", "BASE") if action.get("base_inserted") else ("A",)
                elif str(target or "").startswith("B"):
                    edited_sides = ("B",)
                else:
                    edited_sides = ()
                if row_structure:
                    undo_view._mark_column_mapping_stale(
                        "undo",
                        row_structure=True,
                        edited_sides=edited_sides,
                    )
                elif target in ("A", "B"):
                    undo_view._mark_nonstructural_cell_edit(
                        "undo-cell-overwrite",
                        edited_sides=edited_sides,
                    )
            if target == "A_APPEND":
                start_row = action.get("start_row")
                count = action.get("count")
                if not start_row or not count:
                    return
                ws_edit = self.app.ws_a_edit(sheet)
                ws_val = self.app.ws_a_val(sheet)
                ws_edit.delete_rows(start_row, count)
                ws_val.delete_rows(start_row, count)
                try:
                    for op_map in (
                        self.app.manual_a_cell_ops,
                        self.app.manual_a_formula_cache_ops,
                    ):
                        keys_to_drop = [k for k in op_map.keys() if k[0] == sheet and k[1] >= int(start_row)]
                        for k in keys_to_drop:
                            op_map.pop(k, None)
                except Exception:
                    pass
                self.app.modified_a = True
                self.app.modified_sheets_a.add(sheet)
                if sheet == undo_view.sheet:
                    undo_view._invalidate_only_diff_snapshot_cache()
                    undo_view._invalidate_render_cache()
                    undo_view.refresh(row_only=None, rescan=True)
                    undo_view._update_cursor_lines()
                return
            if target in ("A_DELETE_ROW", "B_DELETE_ROW"):
                row = max(1, int(action.get("row", 1) or 1))
                if target == "A_DELETE_ROW":
                    ws_edit = self.app.ws_a_edit(sheet)
                    ws_val = self.app.ws_a_val(sheet)
                    manual_cells = self.app.manual_a_cell_ops
                    manual_cache = self.app.manual_a_formula_cache_ops
                    manual_row_ops = self.app.manual_a_row_ops
                else:
                    ws_edit = self.app.ws_b_edit(sheet)
                    ws_val = self.app.ws_b_val(sheet)
                    manual_cells = self.app.manual_b_cell_ops
                    manual_cache = self.app.manual_b_formula_cache_ops
                    manual_row_ops = self.app.manual_b_row_ops

                _restore_captured_worksheet_rows(ws_edit, action.get("edit_snapshot"))
                _restore_captured_worksheet_rows(ws_val, action.get("val_snapshot"))
                manual_cells.clear()
                manual_cells.update(dict(action.get("manual_cells_before") or {}))
                manual_cache.clear()
                manual_cache.update(dict(action.get("manual_cache_before") or {}))
                manual_row_ops[:] = copy.deepcopy(list(action.get("manual_row_ops_before") or []))

                if target == "A_DELETE_ROW":
                    self.app.modified_a = bool(action.get("modified_before", False))
                    self.app.modified_sheets_a.clear()
                    self.app.modified_sheets_a.update(
                        set(action.get("modified_sheets_before") or set())
                    )
                else:
                    self.app.modified_b = bool(action.get("modified_before", False))
                    self.app.modified_sheets_b.clear()
                    self.app.modified_sheets_b.update(
                        set(action.get("modified_sheets_before") or set())
                    )
                if sheet == undo_view.sheet:
                    undo_view._invalidate_only_diff_snapshot_cache()
                    undo_view._invalidate_render_cache()
                    undo_view.refresh(row_only=None, rescan=True)
                    undo_view._update_cursor_lines()
                    try:
                        undo_view.info.configure(text=f"已撤销删除 {action.get('count', 1)} 行。")
                    except Exception:
                        pass
                _dlog(
                    f"UNDO_DELETE_MISSING_SOURCE_ROWS sheet={sheet} "
                    f"side={target[:1]} row={row} count={action.get('count', 1)}"
                )
                return
            if target in ("A_INSERT_ROW", "B_INSERT_ROW"):
                row = action.get("row", 1)
                count = action.get("count", 1)
                base_inserted = action.get("base_inserted", False)
                base_row_del = action.get("base_row", row)
                if target == "A_INSERT_ROW":
                    ws_edit = self.app.ws_a_edit(sheet)
                    ws_val = self.app.ws_a_val(sheet)
                    ws_edit.delete_rows(row, count)
                    ws_val.delete_rows(row, count)
                    if "manual_cells_before" in action:
                        self.app.manual_a_cell_ops.clear()
                        self.app.manual_a_cell_ops.update(
                            dict(action.get("manual_cells_before") or {})
                        )
                        self.app.manual_a_formula_cache_ops.clear()
                        self.app.manual_a_formula_cache_ops.update(
                            dict(action.get("manual_cache_before") or {})
                        )
                        self.app.manual_a_row_ops[:] = copy.deepcopy(
                            list(action.get("manual_row_ops_before") or [])
                        )
                    else:
                        try:
                            row_int = int(row)
                            # Drop manual-edit records for the deleted row(s).
                            for op_map in (
                                self.app.manual_a_cell_ops,
                                self.app.manual_a_formula_cache_ops,
                            ):
                                to_drop = [k for k in op_map
                                           if k[0] == sheet and row_int <= k[1] < row_int + count]
                                for k in to_drop:
                                    del op_map[k]
                                # Shift records for rows that moved up after the delete.
                                to_shift = {k: v for k, v in op_map.items()
                                            if k[0] == sheet and k[1] >= row_int + count}
                                for k in to_shift:
                                    del op_map[k]
                                for (s, r, c), v in to_shift.items():
                                    op_map[(s, r - count, c)] = v
                        except Exception:
                            pass
                        self.app.remove_last_manual_a_row_insert(sheet, row, count)
                    if "modified_before" in action:
                        self.app.modified_a = bool(action.get("modified_before"))
                        self.app.modified_sheets_a.clear()
                        self.app.modified_sheets_a.update(
                            set(action.get("modified_sheets_before") or set())
                        )
                    else:
                        self.app.modified_a = True
                        self.app.modified_sheets_a.add(sheet)
                else:
                    ws_edit = self.app.ws_b_edit(sheet)
                    ws_val = self.app.ws_b_val(sheet)
                    ws_edit.delete_rows(row, count)
                    ws_val.delete_rows(row, count)
                    if "manual_cells_before" in action:
                        self.app.manual_b_cell_ops.clear()
                        self.app.manual_b_cell_ops.update(
                            dict(action.get("manual_cells_before") or {})
                        )
                        self.app.manual_b_formula_cache_ops.clear()
                        self.app.manual_b_formula_cache_ops.update(
                            dict(action.get("manual_cache_before") or {})
                        )
                        self.app.manual_b_row_ops[:] = copy.deepcopy(
                            list(action.get("manual_row_ops_before") or [])
                        )
                    else:
                        try:
                            row_int = int(row)
                            for op_map in (
                                self.app.manual_b_cell_ops,
                                self.app.manual_b_formula_cache_ops,
                            ):
                                to_drop = [
                                    key for key in op_map
                                    if key[0] == sheet and row_int <= key[1] < row_int + count
                                ]
                                for key in to_drop:
                                    del op_map[key]
                                to_shift = {
                                    key: value for key, value in op_map.items()
                                    if key[0] == sheet and key[1] >= row_int + count
                                }
                                for key in to_shift:
                                    del op_map[key]
                                for (sheet_name, row_idx, col_idx), value in to_shift.items():
                                    op_map[(sheet_name, row_idx - count, col_idx)] = value
                        except Exception as cache_shift_error:
                            _dlog(
                                f"manual_b_formula_cache_ops undo shift failed: "
                                f"sheet={sheet} row={row} err={cache_shift_error}"
                            )
                        self.app.remove_last_manual_b_row_insert(sheet, row, count)
                    if "modified_before" in action:
                        self.app.modified_b = bool(action.get("modified_before"))
                        self.app.modified_sheets_b.clear()
                        self.app.modified_sheets_b.update(
                            set(action.get("modified_sheets_before") or set())
                        )
                    else:
                        self.app.modified_b = True
                        self.app.modified_sheets_b.add(sheet)
                if base_inserted:
                    try:
                        ws_bv = self.app.ws_base_val(sheet)
                        ws_be = self.app.ws_base_edit(sheet)
                        if ws_bv is not None and ws_be is not None:
                            ws_bv.delete_rows(base_row_del, count)
                            ws_be.delete_rows(base_row_del, count)
                    except Exception:
                        pass
                if sheet == undo_view.sheet:
                    undo_view._invalidate_only_diff_snapshot_cache()
                    undo_view._invalidate_render_cache()
                    undo_view.refresh(row_only=None, rescan=True)
                    undo_view._update_cursor_lines()
                return
            cells = action.get("cells", [])
            if not cells:
                return
            if target == "A":
                ws_edit = self.app.ws_a_edit(sheet)
                ws_val = self.app.ws_a_val(sheet)
                self.app.modified_a = True
                self.app.modified_sheets_a.add(sheet)
            else:
                ws_edit = self.app.ws_b_edit(sheet)
                ws_val = self.app.ws_b_val(sheet)
                self.app.modified_b = True
                self.app.modified_sheets_b.add(sheet)
            rows = set()
            for r, c, old_edit, old_val in cells:
                restored_edit = _choose_edit_value(old_val, old_edit)
                _assign_edit_cell_value(ws_edit.cell(row=r, column=c), restored_edit)
                ws_val.cell(row=r, column=c).value = old_val
                if target == "A":
                    self.app.record_manual_a_cell(sheet, r, c, restored_edit)
                    if _formula_text(restored_edit):
                        self.app.record_manual_a_formula_cache(sheet, r, c, old_val)
                else:
                    self.app.record_manual_b_cell(sheet, r, c, restored_edit)
                    self.app.clear_manual_b_formula_cache(sheet, r, c)
                    if _formula_text(restored_edit):
                        self.app.record_manual_b_formula_cache(sheet, r, c, old_val)
                rows.add(r)
            # refresh current sheet if applicable
            if sheet == undo_view.sheet:
                for r in rows:
                    undo_view.touched_rows.add(r)
                undo_view._invalidate_only_diff_snapshot_cache()
                undo_view._invalidate_render_cache()
                side_lookup = (
                    undo_view.row_a_to_pair_idx if target == "A"
                    else undo_view.row_b_to_pair_idx
                )
                affected_pair_indices = list(dict.fromkeys(
                    int(side_lookup[r])
                    for r in sorted(rows)
                    if r in side_lookup
                ))
                undo_view._refresh_pair_indices_exact(affected_pair_indices)
                if bool(undo_view.only_diff_var.get()) and undo_view.snapshot_only_diff:
                    undo_view._cache_only_diff_rows_from_exact_pair_maps()
                if len(affected_pair_indices) <= _CELL_UNDO_INCREMENTAL_ROW_LIMIT:
                    # ``refresh(row_only=...)`` accepts a worksheet row rather
                    # than a pair index. Prefer Mine's row because refresh
                    # resolves that lookup first, then fall back to Theirs for
                    # a one-sided aligned pair.
                    for pair_idx in affected_pair_indices:
                        ra, rb = undo_view.row_pairs[pair_idx]
                        display_row = ra if ra is not None else rb
                        if display_row is not None:
                            undo_view.refresh(row_only=int(display_row), rescan=False)
                else:
                    undo_view.refresh(row_only=None, rescan=False)
                undo_view._update_cursor_lines()
        except Exception as e:
            messagebox.showerror("撤销失败", f"撤销操作失败，数据可能未恢复：\n{e}")

    def _resolve_conflict_cell(self, r: int, c: int):
        try:
            if self.app.resolve_conflict_cell(self.sheet, r, c):
                # update view based on updated conflict map
                self.refresh(row_only=None, rescan=False)
                self._update_cursor_lines()
        except Exception:
            pass

    def _resolve_conflict_row(
        self,
        r: int,
        cols,
        *,
        refresh: bool = True,
        raise_on_error: bool = False,
    ):
        """Resolve conflict state, optionally deferring repaint to a batch owner."""
        try:
            if self.app.resolve_conflict_row(self.sheet, r, cols):
                if refresh:
                    self.refresh(row_only=None, rescan=False)
                    self._update_cursor_lines()
        except Exception:
            if raise_on_error:
                raise

    def _refresh_row_text_only(self, r: int):
        """Update the rendered row text for row r without recomputing diff_cols_by_row."""
        try:
            ws_a = self.app.ws_a_val(self.sheet)
            ws_b = self.app.ws_b_val(self.sheet)
            ws_a_edit = self.app.ws_a_edit(self.sheet)
            ws_b_edit = self.app.ws_b_edit(self.sheet)

            # A row-only repaint must not replace the semantic column horizon
            # established by the full value/formula scan with Worksheet.max_column.
            # openpyxl includes style-only blank tail cells in max_column (Link is
            # 13 populated columns but has styled cells through column 18).  Growing
            # the logical model here creates false unresolved L14-L18 slots after
            # the first cell/row action and blocks the next action.  Structural
            # column changes use the dedicated rescan path to update these bounds.

            pair_idx = self.row_a_to_pair_idx.get(r)
            if pair_idx is None:
                pair_idx = self.row_b_to_pair_idx.get(r)
            if pair_idx is None:
                return
            ra, rb = self.row_pairs[pair_idx]
            line_a, line_b, _cols = self._build_row_and_diff_pair(ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb)
            self.pair_text_a[pair_idx] = line_a
            self.pair_text_b[pair_idx] = line_b

            line = self.row_to_line.get(pair_idx)
            if line is None:
                return

            self.left.delete(f"{line}.0", f"{line}.end")
            self._render_base_line(line, pair_idx)
            self.right.delete(f"{line}.0", f"{line}.end")
            self.left.insert(f"{line}.0", self.pair_text_a[pair_idx])
            self.right.insert(f"{line}.0", self.pair_text_b[pair_idx])
            self._render_row_header_line(line, pair_idx)
        except Exception:
            pass

    def _recalc_row_diff_and_update(self, r: int):
        """Recompute diff for row r and update its highlight, without changing the row list (snapshot mode)."""
        try:
            ws_a = self.app.ws_a_val(self.sheet)
            ws_b = self.app.ws_b_val(self.sheet)
            ws_a_edit = self.app.ws_a_edit(self.sheet)
            ws_b_edit = self.app.ws_b_edit(self.sheet)

            # Preserve the value/formula-aware bounds from the authoritative
            # sheet scan.  This incremental path is intentionally non-structural;
            # Worksheet.max_column can include formatted but empty tail columns.
            pair_idx = self.row_a_to_pair_idx.get(r)
            if pair_idx is None:
                pair_idx = self.row_b_to_pair_idx.get(r)
            if pair_idx is None:
                return
            if pair_idx >= len(self.row_pairs):
                return
            ra, rb = self.row_pairs[pair_idx]
            line_a, line_b, cols = self._build_row_and_diff_pair(ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb)
            self.pair_diff_cols[pair_idx] = cols
            if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
                self.pair_base_diff_cols[pair_idx] = self._compute_base_diff_cols_for_pair(
                    pair_idx,
                    (ra, rb),
                    max_col=self.max_col,
                    ws_a_val=ws_a,
                    ws_a_edit=ws_a_edit,
                    ws_base_val=self.app.ws_base_val(self.sheet),
                    ws_base_edit=self.app.ws_base_edit(self.sheet),
                )
            else:
                self.pair_base_diff_cols.pop(pair_idx, None)
            self.pair_text_a[pair_idx] = line_a
            self.pair_text_b[pair_idx] = line_b

            line = self.row_to_line.get(pair_idx)
            if line is None:
                # if not visible and touched, rebuild snapshot to include it
                if bool(self.only_diff_var.get()) and (r in self.touched_rows):
                    self.refresh(row_only=None, rescan=False)
                return

            # update text
            self.left.delete(f"{line}.0", f"{line}.end")
            self._render_base_line(line, pair_idx)
            self.right.delete(f"{line}.0", f"{line}.end")
            self.left.insert(f"{line}.0", self.pair_text_a[pair_idx])
            self.right.insert(f"{line}.0", self.pair_text_b[pair_idx])
            self._render_row_header_line(line, pair_idx)

            # update tags for this line
            for w in (self.left, self.base, self.right):
                w.tag_remove("diffrow", f"{line}.0", f"{line}.end")
                w.tag_remove("diffcell", f"{line}.0", f"{line}.end")

            visual_cols = self._visual_diff_cols_for_pair(pair_idx)
            if visual_cols:
                self.left.tag_add("diffrow", f"{line}.0", f"{line}.end")
                self.right.tag_add("diffrow", f"{line}.0", f"{line}.end")
                self.base.tag_add("diffrow", f"{line}.0", f"{line}.end")
                base_line = self._build_base_line(pair_idx) if self._is_three_way_enabled() else ""
                left_args, base_args, right_args, _lr, _br, _rr = self._diffcell_tag_args_for_line(
                    line,
                    pair_idx,
                    self.pair_text_a.get(pair_idx, ""),
                    base_line,
                    self.pair_text_b.get(pair_idx, ""),
                )
                if left_args:
                    self.left.tag_add("diffcell", *left_args)
                if base_args:
                    self.base.tag_add("diffcell", *base_args)
                if right_args:
                    self.right.tag_add("diffcell", *right_args)
                self._clear_diffrow_under_diffcells(left_args, base_args, right_args)
        except Exception:
            pass

    def _invalidate_render_cache(self):
        self._data_version += 1
        self._render_cache.clear()
        self._diff_blocks_cache = None
        self._invalidate_diff_block_model()

    def _build_base_line(self, pair_idx: int) -> str:
        if not self._is_three_way_enabled():
            return ""
        if not getattr(self.app, "has_base", False):
            return ""
        pair_idx = int(pair_idx)
        if pair_idx in self.pair_text_base:
            return self.pair_text_base[pair_idx]
        if not (0 <= pair_idx < len(self.row_pairs)):
            return ""
        pair = self.row_pairs[pair_idx]
        if not pair:
            return ""
        r = self._base_row_for_pair(pair_idx, pair)
        if r is None:
            base_width = max(
                self.max_col,
                int(getattr(self, "col_max_base", 1) or 1),
            )
            raw = ["【此侧缺行】"] + [""] * (base_width - 1)
            line = self._render_line_from_raw_parts(raw, "BASE")
            self.pair_text_base[pair_idx] = line
            return line
        try:
            ws_base = self._display_ws("BASE", edit=False)
        except Exception:
            return ""
        base_width = max(self.max_col, int(getattr(self, "col_max_base", 1) or 1))
        rows_base = _read_rows_into_cache(ws_base, (r,), base_width)
        raw = [
            _val_to_str(value)
            for value in _row_from_cache(rows_base, r, base_width)
        ]
        line = self._render_line_from_raw_parts(raw, "BASE")
        self.pair_text_base[pair_idx] = line
        return line

    def _render_base_full(self):
        if not self._is_three_way_enabled():
            try:
                self.base.delete("1.0", "end")
                self.base.tag_remove("selrow", "1.0", "end")
            except Exception:
                pass
            return []
        lines = []
        if self.display_rows and getattr(self, "_is_large_sheet", False):
            try:
                ws_base = self._display_ws("BASE", edit=False)
                base_rows_needed = []
                for pair_idx in self.display_rows:
                    if pair_idx in self.pair_text_base:
                        continue
                    base_row = self._base_row_for_pair(pair_idx)
                    if base_row is not None:
                        base_rows_needed.append(base_row)
                base_width = max(self.max_col, int(getattr(self, "col_max_base", 1) or 1))
                rows_base = _read_rows_into_cache(ws_base, base_rows_needed, base_width)
                for pair_idx in self.display_rows:
                    if pair_idx in self.pair_text_base:
                        lines.append(self.pair_text_base[pair_idx])
                        continue
                    base_row = self._base_row_for_pair(pair_idx)
                    if base_row is None:
                        lines.append(self._build_base_line(pair_idx))
                        continue
                    row_base = _row_from_cache(rows_base, base_row, base_width)
                    lines.append(self._cache_base_line_from_row_values(pair_idx, row_base))
            except Exception:
                lines = [self._build_base_line(pair_idx) for pair_idx in self.display_rows]
        else:
            lines = [self._build_base_line(pair_idx) for pair_idx in self.display_rows]
        try:
            self.base.delete("1.0", "end")
            self.base.insert("1.0", "\n".join(lines) + ("\n" if lines else ""))
        except Exception:
            pass
        return lines

    def _render_base_line(self, line: int, pair_idx: int):
        if not self._is_three_way_enabled():
            return
        txt = self._build_base_line(pair_idx)
        try:
            self.base.delete(f"{line}.0", f"{line}.end")
            self.base.insert(f"{line}.0", txt)
        except Exception:
            pass

    def _row_label_for_pair_idx(self, pair_idx: int, side: str) -> str:
        try:
            if side == "BASE":
                r = self._base_row_for_pair(pair_idx)
            else:
                pair = self.row_pairs[pair_idx]
                r = self._row_for_side(pair, side)
            return str(r) if r is not None else "缺行"
        except Exception:
            return ""

    def _format_main_row_header(
        self,
        pair_idx: int,
        side: str,
        rownum_width: int,
        *,
        arrow: str | None = None,
    ) -> str:
        prefix = self._diff_block_marker_prefix(pair_idx, side)
        body = arrow if arrow is not None else self._row_label_for_pair_idx(pair_idx, side)
        return prefix + str(body or "").rjust(rownum_width)

    def _rownum_render_width(self) -> int:
        max_label = int(self.max_row or 0)
        try:
            mine_base = getattr(self, "mine_to_base_row", {}) or {}
            theirs_base = getattr(self, "theirs_to_base_row", {}) or {}
            missing_base = getattr(self, "_missing_base_row_map", {}) or {}
            if mine_base:
                max_label = max(max_label, max(int(v) for v in mine_base.values() if v is not None))
            if theirs_base:
                max_label = max(max_label, max(int(v) for v in theirs_base.values() if v is not None))
            if missing_base:
                max_label = max(max_label, max(int(v) for v in missing_base.values() if v is not None))
        except Exception:
            pass
        return max(3, len(str(max(0, max_label))))

    def _sync_row_header_width_widgets(self):
        rn_w = self._rownum_render_width()
        header_w = max(4, rn_w + 1 + self._diff_block_marker_width())
        self._rownum_display_width = rn_w
        if getattr(self, "_row_header_width", None) == header_w:
            return rn_w
        self._row_header_width = header_w
        widgets = [
            getattr(self, "left_ln", None),
            getattr(self, "base_ln", None),
            getattr(self, "right_ln", None),
            getattr(self, "left_corner_hdr", None),
            getattr(self, "base_corner_hdr", None),
            getattr(self, "right_corner_hdr", None),
            getattr(self, "cursor_cmp_corner", None),
            getattr(self, "cursor_cmp_ln", None),
        ]
        for w in widgets:
            if w is None:
                continue
            try:
                w.configure(width=header_w)
            except Exception:
                pass
        return rn_w

    def _render_row_headers_full(self):
        rn_w = self._sync_row_header_width_widgets()
        left_lines = []
        base_lines = []
        right_lines = []
        for pidx in self.display_rows:
            left_lines.append(self._format_main_row_header(pidx, "A", rn_w))
            base_lines.append(self._format_main_row_header(pidx, "BASE", rn_w))
            right_lines.append(self._format_main_row_header(pidx, "B", rn_w))
        for w, lines in ((self.left_ln, left_lines), (self.base_ln, base_lines), (self.right_ln, right_lines)):
            try:
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", "\n".join(lines) + ("\n" if lines else ""))
                w.tag_remove("diffrow", "1.0", "end")
                w.configure(state="disabled")
            except Exception:
                pass

    def _render_row_header_line(self, line: int, pair_idx: int):
        rn_w = self._sync_row_header_width_widgets()
        vals = (
            self._format_main_row_header(pair_idx, "A", rn_w),
            self._format_main_row_header(pair_idx, "BASE", rn_w),
            self._format_main_row_header(pair_idx, "B", rn_w),
        )
        for w, txt in ((self.left_ln, vals[0]), (self.base_ln, vals[1]), (self.right_ln, vals[2])):
            try:
                w.configure(state="normal")
                w.delete(f"{line}.0", f"{line}.end")
                w.insert(f"{line}.0", txt)
                w.tag_remove("diffrow", f"{line}.0", f"{line}.end")
                w.configure(state="disabled")
            except Exception:
                pass

    def _append_row_header_lines(self, pair_indices: list[int]):
        """Append materialized row headers without clamping beyond the Text end."""
        if not pair_indices:
            return
        rn_w = self._sync_row_header_width_widgets()
        for w, side in (
            (self.left_ln, "A"),
            (self.base_ln, "BASE"),
            (self.right_ln, "B"),
        ):
            lines = [self._format_main_row_header(pair_idx, side, rn_w) for pair_idx in pair_indices]
            try:
                w.configure(state="normal")
                w.insert("end", "\n".join(lines) + "\n")
            except Exception:
                pass
            finally:
                try:
                    w.configure(state="disabled")
                except Exception:
                    pass

    def _build_col_header_line(self, side: str = "LOGICAL") -> str:
        projection = self._active_column_projection()
        if projection.slot_count <= 0:
            return ""
        sep = _COL_SEP if self._is_grid_overlay_enabled() else "   "
        trail = " │" if self._is_grid_overlay_enabled() else ""
        parts = []
        for c in range(1, projection.slot_count + 1):
            label = projection.header_label(side, c)
            parts.append(_format_cell(label, self.col_char_widths.get(c, 1)))
        return sep.join(parts) + (trail if parts else "")

    def _column_structure_summary(self) -> str:
        projection = self._active_column_projection()
        cache = self._active_column_comparison_cache()
        special_cols = set(cache.structural_diff_cols)
        special_cols.update(cache.unresolved_cols)
        items = []
        state_labels = {
            "inserted": "新增列",
            "deleted": "删除列",
            "mine-deleted": f"{self._merge_side_label('A')}删除",
            "theirs-deleted": f"{self._merge_side_label('B')}删除",
            "both-deleted": "双方删除",
            "unresolved": "待确认",
        }
        cause_labels = {
            COLUMN_MAPPING_CAUSE_BLANK_COLUMN: "空白列无法唯一识别",
            COLUMN_MAPPING_CAUSE_DUPLICATE_SIGNATURE: "重复列特征",
            COLUMN_MAPPING_CAUSE_FORMULA_MISMATCH: "公式结构不一致",
            COLUMN_MAPPING_CAUSE_INCOMPATIBLE_CACHE: "缓存版本不兼容",
            COLUMN_MAPPING_CAUSE_IMPLICIT_BOUNDARY: "列边界不明确",
            COLUMN_MAPPING_CAUSE_COLUMN_LIMIT: "超过列对齐上限",
            COLUMN_MAPPING_CAUSE_LOW_CONFIDENCE: "匹配置信度不足",
        }
        for block in projection.model.blocks:
            logical_cols = [int(idx) + 1 for idx in block.slot_indices]
            if not any(col in special_cols for col in logical_cols):
                continue
            start_col = logical_cols[0]
            end_col = logical_cols[-1]
            range_label = _excel_column_range_display(start_col, end_col)
            slots = [projection.slot(col) for col in logical_cols]
            slots = [slot for slot in slots if slot is not None]
            unresolved = any(
                slot.state == "unresolved" or slot.confidence.ambiguous
                for slot in slots
            )
            state_text = "待确认" if unresolved else state_labels.get(block.state, "结构变化")
            missing_sides = []
            for side, label in (("A", self._merge_side_label("A")), ("BASE", self._merge_side_label("BASE")), ("B", self._merge_side_label("B"))):
                if side == "BASE" and not self._is_three_way_enabled():
                    continue
                if all(projection.is_missing(side, col) for col in logical_cols):
                    missing_sides.append(f"{label}缺列")
            causes = []
            for slot in slots:
                for cause in slot.confidence.cause_codes:
                    translated = cause_labels.get(cause)
                    if translated:
                        causes.append(translated)
            details = missing_sides + list(dict.fromkeys(causes))
            detail_text = f"（{'；'.join(details)}）" if details else ""
            marker = "?" if unresolved else _LOGICAL_COLUMN_STATE_MARKERS.get(block.state, "!")
            items.append(f"{marker}{range_label} {state_text}{detail_text}")
        if not items:
            return ""
        preview = "，".join(items[:4])
        if len(items) > 4:
            preview += f"，…（另{len(items) - 4}块）"
        return preview

    def _info_column_text(self) -> str:
        summary = self._column_structure_summary()
        self._sync_column_structure_status_detail(summary)
        structural_blocks = sum(
            1
            for block in self._active_column_projection().model.blocks
            if self._column_block_is_structural(block)
        )
        return f"列 {self._logical_slot_count()}｜结构 {structural_blocks}"

    def _normal_sheet_info_text(self) -> str:
        total_rows = len(self.row_pairs) if self.row_pairs else self.max_row
        return (
            f"显示 {len(self.display_rows)}/{total_rows}｜差异行 "
            f"{self._display_diff_row_count}｜{self._info_column_text()}"
        )

    def _apply_column_header_structure_tags(self, widget: tk.Text, side: str):
        try:
            widget.tag_configure("colstruct", background="#FFF1B8", foreground="#7A4B00")
            widget.tag_configure("colmissing", background="#B0B0B0", foreground="#3A3A3A")
            widget.tag_configure("colunresolved", background="#FFD1D1", foreground="#8B0000")
            projection = self._active_column_projection()
            spans = self._spans_for_line(self._build_col_header_line(side))
            for logical_col in range(1, projection.slot_count + 1):
                slot = projection.slot(logical_col)
                if slot is None or logical_col not in spans:
                    continue
                if slot.state == "retained" and not slot.confidence.ambiguous:
                    continue
                start, end = spans[logical_col]
                tag = (
                    "colunresolved"
                    if slot.state == "unresolved" or slot.confidence.ambiguous
                    else "colmissing"
                    if side != "LOGICAL" and projection.is_missing(side, logical_col)
                    else "colstruct"
                )
                widget.tag_add(tag, f"1.{start}", f"1.{end}")
        except Exception:
            pass

    def _render_col_headers(self):
        rn_w = self._sync_row_header_width_widgets()
        corner = "".rjust(rn_w + self._diff_block_marker_width())
        for w in (self.left_corner_hdr, self.base_corner_hdr, self.right_corner_hdr, self.cursor_cmp_corner):
            try:
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", corner)
                w.configure(state="disabled")
            except Exception:
                pass
        header_widgets = (
            (self.left_colhdr, "A"),
            (self.base_colhdr, "BASE"),
            (self.right_colhdr, "B"),
            # C is a focused logical projection. Its logical headers now use
            # the same Excel A..Z/AA convention as the main panes while
            # retaining structural markers independent of a physical side.
            (self.cursor_cmp_colhdr, "LOGICAL"),
        )
        for w, side in header_widgets:
            try:
                hdr = self._build_col_header_line(side)
                w.configure(state="normal")
                w.delete("1.0", "end")
                w.insert("1.0", hdr)
                self._apply_column_header_structure_tags(w, side)
                w.configure(state="disabled")
            except Exception:
                pass
        self._apply_column_block_selection_tags()

    def _render_cursor_row_headers(self, pair, is_three: bool):
        if not hasattr(self, "cursor_cmp_ln"):
            return
        rn_w = self._sync_row_header_width_widgets()
        ra = self._row_for_side(pair, "A") if pair else None
        rb = self._row_for_side(pair, "B") if pair else None
        rows = []
        if is_three:
            pair_idx = self._normalize_pair_idx(getattr(self, "_last_cursor_cmp_pair_idx", None))
            base_r = self._base_row_for_pair(pair_idx, pair) if pair and pair_idx is not None else None
            rows.append(str(base_r) if base_r is not None else "缺行")
            rows.append(str(ra) if ra is not None else "缺行")
        else:
            rows.append(str(ra) if ra is not None else "缺行")
        rows.append(str(rb) if rb is not None else "缺行")
        prefix = " " * self._diff_block_marker_width()
        rows_txt = [prefix + r.rjust(rn_w) for r in rows]
        try:
            self.cursor_cmp_ln.configure(state="normal")
            self.cursor_cmp_ln.delete("1.0", "end")
            self.cursor_cmp_ln.insert("1.0", "\n".join(rows_txt) + ("\n" if rows_txt else ""))
            self.cursor_cmp_ln.configure(state="disabled")
        except Exception:
            pass

    # ---------- Rendering ----------
    def _load_all_rows(self):
        self._full_render = True
        self.refresh(row_only=None, rescan=False)

    def _append_rows(self, new_rows: list[int], *, refresh_block_ui: bool = True):
        if not new_rows:
            return
        ws_a = self.app.ws_a_val(self.sheet)
        ws_b = self.app.ws_b_val(self.sheet)
        try:
            wb_a_edit = getattr(self.app, "_wb_a_edit", None)
            ws_a_edit = wb_a_edit[self.sheet] if wb_a_edit is not None else None
        except Exception:
            ws_a_edit = None
        try:
            wb_b_edit = getattr(self.app, "_wb_b_edit", None)
            ws_b_edit = wb_b_edit[self.sheet] if wb_b_edit is not None else None
        except Exception:
            ws_b_edit = None
        try:
            wb_base_edit = getattr(self.app, "_wb_base_edit", None)
            ws_base_edit_ready = wb_base_edit[self.sheet] if wb_base_edit is not None and getattr(self.app, "has_base", False) else None
        except Exception:
            ws_base_edit_ready = None

        if getattr(self, "_data_ready", False) and not self._column_mapping_is_current():
            self._ensure_column_projection_current(
                "增量加载行",
                ws_a_val=ws_a,
                ws_b_val=ws_b,
                ws_a_edit=ws_a_edit,
                ws_b_edit=ws_b_edit,
                ws_base_val=(self.app.ws_base_val(self.sheet) if getattr(self.app, "has_base", False) else None),
                ws_base_edit=ws_base_edit_ready,
            )

        missing_pair_text = any(
            pair_idx not in self.pair_text_a or pair_idx not in self.pair_text_b
            for pair_idx in new_rows
        )
        # Only rows not covered by the exact background cache need formula-text
        # fallback. Cached rows must never block scrolling/rendering on workbook I/O.
        if missing_pair_text and _USE_CACHED_VALUES_ONLY and (ws_a_edit is None or ws_b_edit is None):
            # Scrolling is a view-only action and must never synchronously parse
            # editable workbooks on Tk. The background preload will publish
            # readiness; until then cached values remain viewable.
            request_preload = getattr(self.app, "_request_edit_preload", None)
            if callable(request_preload):
                request_preload()
            _dlog(
                f"formula fallback deferred off Tk: sheet={self.sheet} "
                f"rows={len(new_rows)}"
            )

        start_line = len(self.display_rows) + 1
        # Preserve current scroll position to avoid jumps
        try:
            first, _last = self.left.yview()
        except Exception:
            first = None

        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            self._ensure_base_diff_cache(
                pair_indices=new_rows,
                max_col=self.max_col,
                ws_a_val=ws_a,
                ws_a_edit=ws_a_edit if ws_a_edit is not None else ws_a,
                ws_base_val=self.app.ws_base_val(self.sheet),
                ws_base_edit=ws_base_edit_ready if ws_base_edit_ready is not None else self.app.ws_base_val(self.sheet),
            )

        row_header_diffrow_args = []
        for idx, pair_idx in enumerate(new_rows, start=0):
            if pair_idx not in self.pair_text_a or pair_idx not in self.pair_text_b:
                ra, rb = self.row_pairs[pair_idx]
                line_a, line_b, cols = self._build_row_and_diff_pair(ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb)
                self.pair_diff_cols[pair_idx] = cols
                self.pair_text_a[pair_idx] = line_a
                self.pair_text_b[pair_idx] = line_b
            else:
                line_a = self.pair_text_a.get(pair_idx, "")
                line_b = self.pair_text_b.get(pair_idx, "")
            visual_cols = self._visual_diff_cols_for_pair(pair_idx)

            line_no = start_line + idx
            self.left.insert("end", line_a + "\n")
            if self._is_three_way_enabled():
                self.base.insert("end", self._build_base_line(pair_idx) + "\n")
            self.right.insert("end", line_b + "\n")

            if visual_cols:
                self._display_diff_row_count += 1
                row_header_diffrow_args.extend([f"{line_no}.0", f"{line_no}.end"])
                self.left.tag_add("diffrow", f"{line_no}.0", f"{line_no}.end")
                self.base.tag_add("diffrow", f"{line_no}.0", f"{line_no}.end")
                self.right.tag_add("diffrow", f"{line_no}.0", f"{line_no}.end")
                base_line = self._build_base_line(pair_idx) if self._is_three_way_enabled() else ""
                left_args, base_args, right_args, _lr, _br, _rr = self._diffcell_tag_args_for_line(
                    line_no,
                    pair_idx,
                    line_a,
                    base_line,
                    line_b,
                )
                if left_args:
                    self.left.tag_add("diffcell", *left_args)
                if base_args:
                    self.base.tag_add("diffcell", *base_args)
                if right_args:
                    self.right.tag_add("diffcell", *right_args)

        self._append_row_header_lines(new_rows)
        if row_header_diffrow_args:
            for w in (self.left_ln, self.base_ln, self.right_ln):
                w.tag_add("diffrow", *row_header_diffrow_args)

        self.display_rows.extend(new_rows)
        for i, pair_idx in enumerate(new_rows, start=start_line):
            self.row_to_line[pair_idx] = i

        # row numbers are rendered in dedicated row-header widgets

        self.info.configure(text=self._normal_sheet_info_text())

        if first is not None:
            try:
                self.left.yview_moveto(first)
                if self._is_three_way_enabled():
                    self.base.yview_moveto(first)
                self.right.yview_moveto(first)
            except Exception:
                pass

        self._invalidate_render_cache()
        if refresh_block_ui:
            self._refresh_diff_block_ui()

    def _maybe_load_more_rows(self, last_fraction: float):
        if not _FAST_OPEN_ENABLED:
            return
        try:
            last_fraction = float(last_fraction)
        except Exception:
            return
        if self._full_render:
            return
        if bool(self.only_diff_var.get()):
            return
        if getattr(self.app, "merge_conflict_mode", False):
            return
        # Only for full-list mode (not only-diff or conflict-only)
        if not self._full_display_rows:
            return
        if last_fraction < 0.98:
            return
        if len(self.display_rows) >= len(self._full_display_rows):
            return
        old_limit = len(self.display_rows)
        new_limit = min(len(self._full_display_rows), self._render_limit + _FAST_RENDER_BATCH)
        self._render_limit = new_limit
        new_rows = self._full_display_rows[old_limit:new_limit]
        self._append_rows(new_rows)

    def _refresh_missing_sheet_view(self, row_only: int | None, rescan: bool):
        meta = self._sheet_meta()
        ws_a = self._display_ws("A", edit=False)
        ws_b = self._display_ws("B", edit=False)
        ws_a_edit = self._display_ws("A", edit=True)
        ws_b_edit = self._display_ws("B", edit=True)
        ws_base = self._display_ws("BASE", edit=False) if getattr(self.app, "has_base", False) else None

        a_r, a_c = _effective_bounds_with_edit(ws_a, ws_a_edit) if meta.get("has_a") else (0, 0)
        b_r, b_c = _effective_bounds_with_edit(ws_b, ws_b_edit) if meta.get("has_b") else (0, 0)
        base_r, base_c = (
            _effective_bounds_with_edit(ws_base, self._display_ws("BASE", edit=True))
            if (ws_base is not None and meta.get("has_base")) else (0, 0)
        )
        self.max_row = max(1, a_r, b_r, base_r)
        self.max_col = max(1, a_c, b_c, base_c)
        self.col_max_a = max(1, a_c)
        self.col_max_b = max(1, b_c)
        self.col_max_base = max(1, base_c)
        self._base_bounds_checked = bool(ws_base is not None and meta.get("has_base"))
        self._bounds_checked = True
        self._is_large_sheet = False
        self._align_rows_enabled = False
        self._diff_partial = False
        self._full_render = True
        self._missing_base_row_map = {}
        self.mine_to_base_row = {r: r for r in range(1, min(a_r, base_r) + 1)} if meta.get("has_a") and meta.get("has_base") else {}
        self.theirs_to_base_row = {r: r for r in range(1, min(b_r, base_r) + 1)} if meta.get("has_b") and meta.get("has_base") else {}
        self.pair_base_row_override = {}

        self.row_pairs = []
        self.row_a_to_pair_idx = {}
        self.row_b_to_pair_idx = {}
        self.pair_text_a = {}
        self.pair_text_b = {}
        self.pair_text_base = {}
        self.pair_diff_cols = {}
        self.pair_base_diff_cols = {}

        for r in range(1, self.max_row + 1):
            ra = r if meta.get("has_a") and r <= a_r else None
            rb = r if meta.get("has_b") and r <= b_r else None
            idx = len(self.row_pairs)
            self.row_pairs.append((ra, rb))
            if ra is not None:
                self.row_a_to_pair_idx[ra] = idx
            if rb is not None:
                self.row_b_to_pair_idx[rb] = idx
            if meta.get("has_base") and r <= base_r:
                self._missing_base_row_map[idx] = r

        self._prescan_col_widths(ws_a, ws_b, ws_base)
        for idx, (ra, rb) in enumerate(self.row_pairs):
            line_a, line_b, cols = self._build_row_and_diff_pair(ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb)
            if (ra is None and rb is None and idx in self._missing_base_row_map) or ((ra is None) != (rb is None)):
                cols = {-1}
            self.pair_text_a[idx] = line_a
            self.pair_text_b[idx] = line_b
            self.pair_diff_cols[idx] = cols

        self._data_ready = True
        self._row_model_exact = True
        self._pair_diff_full_exact = True
        self._base_diff_full_exact = True
        self._cache_formula_aware = bool(self.app._edit_workbooks_ready())
        self._lifecycle_error = None
        self._lifecycle_canceled = False
        self._only_diff_async_build_seq += 1
        self._only_diff_async_building = False
        self._only_diff_async_build_key = None
        exact_diff_rows = [
            pair_idx
            for pair_idx in range(len(self.row_pairs))
            if self._pair_has_visual_diff(pair_idx)
        ]
        self._cache_only_diff_rows_snapshot(exact_diff_rows, exact=True)
        if bool(self.only_diff_var.get()):
            self._full_display_rows = self._only_diff_rows_with_touched(
                exact_diff_rows
            )
        else:
            self._full_display_rows = list(range(0, len(self.row_pairs)))
        self.display_rows = list(self._full_display_rows)
        self.row_to_line = {r: i + 1 for i, r in enumerate(self.display_rows)}

        try:
            self._render_col_headers()
        except Exception:
            pass
        self.left.delete("1.0", "end")
        self.base.delete("1.0", "end")
        self.right.delete("1.0", "end")
        for w in (self.left, self.base, self.right, self.left_ln, self.base_ln, self.right_ln):
            try:
                w.tag_remove("diffrow", "1.0", "end")
                w.tag_remove("diffcell", "1.0", "end")
                w.tag_remove("paddingrow", "1.0", "end")
            except Exception:
                pass
        lines_a = [self.pair_text_a.get(pair_idx, "") for pair_idx in self.display_rows]
        lines_b = [self.pair_text_b.get(pair_idx, "") for pair_idx in self.display_rows]
        self.left.insert("1.0", "\n".join(lines_a) + ("\n" if lines_a else ""))
        lines_base = self._render_base_full()
        self.right.insert("1.0", "\n".join(lines_b) + ("\n" if lines_b else ""))
        self._render_row_headers_full()

        diffrow_args = []
        pad_left = []
        pad_right = []
        for line_idx, pair_idx in enumerate(self.display_rows, start=1):
            if self._pair_has_visual_diff(pair_idx):
                diffrow_args.extend([f"{line_idx}.0", f"{line_idx}.end"])
            ra, rb = self.row_pairs[pair_idx]
            if ra is None:
                pad_left.extend([f"{line_idx}.0", f"{line_idx}.end"])
            if rb is None:
                pad_right.extend([f"{line_idx}.0", f"{line_idx}.end"])
        if diffrow_args:
            for w in (self.left, self.base, self.right, self.left_ln, self.base_ln, self.right_ln):
                w.tag_add("diffrow", *diffrow_args)
        if pad_left:
            self.left.tag_add("paddingrow", *pad_left)
        if pad_right:
            self.right.tag_add("paddingrow", *pad_right)

        self._refresh_diff_block_ui()
        diff_count = len(self.display_rows)
        self._display_diff_row_count = diff_count
        self.info.configure(text=f"缺失 Sheet 对照｜{self._normal_sheet_info_text()}")
        self.app.set_sheet_has_diff(
            self.sheet,
            diff_count > 0 or bool(self._active_column_comparison_cache().structural_diff_cols),
            confirmed=True,
        )
        self.app.refresh_sheet_nav()
        self._update_diff_nav_state()
        try:
            self._update_diff_maps()
        except Exception:
            pass
        self._refresh_interaction_gate()
        return

    def refresh(self, row_only: int | None, rescan: bool, *, column_only: bool = False):
        _dlog(f"REFRESH sheet={self.sheet} row_only={row_only} rescan={rescan} only_diff={bool(self.only_diff_var.get())} raw={self.only_diff_var.get()}")
        if (
            rescan
            and not self._is_missing_sheet_view()
            and not self.app._edit_workbooks_ready()
        ):
            # An explicit refresh/recalculation is an editing intent.  Start
            # deferred editable loading in the background, but keep this
            # refresh non-blocking so the Tk event loop remains responsive.
            self.app._request_edit_preload()
        column_diff_seed_request = None
        if bool(column_only and rescan):
            column_diff_seed_request = getattr(self, "_pending_column_only_diff_seed", None)
        self._pending_column_only_diff_seed = None
        used_column_diff_seed = False
        # One rescan owns one cache bundle.  Mapping, width pre-scan, row diff,
        # and Base diff may all need the same sequential worksheet rows; keeping
        # them local avoids stale cross-refresh data while eliminating duplicate
        # openpyxl iteration and tuple allocation.
        row_cache_bundle: dict = {}
        if rescan and bool(getattr(self, "_only_diff_async_building", False)):
            # A foreground rescan is authoritative and computes the exact row
            # set itself.  Retire any older disk-backed snapshot so its
            # in-flight flag cannot keep the freshly built block model in the
            # "计算中" state or suppress presentation tags.
            self._only_diff_async_build_seq += 1
            self._only_diff_async_building = False
            self._only_diff_async_build_key = None
        if rescan and (not self._full_render):
            self._render_limit = _FAST_RENDER_ROW_LIMIT
        if self._is_missing_sheet_view():
            return self._refresh_missing_sheet_view(row_only, rescan)
        conflict_cells_by_row = None
        if getattr(self.app, "merge_conflict_mode", False):
            rows_map = getattr(self.app, "merge_conflict_cells_by_sheet", None)
            conflict_cells_by_row = rows_map.get(self.sheet) if rows_map else None
        ws_a = self.app.ws_a_val(self.sheet)
        ws_b = self.app.ws_b_val(self.sheet)
        # Non-blocking edit sheets: use loaded edit workbook if already available.
        # Do not trigger expensive load_workbook() during pure view refresh/toggle.
        try:
            wb_a_edit = getattr(self.app, "_wb_a_edit", None)
            ws_a_edit = wb_a_edit[self.sheet] if wb_a_edit is not None else None
        except Exception:
            ws_a_edit = None
        try:
            wb_b_edit = getattr(self.app, "_wb_b_edit", None)
            ws_b_edit = wb_b_edit[self.sheet] if wb_b_edit is not None else None
        except Exception:
            ws_b_edit = None
        try:
            wb_base_edit = getattr(self.app, "_wb_base_edit", None)
            ws_base_edit_ready = wb_base_edit[self.sheet] if wb_base_edit is not None and getattr(self.app, "has_base", False) else None
        except Exception:
            ws_base_edit_ready = None
        reuse_row_alignment = bool(
            rescan
            and getattr(self, "row_pairs", None)
            and (
                column_only
                or getattr(self, "_row_alignment_reuse_requested", False)
            )
        )
        preserved_row_pairs = list(self.row_pairs) if reuse_row_alignment else []
        preserved_mine_to_base = dict(getattr(self, "mine_to_base_row", {}) or {})
        preserved_theirs_to_base = dict(getattr(self, "theirs_to_base_row", {}) or {})
        preserved_base_overrides = dict(getattr(self, "pair_base_row_override", {}) or {})
        preserved_align_enabled = bool(getattr(self, "_align_rows_enabled", False))
        if reuse_row_alignment:
            self._row_alignment_reuse_requested = False

        if (
            not rescan
            and getattr(self, "_data_ready", False)
            and not self._column_mapping_is_current()
        ):
            self._ensure_column_projection_current(
                "刷新显示",
                ws_a_val=ws_a,
                ws_b_val=ws_b,
                ws_a_edit=ws_a_edit,
                ws_b_edit=ws_b_edit,
                ws_base_val=(self.app.ws_base_val(self.sheet) if getattr(self.app, "has_base", False) else None),
                ws_base_edit=ws_base_edit_ready,
            )

        used_column_bounds_seed = bool(
            column_diff_seed_request is not None
            and self._try_apply_column_action_bounds_seed(column_diff_seed_request)
        )
        if (rescan or (not self._bounds_checked)) and not used_column_bounds_seed:
            a_r, a_c = _effective_bounds_with_edit(ws_a, ws_a_edit)
            b_r, b_c = _effective_bounds_with_edit(ws_b, ws_b_edit)
            self._effective_max_row_a = a_r
            self._effective_max_row_b = b_r
            self.max_row = max(a_r, b_r)
            self.max_col = max(a_c, b_c)
            self.col_max_a = a_c
            self.col_max_b = b_c
            self._bounds_checked = True
            self._is_large_sheet = self.max_row >= _LARGE_SHEET_ROW_THRESHOLD
            if self._is_large_sheet:
                self._prefer_only_diff_when_ready = True

        # Full rescan diff map + cache row text if requested
        # Use _data_ready flag instead of checking pair_diff_cols emptiness:
        # pair_diff_cols can legitimately be empty (no diffs found) while still being valid data.
        if rescan or not self._data_ready:
            if not rescan:
                # Data not yet ready (background computation still running).
                # Skip this call; _apply_sheet_cache will call refresh() when done.
                return
            if not reuse_row_alignment:
                self._row_model_version = int(getattr(self, "_row_model_version", 0)) + 1
                self._column_mapping_stale_reason = "row-model-rebuilt"
            self.pair_diff_cols = {}
            self.pair_base_diff_cols = {}
            self.pair_text_a = {}
            self.pair_text_b = {}
            self.pair_text_base = {}
            self.row_a_to_pair_idx = {}
            self.row_b_to_pair_idx = {}
            self.pair_base_row_override = {}
            self.column_comparison_cache = None
            self.column_projection = None
            self.column_alignment_2way = None
            self.column_alignment_3way = None
            self.logical_column_states = ()
            self.logical_column_structural_conflicts = ()
            self._diff_partial = False
            self._pair_diff_full_exact = False

            if (
                conflict_cells_by_row is not None
                and not reuse_row_alignment
                and not bool(getattr(self.app, "has_base", False))
            ):
                # Conflict-only fast path: avoid full-sheet diff scan.
                self._align_rows_enabled = False
                conflict_rows = sorted(conflict_cells_by_row.keys())
                self.row_pairs = [(r, r) for r in conflict_rows]
                for idx, (ra, rb) in enumerate(self.row_pairs):
                    if ra is not None:
                        self.row_a_to_pair_idx[ra] = idx
                    if rb is not None:
                        self.row_b_to_pair_idx[rb] = idx
                # Build the same shared logical projection before formatting.
                ws_base_val_opt = None
                if getattr(self.app, "has_base", False):
                    try:
                        ws_base_val_opt = self.app.ws_base_val(self.sheet)
                    except Exception:
                        pass
                try:
                    self._rebuild_column_comparison_cache_from_worksheets(
                        ws_a,
                        ws_b,
                        ws_a_edit,
                        ws_b_edit,
                        ws_base_val=ws_base_val_opt,
                        ws_base_edit=ws_base_edit_ready or ws_base_val_opt,
                    )
                except Exception as exc:
                    _dlog(f"conflict column projection fallback: sheet={self.sheet} err={exc}")
                    self._install_column_projection(self._identity_column_comparison_cache())
                self._prescan_col_widths(ws_a, ws_b, ws_base_val_opt)
                for idx, (ra, rb) in enumerate(self.row_pairs):
                    line_a, line_b, _cols = self._build_row_and_diff_pair(ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb)
                    cols = set(conflict_cells_by_row.get(ra, set())) if ra is not None else set()
                    if not cols and _cols:  # preserve sentinel {-1} for one-sided rows
                        cols = _cols
                    self.pair_diff_cols[idx] = cols
                    self.pair_text_a[idx] = line_a
                    self.pair_text_b[idx] = line_b
            else:
                # Once edit/formula workbooks are available, use the same
                # value-aware effective horizons as the background cache.  A
                # physical horizon remains the conservative fallback while edit
                # data is still loading, so uncached formulas cannot disappear.
                max_row_a = (
                    int(getattr(self, "_effective_max_row_a", ws_a.max_row or 1))
                    if ws_a_edit is not None else int(ws_a.max_row or 1)
                )
                max_row_b = (
                    int(getattr(self, "_effective_max_row_b", ws_b.max_row or 1))
                    if ws_b_edit is not None else int(ws_b.max_row or 1)
                )

                force_align = bool(getattr(self, "_force_sequence_align", False))
                should_align = (
                    (not getattr(self.app, "merge_conflict_mode", False))
                    and _should_auto_row_align(max_row_a, max_row_b, force=force_align)
                )

                if reuse_row_alignment:
                    self._align_rows_enabled = preserved_align_enabled
                    self.row_pairs = preserved_row_pairs
                    self.mine_to_base_row = preserved_mine_to_base
                    self.theirs_to_base_row = preserved_theirs_to_base
                    self.pair_base_row_override = preserved_base_overrides
                else:
                    self._align_rows_enabled = should_align
                    if self._align_rows_enabled:
                        self.row_pairs = self._build_row_pairs(
                            ws_a,
                            ws_b,
                            force=force_align,
                            max_row_a=max_row_a,
                            max_row_b=max_row_b,
                            ws_a_edit=ws_a_edit,
                            ws_b_edit=ws_b_edit,
                        )
                    else:
                        self.row_pairs = self._build_row_pairs_direct(max_row_a, max_row_b)
                    self.row_pairs = _collapse_one_sided_blank_tail_padding(
                        self.row_pairs,
                        ws_a,
                        ws_b,
                        ws_a_edit,
                        ws_b_edit,
                        max_row_a,
                        max_row_b,
                        self.max_col,
                    )
                    self.mine_to_base_row = {}
                    self.theirs_to_base_row = {}
                if getattr(self.app, "has_base", False) and not reuse_row_alignment:
                    try:
                        ws_base_map = self.app.ws_base_val(self.sheet)
                    except Exception:
                        ws_base_map = None
                    if ws_base_map is not None:
                        if ws_base_edit_ready is not None:
                            base_r, _base_c = _effective_bounds_with_edit(ws_base_map, ws_base_edit_ready)
                        else:
                            base_r = int(ws_base_map.max_row or 1)
                        try:
                            mine_base_pairs = _compute_row_pairs_generic(
                                ws_a,
                                ws_base_map,
                                self.max_col,
                                force=force_align,
                                max_row_a=max_row_a,
                                max_row_b=base_r,
                                ws_a_edit=ws_a_edit,
                                ws_b_edit=ws_base_edit_ready,
                            )
                            mine_base_pairs = _collapse_one_sided_blank_tail_padding(
                                mine_base_pairs,
                                ws_a,
                                ws_base_map,
                                ws_a_edit,
                                ws_base_edit_ready,
                                max_row_a,
                                base_r,
                                self.max_col,
                            )
                            self.mine_to_base_row = _row_map_from_pairs(mine_base_pairs)
                        except Exception:
                            self.mine_to_base_row = {}
                        try:
                            theirs_base_pairs = _compute_row_pairs_generic(
                                ws_b,
                                ws_base_map,
                                self.max_col,
                                force=force_align,
                                max_row_a=max_row_b,
                                max_row_b=base_r,
                                ws_a_edit=ws_b_edit,
                                ws_b_edit=ws_base_edit_ready,
                            )
                            theirs_base_pairs = _collapse_one_sided_blank_tail_padding(
                                theirs_base_pairs,
                                ws_b,
                                ws_base_map,
                                ws_b_edit,
                                ws_base_edit_ready,
                                max_row_b,
                                base_r,
                                self.max_col,
                            )
                            self.theirs_to_base_row = _row_map_from_pairs(theirs_base_pairs)
                        except Exception:
                            self.theirs_to_base_row = {}
                        self.row_pairs = _reconcile_three_way_row_pairs_by_base(
                            self.row_pairs,
                            self.mine_to_base_row,
                            self.theirs_to_base_row,
                            ws_a,
                            ws_b,
                            self.max_col,
                        )
                        self.row_pairs = _split_tail_independent_append_pairs(
                            self.row_pairs,
                            self.mine_to_base_row,
                            self.theirs_to_base_row,
                            ws_a,
                            ws_b,
                            self.max_col,
                        )
                        self.row_pairs = _split_low_similarity_tail_pairs(
                            self.row_pairs,
                            self.mine_to_base_row,
                            self.theirs_to_base_row,
                            ws_a,
                            ws_b,
                            self.max_col,
                        )
                        self.row_pairs, synthetic_base_rows = _augment_three_way_row_pairs_with_base_deletions(
                            self.row_pairs,
                            self.mine_to_base_row,
                            self.theirs_to_base_row,
                            base_r,
                        )
                        self.pair_base_row_override = dict(synthetic_base_rows)
                        self.pair_base_row_override.update(_build_pair_base_row_overrides(
                            self.row_pairs,
                            self.mine_to_base_row,
                            self.theirs_to_base_row,
                            ws_base_map,
                            ws_a,
                            ws_b,
                            self.max_col,
                        ))
                self.row_a_to_pair_idx = {}
                self.row_b_to_pair_idx = {}
                for idx, (ra, rb) in enumerate(self.row_pairs):
                    if ra is not None:
                        self.row_a_to_pair_idx[ra] = idx
                    if rb is not None:
                        self.row_b_to_pair_idx[rb] = idx

                # Pre-scan column widths for aligned display before building any formatted lines.
                ws_base_val_opt = None
                ws_base_edit_opt = None
                if getattr(self.app, "has_base", False):
                    try:
                        ws_base_val_opt = self.app.ws_base_val(self.sheet)
                    except Exception:
                        pass
                    ws_base_edit_opt = ws_base_edit_ready if ws_base_edit_ready is not None else ws_base_val_opt
                used_projection_seed = bool(
                    column_diff_seed_request is not None
                    and self._try_install_column_action_projection_seed(
                        column_diff_seed_request
                    )
                )
                if not used_projection_seed:
                    try:
                        self._rebuild_column_comparison_cache_from_worksheets(
                            ws_a,
                            ws_b,
                            ws_a_edit,
                            ws_b_edit,
                            ws_base_val=ws_base_val_opt,
                            ws_base_edit=ws_base_edit_opt,
                            row_cache_bundle=row_cache_bundle,
                        )
                    except Exception as exc:
                        _dlog(f"column comparison cache fallback: sheet={self.sheet} err={exc}")
                        self._install_column_projection(self._identity_column_comparison_cache())
                if column_diff_seed_request is not None:
                    used_column_diff_seed = self._try_apply_column_action_diff_seed(
                        column_diff_seed_request,
                        ws_a_val=ws_a,
                        ws_b_val=ws_b,
                        ws_a_edit=ws_a_edit,
                        ws_b_edit=ws_b_edit,
                    )
                widths_restored = bool(
                    used_column_diff_seed
                    and getattr(self, "_column_diff_seed_last", {}).get(
                        "widths_restored", False
                    )
                )
                if not widths_restored:
                    _prescan_limit = _FAST_RENDER_ROW_LIMIT if self._is_large_sheet else 0
                    self._prescan_col_widths(
                        ws_a,
                        ws_b,
                        ws_base_val_opt,
                        max_pairs=_prescan_limit,
                        row_cache_bundle=row_cache_bundle,
                    )

                # Large-sheet strategy:
                # - full mode: lazy row compute (first 200 visible rows only)
                # - only-diff mode: block scan from tail to head (1000 rows/block)
                if self._is_large_sheet and bool(self.only_diff_var.get()) and not used_column_diff_seed:
                    self._precompute_large_diff_by_blocks(
                        ws_a,
                        ws_b,
                        ws_a_edit,
                        ws_b_edit,
                        max_row_a,
                        max_row_b,
                        ws_base_val=ws_base_val_opt,
                        ws_base_edit=ws_base_edit_opt,
                    )
                    self._pair_diff_full_exact = True
                elif not self._is_large_sheet:
                    # Read each worksheet once for the foreground rescan.  The
                    # old per-row helper performed four iter_rows calls for
                    # every pair; even with a cached physical horizon that was
                    # the dominant latency of column-action refresh/undo.
                    rows_a_needed = [ra for ra, _rb in self.row_pairs if ra is not None]
                    rows_b_needed = [rb for _ra, rb in self.row_pairs if rb is not None]
                    rows_a_val_all = _read_rows_into_shared_cache(
                        ws_a, rows_a_needed, self.max_col,
                        cache_bundle=row_cache_bundle, cache_key="a_val",
                    )
                    rows_b_val_all = _read_rows_into_shared_cache(
                        ws_b, rows_b_needed, self.max_col,
                        cache_bundle=row_cache_bundle, cache_key="b_val",
                    )
                    rows_a_edit_all = (
                        _read_rows_into_shared_cache(
                            ws_a_edit, rows_a_needed, self.max_col,
                            cache_bundle=row_cache_bundle, cache_key="a_edit",
                        )
                        if ws_a_edit is not None else {}
                    )
                    rows_b_edit_all = (
                        _read_rows_into_shared_cache(
                            ws_b_edit, rows_b_needed, self.max_col,
                            cache_bundle=row_cache_bundle, cache_key="b_edit",
                        )
                        if ws_b_edit is not None else {}
                    )
                    for idx, (ra, rb) in enumerate(self.row_pairs):
                        line_a, line_b, cols = self._build_row_and_diff_pair_from_values(
                            _row_from_cache(rows_a_val_all, ra, self.max_col),
                            _row_from_cache(rows_b_val_all, rb, self.max_col),
                            ra=ra,
                            rb=rb,
                            row_a_edit_vals=_row_from_cache(rows_a_edit_all, ra, self.max_col),
                            row_b_edit_vals=_row_from_cache(rows_b_edit_all, rb, self.max_col),
                        )
                        self.pair_diff_cols[idx] = cols
                        self.pair_text_a[idx] = line_a
                        self.pair_text_b[idx] = line_b
                    self._pair_diff_full_exact = True

            self._data_ready = True
            self._row_model_exact = True
            self._cache_formula_aware = bool(
                ws_a_edit is not None
                and ws_b_edit is not None
                and (
                    not self._is_three_way_enabled()
                    or ws_base_edit_ready is not None
                )
            )

        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            need_full_base_diff = (not self._is_large_sheet) and (bool(self.only_diff_var.get()) or (not self._is_large_sheet))
            if need_full_base_diff:
                added_base_diff = self._ensure_base_diff_cache(
                    max_col=self.max_col,
                    ws_a_val=ws_a,
                    ws_a_edit=ws_a_edit if ws_a_edit is not None else ws_a,
                    ws_base_val=self.app.ws_base_val(self.sheet),
                    ws_base_edit=ws_base_edit_ready if ws_base_edit_ready is not None else self.app.ws_base_val(self.sheet),
                    row_cache_bundle=row_cache_bundle,
                )
                if added_base_diff:
                    self._invalidate_render_cache()
                self._base_diff_full_exact = bool(
                    len(self.pair_base_diff_cols) >= len(self.row_pairs)
                )

        if (
            isinstance(column_diff_seed_request, dict)
            and str(column_diff_seed_request.get("mode") or "") == "restore"
        ):
            self._restore_column_action_comparison_state(
                column_diff_seed_request.get("comparison_state")
            )

        # Build display rows list (pair indices)
        if conflict_cells_by_row is not None:
            # Always show conflict rows only
            rows = []
            for r in sorted(conflict_cells_by_row.keys()):
                idx = self.row_a_to_pair_idx.get(r)
                if idx is not None:
                    rows.append(idx)
            self._full_display_rows = rows
        elif bool(getattr(self, "_only_diff_preview_full", False)):
            # The checkbox already reflects the requested mode, but the exact
            # row set is not published yet. Keep one stable full preview rather
            # than visually reverting or showing a transient partial subset.
            self._full_display_rows = list(range(len(self.row_pairs)))
        elif bool(self.only_diff_var.get()):
            cached_only_diff_rows = self._only_diff_rows_cache if self._has_valid_only_diff_snapshot_cache() else None
            if self.snapshot_only_diff and cached_only_diff_rows is not None and (not rescan):
                self._full_display_rows = self._only_diff_rows_with_touched(cached_only_diff_rows)
            elif self.snapshot_only_diff and self._is_large_sheet and (not rescan):
                started_async = self._start_async_large_only_diff_build()
                if started_async:
                    keep_rows = list(self.display_rows) if self.display_rows else list(self._full_display_rows)
                    self._full_display_rows = keep_rows
                else:
                    # A disk-backed async rebuild is intentionally unavailable
                    # after user edits. Reuse the current in-memory diff maps so
                    # resolved/touched rows remain stable and text is rebuilt
                    # from the edited in-memory workbooks below.
                    fallback_rows = cached_only_diff_rows
                    if fallback_rows is None:
                        fallback_rows = [
                            idx for idx in range(len(self.row_pairs))
                            if self._pair_has_visual_diff(idx)
                        ]
                        self._cache_only_diff_rows_snapshot(
                            fallback_rows,
                            exact=bool(
                                self._pair_diff_full_exact
                                and (
                                    not self._is_three_way_enabled()
                                    or not getattr(self.app, "has_base", False)
                                    or self._base_diff_full_exact
                                )
                            ),
                        )
                    self._full_display_rows = self._only_diff_rows_with_touched(fallback_rows)
            elif (not self.snapshot_only_diff) or rescan or (cached_only_diff_rows is None):
                # Build snapshot: diff rows + touched rows.
                rows = [idx for idx in range(len(self.row_pairs)) if self._pair_has_visual_diff(idx)]

                # Recovery path:
                # In fast-open/background scenarios (especially large sheets), pair_diff_cols can be
                # incomplete when users switch to only-diff. If tab state already says this sheet has
                # diffs but rows is empty, do an on-demand fill so only-diff never becomes an empty page.
                if (not rows) and row_only is None:
                    try:
                        state = int(getattr(self.app, "sheet_diff_state", {}).get(self.sheet, 0))
                    except Exception:
                        state = 0
                    if state > 0:
                        try:
                            _dlog(
                                f"ONLY_DIFF_RECOVERY sheet={self.sheet} "
                                f"large={self._is_large_sheet} pairs={len(self.row_pairs)}"
                            )
                        except Exception:
                            pass
                        if self._is_large_sheet:
                            max_row_a = ws_a.max_row or 1
                            max_row_b = ws_b.max_row or 1
                            self._precompute_large_diff_by_blocks(
                                ws_a, ws_b, ws_a_edit, ws_b_edit, max_row_a, max_row_b
                            )
                        else:
                            for idx, (ra, rb) in enumerate(self.row_pairs):
                                if idx in self.pair_diff_cols:
                                    continue
                                line_a, line_b, cols = self._build_row_and_diff_pair(
                                    ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb
                                )
                                self.pair_diff_cols[idx] = cols
                                self.pair_text_a[idx] = line_a
                                self.pair_text_b[idx] = line_b
                        rows = [idx for idx in range(len(self.row_pairs)) if self._pair_has_visual_diff(idx)]
                        # If recovery found no diffs, the sheet_diff_state was stale.
                        # Clear it so subsequent refreshes do not re-trigger recovery.
                        if (
                            not rows
                            and not self._active_column_comparison_cache().structural_diff_cols
                        ):
                            try:
                                if hasattr(self.app, "sheet_diff_state"):
                                    self.app.sheet_diff_state[self.sheet] = 0
                            except Exception:
                                pass

                self._cache_only_diff_rows_snapshot(
                    rows,
                    exact=bool(
                        self._pair_diff_full_exact
                        and (
                            not self._is_three_way_enabled()
                            or not getattr(self.app, "has_base", False)
                            or self._base_diff_full_exact
                        )
                    ),
                )
                self._full_display_rows = self._only_diff_rows_with_touched(rows)
            else:
                # snapshot mode: keep existing row list stable
                pass
        else:
            self._full_display_rows = list(range(0, len(self.row_pairs)))

        # Fast render: limit initial rows unless user opted to load all
        if self._full_render or (not _FAST_OPEN_ENABLED):
            self.display_rows = list(self._full_display_rows)
        else:
            # reset render limit if full list shrank
            self._render_limit = min(self._render_limit, len(self._full_display_rows)) if self._full_display_rows else _FAST_RENDER_ROW_LIMIT
            if self._full_display_rows:
                target_limit = min(
                    _LARGE_SHEET_INITIAL_ROWS if self._is_large_sheet else _FAST_RENDER_ROW_LIMIT,
                    len(self._full_display_rows),
                )
                if self._render_limit < target_limit:
                    self._render_limit = target_limit
            if (
                (not self._is_large_sheet)
                and len(self._full_display_rows) > _FAST_RENDER_ROW_LIMIT
                and self._render_limit < _FAST_RENDER_ROW_LIMIT
            ):
                self._render_limit = _FAST_RENDER_ROW_LIMIT
            if self._is_large_sheet and rescan:
                action_preview = (
                    _LARGE_DIFF_NAV_PREVIEW_ROWS
                    if (
                        used_column_diff_seed
                        and bool(self.only_diff_var.get())
                    ) else _LARGE_SHEET_INITIAL_ROWS
                )
                self._render_limit = min(action_preview, len(self._full_display_rows)) if self._full_display_rows else action_preview
            self.display_rows = self._full_display_rows[:self._render_limit]
        _dlog(f"  build display_rows: {len(self.display_rows)} / {self.max_row} (only_diff={bool(self.only_diff_var.get())} raw={self.only_diff_var.get()})")

        if self._is_three_way_enabled() and getattr(self.app, "has_base", False) and self.display_rows:
            added_base_diff = self._ensure_base_diff_cache(
                pair_indices=self.display_rows,
                max_col=self.max_col,
                ws_a_val=ws_a,
                ws_a_edit=ws_a_edit if ws_a_edit is not None else ws_a,
                ws_base_val=self.app.ws_base_val(self.sheet),
                ws_base_edit=ws_base_edit_ready if ws_base_edit_ready is not None else self.app.ws_base_val(self.sheet),
                row_cache_bundle=row_cache_bundle,
            )
            if added_base_diff:
                self._invalidate_render_cache()

        # Ensure pair text/diff exists for currently displayed rows (lazy fill)
        if self.display_rows:
            missing = [idx for idx in self.display_rows if idx not in self.pair_text_a or idx not in self.pair_text_b]
            if missing:
                missing_pairs = [
                    self.row_pairs[idx]
                    for idx in missing
                    if 0 <= idx < len(self.row_pairs)
                ]
                missing_rows_a = [ra for ra, _rb in missing_pairs if ra is not None]
                missing_rows_b = [rb for _ra, rb in missing_pairs if rb is not None]
                rows_a_val_missing = _read_rows_into_shared_cache(
                    ws_a, missing_rows_a, self.max_col,
                    cache_bundle=row_cache_bundle, cache_key="a_val",
                )
                rows_b_val_missing = _read_rows_into_shared_cache(
                    ws_b, missing_rows_b, self.max_col,
                    cache_bundle=row_cache_bundle, cache_key="b_val",
                )
                rows_a_edit_missing = _read_rows_into_shared_cache(
                    ws_a_edit, missing_rows_a, self.max_col,
                    cache_bundle=row_cache_bundle, cache_key="a_edit",
                ) if ws_a_edit is not None else {}
                rows_b_edit_missing = _read_rows_into_shared_cache(
                    ws_b_edit, missing_rows_b, self.max_col,
                    cache_bundle=row_cache_bundle, cache_key="b_edit",
                ) if ws_b_edit is not None else {}
                for idx in missing:
                    if idx >= len(self.row_pairs):
                        continue
                    ra, rb = self.row_pairs[idx]
                    line_a, line_b, cols = self._build_row_and_diff_pair_from_values(
                        _row_from_cache(rows_a_val_missing, ra, self.max_col),
                        _row_from_cache(rows_b_val_missing, rb, self.max_col),
                        ra=ra,
                        rb=rb,
                        row_a_edit_vals=_row_from_cache(rows_a_edit_missing, ra, self.max_col),
                        row_b_edit_vals=_row_from_cache(rows_b_edit_missing, rb, self.max_col),
                    )
                    self.pair_diff_cols[idx] = cols
                    self.pair_text_a[idx] = line_a
                    self.pair_text_b[idx] = line_b

        # Lazy text reconstruction may also compute temporary row diffs. For a
        # proved 3-way undo, reapply the compact pre-action channels before any
        # row/cell tags or navigation models consume them.
        if (
            isinstance(column_diff_seed_request, dict)
            and str(column_diff_seed_request.get("mode") or "") == "restore"
        ):
            self._restore_column_action_comparison_state(
                column_diff_seed_request.get("comparison_state")
            )

        self.row_to_line = {r: i + 1 for i, r in enumerate(self.display_rows)}

        if row_only is None:
            try:
                frac = float((self.left.xview() or (0.0, 1.0))[0])
            except Exception:
                frac = 0.0
            try:
                self._render_col_headers()
                # _render_col_headers() resets header xview to 0; restore all panes uniformly.
                self._sync_main_x_to_frac(frac)
                self._sync_c_x_to_frac(frac)
            except Exception:
                pass

        # Partial refresh: update a single excel row if it is visible
        if row_only is not None:
            r = row_only
            pair_idx = self.row_a_to_pair_idx.get(r)
            if pair_idx is None:
                pair_idx = self.row_b_to_pair_idx.get(r)
            if pair_idx is None:
                return
            ra, rb = self.row_pairs[pair_idx]
            # recompute diff cols + cache text for that pair only
            line_a, line_b, cols = self._build_row_and_diff_pair(ws_a, ws_b, ws_a_edit, ws_b_edit, ra, rb)
            self.pair_text_a[pair_idx] = line_a
            self.pair_text_b[pair_idx] = line_b
            if conflict_cells_by_row is not None and ra is not None:
                self.pair_diff_cols[pair_idx] = set(conflict_cells_by_row.get(ra, set()))
            else:
                self.pair_diff_cols[pair_idx] = cols
            if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
                self.pair_base_diff_cols[pair_idx] = self._compute_base_diff_cols_for_pair(
                    pair_idx,
                    (ra, rb),
                    max_col=self.max_col,
                    ws_a_val=ws_a,
                    ws_a_edit=ws_a_edit,
                    ws_base_val=self.app.ws_base_val(self.sheet),
                    ws_base_edit=self.app.ws_base_edit(self.sheet),
                )
            else:
                self.pair_base_diff_cols.pop(pair_idx, None)

            # If only-diff enabled, row might need to be added/removed
            if bool(self.only_diff_var.get()):
                visible = pair_idx in self.row_to_line
                has = self._pair_has_visual_diff(pair_idx)

                # If diffs are resolved but this row was touched, keep it visible as a record.
                keep = (r in self.touched_rows)

                if self.snapshot_only_diff:
                    # Snapshot mode: never auto-remove rows from the list.
                    # If a touched row is not visible (was not in initial snapshot), allow adding it.
                    if (not visible) and keep:
                        self.refresh(row_only=None, rescan=False)
                        return
                else:
                    if visible and (not has) and (not keep):
                        # remove the line
                        line = self.row_to_line[pair_idx]
                        self.left.delete(f"{line}.0", f"{line + 1}.0")
                        if self._is_three_way_enabled():
                            self.base.delete(f"{line}.0", f"{line + 1}.0")
                        self.right.delete(f"{line}.0", f"{line + 1}.0")
                        # rebuild
                        self.refresh(row_only=None, rescan=False)
                        return

                    if (not visible) and (has or keep):
                        # add row: simplest is full rebuild (diff list is small)
                        self.refresh(row_only=None, rescan=False)
                        return

            line = self.row_to_line.get(pair_idx)
            if line is None:
                # not visible
                return

            line_a = self.pair_text_a.get(pair_idx, "")
            line_b = self.pair_text_b.get(pair_idx, "")

            # update text
            self.left.delete(f"{line}.0", f"{line}.end")
            self._render_base_line(line, pair_idx)
            self.right.delete(f"{line}.0", f"{line}.end")
            self.left.insert(f"{line}.0", line_a)
            self.right.insert(f"{line}.0", line_b)

            # clear tags on this line then apply diff highlight (unless touched row resolved)
            for w in (self.left, self.base, self.right):
                w.tag_remove("diffrow", f"{line}.0", f"{line}.end")
                w.tag_remove("diffcell", f"{line}.0", f"{line}.end")

            cols = self._visual_diff_cols_for_pair(pair_idx)
            # If this row was touched and has no diffs anymore, keep it visible but don't show diff highlight.
            show_diff = bool(cols)
            if show_diff:
                self.left.tag_add("diffrow", f"{line}.0", f"{line}.end")
                self.base.tag_add("diffrow", f"{line}.0", f"{line}.end")
                self.right.tag_add("diffrow", f"{line}.0", f"{line}.end")
                base_line = self._build_base_line(pair_idx) if self._is_three_way_enabled() else ""
                left_args, base_args, right_args, _lr, _br, _rr = self._diffcell_tag_args_for_line(
                    line,
                    pair_idx,
                    line_a,
                    base_line,
                    line_b,
                )
                if left_args:
                    self.left.tag_add("diffcell", *left_args)
                if base_args:
                    self.base.tag_add("diffcell", *base_args)
                if right_args:
                    self.right.tag_add("diffcell", *right_args)
                self._clear_diffrow_under_diffcells(left_args, base_args, right_args)
            self._refresh_diff_block_ui()
            # keep fast; do not rebuild sheet nav here
            try:
                self._display_diff_row_count = sum(1 for idx in self.display_rows if self._pair_has_visual_diff(idx))
                self.info.configure(text=self._normal_sheet_info_text())
            except Exception:
                pass
            try:
                self._update_diff_maps()
            except Exception:
                pass
            return

        # Full render (use cache when possible)
        mode_key = "diff" if (conflict_cells_by_row is not None or bool(self.only_diff_var.get())) else "full"
        head = tuple(self.display_rows[:5])
        tail = tuple(self.display_rows[-5:]) if len(self.display_rows) > 5 else tuple(self.display_rows)
        cache_key = (mode_key, self._render_limit, len(self.display_rows), head, tail, self._data_version)
        if row_only is None and (not rescan):
            cached = self._render_cache.get(cache_key)
            if cached is not None:
                text_a, text_b, tag_rows, tag_cells, diff_row_count = cached
                self.left.delete("1.0", "end")
                self.base.delete("1.0", "end")
                self.right.delete("1.0", "end")
                self.left.insert("1.0", text_a)
                self._render_base_full()
                self.right.insert("1.0", text_b)
                self._render_row_headers_full()
                # clear tags
                self.left.tag_remove("diffrow", "1.0", "end")
                self.base.tag_remove("diffrow", "1.0", "end")
                self.right.tag_remove("diffrow", "1.0", "end")
                self.left.tag_remove("diffcell", "1.0", "end")
                self.base.tag_remove("diffcell", "1.0", "end")
                self.right.tag_remove("diffcell", "1.0", "end")
                self.left.tag_remove("paddingrow", "1.0", "end")
                self.base.tag_remove("paddingrow", "1.0", "end")
                self.right.tag_remove("paddingrow", "1.0", "end")
                self.left.tag_remove("paddingcol", "1.0", "end")
                self.base.tag_remove("paddingcol", "1.0", "end")
                self.right.tag_remove("paddingcol", "1.0", "end")
                # apply cached tags in bulk (one Tcl call per tag per widget)
                if tag_rows:
                    cached_diffrow_args = []
                    for line_idx in tag_rows:
                        cached_diffrow_args.extend([f"{line_idx}.0", f"{line_idx}.end"])
                    self.left.tag_add("diffrow", *cached_diffrow_args)
                    self.base.tag_add("diffrow", *cached_diffrow_args)
                    self.right.tag_add("diffrow", *cached_diffrow_args)
                    self.left_ln.tag_add("diffrow", *cached_diffrow_args)
                    self.base_ln.tag_add("diffrow", *cached_diffrow_args)
                    self.right_ln.tag_add("diffrow", *cached_diffrow_args)
                if tag_cells:
                    cached_cell_left = []
                    cached_cell_base = []
                    cached_cell_right = []
                    for line_idx, spans_a, spans_base, spans_b in tag_cells:
                        for s, e in spans_a:
                            cached_cell_left.extend([f"{line_idx}.{s}", f"{line_idx}.{e}"])
                        for s, e in spans_base:
                            cached_cell_base.extend([f"{line_idx}.{s}", f"{line_idx}.{e}"])
                        for s, e in spans_b:
                            cached_cell_right.extend([f"{line_idx}.{s}", f"{line_idx}.{e}"])
                    if cached_cell_left:
                        self.left.tag_add("diffcell", *cached_cell_left)
                    if cached_cell_base:
                        self.base.tag_add("diffcell", *cached_cell_base)
                    if cached_cell_right:
                        self.right.tag_add("diffcell", *cached_cell_right)
                    self._clear_diffrow_under_diffcells(cached_cell_left, cached_cell_base, cached_cell_right)

                # paddingrow: grey slot for one-sided pairs (computed from row_pairs, not cached)
                _padding_left = []
                _padding_right = []
                for _i, _pidx in enumerate(self.display_rows):
                    if _pidx < len(self.row_pairs):
                        _ra, _rb = self.row_pairs[_pidx]
                        _ln = _i + 1
                        if _ra is None:
                            _padding_left.extend([f"{_ln}.0", f"{_ln}.end"])
                        elif _rb is None:
                            _padding_right.extend([f"{_ln}.0", f"{_ln}.end"])
                if _padding_left:
                    self.left.tag_add("paddingrow", *_padding_left)
                if _padding_right:
                    self.right.tag_add("paddingrow", *_padding_right)
                # Placeholder styling follows exact logical slots, including
                # middle insertions/deletions (not only a physical tail).
                _n_lines = len(self.display_rows)
                _pcol_left = self._padding_column_tag_args("A", _n_lines)
                _pcol_base = self._padding_column_tag_args("BASE", _n_lines)
                _pcol_right = self._padding_column_tag_args("B", _n_lines)
                if _pcol_left:
                    self.left.tag_add("paddingcol", *_pcol_left)
                if _pcol_base and self._is_three_way_enabled():
                    self.base.tag_add("paddingcol", *_pcol_base)
                if _pcol_right:
                    self.right.tag_add("paddingcol", *_pcol_right)
                # rownum gutter tags are unused when row headers are separate
                self._refresh_diff_block_ui()

                self._display_diff_row_count = diff_row_count
                self.info.configure(text=self._normal_sheet_info_text())
                self.app.set_sheet_has_diff(
                    self.sheet,
                    diff_row_count > 0 or bool(self._active_column_comparison_cache().structural_diff_cols),
                    confirmed=True,
                )
                self.app.refresh_sheet_nav()
                self._update_diff_nav_state()
                try:
                    self._update_diff_maps()
                except Exception:
                    pass
                return

        # Full render
        self.left.delete("1.0", "end")
        self.base.delete("1.0", "end")
        self.right.delete("1.0", "end")
        self.left.tag_remove("diffrow", "1.0", "end")
        self.base.tag_remove("diffrow", "1.0", "end")
        self.right.tag_remove("diffrow", "1.0", "end")
        self.left.tag_remove("diffcell", "1.0", "end")
        self.base.tag_remove("diffcell", "1.0", "end")
        self.right.tag_remove("diffcell", "1.0", "end")
        self.left.tag_remove("paddingrow", "1.0", "end")
        self.base.tag_remove("paddingrow", "1.0", "end")
        self.right.tag_remove("paddingrow", "1.0", "end")
        self.left.tag_remove("paddingcol", "1.0", "end")
        self.base.tag_remove("paddingcol", "1.0", "end")
        self.right.tag_remove("paddingcol", "1.0", "end")

        # Build full text in memory and insert once (faster)
        lines_a = []
        lines_b = []
        for pair_idx in self.display_rows:
            lines_a.append(self.pair_text_a.get(pair_idx, ""))
            lines_b.append(self.pair_text_b.get(pair_idx, ""))
        self.left.insert("1.0", "\n".join(lines_a) + ("\n" if lines_a else ""))
        lines_base = self._render_base_full()
        self.right.insert("1.0", "\n".join(lines_b) + ("\n" if lines_b else ""))
        self._render_row_headers_full()

        # On some environments/large documents, forcing an idle layout pass improves tag correctness.
        try:
            self.left.update_idletasks()
            self.base.update_idletasks()
            self.right.update_idletasks()
        except Exception:
            pass

        # Restore scroll position if we just appended more rows
        if self._pending_yview is not None:
            try:
                self.left.yview_moveto(self._pending_yview)
                if self._is_three_way_enabled():
                    self.base.yview_moveto(self._pending_yview)
                self.right.yview_moveto(self._pending_yview)
            except Exception:
                pass
            self._pending_yview = None

        if self._is_three_way_enabled() and getattr(self.app, "has_base", False):
            added_base_diff = self._ensure_base_diff_cache(
                pair_indices=self.display_rows,
                max_col=self.max_col,
                ws_a_val=ws_a,
                ws_a_edit=ws_a_edit if ws_a_edit is not None else ws_a,
                ws_base_val=self.app.ws_base_val(self.sheet),
                ws_base_edit=ws_base_edit_ready if ws_base_edit_ready is not None else self.app.ws_base_val(self.sheet),
                row_cache_bundle=row_cache_bundle,
            )
            if added_base_diff:
                self._invalidate_render_cache()

        diff_row_count = 0
        tag_rows = []
        tag_cells = []
        # Collect all tag ranges first; apply in bulk (one Tcl call per tag instead of N).
        # tag_add(tagName, index1, *args) accepts multiple index pairs in a single call.
        diffrow_args = []
        diffcell_args_left = []
        diffcell_args_base = []
        diffcell_args_right = []
        for line_idx, pair_idx in enumerate(self.display_rows, start=1):
            ra, rb = self.row_pairs[pair_idx] if pair_idx < len(self.row_pairs) else (None, None)
            cols = self._visual_diff_cols_for_pair(pair_idx)
            if cols:
                diff_row_count += 1
                diffrow_args.extend([f"{line_idx}.0", f"{line_idx}.end"])
                tag_rows.append(line_idx)

                line_a = lines_a[line_idx - 1] if (line_idx - 1) < len(lines_a) else ""
                line_b = lines_b[line_idx - 1] if (line_idx - 1) < len(lines_b) else ""
                base_line = (
                    lines_base[line_idx - 1]
                    if self._is_three_way_enabled() and (line_idx - 1) < len(lines_base)
                    else ""
                )
                left_args, base_args, right_args, left_ranges, base_ranges, right_ranges = self._diffcell_tag_args_for_line(
                    line_idx,
                    pair_idx,
                    line_a,
                    base_line,
                    line_b,
                )
                diffcell_args_left.extend(left_args)
                diffcell_args_base.extend(base_args)
                diffcell_args_right.extend(right_args)
                if left_ranges or base_ranges or right_ranges:
                    tag_cells.append((line_idx, left_ranges, base_ranges, right_ranges))

        # Apply all diffrow tags in one call per widget
        if diffrow_args:
            self.left.tag_add("diffrow", *diffrow_args)
            self.base.tag_add("diffrow", *diffrow_args)
            self.right.tag_add("diffrow", *diffrow_args)
            self.left_ln.tag_add("diffrow", *diffrow_args)
            self.base_ln.tag_add("diffrow", *diffrow_args)
            self.right_ln.tag_add("diffrow", *diffrow_args)
            for line_idx in tag_rows:
                try:
                    pidx = self.display_rows[line_idx - 1]
                    self._apply_rownum_diff_tag_line(line_idx, pidx)
                except Exception:
                    pass
        # Apply all diffcell tags in one call per widget
        if diffcell_args_left:
            self.left.tag_add("diffcell", *diffcell_args_left)
        if diffcell_args_base:
            self.base.tag_add("diffcell", *diffcell_args_base)
        if diffcell_args_right:
            self.right.tag_add("diffcell", *diffcell_args_right)
        self._clear_diffrow_under_diffcells(diffcell_args_left, diffcell_args_base, diffcell_args_right)
        # Apply paddingrow (grey) to empty slots of one-sided pairs
        _padding_left = []
        _padding_right = []
        for _i, _pidx in enumerate(self.display_rows):
            if _pidx < len(self.row_pairs):
                _ra, _rb = self.row_pairs[_pidx]
                _ln = _i + 1
                if _ra is None:
                    _padding_left.extend([f"{_ln}.0", f"{_ln}.end"])
                elif _rb is None:
                    _padding_right.extend([f"{_ln}.0", f"{_ln}.end"])
        if _padding_left:
            self.left.tag_add("paddingrow", *_padding_left)
        if _padding_right:
            self.right.tag_add("paddingrow", *_padding_right)
        # paddingcol: exact missing-side slots in shared logical geometry.
        _n_lines = len(self.display_rows)
        _pcol_left = self._padding_column_tag_args("A", _n_lines)
        _pcol_base = self._padding_column_tag_args("BASE", _n_lines)
        _pcol_right = self._padding_column_tag_args("B", _n_lines)
        if _pcol_left:
            self.left.tag_add("paddingcol", *_pcol_left)
        if _pcol_base and self._is_three_way_enabled():
            self.base.tag_add("paddingcol", *_pcol_base)
        if _pcol_right:
            self.right.tag_add("paddingcol", *_pcol_right)
        # row-number styling handled by dedicated row-header widgets
        self._refresh_diff_block_ui()

        self._display_diff_row_count = diff_row_count
        self.info.configure(text=self._normal_sheet_info_text())

        self.app.set_sheet_has_diff(
            self.sheet,
            diff_row_count > 0 or bool(self._active_column_comparison_cache().structural_diff_cols),
            confirmed=True,
        )
        self.app.refresh_sheet_nav()
        self._update_diff_nav_state()
        try:
            self._update_diff_maps()
        except Exception:
            pass

        # Cache rendered result for fast toggle
        if row_only is None:
            text_a = "\n".join(lines_a) + ("\n" if lines_a else "")
            text_b = "\n".join(lines_b) + ("\n" if lines_b else "")
            self._render_cache[cache_key] = (text_a, text_b, tag_rows, tag_cells, diff_row_count)
        self._refresh_interaction_gate()


class SowMergeApp:
    def __init__(self, file_a: str, file_b: str, merge_mode: bool = False, merged_path: str | None = None,
                 base_path: str | None = None,
                 merge_conflict_cells_by_sheet: dict | None = None, merge_conflict_mode: bool = False,
                 raw_base: str | None = None, raw_mine: str | None = None, raw_theirs: str | None = None,
                 launch_context: MergeLaunchContext | None = None,
                 startup_outcome: StartupMergeOutcome | None = None,
                 role_mode: str = ""):
        # Sequential GUI instances are common in smoke tests and can also occur
        # in host integrations. Collect destroyed Tk object cycles on the UI
        # thread before any new background XML parser can trigger that GC.
        gc.collect()
        self._startup_trace = UiTrace()
        self._startup_trace.mark("app-init")
        self._is_closing = False
        self._sheet_filter_model = None
        self._sheet_filter_programmatic_select = False
        self._sheet_filter_initializing = True
        self._background_threads_lock = threading.Lock()
        self._background_threads: set[threading.Thread] = set()
        self._interactive_action_lock = threading.Lock()
        self._interactive_action_depth = 0
        self._interactive_action_event = threading.Event()
        self._interactive_owner_stack = []
        self._priority_diff_lock = threading.Lock()
        self._priority_diff_depth = 0
        self._priority_diff_event = threading.Event()
        self._exact_worker_lock = threading.Lock()
        self._priority_exact_owner = None
        self._exact_broker_lock = threading.Lock()
        self._exact_broker_pending = None
        self._exact_broker_running = False
        self._exact_broker_thread = None
        self._only_diff_progress_owner = None
        self._only_diff_progress_win = None
        self._only_diff_progress_stage_var = None
        self._only_diff_progress_detail_var = None
        self._only_diff_progress_bar = None
        self._only_diff_progress_cancel_btn = None
        self._only_diff_progress_started = 0.0
        self._only_diff_tab_states = {}
        self._sheet_switch_guard = False
        # GUI callers may construct the app directly with SVN sidecars whose
        # trailing ``.rN`` hides the real workbook extension from openpyxl.
        # Stable copies are an implementation detail; raw identities stay in
        # the launch context/labels below.
        self.merge_mode = bool(merge_mode)
        self.raw_base = raw_base
        self.raw_mine = raw_mine
        self.raw_theirs = raw_theirs
        self.role_mode = str(role_mode or "")
        self.diff_base_mine_mode = bool(
            not self.merge_mode and self.raw_base and self.raw_mine
        )
        self.file_a = _ensure_xlsx_copy(file_a) if file_a else file_a
        # In a VCS two-way launch, keep B bound to the real working file even
        # when the test/host path lives under %TEMP% (where the generic stable
        # copy helper would otherwise clone it).  SVN revision sidecars still
        # use a safe normalized copy.
        raw_mine_name = os.path.basename(str(self.raw_mine or ""))
        raw_mine_is_working_file = bool(
            self.diff_base_mine_mode
            and self.raw_mine
            and os.path.isfile(str(self.raw_mine))
            and not re.search(r"(?:\.merge-(?:left|right))?\.r\d+$", raw_mine_name, re.IGNORECASE)
        )
        self.file_b = (
            str(self.raw_mine)
            if raw_mine_is_working_file
            else (_ensure_xlsx_copy(file_b) if file_b else file_b)
        )
        self.base_path = _ensure_xlsx_copy(base_path) if base_path else base_path
        self.has_base = bool(base_path and os.path.exists(base_path))
        self.launch_context = launch_context
        self.startup_outcome = startup_outcome or StartupMergeOutcome()
        self.merge_candidate_path = file_a if (startup_outcome and startup_outcome.candidate_path) else None
        self.workspace_chrome_color = WORKSPACE_CHROME_COLORS.get(
            getattr(launch_context, "scenario", MergeScenario.TWO_WAY),
            WORKSPACE_CHROME_COLORS[MergeScenario.TWO_WAY],
        )
        self.workspace_color = self.workspace_chrome_color
        self.merge_mode = bool(merge_mode)
        self.diff_base_mine_mode = bool(
            not self.merge_mode and self.raw_base and self.raw_mine
        )
        self.merged_path = merged_path
        self.merge_conflict_cells_by_sheet = merge_conflict_cells_by_sheet or {}
        self.merge_conflict_mode = merge_conflict_mode
        self.initial_conflict_cell_count = sum(
            len(cols)
            for rows in self.merge_conflict_cells_by_sheet.values()
            for cols in rows.values()
        )
        self.user_touched_conflicts = False
        # In 3-way manual merge mode, persist only explicitly operated A-side cells on save.
        # key: (sheet, row, col) -> edit value to write
        self.manual_a_cell_ops: dict[tuple[str, int, int], object] = {}
        self.manual_b_cell_ops: dict[tuple[str, int, int], object] = {}
        # Same-formula cells can have intentionally adopted cached results in
        # manual-calculation workbooks. Keep them separate from formula edits.
        self.manual_a_formula_cache_ops: dict[tuple[str, int, int], object] = {}
        self.manual_b_formula_cache_ops: dict[tuple[str, int, int], object] = {}
        self.manual_a_row_ops: list[dict[str, object]] = []
        self.manual_b_row_ops: list[dict[str, object]] = []
        self.manual_a_column_ops: list[dict[str, object]] = []
        self.manual_b_column_ops: list[dict[str, object]] = []
        self._manual_column_action_seq = 0
        self._manual_column_op_seq = 0
        self._manual_structural_op_seq = 0
        self.manual_sheet_ops: list[dict[str, object]] = []
        self.auto_sheet_ops: list[dict[str, object]] = []
        self.sheet_level_conflicts: list[dict[str, object]] = []
        self.sheet_level_summary: list[str] = []
        self._merge_mine_snapshot = None
        self.undo_stack = []
        self._undo_group_capture = None
        self._auto_recalc_started = False
        # append debug session marker each run (do not truncate old evidence)
        try:
            with open(_DEBUG_LOG_PATH, "a", encoding="utf-8") as f:
                f.write("\n" + "=" * 72 + "\n")
                f.write(f"SESSION {datetime.now().isoformat(sep=' ', timespec='seconds')}\n")
                f.write(f"{APP_NAME} {APP_VERSION} [{APP_BUILD_TAG}]\n")
                f.write(f"A={self.file_a}\nB={self.file_b}\n")
        except Exception:
            pass
        # load settings
        self.settings = {}
        self.only_diff_default = 0
        try:
            os.makedirs(os.path.dirname(_SETTINGS_PATH), exist_ok=True)
            if os.path.exists(_SETTINGS_PATH):
                with open(_SETTINGS_PATH, "r", encoding="utf-8") as f:
                    self.settings = json.load(f) or {}
            self.only_diff_default = int(self.settings.get("only_diff", 0))
        except Exception as e:
            _dlog(f"settings load failed: {e}")

        _dlog(f"SowMergeApp init only_diff_default={self.only_diff_default}")

        # Fast open: load value workbooks first; defer editable workbooks until first modification/save.
        self._wb_a_edit = None
        self._wb_b_edit = None
        self._wb_base_edit = None
        self._edit_loaded_event = threading.Event()
        self._initial_sheet_ready_event = threading.Event()
        self._edit_preload_active_event = threading.Event()
        self._edit_loading_started = False
        self._edit_preload_runner = None
        self._edit_fallback_lock = threading.Lock()
        self._wb_a_val = None
        self._wb_b_val = None
        self._wb_base_val = None
        self._value_workbooks_regular = False
        self._value_workbook_upgrade_lock = threading.Lock()

        # Keep the editable loader available for the first explicit mutation,
        # but defer starting it until that request so it cannot compete with
        # the first visible Sheet's read-only comparison.
        def _preload_edit():
            loaded_ok = False
            try:
                _dlog("preload edit workbooks waiting for initial Sheet")
                while not self._initial_sheet_ready_event.wait(timeout=0.05):
                    if self._is_closing:
                        return
                _dlog("preload edit workbooks (background) start")
                loaded_ok = self._load_edit_workbooks_owned()
            except Exception as e:
                _dlog(f"preload edit failed: {e}")
            finally:
                if loaded_ok:
                    queue_ui = getattr(self, "_queue_ui_task", None)
                    if callable(queue_ui):
                        queue_ui(self._refresh_loaded_views_after_edit_ready)
                self._edit_loaded_event.set()
                _dlog("preload edit workbooks (background) done")

        def _load_initial_state(report):
            try:
                self._startup_trace.mark("value-load-start")
                report("正在打开 Excel 合并工具", f"加载 mine：{os.path.basename(self.file_a)}", 8)
                t0 = datetime.now()
                self._file_a_val_path = _prepare_val_path(self.file_a)
                self._wb_a_val = load_workbook(
                    self._file_a_val_path,
                    data_only=True,
                    read_only=True,
                    keep_links=False,
                )
                _dlog(f"load wb_a_val: {(datetime.now()-t0).total_seconds():.3f}s")

                mine_working_path = self._mine_working_path()
                side_label = "theirs" if self.merge_mode else "mine"
                report("正在打开 Excel 合并工具", f"加载 {side_label}：{os.path.basename(mine_working_path)}", 30)
                t0 = datetime.now()
                self._file_b_val_path = _prepare_val_path(mine_working_path)
                self._wb_b_val = load_workbook(
                    self._file_b_val_path,
                    data_only=True,
                    read_only=True,
                    keep_links=False,
                )
                _dlog(f"load wb_b_val: {(datetime.now()-t0).total_seconds():.3f}s")

                if self.has_base:
                    report("正在打开 Excel 合并工具", f"加载 base：{os.path.basename(self.base_path)}", 52)
                    t0 = datetime.now()
                    self._file_base_val_path = _prepare_val_path(self.base_path)
                    self._wb_base_val = load_workbook(
                        self._file_base_val_path,
                        data_only=True,
                        read_only=True,
                        keep_links=False,
                    )
                    _dlog(f"load wb_base_val: {(datetime.now()-t0).total_seconds():.3f}s")

                    report("正在准备三方合并", "创建 mine 安全快照...", 68)
                    try:
                        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
                        snap = os.path.join(
                            tempfile.gettempdir(),
                            f"{APP_NAME}_mine_snapshot_{os.getpid()}_{ts}{_workbook_ext(self.file_a)}",
                        )
                        shutil.copy2(self.file_a, snap)
                        self._merge_mine_snapshot = snap
                        _dlog(f"mine snapshot created: {snap}")
                    except Exception as e:
                        _dlog(f"mine snapshot failed: {e}")

                report("正在分析工作簿结构", "读取 Sheet 列表并判断整表新增、删除...", 76)
                self._refresh_sheet_catalog()
                self._startup_trace.mark("sheet-catalog-ready")
                if self._wb_a_edit is None or self._wb_b_edit is None or (self.has_base and self._wb_base_edit is None):
                    # Do not compete with the first visible Sheet's XML
                    # comparison.  The editable workbooks are started on the
                    # first explicit mutation/save request instead; browsing
                    # remains read-only and responsive until then.
                    self._edit_preload_runner = _preload_edit
                    self._edit_loading_started = False
                else:
                    self._edit_loaded_event.set()
                report(
                    "工作簿值数据加载完成",
                    f"共 {len(self.display_sheets)} 个 Sheet；公式、样式和批注将在后台继续预载...",
                    100,
                )
                self._startup_trace.mark("value-load-ready")
            except Exception:
                _wbs_close(self._wb_a_val, self._wb_b_val, self._wb_base_val)
                raise

        _run_startup_progress_task(
            "Excel 合并工具 - 正在打开",
            "正在读取工作簿，请稍候...",
            _load_initial_state,
        )

        self.modified_a = False
        self.modified_b = False
        self.modified_sheets_a = set()
        self.modified_sheets_b = set()
        self.difference_items: tuple[DifferenceItem, ...] = ()
        self._difference_processed: set[str] = set()
        self.sheet_diff_counts: dict[str, int] = {}
        self.sheet_diff_total_counts: dict[str, int] = {}
        self._diff_browser = None

        self.root = _take_startup_progress_root()
        self._startup_trace.mark("startup-window-ready")
        self._window_title_suffix = f"{APP_NAME} {APP_VERSION} [{APP_BUILD_TAG}]"
        self.root.title(self._window_title_suffix)
        self.root.resizable(True, True)
        try:
            configure_ttk_style(self.root)
        except Exception:
            pass
        self._configure_workspace_chrome()
        if self.merge_mode:
            self.root.title(f"{self._window_title_suffix}（SVN 合并）")
        else:
            self.root.title(f"{self._window_title_suffix}（差异对比）")
        self.root.geometry("1450x860")
        self._intended_window_state = "zoomed"

        self._root_after_ids: set[str] = set()
        try:
            self.root.protocol("WM_DELETE_WINDOW", self._request_close)
        except Exception:
            pass

        self._build_ui()
        self._startup_trace.mark("main-ui-built")
        self._safe_root_after(0, self._ensure_only_diff_progress_dialog)
        self._ui_heartbeat_last = time.perf_counter()
        self._ui_heartbeat_max_gap = 0.0
        self._ui_heartbeat_samples = 0

        def _ui_heartbeat():
            if self._is_closing:
                return
            now = time.perf_counter()
            gap = max(0.0, now - self._ui_heartbeat_last)
            self._ui_heartbeat_last = now
            self._ui_heartbeat_max_gap = max(self._ui_heartbeat_max_gap, gap)
            self._ui_heartbeat_samples += 1
            if gap > 0.2:
                try:
                    _dlog(
                        f"UI_HEARTBEAT_GAP ms={gap * 1000.0:.1f} "
                        f"state={self.root.state()} geometry={self.root.geometry()} "
                        f"sheet={getattr(self, 'selected_sheet', '')}"
                    )
                except Exception:
                    pass
            self._safe_root_after(50, _ui_heartbeat)

        def _show_main_window_after_layout():
            if self._is_closing:
                return
            try:
                self.root.update_idletasks()
                _dlog(
                    f"WINDOW_STATE stage=before-show state={self.root.state()} "
                    f"geometry={self.root.geometry()}"
                )
                self.root.deiconify()
                self.root.state(self._intended_window_state)
                self.root.update_idletasks()
                _dlog(
                    f"WINDOW_STATE stage=after-show state={self.root.state()} "
                    f"geometry={self.root.geometry()}"
                )
                durations = self._startup_trace.durations()
                _dlog("STARTUP_TRACE " + " ".join(f"{key}={value * 1000.0:.1f}ms" for key, value in durations.items()))
            except Exception as exc:
                _dlog(f"main window show failed: {exc}")

        self._safe_root_after(0, _show_main_window_after_layout)
        self._safe_root_after(50, _ui_heartbeat)
        self._schedule_auto_recalc()

    def _configure_workspace_chrome(self):
        """Install styles for surrounding UI chrome without touching sheet cells."""
        color = getattr(self, "workspace_chrome_color", WORKSPACE_CHROME_COLORS[MergeScenario.TWO_WAY])
        try:
            self.root.configure(bg=THEME.window_bg)
        except Exception:
            pass
        try:
            style = configure_ttk_style(self.root)
            # Scenario color is an accent for the status chrome only.  Keeping
            # the rest neutral makes the spreadsheet data and conflict colors
            # carry the visual hierarchy.
            style.configure("TFrame", background=THEME.window_bg)
            style.configure("TLabel", background=THEME.window_bg, foreground=THEME.text)
            style.configure("TLabelframe", background=THEME.panel_bg)
            style.configure("TLabelframe.Label", background=THEME.panel_bg, foreground=THEME.text)
            style.configure("TCheckbutton", background=THEME.window_bg, foreground=THEME.text)
            style.configure("MergeChrome.TFrame", background=THEME.window_bg)
            style.configure("MergeChrome.TLabel", background=THEME.window_bg, foreground=THEME.secondary_text)
            style.configure(
                "Workspace.Title.TLabel",
                background=THEME.window_bg,
                foreground=THEME.text,
                font=(THEME.font_family, 13, "bold"),
            )
            style.configure(
                "Workspace.Subtitle.TLabel",
                background=THEME.window_bg,
                foreground=THEME.secondary_text,
                font=(THEME.font_family, 9),
            )
            style.configure(
                "Workspace.Status.TFrame",
                background=THEME.panel_bg,
                relief="solid",
                borderwidth=1,
            )
            style.configure(
                "Workspace.Status.TLabel",
                background=THEME.panel_bg,
                foreground=THEME.secondary_text,
                padding=(8, 4),
            )
            style.configure("MergeChrome.TNotebook", background=color, bordercolor=color)
            # Notebook pages remain the lazy-loading host, but their duplicate
            # tab rows are hidden. The lower Sheet strip is the sole navigator.
            client_only_layout = [("Notebook.client", {"sticky": "nswe"})]
            style.layout("SheetHost.TNotebook", client_only_layout)
            style.configure("SheetHost.TNotebook", background=THEME.window_bg, borderwidth=0)
            # C has one user-visible view; hide its otherwise empty tab chrome.
            style.layout("CompactPanel.TNotebook", client_only_layout)
            style.configure("CompactPanel.TNotebook", background=THEME.window_bg, borderwidth=0)
            style.configure("MergeChrome.TPanedwindow", background=THEME.window_bg)
        except Exception as exc:
            _dlog(f"workspace chrome style failed: {exc}")

    def _sheet_names_for_side(self, side: str) -> list[str]:
        side = str(side or "").upper()
        if side == "A":
            wb = getattr(self, "_wb_a_val", None)
        elif side in ("B", "THEIRS"):
            wb = getattr(self, "_wb_b_val", None)
        elif side == "BASE":
            wb = getattr(self, "_wb_base_val", None)
        else:
            wb = None
        try:
            return list(getattr(wb, "sheetnames", []) or [])
        except Exception:
            return []

    def _refresh_sheet_catalog(self, *, reset_filter: bool = False):
        names_a = self._sheet_names_for_side("A")
        names_b = self._sheet_names_for_side("B")
        names_base = self._sheet_names_for_side("BASE")
        set_a = set(names_a)
        set_b = set(names_b)
        set_base = set(names_base)

        ordered = []
        for seq in (names_a, names_b, names_base):
            for name in seq:
                if name not in ordered:
                    ordered.append(name)

        if self.merge_conflict_mode and self.merge_conflict_cells_by_sheet:
            conflict_sheets = set(self.merge_conflict_cells_by_sheet.keys())
            ordered = [s for s in ordered if s in conflict_sheets]

        self.common_sheets = sorted(set_a & set_b)
        if self.merge_conflict_mode and self.merge_conflict_cells_by_sheet:
            self.common_sheets = [s for s in self.common_sheets if s in set(self.merge_conflict_cells_by_sheet.keys())]
        self.only_a = sorted(set_a - set_b)
        self.only_b = sorted(set_b - set_a)
        self.display_sheets = ordered
        self.compare_sheets = [s for s in ordered if (s in set_a and s in set_b)]
        self.sheet_meta: dict[str, dict[str, object]] = {}
        for s in ordered:
            has_a = s in set_a
            has_b = s in set_b
            has_base = s in set_base
            self.sheet_meta[s] = {
                "has_a": has_a,
                "has_b": has_b,
                "has_base": has_base,
                "view_mode": "normal" if (has_a and has_b) else "missing_sheet",
            }
        self.sheet_diff_state = {s: int(getattr(self, "sheet_diff_state", {}).get(s, 0)) for s in ordered}
        previous_confirmed = set(getattr(self, "_sheet_diff_confirmed", set()) or set())
        self._sheet_diff_confirmed = {s for s in previous_confirmed if s in self.sheet_diff_state}
        self._recompute_auto_sheet_ops()
        if self._sheet_filter_model is None:
            from .sheet_filter import SheetFilterModel

            self._sheet_filter_model = SheetFilterModel(self.display_sheets)
        elif reset_filter:
            self._sheet_filter_model.reset(self.display_sheets)
        else:
            self._sheet_filter_model.sync_names(self.display_sheets)

    def _recompute_auto_sheet_ops(self):
        self.auto_sheet_ops = []
        self.sheet_level_conflicts = []
        self.sheet_level_summary = []
        if not (self.merge_mode and self.has_base):
            return
        set_a = set(self._sheet_names_for_side("A"))
        set_b = set(self._sheet_names_for_side("B"))
        set_base = set(self._sheet_names_for_side("BASE"))
        ordered = list(getattr(self, "display_sheets", []) or [])
        for sheet in ordered:
            in_a = sheet in set_a
            in_b = sheet in set_b
            in_base = sheet in set_base
            if in_b and (not in_a) and (not in_base):
                self.auto_sheet_ops.append({"kind": "copy_sheet", "sheet": sheet, "source_side": "B", "target_side": "A"})
                self.sheet_level_summary.append(f"自动并入 theirs 新增 Sheet: {sheet}")
            elif in_base and (not in_a) and (not in_b):
                self.sheet_level_summary.append(f"保留双方均已删除的 Sheet: {sheet}")
            elif in_base and in_a and (not in_b):
                if self._sheet_values_equal("A", "BASE", sheet):
                    self.auto_sheet_ops.append({"kind": "delete_sheet", "sheet": sheet, "target_side": "A"})
                    self.sheet_level_summary.append(f"自动删除 theirs 已删除且 mine 未修改的 Sheet: {sheet}")
                else:
                    self.sheet_level_conflicts.append({"kind": "sheet_deleted_or_missing_in_theirs", "sheet": sheet})
            elif in_base and in_b and (not in_a):
                if self._sheet_values_equal("B", "BASE", sheet):
                    # Mine deleted the sheet while theirs kept base unchanged:
                    # preserve the local deletion instead of silently restoring it.
                    self.sheet_level_summary.append(f"保留 mine 已删除、theirs 未修改的 Sheet: {sheet}")
                else:
                    # Mine deleted while theirs modified: neither side can be
                    # chosen safely. Keep mine by default and surface a conflict.
                    self.sheet_level_conflicts.append({
                        "kind": "sheet_deleted_in_mine_modified_in_theirs",
                        "sheet": sheet,
                    })
            elif in_a and (not in_base) and (not in_b):
                self.sheet_level_summary.append(f"保留 mine 独有 Sheet: {sheet}")

    def get_sheet_meta(self, sheet: str) -> dict[str, object]:
        return dict(getattr(self, "sheet_meta", {}).get(sheet, {}))

    def _sheet_values_equal(self, side_a: str, side_b: str, sheet: str) -> bool:
        ws_a = self.ws_for_side(side_a, sheet, edit=False, allow_missing=True)
        ws_b = self.ws_for_side(side_b, sheet, edit=False, allow_missing=True)
        if ws_a is None or ws_b is None:
            return False
        ws_a_edit = self.ws_for_side(side_a, sheet, edit=True, allow_missing=True)
        ws_b_edit = self.ws_for_side(side_b, sheet, edit=True, allow_missing=True)
        if ws_a_edit is None or ws_b_edit is None:
            return False
        max_row = max(ws_a.max_row or 1, ws_b.max_row or 1)
        max_col = max(
            ws_a.max_column or 1,
            ws_b.max_column or 1,
            ws_a_edit.max_column or 1,
            ws_b_edit.max_column or 1,
        )
        try:
            if {str(rng) for rng in ws_a_edit.merged_cells.ranges} != {
                str(rng) for rng in ws_b_edit.merged_cells.ranges
            }:
                return False
            if str(ws_a_edit.freeze_panes or "") != str(ws_b_edit.freeze_panes or ""):
                return False
            if str(getattr(ws_a_edit.auto_filter, "ref", "") or "") != str(
                getattr(ws_b_edit.auto_filter, "ref", "") or ""
            ):
                return False

            def _row_dim_key(dim):
                return (
                    getattr(dim, "height", None), getattr(dim, "hidden", None),
                    getattr(dim, "outlineLevel", None), getattr(dim, "collapsed", None),
                    getattr(dim, "style_id", None), getattr(dim, "thickTop", None),
                    getattr(dim, "thickBot", None),
                )

            row_keys = set(ws_a_edit.row_dimensions) | set(ws_b_edit.row_dimensions)
            for key in row_keys:
                if _row_dim_key(ws_a_edit.row_dimensions[key]) != _row_dim_key(ws_b_edit.row_dimensions[key]):
                    return False

            def _col_dim_key(dim):
                return (
                    getattr(dim, "width", None), getattr(dim, "hidden", None),
                    getattr(dim, "bestFit", None), getattr(dim, "outlineLevel", None),
                    getattr(dim, "collapsed", None), getattr(dim, "style_id", None),
                    getattr(dim, "min", None), getattr(dim, "max", None),
                )

            col_keys = set(ws_a_edit.column_dimensions) | set(ws_b_edit.column_dimensions)
            for key in col_keys:
                if _col_dim_key(ws_a_edit.column_dimensions[key]) != _col_dim_key(ws_b_edit.column_dimensions[key]):
                    return False
        except Exception:
            # This predicate controls destructive auto-delete. If structure
            # cannot be compared, fail closed and surface a sheet conflict.
            return False

        rows_a = ws_a.iter_rows(min_row=1, max_row=max_row, min_col=1, max_col=max_col, values_only=True)
        rows_b = ws_b.iter_rows(min_row=1, max_row=max_row, min_col=1, max_col=max_col, values_only=True)
        rows_a_edit = ws_a_edit.iter_rows(min_row=1, max_row=max_row, min_col=1, max_col=max_col, values_only=False)
        rows_b_edit = ws_b_edit.iter_rows(min_row=1, max_row=max_row, min_col=1, max_col=max_col, values_only=False)
        for row_a, row_b, row_a_edit, row_b_edit in zip(rows_a, rows_b, rows_a_edit, rows_b_edit):
            for va, vb, cell_a_edit, cell_b_edit in zip(row_a, row_b, row_a_edit, row_b_edit):
                va_edit = cell_a_edit.value
                vb_edit = cell_b_edit.value
                try:
                    if cell_a_edit.data_type != cell_b_edit.data_type:
                        return False
                    if cell_a_edit._style != cell_b_edit._style:
                        return False
                    comment_a = cell_a_edit.comment
                    comment_b = cell_b_edit.comment
                    if (
                        getattr(comment_a, "text", None), getattr(comment_a, "author", None)
                    ) != (
                        getattr(comment_b, "text", None), getattr(comment_b, "author", None)
                    ):
                        return False
                    link_a = cell_a_edit.hyperlink
                    link_b = cell_b_edit.hyperlink
                    if (
                        getattr(link_a, "target", None), getattr(link_a, "location", None),
                        getattr(link_a, "tooltip", None), getattr(link_a, "display", None),
                    ) != (
                        getattr(link_b, "target", None), getattr(link_b, "location", None),
                        getattr(link_b, "tooltip", None), getattr(link_b, "display", None),
                    ):
                        return False
                except Exception:
                    return False
                formula_a = _formula_text(va_edit)
                formula_b = _formula_text(vb_edit)
                if formula_a or formula_b:
                    if not (formula_a and formula_b and _same_formula(va_edit, vb_edit)):
                        return False
                _display_a, _display_b, equal = _cell_display_and_equal_from_values(
                    va, vb, va_edit, vb_edit
                )
                if not equal:
                    return False
        return True

    def ws_for_side(self, side: str, sheet: str, edit: bool = False, allow_missing: bool = False):
        side = str(side or "").upper()
        if side == "A":
            getter = self.ws_a_edit if edit else self.ws_a_val
        elif side in ("B", "THEIRS"):
            getter = self.ws_b_edit if edit else self.ws_b_val
        elif side == "BASE":
            getter = self.ws_base_edit if edit else self.ws_base_val
        else:
            getter = None
        if getter is None:
            return None
        try:
            return getter(sheet)
        except Exception:
            if allow_missing:
                return None
            raise

    def _start_background_thread(self, target, *, name: str):
        """Start and track a worker so shutdown cannot orphan workbook/Tk state."""
        if getattr(self, "_is_closing", False):
            return None

        def _run_tracked():
            try:
                target()
            finally:
                try:
                    with self._background_threads_lock:
                        self._background_threads.discard(threading.current_thread())
                except Exception:
                    pass

        thread = threading.Thread(target=_run_tracked, daemon=True, name=name)
        with self._background_threads_lock:
            if self._is_closing:
                return None
            self._background_threads.add(thread)
        try:
            thread.start()
        except Exception:
            with self._background_threads_lock:
                self._background_threads.discard(thread)
            raise
        return thread

    def _begin_interactive_action(self, owner_view=None):
        """Pause optional background scans while the user is changing data."""
        with self._interactive_action_lock:
            self._interactive_action_depth += 1
            owner_generation = None
            if owner_view is not None:
                owner_generation = int(
                    getattr(owner_view, "_lifecycle_generation", -1)
                )
            self._interactive_owner_stack.append(
                (owner_view, owner_generation)
            )
            self._interactive_action_event.set()
        view = getattr(self, "sheet_views", {}).get(getattr(self, "selected_sheet", ""))
        if view is not None:
            try:
                view._refresh_interaction_gate()
            except Exception:
                pass
        if owner_view is not None:
            with self._interactive_action_lock:
                if (
                    self._interactive_owner_stack
                    and self._interactive_owner_stack[-1][0] is owner_view
                ):
                    self._interactive_owner_stack[-1] = (
                        owner_view,
                        int(getattr(owner_view, "_lifecycle_generation", -1)),
                    )

    def _end_interactive_action(self):
        with self._interactive_action_lock:
            self._interactive_action_depth = max(0, self._interactive_action_depth - 1)
            if self._interactive_owner_stack:
                self._interactive_owner_stack.pop()
            if self._interactive_action_depth == 0:
                self._interactive_owner_stack.clear()
                self._interactive_action_event.clear()
        view = getattr(self, "sheet_views", {}).get(getattr(self, "selected_sheet", ""))
        if view is not None:
            try:
                view._refresh_interaction_gate()
            except Exception:
                pass

    def _begin_priority_diff_compute(self):
        """Pause lower-priority tab scans while the active Sheet builds exact diffs."""
        with self._priority_diff_lock:
            self._priority_diff_depth += 1
            self._priority_diff_event.set()

    def _end_priority_diff_compute(self):
        with self._priority_diff_lock:
            self._priority_diff_depth = max(0, self._priority_diff_depth - 1)
            if self._priority_diff_depth == 0:
                self._priority_diff_event.clear()

    def _reserve_ui_transition_window(self, duration_ms: int = 250):
        """Briefly yield background XML parsing to a visible Tk transition."""
        self._begin_priority_diff_compute()
        released = False

        def _release():
            nonlocal released
            if released:
                return
            released = True
            self._end_priority_diff_compute()

        try:
            self._safe_root_after(max(50, int(duration_ms)), _release)
        except Exception:
            _release()
        return _release

    def _claim_priority_exact(self, view, build_seq: int):
        """Make one Sheet/generation the sole exact-comparison owner."""
        previous = None
        with self._priority_diff_lock:
            previous = self._priority_exact_owner
            self._priority_exact_owner = (view, int(build_seq))
        if previous and previous[0] is not view:
            old_view, _old_seq = previous
            old_view._only_diff_async_build_seq += 1
            old_view._only_diff_async_building = False
            old_view._only_diff_async_build_key = None
            old_view._only_diff_preview_full = False
            old_view._pending_exact_render = False
            old_view._lifecycle_canceled = True
            self._finish_only_diff_progress(
                old_view,
                _old_seq,
                outcome="superseded",
            )
            try:
                old_view._refresh_interaction_gate()
            except Exception:
                pass
            _dlog(
                f"EXACT_OWNER cancel hidden={old_view.sheet} "
                f"active={getattr(view, 'sheet', '')}"
            )

    def _release_priority_exact(self, view, build_seq: int):
        with self._priority_diff_lock:
            if self._priority_exact_owner == (view, int(build_seq)):
                self._priority_exact_owner = None

    def _cancel_current_only_diff_progress(self, _event=None):
        owner = self._only_diff_progress_owner
        if owner is not None:
            owner[0]._cancel_only_diff_calculation(owner[1])
        return "break"

    def _ensure_only_diff_progress_dialog(self):
        """Create the reusable dialog off the latency-sensitive click path."""
        win = self._only_diff_progress_win
        try:
            if win is not None and win.winfo_exists():
                return win
        except Exception:
            pass
        if self._is_closing:
            return None
        try:
            win = tk.Toplevel(self.root)
            win.withdraw()
            win.transient(self.root)
            win.resizable(False, False)
            self._only_diff_progress_win = win
            self._only_diff_progress_stage_var = tk.StringVar(master=win, value="")
            self._only_diff_progress_detail_var = tk.StringVar(master=win, value="")
            body = ttk.Frame(win, padding=18)
            body.pack(fill="both", expand=True)
            ttk.Label(
                body,
                textvariable=self._only_diff_progress_stage_var,
                font=("Segoe UI", 10, "bold"),
            ).pack(anchor="w")
            ttk.Label(
                body,
                textvariable=self._only_diff_progress_detail_var,
                foreground="#555555",
            ).pack(anchor="w", pady=(8, 6))
            bar = ttk.Progressbar(
                body,
                mode="determinate",
                maximum=100,
                length=420,
            )
            bar.pack(fill="x")
            self._only_diff_progress_bar = bar
            button_row = ttk.Frame(body)
            button_row.pack(fill="x", pady=(14, 0))
            cancel_btn = ttk.Button(
                button_row,
                text="取消",
                command=self._cancel_current_only_diff_progress,
            )
            cancel_btn.pack(side="right")
            self._only_diff_progress_cancel_btn = cancel_btn
            win.protocol(
                "WM_DELETE_WINDOW",
                self._cancel_current_only_diff_progress,
            )
            win.bind("<Escape>", self._cancel_current_only_diff_progress)
            win.update_idletasks()
            return win
        except Exception as exc:
            _dlog(f"only-diff progress preload failed: {exc}")
            self._only_diff_progress_win = None
            return None

    def _begin_only_diff_progress(self, view, build_seq: int):
        """Claim input immediately, then show the prebuilt dialog."""
        token = (view, int(build_seq))
        if self._only_diff_progress_owner == token:
            return
        if self._only_diff_progress_owner is not None:
            old_view, old_seq = self._only_diff_progress_owner
            self._finish_only_diff_progress(old_view, old_seq, outcome="superseded")

        self._only_diff_progress_owner = token
        self._only_diff_progress_started = time.monotonic()

        def _show_dialog():
            if self._only_diff_progress_owner != token or self._is_closing:
                return
            try:
                win = self._ensure_only_diff_progress_dialog()
                if win is None:
                    return
                win.title(f"正在计算差异 — {view.sheet}")
                self._only_diff_progress_stage_var.set(
                    f"正在准备“{view.sheet}”的精确差异"
                )
                self._only_diff_progress_detail_var.set(
                    "正在打开工作簿…  已用时 0.0 秒"
                )
                self._only_diff_progress_bar.configure(value=0)
                self._only_diff_progress_cancel_btn.configure(
                    text="取消",
                    state="normal",
                )
                win.deiconify()
                win.grab_set()
                win.focus_set()
                width = win.winfo_reqwidth()
                height = win.winfo_reqheight()
                win.geometry(
                    f"+{max(0, self.root.winfo_rootx() + (self.root.winfo_width() - width) // 2)}"
                    f"+{max(0, self.root.winfo_rooty() + (self.root.winfo_height() - height) // 2)}"
                )
            except Exception as exc:
                _dlog(
                    f"only-diff progress show failed sheet={view.sheet}: {exc}"
                )

        self._safe_root_after(0, _show_dialog)

    def _update_only_diff_progress(
        self,
        view,
        build_seq: int,
        stage: str,
        current: int,
        total: int,
    ):
        token = (view, int(build_seq))
        if self._only_diff_progress_owner != token:
            return
        current = max(0, int(current or 0))
        total = max(1, int(total or 1))
        percent = max(0.0, min(100.0, current * 100.0 / total))
        elapsed = max(0.0, time.monotonic() - self._only_diff_progress_started)
        try:
            self._only_diff_progress_stage_var.set(str(stage))
            self._only_diff_progress_detail_var.set(
                f"已处理 {min(current, total):,} / {total:,} 行"
                f"（{percent:.1f}%）  已用时 {elapsed:.1f} 秒"
            )
            self._only_diff_progress_bar.configure(value=percent)
        except Exception:
            pass

    def _finish_only_diff_progress(self, view, build_seq: int, *, outcome: str):
        """Close only the matching dialog and release its input ownership."""
        token = (view, int(build_seq))
        if self._only_diff_progress_owner != token:
            return False
        win = self._only_diff_progress_win
        try:
            if win is not None and win.winfo_exists():
                try:
                    if win.grab_current() == win:
                        win.grab_release()
                except Exception:
                    pass
                win.withdraw()
        except tk.TclError:
            pass
        except Exception:
            pass
        # A completed request must invalidate any late worker/UI payload that
        # still carries this generation.  Also remove a replaceable broker
        # request that has not started yet; otherwise it can reopen the
        # progress surface after the user already received a result.
        try:
            current_seq = int(getattr(view, "_only_diff_async_build_seq", build_seq))
            if current_seq == int(build_seq):
                view._only_diff_async_build_seq = current_seq + 1
        except Exception:
            pass
        try:
            with self._exact_broker_lock:
                pending = self._exact_broker_pending
                if pending is not None and pending[0] is view and int(pending[1]) == int(build_seq):
                    self._exact_broker_pending = None
        except Exception:
            pass
        try:
            self._release_priority_exact(view, int(build_seq))
        except Exception:
            pass
        self._only_diff_progress_owner = None
        self._only_diff_tab_states.clear()
        _dlog(
            f"ONLY_DIFF_PROGRESS_END sheet={view.sheet} "
            f"seq={build_seq} outcome={outcome}"
        )
        return True

    def _cancel_priority_exact_for_hidden(self, active_sheet: str):
        with self._priority_diff_lock:
            owner = self._priority_exact_owner
        if owner and getattr(owner[0], "sheet", None) != active_sheet:
            old_view = owner[0]
            old_view._only_diff_async_build_seq += 1
            old_view._only_diff_async_building = False
            old_view._only_diff_async_build_key = None
            old_view._only_diff_preview_full = False
            old_view._lifecycle_canceled = True
            self._finish_only_diff_progress(
                old_view,
                owner[1],
                outcome="tab-superseded",
            )
            try:
                old_view._refresh_interaction_gate()
            except Exception:
                pass
            _dlog(
                f"EXACT_OWNER tab-cancel hidden={old_view.sheet} active={active_sheet}"
            )

    def _submit_priority_exact(self, view, build_seq: int, worker):
        """Submit to one replaceable exact-compute broker.

        There is at most one broker thread and one pending request. Selecting a
        newer Sheet replaces the pending request instead of creating blocked
        daemon threads that keep lower-priority work paused.
        """
        with self._exact_broker_lock:
            self._exact_broker_pending = (view, int(build_seq), worker)
            if self._exact_broker_running:
                return self._exact_broker_thread or True
            self._exact_broker_running = True

        def _broker_loop():
            while not self._is_closing:
                with self._exact_broker_lock:
                    job = self._exact_broker_pending
                    self._exact_broker_pending = None
                    if job is None:
                        self._exact_broker_running = False
                        self._exact_broker_thread = None
                        return
                job_view, job_seq, job_worker = job
                if int(job_seq) != int(job_view._only_diff_async_build_seq):
                    self._release_priority_exact(job_view, job_seq)
                    continue
                self._begin_priority_diff_compute()
                try:
                    job_worker()
                finally:
                    self._release_priority_exact(job_view, job_seq)
                    self._end_priority_diff_compute()
            with self._exact_broker_lock:
                self._exact_broker_pending = None
                self._exact_broker_running = False
                self._exact_broker_thread = None

        thread = self._start_background_thread(
            _broker_loop,
            name="sow-only-diff-broker",
        )
        if thread is None:
            with self._exact_broker_lock:
                self._exact_broker_pending = None
                self._exact_broker_running = False
                self._exact_broker_thread = None
            return None
        with self._exact_broker_lock:
            self._exact_broker_thread = thread
        return thread

    def _join_background_threads(self, timeout: float = 5.0):
        deadline = time.monotonic() + max(0.0, float(timeout))
        with self._background_threads_lock:
            threads = list(self._background_threads)
        current = threading.current_thread()
        for thread in threads:
            if thread is current or not thread.is_alive():
                continue
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            thread.join(timeout=remaining)

    def _safe_root_after(self, delay_ms: int, callback):
        if getattr(self, "_is_closing", False):
            return None
        holder = {"id": None}

        def _wrapped():
            aid = holder.get("id")
            if aid is not None:
                try:
                    self._root_after_ids.discard(aid)
                except Exception:
                    pass
            if getattr(self, "_is_closing", False):
                return
            callback()

        try:
            aid = self.root.after(int(delay_ms), _wrapped)
            holder["id"] = aid
            self._root_after_ids.add(aid)
            return aid
        except Exception:
            return None

    def _cancel_root_afters(self):
        try:
            pending = list(getattr(self, "_root_after_ids", set()) or ())
        except Exception:
            pending = []
        try:
            self._root_after_ids.clear()
        except Exception:
            pass
        for aid in pending:
            try:
                self.root.after_cancel(aid)
            except Exception:
                pass

    def _request_close(self):
        """Close guard with explicit Save / Discard / Cancel semantics."""
        if getattr(self, "_is_closing", False):
            return
        if not bool(getattr(self, "modified_a", False) or getattr(self, "modified_b", False)):
            self._shutdown_root(force=True)
            return
        try:
            choice = messagebox.askyesnocancel(
                "未保存改动",
                "检测到未保存改动。\n\n是：保存并关闭\n否：放弃改动并关闭\n取消：返回当前窗口",
                parent=self.root,
            )
        except Exception:
            choice = None
        if choice is None:
            return
        if choice is False:
            self.modified_a = False
            self.modified_b = False
            self._shutdown_root(force=True)
            return
        try:
            # Merge output has its own complete atomic save/reconciliation path.
            if getattr(self, "merge_mode", False) and getattr(self, "merged_path", None):
                self.save_merged_and_exit(auto=False)
                return
            if getattr(self, "modified_a", False):
                self.save_a_inplace()
            if getattr(self, "modified_b", False):
                self.save_b_inplace()
        except Exception as exc:
            # A failed save must leave the window and in-memory edits intact.
            try:
                messagebox.showerror("保存失败，窗口保持打开", str(exc), parent=self.root)
            except Exception:
                pass
            return
        if not bool(getattr(self, "modified_a", False) or getattr(self, "modified_b", False)):
            self._shutdown_root(force=True)

    def _shutdown_root(self, *, force: bool = False):
        if getattr(self, "_is_closing", False):
            return
        # This is the internal teardown primitive.  The real user close path
        # is ``WM_DELETE_WINDOW -> _request_close`` and owns the unsaved-change
        # prompt; background workers and automated fixtures call this method
        # directly and must never block on a modal dialog.  ``force`` remains
        # accepted for compatibility with existing callers.
        self._is_closing = True
        try:
            self._initial_sheet_ready_event.set()
        except Exception:
            pass
        try:
            owner = getattr(self, "_only_diff_progress_owner", None)
            if owner is not None:
                self._finish_only_diff_progress(
                    owner[0],
                    owner[1],
                    outcome="closing",
                )
        except Exception:
            pass
        self._cancel_root_afters()
        try:
            progress = getattr(self, "task_progress", None)
            if progress is not None:
                progress.stop()
        except Exception:
            pass
        try:
            with self._compute_lock:
                self._compute_queue.clear()
                self._sheet_cache_store.clear()
        except Exception:
            pass
        try:
            for view in list(getattr(self, "sheet_views", {}).values()):
                if view is None:
                    continue
                view._only_diff_async_build_seq += 1
                view._only_diff_async_building = False
                view._only_diff_async_build_key = None
                try:
                    view._hide_loading()
                except Exception:
                    pass
                for attr in ("_settings_save_id", "_hover_debounce_id", "_diff_map_debounce_id"):
                    aid = getattr(view, attr, None)
                    if not aid:
                        continue
                    try:
                        view.frame.after_cancel(aid)
                    except Exception:
                        pass
                    try:
                        setattr(view, attr, None)
                    except Exception:
                        pass
        except Exception:
            pass
        # Widgets and ttk progressbars can schedule Tcl-level callbacks that are
        # not registered through _safe_root_after. Cancel every remaining callback
        # before destroying the interpreter to avoid stale-command warnings.
        try:
            for aid in list(self.root.tk.call("after", "info") or ()):
                try:
                    self.root.after_cancel(aid)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            with self._ui_task_lock:
                self._ui_tasks.clear()
        except Exception:
            pass
        self._join_background_threads(timeout=5.0)
        try:
            _destroy_startup_progress_root()
        except Exception:
            pass
        try:
            with self._edit_fallback_lock:
                _wbs_close(
                    getattr(self, "_wb_a_val", None),
                    getattr(self, "_wb_b_val", None),
                    getattr(self, "_wb_base_val", None),
                    getattr(self, "_wb_a_edit", None),
                    getattr(self, "_wb_b_edit", None),
                    getattr(self, "_wb_base_edit", None),
                )
                self._wb_a_val = None
                self._wb_b_val = None
                self._wb_base_val = None
                self._wb_a_edit = None
                self._wb_b_edit = None
                self._wb_base_edit = None
        except Exception:
            pass
        try:
            temp_specs = [
                (getattr(self, "_file_a_val_path", None), getattr(self, "file_a", None)),
                (getattr(self, "_file_b_val_path", None), getattr(self, "file_b", None)),
                (getattr(self, "_file_base_val_path", None), getattr(self, "base_path", None)),
            ]
            for temp_path, original_path in temp_specs:
                if not temp_path:
                    continue
                try:
                    if original_path and os.path.abspath(temp_path) == os.path.abspath(original_path):
                        continue
                except Exception:
                    pass
                try:
                    if os.path.exists(temp_path):
                        os.remove(temp_path)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            snap = getattr(self, "_merge_mine_snapshot", None)
            if snap and os.path.exists(snap):
                os.remove(snap)
        except Exception:
            pass
        try:
            startup_temp_paths = {
                getattr(self, "merge_candidate_path", None),
                getattr(self, "file_a", None),
                getattr(self, "file_b", None),
                getattr(self, "base_path", None),
            }
            context = getattr(self, "launch_context", None)
            for identity in getattr(context, "identities", {}).values():
                stable_path = getattr(identity, "stable_path", None)
                original_path = getattr(identity, "path", None)
                if stable_path and (
                    not original_path
                    or os.path.abspath(stable_path) != os.path.abspath(original_path)
                ):
                    startup_temp_paths.add(stable_path)
            temp_root = os.path.abspath(tempfile.gettempdir())
            for temp_path in startup_temp_paths:
                if not temp_path:
                    continue
                candidate = os.path.abspath(temp_path)
                if (
                    os.path.commonpath((temp_root, candidate)) != temp_root
                    or not os.path.basename(candidate).lower().startswith(APP_NAME.lower())
                ):
                    continue
                try:
                    if os.path.isfile(candidate):
                        os.remove(candidate)
                except Exception:
                    pass
        except Exception:
            pass
        try:
            self._persist_difference_browser_preferences()
            os.makedirs(os.path.dirname(_SETTINGS_PATH), exist_ok=True)
            with open(_SETTINGS_PATH, "w", encoding="utf-8") as stream:
                json.dump(getattr(self, "settings", {}) or {}, stream, ensure_ascii=False, indent=2)
        except Exception as exc:
            _dlog(f"settings close save failed: {exc}")
        try:
            if self.root.winfo_exists():
                # Ensure Tk mainloop exits and the window is actually closed.
                try:
                    self.root.quit()
                except Exception:
                    pass
                self.root.destroy()
        except Exception:
            pass

    def _edit_workbooks_ready(self) -> bool:
        return bool(
            self._wb_a_edit is not None
            and self._wb_b_edit is not None
            and (not self.has_base or self._wb_base_edit is not None)
        )

    def _is_vcs_two_way_mode(self) -> bool:
        """Whether A is a read-only SVN Base side and B is real Mine.

        TortoiseSVN's two-way invocation supplies ``/base`` and ``/mine``.
        A is normalized to a temporary workbook copy in that path, while B
        remains the working-copy file.  Keep the distinction explicit so a
        toolbar action or a stale callback can never save the Base copy.
        """
        return bool(
            not getattr(self, "merge_mode", False)
            and (
                getattr(self, "diff_base_mine_mode", False)
                or (
                    bool(getattr(self, "raw_base", None))
                    and bool(getattr(self, "raw_mine", None))
                    and not bool(getattr(self, "raw_theirs", None))
                )
            )
        )

    def _mine_working_path(self) -> str:
        """Return the real Mine output path for a VCS two-way session."""
        if self._is_vcs_two_way_mode():
            raw_mine = getattr(self, "raw_mine", None)
            if raw_mine and os.path.isfile(str(raw_mine)):
                return str(raw_mine)
        return str(getattr(self, "file_b", "") or "")

    def _guard_active_sheet_mutation(self, action: str) -> bool:
        view = getattr(self, "sheet_views", {}).get(getattr(self, "selected_sheet", ""))
        if view is None:
            self.show_nonblocking_notice(
                f"{action}暂不可用。当前 Sheet 尚未加载完成。",
                duration_ms=6000,
            )
            return False
        return bool(view._guard_mutation_ready(action))

    def _guard_sheet_mutation(self, sheet: str, action: str) -> bool:
        view = getattr(self, "sheet_views", {}).get(str(sheet))
        if view is None:
            return False
        # A handler acquires readiness before entering BUSY. Deeper workbook
        # primitives may revalidate that same owner/generation without being
        # rejected merely because the handler itself set the BUSY event.
        if self._has_active_mutation_owner(view):
            return True
        return bool(view._guard_mutation_ready(action))

    def _has_active_mutation_owner(self, view) -> bool:
        with self._interactive_action_lock:
            owner_entry = (
                self._interactive_owner_stack[-1]
                if self._interactive_owner_stack
                else None
            )
        if owner_entry is None:
            return False
        owner_view, owner_generation = owner_entry
        return bool(
            owner_view is view
            and int(getattr(owner_view, "_lifecycle_generation", -2))
            == int(owner_generation)
        )

    def _pending_mutation_sheets(self, target_side: str) -> set[str]:
        side = str(target_side or "").upper()
        sheets: set[str] = set()
        if side == "A":
            sheets.update(sheet for sheet, _row, _col in self.manual_a_cell_ops)
            sheets.update(sheet for sheet, _row, _col in self.manual_a_formula_cache_ops)
            sheets.update(str(op.get("sheet")) for op in self.manual_a_row_ops if op.get("sheet"))
            sheets.update(str(op.get("sheet")) for op in self.manual_a_column_ops if op.get("sheet"))
            sheets.update(getattr(self, "modified_sheets_a", set()))
        elif side == "B":
            sheets.update(sheet for sheet, _row, _col in self.manual_b_cell_ops)
            sheets.update(sheet for sheet, _row, _col in self.manual_b_formula_cache_ops)
            sheets.update(str(op.get("sheet")) for op in self.manual_b_row_ops if op.get("sheet"))
            sheets.update(str(op.get("sheet")) for op in self.manual_b_column_ops if op.get("sheet"))
            sheets.update(getattr(self, "modified_sheets_b", set()))
        for op in getattr(self, "manual_sheet_ops", ()):
            if str(op.get("target_side") or "").upper() == side and op.get("sheet"):
                sheets.add(str(op["sheet"]))
        for op in getattr(self, "auto_sheet_ops", ()):
            if str(op.get("target_side") or "A").upper() == side and op.get("sheet"):
                sheets.add(str(op["sheet"]))
        selected = getattr(self, "selected_sheet", None)
        if selected:
            sheets.add(str(selected))
        return sheets

    def _guard_save_readiness(self, action: str, target_side: str) -> bool:
        if not self._edit_workbooks_ready():
            self._request_edit_preload()
            self.show_nonblocking_notice(
                f"{action}暂不可用。可编辑工作簿仍在后台加载。",
                duration_ms=6000,
            )
            return False
        blocked = []
        for sheet in sorted(self._pending_mutation_sheets(target_side)):
            view = getattr(self, "sheet_views", {}).get(sheet)
            if view is None or view._derive_lifecycle_state() != "READY":
                state = "未加载" if view is None else view._derive_lifecycle_state()
                blocked.append(f"{sheet}({state})")
        if blocked:
            self.show_nonblocking_notice(
                f"{action}暂不可用。以下相关 Sheet 尚未 READY："
                + "、".join(blocked[:8]),
                duration_ms=8000,
            )
            return False
        return True

    def _request_edit_preload(self):
        """Start the deferred editable-workbook load exactly once."""
        if self._edit_workbooks_ready() or self._is_closing:
            return
        if getattr(self, "_edit_loading_started", False):
            self._initial_sheet_ready_event.set()
            return
        runner = getattr(self, "_edit_preload_runner", None)
        if not callable(runner):
            return
        self._edit_loading_started = True
        self._initial_sheet_ready_event.set()
        self._edit_preload_thread = self._start_background_thread(
            runner,
            name="sow-edit-preload",
        )

    def _refresh_loaded_views_after_edit_ready(self):
        """Publish edit readiness without performing a Tk-thread rescan.

        Background Sheet caches are already formula-aware. A legacy/value-only
        view is requeued for background refinement; no workbook scan or Text
        rebuild runs from this UI callback.
        """
        if self._is_closing or not self._edit_workbooks_ready():
            return
        started = time.perf_counter()
        requeued = 0
        for sheet, view in list(getattr(self, "sheet_views", {}).items()):
            if view is None:
                continue
            try:
                if (
                    view._is_missing_sheet_view()
                    and bool(getattr(view, "_data_ready", False))
                    and not bool(getattr(view, "_cache_formula_aware", False))
                ):
                    # A missing Sheet is already an exact structural difference:
                    # formulas cannot change row membership or the mutation
                    # target. Editable preload only completes the source used by
                    # a later whole-Sheet copy, so publish readiness without a
                    # foreground row scan.
                    view._cache_formula_aware = True
                    view._refresh_interaction_gate()
                    continue
                if (
                    bool(getattr(view, "_data_ready", False))
                    and not bool(getattr(view, "_cache_formula_aware", False))
                    and sheet not in getattr(self, "modified_sheets_a", set())
                    and sheet not in getattr(self, "modified_sheets_b", set())
                ):
                    view._data_ready = False
                    view._lifecycle_generation += 1
                    self._enqueue_sheet(
                        sheet,
                        front=(sheet == getattr(self, "selected_sheet", "")),
                        exact_only_diff=bool(view.only_diff_var.get()),
                    )
                    requeued += 1
                view._refresh_interaction_gate()
            except Exception as exc:
                _dlog(
                    f"edit-ready state publish failed: sheet={sheet} "
                    f"err={type(exc).__name__}:{exc}"
                )
        if requeued:
            self._kick_worker()
        elapsed_ms = (time.perf_counter() - started) * 1000.0
        _dlog(
            f"EDIT_READY_GATE views={len(getattr(self, 'sheet_views', {}))} "
            f"requeued={requeued} callback_ms={elapsed_ms:.1f} rescan=False"
        )

    def _load_edit_workbooks_owned(self) -> bool:
        """Load each editable workbook once under a single ownership lock.

        Both the background preloader and foreground fallback use this method.
        Holding ownership across XML parsing prevents two complete openpyxl loads
        from racing, and compare-and-set installation prevents a late pristine
        preload from replacing a workbook that already contains user changes.
        """
        loaded_here = []
        self._edit_preload_active_event.set()
        try:
            with self._edit_fallback_lock:
                if self._edit_workbooks_ready():
                    return True
                if self._wb_a_edit is None:
                    t0 = datetime.now()
                    candidate = load_workbook(self.file_a, data_only=False)
                    if self._wb_a_edit is None and not self._is_closing:
                        self._wb_a_edit = candidate
                    else:
                        loaded_here.append(candidate)
                    _dlog(f"load wb_a_edit owned: {(datetime.now()-t0).total_seconds():.3f}s")
                if self._wb_b_edit is None:
                    t0 = datetime.now()
                    candidate = load_workbook(self._mine_working_path(), data_only=False)
                    if self._wb_b_edit is None and not self._is_closing:
                        self._wb_b_edit = candidate
                    else:
                        loaded_here.append(candidate)
                    _dlog(f"load wb_b_edit owned: {(datetime.now()-t0).total_seconds():.3f}s")
                if self.has_base and self._wb_base_edit is None:
                    t0 = datetime.now()
                    candidate = load_workbook(self.base_path, data_only=False)
                    if self._wb_base_edit is None and not self._is_closing:
                        self._wb_base_edit = candidate
                    else:
                        loaded_here.append(candidate)
                    _dlog(f"load wb_base_edit owned: {(datetime.now()-t0).total_seconds():.3f}s")
                return self._edit_workbooks_ready()
        finally:
            self._edit_preload_active_event.clear()
            _wbs_close(*loaded_here)

    def _ensure_value_workbooks_regular(self) -> None:
        """Upgrade read-only value workbooks only when a mutation needs them."""
        if getattr(self, "_value_workbooks_regular", False):
            return
        with self._value_workbook_upgrade_lock:
            if getattr(self, "_value_workbooks_regular", False):
                return
            old_values = (
                self._wb_a_val,
                self._wb_b_val,
                self._wb_base_val,
            )
            loaded = []
            try:
                loaded.append(load_workbook(self._file_a_val_path, data_only=True, keep_links=False))
                loaded.append(load_workbook(self._file_b_val_path, data_only=True, keep_links=False))
                if self.has_base and getattr(self, "_file_base_val_path", None):
                    loaded.append(load_workbook(self._file_base_val_path, data_only=True, keep_links=False))
                new_base = loaded[2] if self.has_base and len(loaded) > 2 else None
                if (
                    len(loaded) != (3 if self.has_base else 2)
                    or any(bool(getattr(workbook, "read_only", False)) for workbook in loaded)
                ):
                    raise RuntimeError("值工作簿升级后仍不可编辑。")
                self._wb_a_val = loaded[0]
                self._wb_b_val = loaded[1]
                self._wb_base_val = new_base
                self._value_workbooks_regular = True
            except Exception:
                _wbs_close(*loaded)
                # The old read-only objects remain valid when the swap did not
                # complete.  Do not leave a stale True marker after a partial
                # reload or a failed open.
                self._value_workbooks_regular = False
                raise
            finally:
                if getattr(self, "_value_workbooks_regular", False):
                    _wbs_close(*old_values)

    def _value_workbooks_are_regular(self) -> bool:
        """Return whether every active value workbook supports mutation.

        ``openpyxl`` exposes ``read_only`` on both ``Workbook`` and
        ``ReadOnlyWorkbook``.  Keep this check centralized because recalculation
        and reload paths can replace only one side at a time.
        """
        workbooks = [self._wb_a_val, self._wb_b_val]
        if self.has_base:
            workbooks.append(self._wb_base_val)
        return bool(
            all(workbook is not None for workbook in workbooks)
            and all(not bool(getattr(workbook, "read_only", False)) for workbook in workbooks)
        )

    def _ensure_edit_loaded(self):
        if self._edit_workbooks_ready():
            return

        if getattr(self, "_edit_loading_started", False):
            self._request_edit_preload()
            _dlog("waiting for single-owner background edit preload")
            while not self._edit_loaded_event.wait(timeout=0.1):
                if self._is_closing:
                    raise RuntimeError("应用正在关闭，已取消可编辑工作簿加载。")
            if self._edit_workbooks_ready():
                return

        _dlog("loading edit workbooks (single-owner fallback)")
        if not self._load_edit_workbooks_owned():
            raise RuntimeError("可编辑工作簿加载失败。")
        self._edit_loaded_event.set()

    def ws_a_edit(self, sheet: str):
        self._ensure_edit_loaded()
        if self._wb_a_edit is None:
            raise KeyError("file_a edit workbook not available")
        return self._wb_a_edit[sheet]

    def ws_b_edit(self, sheet: str):
        self._ensure_edit_loaded()
        if self._wb_b_edit is None:
            raise KeyError("file_b edit workbook not available")
        return self._wb_b_edit[sheet]

    def ws_base_edit(self, sheet: str):
        self._ensure_edit_loaded()
        if self._wb_base_edit is None:
            raise KeyError("base workbook not available")
        return self._wb_base_edit[sheet]

    def ws_a_val(self, sheet: str):
        if self._wb_a_val is None:
            raise KeyError("file_a val workbook not available")
        return self._wb_a_val[sheet]

    def ws_b_val(self, sheet: str):
        if self._wb_b_val is None:
            raise KeyError("file_b val workbook not available")
        return self._wb_b_val[sheet]

    def ws_base_val(self, sheet: str):
        if self._wb_base_val is None:
            raise KeyError("base workbook not available")
        return self._wb_base_val[sheet]

    def record_manual_a_cell(self, sheet: str, r: int, c: int, edit_value):
        try:
            key = (sheet, int(r), int(c))
            self.manual_a_cell_ops[key] = edit_value
            self.manual_a_formula_cache_ops.pop(key, None)
        except Exception:
            pass

    def record_manual_a_formula_cache(self, sheet: str, r: int, c: int, cached_value):
        try:
            key = (sheet, int(r), int(c))
            self.manual_a_formula_cache_ops[key] = cached_value
        except Exception:
            pass

    def record_manual_b_cell(self, sheet: str, r: int, c: int, edit_value):
        try:
            key = (sheet, int(r), int(c))
            self.manual_b_cell_ops[key] = edit_value
            self.manual_b_formula_cache_ops.pop(key, None)
        except Exception:
            pass

    def record_manual_b_formula_cache(self, sheet: str, r: int, c: int, cached_value):
        try:
            self.manual_b_formula_cache_ops[(sheet, int(r), int(c))] = cached_value
        except Exception:
            pass

    def clear_manual_b_formula_cache(self, sheet: str, r: int, c: int):
        try:
            self.manual_b_formula_cache_ops.pop((sheet, int(r), int(c)), None)
        except Exception:
            pass

    def next_manual_column_action_id(self) -> str:
        self._manual_column_action_seq += 1
        return f"column-action-{self._manual_column_action_seq:06d}"

    def _next_manual_structural_operation_order(self) -> int:
        """Allocate one order shared by row and column structural actions."""
        current = max(
            int(getattr(self, "_manual_structural_op_seq", 0) or 0),
            int(getattr(self, "_manual_column_op_seq", 0) or 0),
        ) + 1
        self._manual_structural_op_seq = current
        # Keep the former counter synchronized for old tests/helpers that still
        # initialize or inspect it directly.
        self._manual_column_op_seq = current
        return current

    def remap_manual_cell_operations_for_column_action(
        self,
        target_side: str,
        plan: ColumnBlockActionPlan,
    ):
        """Keep explicit cell/cache records in final physical coordinates.

        Existing edits move with an inserted/deleted column in the live
        workbook.  Their replay keys must move identically; edits made after
        this action are already recorded in the new coordinates.  A direct
        copy overwrites any earlier explicit edits inside the adopted block.
        """
        target_side = str(target_side or "").upper()
        if target_side == "A":
            op_maps = (self.manual_a_cell_ops, self.manual_a_formula_cache_ops)
        elif target_side == "B":
            op_maps = (self.manual_b_cell_ops, self.manual_b_formula_cache_ops)
        else:
            raise ValueError("column action target_side must be A or B")
        anchor = int(plan.target_physical_anchor)
        count = int(plan.count)
        deleted_end = anchor + count - 1
        for op_map_index, op_map in enumerate(op_maps):
            remapped = {}
            for (sheet, row_idx, col_idx), value in op_map.items():
                col_idx = int(col_idx)
                key = (sheet, int(row_idx), col_idx)
                remapped_value = value
                if (
                    op_map_index == 0
                    and plan.action_kind in ("insert_copy", "delete")
                ):
                    remapped_value = _transform_formula_for_column_structure(
                        value,
                        formula_sheet=str(sheet),
                        target_sheet=str(plan.sheet),
                        anchor=anchor,
                        count=count,
                        insert=plan.action_kind == "insert_copy",
                    )
                if sheet != plan.sheet:
                    remapped[key] = remapped_value
                    continue
                if plan.action_kind == "insert_copy":
                    new_col = col_idx + count if col_idx >= anchor else col_idx
                elif plan.action_kind == "delete":
                    if anchor <= col_idx <= deleted_end:
                        continue
                    new_col = col_idx - count if col_idx > deleted_end else col_idx
                elif plan.action_kind == "copy":
                    if anchor <= col_idx <= deleted_end:
                        continue
                    new_col = col_idx
                else:
                    new_col = col_idx
                remapped[(sheet, int(row_idx), int(new_col))] = remapped_value
            op_map.clear()
            op_map.update(remapped)

    def transform_manual_formulas_for_row_action(
        self,
        target_side: str,
        target_sheet: str,
        anchor: int,
        count: int,
        *,
        insert: bool,
    ):
        """Keep previously recorded formulas consistent with a row action.

        Native Excel replay updates workbook formulas when rows are inserted or
        deleted. Explicit cell operations are replayed afterwards, so their
        stored formula text must undergo the same structural transform or an
        older formula can silently overwrite Excel's corrected reference.
        Formula-cache values are intentionally not rewritten.
        """
        target_side = str(target_side or "").upper()
        if target_side == "A":
            op_map = self.manual_a_cell_ops
        elif target_side == "B":
            op_map = self.manual_b_cell_ops
        else:
            raise ValueError("row action target_side must be A or B")
        for key, value in list(op_map.items()):
            formula_sheet = str(key[0])
            op_map[key] = _transform_formula_for_row_structure(
                value,
                formula_sheet=formula_sheet,
                target_sheet=str(target_sheet),
                anchor=int(anchor),
                count=int(count),
                insert=bool(insert),
            )

    def record_manual_column_operations(self, target_side: str, operations) -> list[dict[str, object]]:
        """Append a validated action batch to the ordered target-side log."""
        target_side = str(target_side or "").upper()
        if target_side == "A":
            destination = self.manual_a_column_ops
        elif target_side == "B":
            destination = self.manual_b_column_ops
        else:
            raise ValueError("column operation target_side must be A or B")
        normalized = []
        action_id = None
        next_order = max(
            int(getattr(self, "_manual_structural_op_seq", 0) or 0),
            int(getattr(self, "_manual_column_op_seq", 0) or 0),
        )
        for operation in operations or ():
            op = dict(operation or {})
            if op.get("kind") not in ("insert_cols", "delete_cols", "copy_cols"):
                raise ValueError("unsupported manual column operation")
            if str(op.get("target_side") or "").upper() != target_side:
                raise ValueError("manual column operation target mismatch")
            op_action_id = str(op.get("action_id") or "")
            if not op_action_id or str(op.get("batch_id") or "") != op_action_id:
                raise ValueError("manual column operation requires one action/batch id")
            if action_id is None:
                action_id = op_action_id
            elif op_action_id != action_id:
                raise ValueError("manual column operation batch must share one action id")
            count = int(op.get("count", 0) or 0)
            anchor = int(op.get("target_physical_anchor", 0) or 0)
            logical_slot = int(op.get("target_logical_slot", 0) or 0)
            if count <= 0 or anchor <= 0 or logical_slot <= 0:
                raise ValueError("manual column operation range is invalid")
            source_side = str(op.get("source_side") or "").upper()
            if source_side not in ("A", "BASE", "B"):
                raise ValueError("manual column operation source is invalid")
            source_cols = [int(value) for value in (op.get("source_physical_cols") or [])]
            if op["kind"] == "copy_cols" and len(source_cols) != count:
                raise ValueError("copy_cols source range must match count")
            next_order += 1
            op.update({
                "target_side": target_side,
                "count": count,
                "target_physical_anchor": anchor,
                "target_logical_slot": logical_slot,
                "source_side": source_side,
                "source_physical_cols": source_cols,
                "metadata_scope": list(op.get("metadata_scope") or _COLUMN_ACTION_METADATA_SCOPE),
                "order": next_order,
            })
            normalized.append(op)
        self._manual_column_op_seq = next_order
        self._manual_structural_op_seq = next_order
        destination.extend(normalized)
        return normalized

    def record_manual_a_row_insert(
        self,
        sheet: str,
        row: int,
        count: int = 1,
        source_side: str | None = None,
        source_rows: list[int] | None = None,
    ):
        try:
            op = {
                "sheet": sheet,
                "kind": "insert_rows",
                "row": int(row),
                "count": max(1, int(count)),
                "order": self._next_manual_structural_operation_order(),
            }
            if source_side:
                op["source_side"] = str(source_side).upper()
            if source_rows:
                op["source_rows"] = [int(value) for value in source_rows]
            self.manual_a_row_ops.append(op)
        except Exception:
            pass

    def record_manual_b_row_insert(
        self,
        sheet: str,
        row: int,
        count: int = 1,
        source_side: str | None = None,
        source_rows: list[int] | None = None,
    ):
        op = {
            "sheet": sheet,
            "kind": "insert_rows",
            "row": int(row),
            "count": max(1, int(count)),
            "order": self._next_manual_structural_operation_order(),
        }
        if source_side:
            op["source_side"] = str(source_side).upper()
        if source_rows:
            op["source_rows"] = [int(value) for value in source_rows]
        self.manual_b_row_ops.append(op)

    def record_manual_a_row_delete(self, sheet: str, row: int, count: int = 1):
        op = {
            "sheet": sheet,
            "kind": "delete_rows",
            "row": int(row),
            "count": max(1, int(count)),
            "order": self._next_manual_structural_operation_order(),
        }
        self.manual_a_row_ops.append(op)
        return op

    def record_manual_b_row_delete(self, sheet: str, row: int, count: int = 1):
        op = {
            "sheet": sheet,
            "kind": "delete_rows",
            "row": int(row),
            "count": max(1, int(count)),
            "order": self._next_manual_structural_operation_order(),
        }
        self.manual_b_row_ops.append(op)
        return op

    def remove_last_manual_a_row_insert(self, sheet: str, row: int, count: int = 1) -> bool:
        row = int(row)
        count = max(1, int(count))
        for i in range(len(self.manual_a_row_ops) - 1, -1, -1):
            op = self.manual_a_row_ops[i]
            try:
                if (
                    op.get("sheet") == sheet and
                    op.get("kind") == "insert_rows" and
                    int(op.get("row", 0)) == row and
                    int(op.get("count", 1)) == count
                ):
                    del self.manual_a_row_ops[i]
                    return True
            except Exception:
                continue
        return False

    def remove_last_manual_b_row_insert(self, sheet: str, row: int, count: int = 1) -> bool:
        row = int(row)
        count = max(1, int(count))
        for idx in range(len(self.manual_b_row_ops) - 1, -1, -1):
            op = self.manual_b_row_ops[idx]
            if (
                op.get("sheet") == sheet
                and op.get("kind") == "insert_rows"
                and int(op.get("row", 0)) == row
                and int(op.get("count", 1)) == count
            ):
                del self.manual_b_row_ops[idx]
                return True
        return False

    def record_manual_sheet_copy(
        self,
        sheet: str,
        source_side: str,
        target_side: str,
        target_index: int | None = None,
    ):
        try:
            operation = {
                "kind": "copy_sheet",
                "sheet": sheet,
                "source_side": str(source_side or "").upper(),
                "target_side": str(target_side or "").upper(),
            }
            if target_index is not None:
                operation["target_index"] = int(target_index)
            self.manual_sheet_ops.append(operation)
        except Exception:
            pass

    def record_manual_sheet_delete(self, sheet: str, target_side: str):
        try:
            self.manual_sheet_ops.append({
                "kind": "delete_sheet",
                "sheet": sheet,
                "target_side": str(target_side or "").upper(),
            })
        except Exception:
            pass

    def _workbooks_for_side(self, side: str):
        side = str(side or "").upper()
        if side == "A":
            return getattr(self, "_wb_a_val", None), getattr(self, "_wb_a_edit", None)
        if side in ("B", "THEIRS"):
            return getattr(self, "_wb_b_val", None), getattr(self, "_wb_b_edit", None)
        if side == "BASE":
            return getattr(self, "_wb_base_val", None), getattr(self, "_wb_base_edit", None)
        return None, None

    def _copy_sheet_between_sides(self, sheet: str, source_side: str, target_side: str):
        if not self._guard_sheet_mutation(sheet, "整 Sheet 复制"):
            raise RuntimeError("当前 Sheet 尚未 READY，已阻止整 Sheet 复制。")
        self._ensure_edit_loaded()
        self._ensure_value_workbooks_regular()
        source_side = str(source_side or "").upper()
        target_side = str(target_side or "").upper()
        src_val_wb, src_edit_wb = self._workbooks_for_side(source_side)
        dst_val_wb, dst_edit_wb = self._workbooks_for_side(target_side)
        if src_edit_wb is None or dst_edit_wb is None or sheet not in src_edit_wb.sheetnames:
            raise KeyError(f"sheet copy unavailable: {sheet} {source_side}->{target_side}")
        src_val_ws = src_val_wb[sheet] if src_val_wb is not None and sheet in src_val_wb.sheetnames else src_edit_wb[sheet]
        src_edit_ws = src_edit_wb[sheet]
        target_index = None
        if dst_edit_wb is not None and sheet in dst_edit_wb.sheetnames:
            target_index = int(dst_edit_wb.sheetnames.index(sheet))
        _create_sheet_from_source(
            dst_edit_wb,
            src_edit_ws,
            sheet,
            index=target_index,
        )
        _create_sheet_from_source(
            dst_val_wb,
            src_val_ws,
            sheet,
            index=target_index,
        )
        if target_side == "A":
            self.modified_a = True
            self.modified_sheets_a.add(sheet)
            self.record_manual_sheet_copy(
                sheet,
                source_side,
                target_side,
                target_index=target_index,
            )
        elif target_side == "B":
            self.modified_b = True
            self.modified_sheets_b.add(sheet)
            self.record_manual_sheet_copy(
                sheet,
                source_side,
                target_side,
                target_index=target_index,
            )
        self._refresh_sheet_catalog()

    def _delete_sheet_on_side(self, sheet: str, target_side: str):
        if not self._guard_sheet_mutation(sheet, "整 Sheet 删除"):
            raise RuntimeError("当前 Sheet 尚未 READY，已阻止整 Sheet 删除。")
        self._ensure_edit_loaded()
        self._ensure_value_workbooks_regular()
        target_side = str(target_side or "").upper()
        dst_val_wb, dst_edit_wb = self._workbooks_for_side(target_side)
        changed = _remove_sheet_if_exists(dst_edit_wb, sheet)
        _remove_sheet_if_exists(dst_val_wb, sheet)
        if not changed:
            return False
        if target_side == "A":
            self.modified_a = True
            self.modified_sheets_a.add(sheet)
            self.record_manual_sheet_delete(sheet, target_side)
        elif target_side == "B":
            self.modified_b = True
            self.modified_sheets_b.add(sheet)
            self.record_manual_sheet_delete(sheet, target_side)
        self._refresh_sheet_catalog()
        if sheet not in self.sheet_meta:
            self.display_sheets.append(sheet)
            self.sheet_meta[sheet] = {"has_a": False, "has_b": False, "has_base": False, "view_mode": "missing_sheet"}
            self.sheet_diff_state[sheet] = 0
        return True

    def _sheet_ops_for_target(self, target_side: str, *, include_auto: bool = False):
        target_side = str(target_side or "").upper()
        ops = []
        if include_auto:
            ops.extend(getattr(self, "auto_sheet_ops", []) or [])
        ops.extend(getattr(self, "manual_sheet_ops", []) or [])
        return [
            dict(op)
            for op in ops
            if str(op.get("target_side") or "A").upper() == target_side
        ]

    def _clear_sheet_ops_for_target(self, target_side: str):
        target_side = str(target_side or "").upper()
        self.manual_sheet_ops[:] = [
            op for op in self.manual_sheet_ops
            if str(op.get("target_side") or "A").upper() != target_side
        ]

    def _commit_saved_side_baseline(self, target_side: str):
        """Retire mutations that are now present in the saved workbook.

        This runs before value-workbook reload queues a fresh background
        comparison. Otherwise the cache publisher correctly sees historical
        ``modified_sheets``/``touched_rows`` and rejects every new baseline as
        stale forever.
        """
        side = str(target_side or "").upper()
        saved_sheets = set(self._pending_mutation_sheets(side))
        if side == "A":
            self.modified_a = False
            self.modified_sheets_a.clear()
            self.manual_a_cell_ops.clear()
            self.manual_a_formula_cache_ops.clear()
            self.manual_a_row_ops.clear()
            self.manual_a_column_ops.clear()
        elif side == "B":
            self.modified_b = False
            self.modified_sheets_b.clear()
            self.manual_b_cell_ops.clear()
            self.manual_b_formula_cache_ops.clear()
            self.manual_b_row_ops.clear()
            self.manual_b_column_ops.clear()
        else:
            return
        self._clear_sheet_ops_for_target(side)
        remaining_a = set(getattr(self, "modified_sheets_a", set()))
        remaining_b = set(getattr(self, "modified_sheets_b", set()))
        for sheet in saved_sheets:
            if sheet in remaining_a or sheet in remaining_b:
                continue
            view = getattr(self, "sheet_views", {}).get(sheet)
            if view is not None:
                view.touched_rows.clear()
        _dlog(
            f"SAVE_BASELINE_COMMITTED side={side} "
            f"sheets={','.join(sorted(saved_sheets)) or '-'}"
        )

    def _ensure_live_column_mappings_current(self, operation: str):
        """Synchronously validate/rebuild every materialized view before output."""
        for view in tuple(getattr(self, "sheet_views", {}).values()):
            if view is None or not getattr(view, "_data_ready", False):
                continue
            view._ensure_column_projection_current(operation)

    def _ensure_column_replay_available(self, target_side: str):
        """Validate that pending column operations can use native replay."""
        target_side = str(target_side or "").upper()
        operations = self.manual_a_column_ops if target_side == "A" else self.manual_b_column_ops
        if operations and not _EXCEL_NATIVE_SAVE_ON_MERGE:
            raise RuntimeError(
                f"{target_side} 侧还有 {len(operations)} 条列结构操作待保存。"
                "Excel 原生列回放已禁用；操作与撤销状态已保留，"
                "为避免 openpyxl 结构回退损坏文件，本次保存已停止。"
            )
        if operations:
            _validated_column_replay_operations(operations)

    def build_manual_merge_output_file(self):
        """Build merge output by XML-level patching from pristine mine snapshot."""
        self._ensure_live_column_mappings_current("构建合并输出")
        self._ensure_column_replay_available("A")
        src = self._merge_mine_snapshot if (self._merge_mine_snapshot and os.path.exists(self._merge_mine_snapshot)) else self.file_a
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        out = os.path.join(tempfile.gettempdir(), f"{APP_NAME}_merged_output_{os.getpid()}_{ts}{_workbook_ext(src)}")
        sheet_ops = self._sheet_ops_for_target("A", include_auto=True)
        column_ops = list(getattr(self, "manual_a_column_ops", []) or [])
        manual_ops = _prepare_manual_ops_for_save(
            src,
            self.manual_a_cell_ops,
            row_ops=self.manual_a_row_ops,
            sheet_ops=sheet_ops,
            column_ops=column_ops,
        )
        formula_cache_values = dict(getattr(self, "manual_a_formula_cache_ops", {}) or {})
        literal_text_values = {
            key: value for key, value in manual_ops.items()
            if isinstance(value, _LiteralText)
        }
        cached_values = dict(formula_cache_values)
        for sheet, row_idx, col_idx in manual_ops.keys():
            try:
                cached_values[(sheet, row_idx, col_idx)] = self.ws_a_val(sheet).cell(
                    row=int(row_idx), column=int(col_idx)
                ).value
            except Exception:
                pass
        zip_ops = dict(manual_ops)
        for key in formula_cache_values.keys():
            sheet, row_idx, col_idx = key
            try:
                formula = _formula_text(
                    self.ws_a_edit(sheet).cell(row=int(row_idx), column=int(col_idx)).value
                )
                if formula:
                    zip_ops[key] = formula
            except Exception:
                pass
        required_sources = {
            str(op.get("source_side") or "").upper()
            for op in (
                list(self.manual_a_row_ops)
                + list(sheet_ops)
                + list(column_ops)
            )
        }
        source_paths = {}
        if required_sources & {"B", "THEIRS"}:
            source_paths["B"] = self.file_b
        if "BASE" in required_sources and getattr(self, "base_path", None):
            source_paths["BASE"] = self.base_path
        if not zip_ops and not self.manual_a_row_ops and not sheet_ops and not column_ops:
            shutil.copy2(src, out)
            return out

        # Cell-only replay is safer at OOXML level: untouched formula caches and
        # shared-formula metadata stay intact, and text values keep their type.
        if not self.manual_a_row_ops and not sheet_ops and not column_ops:
            try:
                _build_manual_merge_xlsx_via_zip(
                    src,
                    out,
                    zip_ops,
                    cached_values=cached_values,
                    cache_only_keys=set(formula_cache_values),
                )
                return out
            except Exception as e:
                _dlog(f"validated cell-only ZIP patch failed; trying Excel native save: {e}")

        if _EXCEL_NATIVE_SAVE_ON_MERGE:
            ok = _build_manual_merge_output_with_excel(
                src,
                out,
                manual_ops,
                self.manual_a_row_ops,
                sheet_ops=sheet_ops,
                source_paths=source_paths,
                column_ops=column_ops,
            )
            if ok:
                if formula_cache_values or literal_text_values:
                    cache_out = out + ".formula-cache.xlsx"
                    post_save_ops = {
                        key: zip_ops[key] for key in formula_cache_values
                        if key in zip_ops
                    }
                    post_save_ops.update(literal_text_values)
                    _build_manual_merge_xlsx_via_zip(
                        out,
                        cache_out,
                        post_save_ops,
                        cached_values=formula_cache_values,
                        cache_only_keys=set(formula_cache_values),
                    )
                    os.replace(cache_out, out)
                    if column_ops and not _excel_reopen_validate(out):
                        try:
                            os.remove(out)
                        except Exception:
                            pass
                        raise RuntimeError(
                            "列结构输出的公式缓存补丁未通过 Excel 重开校验；"
                            "目标文件未被替换。"
                        )
                return out
            if column_ops:
                raise RuntimeError(
                    "Excel 原生列结构回放失败。为保护公式、宏和高级元数据，"
                    "已停止保存且未替换目标文件；请关闭占用文件的 Excel 后重试。"
                )
            _dlog("WARNING: excel native save failed, trying openpyxl replay fallback")
        if self.manual_a_row_ops or sheet_ops:
            unsafe_sources = [
                path for path in _replay_formula_source_paths(
                    src,
                    row_ops=self.manual_a_row_ops,
                    sheet_ops=sheet_ops,
                    source_paths=source_paths,
                )
                if _xlsx_requires_native_structural_replay(path)
            ]
            if unsafe_sources:
                raise RuntimeError(
                    "Excel 原生保存失败。为避免 openpyxl 回退破坏公式缓存或高级 Sheet 对象，"
                    "已停止保存且未替换目标文件；请关闭占用文件的 Excel 后重试。"
                    f"\n需要原生回放的来源文件：{', '.join(os.path.basename(path) for path in unsafe_sources)}"
                )
            ok = _build_manual_merge_output_with_openpyxl(
                src,
                out,
                manual_ops,
                self.manual_a_row_ops,
                sheet_ops=sheet_ops,
                source_paths=source_paths,
            )
            if ok:
                return out
            raise RuntimeError("manual merge output fallback failed for sheet/row operations")
        raise RuntimeError(
            "无法安全保存所选公式单元格：ZIP 校验未通过且 Excel 原生保存不可用。"
            "目标文件未被替换。"
        )

    def build_manual_b_output_file(self):
        """Build a 2-way B-side result by replaying structural operations safely."""
        self._ensure_live_column_mappings_current("构建B输出")
        self._ensure_column_replay_available("B")
        src = self._mine_working_path()
        ts = datetime.now().strftime("%Y%m%d_%H%M%S")
        out = os.path.join(
            tempfile.gettempdir(),
            f"{APP_NAME}_b_output_{os.getpid()}_{ts}{_workbook_ext(src)}",
        )
        row_ops = list(getattr(self, "manual_b_row_ops", []) or [])
        column_ops = list(getattr(self, "manual_b_column_ops", []) or [])
        sheet_ops = self._sheet_ops_for_target("B")
        manual_ops = _prepare_manual_ops_for_save(
            src,
            self.manual_b_cell_ops,
            row_ops=row_ops,
            sheet_ops=sheet_ops,
            column_ops=column_ops,
        )
        formula_cache_values = dict(getattr(self, "manual_b_formula_cache_ops", {}) or {})
        literal_text_values = {
            key: value for key, value in manual_ops.items()
            if isinstance(value, _LiteralText)
        }
        cached_values = dict(formula_cache_values)
        for sheet, row_idx, col_idx in manual_ops.keys():
            try:
                cached_values[(sheet, row_idx, col_idx)] = self.ws_b_val(sheet).cell(
                    row=int(row_idx), column=int(col_idx)
                ).value
            except Exception:
                pass
        zip_ops = dict(manual_ops)
        for key in formula_cache_values.keys():
            sheet, row_idx, col_idx = key
            try:
                formula = _formula_text(
                    self.ws_b_edit(sheet).cell(row=int(row_idx), column=int(col_idx)).value
                )
                if formula:
                    zip_ops[key] = formula
            except Exception:
                pass
        if not zip_ops and not row_ops and not sheet_ops and not column_ops:
            shutil.copy2(src, out)
            return out
        if not row_ops and not sheet_ops and not column_ops:
            try:
                _build_manual_merge_xlsx_via_zip(
                    src,
                    out,
                    zip_ops,
                    cached_values=cached_values,
                    cache_only_keys=set(formula_cache_values),
                )
                return out
            except Exception as exc:
                _dlog(
                    "validated B-side cell-only ZIP patch failed; "
                    f"trying Excel native save: {exc}"
                )
                try:
                    if os.path.exists(out):
                        os.remove(out)
                except Exception:
                    pass

        required_sources = {
            str(op.get("source_side") or "").upper()
            for op in (list(row_ops) + list(sheet_ops) + list(column_ops))
        }
        source_paths = {"A": self.file_a} if "A" in required_sources else {}
        if _EXCEL_NATIVE_SAVE_ON_MERGE and _build_manual_merge_output_with_excel(
            src,
            out,
            manual_ops,
            row_ops,
            sheet_ops=sheet_ops,
            source_paths=source_paths,
            column_ops=column_ops,
        ):
            if formula_cache_values or literal_text_values:
                cache_out = out + ".formula-cache.xlsx"
                post_save_ops = {
                    key: zip_ops[key] for key in formula_cache_values
                    if key in zip_ops
                }
                post_save_ops.update(literal_text_values)
                _build_manual_merge_xlsx_via_zip(
                    out,
                    cache_out,
                    post_save_ops,
                    cached_values=formula_cache_values,
                    cache_only_keys=set(formula_cache_values),
                )
                os.replace(cache_out, out)
                if column_ops and not _excel_reopen_validate(out):
                    try:
                        os.remove(out)
                    except Exception:
                        pass
                    raise RuntimeError(
                        "列结构输出的公式缓存补丁未通过 Excel 重开校验；"
                        "目标文件未被替换。"
                    )
            return out

        if not row_ops and not sheet_ops and not column_ops:
            raise RuntimeError(
                "无法安全保存所选空单元格：目标是数组/数据表公式，"
                "或共享公式无法安全展开；ZIP 改写失败且 Excel 原生保存不可用。"
                "目标文件未被替换；请关闭占用文件的 Excel 后重试。"
            )

        if column_ops:
            raise RuntimeError(
                "Excel 原生列结构回放失败。为保护公式、宏和高级元数据，"
                "已停止保存且未替换目标文件；请关闭占用文件的 Excel 后重试。"
            )

        unsafe_sources = [
            path for path in _replay_formula_source_paths(
                src,
                row_ops=row_ops,
                sheet_ops=sheet_ops,
                source_paths=source_paths,
            )
            if _xlsx_requires_native_structural_replay(path)
        ]
        if unsafe_sources:
            raise RuntimeError(
                "Excel 原生保存失败。为避免 openpyxl 插行破坏公式引用或高级 Sheet 对象，"
                "已停止保存且未替换目标文件；请关闭占用文件的 Excel 后重试。"
                f"\n需要原生回放的来源文件：{', '.join(os.path.basename(path) for path in unsafe_sources)}"
            )
        if _build_manual_merge_output_with_openpyxl(
            src,
            out,
            manual_ops,
            row_ops,
            sheet_ops=sheet_ops,
            source_paths=source_paths,
        ):
            return out
        raise RuntimeError("B-side structural replay failed")

    def _difference_items_from_view(self, view: "SheetView") -> list[DifferenceItem]:
        """Project the already-built SheetView cache into browser rows."""
        items: list[DifferenceItem] = []
        presentation = getattr(view, "role_presentation", RolePresentation.for_app(self))
        is_three_way = bool(
            getattr(self, "merge_mode", False) and getattr(self, "has_base", False)
        )
        base_value_label = presentation.middle if is_three_way else presentation.left
        mine_value_label = presentation.left if is_three_way else presentation.right
        theirs_value_label = presentation.right if is_three_way else "Theirs"
        conflict_map = getattr(self, "merge_conflict_cells_by_sheet", {}) or {}
        diff_sources = [(getattr(view, "pair_diff_cols", {}) or {}, False)]
        if self._three_way_model_active_for_view(view):
            diff_sources.append((getattr(view, "pair_base_diff_cols", {}) or {}, True))
        for diff_map, base_map in diff_sources:
            for pair_idx, cols in diff_map.items():
                if not cols:
                    continue
                try:
                    ra, rb = view.row_pairs[int(pair_idx)]
                except Exception:
                    continue
                row = ra or rb
                physical_row = row
                side_token = "B" if not base_map else "BASE"
                if -1 in cols:
                    base_row = None
                    if base_map:
                        # Browser projection remains complete while the UI is
                        # folded to two panes; use the cache override directly
                        # instead of requiring the optional three-way toggle.
                        overrides = getattr(view, "pair_base_row_override", {}) or {}
                        base_row = overrides.get(int(pair_idx))
                        if base_row is None:
                            base_row = overrides.get(str(pair_idx))
                        if base_row is None:
                            try:
                                base_row = view._base_row_for_pair(int(pair_idx), (ra, rb))
                            except Exception:
                                base_row = None
                    sentinel_row = row or base_row or int(pair_idx) + 1
                    if base_map and base_row is None and ra is not None and rb is not None:
                        sentinel_kind = DifferenceKind.ADDED
                        sentinel_summary = "Mine 与 Theirs 共同新增行"
                    elif base_map and base_row is not None and ra is None and rb is None:
                        sentinel_kind = DifferenceKind.DELETED
                        sentinel_summary = "Mine 与 Theirs 共同删除行"
                    elif not base_map:
                        sentinel_kind = DifferenceKind.ADDED if ra is None else DifferenceKind.DELETED
                        sentinel_summary = "目标侧缺失对应行"
                    else:
                        sentinel_kind = DifferenceKind.STRUCTURE
                        sentinel_summary = "行结构变化"
                    sentinel_id = f"{view.sheet}:pair:{int(pair_idx)}:side:{side_token}:kind:{sentinel_kind.value}:row:{sentinel_row}:sentinel"
                    items.append(DifferenceItem(
                        id=sentinel_id, sheet=view.sheet, kind=sentinel_kind,
                        row=sentinel_row, summary=sentinel_summary,
                        role=self.role_presentation_for_view(
                            view,
                            direction="BASE2A" if base_map else (
                                "B2A" if is_three_way else "A2B"
                            ),
                        ),
                        base_label=base_value_label,
                        mine_label=mine_value_label,
                        theirs_label=theirs_value_label,
                        processed=sentinel_id in self._difference_processed,
                    ))
                for logical_col in sorted(int(c) for c in cols if int(c) > 0):
                    conflict = bool(row and logical_col in (conflict_map.get(view.sheet, {}).get(row, {}) or {}))
                    kind = DifferenceKind.CONFLICT if conflict else DifferenceKind.MODIFIED
                    if ra is None and rb is not None:
                        kind = DifferenceKind.ADDED
                    elif rb is None and ra is not None:
                        kind = DifferenceKind.DELETED
                    item_id = f"{view.sheet}:pair:{int(pair_idx)}:side:{side_token}:kind:{kind.value}:row:{physical_row or 0}:col:{logical_col}"
                    # ``pair_parts_*`` is normally a tuple of physical-column
                    # display values.  Lightweight/legacy adapters may carry
                    # one scalar instead; leave it untouched and let the
                    # logical-value helper normalize both shapes.
                    a_value = self._view_pair_parts(view, "pair_parts_a", int(pair_idx))
                    b_value = self._view_pair_parts(view, "pair_parts_b", int(pair_idx))
                    base_parts = self._view_pair_parts(view, "pair_parts_base", int(pair_idx))
                    if is_three_way:
                        mine_value, theirs_value, base_value = a_value, b_value, base_parts
                    else:
                        base_value, mine_value, theirs_value = a_value, b_value, ()
                    base_value = self._logical_value_from_view(
                        view,
                        int(pair_idx),
                        logical_col,
                        "BASE" if is_three_way else "A",
                        base_value,
                    )
                    mine_value = self._logical_value_from_view(
                        view,
                        int(pair_idx),
                        logical_col,
                        "A" if is_three_way else "B",
                        mine_value,
                    )
                    theirs_value = (
                        self._logical_value_from_view(
                            view, int(pair_idx), logical_col, "B", theirs_value
                        )
                        if is_three_way
                        else None
                    )
                    items.append(DifferenceItem(
                        id=item_id, sheet=view.sheet, kind=kind, row=row, column=logical_col,
                        summary=f"逻辑列 {get_column_letter(logical_col)} 的值或公式不同",
                        role=self.role_presentation_for_view(
                            view,
                            logical_col,
                            direction="BASE2A" if base_map else (
                                "B2A" if is_three_way else "A2B"
                            ),
                        ),
                        base_label=base_value_label,
                        mine_label=mine_value_label,
                        theirs_label=theirs_value_label,
                        processed=item_id in self._difference_processed, conflict=conflict,
                        base_value=base_value,
                        mine_value=mine_value,
                        theirs_value=theirs_value,
                        source_side="base" if base_map else (
                            "theirs" if is_three_way else "base"
                        ),
                        target_side="mine",
                    ))
        # A structural block has no single cell location; keep it in the same
        # list so users can see why a sheet is not fully resolved.
        projection = getattr(view, "column_comparison_cache", None)
        structural = getattr(projection, "structural_diff_cols", ()) if projection is not None else ()
        for logical_col in sorted(int(c) for c in (structural or ()) if int(c) > 0):
            item_id = f"{view.sheet}:pair:-1:side:structure:kind:structure:row:0:col:{logical_col}"
            items.append(DifferenceItem(
                id=item_id, sheet=view.sheet, kind=DifferenceKind.STRUCTURE,
                column=logical_col, summary=f"逻辑列 {get_column_letter(logical_col)} 存在结构变化",
                role=self.role_presentation_for_view(
                    view,
                    direction="B2A" if is_three_way else "A2B",
                ), processed=item_id in self._difference_processed,
                base_label=base_value_label,
                mine_label=mine_value_label,
                theirs_label=theirs_value_label,
            ))
        return items

    @staticmethod
    def _value_from_parts(
        parts,
        physical_col: int | None,
        logical_col: int,
        *,
        projection_known: bool = False,
    ):
        """Read one value from either a physical row tuple or a scalar.

        Difference rows are a presentation model, not a second workbook
        representation.  In particular, once a caller has resolved a value
        to a scalar (including ``str``, ``int``, ``float`` or ``None``), it
        must never be sent through ``len`` or indexed again.  Treat strings
        and bytes as scalar cell values and only index concrete row
        sequences.
        """
        if projection_known and physical_col is None:
            # ``None`` is an authoritative missing-side mapping when a valid
            # projection answered the lookup.  Never fall through to the
            # adjacent logical column in that case.
            return None
        if parts is None:
            return None
        if isinstance(parts, (str, bytes, bytearray)):
            return parts
        if not isinstance(parts, Sequence):
            return parts
        try:
            index = int(physical_col if physical_col is not None else logical_col) - 1
        except (TypeError, ValueError):
            return None
        if index < 0 or index >= len(parts):
            return None
        return parts[index]

    @classmethod
    def _logical_value_from_view(cls, view: "SheetView", pair_idx: int, logical_col: int, side: str, parts):
        projection_known = False
        try:
            projection = view._active_column_projection()
            if projection is None:
                raise LookupError("column projection unavailable")
            resolver = getattr(projection, "physical_col", None)
            if not callable(resolver):
                raise LookupError("column projection has no physical lookup")
            physical = resolver(side, logical_col)
            projection_known = True
        except Exception:
            physical = None
        return cls._value_from_parts(
            parts,
            physical,
            logical_col,
            projection_known=projection_known,
        )

    @staticmethod
    def _three_way_model_active_for_view(view: "SheetView") -> bool:
        enabled = bool(getattr(view, "_is_three_way_enabled", lambda: False)())
        if enabled:
            return True
        app = getattr(view, "app", None)
        # A folded merge view still owns a complete Base-relative cache.  The
        # browser must expose those structural rows even before the user
        # expands the third pane.
        return bool(
            getattr(app, "merge_mode", False)
            and getattr(app, "has_base", False)
            and getattr(view, "pair_base_diff_cols", None)
        )

    @classmethod
    def _logical_value_from_cache(cls, cache: dict, pair_idx: int, logical_col: int, side: str, parts):
        projection_known = False
        try:
            projection = cache.get("column_comparison_cache")
            if projection is None:
                raise LookupError("column projection unavailable")
            resolver = getattr(projection, "physical_col", None)
            if not callable(resolver):
                raise LookupError("column projection has no physical lookup")
            physical = resolver(side, logical_col)
            projection_known = True
        except Exception:
            physical = None
        return cls._value_from_parts(
            parts,
            physical,
            logical_col,
            projection_known=projection_known,
        )

    @staticmethod
    def _cache_pair_parts(cache: dict, name: str, pair_idx: int):
        values = cache.get(name, {}) or {}
        if not isinstance(values, dict):
            return None
        value = values.get(pair_idx)
        if value is None and str(pair_idx) in values:
            value = values.get(str(pair_idx))
        return value

    @staticmethod
    def _view_pair_parts(view: "SheetView", name: str, pair_idx: int):
        values = getattr(view, name, {}) or {}
        if not isinstance(values, dict):
            return None
        value = values.get(pair_idx)
        if value is None and str(pair_idx) in values:
            value = values.get(str(pair_idx))
        return value

    def _difference_items_from_cache(self, cache: dict) -> list[DifferenceItem]:
        """Project an unopened Sheet's background cache without creating Tk widgets."""
        sheet = str(cache.get("sheet") or "")
        pairs = list(cache.get("row_pairs") or ())
        diff_map = cache.get("pair_diff_cols", {}) or {}
        items: list[DifferenceItem] = []
        presentation = RolePresentation.for_app(self)
        is_three_way = bool(
            getattr(self, "merge_mode", False) and getattr(self, "has_base", False)
        )
        base_value_label = presentation.middle if is_three_way else presentation.left
        mine_value_label = presentation.left if is_three_way else presentation.right
        theirs_value_label = presentation.right if is_three_way else "Theirs"
        for raw_idx, cols in diff_map.items():
            idx = int(raw_idx)
            if not (0 <= idx < len(pairs)):
                continue
            ra, rb = pairs[idx]
            row = ra or rb
            base_kind = DifferenceKind.ADDED if ra is None else DifferenceKind.DELETED if rb is None else DifferenceKind.MODIFIED
            if -1 in cols:
                sentinel_row = row or idx + 1
                sentinel_kind = DifferenceKind.ADDED if ra is None else DifferenceKind.DELETED
                sentinel_id = f"{sheet}:pair:{idx}:side:B:kind:{sentinel_kind.value}:row:{sentinel_row}:sentinel"
                items.append(DifferenceItem(
                    id=sentinel_id, sheet=sheet, kind=sentinel_kind, row=sentinel_row,
                    summary="目标侧缺失对应行", role=self.role_presentation_for_cache(
                        "A2B" if not is_three_way else "B2A"
                    ),
                    base_label=base_value_label,
                    mine_label=mine_value_label,
                    theirs_label=theirs_value_label,
                    processed=sentinel_id in self._difference_processed,
                ))
            for col in sorted(int(value) for value in cols if int(value) > 0):
                conflict = bool(row and col in (getattr(self, "merge_conflict_cells_by_sheet", {}).get(sheet, {}).get(row, {}) or {}))
                item_kind = DifferenceKind.CONFLICT if conflict else base_kind
                item_id = f"{sheet}:pair:{idx}:side:B:kind:{item_kind.value}:row:{row or 0}:col:{col}"
                # Keep scalar values (0, empty text, None) intact.  The
                # logical resolver handles both row tuples and scalar values.
                mine_value = self._cache_pair_parts(cache, "pair_parts_a", idx)
                theirs_value = self._cache_pair_parts(cache, "pair_parts_b", idx)
                base_value = self._cache_pair_parts(cache, "pair_parts_base", idx)
                if is_three_way:
                    display_base = self._logical_value_from_cache(cache, idx, col, "BASE", base_value)
                    display_mine = self._logical_value_from_cache(cache, idx, col, "A", mine_value)
                    display_theirs = self._logical_value_from_cache(cache, idx, col, "B", theirs_value)
                else:
                    display_base = self._logical_value_from_cache(cache, idx, col, "A", mine_value)
                    display_mine = self._logical_value_from_cache(cache, idx, col, "B", theirs_value)
                    display_theirs = None
                items.append(DifferenceItem(
                    id=item_id, sheet=sheet, kind=item_kind, row=row, column=col,
                    summary=f"逻辑列 {get_column_letter(col)} 的值或公式不同",
                    role=self.role_presentation_for_cache(
                        "B2A" if is_three_way else "A2B"
                    ), processed=item_id in self._difference_processed, conflict=conflict,
                    base_label=base_value_label,
                    mine_label=mine_value_label,
                    theirs_label=theirs_value_label,
                    base_value=display_base, mine_value=display_mine, theirs_value=display_theirs,
                    source_side="theirs" if is_three_way else "base",
                    target_side="mine",
                ))
        projection = cache.get("column_comparison_cache")
        for raw_idx, cols in (cache.get("pair_base_diff_cols", {}) or {}).items():
            idx = int(raw_idx)
            if not (0 <= idx < len(pairs)):
                continue
            ra, rb = pairs[idx]
            row = ra or rb or idx + 1
            for col in sorted(int(value) for value in cols if int(value) > 0):
                item_id = f"{sheet}:pair:{idx}:side:BASE:kind:modified:row:{row}:col:{col}"
                base_parts = self._cache_pair_parts(cache, "pair_parts_base", idx)
                mine_parts = self._cache_pair_parts(cache, "pair_parts_a", idx)
                items.append(DifferenceItem(
                    id=item_id, sheet=sheet, kind=DifferenceKind.MODIFIED, row=row, column=col,
                    summary=f"逻辑列 {get_column_letter(col)} 的 Mine/Base 值或公式不同",
                    role=self.role_presentation_for_cache("BASE2A"), processed=item_id in self._difference_processed,
                    base_label=base_value_label,
                    mine_label=mine_value_label,
                    theirs_label=theirs_value_label,
                    base_value=self._logical_value_from_cache(cache, idx, col, "BASE", base_parts),
                    mine_value=self._logical_value_from_cache(cache, idx, col, "A", mine_parts),
                    theirs_value=self._logical_value_from_cache(
                        cache, idx, col, "B", self._cache_pair_parts(cache, "pair_parts_b", idx)
                    ),
                    source_side="base", target_side="mine",
                ))
        for col in sorted(int(value) for value in getattr(projection, "structural_diff_cols", ()) if int(value) > 0):
            item_id = f"{sheet}:pair:-1:side:structure:kind:structure:row:0:col:{col}"
            items.append(DifferenceItem(
                id=item_id, sheet=sheet, kind=DifferenceKind.STRUCTURE, column=col,
                summary=f"逻辑列 {get_column_letter(col)} 存在结构变化", role=self.role_presentation_for_cache(
                    "B2A" if is_three_way else "A2B"
                ),
                processed=item_id in self._difference_processed,
                base_label=base_value_label,
                mine_label=mine_value_label,
                theirs_label=theirs_value_label,
            ))
        for raw_idx, cols in (cache.get("pair_base_diff_cols", {}) or {}).items():
            if -1 not in cols:
                continue
            idx = int(raw_idx)
            if not (0 <= idx < len(pairs)):
                continue
            ra, rb = pairs[idx]
            base_row = (cache.get("pair_base_row_override", {}) or {}).get(idx)
            if base_row is None:
                base_row = (cache.get("pair_base_row_override", {}) or {}).get(str(idx))
            if base_row is None and ra is not None:
                base_row = (cache.get("mine_to_base_row", {}) or {}).get(ra)
                if base_row is None:
                    base_row = (cache.get("mine_to_base_row", {}) or {}).get(str(ra))
            if base_row is None and rb is not None:
                base_row = (cache.get("theirs_to_base_row", {}) or {}).get(rb)
                if base_row is None:
                    base_row = (cache.get("theirs_to_base_row", {}) or {}).get(str(rb))
            row = ra or rb or base_row or idx + 1
            if base_row is None and ra is not None and rb is not None:
                kind, summary = DifferenceKind.ADDED, "Mine 与 Theirs 共同新增行"
            elif base_row is not None and ra is None and rb is None:
                kind, summary = DifferenceKind.DELETED, "Mine 与 Theirs 共同删除行"
            else:
                kind, summary = DifferenceKind.DELETED, "Base-only 行：Mine 与 Theirs 均无对应行"
            item_id = f"{sheet}:pair:{idx}:side:BASE:kind:{kind.value}:row:{row}:sentinel"
            items.append(DifferenceItem(
                id=item_id, sheet=sheet, kind=kind, row=row,
                summary=summary, role=self.role_presentation_for_cache(
                    "BASE2A" if is_three_way else "A2B"
                ),
                base_label=base_value_label,
                mine_label=mine_value_label,
                theirs_label=theirs_value_label,
                processed=item_id in self._difference_processed,
            ))
        return items

    def role_presentation_for_cache(self, direction: str | None = None) -> str:
        presentation = RolePresentation.for_app(self)
        if direction is None:
            direction = "B2A" if getattr(self, "merge_mode", False) else "A2B"
        return presentation.action_label(direction)

    def role_presentation_for_view(
        self,
        view: "SheetView",
        logical_col: int = 0,
        *,
        direction: str | None = None,
    ) -> str:
        try:
            presentation = getattr(view, "role_presentation", RolePresentation.for_app(self))
            if direction is None:
                direction = "B2A" if getattr(self, "merge_mode", False) else "A2B"
            return presentation.action_label(direction)
        except Exception:
            return self.role_presentation_for_cache(direction)

    def refresh_difference_browser(self) -> None:
        if self._diff_browser is None:
            return
        items: list[DifferenceItem] = []
        loaded_sheets = set()
        for view in getattr(self, "sheet_views", {}).values():
            if view is not None and getattr(view, "_data_ready", False):
                items.extend(self._difference_items_from_view(view))
                loaded_sheets.add(view.sheet)
        for sheet, cache in getattr(self, "_sheet_cache_store", {}).items():
            if sheet not in loaded_sheets:
                items.extend(self._difference_items_from_cache(cache))
        self.difference_items = tuple({item.id: item for item in items}.values())
        counts: dict[str, int] = {}
        total_counts: dict[str, int] = {}
        for item in self.difference_items:
            total_counts[item.sheet] = total_counts.get(item.sheet, 0) + 1
            counts[item.sheet] = counts.get(item.sheet, 0) + (0 if item.processed else 1)
        self.sheet_diff_counts = counts
        self.sheet_diff_total_counts = total_counts
        model = getattr(self, "_sheet_filter_model", None)
        if model is not None:
            model.update_counts_from_items(self.difference_items)
        self._diff_browser.set_items(items)
        self.refresh_sheet_nav()
        self._refresh_command_widgets()

    def _persist_difference_browser_layout(self, height: int, collapsed: bool) -> None:
        settings = getattr(self, "settings", None)
        if not isinstance(settings, dict):
            return
        settings["difference_browser_height"] = max(90, min(460, int(height)))
        settings["difference_browser_collapsed"] = bool(collapsed)
        self._schedule_layout_settings_save()

    def _schedule_layout_settings_save(self) -> None:
        """Persist layout changes after a short drag debounce."""
        root = getattr(self, "root", None)
        if root is None or getattr(self, "_is_closing", False):
            return
        pending = getattr(self, "_layout_save_after_id", None)
        if pending:
            try:
                root.after_cancel(pending)
            except (tk.TclError, RuntimeError):
                pass
        try:
            self._layout_save_after_id = root.after(500, self._write_layout_settings)
        except (tk.TclError, RuntimeError):
            self._layout_save_after_id = None

    def _write_layout_settings(self) -> None:
        self._layout_save_after_id = None
        try:
            os.makedirs(os.path.dirname(_SETTINGS_PATH), exist_ok=True)
            with open(_SETTINGS_PATH, "w", encoding="utf-8") as stream:
                json.dump(getattr(self, "settings", {}) or {}, stream, ensure_ascii=False, indent=2)
        except (OSError, TypeError, ValueError) as exc:
            _dlog(f"layout settings save failed: {exc}")

    def _apply_sheet_nav_height(self, *, persist: bool = True) -> None:
        from .vertical_layout import VerticalLayout

        layout = VerticalLayout(
            nav_height=int(getattr(self, "_sheet_nav_height", 34)),
        ).normalized(
            max(360, int(self.root.winfo_height() or 620)),
        )
        self._sheet_nav_height = layout.nav_height
        try:
            self.bottom.configure(height=self._sheet_nav_height)
            self.nav_canvas.configure(height=max(18, self._sheet_nav_height - 10))
        except (AttributeError, tk.TclError):
            return
        if persist:
            self.settings["sheet_nav_height"] = self._sheet_nav_height
            self._schedule_layout_settings_save()

    def _on_sheet_nav_grip_press(self, event) -> None:
        self._sheet_nav_drag_origin = (
            int(event.y_root),
            int(getattr(self, "_sheet_nav_height", 34)),
        )

    def _on_sheet_nav_grip_motion(self, event) -> None:
        origin_y, origin_height = getattr(
            self,
            "_sheet_nav_drag_origin",
            (int(event.y_root), int(getattr(self, "_sheet_nav_height", 34))),
        )
        self._sheet_nav_height = origin_height + origin_y - int(event.y_root)
        self._apply_sheet_nav_height()

    def _reset_workspace_layout(self) -> None:
        self.settings.pop("vertical_sashes", None)
        self.settings["sheet_nav_height"] = 34
        for view in getattr(self, "sheet_views", {}).values():
            if view is not None:
                view.reset_vertical_layout()
        self._sheet_nav_height = 34
        self._apply_sheet_nav_height(persist=False)
        diff_browser = getattr(self, "_diff_browser", None)
        if diff_browser is not None:
            diff_browser.set_layout(
                height=150,
                collapsed=False,
                notify=False,
            )
        self._schedule_layout_settings_save()

    def _on_global_reset_layout(self, _event=None):
        self._reset_workspace_layout()
        return "break"

    def _persist_difference_browser_preferences(self) -> None:
        if self._diff_browser is None:
            return
        settings = getattr(self, "settings", {})
        settings["difference_browser_query"] = self._diff_browser.query_var.get()
        settings["difference_browser_unprocessed"] = bool(self._diff_browser.unprocessed_var.get())
        settings["difference_browser_conflicts"] = bool(self._diff_browser.conflicts_var.get())

    def get_difference_items(self, limit: int = 500) -> tuple[DifferenceItem, ...]:
        """Return a bounded snapshot suitable for tests, diagnostics or plugins."""
        self.refresh_difference_browser()
        return tuple(self.difference_items[: max(0, int(limit))])

    def mark_difference_processed(self, item_id: str, processed: bool = True) -> None:
        """Incrementally update the browser after an explicit merge action."""
        key = str(item_id)
        keys = {key}
        if ":structure:" in key:
            col = key.rsplit(":", 1)[-1]
            # Persist the canonical browser ID even when a structural action
            # completes before the first difference-browser snapshot exists.
            # The next cache refresh can then restore the processed badge
            # without relying on the legacy short alias.
            if col.isdigit() and ":pair:" not in key:
                sheet = key.split(":structure:", 1)[0]
                keys.add(
                    f"{sheet}:pair:-1:side:structure:kind:structure:row:0:col:{col}"
                )
            if ":pair:" not in key:
                sheet = key.split(":structure:", 1)[0]
                keys.update(
                    item.id
                    for item in self.difference_items
                    if item.sheet == sheet
                    and item.kind == DifferenceKind.STRUCTURE
                    and item.id.endswith(f":col:{col}")
                )
        for stable_key in keys:
            if processed:
                self._difference_processed.add(stable_key)
            else:
                self._difference_processed.discard(stable_key)
        if self._diff_browser is not None:
            self._diff_browser.mark_processed(key, processed)

    def mark_structure_difference_processed(
        self, sheet: str, logical_col: int, processed: bool = True
    ) -> None:
        """Mark the real structural DifferenceItem IDs for a column action.

        Structural operations can span one or more physical columns, while
        the browser exposes a stable logical-column item.  Resolve those IDs
        from the current read-only view model first; retain the old compact
        alias only as a compatibility fallback for callers with no browser
        snapshot yet.
        """
        sheet = str(sheet)
        logical_col = int(logical_col)
        matches = [
            item.id
            for item in getattr(self, "difference_items", ())
            if item.sheet == sheet
            and item.kind == DifferenceKind.STRUCTURE
            and int(item.column or 0) == logical_col
        ]
        if matches:
            for item_id in matches:
                self.mark_difference_processed(item_id, processed)
            return
        self.mark_difference_processed(f"{sheet}:structure:{logical_col}", processed)

    def mark_difference_items_processed(
        self, item_ids: Iterable[str], processed: bool = True
    ) -> tuple[str, ...]:
        """Batch-update browser state once for a retain/global acknowledgement."""
        ids = tuple(dict.fromkeys(str(item_id) for item_id in (item_ids or ()) if item_id))
        if not ids:
            return ()
        for item_id in ids:
            if processed:
                self._difference_processed.add(item_id)
            else:
                self._difference_processed.discard(item_id)
        browser = getattr(self, "_diff_browser", None)
        if browser is not None:
            try:
                for item_id in ids:
                    browser.index.update(item_id, processed=processed)
                selected = browser.tree.selection()[0] if browser.tree.selection() else None
                browser.render()
                if selected and selected in getattr(browser, "_rendered", {}):
                    browser.tree.selection_set(selected)
                    browser.tree.focus(selected)
            except Exception:
                pass
        return ids

    def mark_difference_pair_processed(
        self,
        sheet: str,
        pair_idx: int,
        columns: Iterable[int] | None = None,
        processed: bool = True,
    ) -> tuple[str, ...]:
        """Mark the stable DifferenceItem IDs belonging to one aligned pair."""
        sheet = str(sheet)
        pair_idx = int(pair_idx)
        requested = tuple(int(value) for value in (columns or ()))
        wanted = {value for value in requested if value > 0}
        matches = []
        for item in getattr(self, "difference_items", ()):
            if item.sheet != sheet or f":pair:{pair_idx}:" not in item.id:
                continue
            if requested:
                if item.column is None:
                    if -1 not in requested:
                        continue
                elif int(item.column) not in wanted:
                    continue
            matches.append(item.id)
        return self.mark_difference_items_processed(matches, processed)

    def mark_difference_row_processed(
        self, sheet: str, row: int, processed: bool = True
    ) -> tuple[str, ...]:
        """Mark all real DifferenceItems on one row and return their IDs.

        The row alias predates pair-based IDs and remains a compatibility
        fallback for callers that cannot resolve a current pair.  Returning
        the concrete IDs is essential for compound/region retain actions:
        their undo entry must carry the same stable IDs that were actually
        marked, rather than an empty legacy return value.
        """
        sheet = str(sheet)
        row = int(row)
        prefix = f"{sheet}:row:{row}:"
        matches = tuple(
            dict.fromkeys(
                str(item.id)
                for item in self.difference_items
                if item.id.startswith(prefix)
                or (item.sheet == sheet and item.row == row)
            )
        )
        for item_id in matches:
            self.mark_difference_processed(item_id, processed)
        self.refresh_difference_browser()
        return matches

    def command_state(self) -> CommandState:
        """Return one authoritative snapshot for toolbar enablement."""
        view = getattr(self, "sheet_views", {}).get(getattr(self, "selected_sheet", ""))
        vcs_two_way = self._is_vcs_two_way_mode()
        unsaved = (
            bool(getattr(self, "modified_b", False))
            if vcs_two_way
            else bool(getattr(self, "modified_a", False) or getattr(self, "modified_b", False))
        )
        return CommandState(
            busy=bool(getattr(self, "_is_closing", False) or getattr(self, "_interactive_action_event", threading.Event()).is_set()),
            ready=bool(view is not None and getattr(view, "_data_ready", False)),
            has_selection=bool(view is not None and getattr(view, "selected_pair_idx", None) is not None),
            has_unsaved_changes=unsaved,
            has_conflicts=bool(getattr(self, "merge_conflict_cells_by_sheet", {})),
            can_save=bool(getattr(self, "merged_path", None) or unsaved),
            can_undo=bool(getattr(self, "undo_stack", [])),
        )

    def _refresh_command_widgets(self) -> None:
        state = self.command_state()
        mapping = {
            "top_prev_btn": "previous", "top_next_btn": "next", "top_search_btn": "search",
            "top_filter_btn": "filter", "top_apply_btn": "apply_source", "top_retain_btn": "retain",
            "top_base_btn": "base", "top_undo_btn": "undo", "primary_save_btn": "save_merged",
            "top_save_as_btn": "save_as",
        }
        for name, command in mapping.items():
            widget = getattr(self, name, None)
            if widget is None:
                continue
            try:
                enabled = state.enabled(command)
                # Retaining Mine is only a three-way conflict acknowledgement;
                # it is not a valid two-way command.  Likewise, VCS two-way
                # comparisons protect the A/Base temporary copy from any
                # reverse-direction action.
                if name == "top_retain_btn" and not (
                    getattr(self, "merge_mode", False)
                    and getattr(self, "has_base", False)
                ):
                    enabled = False
                widget.configure(state="normal" if enabled else "disabled")
            except Exception:
                pass

    def _on_difference_selected(self, item: DifferenceItem) -> None:
        # Keep the browser's stable identity attached to the loaded view so a
        # subsequent structural/row action and its undo can update exactly
        # that item instead of rebuilding a location-based approximation.
        view = getattr(self, "sheet_views", {}).get(item.sheet)
        if view is not None:
            try:
                view._selected_difference_item_id = item.id
            except Exception:
                pass
            # Structural/synthetic rows (for example a Base-only row deleted
            # by both sides) have no physical Mine/Theirs row number.  Their
            # stable DifferenceItem ID still carries the exact aligned pair;
            # use that pair for navigation before falling back to a raw Excel
            # row lookup.
            match = re.search(r":pair:(\d+):", str(item.id or ""))
            if match:
                try:
                    pair_idx = int(match.group(1))
                    if view._materialize_pair_for_navigation(pair_idx):
                        line = view.row_to_line.get(pair_idx)
                        if line is not None:
                            view._goto_block_start(int(line))
                            view._set_main_selected_cell(int(line), int(item.column or 1))
                            view.selected_pair_idx = pair_idx
                            view._update_cursor_lines()
                            view._update_diff_nav_state()
                            return
                except Exception:
                    pass
        if item.row is None:
            return
        self._navigate_to_conflict_cell(item.sheet, int(item.row), int(item.column or 1))

    def _sheet_filter_status(self, sheet: str):
        model = getattr(self, "_sheet_filter_model", None)
        if model is None:
            return None
        try:
            return model.status(sheet)
        except (KeyError, TypeError):
            return None

    def mark_sheet_loading(self, sheet: str) -> None:
        model = getattr(self, "_sheet_filter_model", None)
        if model is None:
            return
        model.mark_loading(sheet)
        if not bool(getattr(self, "_defer_sheet_nav_refresh", False)):
            self.refresh_sheet_nav()

    def mark_sheet_failed(self, sheet: str, error: str = "") -> None:
        model = getattr(self, "_sheet_filter_model", None)
        if model is None:
            return
        model.mark_failed(sheet, error)
        if not bool(getattr(self, "_defer_sheet_nav_refresh", False)):
            self.refresh_sheet_nav()

    def _select_sheet_for_filter(self, sheet: str | None) -> None:
        if not sheet or sheet == getattr(self, "selected_sheet", None):
            return
        self._sheet_filter_programmatic_select = True
        try:
            self._select_tab(sheet)
        finally:
            self._sheet_filter_programmatic_select = False

    def _sync_sheet_filter_selection(self) -> None:
        model = getattr(self, "_sheet_filter_model", None)
        if model is None:
            return
        current = getattr(self, "selected_sheet", None)
        status = self._sheet_filter_status(current) if current else None
        # Do not jump while the current sheet is still unknown/loading. Once
        # it is confirmed clean, select the first confirmed diff in stable
        # workbook order. This consumes state only; it never queues a scan.
        if (
            model.only_diff
            and current
            and status is not None
            and status.wait_like
            and (not model.auto_select_pending or not model.confirmed_diff_names())
        ):
            return
        target = model.preferred_sheet(current)
        if target and target != current:
            self._select_sheet_for_filter(target)

    def _set_sheet_filter_mode(self, mode: str) -> None:
        model = getattr(self, "_sheet_filter_model", None)
        if model is None:
            return
        model.set_mode(mode)
        self._sync_sheet_filter_selection()
        self.refresh_sheet_nav()

    def _sheet_filter_nav_names(self) -> tuple[str, ...]:
        model = getattr(self, "_sheet_filter_model", None)
        return model.visible_names() if model is not None else tuple(self.display_sheets)

    def set_sheet_has_diff(self, sheet: str, has: bool, confirmed: bool = True):
        # Keep API: mark sheet diff state
        if sheet not in self.sheet_diff_state:
            return
        confirmed_sheets = getattr(self, "_sheet_diff_confirmed", None)
        if confirmed_sheets is None:
            self._sheet_diff_confirmed = set()
            confirmed_sheets = self._sheet_diff_confirmed
        if not confirmed and sheet in confirmed_sheets:
            # A late Stage-1 callback must never overwrite an exact result.
            return
        if confirmed:
            confirmed_sheets.add(sheet)
        if has:
            self.sheet_diff_state[sheet] = 2 if confirmed else max(self.sheet_diff_state[sheet], 1)
        else:
            # only downgrade when confirmed
            if confirmed:
                self.sheet_diff_state[sheet] = 0
        model = getattr(self, "_sheet_filter_model", None)
        if model is not None:
            model.publish(
                sheet,
                has,
                count=int(getattr(self, "sheet_diff_total_counts", {}).get(sheet, 0)),
                confirmed=confirmed,
            )
            self._sync_sheet_filter_selection()

    def _active_sheet_name(self) -> str | None:
        try:
            tab_id = self.nb.select()
            if not tab_id:
                return None
            tab_text = str(self.nb.tab(tab_id, "text") or "").strip()
            return tab_text or None
        except Exception:
            return None

    def _on_global_f4(self, event=None):
        """Route F4 to the currently active sheet view only."""
        try:
            sheet = self._active_sheet_name()
            if not sheet:
                return None
            view = self.sheet_views.get(sheet)
            if view is None and sheet in self._sheet_containers:
                try:
                    self.nb.select(self._sheet_containers[sheet])
                    self.root.update_idletasks()
                    self.root.update()
                    view = self.sheet_views.get(sheet)
                except Exception:
                    view = None
            if view is None:
                return None
            return view._on_hover_compare_f4_toggle(event)
        except Exception:
            return None

    def _set_task_status(
        self,
        message: str,
        *,
        active: bool = False,
        current: int | None = None,
        total: int | None = None,
    ):
        """Update the always-visible application task status strip."""
        label = getattr(self, "task_status_var", None)
        progress = getattr(self, "task_progress", None)
        if label is None or progress is None:
            return
        try:
            label.set(message)
            if active:
                if total and total > 0 and current is not None:
                    progress.stop()
                    progress.configure(mode="determinate", maximum=max(1, total), value=max(0, min(current, total)))
                else:
                    progress.configure(mode="indeterminate")
                    progress.start(12)
            else:
                progress.stop()
                if total and total > 0:
                    progress.configure(mode="determinate", maximum=total, value=total)
                else:
                    progress.configure(mode="determinate", maximum=100, value=0)
        except Exception:
            pass

    def _hide_nonblocking_notice(self):
        aid = getattr(self, "_notice_after_id", None)
        if aid is not None:
            try:
                self.root.after_cancel(aid)
            except Exception:
                pass
        self._notice_after_id = None
        try:
            self.notice_frame.pack_forget()
        except Exception:
            pass

    def show_nonblocking_notice(
        self,
        message: str,
        *,
        warning: bool = False,
        duration_ms: int = 15000,
    ):
        """Show an in-window reminder without focus, grab, or wait_window."""
        self._hide_nonblocking_notice()
        bg = "#FDE2E2" if warning else "#E8F2FF"
        fg = "#A40000" if warning else "#174A7E"
        try:
            self.notice_frame.configure(bg=bg)
            self.notice_label.configure(bg=bg, fg=fg)
            self.notice_close.configure(bg=bg, activebackground=bg, fg=fg)
            self.notice_var.set(str(message or ""))
            self.notice_frame.pack(
                fill="x",
                padx=10,
                pady=(0, 4),
                before=self.nb,
            )
            if int(duration_ms or 0) > 0:
                self._notice_after_id = self._safe_root_after(
                    int(duration_ms),
                    self._hide_nonblocking_notice,
                )
        except Exception as e:
            _dlog(f"nonblocking notice failed: {e}")

    def show_startup_outcome_dialog_deferred(self):
        """Show the single post-analysis modal after the main window is visible."""
        if not self.merge_mode or getattr(self, "launch_context", None) is None:
            return
        self._safe_root_after(350, self._show_startup_outcome_dialog)

    def _show_startup_outcome_dialog(self):
        if self._is_closing:
            return
        outcome = getattr(self, "startup_outcome", None)
        context = getattr(self, "launch_context", None)
        if outcome is None or context is None:
            return
        try:
            dialog = tk.Toplevel(self.root)
            dialog.title("三方合并启动结果")
            dialog.transient(self.root)
            dialog.resizable(False, False)
            dialog.configure(bg=self.workspace_chrome_color)
            body = tk.Frame(dialog, bg=self.workspace_chrome_color, padx=18, pady=14)
            body.pack(fill="both", expand=True)
            is_cross_branch = context.scenario == MergeScenario.CROSS_BRANCH_MERGE
            action_label = {
                "initialize-from-theirs": "已由 Theirs 初始化合并候选",
                "initialize-from-mine": "已由 Mine 初始化合并候选",
                "initialize-from-common-mine-theirs": "Mine 与 Theirs 相同，已初始化共同候选",
                "initialize-from-mine-empty-branch-delta": "源分支无变化，已保留 Mine",
                "semantic-premerge": "已应用安全的 Base 锚定语义预合并",
                "cross-branch-source-delta": "已将 Source Before → Source After 的变更投影到 Target Working",
                "incoming-already-present": "所有支持的 incoming 变更已存在于 Target Working；候选保持原始内容",
                "manual-review": "未执行不安全的自动合并，保留人工三方审查",
            }.get(outcome.automatic_action, outcome.automatic_action)
            if is_cross_branch:
                action_label = {
                    "initialize-from-theirs": "Target Working 等于 Source Before，已由 Source After 初始化候选",
                    "initialize-from-mine": "Source After 等于 Source Before，已保留 Target Working",
                    "initialize-from-common-mine-theirs": "Target Working 与 Source After 相同，已保留共同候选",
                    "initialize-from-mine-empty-branch-delta": "Source Before 与 Source After 相同，已保留 Target Working",
                }.get(outcome.automatic_action, action_label)
            lines = [
                f"场景：{context.scenario.value}",
                action_label,
                "等价证据：" + ("；".join(outcome.equality_evidence) or "无完整包等价收敛"),
            ]
            if is_cross_branch:
                lines.append(
                    "Source delta："
                    f"incoming {outcome.incoming_count} 项；applied {outcome.applied_count} 项；"
                    f"already present {outcome.already_present_count} 项；"
                    f"target retained {outcome.target_retained_count} 项；"
                    f"unresolved {outcome.unresolved_count} 项"
                )
            else:
                lines.append(f"自动处理：{outcome.merged_count} 项；待解决：{outcome.unresolved_count} 项")
            lines.append(
                (
                    f"已折叠冗余 {merge_role_label(context, outcome.folded_identity)} 窗格；可随时点“展开三方”。"
                    if outcome.folded_identity else "保持完整三方视图。"
                )
            )
            if outcome.fallback_reasons:
                lines.append("保守回退：" + "；".join(outcome.fallback_reasons[:2]))
            tk.Label(
                body, text="\n".join(lines), justify="left", anchor="w",
                bg=self.workspace_chrome_color, fg="#263238", wraplength=680,
            ).pack(fill="x")
            button_row = tk.Frame(body, bg=self.workspace_chrome_color)
            button_row.pack(fill="x", pady=(14, 0))
            first_navigable_conflict = (
                self._first_unresolved_conflict_cell()
                if outcome.unresolved_count else None
            )
            review_sheet_hint = (
                self._source_delta_review_sheet_from_fallback(outcome)
                if outcome.unresolved_count and first_navigable_conflict is None
                else None
            )

            def _close():
                try:
                    dialog.grab_release()
                except Exception:
                    pass
                dialog.destroy()

            def _primary():
                _close()
                self._activate_startup_outcome_primary_action(
                    outcome,
                    first_conflict=first_navigable_conflict,
                )

            if outcome.unresolved_count:
                primary_text = (
                    "前往第一处未解决冲突"
                    if first_navigable_conflict is not None
                    else (
                        f"检查 {review_sheet_hint} 完整三方"
                        if review_sheet_hint else "检查完整三方"
                    )
                )
            elif outcome.automatic_action == "manual-review":
                primary_text = "检查完整三方"
            else:
                primary_text = "查看并保存 Merged"
            tk.Button(button_row, text="关闭", command=_close, padx=12).pack(side="right")
            primary = tk.Button(button_row, text=primary_text, command=_primary, padx=12)
            primary.pack(side="right", padx=(0, 8))
            dialog.protocol("WM_DELETE_WINDOW", _close)
            dialog.update_idletasks()
            try:
                dialog.grab_set()
            except Exception:
                pass
            primary.focus_set()
        except Exception as exc:
            _dlog(f"startup outcome dialog failed: {exc}")

    def _focus_save_merged_action(self):
        def _focus():
            try:
                view = self.sheet_views.get(getattr(self, "selected_sheet", ""))
                button = getattr(view, "save_a_btn", None) if view is not None else None
                if button is not None:
                    button.focus_set()
                    return
            except Exception:
                pass
            try:
                self.root.focus_set()
            except Exception:
                pass
        self._safe_root_after(0, _focus)

    def _source_delta_review_sheet_from_fallback(
        self,
        outcome: StartupMergeOutcome | None,
    ) -> str | None:
        """Resolve a declined Source OOXML part back to a real review Sheet.

        A package member such as ``xl/worksheets/sheet2.xml`` is review
        evidence, not a cell address.  Source Before owns the authoritative
        sheet-part mapping, so use it only to select a real displayed Sheet and
        never manufacture a row or column coordinate.
        """
        if outcome is None:
            return None
        member = None
        for reason in tuple(getattr(outcome, "fallback_reasons", ()) or ()):
            match = re.search(
                r"Unsupported Source OOXML (?:representation|member) change:\s*([^\s;]+)",
                str(reason or ""),
                re.IGNORECASE,
            )
            if match:
                member = match.group(1).replace("\\", "/").lstrip("/")
                break
        if not member:
            return None
        try:
            context = getattr(self, "launch_context", None)
            source_before = context.identity_for("base") if context else None
            source_path = source_before.effective_path if source_before else None
            fingerprint = _ooxml_package_fingerprint(source_path)
            if not fingerprint.ready:
                return None
            displayed = {
                str(sheet) for sheet in (getattr(self, "display_sheets", ()) or ())
            }
            containers = getattr(self, "_sheet_containers", {}) or {}
            for sheet, part in _ooxml_sheet_part_map(fingerprint.payloads).items():
                normalized_part = str(part or "").replace("\\", "/").lstrip("/")
                if (
                    normalized_part == member
                    and sheet in displayed
                    and sheet in containers
                ):
                    _dlog(
                        f"SOURCE_DELTA_REVIEW_SHEET member={member} sheet={sheet}"
                    )
                    return sheet
        except Exception as exc:
            _dlog(
                f"SOURCE_DELTA_REVIEW_SHEET_SKIPPED member={member} "
                f"err={type(exc).__name__}:{exc}"
            )
        return None

    def _focus_full_three_way_manual_review(
        self,
        outcome: StartupMergeOutcome | None = None,
    ):
        """Return from a global/manual marker to an inspectable full view."""
        review_sheet = self._source_delta_review_sheet_from_fallback(outcome)

        def _expand_when_ready(sheet: str, remaining: int = 30):
            view = getattr(self, "sheet_views", {}).get(sheet)
            if view is None:
                if remaining > 0:
                    self._safe_root_after(
                        50,
                        lambda: _expand_when_ready(sheet, remaining - 1),
                    )
                return
            try:
                if view._is_three_way_enabled() and not view._is_three_way_expanded():
                    if view._derive_lifecycle_state() != "READY":
                        if remaining > 0:
                            self._safe_root_after(
                                50,
                                lambda: _expand_when_ready(sheet, remaining - 1),
                            )
                        return
                    view.three_way_var.set(1)
                    view._toggle_three_way_view()
            except Exception:
                pass
            try:
                self.root.focus_set()
            except Exception:
                pass

        def _focus():
            try:
                selected = review_sheet or str(
                    getattr(self, "selected_sheet", "") or ""
                )
                if review_sheet:
                    container = getattr(self, "_sheet_containers", {}).get(review_sheet)
                    if container is not None:
                        self.nb.select(container)
                    self.selected_sheet = review_sheet
                view = getattr(self, "sheet_views", {}).get(selected)
                if view is None and not review_sheet:
                    for candidate in getattr(self, "sheet_views", {}).values():
                        if candidate is not None:
                            view = candidate
                            break
                if (
                    view is not None
                    and view._is_three_way_enabled()
                    and not view._is_three_way_expanded()
                ):
                    view.three_way_var.set(1)
                    view._toggle_three_way_view()
            except Exception:
                pass
            if selected:
                _expand_when_ready(selected)
            try:
                self._set_task_status(
                    "存在工作簿级未解决项，请检查"
                    f" {selected or '完整三方视图'}。",
                    active=False,
                )
            except Exception:
                pass
            try:
                self.root.focus_set()
            except Exception:
                pass
        self._safe_root_after(0, _focus)

    def _activate_startup_outcome_primary_action(
        self,
        outcome: StartupMergeOutcome,
        *,
        first_conflict: tuple[str, int, int] | None = None,
    ) -> str:
        """Run the outcome dialog's primary action without routing pseudo Sheets."""
        if outcome.unresolved_count:
            first = first_conflict or self._first_unresolved_conflict_cell()
            if first is not None:
                self._navigate_to_conflict_cell(*first)
                return "navigate"
            self._focus_full_three_way_manual_review(outcome)
            return "manual-review"
        if outcome.automatic_action == "manual-review":
            self._focus_full_three_way_manual_review(outcome)
            return "manual-review"
        self._focus_save_merged_action()
        return "save"

    def _show_compare_settings(self):
        messagebox.showinfo("比较设置", "当前比较会优先使用 SVN/右键传入的文件身份与 Sheet 配对；\n如需自定义唯一键或列映射，请在当前 Sheet 的列结构标记处确认。", parent=self.root)

    def _save_as_result(self):
        path = filedialog.asksaveasfilename(
            parent=self.root, title="另存为", defaultextension=".xlsx",
            filetypes=[("Excel 工作簿", "*.xlsx *.xlsm")],
        )
        if not path:
            return
        try:
            self._ensure_edit_loaded()
            if self.merge_mode and self.merged_path:
                source = self.build_manual_merge_output_file()
                shutil.copy2(source, path)
                try: os.remove(source)
                except OSError: pass
            else:
                self._atomic_save(self._wb_b_edit, path)
            messagebox.showinfo("另存为成功", f"已写入：\n{path}", parent=self.root)
        except Exception as exc:
            messagebox.showerror("另存为失败", str(exc), parent=self.root)

    def _save_primary_result(self):
        if self.merge_mode and self.merged_path:
            return self.save_merged_and_exit()
        # A TortoiseSVN two-way invocation is Base(A) -> Mine(B).  A is a
        # temporary read-only projection; the primary output command must
        # always save the real working file, even if a stale callback left an
        # accidental A-side dirty flag behind.
        if self._is_vcs_two_way_mode():
            return self.save_b_inplace()
        if getattr(self, "modified_a", False):
            return self.save_a_inplace()
        return self.save_b_inplace()

    def _schedule_command_bar_layout(self, _event=None):
        """Coalesce command-bar reflow while the main window is resized."""
        top = getattr(self, "_command_bar_top", None)
        if top is None:
            return
        pending = getattr(self, "_command_bar_layout_after_id", None)
        if pending is not None:
            try:
                top.after_cancel(pending)
            except tk.TclError as exc:
                _dlog(f"command bar layout timer cancel skipped: {exc}")
        try:
            self._command_bar_layout_after_id = top.after_idle(
                self._layout_command_bar
            )
        except (tk.TclError, RuntimeError) as exc:
            _dlog(f"command bar layout scheduling skipped: {exc}")
            self._command_bar_layout_after_id = None

    def _layout_command_bar(self):
        """Keep every core command inside the client area at narrow widths.

        The wide layout remains a single compact row.  Below the wide-layout
        threshold the title gets a full row and command groups wrap into a
        second/third row using their measured request widths; this avoids
        placing output actions just beyond the right edge of a 900px window.
        """
        self._command_bar_layout_after_id = None
        top = getattr(self, "_command_bar_top", None)
        heading = getattr(self, "_command_bar_heading", None)
        actions = getattr(self, "_command_bar_actions", None)
        items = tuple(getattr(self, "_command_bar_items", ()) or ())
        if top is None or heading is None or actions is None or not items:
            return
        try:
            top.update_idletasks()
            width = int(top.winfo_width() or self.root.winfo_width() or 0)
        except (tk.TclError, TypeError, ValueError) as exc:
            _dlog(f"command bar width unavailable: {exc}")
            return
        try:
            heading_requested = max(1, int(heading.winfo_reqwidth()))
            actions_requested = max(1, int(actions.winfo_reqwidth()))
        except (tk.TclError, TypeError, ValueError) as exc:
            _dlog(f"command bar request width unavailable: {exc}")
            heading_requested = 360
            actions_requested = 1180
        # Use the single-row arrangement only when the title and all command
        # groups can actually fit together.  A fixed breakpoint alone leaves
        # the output group outside a 1366px client area when the localized
        # title's natural width grows.
        narrow = width < heading_requested + actions_requested + 26
        try:
            for item in items:
                item.grid_remove()
                item.place_forget()
        except tk.TclError as exc:
            _dlog(f"command bar item hide skipped: {exc}")

        # ``actions`` is an explicit overflow container.  Its children use
        # pixel placement below rather than one shared Tk Grid: Grid columns
        # are global to every row, so a wide item in row 1 can silently push a
        # row-2 item beyond the right edge at high DPI.
        try:
            actions.grid_propagate(False)
        except tk.TclError as exc:
            _dlog(f"command bar propagation setup skipped: {exc}")
        secondary_items = tuple(
            getattr(self, "_command_bar_secondary_items", ()) or ()
        )
        try:
            tk_scaling = float(self.root.tk.call("tk", "scaling"))
        except (tk.TclError, TypeError, ValueError) as exc:
            _dlog(f"command bar scaling unavailable: {exc}")
            tk_scaling = 1.0
        layout_items = tuple(
            item for item in items
            if not (
                narrow
                and width < 1080
                and tk_scaling >= 1.9
                and item in secondary_items
            )
        )
        for item in secondary_items:
            if item not in items:
                continue
            try:
                item.grid_remove()
                item.place_forget()
            except tk.TclError as exc:
                _dlog(f"secondary command hide skipped: {exc}")

        if not narrow:
            top.grid_columnconfigure(0, weight=1)
            top.grid_columnconfigure(1, weight=0)
            heading.grid_configure(
                row=0, column=0, columnspan=1, sticky="w", padx=0, pady=0
            )
            actions.grid_configure(
                row=0, column=1, columnspan=1, sticky="e", padx=(18, 0), pady=0
            )
            x = 0
            row_height = 0
            for item in layout_items:
                try:
                    requested = max(1, int(item.winfo_reqwidth()))
                    row_height = max(row_height, int(item.winfo_reqheight()))
                except (tk.TclError, TypeError, ValueError) as exc:
                    _dlog(f"wide command size fallback: {exc}")
                    requested = 120
                    row_height = max(row_height, 32)
                gap = 4 if x else 0
                item.place(x=x + gap, y=0, anchor="nw")
                x += gap + requested
            try:
                actions.configure(width=max(1, x), height=max(1, row_height))
            except tk.TclError as exc:
                _dlog(f"wide command bar size update skipped: {exc}")
            return

        top.grid_columnconfigure(0, weight=1)
        top.grid_columnconfigure(1, weight=0)
        heading.grid_configure(
            row=0, column=0, columnspan=2, sticky="ew", padx=0, pady=(0, 3)
        )
        actions.grid_configure(
            row=1, column=0, columnspan=2, sticky="ew", padx=0, pady=0
        )
        try:
            actions.update_idletasks()
            available = int(actions.winfo_width() or width)
        except (tk.TclError, TypeError, ValueError) as exc:
            _dlog(f"narrow command bar width unavailable: {exc}")
            available = width
        available = max(1, available)
        row = 0
        row_width = 0
        row_height = 0
        column = 0
        row_heights: list[int] = []
        for item in layout_items:
            try:
                requested = max(1, int(item.winfo_reqwidth()))
                requested_height = max(1, int(item.winfo_reqheight()))
            except (tk.TclError, TypeError, ValueError) as exc:
                _dlog(f"narrow command size fallback: {exc}")
                requested = 120
                requested_height = 32
            gap = 4 if column else 0
            if column and row_width + gap + requested > available:
                row_heights.append(row_height)
                row += 1
                row_width = 0
                row_height = 0
                column = 0
                gap = 0
            y = sum(row_heights) + (2 * row)
            item.place(x=row_width + gap, y=y, anchor="nw")
            row_width += gap + requested
            row_height = max(row_height, requested_height)
            column += 1
        row_heights.append(row_height)
        try:
            actions.configure(
                width=available,
                height=max(1, sum(row_heights) + 2 * max(0, len(row_heights) - 1)),
            )
        except tk.TclError as exc:
            _dlog(f"narrow command bar size update skipped: {exc}")

